--
-- Name: activity_body_media(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.activity_body_media(p_body jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct u) filter (where u is not null and u <> ''), '{}')
    from (
      select e #>> '{}' as u
        from jsonb_array_elements(case when jsonb_typeof(p_body) = 'array' then p_body else '[]'::jsonb end) b
        cross join lateral jsonb_array_elements(case when jsonb_typeof(b) = 'object' and jsonb_typeof(b -> 'urls') = 'array' then b -> 'urls' else '[]'::jsonb end) e
       where jsonb_typeof(b) = 'object' and b ->> 'type' = 'images' and jsonb_typeof(e) = 'string'
      union all
      select b ->> 'beforeUrl'
        from jsonb_array_elements(case when jsonb_typeof(p_body) = 'array' then p_body else '[]'::jsonb end) b
       where jsonb_typeof(b) = 'object' and b ->> 'type' = 'before_after' and jsonb_typeof(b -> 'beforeUrl') = 'string'
      union all
      select b ->> 'afterUrl'
        from jsonb_array_elements(case when jsonb_typeof(p_body) = 'array' then p_body else '[]'::jsonb end) b
       where jsonb_typeof(b) = 'object' and b ->> 'type' = 'before_after' and jsonb_typeof(b -> 'afterUrl') = 'string'
    ) s;
$$;


--
-- Name: activity_body_media_keys(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.activity_body_media_keys(p_body jsonb) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct k) filter (where k is not null), '{}')
    from (select private.media_object_key(u) as k from unnest(private.activity_body_media(p_body)) u) s;
$$;


--
-- Name: add_business_days(timestamp with time zone, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.add_business_days(p_from timestamp with time zone, p_days integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v timestamp;
  n integer := 0;
begin
  if p_from is null or p_days is null then return null; end if;
  if p_days < 0 then raise exception 'Business days cannot be negative' using errcode = '22023'; end if;
  v := p_from at time zone 'UTC';
  while n < p_days loop
    v := v + interval '1 day';
    if extract(isodow from v) < 6 then n := n + 1; end if;
  end loop;
  return v at time zone 'UTC';
end $$;


