--
-- Name: block_ends_follows(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.block_ends_follows() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform private.lock_member_pair(new.blocker_id, new.blocked_id);
  delete from public.follows f
   where (f.follower_id = new.blocker_id and f.target_type = 'profile' and f.target_id = new.blocked_id)
      or (f.follower_id = new.blocked_id and f.target_type = 'profile' and f.target_id = new.blocker_id)
      or (f.follower_id = new.blocker_id and f.target_type = 'car'
          and f.target_id in (select c.id from public.cars c where c.owner_id = new.blocked_id))
      or (f.follower_id = new.blocked_id and f.target_type = 'car'
          and f.target_id in (select c.id from public.cars c where c.owner_id = new.blocker_id));
  return new;
end;
$$;


--
-- Name: body_without_urls(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.body_without_urls(p_body jsonb, p_urls text[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case when jsonb_typeof(p_body) <> 'array' or coalesce(cardinality(p_urls), 0) = 0 then p_body else coalesce((
    select jsonb_agg(blk order by ord) from (
      select ord,
             case when jsonb_typeof(b) = 'object' and b ->> 'type' = 'images' and jsonb_typeof(b -> 'urls') = 'array'
                  then jsonb_set(b, '{urls}', coalesce((
                         select jsonb_agg(u order by n) from jsonb_array_elements(b -> 'urls') with ordinality x(u, n)
                          where jsonb_typeof(u) <> 'string' or not ((u #>> '{}') = any (p_urls))), '[]'::jsonb))
                  else b end as blk
        from jsonb_array_elements(p_body) with ordinality t(b, ord)
       where not (jsonb_typeof(b) = 'object' and b ->> 'type' = 'before_after'
                  and ((jsonb_typeof(b -> 'beforeUrl') = 'string' and (b ->> 'beforeUrl') = any (p_urls))
                    or (jsonb_typeof(b -> 'afterUrl') = 'string' and (b ->> 'afterUrl') = any (p_urls))))
    ) s
    where not (jsonb_typeof(blk) = 'object' and blk ->> 'type' = 'images' and jsonb_typeof(blk -> 'urls') = 'array'
               and jsonb_array_length(blk -> 'urls') = 0)
  ), '[]'::jsonb) end;
$$;


--
-- Name: car_media_cap(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.car_media_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cap integer := tg_argv[0]::integer;
begin
  if (select auth.uid()) is null then
    return new;
  end if;
  perform 1 from public.cars c where c.id = new.car_id for update;
  if tg_table_name = 'car_images'
     and (select count(*) from public.car_images i where i.car_id = new.car_id) >= v_cap then
    raise exception 'A gallery can hold up to % photos', v_cap using errcode = '23514';
  end if;
  if tg_table_name = 'car_hotspots'
     and (select count(*) from public.car_hotspots h where h.car_id = new.car_id) >= v_cap then
    raise exception 'showcase hotspot limit reached (%)', v_cap using errcode = '23514';
  end if;
  return new;
end;
$$;


