    raise exception 'A photo or pin stays on the car it was added to.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: car_moderation_hold_apply(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.car_moderation_hold_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Unconditional on purpose: filtering on is_public read the last
  -- committed row and skipped a car whose publish was still in flight,
  -- without waiting for it. Updating every time takes the row lock, so this
  -- waits for that publish to commit and then makes the build private.
  update public.cars set is_public = false where id = new.car_id;
  return new;
end;
$$;


--
-- Name: car_moderation_hold_keeps_private(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.car_moderation_hold_keeps_private() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.is_public and exists (select 1 from public.car_moderation_holds h where h.car_id = new.id) then
    new.is_public := false;
  end if;
  return new;
end;
$$;


--
-- Name: check_member_live_listing_photo(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.check_member_live_listing_photo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_listing uuid;
  v_seller uuid;
  v_status text;
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    return null;
  end if;
  if tg_table_name = 'listings' then
    if tg_op = 'UPDATE' and old.status not in ('draft', 'paused', 'archived') then
      return null;
    end if;
    v_listing := new.id;
  else
    v_listing := old.listing_id;
  end if;

  select l.seller_id, l.status into v_seller, v_status
  from public.listings l
  where l.id = v_listing;
  if not found or v_status is distinct from 'active' or v_seller is distinct from auth.uid() then
    return null;
  end if;
  if not exists (select 1 from public.listing_images i where i.listing_id = v_listing) then
    raise exception 'A live listing needs at least one photo' using errcode = '23514';
  end if;
  return null;
end;
$$;


