--
-- Name: copyright_admin_step_up(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copyright_admin_step_up() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_admin() or public.admin_role() is distinct from 'admin' or not exists (
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb -> 'amr', '[]'::jsonb)) m
    where m ->> 'method' in ('totp', 'mfa/totp')
      and (m ->> 'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then
    raise exception 'Admin step-up required' using errcode = '42501';
  end if;
  return (select auth.uid());
end;
$$;


--
-- Name: copyright_blocked_media_purge(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copyright_blocked_media_purge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_keys text[];
  k text;
  v_write text := current_setting('drvn.activity_write', true);
begin
  select coalesce(array_agg(distinct a.object_key order by a.object_key), '{}') into v_keys from added a;
  -- Waits for any write that is checking these objects right now, in key
  -- order; anything it committed is visible to the statements below, and
  -- anything after sees the rows and is refused.
  foreach k in array v_keys loop
    perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || k, 0));
  end loop;
  delete from public.order_item_snapshot_images where private.media_object_key(url) = any(v_keys);
  delete from public.listing_images where private.media_object_key(url) = any(v_keys);
  delete from public.car_images where private.media_object_key(url) = any(v_keys);
  delete from public.activity_images where private.media_object_key(url) = any(v_keys);
  delete from public.car_hotspots where private.media_object_key(image_url) = any(v_keys);
  update public.mod_items set image_url = null where private.media_object_key(image_url) = any(v_keys);
  update public.cars set cover_image_url = null where private.media_object_key(cover_image_url) = any(v_keys);
  update public.profiles set avatar_url = null where private.media_object_key(avatar_url) = any(v_keys);
  -- The durable-write guard admits this one system edit (an admin's
  -- takedown runs in the admin's session); the setting is put back after.
  perform set_config('drvn.activity_write', 'v1', true);
  update public.activity_posts p
     set body = private.strip_media_from_body(p.body, v_keys)
   where strpos(p.body::text, '/storage/v1/') > 0
     and private.json_media_keys(p.body) && v_keys
     and private.strip_media_from_body(p.body, v_keys) is distinct from p.body;
  perform set_config('drvn.activity_write', coalesce(v_write, ''), true);
  return null;
end;
$$;


--
-- Name: copyright_hold_listing_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copyright_hold_listing_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Taken down and removed: no restore, no re-publish. Said, not silent.
  if old.status = 'removed' and new.status is distinct from 'removed' and private.copyright_listing_held(new.id) then
    raise exception 'This listing was taken down after a copyright notice, so it can''t be restored or put back on sale. The seller was sent the notice; a counter-notice is the way to dispute it.'
      using errcode = '42501';
  end if;
  if new.status = 'active' and old.status is distinct from 'active' and private.copyright_listing_held(new.id) then
    new.status := 'removed';
    new.removed_at := coalesce(new.removed_at, now());
    new.removed_reason := coalesce(new.removed_reason, 'Copyright notice: taken down while a checkout held it');
  end if;
  return new;
end;
$$;


--
-- Name: copyright_listing_held(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copyright_listing_held(p_listing uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.copyright_notices n
     where n.status = 'actioned'
       and ((jsonb_typeof(n.takedown -> 'keptListingStatus') = 'array' and (n.takedown -> 'keptListingStatus') ? p_listing::text)
         or (jsonb_typeof(n.takedown -> 'removedListings') = 'array' and (n.takedown -> 'removedListings') ? p_listing::text))
  );
$$;


--
-- Name: dedupe_relationship_notification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dedupe_relationship_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- 'listing_save' is what notify_on_save sends for a saved part.
  if new.actor_id is null
     or new.kind not in ('follow', 'car_follow', 'reaction', 'save', 'listing_save', 'like') then
    return new;
  end if;
  -- Serialise the same (recipient, actor, kind, target) so two racing
  -- inserts can't both pass the check.
  perform pg_advisory_xact_lock(
    hashtextextended(new.user_id::text || ':' || new.actor_id::text || ':' || new.kind || ':' ||
                     coalesce(new.target_id::text, new.href, ''), 0)
  );
  if exists (
    select 1 from public.notifications n
     where n.user_id = new.user_id
       and n.actor_id = new.actor_id
       and n.kind = new.kind
       and n.target_id is not distinct from new.target_id
       and n.href is not distinct from new.href
       and n.created_at > now() - interval '1 day'
  ) then
    return null; -- already told today: skip the duplicate quietly
  end if;
  return new;
end;
$$;


--
-- Name: dispute_evidence_attach_cap(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dispute_evidence_attach_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count int;
begin
  -- A row whose uploader's account is gone has no one to limit.
  if new.uploader_id is null then
    return new;
  end if;
  -- Held to the end of the attach's transaction: a second attach by the same
  -- party to the same dispute waits here until the first has committed (or
  -- failed), and the count below, a new statement with a new snapshot, then
  -- includes it.
  perform pg_advisory_xact_lock(
    hashtextextended('dispute-evidence-attach:' || new.uploader_id::text || ':' || new.order_id::text, 0)
  );
  select count(*)::int into v_count
    from public.dispute_evidence de
   where de.order_id = new.order_id
     and de.uploader_id = new.uploader_id;
  if v_count >= 8 then
    raise exception 'You''ve attached the maximum of 8 photos.'
      using errcode = 'check_violation',
            detail = format('dispute_evidence: %s already attached by this party to this order', v_count);
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION dispute_evidence_attach_cap(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.dispute_evidence_attach_cap() IS 'OS-W29: at most 8 evidence photos per party per dispute, counted under a per-order-and-uploader lock so concurrent attaches cannot pass it together. Raises 23514.';


--
-- Name: dispute_journal_close_case(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dispute_journal_close_case() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.state in ('won', 'warning_closed', 'lost') and old.state not in ('won', 'warning_closed', 'lost') then
    update public.payment_recoveries
       set status = 'recovered', resolved_at = now(),
           resolution_note = left('Closed automatically: Stripe''s outcome (' || new.state || ') was applied after the review.', 2000)
     where recovery_key = 'stripe:dispute:' || new.dispute_id and status = 'open';
  end if;
  return null;
end;
$$;


--
-- Name: dispute_journal_held_state(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dispute_journal_held_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.state = 'recovery' and old.state is distinct from 'recovery' then
    new.held_from_state := old.state;
    new.held_event_id := null;
    new.held_event_created := null;
    new.retry_until := null;
  end if;
  return new;
end;
$$;


--
-- Name: either_blocked(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.either_blocked(p_a uuid, p_b uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_a is not null and p_b is not null and exists (
    select 1 from public.member_blocks b
     where (b.blocker_id = p_a and b.blocked_id = p_b)
        or (b.blocker_id = p_b and b.blocked_id = p_a)
  );
$$;


--
-- Name: enqueue_deleted_media(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_deleted_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_urls text[];
  v_reason text;
  v_owner uuid;
  v_origin text;
  v_prefix text;
begin
  -- Cleanup authority comes from the deleted row's real owner, never from a
  -- URL: a post's text could name anyone's upload. Only objects in that
  -- owner's own folder, on our own storage origin, are queued; with no
  -- recorded origin nothing is (fail closed, like member writes).
  select value into v_origin from public.job_config where key = 'media_storage_origin';
  if v_origin is null or v_origin !~ '^https?://[^/?#@]+/?$' then return old; end if;
  v_prefix := rtrim(v_origin, '/') || '/storage/v1/';

  if tg_table_name = 'cars' then
    v_reason := 'car_deleted';
    v_owner := old.owner_id;
    select array_agg(u) into v_urls from (
      select old.cover_image_url as u
      union all select url from public.car_images where car_id = old.id
      union all select image_url from public.mod_items where car_id = old.id
      -- A pin's photo can outlive its gallery row (removed from the gallery,
      -- pins left on it); the cascade would drop it unqueued.
      union all select image_url from public.car_hotspots where car_id = old.id
    ) s;
  elsif tg_table_name = 'activity_posts' then
    v_reason := 'post_deleted';
    v_owner := old.author_id;
    -- The post's photos, and every media URL its body names in any shape
    -- or spelling.
    select array_agg(u) into v_urls from (
      select url as u from public.activity_images where post_id = old.id
      union all select unnest(private.json_media_urls(old.body))
    ) s;
  elsif tg_table_name = 'listings' then
    v_reason := 'listing_deleted';
    v_owner := old.seller_id;
    select array_agg(url) into v_urls from public.listing_images where listing_id = old.id;
  end if;
  if v_owner is null then return old; end if;

  insert into public.media_cleanup_queue (bucket, path, owner_id, reason)
  select split_part(k, '/', 1), substr(k, length(split_part(k, '/', 1)) + 2), v_owner, v_reason
    from (
      select distinct private.media_object_key(u) as k
        from unnest(coalesce(v_urls, '{}')) u
       where left(u, length(v_prefix)) = v_prefix
    ) keys
   where k is not null
     and split_part(k, '/', 1) in ('avatars', 'car-images', 'activity-images', 'listing-images')
     and split_part(k, '/', 2) = v_owner::text
  on conflict (bucket, path) do update
    set enqueued_at = now(), attempts = 0, next_attempt_at = now(), last_error = null, reason = excluded.reason,
        generation = gen_random_uuid()
    where media_cleanup_queue.owner_id = excluded.owner_id;
  return old;
end;
$_$;


--
-- Name: foreign_photo_ref_counts(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.foreign_photo_ref_counts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (
    select case when owner_id is null then 'owner_unknown'
                when relation in ('cars', 'mod_items') then relation || '.' || field
                when relation = 'activity_posts' then 'activity_posts.body'
                else relation end as k,
           count(*) as n
      from private.photo_ref_candidates()
     group by 1
  ) x;
$$;


