--
-- Name: guard_listing_archive_offers(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_listing_archive_offers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.status = 'archived' and old.status is distinct from 'archived'
     and exists (select 1 from public.offers o where o.listing_id = old.id and o.status in ('open', 'countered')) then
    raise exception 'This listing has open offers. Withdraw it instead, so the buyers are told.'
      using errcode = 'LW409';
  end if;
  return new;
end;
$$;


--
-- Name: guard_listing_delete_history(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_listing_delete_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return old;
  end if;
  if exists (select 1 from public.offers o where o.listing_id = old.id) then
    raise exception 'This listing has offers. Withdraw it instead, so the buyers keep their history.'
      using errcode = 'LW409';
  end if;
  return old;
end;
$$;


--
-- Name: guard_listing_reservation_payable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_listing_reservation_payable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'reserved'
     and old.status is distinct from 'reserved'
     and not private.seller_can_take_payment(new.seller_id) then
    raise exception 'This seller can''t take payment yet: their payouts aren''t set up'
      using errcode = 'LS001';
  end if;
  return new;
end;
$$;


--
-- Name: guard_member_listing_publish(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_member_listing_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'authenticated'
     or new.seller_id is distinct from auth.uid()
     or new.status is distinct from 'active'
     or (tg_op = 'UPDATE' and old.status not in ('draft', 'paused', 'archived')) then
    return new;
  end if;
  if not private.seller_can_take_payment(new.seller_id) then
    raise exception 'Publishing needs payouts set up first, so a sale has somewhere to send the money'
      using errcode = 'LS001';
  end if;
  return new;
end;
$$;


--
-- Name: guard_member_media_ref(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_member_media_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_new jsonb := to_jsonb(new);
  v_url text := v_new ->> tg_argv[0];
  v_owner uuid;
begin
  if v_url is null then return new; end if;
  if tg_op = 'UPDATE' and v_url is not distinct from (to_jsonb(old) ->> tg_argv[0]) then return new; end if;
  -- 20261110120000: every writer, whatever its role.
  if private.media_url_blocked(v_url) then
    raise exception 'This photo was removed after a copyright notice and can''t be used again' using errcode = '42501';
  end if;
  if coalesce(auth.role(), '') <> 'authenticated' then return new; end if;
  case
    when tg_argv[1] like 'self:%' then v_owner := (v_new ->> substr(tg_argv[1], 6))::uuid;
    when tg_argv[1] = 'car' then select c.owner_id into v_owner from public.cars c where c.id = (v_new ->> 'car_id')::uuid;
    when tg_argv[1] = 'listing' then select l.seller_id into v_owner from public.listings l where l.id = (v_new ->> 'listing_id')::uuid;
    when tg_argv[1] = 'post' then select p.author_id into v_owner from public.activity_posts p where p.id = (v_new ->> 'post_id')::uuid;
    else v_owner := null;
  end case;
  if not private.member_media_ref_ok(v_url, v_owner) then
    raise exception 'Photos must be your own uploads to DRVN' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_member_post_body_media(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_member_post_body_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_url text;
  v_old text[] := '{}';
  v_added text[];
begin
  if tg_op = 'UPDATE' then
    if new.body is not distinct from old.body then return new; end if;
    v_old := private.activity_body_media(old.body);
  end if;
  -- The photos this write adds, in key order (so concurrent writes lock alike).
  select coalesce(array_agg(u order by private.media_object_key(u), u), '{}') into v_added
    from unnest(private.activity_body_media(new.body)) u
   where not (u = any(v_old));
  -- 20261110120000: every writer, whatever its role.
  foreach v_url in array v_added loop
    if private.media_url_blocked(v_url) then
      raise exception 'This photo was removed after a copyright notice and can''t be used again' using errcode = '42501';
    end if;
  end loop;
  if coalesce(auth.role(), '') <> 'authenticated' then return new; end if;
  foreach v_url in array v_added loop
    if not private.member_media_ref_ok(v_url, new.author_id) then
      raise exception 'Photos must be your own uploads to DRVN' using errcode = '42501';
    end if;
  end loop;
  return new;
end;
$$;


--
-- Name: guard_notification_kind(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_notification_kind() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if current_setting('drvn.strict_notification_kinds', true) = 'on' and private.notification_member_text(new.kind) is null then
    raise exception 'Notification kind "%" is not classified: say whose words it carries in private.notification_member_text (N1069, work review #153)', new.kind
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: guard_payout_deadline_dispatch(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_payout_deadline_dispatch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if ((old.shipped_at is null and new.shipped_at is not null)
      or (old.delivered_at is null and new.delivered_at is not null)
      or (new.status in ('shipped', 'delivered', 'completed') and new.status is distinct from old.status)
      or (new.pre_dispute_status in ('shipped', 'delivered', 'completed')
          and new.pre_dispute_status is distinct from old.pre_dispute_status))
     and private.payout_deadline_open_claim(new.id) then
    raise exception 'This order is being cancelled and refunded: payouts weren''t set up within 14 days of the sale'
      using errcode = 'LS002';
  end if;
  return new;
end;
$$;


--
-- Name: guard_photo_owner_folder(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_photo_owner_folder() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row jsonb := to_jsonb(new);
  v_url text := v_row ->> tg_argv[0];
begin
  if v_url is null then return new; end if;
  if not private.photo_in_owner_folder(v_url, private.photo_row_owner(tg_argv[1], v_row)) then
    raise exception 'A photo on %.% must be in its owner''s own folder (N940)', tg_table_name, tg_argv[0]
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_photo_owner_folder_body(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_photo_owner_folder_body() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_url text;
begin
  foreach v_url in array private.activity_body_media(new.body) loop
    if not private.photo_in_owner_folder(v_url, new.author_id) then
      raise exception 'A photo in a post must be in its author''s own folder (N940)' using errcode = '42501';
    end if;
  end loop;
  return new;
end;
$$;


--
-- Name: guard_staged_upload(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_staged_upload() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.owner_id is distinct from old.owner_id or new.bucket is distinct from old.bucket
       or new.path is distinct from old.path or new.url is distinct from old.url then
      raise exception 'A staged upload''s object cannot change' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.bucket not in ('avatars', 'car-images', 'activity-images', 'listing-images', 'dispute-evidence', 'message-photos')
     or not coalesce(private.media_path_ok(new.path), false)
     or split_part(new.path, '/', 1) <> new.owner_id::text
     or private.media_object_key(new.url) is distinct from new.bucket || '/' || new.path then
    raise exception 'A staged upload must name an object in its owner''s own folder' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_username_choice(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_username_choice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.username is null or (tg_op = 'UPDATE' and new.username is not distinct from old.username) then
    return new;
  end if;
  perform pg_advisory_xact_lock(private.username_lock_key(new.username));
  if exists (select 1 from private.reserved_usernames r where r.username = new.username) then
    raise exception 'That username is taken.' using errcode = '23505', hint = 'username_reserved';
  end if;
  if exists (select 1 from private.username_tombstones t where t.username = new.username) then
    raise exception 'That username is taken.' using errcode = '23505', hint = 'username_retired';
  end if;
  return new;
end;
$$;


