--
-- Name: guest_holds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.guest_holds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    device_key text NOT NULL,
    network_key text NOT NULL,
    listing_id uuid NOT NULL,
    buyer_id uuid,
    order_id uuid,
    admitted_until timestamp with time zone DEFAULT (now() + '00:15:00'::interval) NOT NULL,
    released_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    request_key text,
    CONSTRAINT guest_holds_device_key_check CHECK (((char_length(device_key) >= 16) AND (char_length(device_key) <= 128))),
    CONSTRAINT guest_holds_network_key_check CHECK (((char_length(network_key) >= 16) AND (char_length(network_key) <= 128))),
    CONSTRAINT guest_holds_request_key_check CHECK (((request_key IS NULL) OR ((char_length(request_key) >= 16) AND (char_length(request_key) <= 200))))
);


--
-- Name: TABLE guest_holds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.guest_holds IS 'N89: guest checkout holds, capped at 2 live per device and per network and 1 live per listing (guest_hold_admit). Service role only.';


--
-- Name: COLUMN guest_holds.request_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guest_holds.request_key IS 'The checkout request (guest idempotency key) that took this admission. Only that request reuses, binds or releases it (20261108130000).';


--
-- Name: guest_hold_live(public.guest_holds); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guest_hold_live(h public.guest_holds) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select h.released_at is null and (
    (h.order_id is null and h.admitted_until > now())
    or exists (select 1 from public.orders o where o.id = h.order_id and o.status in ('pending', 'requires_action'))
  );
$$;


--
-- Name: guest_holds_settle(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guest_holds_settle(p_request text, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_request is null then
    return;
  end if;
  update public.guest_holds h
     set order_id = (
       select (o ->> 'order_id')::uuid
         from jsonb_array_elements(coalesce(p_result -> 'orders', '[]'::jsonb)) o
        where coalesce(o -> 'listing_ids', '[]'::jsonb) ? h.listing_id::text
        limit 1)
   where h.request_key = p_request
     and h.released_at is null
     and h.order_id is null;
  update public.guest_holds h
     set released_at = now()
   where h.request_key = p_request
     and h.released_at is null
     and h.order_id is null;
end;
$$;


--
-- Name: json_media_keys(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.json_media_keys(p jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select coalesce(array_agg(distinct k) filter (where k is not null), '{}')
    from (
      select private.media_object_key(s #>> '{}') as k
        from jsonb_path_query(coalesce(p, 'null'::jsonb), 'lax $.** ? (@.type() == "string")') s
    ) x;
$_$;


--
-- Name: json_media_urls(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.json_media_urls(p jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select coalesce(array_agg(distinct u) filter (where private.media_object_key(u) is not null), '{}')
    from (
      select s #>> '{}' as u
        from jsonb_path_query(coalesce(p, 'null'::jsonb), 'lax $.** ? (@.type() == "string")') s
    ) x;
$_$;


--
-- Name: limit_first_contact(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.limit_first_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null or new.kind = 'event' or new.order_id is not null or new.offer_id is not null then
    return new;
  end if;
  if exists (
    select 1 from public.conversations c
     where c.participant_a = least(new.sender_id, new.recipient_id)
       and c.participant_b = greatest(new.sender_id, new.recipient_id)
  ) then
    return new;
  end if;
  if not public.consume_rate_limit('db-first-contact:' || v_uid::text, 10, interval '1 day') then
    raise exception 'You''ve messaged a lot of new people today — try again tomorrow.' using errcode = 'RL429';
  end if;
  return new;
end;
$$;


--
-- Name: listing_can_go_live(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.listing_can_go_live(p_listing uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((
    select private.seller_can_take_payment(l.seller_id)
       and not public.is_suspended(l.seller_id)
       and exists (select 1 from public.listing_images i where i.listing_id = l.id)
    from public.listings l where l.id = p_listing
  ), false);
$$;


