-- Name: lock_member_pair(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_member_pair(p_a uuid, p_b uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select pg_advisory_xact_lock(private.member_pair_lock_key(p_a, p_b));
$$;


--
-- Name: FUNCTION lock_member_pair(p_a uuid, p_b uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.lock_member_pair(p_a uuid, p_b uuid) IS 'OS-W32: serialises a block with contact writes between the same two members (held to commit).';


--
-- Name: media_object_key(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.media_object_key(p_ref text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_m text[];
  v_raw text;
  v_path text;
  v_out bytea := ''::bytea;
  v_i int := 1;
  v_c text;
begin
  if p_ref is null or length(p_ref) > 2000 then return null; end if;
  v_m := regexp_match(
    p_ref,
    '^[A-Za-z][A-Za-z0-9+.-]*://[^/?#]+/storage/v1/(?:object|render/image)/(?:public|sign|authenticated)/([a-z0-9_-]{1,63})/([^?#]+)'
  );
  if v_m is null then return null; end if;
  v_raw := v_m[2];
  if strpos(v_raw, '%') = 0 then
    v_path := v_raw;
  else
    begin
      while v_i <= length(v_raw) loop
        v_c := substr(v_raw, v_i, 1);
        if v_c = '%' then
          if substr(v_raw, v_i + 1, 2) !~ '^[0-9A-Fa-f]{2}$' then return null; end if;
          v_out := v_out || decode(substr(v_raw, v_i + 1, 2), 'hex');
          v_i := v_i + 3;
        else
          v_out := v_out || convert_to(v_c, 'UTF8');
          v_i := v_i + 1;
        end if;
      end loop;
      v_path := convert_from(v_out, 'UTF8');
    exception when others then
      return null;
    end;
  end if;
  if not (length(v_path) between 3 and 512
          and position('/' in v_path) > 1
          and v_path !~ '/$' and v_path !~ '//'
          and v_path !~ '(^|/)\.{1,2}(/|$)'
          and v_path !~ '[[:cntrl:]\\?#%]') then
    return null;
  end if;
  return v_m[1] || '/' || v_path;
end;
$_$;


--
-- Name: FUNCTION media_object_key(p_ref text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.media_object_key(p_ref text) IS 'Canonical storage identity ''<bucket>/<decoded path>'' of a storage URL, or null. Mirrors canonicalStorageObject in src/lib/media-url.ts.';


--
-- Name: media_path_ok(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.media_path_ok(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select p is not null
    and length(p) between 3 and 512
    and position('/' in p) > 1
    and p !~ '^/' and p !~ '/$' and p !~ '//'
    and p !~ '(^|/)\.{1,2}(/|$)'
    and p !~ '[[:cntrl:]\\?#%]';
$_$;


--
-- Name: media_url_blocked(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.media_url_blocked(p_url text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  k text := private.media_object_key(p_url);
begin
  if k is null then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || k, 0));
  return exists (select 1 from public.copyright_blocked_media b where b.object_key = k);
end;
$$;


--
-- Name: member_media_ref_ok(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_media_ref_ok(p_url text, p_owner uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  k text;
  v_origin text;
  v_prefix text;
begin
  if p_url is null then return true; end if;
  if p_owner is null or length(p_url) > 2000 or p_url ~ '[?#%@\\[:space:][:cntrl:]]' then return false; end if;
  if p_url !~ '^https?://[^/]+/storage/v1/object/public/' then return false; end if;
  k := private.media_object_key(p_url);
  if k is null
     or split_part(k, '/', 1) not in ('avatars', 'car-images', 'activity-images', 'listing-images')
     or split_part(k, '/', 2) <> p_owner::text then
    return false;
  end if;
  -- Fail closed: until the deployment records its storage origin (see
  -- docs/production-runbook.md), no new member photo reference is accepted —
  -- otherwise one saved on another host before then would never be
  -- revalidated.
  select value into v_origin from public.job_config where key = 'media_storage_origin';
  if v_origin is null or v_origin !~ '^https?://[^/?#@]+/?$' then return false; end if;
  v_prefix := rtrim(v_origin, '/') || '/storage/v1/object/public/';
  if left(p_url, length(v_prefix)) <> v_prefix then return false; end if;
  -- 20261110120000: taken down means never attached again.
  if private.media_url_blocked(p_url) then return false; end if;
  return true;
end;
$_$;


--
-- Name: member_pair_lock_key(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_pair_lock_key(p_a uuid, p_b uuid) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select hashtextextended('member-pair:' || least(p_a, p_b)::text || ':' || greatest(p_a, p_b)::text, 0);
$$;


--
-- Name: member_write_quota(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_write_quota() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_action text := tg_argv[0];
  v_limit int := tg_argv[1]::int;
  v_window interval := tg_argv[2]::interval;
begin
  -- Only a member's own token is limited here; trusted server paths
  -- (service role, workers, migrations) carry no auth.uid().
  if v_uid is null then
    return new;
  end if;
  if not public.consume_rate_limit('db-' || v_action || ':' || v_uid::text, v_limit, v_window) then
    raise exception 'That''s a lot at once — try again in a few minutes.'
      using errcode = 'RL429',
            detail = format('%s: %s per %s', v_action, v_limit, v_window);
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION member_write_quota(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.member_write_quota() IS 'N247: per-member insert quota (trigger args: action, limit, window). Mirrors src/lib/rate-limit.ts; raises RL429.';


--
-- Name: mod_sheet_lock(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mod_sheet_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform 1 from public.cars c where c.id = old.car_id for no key update;
    return old;
  end if;
  if tg_op = 'UPDATE' and new.car_id is distinct from old.car_id then
    -- A line moved between two sheets: both, in a fixed order.
    perform 1 from public.cars c where c.id in (old.car_id, new.car_id) order by c.id for no key update;
  else
    perform 1 from public.cars c where c.id = new.car_id for no key update;
  end if;
  if tg_op = 'UPDATE' then
    new.updated_at := greatest(clock_timestamp(), old.updated_at + interval '1 microsecond');
  end if;
  return new;
end;
$$;


--
-- Name: normalized_sql(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalized_sql(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select regexp_replace(btrim(p), '\s+', ' ', 'g') $$;


--
-- Name: not_received_refund_due(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.not_received_refund_due(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
      from public.orders o
     where o.id = p_order
       and o.status = 'disputed'
       and o.dispute_category = 'item_not_received'
       and o.dispute_escalated_at is not null
       and now() >= coalesce(o.dispute_respond_by, private.add_business_days(o.disputed_at, 3))
       and o.refunded_cents < o.total_cents
       and not private.order_has_unresolved_chargeback(o.id)
       and not exists (
         select 1 from public.returns r
          where r.order_id = o.id
            and r.status in ('requested', 'approved', 'awaiting_shipment', 'in_transit', 'delivered', 'received', 'escalated')
       )
       and not private.order_has_valid_tracking(o.id)
  );
$$;


--
-- Name: note_held_dispute_event(text, text, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.note_held_dispute_event(p_dispute text, p_event text, p_created bigint) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update public.stripe_dispute_journal
     set held_event_id = p_event, held_event_created = p_created
   where dispute_id = p_dispute and state = 'recovery' and p_event is not null
     and (held_event_created is null or p_created >= held_event_created);
$$;


--
-- Name: notification_member_text(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notification_member_text(p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when p_kind in ('follow', 'car_follow', 'save', 'listing_save', 'comment', 'reaction', 'review', 'question', 'message') then 'actor'
    when p_kind in ('offer_new', 'offer_countered', 'offer_declined', 'offer_accepted', 'offer_counter_accepted', 'offer_withdrawn',
                    'offer_countered_back', 'offer_expired', 'offer_agent_recommends_accept', 'offer_agent_deal_reached',
                    'offer_agent_out_of_rounds', 'offer_listing_withdrawn') then 'listing_title'
    when p_kind in ('order_disputed', 'order_cancelled', 'order_refunded') then 'order_reason'
    when p_kind = 'saved_search' then 'matched_titles'
    when p_kind in ('order_sold', 'order_paid', 'order_shipped', 'order_delivered', 'order_completed', 'order_pending',
                    'order_requires_action', 'order_payment_failed',
                    'receipt_due', 'receipt_auto_confirmed', 'dispute_resolved', 'dispute_escalated',
                    'refund_offered', 'refund_offer_expired', 'payout_sent', 'payout_blocked',
                    'report_reviewed', 'post_removed', 'comment_removed', 'listing_removed', 'car_hidden', 'car_restored',
                    'account_suspended', 'account_restored', 'password_changed', 'copyright_takedown', 'policy_updated',
                    'admin_action',
                    'payout_setup_reminder', 'order_partially_refunded', 'dispatch_reminder') then 'none'
  end;
$$;


--
-- Name: notify_on_partial_refund(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notify_on_partial_refund() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_amount text;
begin
  if new.refunded_cents <= old.refunded_cents or new.refunded_cents >= new.total_cents
     or new.status in ('refunded', 'cancelled')
     or coalesce(new.cancel_reason, '') like 'Card dispute lost (%' then
    return new;
  end if;
  v_amount := to_char((new.refunded_cents - old.refunded_cents) / 100.0, 'FM999G999G990D00') || ' ' || upper(new.currency);
  perform public.notify(new.buyer_id, 'order_partially_refunded', 'marketplace',
    'Part of your order was refunded', v_amount || ' was refunded to the card you paid with.', '/orders/' || new.id, null);
  perform public.notify(new.seller_id, 'order_partially_refunded', 'marketplace',
    'A partial refund was issued on a sale', v_amount || ' was refunded to the buyer.', '/orders/' || new.id, null);
  return new;
end;
$$;


--
-- Name: order_deadlines(uuid, boolean, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.order_deadlines(p_seller uuid, p_is_collection boolean, p_ship_country text, p_shipping_quote jsonb, p_paid_at timestamp with time zone, OUT dispatch_by timestamp with time zone, OUT deliver_by timestamp with time zone, OUT available_by timestamp with time zone, OUT estimate_source text) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_handling integer;
  v_seller_country text;
  v_transit integer;
begin
  select p.default_handling_days, p.country into v_handling, v_seller_country
    from public.seller_fulfillment_profiles p
   where p.seller_id = p_seller;
  v_handling := least(greatest(coalesce(v_handling, 3), 1), 10);

  if coalesce(p_is_collection, false) then
    available_by := private.add_business_days(p_paid_at, v_handling);
    estimate_source := 'collection';
    return;
  end if;

  select max(ceil((e ->> 'est_delivery_days')::numeric))::integer into v_transit
    from jsonb_array_elements(
           case when jsonb_typeof(p_shipping_quote) = 'array' then p_shipping_quote else '[]'::jsonb end
         ) e
   where jsonb_typeof(e -> 'est_delivery_days') = 'number'
     and (e ->> 'est_delivery_days')::numeric > 0;

  if v_transit is not null then
    estimate_source := 'quote';
    v_transit := least(v_transit, 30);
  else
    estimate_source := 'fallback';
    v_transit := case
      when p_ship_country is not null and v_seller_country is not null
           and upper(btrim(p_ship_country)) <> upper(btrim(v_seller_country)) then 15
      else 5
    end;
  end if;

  dispatch_by := private.add_business_days(p_paid_at, v_handling);
  deliver_by := private.add_business_days(dispatch_by, v_transit);
end $$;


--
-- Name: order_emails_account_closed(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.order_emails_account_closed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- A held deletion (temporary_financial_hold) leaves the member settling
  -- orders with their account: they still need these emails.
  if new.user_id is not null and (new.outcome <> 'temporary_financial_hold' or new.scrubbed_at is not null) then
    update public.order_email_outbox
       set status = 'skipped', skip_reason = 'account_closed', lease_id = null, lease_expires_at = null, updated_at = now()
     where recipient_id = new.user_id and status in ('pending', 'sending');
  end if;
  return new;
end;
$$;


--
-- Name: order_has_unresolved_chargeback(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.order_has_unresolved_chargeback(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.stripe_dispute_journal j
    where j.order_ids @> array[p_order]
      and j.state not in ('won', 'warning_closed', 'lost')
  );
$$;


--
-- Name: order_has_valid_tracking(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.order_has_valid_tracking(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.orders o
     where o.id = p_order
       and case
         when o.is_collection then o.pickup_ready_at is not null
         else exists (
           select 1
             from public.delivery_proofs p
             join public.shipments s on s.id = p.shipment_id
            where p.order_id = o.id
              and s.status not in ('cancelled', 'failed')
              and p.verdict in ('verified', 'review')
         )
         -- A carrier delivery whose proof isn't on record yet (still being
         -- evaluated, or a recording retry) protects the seller too.
         or exists (
           select 1 from public.shipments s
            where s.order_id = o.id and s.direction = 'outbound' and s.status = 'delivered'
              and not exists (select 1 from public.delivery_proofs p where p.shipment_id = s.id)
         )
       end
  );
$$;


--
-- Name: payout_deadline_open_claim(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.payout_deadline_open_claim(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from private.payout_deadline_cancellations c
                 where c.order_id = p_order and c.settled_at is null);
$$;


--
-- Name: payout_readiness_required(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.payout_readiness_required() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select c.value from public.job_config c where c.key = 'payments_mode'), 'stripe') <> 'stub';
$$;


--
-- Name: photo_in_owner_folder(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_in_owner_folder(p_url text, p_owner uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when p_url is null then true
    when private.media_object_key(p_url) is null then true
    when split_part(private.media_object_key(p_url), '/', 1) not in ('car-images', 'listing-images', 'activity-images') then true
    else p_owner is not null and split_part(private.media_object_key(p_url), '/', 2) = p_owner::text
  end;
$$;


--
-- Name: photo_names_member_object(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_names_member_object(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce(split_part(private.media_object_key(p_url), '/', 1) in ('car-images', 'listing-images', 'activity-images'), false);
$$;


--
-- Name: photo_ref_candidates(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_ref_candidates() RETURNS TABLE(relation text, field text, row_id uuid, value text, owner_id uuid, row_data jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'car_images', 'url', ci.id, ci.url, c.owner_id, to_jsonb(ci)
    from public.car_images ci left join public.cars c on c.id = ci.car_id
   where private.photo_names_member_object(ci.url) and (c.owner_id is null or not private.photo_in_owner_folder(ci.url, c.owner_id))
  union all
  select 'car_hotspots', 'image_url', h.id, h.image_url, c.owner_id, to_jsonb(h)
    from public.car_hotspots h left join public.cars c on c.id = h.car_id
   where private.photo_names_member_object(h.image_url) and (c.owner_id is null or not private.photo_in_owner_folder(h.image_url, c.owner_id))
  union all
  select 'listing_images', 'url', li.id, li.url, l.seller_id, to_jsonb(li)
    from public.listing_images li left join public.listings l on l.id = li.listing_id
   where private.photo_names_member_object(li.url) and (l.seller_id is null or not private.photo_in_owner_folder(li.url, l.seller_id))
  union all
  select 'activity_images', 'url', ai.id, ai.url, p.author_id, to_jsonb(ai)
    from public.activity_images ai left join public.activity_posts p on p.id = ai.post_id
   where private.photo_names_member_object(ai.url) and (p.author_id is null or not private.photo_in_owner_folder(ai.url, p.author_id))
  union all
  select 'activity_posts', 'body', p.id, u.url, p.author_id, to_jsonb(p)
    from public.activity_posts p cross join lateral unnest(private.activity_body_media(p.body)) u(url)
   where strpos(p.body::text, '/storage/v1/') > 0
     and private.photo_names_member_object(u.url) and (p.author_id is null or not private.photo_in_owner_folder(u.url, p.author_id))
  union all
  select 'order_item_snapshot_images', 'url', s.id, s.url, o.seller_id, to_jsonb(s)
    from public.order_item_snapshot_images s
    left join public.order_items oi on oi.id = s.order_item_id
    left join public.orders o on o.id = oi.order_id
   where private.photo_names_member_object(s.url) and (o.seller_id is null or not private.photo_in_owner_folder(s.url, o.seller_id))
  union all
  select 'cars', 'cover_image_url', c.id, c.cover_image_url, c.owner_id, to_jsonb(c)
    from public.cars c
   where private.photo_names_member_object(c.cover_image_url) and (c.owner_id is null or not private.photo_in_owner_folder(c.cover_image_url, c.owner_id))
  union all
  select 'mod_items', 'image_url', m.id, m.image_url, c.owner_id, to_jsonb(m)
    from public.mod_items m left join public.cars c on c.id = m.car_id
   where private.photo_names_member_object(m.image_url) and (c.owner_id is null or not private.photo_in_owner_folder(m.image_url, c.owner_id));
$$;


--
-- Name: photo_refs_quarantined_forget_member(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_refs_quarantined_forget_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.user_id is not null and new.scrubbed_at is not null and old.scrubbed_at is null then
    delete from private.photo_refs_quarantined
     where owner_id = new.user_id or folder_owner = new.user_id::text;
  end if;
  return new;
end;
$$;


--
-- Name: photo_row_owner(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_row_owner(p_kind text, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_owner uuid;
begin
  if p_kind like 'self:%' then
    return (p_row ->> substr(p_kind, 6))::uuid;
  elsif p_kind = 'car' then
    select c.owner_id into v_owner from public.cars c where c.id = (p_row ->> 'car_id')::uuid;
  elsif p_kind = 'listing' then
    select l.seller_id into v_owner from public.listings l where l.id = (p_row ->> 'listing_id')::uuid;
  elsif p_kind = 'post' then
    select p.author_id into v_owner from public.activity_posts p where p.id = (p_row ->> 'post_id')::uuid;
  elsif p_kind = 'order_item' then
    select o.seller_id into v_owner
      from public.order_items oi join public.orders o on o.id = oi.order_id
     where oi.id = (p_row ->> 'order_item_id')::uuid;
  else
    raise exception 'Unknown photo owner kind % (N940)', p_kind;
  end if;
  return v_owner;
end;
$$;


--
-- Name: photo_scrub_bucket(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_scrub_bucket(p_bucket text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select p_bucket in ('message-photos', 'agent-chat-photos');
$$;


--
-- Name: photo_signable_positions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_signable_positions() RETURNS TABLE(kind text, relation text, field text, source text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  values
    ('column', 'cars', 'cover_image_url', null::text),
    ('column', 'car_images', 'url', null::text),
    ('column', 'car_hotspots', 'image_url', null::text),
    ('column', 'mod_items', 'image_url', null::text),
    ('column', 'listing_images', 'url', null::text),
    ('column', 'activity_images', 'url', null::text),
    ('column', 'order_item_snapshot_images', 'url', null::text),
    ('body', 'activity_posts', 'body', null::text),
    ('rpc', 'feed_hydration', 'posts.cover_url', 'activity_images.url'),
    ('rpc', 'feed_hydration', 'posts.body', 'activity_posts.body'),
    ('rpc', 'feed_hydration', 'cars.cover_image_url', 'cars.cover_image_url'),
    ('rpc', 'feed_hydration', 'listings.cover_url', 'listing_images.url'),
    ('rpc', 'feed_hydration', 'post_cars.cover_image_url', 'cars.cover_image_url'),
    ('rpc', 'garage_car_stats', 'latest_update.cover_url', 'activity_images.url'),
    ('rpc', 'garage_car_stats', 'latest_update.body', 'activity_posts.body'),
    ('rpc', 'seller_listing_stats', 'cover_url', 'listing_images.url'),
    ('rpc', 'car_update_page', 'body', 'activity_posts.body')
$$;


--
-- Name: photo_signatures_forget_member(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_signatures_forget_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.user_id is not null and new.scrubbed_at is not null and old.scrubbed_at is null then
    -- Locked in key order, the order offers take, so this can never
    -- deadlock with one and abort the scrub.
    delete from private.photo_signatures d
     where d.ctid in (select x.ctid from private.photo_signatures x
                       where split_part(x.path, '/', 1) = new.user_id::text
                       order by x.bucket, x.path, x.signing_window
                       for update);
  end if;
  return new;
end;
$$;


--
-- Name: postcode_key(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.postcode_key(p_code text, p_country text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select case
    when k = '' then null
    when k ~ '^[0-9]{9}$' and (p_country is null or upper(btrim(p_country)) in ('US', 'USA')) then left(k, 5)
    else k
  end
  from (select upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')) as k) s;
$_$;


--
-- Name: prune_cron_history(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prune_cron_history() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  removed integer;
begin
  delete from cron.job_run_details where coalesce(end_time, start_time) < now() - interval '14 days';
  get diagnostics removed = row_count;
  -- Rows an offer is writing right now are skipped, not waited for.
  delete from private.photo_signatures d
   where d.ctid in (select x.ctid from private.photo_signatures x
                     where x.created_at < now() - interval '2 hours'
                     for update skip locked);
  -- 20261110190000: quarantined photo references past their 90 days.
  delete from private.photo_refs_quarantined where expires_at < now();
  -- 20261111090000: settled order emails and reminder ledgers past 90 days.
  delete from public.order_email_outbox where status in ('sent', 'skipped', 'failed') and updated_at < now() - interval '90 days';
  delete from public.payout_setup_reminders where created_at < now() - interval '90 days';
  delete from public.dispatch_reminders where created_at < now() - interval '90 days';
  return removed;
end;
$$;


--
-- Name: quarantine_foreign_photo_refs(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.quarantine_foreign_photo_refs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n integer;
  v_write text := current_setting('drvn.activity_write', true);
begin
  create temp table photo_ref_moving on commit drop as
    select * from private.photo_ref_candidates() where owner_id is not null;
  insert into private.photo_refs_quarantined (relation, field, value, row_data, action, owner_id, folder_owner)
  select m.relation, m.field, m.value, m.row_data,
         case when m.relation in ('cars', 'mod_items') then 'cleared' when m.relation = 'activity_posts' then 'stripped' else 'deleted' end,
         m.owner_id, split_part(private.media_object_key(m.value), '/', 2)
    from photo_ref_moving m;
  get diagnostics n = row_count;

  delete from public.car_images where id in (select row_id from photo_ref_moving where relation = 'car_images');
  delete from public.car_hotspots where id in (select row_id from photo_ref_moving where relation = 'car_hotspots');
  delete from public.listing_images where id in (select row_id from photo_ref_moving where relation = 'listing_images');
  delete from public.order_item_snapshot_images where id in (select row_id from photo_ref_moving where relation = 'order_item_snapshot_images');
  update public.cars set cover_image_url = null where id in (select row_id from photo_ref_moving where relation = 'cars');
  update public.mod_items set image_url = null where id in (select row_id from photo_ref_moving where relation = 'mod_items');
  perform set_config('drvn.activity_write', 'v1', true);
  delete from public.activity_images where id in (select row_id from photo_ref_moving where relation = 'activity_images');
  update public.activity_posts p
     set body = private.body_without_urls(p.body, x.urls)
    from (select row_id, array_agg(value) as urls from photo_ref_moving where relation = 'activity_posts' group by row_id) x
   where p.id = x.row_id;
  perform set_config('drvn.activity_write', coalesce(v_write, ''), true);
  drop table photo_ref_moving;
  return n;
end;
$$;


--
-- Name: queue_order_email(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_order_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_order uuid;
begin
  if new.kind not in ('order_sold', 'order_paid', 'order_shipped', 'order_delivered', 'receipt_auto_confirmed',
                      'order_disputed', 'dispute_resolved', 'admin_action', 'order_refunded', 'payout_setup_reminder',
                      'order_cancelled', 'order_partially_refunded', 'dispatch_reminder') then
    return new;
  end if;
  -- Exactly /orders/<uuid>: anything else (a fragment, a query, another
  -- path) queues nothing.
  if new.href is null or new.href !~ '^/orders/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return new;
  end if;
  v_order := substr(new.href, 9)::uuid;
  -- The notice's own recipient, and only when they are a party to the order:
  -- a notice can never widen who is emailed.
  if not exists (select 1 from public.orders o where o.id = v_order and new.user_id in (o.buyer_id, o.seller_id)) then
    return new;
  end if;
  insert into public.order_email_outbox (notification_id, recipient_id, order_id, kind)
  values (new.id, new.user_id, v_order, new.kind)
  on conflict (notification_id) do nothing;
  return new;
end;
$_$;


--
-- Name: record_account_deletion_late_hold(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_account_deletion_late_hold(p_user uuid, p_order uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.account_deletion_requests
     set outcome = 'operator_attention', blocker_code = 'late_hold_after_scrub',
         affected_data_classes = array['orders', 'returns', 'refunds', 'payouts', 'chargebacks'],
         hold_order_id = p_order,
         next_action = private.account_deletion_late_hold_note(p_order),
         responsible_owner = 'operations', completed_at = null, updated_at = now()
   where user_id = p_user and scrubbed_at is not null and outcome <> 'completed';
end $$;


--
-- Name: record_unproven_buyer_order(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_unproven_buyer_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.buyer_id is not null and not exists (
    select 1 from auth.users u where u.id = new.buyer_id and u.confirmed_at is not null
  ) then
    insert into private.unproven_buyer_orders (order_id, buyer_id)
    values (new.id, new.buyer_id)
    on conflict (order_id) do nothing;
  end if;
  return null;
end;
$$;


--
-- Name: refuse_blocked_contact(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refuse_blocked_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_other uuid;
  v_seller uuid;
begin
  case tg_table_name
    when 'messages' then
      -- Lifecycle events are DRVN's, not the member's. Only a trusted
      -- writer can get here with one: messages_00_member_events refuses a
      -- member's.
      if new.kind = 'event' then return new; end if;
      v_actor := new.sender_id;
      v_other := new.recipient_id;
      -- The order exception: only communication attached to an order the
      -- two of them share, so an open order can still be finished.
      if new.order_id is not null and exists (
        select 1 from public.orders o
         where o.id = new.order_id
           and ((o.buyer_id = v_actor and o.seller_id = v_other) or (o.seller_id = v_actor and o.buyer_id = v_other))
      ) then
        return new;
      end if;
    when 'offers' then
      select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;
      v_actor := new.buyer_id;
      v_other := v_seller;
    when 'offer_rounds' then
      -- Moves that end a negotiation only reduce contact, so a block never
      -- stops them: DRVN's own moves (a lapsed offer expiring, rival offers
      -- expiring when the part sells — purchase_finalize, after the payment
      -- succeeded — a withdrawal DRVN makes), any expiry, a decline by
      -- either party, and the offer's maker withdrawing it. Refusing them
      -- would roll back the work they're part of, or leave the blocked
      -- offer stuck open. New proposals and agreement — an offer, a
      -- counter, an accept, a below-minimum attempt — by a member or the
      -- agent are still refused.
      if new.actor_role = 'system'
         or new.kind in ('expire', 'decline')
         or (new.kind = 'withdraw' and new.actor_role = 'buyer') then
        return new;
      end if;
      select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;
      v_actor := new.buyer_id;
      v_other := v_seller;
    when 'listing_questions' then
      select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;
      v_actor := new.author_id;
      if v_actor = v_seller and new.parent_id is not null then
        select q.author_id into v_other from public.listing_questions q where q.id = new.parent_id;
      else
        v_other := v_seller;
      end if;
    when 'activity_comments' then
      v_actor := new.author_id;
      select p.author_id into v_other from public.activity_posts p where p.id = new.post_id;
    when 'follows' then
      v_actor := new.follower_id;
      if new.target_type = 'profile' then
        v_other := new.target_id;
      else
        select c.owner_id into v_other from public.cars c where c.id = new.target_id;
      end if;
    else
      return new;
  end case;
  if v_actor is null or v_other is null or v_actor = v_other then
    return new;
  end if;
  -- Serialise with a concurrent block between the two, then check: this
  -- statement runs after the lock, so it sees a block that committed while
  -- this write waited.
  perform private.lock_member_pair(v_actor, v_other);
  if private.either_blocked(v_actor, v_other) then
    raise exception 'You can''t contact this member.' using errcode = 'BL403';
  end if;
  return new;
end;
$$;


--
-- Name: refuse_claimed_media(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refuse_claimed_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_old text[] := '{}';
  k text;
begin
  if tg_op = 'UPDATE' then
    v_old := private.row_media_keys(to_jsonb(old), tg_argv[0], tg_argv[1]);
  end if;
  -- Sorted, so two writers lock in the same order.
  foreach k in array private.row_media_keys(to_jsonb(new), tg_argv[0], tg_argv[1]) loop
    continue when k = any(v_old);
    perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || k, 0));
    if exists (select 1 from private.media_deletion_claims c
                where c.bucket = split_part(k, '/', 1) and c.path = substr(k, length(split_part(k, '/', 1)) + 2)) then
      raise exception 'That photo has been removed from storage. Upload it again.' using errcode = '55000';
    end if;
  end loop;
  return new;
end;
$$;


--
-- Name: refuse_member_events(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refuse_member_events() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind is distinct from 'message' and not public.is_trusted_writer() then
    raise exception 'Only DRVN writes lifecycle events.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: refuse_review_of_unproven_buyer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refuse_review_of_unproven_buyer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (
    select 1 from private.unproven_buyer_orders p
    where p.order_id = new.order_id and p.buyer_id = new.reviewee_id
  ) then
    raise exception 'This buyer checked out as a guest, so they can''t be reviewed on this order'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: repair_scrubbed_previews(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.repair_scrubbed_previews(p_batch integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_counts jsonb;
  v_actor integer := 0;
  v_offers integer := 0;
  v_orders integer := 0;
  v_links integer := 0;
  v_matched integer := 0;
  v_digests integer := 0;
  n integer;
  r record;
begin
  -- 1. Every already-scrubbed member, through the same rules as the scrub.
  --    Each member's notices are found through indexed keys (actor, the
  --    recipient of an offer or order of theirs), one member at a time.
  for r in
    select d.user_id from public.account_deletion_requests d
     where d.scrubbed_at is not null and d.user_id is not null
  loop
    v_counts := private.scrub_member_notices(r.user_id, null) || private.scrub_member_digest_items(r.user_id);
    v_actor := v_actor + (v_counts->>'notifications_sent')::integer;
    v_offers := v_offers + (v_counts->>'offer_notice_bodies')::integer;
    v_orders := v_orders + (v_counts->>'order_notice_bodies')::integer;
    v_matched := v_matched + (v_counts->>'saved_search_notices')::integer;
    v_digests := v_digests + (v_counts->>'digests_trimmed')::integer + (v_counts->>'digests_not_sent')::integer + (v_counts->>'digest_titles_removed')::integer;
  end loop;
  -- With no scrubbed member at all, a digest can still name a listing that is gone.
  v_counts := private.scrub_member_digest_items(null);
  v_digests := v_digests + (v_counts->>'digests_trimmed')::integer + (v_counts->>'digests_not_sent')::integer + (v_counts->>'digest_titles_removed')::integer;

  -- 2. Links to a retired handle lead nowhere and name the member who left.
  --    A scan of notifications, so in batches; one batch is enough today.
  loop
    update public.notifications nt
       set href = null
     where nt.id in (
       select x.id from public.notifications x
        where x.href ~ '^/u/[a-z0-9_]{3,30}$'
          and exists (select 1 from private.username_tombstones t where '/u/' || t.username = x.href)
        limit greatest(coalesce(p_batch, 5000), 1));
    get diagnostics n = row_count;
    v_links := v_links + n;
    exit when n = 0;
  end loop;

  return jsonb_build_object('actor_rows', v_actor, 'offer_bodies', v_offers, 'order_bodies', v_orders, 'retired_links', v_links,
    'saved_search_notices', v_matched, 'saved_search_digests', v_digests);
end $_$;


--
-- Name: requeue_account_deletion_for_hold(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.requeue_account_deletion_for_hold(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order uuid;
begin
  if not exists (
    select 1 from public.remediation_jobs
     where dedup_key = 'delete:' || p_user::text and kind = 'delete_account'
       and status not in ('pending', 'processing')
  ) then
    return;
  end if;
  if not exists (select 1 from public.account_deletion_requests where user_id = p_user and outcome <> 'completed') then
    return;
  end if;
  if not coalesce((public.account_deletion_blockers(p_user)->>'financial_hold')::boolean, false) then
    return;
  end if;

  v_order := private.account_deletion_hold_order(p_user);
  if exists (select 1 from public.account_deletion_requests where user_id = p_user and scrubbed_at is not null) then
    perform private.record_account_deletion_late_hold(p_user, v_order);
    return;
  end if;
  update public.remediation_jobs
     set status = 'pending', next_attempt_at = now(), locked_until = null, lease_id = null,
         attempts = 0, last_error = null, completed_at = null
   where dedup_key = 'delete:' || p_user::text and kind = 'delete_account'
     and status not in ('pending', 'processing');
  update public.account_deletion_requests
     set outcome = 'temporary_financial_hold', blocker_code = private.account_deletion_hold_code(v_order),
         affected_data_classes = array['orders', 'returns', 'refunds', 'payouts', 'chargebacks'],
         hold_order_id = v_order,
         next_action = private.account_deletion_hold_note(v_order),
         responsible_owner = 'account owner', completed_at = null, updated_at = now()
   where user_id = p_user and outcome <> 'completed';
end $$;


--
-- Name: requeue_unscrubbed_retained_deletions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.requeue_unscrubbed_retained_deletions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_case record;
  v_job uuid;
  v_count integer := 0;
begin
  for v_case in
    select r.id, r.user_id
      from public.account_deletion_requests r
      join auth.users u on u.id = r.user_id
     where r.outcome = 'operator_attention' and r.scrubbed_at is null
     order by r.requested_at, r.id
     for update of r
  loop
    update public.remediation_jobs
       set status = 'pending', next_attempt_at = now(), locked_until = null, lease_id = null,
           attempts = 0, last_error = null, completed_at = null
     where dedup_key = 'delete:' || v_case.user_id::text and kind = 'delete_account'
       and status not in ('pending', 'processing')
    returning id into v_job;
    if v_job is null then
      insert into public.remediation_jobs (kind, dedup_key, payload)
      values ('delete_account', 'delete:' || v_case.user_id::text, jsonb_build_object('user_id', v_case.user_id))
      on conflict (dedup_key) do nothing
      returning id into v_job;
    end if;
    if v_job is null then
      select id into v_job from public.remediation_jobs where dedup_key = 'delete:' || v_case.user_id::text;
    end if;
    update public.account_deletion_requests
       set outcome = 'cleanup_pending', blocker_code = null, hold_order_id = null,
           job_id = coalesce(v_job, job_id),
           affected_data_classes = array['profile', 'owned content', 'uploads', 'provider customer'],
           next_action = 'Automated cleanup is in progress.', responsible_owner = 'privacy worker',
           completed_at = null, updated_at = now()
     where id = v_case.id;
    v_count := v_count + 1;
    v_job := null;
  end loop;
  return v_count;
end $$;


--
-- Name: restore_payout_paused_listings(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.restore_payout_paused_listings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.payouts_enabled
     and not public.is_suspended(new.id)
     and exists (select 1 from private.payout_deadline_paused_listings pl where pl.seller_id = new.id) then
    perform 1 from public.listings l
    where l.id in (select pl.listing_id from private.payout_deadline_paused_listings pl where pl.seller_id = new.id)
    order by l.id for update;
    update public.listings l set status = 'active'
    where l.status = 'paused'
      and l.id in (select pl.listing_id from private.payout_deadline_paused_listings pl where pl.seller_id = new.id)
      and private.listing_can_go_live(l.id);
    delete from private.payout_deadline_paused_listings where seller_id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: restore_quarantined_photo_ref(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.restore_quarantined_photo_ref(p_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  q private.photo_refs_quarantined%rowtype;
  v_still text[];
  v_current jsonb;
  v_original jsonb;
  v_rows integer;
  v_write text := current_setting('drvn.activity_write', true);
begin
  select * into strict q from private.photo_refs_quarantined where id = p_id for update;
  if q.action = 'deleted' then
    execute format('insert into public.%I select * from jsonb_populate_record(null::public.%I, $1)', q.relation, q.relation) using q.row_data;
  elsif q.action = 'cleared' then
    execute format('update public.%I set %I = $1 where id = ($2 ->> ''id'')::uuid and %I is null', q.relation, q.field, q.field)
      using q.value, q.row_data;
    get diagnostics v_rows = row_count;  -- EXECUTE does not set FOUND
    if v_rows = 0 then
      raise exception 'Not restored: %.% on that row was changed or removed since it was moved aside (N940)', q.relation, q.field
        using errcode = '55000';
    end if;
  else
    -- Every photo of this post still moved aside, this one included, locked
    -- so two restores of one post run one after the other.
    perform 1 from private.photo_refs_quarantined
      where relation = 'activity_posts' and row_data ->> 'id' = q.row_data ->> 'id' for update;
    select array_agg(value) into v_still from private.photo_refs_quarantined
     where relation = 'activity_posts' and row_data ->> 'id' = q.row_data ->> 'id';
    v_original := q.row_data -> 'body';
    select p.body into v_current from public.activity_posts p where p.id = (q.row_data ->> 'id')::uuid for update;
    if not found or v_current is distinct from private.body_without_urls(v_original, v_still) then
      raise exception 'Not restored: the post was edited or removed since its photo was moved aside (N940)' using errcode = '55000';
    end if;
    perform set_config('drvn.activity_write', 'v1', true);
    update public.activity_posts
       set body = private.body_without_urls(v_original, array_remove(v_still, q.value))
     where id = (q.row_data ->> 'id')::uuid;
    perform set_config('drvn.activity_write', coalesce(v_write, ''), true);
  end if;
  delete from private.photo_refs_quarantined where id = p_id;
  return q.relation || '.' || q.field || ' ' || q.action || ' reference restored';
end;
$_$;


--
-- Name: row_media_keys(jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.row_media_keys(p_row jsonb, p_column text, p_kind text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_keys text[];
begin
  if p_row is null then return '{}'; end if;
  if p_kind = 'url' then
    v_keys := array[private.media_object_key(p_row ->> p_column)];
  elsif p_kind = 'json' then
    v_keys := private.json_media_keys(p_row -> p_column);
  elsif p_kind = 'evidence' then
    v_keys := array[
      case when private.media_path_ok(p_row ->> 'storage_path') then 'dispute-evidence/' || (p_row ->> 'storage_path') end,
      private.media_object_key(p_row ->> 'url'),
      case when private.media_path_ok(p_row ->> 'url') then 'dispute-evidence/' || (p_row ->> 'url') end
    ];
  elsif p_kind like 'paths:%' then
    select array_agg(substr(p_kind, 7) || '/' || e) into v_keys
      from jsonb_array_elements_text(case when jsonb_typeof(p_row -> p_column) = 'array' then p_row -> p_column else '[]'::jsonb end) e
     where private.media_path_ok(e);
  end if;
  return coalesce(array(select distinct k from unnest(v_keys) k where k is not null order by k), '{}');
end;
$$;


