--
-- Name: scrub_member_digest_items(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.scrub_member_digest_items(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  a_listing constant text := 'A listing by a member who has since left DRVN';
  v_trimmed integer;
  v_skipped integer;
  v_neutral integer;
begin
  with item as (
    select d.id as digest_id, e.i, e.ord,
           -- The member's, or no longer there at all.
           (e.i->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             or not exists (select 1 from public.listings l where l.id = (e.i->>'id')::uuid and l.seller_id is distinct from p_user) as theirs
      from public.saved_search_email_digests d
      cross join lateral jsonb_array_elements(d.items) with ordinality as e(i, ord)
  ), hit as (
    select digest_id,
           jsonb_agg(i order by ord) filter (where not theirs) as kept,
           jsonb_agg(case when theirs then jsonb_set(i, '{title}', to_jsonb(a_listing)) else i end order by ord) as neutral,
           count(*) filter (where theirs) as gone,
           bool_or(theirs and i->>'title' is distinct from a_listing) as changes
      from item group by digest_id
    having bool_or(theirs)
  ), done as (
    update public.saved_search_email_digests d
       set items = case when d.status in ('pending', 'sending') and hit.kept is not null then hit.kept else hit.neutral end,
           match_count = case when d.status in ('pending', 'sending') and hit.kept is not null
                              then greatest(d.match_count - hit.gone::integer, jsonb_array_length(hit.kept)) else d.match_count end,
           status = case when d.status in ('pending', 'sending') and hit.kept is null then 'skipped' else d.status end,
           skip_reason = case when d.status in ('pending', 'sending') and hit.kept is null then 'listings_removed' else d.skip_reason end,
           updated_at = now()
      from hit
     where d.id = hit.digest_id
       and (d.status in ('pending', 'sending') or hit.changes)
    returning (d.status = 'skipped' and d.skip_reason = 'listings_removed' and hit.kept is null) as skipped,
              (hit.kept is not null and d.items = hit.kept) as trimmed
  )
  select count(*) filter (where trimmed and not skipped), count(*) filter (where skipped), count(*) filter (where not trimmed and not skipped)
    into v_trimmed, v_skipped, v_neutral from done;
  return jsonb_build_object('digests_trimmed', v_trimmed, 'digests_not_sent', v_skipped, 'digest_titles_removed', v_neutral);
end $_$;


--
-- Name: scrub_member_notices(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.scrub_member_notices(p_user uuid, p_username text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  left_drvn constant text := 'A member who has since left DRVN';
  a_listing constant text := 'A listing by a member who has since left DRVN';
  v_actor integer;
  v_offer integer;
  v_order integer;
  v_matched integer;
begin
  update public.notifications nt
     set title = case
           -- Not the actor's words: DRVN's title stays. An unclassified kind is treated as theirs.
           when coalesce(private.notification_member_text(nt.kind), 'actor') <> 'actor' then nt.title
           when nt.kind = 'follow' then left_drvn || ' followed you'
           when nt.kind = 'car_follow' then left_drvn || ' is following your build'
           when nt.kind in ('save', 'listing_save') then left_drvn || ' saved this'
           when nt.kind = 'comment' then left_drvn || ' commented on your update'
           when nt.kind = 'reaction' then left_drvn || ' reacted to your update'
           when nt.kind = 'review' then left_drvn || ' left you a review'
           when nt.kind = 'question' then left_drvn || ' wrote about your part'
           when nt.kind = 'message' then 'Message from a member who has since left DRVN'
           else left_drvn
         end,
         body = case
           -- Offer, order and saved-search bodies are decided by linkage below.
           when coalesce(private.notification_member_text(nt.kind), 'actor') <> 'actor' then nt.body
           when nt.body is null then null
           else '(removed)'
         end,
         href = case
           when nt.target_id = p_user or (p_username is not null and nt.href = '/u/' || p_username) then null
           else nt.href
         end,
         actor_id = null
   where nt.actor_id = p_user;
  get diagnostics v_actor = row_count;

  -- 2. Offers on the member's listings, as their buyers were told.
  with linked as (
    select o.buyer_id, '/offers/' || o.id as href from public.offers o
      join public.listings l on l.id = o.listing_id
     where l.seller_id = p_user and o.buyer_id <> p_user
    union all
    select x.buyer_id, '/orders/' || x.id || suffix from public.orders x
      join public.offers o on o.id = x.origin_offer_id
      join public.listings l on l.id = o.listing_id
      cross join (values (''), ('/checkout')) as v(suffix)
     where l.seller_id = p_user and x.buyer_id <> p_user
  )
  update public.notifications nt
     set body = case nt.kind
           when 'offer_listing_withdrawn' then 'Your offer on a listing by a member who has since left DRVN has ended. Nothing was charged.'
           when 'offer_agent_out_of_rounds' then a_listing || coalesce(substring(nt.body from ' · \$[0-9,.]+ over your max$'), '')
           else a_listing
         end
    from linked
   where nt.user_id = linked.buyer_id and nt.href = linked.href
     and coalesce(private.notification_member_text(nt.kind), 'listing_title') = 'listing_title' and nt.body is not null
     and nt.body not like a_listing || '%' and nt.body not like 'Your offer on a listing by a member who has since left DRVN%';
  get diagnostics v_offer = row_count;

  -- 3. Order notices quoting what the member wrote, as the other party got them.
  update public.notifications nt
     set body = case nt.kind
           when 'order_disputed' then 'The description of the problem was removed because the member who wrote it left DRVN. See the order for details.'
           else 'The reason was removed because a member on this order left DRVN. See the order for details.'
         end
    from public.orders x
   where p_user in (x.buyer_id, x.seller_id)
     and nt.user_id in (x.buyer_id, x.seller_id) and nt.user_id <> p_user
     and nt.href = '/orders/' || x.id
     and nt.body is not null
     and (
       (nt.kind = 'order_disputed' and coalesce(x.disputed_by, x.buyer_id) = p_user)
       or (nt.kind in ('order_cancelled', 'order_refunded')
           and nt.body not in ('checkout not completed in time', 'checkout abandoned')
           and nt.body !~* 'payouts weren''t set up within 14 days')
     )
     and nt.body not like 'The % was removed because %';
  get diagnostics v_order = row_count;

  -- 4. Saved-search notices that named the member's listings to other members
  --    (src/app/api/jobs/saved-searches/route.ts: the title ends ": <listing
  --    title>" for one match, the body is up to three titles joined by " · ").
  --    Nothing links such a notice to the listing, so it is found by the
  --    exact title, whole, in its place.
  with mine as (
    select distinct l.title from public.listings l
     where l.seller_id = p_user and l.title is not null and btrim(l.title) <> ''
  )
  update public.notifications nt
     set title = coalesce((
           select left(nt.title, length(nt.title) - length(m.title)) || a_listing from mine m
            where nt.title like 'New match for %' and right(nt.title, length(m.title) + 2) = ': ' || m.title
            order by length(m.title) desc limit 1), nt.title),
         body = (
           select string_agg(case when exists (select 1 from mine m where m.title = e.t) then a_listing else e.t end, ' · ' order by e.ord)
             from unnest(string_to_array(nt.body, ' · ')) with ordinality as e(t, ord))
   where private.notification_member_text(nt.kind) = 'matched_titles'
     and nt.user_id <> p_user
     and exists (
       select 1 from mine m
        where (nt.body is not null and strpos(' · ' || nt.body || ' · ', ' · ' || m.title || ' · ') > 0)
           or (nt.title like 'New match for %' and right(nt.title, length(m.title) + 2) = ': ' || m.title));
  get diagnostics v_matched = row_count;

  return jsonb_build_object('notifications_sent', v_actor, 'offer_notice_bodies', v_offer, 'order_notice_bodies', v_order, 'saved_search_notices', v_matched);
end $_$;


--
-- Name: seller_can_take_payment(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seller_can_take_payment(p_seller uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select not private.payout_readiness_required()
      or coalesce((
        select p.payouts_enabled
            or (p.stripe_account_id is not null
                and p.payout_details_submitted
                and p.payout_restricted_at is null)
        from public.profiles p where p.id = p_seller
      ), false);
$$;


--
-- Name: FUNCTION seller_can_take_payment(p_seller uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.seller_can_take_payment(p_seller uuid) IS 'Whether this seller can publish and be bought from: payouts enabled, or Stripe setup started (details submitted) and not restricted at day 14, or job_config.payments_mode is ''stub'' (20261108100000).';


--
-- Name: signed_in_within(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.signed_in_within(p_seconds integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with claims as (
    select nullif(current_setting('request.jwt.claims', true), '')::jsonb as value
  )
  select coalesce((
    select max((entry ->> 'timestamp')::numeric)
    from claims, jsonb_array_elements(
      case when jsonb_typeof(claims.value -> 'amr') = 'array' then claims.value -> 'amr' else '[]'::jsonb end
    ) as entry
    where jsonb_typeof(entry) = 'object'
      and jsonb_typeof(entry -> 'timestamp') = 'number'
  ) between extract(epoch from now()) - p_seconds and extract(epoch from now()) + 60, false)
$$;


--
-- Name: FUNCTION signed_in_within(p_seconds integer); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.signed_in_within(p_seconds integer) IS 'True when the caller''s verified access token shows an authentication (any amr method) within p_seconds. N41.';


--
-- Name: snapshot_xmin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.snapshot_xmin() RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select pg_snapshot_xmin(pg_current_snapshot())::text::bigint $$;


--
-- Name: storage_reference_rows(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.storage_reference_rows() RETURNS TABLE(source text, bucket text, path text, retention_expired boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with refs(source, k, expired) as (
    select 'car_images', private.media_object_key(url), false from public.car_images
    union all select 'listing_images', private.media_object_key(url), false from public.listing_images
    union all select 'activity_images', private.media_object_key(url), false from public.activity_images
    union all select 'order_item_snapshot_images', private.media_object_key(url), false from public.order_item_snapshot_images
    union all select 'profiles.avatar_url', private.media_object_key(avatar_url), false from public.profiles
    union all select 'cars.cover_image_url', private.media_object_key(cover_image_url), false from public.cars
    union all select 'mod_items.image_url', private.media_object_key(image_url), false from public.mod_items
    union all select 'car_hotspots.image_url', private.media_object_key(image_url), false from public.car_hotspots
    -- Evidence by bare path (0027), legacy rows by URL or by bare path in url.
    union all select 'dispute_evidence', 'dispute-evidence/' || storage_path, false from public.dispute_evidence
      where private.media_path_ok(storage_path)
    union all select 'dispute_evidence',
      coalesce(private.media_object_key(url), case when private.media_path_ok(url) then 'dispute-evidence/' || url end), false
      from public.dispute_evidence
    union all select 'messages.attachments', 'message-photos/' || a, false
      from public.messages m cross join lateral unnest(m.attachments) a where private.media_path_ok(a)
    union all select 'agent_messages.images', private.media_object_key(i), private.agent_chat_photo_swept(am.created_at)
      from public.agent_messages am cross join lateral unnest(am.images) i
    union all select 'order_items.commercial_snapshot', unnest(private.json_media_keys(commercial_snapshot)), false
      from public.order_items where strpos(commercial_snapshot::text, '/storage/v1/') > 0
    union all select 'activity_posts.body', unnest(private.json_media_keys(body)), false
      from public.activity_posts where strpos(body::text, '/storage/v1/') > 0
  )
  select r.source, split_part(r.k, '/', 1), substr(r.k, length(split_part(r.k, '/', 1)) + 2), bool_and(r.expired)
    from refs r
   where r.k is not null
   group by 1, 2, 3;
$$;


--
-- Name: strip_media_from_body(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.strip_media_from_body(p_body jsonb, p_keys text[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when jsonb_typeof(p_body) <> 'array' then p_body else coalesce((
    select jsonb_agg(blk order by ord) from (
      select ord,
             case when b ->> 'type' = 'images' and jsonb_typeof(b -> 'urls') = 'array'
                  then jsonb_set(b, '{urls}', coalesce((
                         select jsonb_agg(u order by n) from jsonb_array_elements(b -> 'urls') with ordinality x(u, n)
                          where not coalesce(private.media_object_key(u #>> '{}') = any(p_keys), false)), '[]'::jsonb))
                  else b end as blk
        from jsonb_array_elements(p_body) with ordinality t(b, ord)
       where not (b ->> 'type' = 'before_after'
                  and (coalesce(private.media_object_key(b ->> 'beforeUrl') = any(p_keys), false)
                       or coalesce(private.media_object_key(b ->> 'afterUrl') = any(p_keys), false)))
    ) s
    where not (blk ->> 'type' = 'images' and jsonb_typeof(blk -> 'urls') = 'array' and jsonb_array_length(blk -> 'urls') = 0)
  ), '[]'::jsonb) end;
$$;


--
-- Name: username_lock_key(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.username_lock_key(p_username text) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select hashtextextended('drvn:username:' || lower(p_username), 0);
$$;


--
-- Name: account_deletion_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_blockers(p_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'financial_hold',
      exists(select 1 from public.orders where (buyer_id=p_user or seller_id=p_user) and status not in ('completed','cancelled','payment_failed','refunded'))
      or exists(select 1 from public.transfer_intents where seller_id=p_user and status not in ('transferred','cancelled'))
      or exists(select 1 from public.refund_operations r join public.orders o on o.id=r.order_id where (o.buyer_id=p_user or o.seller_id=p_user) and r.status<>'completed')
      or exists(select 1 from public.payment_requests p where p.request->>'buyerId'=p_user::text and p.provider_reference is null)
      or exists(select 1 from public.payment_recoveries r join public.orders o on o.id=r.order_id where r.status='open' and (o.buyer_id=p_user or o.seller_id=p_user))
      or exists(select 1 from public.returns r join public.orders o on o.id=r.order_id where (o.buyer_id=p_user or o.seller_id=p_user) and r.status not in ('completed','rejected','expired','cancelled'))
      -- Same "unresolved" as private.order_has_unresolved_chargeback (20261107130000).
      or exists(select 1 from public.stripe_dispute_journal j join public.orders o on o.id=any(j.order_ids) where j.state not in ('won','warning_closed','lost') and (o.buyer_id=p_user or o.seller_id=p_user)),
    'retained_identity',
      exists(select 1 from public.orders where buyer_id=p_user or seller_id=p_user)
      or exists(select 1 from public.admin_audit_log where actor_id=p_user)
      or exists(select 1 from public.reports where reporter_id=p_user or resolved_by=p_user)
      or exists(select 1 from public.refund_operations where requested_by=p_user::text)
  );
$$;


--
-- Name: account_deletion_finalise(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_finalise(p_job uuid, p_lease uuid, p_user uuid, p_retained jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_blockers jsonb;
begin
  perform pg_advisory_xact_lock(private.account_deletion_lock_key(p_user));
  if not private.account_deletion_lease_held(p_job, p_lease, p_user) then
    raise exception 'Deletion lease lost';
  end if;

  v_blockers := public.account_deletion_blockers(p_user);
  if coalesce((v_blockers->>'financial_hold')::boolean, true) then
    return v_blockers || jsonb_build_object('held', true, 'hold_order_id', private.account_deletion_hold_order(p_user),
      'scrubbed', exists (select 1 from public.account_deletion_requests where user_id = p_user and scrubbed_at is not null));
  end if;

  if coalesce((v_blockers->>'retained_identity')::boolean, true) then
    if p_retained is null or jsonb_typeof(p_retained) <> 'object' or coalesce(p_retained->>'next_action', '') = '' then
      raise exception 'The retained-identity record is required' using errcode = '22023';
    end if;
    update public.account_deletion_requests
       set outcome = 'operator_attention',
           blocker_code = p_retained->>'blocker_code',
           affected_data_classes = array(select jsonb_array_elements_text(coalesce(p_retained->'affected_data_classes', '[]'::jsonb))),
           next_action = p_retained->>'next_action',
           responsible_owner = p_retained->>'responsible_owner',
           review_at = null,
           policy_decisions_pending = array(select jsonb_array_elements_text(coalesce(p_retained->'policy_decisions_pending', '[]'::jsonb))),
           hold_order_id = null,
           updated_at = now()
     where user_id = p_user;
    if not found then raise exception 'Deletion request record is missing'; end if;
    perform public.finish_remediation_job(p_job, p_lease, null);
    return v_blockers || jsonb_build_object('held', false, 'outcome', 'operator_attention');
  end if;

  return v_blockers || jsonb_build_object('held', false, 'outcome', 'hard_delete_eligible');
end $$;


--
-- Name: account_deletion_hold_gate(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_hold_gate(p_job uuid, p_lease uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_blockers jsonb;
  v_scrubbed boolean;
begin
  perform pg_advisory_xact_lock(private.account_deletion_lock_key(p_user));
  if not private.account_deletion_lease_held(p_job, p_lease, p_user) then
    raise exception 'Deletion lease lost';
  end if;

  v_scrubbed := exists (select 1 from public.account_deletion_requests where user_id = p_user and scrubbed_at is not null);
  v_blockers := public.account_deletion_blockers(p_user);
  -- An unreadable answer holds: never ban or delete on a guess.
  if coalesce((v_blockers->>'financial_hold')::boolean, true) then
    return v_blockers || jsonb_build_object('held', true, 'hold_order_id', private.account_deletion_hold_order(p_user), 'scrubbed', v_scrubbed);
  end if;

  update public.account_deletion_requests
     set outcome = 'cleanup_pending', blocker_code = null, hold_order_id = null,
         affected_data_classes = array['profile', 'owned content', 'uploads', 'provider customer'],
         next_action = 'Automated cleanup is in progress.', responsible_owner = 'privacy worker',
         updated_at = now()
   where user_id = p_user
     and (outcome = 'temporary_financial_hold'
          or (outcome = 'operator_attention' and blocker_code = 'late_hold_after_scrub'));
  return v_blockers || jsonb_build_object('held', false, 'hold_order_id', null, 'scrubbed', v_scrubbed);
end $$;


--
-- Name: activity_post_search_text(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activity_post_search_text(body jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select coalesce(string_agg(part, ' '), '')
  from (
    select case b.value->>'type'
      when 'text' then b.value->>'text'
      when 'mod' then concat_ws(' ', b.value->>'label', b.value->>'detail')
      when 'performance' then b.value->>'note'
      else null
    end as part
    from jsonb_array_elements(
      case when jsonb_typeof(body) = 'array' then body else '[]'::jsonb end
    ) as b
  ) parts
  where part is not null and part <> ''
$$;


