    CONSTRAINT admin_audit_log_subject_type_check CHECK ((subject_type = ANY (ARRAY['agent'::text, 'copyright_notice'::text, 'dispute'::text, 'export'::text, 'listing'::text, 'order'::text, 'payment'::text, 'product_review'::text, 'report'::text, 'user'::text])))
);


--
-- Name: admin_audit_page(text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_audit_page(p_action text DEFAULT NULL::text, p_actor text DEFAULT NULL::text, p_subject_type text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id bigint DEFAULT NULL::bigint, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50) RETURNS SETOF public.admin_audit_log
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_action text := nullif(trim(coalesce(p_action, '')), '');
  v_actor text := nullif(trim(coalesce(p_actor, '')), '');
  -- Literal text inside an ILIKE pattern: \ % and _ match themselves.
  v_action_like text := replace(replace(replace(coalesce(v_action, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  v_actor_like text := '%' || replace(replace(replace(coalesce(v_actor, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
begin
  if (p_before_at is null) <> (p_before_id is null) then
    raise exception 'A page cursor needs both its time and its id' using errcode = '22023';
  end if;
  return query
  select a.*
  from public.admin_audit_log a
  where (v_action is null or a.action ilike v_action_like)
    and (p_subject_type is null or a.subject_type = p_subject_type)
    and (p_from is null or a.created_at >= p_from)
    and (p_to is null or a.created_at < p_to)
    and (v_actor is null or exists (
          select 1 from public.profiles pr
          where pr.id = a.actor_id
            and (pr.username ilike v_actor_like or pr.display_name ilike v_actor_like)))
    and (p_before_id is null or (a.created_at, a.id) < (p_before_at, p_before_id))
  order by a.created_at desc, a.id desc
  offset greatest(coalesce(p_offset, 0), 0)
  limit least(greatest(coalesce(p_limit, 50), 1), 1000);
end;
$$;


--
-- Name: admin_cancel_seller_carry_payout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_cancel_seller_carry_payout(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_payout public.seller_carry_payouts;
  v_restored boolean := false;
begin
  if p_id is null then
    raise exception 'A payout is required' using errcode = '22023';
  end if;
  select * into v_payout from public.seller_carry_payouts where id = p_id for update;
  if not found then
    raise exception 'That payout no longer exists' using errcode = 'P0002';
  end if;
  if v_payout.status in ('paid', 'cancelled') then
    raise exception 'This payout is already %', v_payout.status using errcode = '22023';
  end if;
  if v_payout.status = 'processing' and v_payout.lease_expires_at is not null and v_payout.lease_expires_at > now() then
    raise exception 'A worker holds this payout right now; try again in a few minutes' using errcode = '55P03';
  end if;
  if v_payout.provider_call_may_have_occurred then
    raise exception 'Stripe may have been called for this payout, so it cannot be cancelled: find the transfer in Stripe (group carry-payout:%), then retry so the worker completes it', v_payout.id
      using errcode = '22023';
  end if;
  if v_payout.seller_id is not null then
    -- The lock every carry writer takes; the balance can't move under us.
    perform pg_advisory_xact_lock(hashtextextended('seller-carry:' || v_payout.seller_id::text, 0));
    perform public.record_seller_carry(
      v_payout.seller_id, 'paid_out_reversed', v_payout.amount_cents, null, null,
      'paid-out-reversed:' || v_payout.id::text);
    v_restored := true;
  end if;
  update public.seller_carry_payouts
     set status = 'cancelled',
         next_attempt_at = null,
         locked_by = null,
         lease_expires_at = null,
         updated_at = now()
   where id = p_id;
  return jsonb_build_object('id', p_id, 'status', 'cancelled', 'previous_status', v_payout.status,
                            'credit_restored_cents', case when v_restored then v_payout.amount_cents else 0 end);
end;
$$;


