--
-- Name: admin_export_orders(text, text, text, text, timestamp with time zone, timestamp with time zone, integer, integer, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_export_orders(p_view text, p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_min_cents integer DEFAULT NULL::integer, p_max_cents integer DEFAULT NULL::integer, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, sort_at timestamp with time zone, created_at timestamp with time zone, status text, total_cents integer, refunded_cents integer, currency text, transferred boolean, disputed_at timestamp with time zone, dispute_resolved_at timestamp with time zone, dispute_category text, dispute_reason text, refund_offer_cents integer, buyer_id uuid, buyer_username text, buyer_display_name text, seller_id uuid, seller_username text, seller_display_name text, title text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_q text := nullif(trim(coalesce(p_query, '')), '');
  v_hex text;
  v_like text;
  v_limit int := least(greatest(coalesce(p_limit, 500), 1), 1000);
begin
  if p_view not in ('orders', 'disputes_open', 'disputes_resolved') then
    raise exception 'Unknown export view %', p_view using errcode = '22023';
  end if;
  if (p_after_at is null) <> (p_after_id is null) then
    raise exception 'A page cursor needs both its time and its id' using errcode = '22023';
  end if;
  -- An id-shaped search is an order-id prefix (dashes optional); a pi_
  -- search is a payment reference; anything else is a name (or, for
  -- disputes, an item title).
  if v_q ~* '^[0-9a-f-]{8,}$' then v_hex := replace(lower(v_q), '-', ''); end if;
  -- Literal text inside an ILIKE pattern: \ % and _ match themselves.
  v_like := '%' || replace(replace(replace(coalesce(v_q, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
  with picked as (
    select o.*,
      case p_view
        when 'orders' then o.created_at
        -- An open dispute missing its timestamp still gets a place in the order.
        when 'disputes_open' then coalesce(o.disputed_at, o.created_at)
        else o.dispute_resolved_at
      end as sort_key
    from public.orders o
    where case p_view
            when 'orders' then true
            when 'disputes_open' then o.status = 'disputed'
            else o.dispute_resolved_at is not null
          end
      and (p_status is null or p_view <> 'orders' or o.status = p_status)
      and (p_category is null or p_view = 'orders' or o.dispute_category = p_category)
      and (p_from is null or p_view <> 'orders' or o.created_at >= p_from)
      and (p_to is null or p_view <> 'orders' or o.created_at < p_to)
      and (p_min_cents is null or p_view <> 'orders' or o.total_cents >= p_min_cents)
      and (p_max_cents is null or p_view <> 'orders' or o.total_cents <= p_max_cents)
      and (
        v_q is null
        or (v_hex is not null and (
              replace(o.id::text, '-', '') like v_hex || '%'
              or (p_view = 'orders' and exists (
                select 1 from public.payments pay
                where pay.order_id = o.id and pay.provider_reference ilike v_q || '%'))))
        or (v_hex is null and lower(v_q) like 'pi\_%' and p_view = 'orders' and exists (
              select 1 from public.payments pay
              where pay.order_id = o.id and pay.provider_reference ilike v_q || '%'))
        or (v_hex is null and not (p_view = 'orders' and lower(v_q) like 'pi\_%') and (
              exists (
                select 1 from public.profiles pr
                where pr.id in (o.buyer_id, o.seller_id)
                  and (pr.username ilike v_like or pr.display_name ilike v_like))
              or (p_view <> 'orders' and exists (
                select 1 from public.order_items oi
                where oi.order_id = o.id and oi.title ilike v_like))))
      )
  )
  select p.id, p.sort_key, p.created_at, p.status, p.total_cents, p.refunded_cents, p.currency,
         p.transfer_reference is not null,
         p.disputed_at, p.dispute_resolved_at, p.dispute_category, p.dispute_reason, p.refund_offer_cents,
         p.buyer_id, b.username, b.display_name,
         p.seller_id, s.username, s.display_name,
         items.title
  from picked p
  left join public.profiles b on b.id = p.buyer_id
  left join public.profiles s on s.id = p.seller_id
  left join lateral (
    select case when count(*) > 1
                then coalesce((array_agg(oi.title order by oi.id))[1], 'Part') || ' +' || (count(*) - 1) || ' more'
                else (array_agg(coalesce(oi.title, 'Part') order by oi.id))[1]
           end as title
    from public.order_items oi
    where oi.order_id = p.id
  ) items on true
  where p_after_id is null
     or (p_view = 'disputes_open' and (p.sort_key, p.id) > (p_after_at, p_after_id))
     or (p_view <> 'disputes_open' and (p.sort_key, p.id) < (p_after_at, p_after_id))
  order by
    case when p_view = 'disputes_open' then p.sort_key end asc,
    case when p_view = 'disputes_open' then p.id end asc,
    case when p_view <> 'disputes_open' then p.sort_key end desc,
    case when p_view <> 'disputes_open' then p.id end desc
  limit v_limit;
end;
$_$;


--
-- Name: admin_open_agent_chat(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_open_agent_chat(p_member uuid, p_case_kind text, p_case uuid, p_reason text) RETURNS TABLE(id uuid, role text, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists(
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->'amr', '[]'::jsonb)) m
    where m->>'method' in ('totp', 'mfa/totp')
      and (m->>'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then raise exception 'Admin step-up required' using errcode = '42501'; end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 1000 then
    raise exception 'A reason of 1–1000 characters is required' using errcode = '22023';
  end if;
  if p_case_kind is null or p_case_kind not in ('dispute', 'report') or p_case is null or p_member is null then
    raise exception 'Name the dispute or report this is for' using errcode = '22023';
  end if;
  -- A dispute is an order that has one (orders.dispute_reason, 0007/0046);
  -- the member must be a party to it.
  if (p_case_kind = 'dispute' and not exists (select 1 from public.orders o where o.id = p_case
        and (o.dispute_reason is not null or o.status = 'disputed') and p_member in (o.buyer_id, o.seller_id)))
     -- A report about this member: them, a listing of theirs, or one they filed.
     or (p_case_kind = 'report' and not exists (select 1 from public.reports r where r.id = p_case
        and (r.reporter_id = p_member
             or (r.subject_type = 'user' and r.subject_id = p_member)
             or (r.subject_type = 'listing' and exists (select 1 from public.listings l where l.id = r.subject_id and l.seller_id = p_member))))) then
    raise exception 'No such case' using errcode = 'P0002';
  end if;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'agent.chat_opened', 'user', p_member, btrim(p_reason),
    jsonb_build_object('case_kind', p_case_kind, 'case_id', p_case));
  return query
    select m.id, m.role, m.body, m.created_at
    from public.agent_messages m join public.agent_conversations c on c.id = m.conversation_id
    where c.owner_id = p_member order by m.created_at;
end;
$$;


--
-- Name: admin_open_operations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_open_operations(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(o) order by o.id desc), '[]'::jsonb)
  from (
    select r.id, r.action, r.subject_type, r.subject_id, r.order_id, r.reason, r.created_at, r.actor_id,
           r.metadata->>'operationId' as operation_id,
           coalesce(l.phases, '{}'::text[]) as phases,
           greatest(r.id, coalesce(l.newest, 0)) as seen_through
    from public.admin_audit_log r
    left join lateral (
      select array_agg(distinct a.metadata->>'phase') as phases, max(a.id) as newest
      from public.admin_audit_log a
      where a.metadata->>'operationId' = r.metadata->>'operationId'
        and a.metadata->>'phase' <> 'requested'
    ) l on true
    where r.metadata->>'phase' = 'requested'
      and r.metadata->>'operationId' is not null
      and not exists (
        select 1 from public.admin_audit_log c
        where c.metadata->>'operationId' = r.metadata->>'operationId'
          and c.metadata->>'phase' in ('completed', 'reconciled')
      )
    order by r.id desc
    limit least(greatest(coalesce(p_limit, 50), 1), 200)
  ) o;
$$;


--
-- Name: FUNCTION admin_open_operations(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_open_operations(p_limit integer) IS 'The newest admin operations still awaiting an outcome (a "requested" audit row with no "completed" or "reconciled" row), with the phases recorded since and the operation''s newest audit id (N718). With fewer open operations than the limit it probes every requested row through the index, so its cost grows with the log: for the admin audit page only. Service role only.';


--
-- Name: admin_order_money_window(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_order_money_window(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'orders', (
      select count(*) from public.orders
      where created_at >= p_from and created_at < p_to
        and status in ('paid', 'shipped', 'delivered', 'completed', 'disputed', 'refunded')
    ),
    'gmv_cents', (
      select coalesce(sum(total_cents), 0) from public.orders
      where created_at >= p_from and created_at < p_to
        and status in ('paid', 'shipped', 'delivered', 'completed', 'disputed', 'refunded')
    ),
    'fee_cents', (
      select coalesce(sum(platform_fee_cents), 0) from public.orders
      where created_at >= p_from and created_at < p_to
        and status in ('paid', 'shipped', 'delivered', 'completed', 'disputed', 'refunded')
    ),
    'refunded_cents', (
      select coalesce(sum(refunded_cents), 0) from public.orders
      where refunded_cents > 0 and refunded_at >= p_from and refunded_at < p_to
    ),
    'fee_refunded_cents', (
      select coalesce(sum(platform_fee_refunded_cents), 0) from public.orders
      where refunded_cents > 0 and refunded_at >= p_from and refunded_at < p_to
    )
  );
$$;


--
-- Name: admin_resume_account_deletion(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resume_account_deletion(p_actor uuid, p_user uuid, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.account_deletion_requests%rowtype;
  v_job public.remediation_jobs%rowtype;
  v_held boolean;
  v_shape text;
begin
  -- The database's own check that the caller acts for a full admin. Before
  -- anything else, the dry run included: a refusal's words describe a
  -- member's deletion, and are for an admin to read.
  perform public.assert_admin_actor(p_actor);
  if p_user is null then raise exception 'Missing member' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(private.account_deletion_lock_key(p_user));

  select * into v_request from public.account_deletion_requests where user_id = p_user for update;
  if not found then raise exception 'This member has no deletion request' using errcode = 'P0002'; end if;
  if v_request.outcome = 'completed' then raise exception 'This deletion is already complete' using errcode = '22023'; end if;

  select * into v_job from public.remediation_jobs
   where dedup_key = 'delete:' || p_user::text and kind = 'delete_account'
   for update;
  if not found then raise exception 'This deletion has no job to resume' using errcode = 'P0002'; end if;
  if v_job.status in ('pending', 'processing') then
    raise exception 'This deletion is already queued or running; the worker picks it up on its next pass' using errcode = '22023';
  end if;

  v_held := coalesce((public.account_deletion_blockers(p_user)->>'financial_hold')::boolean, true);

  if v_job.status = 'failed' then
    v_shape := 'failed_job';
  elsif v_request.outcome = 'operator_attention' and v_request.blocker_code = 'late_hold_after_scrub' then
    if v_held then
      raise exception 'The order that holds this deletion is still open. Settle it first (refund, payout or chargeback), then resume' using errcode = '22023';
    end if;
    v_shape := 'late_hold_settled';
  elsif v_request.outcome = 'operator_attention' and v_request.blocker_code = 'immutable_retained_identity' then
    raise exception 'Nothing to resume: personal data is removed and the transaction keys are kept until the retention date' using errcode = '22023';
  elsif v_request.outcome = 'temporary_financial_hold' then
    raise exception 'The member settles this hold themselves; the worker rechecks it every hour' using errcode = '22023';
  else
    raise exception 'Nothing to resume in this state' using errcode = '22023';
  end if;

  -- The console asks first (p_dry_run), so a refusal is said in words before
  -- anything is journalled; the real call repeats every check under the lock.
  if not coalesce(p_dry_run, false) then
    update public.remediation_jobs
       set status = 'pending', next_attempt_at = now(), locked_until = null, lease_id = null,
           attempts = 0, last_error = null, completed_at = null
     where id = v_job.id;
  end if;

  return jsonb_build_object(
    'resumed', not coalesce(p_dry_run, false),
    'shape', v_shape,
    'previous_job_status', v_job.status,
    'previous_error', v_job.last_error,
    'outcome', v_request.outcome,
    'blocker_code', v_request.blocker_code,
    'still_held', v_held
  );
end $$;


--
-- Name: admin_retry_dispute_recovery(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retry_dispute_recovery(p_dispute text, p_actor uuid, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_entry public.stripe_dispute_journal%rowtype;
  v_case public.payment_recoveries%rowtype;
begin
  perform public.assert_admin_actor(p_actor);
  select * into v_entry from public.stripe_dispute_journal where dispute_id = p_dispute for update;
  if not found then raise exception 'No such chargeback' using errcode = 'P0002'; end if;
  if v_entry.state <> 'recovery' then
    raise exception 'This chargeback isn''t held for review (it is %)', v_entry.state using errcode = '22023';
  end if;
  if v_entry.held_from_state in ('won', 'warning_closed', 'lost') then
    raise exception 'This chargeback was already settled as % before a conflicting Stripe event held it. Retry can''t change a settled outcome: check the dispute in Stripe and leave the case for the owner', v_entry.held_from_state
      using errcode = '22023';
  end if;
  if v_entry.held_from_state = 'loss_pending' then
    raise exception 'A loss was being booked when this chargeback was held. Retry can''t finish a booking: leave the case for the owner'
      using errcode = '22023';
  end if;
  if v_entry.held_from_state is distinct from 'open' then
    -- Null: held before 20261110230000 recorded where from. It may have been
    -- settled or mid-booking, so it is treated as if it was.
    raise exception 'This chargeback was held before the state it was held from was recorded, so Retry can''t tell whether it is safe: check the dispute in Stripe and leave the case for the owner'
      using errcode = '22023';
  end if;
  if v_entry.held_event_id is null then
    raise exception 'No Stripe event is recorded for this hold, so there is nothing to replay. Check the dispute in Stripe; its next event is handled normally'
      using errcode = '22023';
  end if;
  if not exists (select 1 from public.webhook_events w where w.id = v_entry.held_event_id and w.payload is not null) then
    raise exception 'The Stripe event that caused this hold (%) isn''t stored, so it can''t be replayed', v_entry.held_event_id
      using errcode = '22023';
  end if;
  perform 1 from public.orders where id = any(v_entry.order_ids) order by id for update;
  select * into v_case from public.payment_recoveries where recovery_key = 'stripe:dispute:' || p_dispute for update;
  if not coalesce(p_dry_run, false) then
    -- The entry stays held. The replay of this event, inside five minutes,
    -- reopens it and applies it in one transaction (apply_stripe_dispute_event).
    update public.stripe_dispute_journal set retry_until = now() + interval '5 minutes', updated_at = now()
     where dispute_id = p_dispute;
  end if;
  return jsonb_build_object(
    'dispute_id', p_dispute,
    'event_id', v_entry.held_event_id,
    'replay_allowed', not coalesce(p_dry_run, false),
    'before', jsonb_build_object(
      'state', v_entry.state, 'held_from_state', v_entry.held_from_state,
      'amount_cents', v_entry.amount_cents, 'currency', v_entry.currency, 'order_ids', to_jsonb(v_entry.order_ids),
      'last_event_id', v_entry.last_event_id, 'held_event_id', v_entry.held_event_id,
      'case_id', v_case.id, 'case_status', v_case.status));
end;
$$;


--
-- Name: admin_retry_seller_carry_payout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retry_seller_carry_payout(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_payout public.seller_carry_payouts;
begin
  if p_id is null then
    raise exception 'A payout is required' using errcode = '22023';
  end if;
  select * into v_payout from public.seller_carry_payouts where id = p_id for update;
  if not found then
    raise exception 'That payout no longer exists' using errcode = 'P0002';
  end if;
  if v_payout.status in ('paid', 'cancelled') then
    raise exception 'This payout is already %', v_payout.status using errcode = '22023';
  end if;
  if v_payout.status = 'processing' and v_payout.lease_expires_at is not null and v_payout.lease_expires_at > now() then
    raise exception 'A worker holds this payout right now; try again in a few minutes' using errcode = '55P03';
  end if;
  update public.seller_carry_payouts
     set status = 'pending',
         attempts = 0,
         next_attempt_at = null,
         locked_by = null,
         lease_expires_at = null,
         updated_at = now()
   where id = p_id;
  return jsonb_build_object('id', p_id, 'status', 'pending', 'previous_status', v_payout.status,
                            'provider_call_may_have_occurred', v_payout.provider_call_may_have_occurred);
end;
$$;


--
-- Name: admin_retry_transfer_intent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retry_transfer_intent(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_intent public.transfer_intents;
begin
  if p_order is null then
    raise exception 'A payout is required' using errcode = '22023';
  end if;
  -- Parent lock first, as refund settlement, completion and recovery take it.
  perform 1 from public.orders where id = p_order for key share;
  select * into v_intent from public.transfer_intents where order_id = p_order for update;
  if not found then
    raise exception 'That payout no longer exists' using errcode = 'P0002';
  end if;
  if v_intent.status in ('transferred', 'cancelled') then
    raise exception 'This payout is already %', v_intent.status using errcode = '22023';
  end if;
  if v_intent.status = 'processing' then
    raise exception 'A worker holds this payout right now; try again in a few minutes' using errcode = '55P03';
  end if;
  -- Only a payout the worker gave up on. Anything else is still the
  -- worker's (it retries on its own) or waits on the seller or readiness.
  if v_intent.status <> 'failed' or v_intent.attempts < 8 then
    raise exception 'This payout is still being retried automatically' using errcode = '22023';
  end if;

  update public.transfer_intents
     set attempts = 0,
         next_attempt_at = null,
         last_error = 'Queued again by an operator',
         locked_at = null,
         locked_by = null,
         lease_expires_at = null,
         updated_at = now()
   where order_id = p_order;

  return jsonb_build_object(
    'order_id', p_order,
    'status', 'failed',
    'previous_attempts', v_intent.attempts,
    'provider_call_may_have_occurred', v_intent.provider_call_may_have_occurred
  );
end;
$$;


--
-- Name: admin_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select a.role from public.admin_users a
  where a.user_id = auth.uid()
    and (a.sessions_valid_after is null
      or coalesce((nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'iat')::numeric, 0)
         > extract(epoch from a.sessions_valid_after))
    and private.admin_factor_confirmed(a.user_id, a.mfa_factor_id);
$$;


--
-- Name: admin_set_agent_beta_step(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_agent_beta_step(p_step text, p_open boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists(
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->'amr', '[]'::jsonb)) m
    where m->>'method' in ('totp', 'mfa/totp')
      and (m->>'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then raise exception 'Admin step-up required' using errcode = '42501'; end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 1000 then
    raise exception 'A reason of 1–1000 characters is required' using errcode = '22023';
  end if;
  if p_step is null or p_step not in ('seller', 'buyer', 'chat', 'jobs') or p_open is null then
    raise exception 'Invalid step' using errcode = '22023';
  end if;
  update public.agent_beta_steps set open = p_open, changed_by = v_actor, changed_at = now(), reason = btrim(p_reason)
  where step = p_step;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, case when p_open then 'agent.beta_open' else 'agent.beta_close' end, 'agent', gen_random_uuid(), btrim(p_reason),
    jsonb_build_object('step', p_step));
end;
$$;


--
-- Name: admin_set_agent_control(text, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_agent_control(p_scope text, p_subject uuid, p_on boolean, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_id uuid;
  v_subject_type text;
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists(
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->'amr', '[]'::jsonb)) m
    where m->>'method' in ('totp', 'mfa/totp')
      and (m->>'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then raise exception 'Admin step-up required' using errcode = '42501'; end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 1000 then
    raise exception 'A reason of 1–1000 characters is required' using errcode = '22023';
  end if;
  if p_scope is null or p_scope not in ('all', 'buyer', 'seller', 'member', 'mandate', 'listing', 'account') or p_on is null
     or ((p_scope in ('all', 'buyer', 'seller')) <> (p_subject is null)) then
    raise exception 'Invalid kill switch' using errcode = '22023';
  end if;
  if (p_scope in ('member', 'account') and not exists (select 1 from public.profiles where id = p_subject))
     or (p_scope = 'mandate' and not exists (select 1 from public.agent_mandates where id = p_subject))
     or (p_scope = 'listing' and not exists (select 1 from public.listings where id = p_subject)) then
    raise exception 'Not found' using errcode = 'P0002';
  end if;
  -- Exclusive against the worker's shared lock: waits for agent writes in flight.
  perform pg_advisory_xact_lock(public.agent_controls_lock_key());
  select id into v_id from public.agent_controls
  where scope = p_scope and subject_id is not distinct from p_subject and cleared_at is null;
  if p_on and v_id is null then
    insert into public.agent_controls(scope, subject_id, reason, set_by) values (p_scope, p_subject, btrim(p_reason), v_actor)
    returning id into v_id;
  elsif not p_on and v_id is not null then
    update public.agent_controls set cleared_at = now(), cleared_by = v_actor where id = v_id;
  elsif v_id is null then
    -- Already off: still audited, nothing changes.
    v_id := coalesce(p_subject, gen_random_uuid());
  end if;
  v_subject_type := case p_scope when 'listing' then 'listing' when 'member' then 'user' when 'account' then 'user' else 'agent' end;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, case when p_on then 'agent.pause' else 'agent.resume' end, v_subject_type, coalesce(p_subject, v_id), btrim(p_reason),
    jsonb_build_object('scope', p_scope, 'control_id', v_id));
  return v_id;
end;
$$;


--
-- Name: admin_set_agent_spend_limits(numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_agent_spend_limits(p_member_usd numeric, p_global_usd numeric, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists(
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->'amr', '[]'::jsonb)) m
    where m->>'method' in ('totp', 'mfa/totp')
      and (m->>'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then raise exception 'Admin step-up required' using errcode = '42501'; end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 1000 then
    raise exception 'A reason of 1–1000 characters is required' using errcode = '22023';
  end if;
  if p_member_usd is null or p_global_usd is null or p_member_usd < 0 or p_global_usd < 0 or p_member_usd > p_global_usd then
    raise exception 'Caps must be zero or more, and the member cap no more than the global one' using errcode = '22023';
  end if;
  update public.agent_spend_limits set per_member_daily_usd = p_member_usd, global_daily_usd = p_global_usd,
    changed_by = v_actor, changed_at = now() where singleton;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'agent.spend_limits', 'agent', gen_random_uuid(), btrim(p_reason),
    jsonb_build_object('per_member_daily_usd', p_member_usd, 'global_daily_usd', p_global_usd));
end;
$$;


--
-- Name: admin_users_page(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_users_page(p_query text DEFAULT NULL::text, p_state text DEFAULT 'all'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_q text := nullif(trim(coalesce(p_query, '')), '');
  v_like text := '%' || replace(replace(replace(coalesce(v_q, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  v_total bigint;
  v_rows jsonb;
begin
  if coalesce(p_state, 'all') not in ('all', 'suspended', 'sellers', 'no_payouts', 'admins') then
    raise exception 'Unknown member filter %', p_state using errcode = '22023';
  end if;

  with matched as (
    select pr.*
    from public.profiles pr
    where (
        v_q is null
        -- Support mail arrives by email address: match the account's email.
        or (position('@' in v_q) > 0 and exists (
              select 1 from public.account_emails e where e.user_id = pr.id and e.email ilike v_like))
        or (position('@' in v_q) = 0 and (pr.username ilike v_like or pr.display_name ilike v_like))
      )
      and case coalesce(p_state, 'all')
            when 'suspended' then pr.suspended_at is not null
            when 'admins' then exists (select 1 from public.admin_users au where au.user_id = pr.id)
            when 'sellers' then exists (select 1 from public.listings l where l.seller_id = pr.id)
                             or exists (select 1 from public.orders o where o.seller_id = pr.id)
            when 'no_payouts' then not pr.payouts_enabled and (
                               exists (select 1 from public.listings l where l.seller_id = pr.id)
                               or exists (select 1 from public.orders o where o.seller_id = pr.id))
            else true
          end
  ),
  counted as (select count(*) as n from matched),
  page as (
    select m.* from matched m
    order by m.created_at desc, m.id desc
    offset greatest(coalesce(p_offset, 0), 0)
    limit least(greatest(coalesce(p_limit, 50), 1), 200)
  )
  select (select n from counted),
         coalesce(jsonb_agg(jsonb_build_object(
           'id', pg.id,
           'username', pg.username,
           'display_name', pg.display_name,
           'profile_type', pg.profile_type,
           'created_at', pg.created_at,
           'suspended_at', pg.suspended_at,
           'suspended_reason', pg.suspended_reason,
           'payouts_enabled', pg.payouts_enabled,
           'listing_count', (select count(*) from public.listings l where l.seller_id = pg.id),
           -- A sale is an order that was paid — cancelled and abandoned ones aren't.
           'sale_count', (select count(*) from public.orders o where o.seller_id = pg.id
                            and o.status in ('paid', 'shipped', 'delivered', 'completed', 'disputed')),
           'dispute_count', (select count(*) from public.orders o where o.seller_id = pg.id and o.disputed_at is not null)
                          + (select count(*) from public.orders o where o.buyer_id = pg.id and o.disputed_at is not null),
           'is_admin', exists (select 1 from public.admin_users au where au.user_id = pg.id)
         ) order by pg.created_at desc, pg.id desc), '[]'::jsonb)
    into v_total, v_rows
  from page pg;

  return jsonb_build_object('total', coalesce(v_total, 0), 'rows', v_rows);
end;
$$;


--
-- Name: admit_saved_search_digest(uuid, timestamp with time zone, bigint, integer, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_saved_search_digest(p_saved_search_id uuid, p_window_end timestamp with time zone, p_window_xact bigint, p_match_count integer, p_items jsonb, p_href text, p_expected_through timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search record;
  v_cursor record;
  v_today date := private.saved_search_digest_day(now());
  v_id uuid;
begin
  if p_window_end is null or p_window_end > now() then
    raise exception 'Invalid digest window' using errcode = '22023';
  end if;
  -- A window can't close on transactions that haven't finished yet.
  if p_window_xact is null or p_window_xact > private.snapshot_xmin() then
    raise exception 'Invalid digest window' using errcode = '22023';
  end if;
  if p_match_count is null or p_match_count < 0 then
    raise exception 'Invalid match count' using errcode = '22023';
  end if;

  -- The search row serialises admissions, the sweep and the alert trigger.
  select s.id, s.user_id, s.name, s.alert into v_search
  from public.saved_searches s where s.id = p_saved_search_id for update;
  if not found then return 'gone'; end if;
  if not v_search.alert then return 'alert_off'; end if;

  select c.checked_through, c.checked_xact into v_cursor
  from public.saved_search_email_cursors c where c.saved_search_id = p_saved_search_id for update;
  if not found then
    if p_expected_through is not null then return 'stale'; end if;
    insert into public.saved_search_email_cursors (saved_search_id, checked_through, checked_xact, activated_at)
    values (p_saved_search_id, p_window_end, p_window_xact, now());
    return 'baseline';
  end if;

  if p_expected_through is null or v_cursor.checked_through <> p_expected_through then return 'stale'; end if;
  if p_window_end <= v_cursor.checked_through or p_window_xact < v_cursor.checked_xact then return 'stale'; end if;
  if private.saved_search_digest_day(v_cursor.checked_through) >= v_today then return 'already_today'; end if;
  if exists (select 1 from public.saved_search_email_digests d
             where d.saved_search_id = p_saved_search_id and d.status in ('pending', 'sending') and d.digest_day < v_today) then
    return 'blocked';
  end if;

  if p_match_count > 0 and private.saved_search_emails_enabled(v_search.user_id) then
    insert into public.saved_search_email_digests
      (saved_search_id, digest_day, window_start, window_end, window_start_xact, window_end_xact,
       search_name, href, match_count, items)
    values
      (p_saved_search_id, v_today, greatest(v_cursor.checked_through, private.saved_search_digest_floor()), p_window_end,
       v_cursor.checked_xact, p_window_xact,
       v_search.name, p_href, p_match_count, p_items)
    on conflict (saved_search_id, digest_day) do nothing
    returning id into v_id;
    if v_id is null then return 'already_today'; end if;
  end if;

  update public.saved_search_email_cursors
     set checked_through = p_window_end, checked_xact = p_window_xact, updated_at = now()
   where saved_search_id = p_saved_search_id;

  return case when p_match_count = 0 then 'empty' when v_id is null then 'muted' else 'admitted' end;
end;
$$;


--
-- Name: advance_search_rebuild(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_search_rebuild(p_run uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare r public.search_rebuilds; target text; ids uuid[]; item uuid;
begin
 select * into r from public.search_rebuilds where id=p_run for update;
 if not found then raise exception 'Unknown rebuild'; end if;
 if r.status='completed' then return jsonb_build_object('completed',true,'queued',0); end if;
 target:=case r.entity when 'listing' then 'listings' when 'car' then 'cars' when 'profile' then 'profiles' when 'update' then 'activity_posts' end;
 execute format('select array_agg(id order by id) from (select id from public.%I where ($1 is null or id>$1) order by id limit 500) page',target) into ids using r.cursor;
 foreach item in array coalesce(ids,'{}'::uuid[]) loop
   insert into public.remediation_jobs(kind,dedup_key,payload) values('search','rebuild:'||r.id||':'||item,jsonb_build_object('entity',r.entity,'id',item)) on conflict(dedup_key) do nothing;
 end loop;
 update public.search_rebuilds set cursor=coalesce(ids[cardinality(ids)],cursor),status=case when coalesce(cardinality(ids),0)<500 then 'completed' else 'pending' end where id=p_run;
 return jsonb_build_object('completed',coalesce(cardinality(ids),0)<500,'queued',coalesce(cardinality(ids),0));
end $_$;


--
-- Name: agent_approval_decide(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_approval_decide(p_approval uuid, p_choice text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_approval public.agent_approvals;
  v_result jsonb;
  v_outcome text;
  v_status text;
  v_offer_status text;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_approval is null or p_choice is null or p_choice not in ('accept', 'dismiss') then
    raise exception 'Invalid choice' using errcode = '22023';
  end if;
  select * into v_approval from public.agent_approvals where id = p_approval and owner_id = v_actor;
  if not found then raise exception 'Not found' using errcode = 'P0002'; end if;

  -- Lock order: listing → offer → task → approval, as the outbox trigger takes them.
  perform 1 from public.listings l join public.offers o on o.listing_id = l.id where o.id = v_approval.offer_id for update of l;
  perform 1 from public.offers where id = v_approval.offer_id for update;
  perform 1 from public.agent_tasks where id = v_approval.task_id for update;
  select * into v_approval from public.agent_approvals where id = p_approval for update;

  if v_approval.status <> 'pending' then
    -- Already answered, or overtaken by the offer: say what it was, change nothing.
    return jsonb_build_object('approval_id', p_approval, 'status', v_approval.status, 'replayed', true,
      'outcome', case v_approval.status when 'approved' then 'accepted' when 'dismissed' then 'dismissed'
        when 'expired' then 'expired' when 'refused' then 'refused' else 'noop' end);
  end if;

  if p_choice = 'accept' then
    begin
      -- The owner accepts, as themself: the move is theirs, not the agent's.
      v_result := public.offer_move_core(v_actor, v_approval.offer_id, 'accept', null,
        'approval:' || p_approval, v_approval.round_no, null);
      v_outcome := case when v_result->>'kind' = 'accept' then 'accepted'
                        when v_result->>'outcome' = 'expired' then 'expired'
                        else 'refused' end;
    exception when sqlstate 'OF002' or sqlstate 'OF003' or sqlstate 'OF005' or sqlstate 'OF007' then
      -- The move is rolled back; the offer is as it was.
      select status into v_offer_status from public.offers where id = v_approval.offer_id;
      v_outcome := case when v_offer_status = 'expired' then 'expired' else 'refused' end;
      v_result := null;
    end;
    v_status := case v_outcome when 'accepted' then 'approved' else v_outcome end;
    -- Unconditional: the move's own round may already have superseded it.
    update public.agent_approvals set status = v_status, decided_at = now() where id = p_approval;
  else
    v_outcome := 'dismissed';
    v_status := 'dismissed';
    update public.agent_approvals set status = 'dismissed', decided_at = now() where id = p_approval;
  end if;

  if v_outcome in ('dismissed', 'refused') then
    -- No round was written, so the trigger didn't move the task: it waits again.
    update public.agent_tasks set status = 'waiting_for_event'
    where id = v_approval.task_id and status = 'needs_approval'
      and not exists (select 1 from public.agent_approvals a where a.task_id = v_approval.task_id and a.status = 'pending');
  end if;

  insert into public.agent_events(owner_id, task_id, kind, initiated_by, result)
  values (v_actor, v_approval.task_id, 'approval', 'owner',
    jsonb_build_object('approval_id', p_approval, 'choice', p_choice, 'outcome', v_outcome));
  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object('approval_id', p_approval, 'status', v_status,
    'outcome', v_outcome, 'replayed', false);
end;
$$;


--
-- Name: agent_audit_ids_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_audit_ids_valid(p_ids jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select jsonb_typeof(p_ids) = 'object' and not exists (
    select 1 from jsonb_each(p_ids) as kv(key, value)
    where kv.key <> all (public.agent_audit_vocabulary('id_key'))
       or not case jsonb_typeof(kv.value)
            when 'string' then (kv.value #>> '{}') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            when 'array' then not exists (select 1 from jsonb_array_elements(kv.value) e
                                          where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
            else false
          end);
$_$;


--
-- Name: agent_audit_vocabulary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_audit_vocabulary(p_list text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_list
    when 'tool' then array['search_parts', 'browse_marketplace', 'read_listing_messages', 'read_listing', 'read_my_car', 'read_product',
                           'fitment_evidence', 'price_comparables', 'list_my_cars', 'read_part_link', 'propose_build_change', 'draft_build_list',
                           'find_parts_to_list', 'draft_listing_from_photos', 'draft_car_update', 'move_offer', 'set_agent_limits', 'unknown_tool']
    when 'id_key' then array['listingId', 'carId', 'replacesModId', 'modId', 'modIds', 'offerId', 'proposalId']
    when 'code' then array['not_allowed', 'invalid_input', 'invalid_output', 'failed', 'stopped']
    when 'turn' then array['ok', 'ai_disabled', 'model_error', 'refused', 'incomplete', 'not_allowed', 'spend_cap', 'paused', 'suspended', 'timeout']
  end;
$$;


--
-- Name: agent_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid NOT NULL,
    kind text NOT NULL,
    expected_action text NOT NULL,
    listing_id uuid NOT NULL,
    offer_id uuid,
    round_no integer,
    dedup_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    lease_id uuid,
    lease_expires_at timestamp with time zone,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT agent_jobs_dedup_key_check CHECK (((length(dedup_key) >= 8) AND (length(dedup_key) <= 300))),
    CONSTRAINT agent_jobs_expected_action_check CHECK ((expected_action = ANY (ARRAY['offer_move'::text, 'offer_open'::text]))),
    CONSTRAINT agent_jobs_finished CHECK (((status = ANY (ARRAY['done'::text, 'failed'::text, 'cancelled'::text, 'dead'::text])) = (finished_at IS NOT NULL))),
    CONSTRAINT agent_jobs_kind_check CHECK ((kind = ANY (ARRAY['offer_turn'::text, 'offer_open'::text]))),
    CONSTRAINT agent_jobs_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 200))),
    CONSTRAINT agent_jobs_lease CHECK (((status = 'leased'::text) = ((lease_id IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT agent_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT agent_jobs_shape CHECK ((((kind = 'offer_turn'::text) AND (expected_action = 'offer_move'::text) AND (offer_id IS NOT NULL) AND (round_no IS NOT NULL)) OR ((kind = 'offer_open'::text) AND (expected_action = 'offer_open'::text) AND (offer_id IS NULL)))),
    CONSTRAINT agent_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'leased'::text, 'done'::text, 'failed'::text, 'cancelled'::text, 'dead'::text])))
);


--
-- Name: TABLE agent_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_jobs IS 'The agent outbox (20261021100000): written in the same transaction as the event, leased by agent_worker. Ids and states only; kept 30 days after it finishes.';


--
-- Name: listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seller_id uuid NOT NULL,
    source_car_id uuid,
    title text NOT NULL,
    description text,
    category text NOT NULL,
    subcategory text,
    condition text,
    price_cents integer NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    location text,
    compatibility_notes text,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    shipping_cents integer DEFAULT 0 NOT NULL,
    allows_collection boolean DEFAULT false NOT NULL,
    sold_at timestamp with time zone,
    reserved_until timestamp with time zone,
    part_number text,
    view_count integer DEFAULT 0 NOT NULL,
    removed_at timestamp with time zone,
    removed_reason text,
    grade text,
    condition_checklist jsonb,
    part_number_compact text GENERATED ALWAYS AS (NULLIF(regexp_replace(lower(COALESCE(part_number, ''::text)), '[^a-z0-9]'::text, ''::text, 'g'::text), ''::text)) STORED,
    shipping_mode text DEFAULT 'flat'::text NOT NULL,
    weight_oz numeric(8,2),
    length_in numeric(6,2),
    width_in numeric(6,2),
    height_in numeric(6,2),
    brand text,
    part_miles integer,
    part_miles_unit text,
    brand_key text GENERATED ALWAYS AS (lower(brand)) STORED,
    show_offer_floor boolean DEFAULT false NOT NULL,
    published_at timestamp with time zone,
    published_xact bigint,
    CONSTRAINT listings_catalog_assignment CHECK (((category = ANY (ARRAY['performance'::text, 'engine'::text, 'exterior-body'::text, 'interior-lighting'::text, 'brakes-suspension'::text, 'wheels-tires'::text])) AND ((subcategory IS NULL) OR ((category = 'performance'::text) AND (subcategory = ANY (ARRAY['exhaust'::text, 'intake'::text, 'turbo'::text, 'intercoolers'::text, 'tuning'::text, 'fueling'::text]))) OR ((category = 'engine'::text) AND (subcategory = ANY (ARRAY['internals'::text, 'drivetrain'::text, 'transmission'::text, 'engine-mounts'::text, 'maintenance'::text]))) OR ((category = 'exterior-body'::text) AND (subcategory = ANY (ARRAY['aero'::text, 'bumpers'::text, 'hoods'::text, 'spoilers'::text, 'mirrors-trim'::text]))) OR ((category = 'interior-lighting'::text) AND (subcategory = ANY (ARRAY['seats'::text, 'steering'::text, 'gauges'::text, 'headlights'::text, 'interior-trim'::text]))) OR ((category = 'brakes-suspension'::text) AND (subcategory = ANY (ARRAY['big-brake-kits'::text, 'pads-rotors'::text, 'coilovers'::text, 'sway-bars'::text, 'air-ride'::text]))) OR ((category = 'wheels-tires'::text) AND (subcategory = ANY (ARRAY['wheels'::text, 'tires'::text, 'spacers-hardware'::text, 'tpms'::text])))))),
    CONSTRAINT listings_condition_check CHECK ((condition = ANY (ARRAY['new'::text, 'like_new'::text, 'used'::text, 'for_parts'::text]))),
    CONSTRAINT listings_condition_checklist_shape CHECK (((condition_checklist IS NULL) OR (jsonb_typeof(condition_checklist) = 'object'::text))),
    CONSTRAINT listings_currency_usd CHECK ((currency = 'USD'::text)),
    CONSTRAINT listings_grade_check CHECK (((grade IS NULL) OR (grade = ANY (ARRAY['a'::text, 'b'::text, 'c'::text])))),
    CONSTRAINT listings_part_miles_check CHECK (((part_miles IS NULL) OR ((part_miles >= 0) AND (part_miles <= 2000000) AND (part_miles_unit = ANY (ARRAY['mi'::text, 'km'::text]))))),
    CONSTRAINT listings_price_ceiling CHECK ((price_cents <= 100000000)),
    CONSTRAINT listings_price_cents_check CHECK ((price_cents >= 0)),
    CONSTRAINT listings_shipping_bounds CHECK (((shipping_cents >= 0) AND (shipping_cents <= 10000000))),
    CONSTRAINT listings_shipping_mode_check CHECK ((shipping_mode = ANY (ARRAY['flat'::text, 'drvn'::text, 'pickup_only'::text]))),
    CONSTRAINT listings_shipping_mode_shape_check CHECK ((((shipping_mode <> 'drvn'::text) OR ((weight_oz > (0)::numeric) AND (length_in > (0)::numeric) AND (width_in > (0)::numeric) AND (height_in > (0)::numeric))) AND ((shipping_mode <> 'pickup_only'::text) OR (allows_collection AND (shipping_cents = 0))))),
    CONSTRAINT listings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'reserved'::text, 'paused'::text, 'sold'::text, 'archived'::text, 'removed'::text]))),
    CONSTRAINT listings_text_bounds CHECK (((char_length(title) BETWEEN 1 AND 140) AND (char_length(COALESCE(description, ''::text)) <= 8000) AND (char_length(COALESCE(compatibility_notes, ''::text)) <= 2000) AND (char_length(COALESCE(location, ''::text)) <= 120)))
)
WITH (fillfactor='90');


--
-- Name: COLUMN listings.part_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.part_number IS 'Manufacturer part number, seller-entered. Not verified by the platform.';


--
-- Name: COLUMN listings.view_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.view_count IS 'Public part-sheet loads, excluding the seller. Counts loads, not unique viewers.';


--
-- Name: COLUMN listings.brand; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.brand IS 'Who made the part. Prefilled from the mod or the importer, matched from the title otherwise, always editable.';


--
-- Name: COLUMN listings.part_miles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.part_miles IS 'How far this part has been driven (M-7). Optional, used parts only.';


--
-- Name: COLUMN listings.part_miles_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.part_miles_unit IS 'mi | km for part_miles. Required when part_miles is set.';


--
-- Name: COLUMN listings.show_offer_floor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listings.show_offer_floor IS 'The seller chose to show their offer minimum on the listing (O-3). The amount itself is in listing_private_terms.';


--
-- Name: offers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    buyer_id uuid NOT NULL,
    amount_cents integer NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    counter_amount_cents integer,
    countered_at timestamp with time zone,
    expires_at timestamp with time zone,
    responded_at timestamp with time zone,
    round_count integer DEFAULT 0 NOT NULL,
    last_round_id uuid,
    ended_reason text,
    CONSTRAINT offers_amount_ceiling CHECK ((amount_cents <= 100000000)),
    CONSTRAINT offers_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT offers_counter_bounds CHECK (((counter_amount_cents IS NULL) OR ((counter_amount_cents > 0) AND (counter_amount_cents <= 100000000)))),
    CONSTRAINT offers_ended_reason_check CHECK (((ended_reason IS NULL) OR ((ended_reason = 'listing_withdrawn'::text) AND (status = 'withdrawn'::text)))),
    CONSTRAINT offers_status_check CHECK ((status = ANY (ARRAY['open'::text, 'countered'::text, 'accepted'::text, 'declined'::text, 'withdrawn'::text, 'expired'::text])))
);


--
-- Name: COLUMN offers.ended_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.offers.ended_reason IS 'N77: why DRVN ended the offer rather than one of its parties. listing_withdrawn: the seller withdrew the listing.';


--
-- Name: agent_authority(public.agent_jobs, public.listings, public.offers); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_authority(p_job public.agent_jobs, p_listing public.listings, p_offer public.offers) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task public.agent_tasks;
  v_mandate public.agent_mandates;
  v_owner uuid;
  v_counterparty uuid;
  v_halt text;
begin
  select * into v_task from public.agent_tasks where id = p_job.task_id;
  -- AG-7 (R-agentmode): the owner's lock, shared, before the mandate. Saving
  -- Off or Suggest takes it exclusively, so it waits for a write already
  -- past this check, and a write after it sees the new mode.
  perform pg_advisory_xact_lock_shared(public.agent_member_lock_key(v_task.owner_id));
  if (select p.agent_mode from public.profiles p where p.id = v_task.owner_id) is distinct from 'act' then
    raise exception 'The owner set their agent below Act' using errcode = 'AG003';
  end if;
  select * into v_mandate from public.agent_mandates where id = v_task.mandate_id for share;
  select * into v_task from public.agent_tasks where id = p_job.task_id for update;
  if v_task.finished_at is not null or v_mandate.id is null or v_mandate.status <> 'active'
     or (v_mandate.expires_at is not null and v_mandate.expires_at <= now()) then
    raise exception 'The owner turned this off' using errcode = 'AG003';
  end if;
  v_owner := v_mandate.owner_id;
  if v_task.owner_id <> v_owner or v_task.scope <> v_mandate.scope or v_mandate.listing_id <> p_listing.id
     or p_job.listing_id <> p_listing.id
     or (v_mandate.scope = 'seller' and p_listing.seller_id <> v_owner)
     or (v_mandate.scope = 'buyer' and (p_listing.seller_id = v_owner or (p_offer.id is not null and p_offer.buyer_id <> v_owner))) then
    raise exception 'Not the owner''s side of this' using errcode = 'AG005';
  end if;
  if public.is_suspended(v_owner) then raise exception 'The owner''s account is suspended' using errcode = 'AG007'; end if;
  v_counterparty := case v_mandate.scope when 'seller' then p_offer.buyer_id else p_listing.seller_id end;
  v_halt := public.agent_halt_reason(v_mandate.scope, v_owner, v_mandate.id, p_listing.id, v_counterparty);
  if v_halt is not null then raise exception 'Agents are paused (%)', v_halt using errcode = 'AG004'; end if;
  return jsonb_build_object('owner_id', v_owner, 'task_id', v_task.id, 'mandate_id', v_mandate.id,
    'mandate_version', v_mandate.version, 'scope', v_mandate.scope, 'ceiling_cents', v_mandate.ceiling_cents,
    'ceiling_basis', v_mandate.ceiling_basis);
end;
$$;


--
-- Name: agent_chat_append(uuid, text, text, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_append(p_owner uuid, p_role text, p_body text, p_cards jsonb DEFAULT '[]'::jsonb, p_images text[] DEFAULT '{}'::text[]) RETURNS TABLE(id uuid, role text, body text, cards jsonb, images text[], created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_conversation uuid;
begin
  if p_owner is null or p_role not in ('member', 'agent') then
    raise exception 'invalid chat message' using errcode = '22023';
  end if;
  if p_role = 'member' and public.is_suspended(p_owner) then
    raise exception 'account is suspended' using errcode = '42501';
  end if;
  if p_cards is null or jsonb_typeof(p_cards) <> 'array' or jsonb_array_length(p_cards) > 5
     or exists (select 1 from jsonb_array_elements(p_cards) card where not public.agent_chat_card_ok(card))
     or (p_role = 'member' and jsonb_array_length(p_cards) > 0) then
    raise exception 'invalid chat cards' using errcode = '22023';
  end if;
  -- Photos: the member's own private chat uploads only, on their own
  -- message (R81, 20261107220300): never a public listing photo any more.
  if p_images is null or cardinality(p_images) > 4
     or (p_role = 'agent' and cardinality(p_images) > 0)
     or exists (select 1 from unnest(p_images) url
                 where url !~ ('^https?://[^/?#]+/storage/v1/object/authenticated/agent-chat-photos/' || p_owner::text
                               || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$')
                    or length(url) > 2000) then
    raise exception 'invalid chat photos' using errcode = '22023';
  end if;

  insert into public.agent_conversations as c (owner_id, last_message_at)
  values (p_owner, now())
  on conflict (owner_id) do update set last_message_at = now()
  returning c.id into v_conversation;

  return query
  insert into public.agent_messages as m (conversation_id, owner_id, role, body, cards, images)
  values (v_conversation, p_owner, p_role, p_body, p_cards, p_images)
  returning m.id, m.role, m.body, m.cards, m.images, m.created_at;
end;
$_$;


--
-- Name: agent_chat_card_ok(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_card_ok(p_card jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select case
    when jsonb_typeof(p_card) <> 'object' then false
    when p_card->>'kind' = 'listing' then
      (select count(*) from jsonb_object_keys(p_card)) = 2
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    when p_card->>'kind' = 'build_change' then
      not exists (
        select 1 from jsonb_object_keys(p_card) k
         where k not in ('kind', 'id', 'car', 'replaces', 'brand', 'product', 'part_number', 'category', 'product_url', 'image_url'))
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(p_card->>'car', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (p_card->'replaces' is null or jsonb_typeof(p_card->'replaces') = 'null'
           or coalesce(p_card->>'replaces', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
      and jsonb_typeof(p_card->'product') = 'string' and length(p_card->>'product') between 1 and 200
      and coalesce(jsonb_typeof(p_card->'brand'), 'null') in ('string', 'null') and coalesce(length(p_card->>'brand'), 0) <= 120
      and coalesce(jsonb_typeof(p_card->'part_number'), 'null') in ('string', 'null') and coalesce(length(p_card->>'part_number'), 0) <= 80
      and (coalesce(jsonb_typeof(p_card->'category'), 'null') = 'null'
           or p_card->>'category' in ('suspension', 'exhaust', 'intake', 'turbo', 'wheels', 'brakes', 'ecu-tune', 'aero-exterior', 'interior', 'drivetrain'))
      and (coalesce(jsonb_typeof(p_card->'product_url'), 'null') = 'null'
           or (jsonb_typeof(p_card->'product_url') = 'string' and length(p_card->>'product_url') <= 2000 and p_card->>'product_url' ~* '^https?://'))
      and (coalesce(jsonb_typeof(p_card->'image_url'), 'null') = 'null'
           or (jsonb_typeof(p_card->'image_url') = 'string' and length(p_card->>'image_url') <= 2000 and p_card->>'image_url' ~* '^https://'))
    when p_card->>'kind' = 'build_list' then
      not exists (select 1 from jsonb_object_keys(p_card) k where k not in ('kind', 'id', 'car', 'lines'))
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(p_card->>'car', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and jsonb_typeof(p_card->'lines') = 'array'
      and jsonb_array_length(p_card->'lines') between 1 and 40
      and not exists (
        select 1 from jsonb_array_elements(p_card->'lines') line
         where jsonb_typeof(line) <> 'object'
            or exists (select 1 from jsonb_object_keys(line) k where k not in ('id', 'group_label', 'brand', 'product', 'part_number', 'category', 'confidence'))
            or coalesce(line->>'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            or coalesce(line->>'group_label', '') not in ('Performance', 'Suspension', 'Exterior', 'Interior', 'Wheels & Tires', 'Other')
            or coalesce(jsonb_typeof(line->'brand'), 'null') not in ('string', 'null') or coalesce(length(line->>'brand'), 0) > 120
            or coalesce(jsonb_typeof(line->'product'), 'null') not in ('string', 'null') or coalesce(length(line->>'product'), 0) > 200
            or coalesce(line->>'brand', line->>'product') is null
            or coalesce(jsonb_typeof(line->'part_number'), 'null') not in ('string', 'null') or coalesce(length(line->>'part_number'), 0) > 80
            or (coalesce(jsonb_typeof(line->'category'), 'null') <> 'null' and line->>'category' not in ('suspension', 'exhaust', 'intake', 'turbo', 'wheels', 'brakes', 'ecu-tune', 'aero-exterior', 'interior', 'drivetrain'))
            or jsonb_typeof(line->'confidence') <> 'number' or (line->>'confidence')::numeric not between 0 and 1)
    when p_card->>'kind' = 'list_part' then
      (select count(*) from jsonb_object_keys(p_card)) = 3
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(p_card->>'car', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    when p_card->>'kind' = 'listing_draft' then
      not exists (select 1 from jsonb_object_keys(p_card) k where k not in ('kind', 'id', 'title', 'brand', 'part_number', 'category', 'images'))
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and jsonb_typeof(p_card->'title') = 'string' and length(p_card->>'title') between 1 and 140
      and coalesce(jsonb_typeof(p_card->'brand'), 'null') in ('string', 'null') and coalesce(length(p_card->>'brand'), 0) <= 80
      and coalesce(jsonb_typeof(p_card->'part_number'), 'null') in ('string', 'null') and coalesce(length(p_card->>'part_number'), 0) <= 80
      and (coalesce(jsonb_typeof(p_card->'category'), 'null') = 'null' or p_card->>'category' in ('suspension', 'exhaust', 'intake', 'turbo', 'wheels', 'brakes', 'ecu-tune', 'aero-exterior', 'interior', 'drivetrain'))
      and (jsonb_typeof(p_card->'images') = 'array' and jsonb_array_length(p_card->'images') between 1 and 4
           and not exists (select 1 from jsonb_array_elements(p_card->'images') img
                            where jsonb_typeof(img) <> 'string' or length(img #>> '{}') > 2000 or (img #>> '{}') !~* '^https?://'))
    when p_card->>'kind' = 'update_draft' then
      not exists (select 1 from jsonb_object_keys(p_card) k where k not in ('kind', 'id', 'car', 'title', 'body', 'images', 'mods'))
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(p_card->>'car', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and jsonb_typeof(p_card->'title') = 'string' and length(p_card->>'title') between 1 and 140
      and jsonb_typeof(p_card->'body') = 'string' and length(p_card->>'body') <= 2000
      and (jsonb_typeof(p_card->'images') = 'array' and jsonb_array_length(p_card->'images') between 1 and 4
           and not exists (select 1 from jsonb_array_elements(p_card->'images') img
                            where jsonb_typeof(img) <> 'string' or length(img #>> '{}') > 2000 or (img #>> '{}') !~* '^https?://'))
      and jsonb_typeof(p_card->'mods') = 'array' and jsonb_array_length(p_card->'mods') <= 5
      and not exists (select 1 from jsonb_array_elements(p_card->'mods') m where coalesce(m #>> '{}', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    when p_card->>'kind' = 'marketplace' then
      not exists (select 1 from jsonb_object_keys(p_card) k where k not in ('kind', 'id', 'query', 'href', 'count', 'capped'))
      and coalesce(p_card->>'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and jsonb_typeof(p_card->'query') = 'string' and length(p_card->>'query') between 1 and 200
      and jsonb_typeof(p_card->'href') = 'string' and length(p_card->>'href') <= 600
      and p_card->>'href' ~ '^/marketplace(/[a-z0-9-]+){0,2}(\?[^#]*)?$'
      and jsonb_typeof(p_card->'count') = 'number' and (p_card->>'count')::numeric between 0 and 1000
      and jsonb_typeof(p_card->'capped') = 'boolean'
    else false
  end;
$_$;


--
-- Name: agent_chat_message_json(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_message_json(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('id', m.id, 'role', m.role, 'body', m.body, 'cards', m.cards, 'images', m.images, 'created_at', m.created_at)
  from public.agent_messages m where m.id = p_id;
$$;


--
-- Name: agent_chat_photos_expired(interval, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_photos_expired(p_older_than interval DEFAULT NULL::interval, p_limit integer DEFAULT 500) RETURNS TABLE(name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select o.name
    from storage.objects o
   where o.bucket_id = 'agent-chat-photos'
     and o.created_at < now() - greatest(coalesce(p_older_than, private.agent_chat_photo_retention()), interval '1 hour')
     and not exists (select 1 from private.media_rewrite_claims r
                      where r.bucket = 'agent-chat-photos' and r.path = o.name
                        and r.claimed_at > now() - interval '10 minutes')
   order by o.created_at
   limit greatest(1, least(coalesce(p_limit, 500), 1000));
$$;


--
-- Name: agent_chat_turn_begin(uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_turn_begin(p_owner uuid, p_request uuid, p_body text, p_images text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.agent_chat_requests;
  v_member uuid;
begin
  if p_owner is null or p_request is null then
    raise exception 'invalid chat message' using errcode = '22023';
  end if;
  if public.is_suspended(p_owner) then
    raise exception 'account is suspended' using errcode = '42501';
  end if;
  -- AG-7 (R-agentmode): an agent set to Off answers nothing. Read under the
  -- member's lock, shared, before any chat row is touched (member → chat
  -- rows; agent_mode_set takes no chat lock). Waiting here is safe and short:
  -- a save in flight finishes, and this send then sees what it saved.
  perform pg_advisory_xact_lock_shared(public.agent_member_lock_key(p_owner));
  if (select p.agent_mode from public.profiles p where p.id = p_owner) is not distinct from 'off' then
    raise exception 'Your agent is off in Settings' using errcode = 'AG009';
  end if;
  delete from public.agent_chat_requests where created_at < now() - interval '7 days';

  insert into public.agent_chat_requests(owner_id, request_id) values (p_owner, p_request)
  on conflict (owner_id, request_id) do nothing;
  if not found then
    -- Seen before: wait for the first attempt's row, then replay it.
    select * into v_request from public.agent_chat_requests
    where owner_id = p_owner and request_id = p_request for update;
    return jsonb_build_object('replayed', true,
      'member', public.agent_chat_message_json(v_request.member_message_id),
      'reply', public.agent_chat_message_json(v_request.reply_message_id));
  end if;

  select a.id into v_member from public.agent_chat_append(p_owner, 'member', p_body, '[]'::jsonb, coalesce(p_images, '{}'::text[])) a;
  update public.agent_chat_requests set member_message_id = v_member where owner_id = p_owner and request_id = p_request;
  return jsonb_build_object('replayed', false, 'member', public.agent_chat_message_json(v_member), 'reply', null);
end;
$$;


--
-- Name: agent_chat_turn_finish(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_turn_finish(p_owner uuid, p_request uuid, p_body text, p_cards jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.agent_chat_requests;
  v_reply uuid;
begin
  select * into v_request from public.agent_chat_requests
  where owner_id = p_owner and request_id = p_request for update;
  if not found or v_request.member_message_id is null then
    raise exception 'No such chat request' using errcode = 'P0002';
  end if;
  if v_request.reply_message_id is not null then
    return public.agent_chat_message_json(v_request.reply_message_id);
  end if;
  select a.id into v_reply from public.agent_chat_append(p_owner, 'agent', p_body, coalesce(p_cards, '[]'::jsonb), '{}'::text[]) a;
  update public.agent_chat_requests set reply_message_id = v_reply where owner_id = p_owner and request_id = p_request;
  return public.agent_chat_message_json(v_reply);
end;
$$;


--
-- Name: agent_chat_turn_status(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_chat_turn_status(p_owner uuid, p_request uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select jsonb_build_object('found', true,
              'member', public.agent_chat_message_json(r.member_message_id),
              'reply', public.agent_chat_message_json(r.reply_message_id))
       from public.agent_chat_requests r
      where r.owner_id = p_owner and r.request_id = p_request),
    jsonb_build_object('found', false, 'member', null, 'reply', null));
$$;


--
-- Name: agent_claim_jobs(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_claim_jobs(p_limit integer DEFAULT 5, p_lease_seconds integer DEFAULT 60) RETURNS TABLE(job_id uuid, lease_id uuid, task_id uuid, kind text, expected_action text, listing_id uuid, offer_id uuid, round_no integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_job public.agent_jobs;
  v_task public.agent_tasks;
  v_mandate public.agent_mandates;
  v_seller uuid;
  v_buyer uuid;
  v_lease uuid;
  v_taken integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 50 or p_lease_seconds is null or p_lease_seconds not between 10 and 600 then
    raise exception 'Invalid claim' using errcode = '22023';
  end if;

  -- Jobs that kept losing their lease stop retrying.
  with dead as (
    update public.agent_jobs j set status = 'dead', lease_id = null, lease_expires_at = null, finished_at = now(),
      last_error = coalesce(j.last_error, 'lease lost too often')
    where j.status = 'leased' and j.lease_expires_at < now() and j.attempts >= j.max_attempts
    returning j.id, j.task_id
  )
  insert into public.agent_telemetry(kind, task_id, job_id, owner_id)
  select 'job_dead', d.task_id, d.id, t.owner_id from dead d join public.agent_tasks t on t.id = d.task_id;

  for v_job in
    select * from public.agent_jobs j
    where (j.status = 'pending' and j.available_at <= now())
       or (j.status = 'leased' and j.lease_expires_at < now() and j.attempts < j.max_attempts)
    order by j.available_at, j.id
    limit p_limit * 4
    for update skip locked
  loop
    exit when v_taken >= p_limit;
    select * into v_task from public.agent_tasks where id = v_job.task_id;
    select * into v_mandate from public.agent_mandates where id = v_task.mandate_id;
    if v_task.finished_at is not null or v_mandate.id is null or v_mandate.status in ('revoked', 'ended')
       or (v_mandate.expires_at is not null and v_mandate.expires_at <= now()) then
      update public.agent_jobs set status = 'cancelled', lease_id = null, lease_expires_at = null, finished_at = now(),
        last_error = 'task or mandate ended'
      where id = v_job.id;
      continue;
    end if;
    -- AG-7 (R-agentmode): read the owner's mode under their lock, shared,
    -- after the job's (job → member, as the lock order says). A save in
    -- flight holds it exclusively: try, and if it is held, step the job back
    -- a minute rather than hold up the whole claim.
    if not pg_try_advisory_xact_lock_shared(public.agent_member_lock_key(v_mandate.owner_id)) then
      update public.agent_jobs set available_at = now() + interval '1 minute' where id = v_job.id;
      continue;
    end if;
    -- Below Act: saving that revoked their mandates; a job that outlived it
    -- has nothing to do.
    if (select p.agent_mode from public.profiles p where p.id = v_mandate.owner_id) is distinct from 'act' then
      update public.agent_jobs set status = 'cancelled', lease_id = null, lease_expires_at = null, finished_at = now(),
        last_error = 'agent set below act'
      where id = v_job.id;
      continue;
    end if;
    -- Paused or switched off: leave it queued, but behind everyone else's.
    if v_mandate.status = 'paused' then
      update public.agent_jobs set available_at = now() + interval '1 minute' where id = v_job.id;
      continue;
    end if;
    select l.seller_id into v_seller from public.listings l where l.id = v_job.listing_id;
    select o.buyer_id into v_buyer from public.offers o where o.id = v_job.offer_id;
    if public.agent_halt_reason(v_mandate.scope, v_mandate.owner_id, v_mandate.id, v_job.listing_id,
         case v_mandate.scope when 'seller' then v_buyer else v_seller end) is not null then
      update public.agent_jobs set available_at = now() + interval '1 minute' where id = v_job.id;
      continue;
    end if;
    v_lease := gen_random_uuid();
    update public.agent_jobs set status = 'leased', lease_id = v_lease,
      lease_expires_at = now() + make_interval(secs => p_lease_seconds), attempts = attempts + 1
    where id = v_job.id;
    v_taken := v_taken + 1;
    job_id := v_job.id; lease_id := v_lease; task_id := v_job.task_id; kind := v_job.kind;
    expected_action := v_job.expected_action; listing_id := v_job.listing_id; offer_id := v_job.offer_id; round_no := v_job.round_no;
    return next;
  end loop;
end;
$$;


--
-- Name: agent_clear_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_clear_conversation() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  delete from public.agent_conversations where owner_id = auth.uid();
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: agent_compute_metrics(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_compute_metrics(p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_from timestamptz := p_day::timestamp at time zone 'utc';
  v_to timestamptz := (p_day + 1)::timestamp at time zone 'utc';
  v_rows integer := 0;
begin
  if p_day is null then raise exception 'A day is required' using errcode = '22023'; end if;

  create temporary table if not exists pg_temp.agent_measure(scope text, measure text, value numeric, sample integer) on commit drop;
  truncate pg_temp.agent_measure;

  -- Offers made that day on listings the seller's agent was handling.
  with agent_offers as (
    select o.id, o.status, o.listing_id,
      exists (select 1 from public.offer_rounds r where r.offer_id = o.id and r.actor_role = 'seller'
              and r.actor_task_id is null and r.kind in ('counter', 'decline')) as seller_stepped_in
    from public.offers o
    where o.created_at >= v_from and o.created_at < v_to
      and exists (select 1 from public.agent_mandates m where m.listing_id = o.listing_id and m.scope = 'seller'
                  and m.created_at <= o.created_at and (m.ended_at is null or m.ended_at > o.created_at))
  )
  insert into pg_temp.agent_measure
  select 'seller', 'offers_handled', count(*), count(*) from agent_offers
  union all
  select 'seller', 'share_without_seller_action', avg(case when seller_stepped_in then 0 else 1 end), count(*) from agent_offers;

  -- Agent-reached seller deals that day, how they ended, and where they landed.
  with deals as (
    select ord.id, ord.status, ord.subtotal_cents, l.price_cents, m.minimum_cents
    from public.orders ord
    join public.offers o on o.id = ord.origin_offer_id
    join public.listings l on l.id = o.listing_id
    left join lateral (select m.minimum_cents from public.agent_mandates m where m.listing_id = o.listing_id and m.scope = 'seller'
                       order by m.created_at desc limit 1) m on true
    where ord.created_at >= v_from and ord.created_at < v_to
      and exists (select 1 from public.offer_rounds r where r.offer_id = o.id and r.actor_role = 'seller' and r.actor_task_id is not null)
  )
  insert into pg_temp.agent_measure
  select 'seller', 'agent_deals', count(*), count(*) from deals
  union all
  select 'seller', 'agent_deal_cancel_rate', avg(case when status = 'cancelled' then 1 else 0 end), count(*) from deals
  union all
  select 'seller', 'agent_deal_paid_rate', avg(case when status in ('paid', 'shipped', 'delivered', 'completed') then 1 else 0 end), count(*) from deals
  union all
  -- 0 = at the minimum, 1 = at asking.
  select 'seller', 'price_position', avg(case when price_cents > minimum_cents then (subtotal_cents - minimum_cents)::numeric / (price_cents - minimum_cents) end),
    count(*) filter (where price_cents > minimum_cents) from deals;

  -- Approvals answered, and how fast.
  with asked as (
    select a.status, a.created_at, a.decided_at, t.scope from public.agent_approvals a join public.agent_tasks t on t.id = a.task_id
    where a.created_at >= v_from and a.created_at < v_to
  )
  insert into pg_temp.agent_measure
  select scope, 'approvals', count(*), count(*) from asked group by scope
  union all
  select scope, 'approvals_answered', avg(case when status in ('approved', 'dismissed', 'expired', 'refused') then 1 else 0 end), count(*) from asked group by scope
  union all
  select scope, 'minutes_to_answer', percentile_cont(0.5) within group (order by extract(epoch from decided_at - created_at) / 60),
    count(*) filter (where decided_at is not null) from asked where decided_at is not null group by scope;

  -- Buyers who handed a negotiation to the agent, and its deals.
  insert into pg_temp.agent_measure
  select 'buyer', 'negotiations_started', count(*), count(*) from public.agent_mandates
  where scope = 'buyer' and created_at >= v_from and created_at < v_to;
  insert into pg_temp.agent_measure
  select 'buyer', 'agent_accepts', count(*), count(*) from public.offer_rounds
  where kind = 'accept' and actor_role = 'buyer' and actor_task_id is not null and created_at >= v_from and created_at < v_to;

  -- Signs of an incorrect action: each a count, not a judgement.
  insert into pg_temp.agent_measure
  select 'all', 'permission_denials', count(*), count(*) from public.agent_telemetry
  where kind = 'permission_denied' and created_at >= v_from and created_at < v_to;
  insert into pg_temp.agent_measure
  select 'all', 'approvals_dismissed', count(*), count(*) from public.agent_approvals
  where status = 'dismissed' and decided_at >= v_from and decided_at < v_to;
  insert into pg_temp.agent_measure
  select 'seller', 'turned_off_after_a_move', count(*), count(*) from public.agent_mandates m
  where m.status = 'revoked' and m.ended_at >= v_from and m.ended_at < v_to
    and exists (select 1 from public.agent_events e where e.mandate_id = m.id and e.kind = 'move'
                and e.created_at > m.ended_at - interval '1 day' and e.created_at <= m.ended_at);

  -- What the model cost, and per finished task.
  insert into pg_temp.agent_measure
  select 'all', 'model_cost_usd', coalesce(sum(cost_usd), 0), count(*) from public.agent_usage where created_at >= v_from and created_at < v_to;
  insert into pg_temp.agent_measure
  select 'all', 'cost_per_completed_task_usd',
    (select coalesce(sum(cost_usd), 0) from public.agent_usage where created_at >= v_from and created_at < v_to)
      / nullif(count(*), 0), count(*)
  from public.agent_tasks where status = 'completed' and finished_at >= v_from and finished_at < v_to;

  -- Repeat use: members whose agent did something that day and had done something before.
  with active as (
    select distinct t.owner_id from public.agent_tasks t where t.updated_at >= v_from and t.updated_at < v_to
  )
  insert into pg_temp.agent_measure
  select 'all', 'active_members', count(*), count(*) from active
  union all
  select 'all', 'repeat_share', avg(case when exists (select 1 from public.agent_tasks p where p.owner_id = a.owner_id and p.created_at < v_from) then 1 else 0 end), count(*)
  from active a;

  insert into public.agent_metrics_daily(day, scope, measure, value, sample, computed_at)
  select p_day, scope, measure, case when sample < 5 then null else round(value, 4) end, coalesce(sample, 0), now()
  from pg_temp.agent_measure where scope is not null
  on conflict (day, scope, measure) do update set value = excluded.value, sample = excluded.sample, computed_at = excluded.computed_at;
  get diagnostics v_rows = row_count;
  return v_rows;
end;
$$;


--
-- Name: agent_controls_lock_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_controls_lock_key() RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select hashtextextended('drvn.agent_controls', 0);
$$;


--
-- Name: agent_enqueue_turns(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_enqueue_turns(p_task uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task public.agent_tasks;
  v_mandate public.agent_mandates;
  v_listing public.listings;
  v_used integer;
  v_added integer := 0;
  v_n integer;
begin
  select * into v_task from public.agent_tasks where id = p_task;
  if not found or v_task.finished_at is not null then return 0; end if;
  select * into v_mandate from public.agent_mandates where id = v_task.mandate_id;
  if not found or v_mandate.status <> 'active' then return 0; end if;
  select * into v_listing from public.listings where id = v_mandate.listing_id;
  if not found or v_listing.status <> 'active' then return 0; end if;

  if v_mandate.scope = 'seller' then
    insert into public.agent_jobs(task_id, kind, expected_action, listing_id, offer_id, round_no, dedup_key)
    select v_task.id, 'offer_turn', 'offer_move', o.listing_id, o.id, o.round_count,
           'turn:' || o.id || ':r' || o.round_count || ':' || v_task.id
    from public.offers o
    where o.listing_id = v_listing.id and o.status = 'open' and o.round_count > 0
      and v_listing.seller_id = v_mandate.owner_id
    on conflict (dedup_key) do nothing;
    get diagnostics v_n = row_count;
    v_added := v_added + v_n;
  else
    insert into public.agent_jobs(task_id, kind, expected_action, listing_id, offer_id, round_no, dedup_key)
    select v_task.id, 'offer_turn', 'offer_move', o.listing_id, o.id, o.round_count,
           'turn:' || o.id || ':r' || o.round_count || ':' || v_task.id
    from public.offers o
    where o.listing_id = v_listing.id and o.buyer_id = v_mandate.owner_id and o.status = 'countered'
    on conflict (dedup_key) do nothing;
    get diagnostics v_n = row_count;
    v_added := v_added + v_n;
    if not exists (select 1 from public.offers o where o.listing_id = v_listing.id and o.buyer_id = v_mandate.owner_id
                   and o.status in ('open', 'countered')) then
      select count(*) into v_used from public.offer_rounds r
      where r.listing_id = v_listing.id and r.buyer_id = v_mandate.owner_id and r.actor_role = 'buyer'
        and r.kind in ('offer', 'counter', 'below_minimum');
      if v_used < 3 and not exists (select 1 from public.offers o where o.listing_id = v_listing.id
                                    and o.buyer_id = v_mandate.owner_id and o.status = 'accepted') then
        insert into public.agent_jobs(task_id, kind, expected_action, listing_id, dedup_key)
        values (v_task.id, 'offer_open', 'offer_open', v_listing.id, 'open:' || v_task.id || ':n' || v_used)
        on conflict (dedup_key) do nothing;
        get diagnostics v_n = row_count;
        v_added := v_added + v_n;
      end if;
    end if;
  end if;
  return v_added;
end;
$$;


--
-- Name: agent_finish_job(uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_finish_job(p_job uuid, p_lease uuid, p_outcome text, p_code text DEFAULT NULL::text, p_end_task boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.agent_jobs;
  v_owner uuid;
begin
  if p_outcome is null or p_outcome not in ('retry', 'failed', 'cancelled') or (p_code is not null and length(p_code) > 40)
     or p_end_task is null then
    raise exception 'Invalid finish' using errcode = '22023';
  end if;
  select * into v_job from public.agent_jobs where id = p_job;
  if not found then return false; end if;
  -- Lock order: listing → offer → job → task.
  perform 1 from public.listings where id = v_job.listing_id for update;
  perform 1 from public.offers where id = v_job.offer_id for update;
  select * into v_job from public.agent_jobs where id = p_job for update;
  if v_job.status <> 'leased' or v_job.lease_id is distinct from p_lease then
    return false;
  end if;
  select t.owner_id into v_owner from public.agent_tasks t where t.id = v_job.task_id;
  if p_outcome = 'retry' and v_job.attempts < v_job.max_attempts then
    update public.agent_jobs set status = 'pending', lease_id = null, lease_expires_at = null, last_error = p_code,
      available_at = now() + make_interval(secs => least(30 * power(2, v_job.attempts), 1800))
    where id = v_job.id;
  else
    update public.agent_jobs set status = case p_outcome when 'cancelled' then 'cancelled' else 'failed' end,
      lease_id = null, lease_expires_at = null, finished_at = now(), last_error = p_code
    where id = v_job.id;
  end if;
  if p_code is not null then
    insert into public.agent_telemetry(kind, code, task_id, job_id, owner_id)
    values (case when p_code like 'AG%' or p_code = '42501' then 'permission_denied'
                 when p_code like 'model%' then 'model_error' else 'job_failed' end,
            p_code, v_job.task_id, v_job.id, v_owner);
  end if;
  if p_end_task and p_outcome <> 'retry' then
    update public.agent_tasks set status = 'failed', outcome = left(coalesce(p_code, 'failed'), 200)
    where id = v_job.task_id and finished_at is null
      and not exists (select 1 from public.agent_jobs j where j.task_id = v_job.task_id and j.status in ('pending', 'leased'));
  end if;
  return true;
end;
$$;


--
-- Name: agent_halt_reason(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_halt_reason(p_scope text, p_owner uuid, p_mandate uuid, p_listing uuid, p_counterparty uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform pg_advisory_xact_lock_shared(public.agent_controls_lock_key());
  return (select c.scope from public.agent_controls c
  where c.cleared_at is null
    and (c.scope = 'all'
      or (c.scope = p_scope and c.subject_id is null)
      or (c.scope = 'member' and c.subject_id = p_owner)
      or (c.scope = 'mandate' and c.subject_id = p_mandate)
      or (c.scope = 'listing' and c.subject_id = p_listing)
      or (c.scope = 'account' and c.subject_id in (p_owner, p_counterparty)))
  order by case c.scope when 'all' then 1 when 'buyer' then 2 when 'seller' then 2 when 'account' then 3
    when 'member' then 4 when 'listing' then 5 else 6 end
  limit 1);
end;
$$;


--
-- Name: agent_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_health() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'stuck_tasks', (select count(*) from public.agent_tasks t
      where t.finished_at is null and t.status = 'working' and t.updated_at < now() - interval '15 minutes'
        and not exists (select 1 from public.agent_jobs j where j.task_id = t.id and j.status in ('pending', 'leased'))),
    'stale_jobs', (select count(*) from public.agent_jobs j
      where (j.status = 'pending' and j.available_at < now() - interval '10 minutes')
         or (j.status = 'leased' and j.lease_expires_at < now() - interval '5 minutes')),
    'repeated_decisions', (select count(*) from (
      select e.task_id from public.agent_events e
      where e.kind in ('decision', 'move', 'approval') and e.created_at > now() - interval '1 hour' and e.job_id is not null
      group by e.task_id, e.initiated_by having count(*) > 2) x),
    'permission_denied_1h', (select count(*) from public.agent_telemetry where kind = 'permission_denied' and created_at > now() - interval '1 hour'),
    'model_errors_1h', (select count(*) from public.agent_telemetry where kind = 'model_error' and created_at > now() - interval '1 hour'),
    'dead_jobs_24h', (select count(*) from public.agent_jobs where status = 'dead' and finished_at > now() - interval '24 hours'),
    'controls_on', (select coalesce(jsonb_agg(c.scope order by c.set_at), '[]'::jsonb) from public.agent_controls c where c.cleared_at is null)
  );
$$;


--
-- Name: agent_job_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_job_context(p_job uuid, p_lease uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.agent_jobs;
  v_task public.agent_tasks;
  v_mandate public.agent_mandates;
  v_listing public.listings;
  v_offer public.offers;
  v_owner uuid;
  v_buyer uuid;
begin
  v_job := public.agent_lock_job(p_job, p_lease, null);
  select * into v_task from public.agent_tasks where id = v_job.task_id;
  select * into v_mandate from public.agent_mandates where id = v_task.mandate_id;
  select * into v_listing from public.listings where id = v_job.listing_id;
  select * into v_offer from public.offers where id = v_job.offer_id;
  v_owner := v_mandate.owner_id;
  v_buyer := coalesce(v_offer.buyer_id, case when v_mandate.scope = 'buyer' then v_owner end);
  return jsonb_build_object(
    'job', jsonb_build_object('id', v_job.id, 'kind', v_job.kind, 'expected_action', v_job.expected_action,
      'offer_id', v_job.offer_id, 'round_no', v_job.round_no),
    'task', jsonb_build_object('id', v_task.id, 'scope', v_task.scope, 'status', v_task.status),
    'mandate', jsonb_build_object('id', v_mandate.id, 'version', v_mandate.version, 'status', v_mandate.status,
      'style', v_mandate.style, 'target_cents', v_mandate.target_cents,
      'ceiling_cents', case when v_mandate.scope = 'buyer' then v_mandate.ceiling_cents end,
      'ceiling_basis', case when v_mandate.scope = 'buyer' then v_mandate.ceiling_basis end),
    'effective_floor_cents', case when v_mandate.scope = 'seller' and v_listing.seller_id = v_owner
      then public.offer_effective_floor(v_listing.id) end,
    'listing', jsonb_build_object('id', v_listing.id, 'status', v_listing.status, 'price_cents', v_listing.price_cents,
      'shipping_cents', v_listing.shipping_cents, 'shipping_mode', v_listing.shipping_mode),
    'offer', case when v_offer.id is null then null else jsonb_build_object('id', v_offer.id, 'status', v_offer.status,
      'amount_cents', v_offer.amount_cents, 'counter_amount_cents', v_offer.counter_amount_cents,
      'round_count', v_offer.round_count, 'expires_at', v_offer.expires_at) end,
    'rounds', coalesce((select jsonb_agg(jsonb_build_object('round_no', r.round_no, 'actor_role', r.actor_role, 'kind', r.kind,
        'amount_cents', r.amount_cents, 'by_agent', r.actor_task_id is not null) order by r.round_no)
      from public.offer_rounds r where r.offer_id = v_offer.id), '[]'::jsonb),
    'buyer_amounts', coalesce((select jsonb_agg(r.amount_cents order by r.created_at)
      from public.offer_rounds r where r.listing_id = v_listing.id and r.buyer_id = v_buyer and r.actor_role = 'buyer'
        and r.kind in ('offer', 'counter', 'below_minimum')), '[]'::jsonb),
    'halted', public.agent_halt_reason(v_mandate.scope, v_owner, v_mandate.id, v_listing.id,
      case v_mandate.scope when 'seller' then v_offer.buyer_id else v_listing.seller_id end)
  );
end;
$$;


--
-- Name: agent_lock_job(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_lock_job(p_job uuid, p_lease uuid, p_action text) RETURNS public.agent_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.agent_jobs;
begin
  select * into v_job from public.agent_jobs where id = p_job for update;
  if not found or v_job.status <> 'leased' or v_job.lease_id is distinct from p_lease or v_job.lease_expires_at <= now() then
    raise exception 'This job is not leased to you' using errcode = 'AG001';
  end if;
  if p_action is not null and v_job.expected_action <> p_action then
    raise exception 'This job is for another action' using errcode = 'AG002';
  end if;
  return v_job;
end;
$$;


--
-- Name: agent_luhn(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_luhn(p_digits text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_sum integer := 0;
  v_digit integer;
  v_double boolean := false;
  i integer;
begin
  if p_digits is null or p_digits !~ '^[0-9]+$' then return false; end if;
  for i in reverse length(p_digits)..1 loop
    v_digit := substr(p_digits, i, 1)::integer;
    if v_double then
      v_digit := v_digit * 2;
      if v_digit > 9 then v_digit := v_digit - 9; end if;
    end if;
    v_sum := v_sum + v_digit;
    v_double := not v_double;
  end loop;
  return v_sum % 10 = 0;
end;
$_$;


--
-- Name: agent_mandate_set(text, uuid, integer, integer, integer, text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_mandate_set(p_scope text, p_listing uuid, p_minimum_cents integer DEFAULT NULL::integer, p_target_cents integer DEFAULT NULL::integer, p_ceiling_cents integer DEFAULT NULL::integer, p_ceiling_basis text DEFAULT NULL::text, p_style text DEFAULT 'balanced'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_acknowledge_binding boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_listing public.listings;
  v_mandate public.agent_mandates;
  v_task uuid;
  v_floor integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if public.is_suspended(v_actor) then raise exception 'account is suspended' using errcode = '42501'; end if;
  if p_scope is null or p_scope not in ('seller', 'buyer') or p_style is null or p_style not in ('firm', 'balanced', 'flexible')
     or p_listing is null or p_acknowledge_binding is null or (p_expires_at is not null and p_expires_at <= now()) then
    raise exception 'Invalid agent limits' using errcode = '22023';
  end if;
  -- The step opens from /admin/agent (20261024100000); until it does, no
  -- member can set this side's limits, whatever client they use.
  if not exists (select 1 from public.agent_beta_steps s where s.step = p_scope and s.open) then
    raise exception 'That part of the agent isn''t open yet' using errcode = '42501';
  end if;
  -- Lock order: the listing first, like every move on it.
  select * into v_listing from public.listings where id = p_listing for update;
  if not found or v_listing.status <> 'active' then raise exception 'Listing is not available' using errcode = 'OF007'; end if;
  -- AG-7 (R-agentmode): a mandate starts or changes only under Act within
  -- my limits, read under the member's lock (after the listing), so a save
  -- to Off or Suggest in another tab either waits for this or is waited for.
  perform pg_advisory_xact_lock_shared(public.agent_member_lock_key(v_actor));
  if (select p.agent_mode from public.profiles p where p.id = v_actor) is distinct from 'act' then
    raise exception 'Your agent is set to Off or Suggest in Settings' using errcode = 'AG009';
  end if;
  if v_listing.shipping_mode = 'drvn' then raise exception 'Offers are unavailable with rated shipping' using errcode = 'OF007'; end if;

  if p_scope = 'seller' then
    if v_listing.seller_id <> v_actor then raise exception 'Not your listing' using errcode = '42501'; end if;
    if p_ceiling_cents is not null or p_ceiling_basis is not null then raise exception 'Invalid agent limits' using errcode = '22023'; end if;
    if p_minimum_cents is not null and (p_minimum_cents <= 0 or p_minimum_cents > v_listing.price_cents) then
      raise exception 'Your agent''s minimum must be between $0 and the asking price' using errcode = 'OF004';
    end if;
    if p_target_cents is not null and (p_target_cents > v_listing.price_cents
       or p_target_cents < coalesce(p_minimum_cents, 1)) then
      raise exception 'Your target must be between your minimum and the asking price' using errcode = 'OF004';
    end if;
    select greatest(t.offer_floor_cents, p_minimum_cents) into v_floor from public.listing_private_terms t where t.listing_id = p_listing;
    v_floor := coalesce(v_floor, p_minimum_cents);
    if v_floor is null then raise exception 'Set a minimum before your agent handles offers' using errcode = 'OF004'; end if;
  else
    if v_listing.seller_id = v_actor then raise exception 'You can''t offer on your own listing' using errcode = '42501'; end if;
    if p_minimum_cents is not null or p_ceiling_cents is null or p_ceiling_cents <= 0 or p_ceiling_cents > 100000000
       or p_ceiling_basis is null or p_ceiling_basis not in ('item', 'total') or (p_target_cents is not null and p_target_cents > p_ceiling_cents) then
      raise exception 'Invalid agent limits' using errcode = '22023';
    end if;
    -- "Total up to" only where the total is knowable.
    if p_ceiling_basis = 'total' and v_listing.shipping_mode <> 'flat' then
      raise exception 'A total ceiling needs a fixed shipping price' using errcode = '22023';
    end if;
  end if;

  select * into v_mandate from public.agent_mandates
  where owner_id = v_actor and scope = p_scope and listing_id = p_listing and status in ('active', 'paused') for update;
  if found then
    if p_scope = 'seller' and v_mandate.binding_acknowledged_at is null and not p_acknowledge_binding then
      raise exception 'Confirm that your agent''s counters are binding' using errcode = '22023';
    end if;
    update public.agent_mandates set version = version + 1, minimum_cents = p_minimum_cents, target_cents = p_target_cents,
      ceiling_cents = p_ceiling_cents, ceiling_basis = p_ceiling_basis, style = p_style, expires_at = p_expires_at,
      updated_at = now()
    where id = v_mandate.id;
  else
    if p_scope = 'seller' and not p_acknowledge_binding then
      raise exception 'Confirm that your agent''s counters are binding' using errcode = '22023';
    end if;
    insert into public.agent_mandates(owner_id, scope, listing_id, minimum_cents, target_cents, ceiling_cents, ceiling_basis,
      style, expires_at, binding_acknowledged_at)
    values (v_actor, p_scope, p_listing, p_minimum_cents, p_target_cents, p_ceiling_cents, p_ceiling_basis,
      p_style, p_expires_at, case when p_scope = 'seller' then now() end)
    returning * into v_mandate;
  end if;

  v_task := public.agent_open_task(v_mandate.id);
  insert into public.agent_events(owner_id, task_id, mandate_id, mandate_version, kind, initiated_by, result)
  select v_actor, v_task, m.id, m.version, 'status', 'mandate_set', jsonb_build_object('mandate_status', m.status)
  from public.agent_mandates m where m.id = v_mandate.id;
  if public.agent_enqueue_turns(v_task) > 0 then
    update public.agent_tasks set status = 'working' where id = v_task and status = 'waiting_for_event';
  end if;
  return v_mandate.id;
end;
$_$;


--
-- Name: agent_mandate_set_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_mandate_set_status(p_mandate uuid, p_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_mandate public.agent_mandates;
  v_task uuid;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_mandate is null or p_status is null or p_status not in ('active', 'paused', 'revoked') then
    raise exception 'Invalid status' using errcode = '22023';
  end if;
  select * into v_mandate from public.agent_mandates where id = p_mandate and owner_id = v_actor;
  if not found then raise exception 'Not found' using errcode = 'P0002'; end if;
  -- Lock order: listing, then the member (AG-7), then the mandate and its task.
  perform 1 from public.listings where id = v_mandate.listing_id for update;
  perform pg_advisory_xact_lock_shared(public.agent_member_lock_key(v_actor));
  select * into v_mandate from public.agent_mandates where id = p_mandate for update;
  if v_mandate.status = p_status then return p_status; end if;
  if v_mandate.status in ('revoked', 'ended') then raise exception 'This mandate has ended' using errcode = '22023'; end if;
  if p_status = 'active' and public.is_suspended(v_actor) then raise exception 'account is suspended' using errcode = '42501'; end if;
  -- AG-7 (R-agentmode): resuming is starting again; only under Act.
  if p_status = 'active' and (select p.agent_mode from public.profiles p where p.id = v_actor) is distinct from 'act' then
    raise exception 'Your agent is set to Off or Suggest in Settings' using errcode = 'AG009';
  end if;
  update public.agent_mandates set status = p_status, updated_at = now(),
    ended_at = case when p_status = 'revoked' then now() end
  where id = p_mandate;
  if p_status = 'active' then
    -- Resuming after the task ended (a failed offer while paused) opens a new one.
    v_task := public.agent_open_task(p_mandate);
    perform public.agent_enqueue_turns(v_task);
  else
    select id into v_task from public.agent_tasks where mandate_id = p_mandate and finished_at is null for update;
  end if;
  if v_task is not null then
    if p_status = 'revoked' then
      update public.agent_tasks set status = 'cancelled', outcome = 'turned off by owner' where id = v_task and finished_at is null;
      update public.agent_approvals set status = 'dismissed', decided_at = now() where task_id = v_task and status = 'pending';
    end if;
    insert into public.agent_events(owner_id, task_id, mandate_id, mandate_version, kind, initiated_by, result)
    values (v_actor, v_task, p_mandate, v_mandate.version, 'status', 'owner', jsonb_build_object('mandate_status', p_status));
  end if;
  return p_status;
end;
$$;


--
-- Name: agent_member_lock_key(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_member_lock_key(p_owner uuid) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select hashtextextended('drvn.agent_member:' || p_owner::text, 0);
$$;


--
-- Name: agent_mode_set(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_mode_set(p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_mandate record;
  v_task uuid;
  v_revoked integer := 0;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_mode is null or p_mode not in ('off', 'suggest', 'act') then raise exception 'Invalid agent mode' using errcode = '22023'; end if;
  -- Exclusive: waits for every agent write and mandate start holding the
  -- member's lock; none starts until this commits.
  perform pg_advisory_xact_lock(public.agent_member_lock_key(v_actor));
  update public.profiles set agent_mode = p_mode where id = v_actor;
  if not found then raise exception 'Not found' using errcode = 'P0002'; end if;
  if p_mode <> 'act' then
    -- After the member in the lock order: no listing lock here (see header).
    for v_mandate in
      select m.id, m.version from public.agent_mandates m
      where m.owner_id = v_actor and m.status in ('active', 'paused')
      order by m.id
      for update
    loop
      update public.agent_mandates set status = 'revoked', ended_at = now(), updated_at = now() where id = v_mandate.id;
      select id into v_task from public.agent_tasks where mandate_id = v_mandate.id and finished_at is null for update;
      if v_task is not null then
        update public.agent_tasks set status = 'cancelled', outcome = 'agent set to ' || p_mode || ' by owner'
        where id = v_task and finished_at is null;
        update public.agent_approvals set status = 'dismissed', decided_at = now() where task_id = v_task and status = 'pending';
        insert into public.agent_events(owner_id, task_id, mandate_id, mandate_version, kind, initiated_by, result)
        values (v_actor, v_task, v_mandate.id, v_mandate.version, 'status', 'owner',
          jsonb_build_object('mandate_status', 'revoked', 'agent_mode', p_mode));
      end if;
      v_revoked := v_revoked + 1;
    end loop;
  end if;
  return jsonb_build_object('mode', p_mode, 'revoked', v_revoked);
end;
$$;


--
-- Name: agent_offer_move(uuid, uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_offer_move(p_job uuid, p_lease uuid, p_offer uuid, p_kind text, p_amount integer, p_expected_round integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_peek public.agent_jobs;
  v_job public.agent_jobs;
  v_listing public.listings;
  v_offer public.offers;
  v_auth jsonb;
  v_owner uuid;
  v_key text;
  v_live integer;
  v_result jsonb;
begin
  select * into v_peek from public.agent_jobs where id = p_job;
  if not found then raise exception 'This job is not leased to you' using errcode = 'AG001'; end if;
  -- Lock order: listing → offer → job → mandate → task.
  select * into v_listing from public.listings where id = v_peek.listing_id for update;
  select * into v_offer from public.offers where id = v_peek.offer_id for update;
  v_job := public.agent_lock_job(p_job, p_lease, 'offer_move');
  if v_job.offer_id is distinct from p_offer or v_job.round_no is distinct from p_expected_round then
    raise exception 'This job is for another move' using errcode = 'AG002';
  end if;
  v_auth := public.agent_authority(v_job, v_listing, v_offer);
  v_owner := (v_auth->>'owner_id')::uuid;

  if v_auth->>'scope' = 'seller' then
    -- The seller's agent counters; it never accepts (AG-5; no auto-accept at launch).
    if p_kind not in ('counter', 'decline') then
      raise exception 'The seller''s agent can only counter or decline' using errcode = 'AG008';
    end if;
  else
    if p_kind not in ('counter', 'accept', 'withdraw') then
      raise exception 'The buyer''s agent can counter, accept or withdraw' using errcode = 'AG008';
    end if;
    v_live := case p_kind when 'counter' then p_amount when 'accept' then v_offer.counter_amount_cents end;
    -- "Total up to" counts the listing's shipping.
    v_live := v_live + (case when v_auth->>'ceiling_basis' = 'total' then v_listing.shipping_cents else 0 end);
    if v_live is not null and v_live > (v_auth->>'ceiling_cents')::integer then
      raise exception 'That is above the owner''s limit' using errcode = 'AG006';
    end if;
  end if;

  -- The task waits for the other side unless the move settles it (the outbox
  -- trigger runs inside the move and may finish or re-queue it).
  update public.agent_tasks set status = 'waiting_for_event'
  where id = v_job.task_id and status = 'working'
    and not exists (select 1 from public.agent_jobs j where j.task_id = v_job.task_id and j.id <> v_job.id
                    and j.status in ('pending', 'leased'));
  update public.agent_jobs set status = 'done', lease_id = null, lease_expires_at = null, finished_at = now()
  where id = v_job.id;

  v_key := p_kind || ':' || p_offer || ':r' || p_expected_round || ':' || coalesce(p_amount, 0);
  v_result := public.offer_move_core(v_owner, p_offer, p_kind, p_amount, v_key, p_expected_round,
    jsonb_build_object('task_id', v_job.task_id, 'job_id', v_job.id, 'mandate_version', (v_auth->>'mandate_version')::integer,
      'ceiling_cents', (v_auth->>'ceiling_cents')::integer));

  insert into public.agent_events(owner_id, task_id, job_id, mandate_id, mandate_version, kind, initiated_by, inputs, result, idempotency_key)
  values (v_owner, v_job.task_id, v_job.id, (v_auth->>'mandate_id')::uuid, (v_auth->>'mandate_version')::integer, 'move',
    'offer_round:' || p_offer || ':r' || p_expected_round,
    jsonb_build_object('kind', p_kind, 'amount_cents', p_amount),
    v_result - 'order_id', v_key);
  return v_result;
end;
$$;


--
-- Name: agent_offer_open(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_offer_open(p_job uuid, p_lease uuid, p_listing uuid, p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_peek public.agent_jobs;
  v_job public.agent_jobs;
  v_listing public.listings;
  v_none public.offers;
  v_auth jsonb;
  v_owner uuid;
  v_result jsonb;
  v_live integer;
begin
  select * into v_peek from public.agent_jobs where id = p_job;
  if not found then raise exception 'This job is not leased to you' using errcode = 'AG001'; end if;
  select * into v_listing from public.listings where id = v_peek.listing_id for update;
  v_job := public.agent_lock_job(p_job, p_lease, 'offer_open');
  if v_job.listing_id is distinct from p_listing then
    raise exception 'This job is for another listing' using errcode = 'AG002';
  end if;
  v_auth := public.agent_authority(v_job, v_listing, v_none);
  v_owner := (v_auth->>'owner_id')::uuid;
  if v_auth->>'scope' <> 'buyer' then
    raise exception 'Only the buyer''s agent opens offers' using errcode = 'AG008';
  end if;
  v_live := p_amount + (case when v_auth->>'ceiling_basis' = 'total' then v_listing.shipping_cents else 0 end);
  if v_live is null or v_live > (v_auth->>'ceiling_cents')::integer then
    raise exception 'That is above the owner''s limit' using errcode = 'AG006';
  end if;

  update public.agent_tasks set status = 'waiting_for_event', offer_id = null
  where id = v_job.task_id and status = 'working';
  update public.agent_jobs set status = 'done', lease_id = null, lease_expires_at = null, finished_at = now()
  where id = v_job.id;

  v_result := public.offer_open_core(v_owner, v_job.id, p_listing, p_amount, null,
    jsonb_build_object('task_id', v_job.task_id, 'job_id', v_job.id, 'mandate_version', (v_auth->>'mandate_version')::integer,
      'ceiling_cents', (v_auth->>'ceiling_cents')::integer));
  update public.agent_tasks set offer_id = v_job.id where id = v_job.task_id and finished_at is null;

  insert into public.agent_events(owner_id, task_id, job_id, mandate_id, mandate_version, kind, initiated_by, inputs, result, idempotency_key)
  values (v_owner, v_job.task_id, v_job.id, (v_auth->>'mandate_id')::uuid, (v_auth->>'mandate_version')::integer, 'move',
    'task:' || v_job.task_id, jsonb_build_object('kind', 'offer', 'amount_cents', p_amount), v_result, 'open:' || v_job.id);
  return v_result;
end;
$$;


--
-- Name: agent_on_offer_round(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_on_offer_round() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_offer public.offers;
  v_seller uuid;
  v_task record;
  v_ended boolean;
begin
  select * into v_offer from public.offers where id = new.offer_id;
  select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;

  -- Earlier turns on this offer are over: their jobs and approvals lapse.
  update public.agent_jobs set status = 'cancelled', lease_id = null, lease_expires_at = null,
    finished_at = now(), last_error = 'superseded'
  where offer_id = new.offer_id and status in ('pending', 'leased') and round_no < new.round_no;

  v_ended := v_offer.status not in ('open', 'countered');

  if not v_ended then
    -- Whose turn now: open = the seller's, countered = the buyer's.
    for v_task in
      select t.id, t.status from public.agent_tasks t
      join public.agent_mandates m on m.id = t.mandate_id
      where m.listing_id = new.listing_id and m.status = 'active' and t.finished_at is null
        and ((v_offer.status = 'open' and m.scope = 'seller' and m.owner_id = v_seller)
          or (v_offer.status = 'countered' and m.scope = 'buyer' and m.owner_id = v_offer.buyer_id))
      order by m.id
    loop
      insert into public.agent_jobs(task_id, kind, expected_action, listing_id, offer_id, round_no, dedup_key)
      values (v_task.id, 'offer_turn', 'offer_move', new.listing_id, new.offer_id, new.round_no,
              'turn:' || new.offer_id || ':r' || new.round_no || ':' || v_task.id)
      on conflict (dedup_key) do nothing;
      update public.agent_tasks set status = 'working' where id = v_task.id and status = 'waiting_for_event';
    end loop;
  end if;

  if v_ended then
    -- Settle the tasks this offer was about.
    for v_task in
      select t.id, t.status, m.id mandate_id, m.scope, m.status mandate_status from public.agent_tasks t
      join public.agent_mandates m on m.id = t.mandate_id
      where m.listing_id = new.listing_id and t.finished_at is null
        and ((m.scope = 'seller' and m.owner_id = v_seller)
          or (m.scope = 'buyer' and m.owner_id = v_offer.buyer_id))
      order by m.id
    loop
      -- Each update re-checks the row's state: a concurrent revoke or sweep
      -- may have finished it, and this must never fail a person's move.
      if v_offer.status = 'accepted' and v_task.scope = 'buyer' then
        update public.agent_mandates set status = 'ended', ended_at = now(), updated_at = now()
        where id = v_task.mandate_id and status in ('active', 'paused');
        update public.agent_tasks set status = 'completed', outcome = 'bought' where id = v_task.id and finished_at is null;
        insert into public.agent_events(owner_id, task_id, mandate_id, kind, initiated_by, result)
        select t.owner_id, t.id, v_task.mandate_id, 'status', 'offer_round:' || new.offer_id || ':r' || new.round_no,
               jsonb_build_object('status', t.status, 'outcome', t.outcome)
        from public.agent_tasks t where t.id = v_task.id;
      elsif v_offer.status = 'accepted' then
        -- The seller's task and minimum stay until the sale completes: if
        -- checkout is cancelled the listing comes back with its agent's
        -- minimum still in force. The sweep completes it once sold.
        update public.agent_tasks set status = 'waiting_for_event' where id = v_task.id and status = 'working';
      elsif v_task.scope = 'buyer' then
        -- A buyer's agent tries again after a decline while it has offers left.
        if v_task.mandate_status = 'active' and new.kind in ('decline', 'below_minimum')
           and public.agent_enqueue_turns(v_task.id) > 0 then
          update public.agent_tasks set status = 'working' where id = v_task.id and finished_at is null and status <> 'working';
        else
          update public.agent_tasks set status = 'failed', outcome = 'offer ' || new.kind where id = v_task.id and finished_at is null;
          insert into public.agent_events(owner_id, task_id, mandate_id, kind, initiated_by, result)
          select t.owner_id, t.id, v_task.mandate_id, 'status', 'offer_round:' || new.offer_id || ':r' || new.round_no,
                 jsonb_build_object('status', t.status, 'outcome', t.outcome)
          from public.agent_tasks t where t.id = v_task.id;
        end if;
      end if;
    end loop;
  end if;

  update public.agent_approvals set status = 'superseded', decided_at = now()
  where offer_id = new.offer_id and status = 'pending' and (round_no < new.round_no or v_ended);
  -- A seller task waiting only on approvals that just lapsed goes back to waiting.
  update public.agent_tasks t set status = 'waiting_for_event'
  where t.status = 'needs_approval' and t.listing_id = new.listing_id
    and not exists (select 1 from public.agent_approvals a where a.task_id = t.id and a.status = 'pending')
    and not exists (select 1 from public.agent_jobs j where j.task_id = t.id and j.status in ('pending', 'leased'));
  return null;
end;
$$;


--
-- Name: agent_open_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_open_task(p_mandate uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mandate public.agent_mandates;
  v_task uuid;
begin
  select * into v_mandate from public.agent_mandates where id = p_mandate;
  if not found or v_mandate.status not in ('active', 'paused') then return null; end if;
  select id into v_task from public.agent_tasks where mandate_id = p_mandate and finished_at is null for update;
  if v_task is null then
    insert into public.agent_tasks(owner_id, mandate_id, scope, objective, status, listing_id)
    values (v_mandate.owner_id, v_mandate.id, v_mandate.scope,
      case v_mandate.scope when 'seller' then 'Handle offers on this listing' else 'Negotiate this part for me' end,
      case v_mandate.scope when 'seller' then 'waiting_for_event' else 'working' end, v_mandate.listing_id)
    returning id into v_task;
  end if;
  return v_task;
end;
$$;


--
-- Name: agent_purge_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_purge_member(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tasks integer; v_mandates integer; v_events integer;
begin
  if p_user is null then raise exception 'A member is required' using errcode = '22023'; end if;
  perform set_config('drvn.agent_purge', 'on', true);
  delete from public.agent_conversations where owner_id = p_user;
  delete from public.agent_approvals where owner_id = p_user;
  delete from public.agent_events where owner_id = p_user;
  get diagnostics v_events = row_count;
  delete from public.agent_tasks where owner_id = p_user;
  get diagnostics v_tasks = row_count;
  delete from public.agent_mandates where owner_id = p_user;
  get diagnostics v_mandates = row_count;
  update public.agent_telemetry set owner_id = null where owner_id = p_user;
  perform set_config('drvn.agent_purge', '', true);
  return jsonb_build_object('tasks', v_tasks, 'mandates', v_mandates, 'events', v_events);
end;
$$;


--
-- Name: agent_reconcile_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_reconcile_outbox(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_released integer;
  v_cancelled integer;
  v_ended integer := 0;
  v_added integer := 0;
  v_skipped integer := 0;
  v_n integer;
  v_task record;
  v_why text;
  v_listing public.listings;
begin
  -- One listing at a time, in id order, each locked first like every move on
  -- it (listing → offer → job → mandate → task). A listing busy with a move
  -- is skipped this pass rather than waited for, so the sweep never holds up
  -- a member or deadlocks against one.
  for v_task in
    select t.id, t.owner_id, t.listing_id, t.mandate_id, m.status mandate_status, m.expires_at
    from public.agent_tasks t
    left join public.agent_mandates m on m.id = t.mandate_id
    where t.finished_at is null and t.scope in ('seller', 'buyer')
    order by t.listing_id nulls first, t.id
    limit greatest(coalesce(p_limit, 200), 1)
  loop
    v_listing := null;
    if v_task.listing_id is not null then
      select * into v_listing from public.listings where id = v_task.listing_id for update skip locked;
      if not found then
        if exists (select 1 from public.listings where id = v_task.listing_id) then
          v_skipped := v_skipped + 1;
          continue;
        end if;
      end if;
    end if;
    perform 1 from public.offers where listing_id = v_task.listing_id and status in ('open', 'countered') order by id for update;

    -- Tasks with nothing left to do end: the listing sold, went (archived,
    -- removed, deleted), the mandate expired or is gone.
    v_why := case
      when v_task.mandate_id is null then 'mandate gone'
      when v_listing.id is null then 'listing gone'
      when v_listing.status = 'sold' then 'sold'
      when v_listing.status in ('archived', 'removed') then 'listing unavailable'
      when v_task.expires_at is not null and v_task.expires_at <= now() then 'mandate expired'
    end;
    if v_why is not null then
      update public.agent_jobs set status = 'cancelled', lease_id = null, lease_expires_at = null, finished_at = now(),
        last_error = 'task ended'
      where task_id = v_task.id and status in ('pending', 'leased');
      update public.agent_mandates set status = 'ended', ended_at = now(), updated_at = now()
      where id = v_task.mandate_id and status in ('active', 'paused');
      update public.agent_tasks set status = case v_why when 'sold' then 'completed' else 'cancelled' end, outcome = v_why
      where id = v_task.id and finished_at is null;
      insert into public.agent_events(owner_id, task_id, mandate_id, kind, initiated_by, result)
      values (v_task.owner_id, v_task.id, v_task.mandate_id, 'status', 'reconcile', jsonb_build_object('outcome', v_why));
      v_ended := v_ended + 1;
      continue;
    end if;

    -- A live turn with no job means the outbox missed an event.
    if v_task.mandate_status = 'active' then
      v_n := public.agent_enqueue_turns(v_task.id);
      if v_n > 0 then
        v_added := v_added + v_n;
        insert into public.agent_telemetry(kind, code, task_id, owner_id) values ('outbox_reconciled', v_n::text, v_task.id, v_task.owner_id);
        update public.agent_tasks set status = 'working' where id = v_task.id and status = 'waiting_for_event';
      end if;
    end if;
  end loop;

  -- Leases that ran out go back to the queue (claim also re-leases them), and
  -- jobs whose task ended have nothing to do. Jobs only: no listing waits on these.
  update public.agent_jobs set status = 'pending', lease_id = null, lease_expires_at = null
  where status = 'leased' and lease_expires_at < now() - interval '1 minute' and attempts < max_attempts;
  get diagnostics v_released = row_count;
  update public.agent_jobs j set status = 'cancelled', lease_id = null, lease_expires_at = null, finished_at = now(),
    last_error = 'task ended'
  from public.agent_tasks t
  where t.id = j.task_id and t.finished_at is not null and j.status in ('pending', 'leased');
  get diagnostics v_cancelled = row_count;
  return jsonb_build_object('released', v_released, 'ended', v_ended, 'cancelled', v_cancelled, 'enqueued', v_added, 'skipped', v_skipped);
end;
$$;


--
-- Name: agent_record_decision(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_record_decision(p_job uuid, p_lease uuid, p_decision text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_peek public.agent_jobs;
  v_job public.agent_jobs;
  v_listing public.listings;
  v_offer public.offers;
  v_auth jsonb;
begin
  if p_decision is null or p_decision not in ('hold', 'at_limit', 'skip') then
    raise exception 'Invalid decision' using errcode = '22023';
  end if;
  select * into v_peek from public.agent_jobs where id = p_job;
  if not found then raise exception 'This job is not leased to you' using errcode = 'AG001'; end if;
  select * into v_listing from public.listings where id = v_peek.listing_id for update;
  select * into v_offer from public.offers where id = v_peek.offer_id for update;
  v_job := public.agent_lock_job(p_job, p_lease, null);
  v_auth := public.agent_authority(v_job, v_listing, v_offer);
  update public.agent_jobs set status = 'done', lease_id = null, lease_expires_at = null, finished_at = now() where id = v_job.id;
  update public.agent_tasks set status = 'waiting_for_event'
  where id = v_job.task_id and status = 'working'
    and not exists (select 1 from public.agent_jobs j where j.task_id = v_job.task_id and j.status in ('pending', 'leased'));
  insert into public.agent_events(owner_id, task_id, job_id, mandate_id, mandate_version, kind, initiated_by, inputs, result)
  values ((v_auth->>'owner_id')::uuid, v_job.task_id, v_job.id, (v_auth->>'mandate_id')::uuid, (v_auth->>'mandate_version')::integer, 'decision',
    coalesce('offer_round:' || v_job.offer_id || ':r' || v_job.round_no, 'task:' || v_job.task_id),
    '{}'::jsonb, jsonb_build_object('decision', p_decision, 'reason', left(public.agent_redact_cards(p_reason), 200)));
end;
$$;


--
-- Name: agent_record_mandate_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_record_mandate_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.version = old.version then
    -- A status change keeps the version; keep the stored row in step.
    update public.agent_mandate_versions set status = new.status
    where mandate_id = new.id and version = new.version;
    return null;
  end if;
  insert into public.agent_mandate_versions(mandate_id, version, owner_id, status, minimum_cents, target_cents,
    ceiling_cents, ceiling_basis, style, expires_at)
  values (new.id, new.version, new.owner_id, new.status, new.minimum_cents, new.target_cents,
    new.ceiling_cents, new.ceiling_basis, new.style, new.expires_at)
  on conflict (mandate_id, version) do nothing;
  return null;
end;
$$;


--
-- Name: agent_record_tool_calls(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_record_tool_calls(p_owner uuid, p_request uuid, p_turn text, p_calls jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_call jsonb;
  v_seq integer := 0;
  v_tool text;
  v_outcome text;
  v_code text;
  v_ms integer;
  v_ids jsonb;
  v_key text;
  v_value jsonb;
  v_n integer := 0;
begin
  if p_owner is null or p_request is null then
    raise exception 'An owner and a request are required' using errcode = '22023';
  end if;
  if p_turn is null or p_turn <> all (public.agent_audit_vocabulary('turn')) then
    raise exception 'Bad turn outcome' using errcode = '22023';
  end if;
  if p_calls is null or jsonb_typeof(p_calls) <> 'array' or jsonb_array_length(p_calls) > 50 then
    raise exception 'Calls must be an array of at most 50' using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles where id = p_owner) then
    raise exception 'No such member' using errcode = 'P0002';
  end if;
  -- Recorded once per request: a repeat (a retried server action) adds nothing.
  if exists (select 1 from public.agent_events
             where owner_id = p_owner and kind = 'tool_call' and initiated_by = 'chat:' || p_request::text) then
    return 0;
  end if;

  for v_call in select value from jsonb_array_elements(p_calls) loop
    v_seq := v_seq + 1;
    if jsonb_typeof(v_call) <> 'object' then
      raise exception 'Call % is not an object', v_seq using errcode = '22023';
    end if;
    -- A capability's name, or unknown_tool: a name the model made up could hold anything.
    v_tool := v_call->>'tool';
    if v_tool is null or v_tool <> all (public.agent_audit_vocabulary('tool')) then v_tool := 'unknown_tool'; end if;
    v_outcome := v_call->>'outcome';
    if v_outcome is null or v_outcome not in ('ok', 'refused', 'failed') then
      raise exception 'Call % has a bad outcome', v_seq using errcode = '22023';
    end if;
    v_code := v_call->>'code';
    if v_code is not null and v_code <> all (public.agent_audit_vocabulary('code')) then v_code := 'failed'; end if;
    v_ms := case when jsonb_typeof(v_call->'ms') = 'number'
                 then least(greatest(round((v_call->>'ms')::numeric), 0), 600000)::integer end;
    -- Object ids only: a known key, and uuid values.
    v_ids := '{}'::jsonb;
    if jsonb_typeof(v_call->'ids') = 'object' then
      for v_key, v_value in select key, value from jsonb_each(v_call->'ids') loop
        continue when v_key <> all (public.agent_audit_vocabulary('id_key'));
        if jsonb_typeof(v_value) = 'string' and (v_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          v_ids := v_ids || jsonb_build_object(v_key, lower(v_value #>> '{}'));
        elsif jsonb_typeof(v_value) = 'array' then
          v_ids := v_ids || jsonb_build_object(v_key, coalesce((
            select jsonb_agg(lower(e #>> '{}'))
            from (select e from jsonb_array_elements(v_value) e limit 40) picked
            where jsonb_typeof(e) = 'string'
              and (e #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'), '[]'::jsonb));
        end if;
      end loop;
    end if;

    insert into public.agent_events(owner_id, kind, initiated_by, inputs, result, idempotency_key)
    values (
      p_owner, 'tool_call', 'chat:' || p_request::text,
      jsonb_build_object('tool', v_tool, 'ids', v_ids),
      jsonb_strip_nulls(jsonb_build_object('outcome', v_outcome, 'code', v_code, 'ms', v_ms, 'seq', v_seq, 'turn', p_turn)),
      'tool:' || p_request::text || ':' || v_seq::text
    );
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$_$;


--
-- Name: FUNCTION agent_record_tool_calls(p_owner uuid, p_request uuid, p_turn text, p_calls jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.agent_record_tool_calls(p_owner uuid, p_request uuid, p_turn text, p_calls jsonb) IS 'One tool_call agent_event per tool the model ran in a chat turn: tool name, object ids, outcome, code, timing, correlation. Never chat or arguments (20261107210200, OS-W07 R-audit). Server only.';


--
-- Name: agent_redact_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_redact_approval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.reason := public.agent_redact_cards(new.reason);
  return new;
end;
$$;


--
-- Name: agent_redact_cards(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_redact_cards(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_out text := '';
  v_rest text := p_text;
  v_id text;
  v_at integer;
begin
  if p_text is null then return null; end if;
  loop
    -- The leftmost UUID-shaped text left; no earlier copy of it exists, so
    -- position() finds that same match.
    v_id := substring(v_rest from '[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}');
    exit when v_id is null;
    v_at := position(v_id in v_rest);
    v_out := v_out || private.agent_redact_card_runs(left(v_rest, v_at - 1)) || v_id;
    v_rest := substr(v_rest, v_at + length(v_id));
  end loop;
  return v_out || private.agent_redact_card_runs(v_rest);
end;
$$;


--
-- Name: agent_redact_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_redact_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ids jsonb;
begin
  begin
    if new.kind = 'tool_call' and public.agent_audit_ids_valid(new.inputs->'ids') then
      v_ids := new.inputs->'ids';
      new.inputs := public.agent_redact_cards((new.inputs - 'ids')::text)::jsonb || jsonb_build_object('ids', v_ids);
    else
      new.inputs := public.agent_redact_cards(new.inputs::text)::jsonb;
    end if;
    new.result := public.agent_redact_cards(new.result::text)::jsonb;
  exception when others then
    new.inputs := jsonb_build_object('redacted', true);
    new.result := jsonb_build_object('redacted', true);
  end;
  return new;
end;
$$;


--
-- Name: agent_redact_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_redact_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.body := public.agent_redact_cards(new.body);
  return new;
end;
$$;


--
-- Name: agent_renew_lease(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_renew_lease(p_job uuid, p_lease uuid, p_lease_seconds integer DEFAULT 60) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.agent_jobs;
begin
  v_job := public.agent_lock_job(p_job, p_lease, null);
  update public.agent_jobs set lease_expires_at = now() + make_interval(secs => least(greatest(coalesce(p_lease_seconds, 60), 10), 600))
  where id = v_job.id returning lease_expires_at into v_job.lease_expires_at;
  return v_job.lease_expires_at;
end;
$$;


--
-- Name: agent_request_approval(uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_request_approval(p_job uuid, p_lease uuid, p_offer uuid, p_expected_round integer, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_peek public.agent_jobs;
  v_job public.agent_jobs;
  v_listing public.listings;
  v_offer public.offers;
  v_auth jsonb;
  v_owner uuid;
  v_amount integer;
  v_id uuid;
begin
  select * into v_peek from public.agent_jobs where id = p_job;
  if not found then raise exception 'This job is not leased to you' using errcode = 'AG001'; end if;
  select * into v_listing from public.listings where id = v_peek.listing_id for update;
  select * into v_offer from public.offers where id = v_peek.offer_id for update;
  v_job := public.agent_lock_job(p_job, p_lease, 'offer_move');
  if v_job.offer_id is distinct from p_offer or v_job.round_no is distinct from p_expected_round
     or v_offer.round_count is distinct from p_expected_round then
    raise exception 'This job is for another move' using errcode = 'AG002';
  end if;
  v_auth := public.agent_authority(v_job, v_listing, v_offer);
  v_owner := (v_auth->>'owner_id')::uuid;
  if v_offer.status not in ('open', 'countered') then raise exception 'This offer is already settled' using errcode = 'OF005'; end if;
  if (v_auth->>'scope' = 'seller' and v_offer.status <> 'open') or (v_auth->>'scope' = 'buyer' and v_offer.status <> 'countered') then
    raise exception 'It''s not your turn' using errcode = 'OF002';
  end if;
  v_amount := case v_offer.status when 'open' then v_offer.amount_cents else v_offer.counter_amount_cents end;

  insert into public.agent_approvals(owner_id, task_id, kind, offer_id, round_no, amount_cents, reason)
  values (v_owner, v_job.task_id, 'accept_offer', p_offer, p_expected_round, v_amount, left(p_reason, 200))
  on conflict (task_id, offer_id, round_no) where status = 'pending' do nothing
  returning id into v_id;
  if v_id is null then
    select id into v_id from public.agent_approvals
    where task_id = v_job.task_id and offer_id = p_offer and round_no = p_expected_round and status = 'pending';
  end if;
  update public.agent_jobs set status = 'done', lease_id = null, lease_expires_at = null, finished_at = now() where id = v_job.id;
  update public.agent_tasks set status = 'needs_approval' where id = v_job.task_id and status <> 'needs_approval';
  insert into public.agent_events(owner_id, task_id, job_id, mandate_id, mandate_version, kind, initiated_by, inputs, result)
  values (v_owner, v_job.task_id, v_job.id, (v_auth->>'mandate_id')::uuid, (v_auth->>'mandate_version')::integer, 'approval',
    'offer_round:' || p_offer || ':r' || p_expected_round, jsonb_build_object('amount_cents', v_amount, 'reason', left(p_reason, 200)),
    jsonb_build_object('approval_id', v_id));
  return v_id;
end;
$$;


--
-- Name: agent_retention_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_retention_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_jobs integer; v_telemetry integer; v_events integer; v_tasks integer; v_mandates integer; v_conversations integer;
begin
  perform set_config('drvn.agent_purge', 'on', true);
  delete from public.agent_jobs where finished_at < now() - interval '30 days';
  get diagnostics v_jobs = row_count;
  delete from public.agent_telemetry where created_at < now() - interval '30 days';
  get diagnostics v_telemetry = row_count;
  delete from public.agent_events where created_at < now() - interval '12 months';
  get diagnostics v_events = row_count;
  delete from public.agent_tasks where finished_at < now() - interval '12 months';
  get diagnostics v_tasks = row_count;
  delete from public.agent_mandates m where m.ended_at < now() - interval '12 months'
    and not exists (select 1 from public.agent_tasks t where t.mandate_id = m.id and t.finished_at is null);
  get diagnostics v_mandates = row_count;
  delete from public.agent_conversations where last_message_at < now() - interval '12 months';
  get diagnostics v_conversations = row_count;
  perform set_config('drvn.agent_purge', '', true);
  return jsonb_build_object('jobs', v_jobs, 'telemetry', v_telemetry, 'events', v_events, 'tasks', v_tasks,
    'mandates', v_mandates, 'conversations', v_conversations);
end;
$$;


--
-- Name: agent_spend_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_spend_allowed(p_owner uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with lim as (select per_member_daily_usd, global_daily_usd from public.agent_spend_limits where singleton),
  today as (
    select coalesce(sum(cost_usd) filter (where owner_id = p_owner), 0) as member_usd, coalesce(sum(cost_usd), 0) as global_usd
    from public.agent_usage where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
  )
  select jsonb_build_object(
    'allowed', today.member_usd < lim.per_member_daily_usd and today.global_usd < lim.global_daily_usd,
    'member_usd', today.member_usd, 'global_usd', today.global_usd,
    'member_cap', lim.per_member_daily_usd, 'global_cap', lim.global_daily_usd)
  from lim, today;
$$;


--
-- Name: agent_spend_reserve(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_spend_reserve(p_owner uuid, p_feature text, p_amount_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limits public.agent_spend_limits;
  v_day timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
  v_member numeric;
  v_global numeric;
  v_hold uuid;
begin
  if p_owner is null or p_feature is null or p_feature not in ('agent_chat', 'agent_eval', 'listing_import', 'marketplace_filters')
     or p_amount_usd is null or p_amount_usd <= 0 or p_amount_usd > 5 then
    raise exception 'Invalid spend reservation' using errcode = '22023';
  end if;
  if public.is_suspended(p_owner) then
    return jsonb_build_object('allowed', false, 'reason', 'suspended');
  end if;
  -- Read the switches the way agent_halt_reason does, so a switch being
  -- flipped right now is seen either before or after, never half.
  perform pg_advisory_xact_lock_shared(public.agent_controls_lock_key());
  if exists (select 1 from public.agent_controls c
             where c.cleared_at is null
               and (c.scope = 'all' or (c.scope in ('member', 'account') and c.subject_id = p_owner))) then
    return jsonb_build_object('allowed', false, 'reason', 'paused');
  end if;

  -- One reservation or settlement at a time, everyone's: agent_spend_settle
  -- takes this lock too, so no hold can turn into usage between the reads
  -- below. The transaction is a few index reads long.
  select * into v_limits from public.agent_spend_limits where singleton for update;
  if not found then
    return jsonb_build_object('allowed', false, 'reason', 'spend_cap');
  end if;
  delete from public.agent_spend_holds where created_at < now() - interval '2 days';

  -- Spend and holds from one snapshot.
  select
    coalesce((select sum(u.cost_usd) from public.agent_usage u where u.created_at >= v_day and u.owner_id = p_owner), 0)
      + coalesce((select sum(h.amount_usd) from public.agent_spend_holds h where h.created_at >= v_day and h.owner_id = p_owner), 0),
    coalesce((select sum(u.cost_usd) from public.agent_usage u where u.created_at >= v_day), 0)
      + coalesce((select sum(h.amount_usd) from public.agent_spend_holds h where h.created_at >= v_day), 0)
  into v_member, v_global;

  if v_member + p_amount_usd > v_limits.per_member_daily_usd or v_global + p_amount_usd > v_limits.global_daily_usd then
    return jsonb_build_object('allowed', false, 'reason', 'spend_cap',
      'member_usd', v_member, 'global_usd', v_global,
      'member_cap', v_limits.per_member_daily_usd, 'global_cap', v_limits.global_daily_usd);
  end if;

  insert into public.agent_spend_holds(owner_id, feature, amount_usd)
  values (p_owner, p_feature, p_amount_usd)
  returning id into v_hold;
  return jsonb_build_object('allowed', true, 'hold', v_hold);
end;
$$;


--
-- Name: agent_spend_settle(uuid, uuid, text, text, integer, integer, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_spend_settle(p_hold uuid, p_owner uuid, p_feature text, p_model text, p_input_tokens integer, p_output_tokens integer, p_cost_usd numeric DEFAULT NULL::numeric, p_task uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_hold is null or p_owner is null or p_feature is null or p_model is null or p_input_tokens is null or p_output_tokens is null
     or p_input_tokens < 0 or p_output_tokens < 0 or (p_cost_usd is not null and p_cost_usd < 0) then
    raise exception 'Invalid spend settlement' using errcode = '22023';
  end if;
  -- The reservation's lock: a reservation sees this hold or this usage, never neither.
  perform 1 from public.agent_spend_limits where singleton for update;
  delete from public.agent_spend_holds where id = p_hold and owner_id = p_owner;
  if p_input_tokens + p_output_tokens > 0 or coalesce(p_cost_usd, 0) > 0 then
    insert into public.agent_usage(owner_id, task_id, feature, model, input_tokens, output_tokens, cost_usd)
    values (p_owner, p_task, p_feature, p_model, p_input_tokens, p_output_tokens, p_cost_usd);
  end if;
end;
$$;


--
-- Name: agent_usage_retention_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_usage_retention_sweep() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with gone as (delete from public.agent_usage where created_at < now() - interval '12 months' returning 1)
  select count(*)::integer from gone;
$$;


--
-- Name: announce_policy_update(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.announce_policy_update(p_key text, p_title text, p_body text, p_href text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count int;
begin
  insert into public.policy_announcements (key, title, body, href)
  values (p_key, p_title, p_body, p_href)
  on conflict (key) do nothing;
  if not found then
    return 0;
  end if;

  insert into public.notifications (user_id, kind, section, title, body, href, actor_id)
  select p.id, 'policy_updated', 'marketplace', p_title, p_body, p_href, null
    from public.profiles p
   where p.username is not null;
  get diagnostics v_count = row_count;

  update public.policy_announcements set recipients = v_count where key = p_key;
  return v_count;
end;
$$;


--
-- Name: apply_stripe_dispute_event(text, text, integer, text, text, boolean, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stripe_dispute_event(p_dispute text, p_intent text, p_amount integer, p_currency text, p_status text, p_closed boolean, p_event text, p_created bigint, p_lease uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare entry public.stripe_dispute_journal%rowtype; ids uuid[]; total bigint;
 valid boolean; order_row public.orders%rowtype; prior_exists boolean; retried boolean:=false;
begin
 if p_closed is null then raise exception 'Missing dispute event phase'; end if;
 if p_closed and (p_status in ('won','warning_closed','lost')) is distinct from true then return 'retry'; end if;
 if p_dispute is null or p_intent is null or p_event is null or p_lease is null or p_created is null or p_amount<=0 or p_currency!~'^[a-z]{3}$' then raise exception 'Invalid dispute event'; end if;
 perform pg_advisory_xact_lock(hashtextextended('stripe-dispute:'||p_intent,0));
 select * into entry from public.stripe_dispute_journal where dispute_id=p_dispute for update;
 prior_exists:=found;
 if prior_exists then
  if entry.payment_reference<>p_intent or entry.amount_cents<>p_amount or entry.currency<>p_currency then return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Provider dispute identity, amount or currency changed. Reconcile against the original journal.'); end if;
  -- 20261110230000: a later event while held is remembered, so Retry
  -- replays the newest Stripe knows.
  if entry.state='recovery' then
   -- Only an entry known to have been held from 'open'. One held before
   -- this migration has no held_from_state: what it was held from is
   -- unknown, and unknown is not retryable (review of #208).
   if entry.retry_until is not null and entry.retry_until>now() and p_event=entry.held_event_id
      and entry.held_from_state='open' then
    -- An admin's Retry allowed this one replay (work review #148). The
    -- reopen and everything below are this one transaction: it ends
    -- settled, open, or held again, never reopened with nothing replayed.
    update public.stripe_dispute_journal set state='open',retry_until=null,lease_id=null,lease_expires_at=null,updated_at=now()
     where dispute_id=p_dispute returning * into entry;
    retried:=true;
   else
    perform private.note_held_dispute_event(p_dispute,p_event,p_created); return 'recovery_recorded';
   end if;
  end if;
  if not p_closed and entry.state<>'open' then return 'committed'; end if;
  if p_closed and entry.state in ('won','warning_closed','lost') then
   if entry.state=p_status then return 'committed'; end if;
   return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Conflicting terminal provider dispute outcomes require review.');
  end if;
  if entry.state='loss_pending' and p_closed and p_status<>'lost' then return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Conflicting terminal outcome during chargeback booking.'); end if;
  if entry.state='loss_pending' and entry.lease_expires_at>now() then return 'retry'; end if;
  -- Not newer than the last event applied: nothing to do, except on a
  -- replay, whose event (often the very one that held it) must be checked
  -- against the basket below before anything is called done.
  if not p_closed and p_created<=entry.last_event_created and not retried then return 'committed'; end if;
 end if;
 select array_agg(distinct p.order_id order by p.order_id),sum(p.amount_cents),
 bool_and(lower(p.currency)=p_currency and p.status in ('succeeded','partially_refunded','refunded'))
 into ids,total,valid from public.payments p where p.provider='stripe' and p.provider_reference=p_intent;
 if ids is null then return 'retry'; end if;
 -- 20261107130000: the basket's orders are locked before any journal write
 -- below (the insert, or hold_stripe_dispute), in the order dispatch uses.
 perform 1 from public.orders where id=any(ids) order by id for update;
 if not prior_exists then
  insert into public.stripe_dispute_journal(dispute_id,payment_reference,amount_cents,currency,state,last_event_id,last_event_created,order_ids)
  values(p_dispute,p_intent,p_amount,p_currency,'open',p_event,p_created,ids)
  returning * into entry;
 end if;
 if cardinality(ids)>50 then return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Dispute basket exceeds the bounded automatic-processing limit.'); end if;
 if ids is distinct from entry.order_ids or total<>p_amount or valid is distinct from true then
  return public.hold_stripe_dispute(p_dispute,p_event,p_created,'The dispute does not exactly match the frozen payment basket and currency. Allocate the provider amount before booking any refund.');
 end if;
 perform id from public.orders where id=any(ids) order by id for update;
 if (select sum(total_cents) from public.orders where id=any(ids))<>p_amount or exists(select 1 from public.orders o where o.id=any(ids) and lower(o.currency)<>p_currency) then
  return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Order and provider dispute currencies differ.');
 end if;
 if p_closed and p_status not in ('won','warning_closed','lost') then return 'retry'; end if;
 -- Won/closed-before-created is journaled without inventing a prior hold.
 if p_closed and p_status in ('won','warning_closed') then
  if exists(select 1 from public.orders o where o.id=any(ids) and o.status='disputed' and o.stripe_dispute_id=p_dispute and o.dispute_reason not like '% — '||p_dispute) then
   return public.hold_stripe_dispute(p_dispute,p_event,p_created,'A newer in-app dispute owns an order; provider closure cannot resolve it.');
  end if;
  update public.orders set status=coalesce(pre_dispute_status,'paid'),dispute_resolved_at=now()
   where id=any(ids) and status='disputed' and stripe_dispute_id=p_dispute
   and dispute_reason like '% — '||p_dispute;
  update public.stripe_dispute_journal set state=p_status,last_event_id=p_event,last_event_created=p_created,updated_at=now() where dispute_id=p_dispute;
  return 'committed';
 end if;
 if exists(select 1 from public.orders o where o.id=any(ids) and (
  (o.status='disputed' and o.stripe_dispute_id is distinct from p_dispute)
  or (o.status not in ('paid','shipped','delivered','completed','disputed') and entry.state<>'loss_pending')
  or (p_status='lost' and p_closed and o.refunded_cents>0 and entry.state<>'loss_pending')
 )) then return public.hold_stripe_dispute(p_dispute,p_event,p_created,'Existing order/dispute/refund state prevents safe automatic chargeback allocation.'); end if;
 for order_row in select * from public.orders where id=any(ids) loop
  if order_row.status<>'disputed' and entry.state<>'loss_pending' then
   update public.orders set status='disputed',pre_dispute_status=order_row.status,
    disputed_at=now(),dispute_resolved_at=null,dispute_outcome=null,dispute_category='other',
    dispute_reason='Card dispute via Stripe — '||p_dispute,stripe_dispute_id=p_dispute
   where id=order_row.id;
  end if;
 end loop;
 update public.stripe_dispute_journal set state=case when p_closed then 'loss_pending' else 'open' end,
 last_event_id=p_event,last_event_created=p_created,
 lease_id=case when p_closed then p_lease else null end,
 lease_expires_at=case when p_closed then now()+interval '5 minutes' else null end,updated_at=now()
 where dispute_id=p_dispute;
 return case when p_closed then 'apply_loss' else 'committed' end;
end $_$;


--
-- Name: assert_admin_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_admin_actor(p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_actor is null or not exists (
    select 1 from public.admin_users au
    where au.user_id = p_actor and au.role = 'admin'
  ) then
    raise exception 'actor % is not a full admin — mutation refused', p_actor
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_deletion_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_deletion_ready(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare uid uuid:=p_user;
begin
 if exists(select 1 from public.orders where (buyer_id=uid or seller_id=uid) and status not in ('completed','cancelled','payment_failed','refunded'))
 or exists(select 1 from public.transfer_intents where seller_id=uid and status not in ('transferred','cancelled'))
 or exists(select 1 from public.refund_operations r join public.orders o on o.id=r.order_id where (o.buyer_id=uid or o.seller_id=uid) and r.status<>'completed')
 or exists(select 1 from public.payment_requests p where p.request->>'buyerId'=uid::text and p.provider_reference is null)
 or exists(select 1 from public.payment_recoveries r join public.orders o on o.id=r.order_id where r.status='open' and (o.buyer_id=uid or o.seller_id=uid))
 or exists(select 1 from public.payment_recoveries r join public.payments p on r.recovery_key='capture:'||p.provider_reference join public.orders o on o.id=p.order_id where r.status='open' and (o.buyer_id=uid or o.seller_id=uid))
 or exists(select 1 from public.returns r join public.orders o on o.id=r.order_id where (o.buyer_id=uid or o.seller_id=uid) and r.status not in ('completed','rejected','expired','cancelled')) then
 raise exception 'Finish outstanding orders, returns and payment obligations before requesting deletion'; end if;
end $$;


--
-- Name: auto_confirm_delivery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_confirm_delivery(p_order uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  pending public.delivery_auto_confirmations;
  o public.orders;
  stub_settlement boolean := false;
  stamped_at timestamptz := now();
begin
  select * into pending from public.delivery_auto_confirmations
   where order_id = p_order and confirmed_at is null
   for update;
  if not found or pending.confirm_at > stamped_at then return false; end if;

  select * into strict o from public.orders where id = p_order for update;
  if not public.delivery_auto_confirm_eligible(o.id) then return false; end if;

  -- The same obligation check as mark_order_received: a real order must
  -- have a transfer intent for the seller; only a stub-settled one may not.
  if not exists (select 1 from public.transfer_intents where order_id = o.id) then
    select exists(
      select 1 from public.payments p where p.order_id = o.id
      and p.provider = 'stub' and p.status = 'succeeded' and p.provider_reference is not null
      and p.amount_cents = o.total_cents and lower(p.currency) = lower(o.currency)
    ) into stub_settlement;
    if not stub_settlement then raise exception 'Seller transfer obligation is missing'; end if;
  end if;

  -- notify_on_order_status reads this to tell the seller why the order is
  -- delivered; it is local to the transaction and cleared straight after.
  perform set_config('drvn.delivery_source', 'auto_confirm', true);
  update public.orders
     set status = 'delivered', delivered_at = stamped_at, completed_at = stamped_at
   where id = o.id;
  perform set_config('drvn.delivery_source', '', true);

  update public.shipments
     set status = 'delivered', delivered_at = coalesce(delivered_at, stamped_at)
   where order_id = o.id and direction = 'outbound'
     and status in ('label_purchased', 'in_transit', 'out_for_delivery');

  insert into public.shipment_events (shipment_id, provider_event_ref, status, description, occurred_at)
  select s.id, 'drvn:auto-confirm', 'delivered',
         'Marked delivered automatically: no problem was reported within '
           || pending.after_days || ' days of dispatch',
         stamped_at
    from public.shipments s
   where s.order_id = o.id and s.direction = 'outbound' and s.status = 'delivered'
  on conflict do nothing;

  if not stub_settlement then
    update public.transfer_intents
       set available_at = coalesce(available_at, public.payout_available_at(o.id, stamped_at)),
           updated_at = now()
     where order_id = o.id and status = 'holding';
  end if;

  update public.delivery_auto_confirmations
     set confirmed_at = stamped_at, last_error = null
   where order_id = o.id;

  perform public.notify(
    o.buyer_id, 'receipt_auto_confirmed', 'marketplace',
    'We marked your order delivered',
    'No problem was reported, so the order is complete and the seller will be paid. If something is wrong, report it from the order.',
    '/orders/' || o.id, null
  );
  return true;
end;
$$;


--
-- Name: auto_confirm_untracked_deliveries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_confirm_untracked_deliveries(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  after_days integer;
  notice_days integer;
  run_id uuid := gen_random_uuid();
  started timestamptz := clock_timestamp();
  reminded integer := 0;
  confirmed integer := 0;
  failed integer := 0;
  candidate record;
  due timestamptz;
  days_left integer;
  summary jsonb;
begin
  select s.auto_confirm_after_days, s.auto_confirm_notice_days
    into after_days, notice_days
    from public.settlement_settings s
   where s.id;

  if after_days is not null then
    -- 1. Warn. The row is the "sent once" record: a second run finds it.
    for candidate in
      select o.id, o.buyer_id, o.shipped_at
        from public.orders o
       where o.status = 'shipped'
         and o.shipped_at <= now() - make_interval(days => after_days - notice_days)
         and not exists (select 1 from public.delivery_auto_confirmations a where a.order_id = o.id)
         and public.delivery_auto_confirm_eligible(o.id)
       order by o.shipped_at, o.id
       limit p_limit
    loop
      begin
        due := greatest(candidate.shipped_at + make_interval(days => after_days),
                        now() + make_interval(days => notice_days));
        insert into public.delivery_auto_confirmations (order_id, after_days, confirm_at)
        values (candidate.id, after_days, due)
        on conflict (order_id) do nothing;
        if found then
          days_left := ceil(extract(epoch from due - now()) / 86400)::integer;
          perform public.notify(
            candidate.buyer_id, 'receipt_due', 'marketplace',
            'Has your order arrived?',
            'Confirm receipt or report a problem. If we don''t hear from you, we''ll mark it delivered in '
              || days_left || case when days_left = 1 then ' day' else ' days' end
              || ' and the seller will be paid.',
            '/orders/' || candidate.id, null
          );
          reminded := reminded + 1;
        end if;
      exception when others then
        failed := failed + 1;
        raise warning 'auto-confirm reminder failed for order %: %', candidate.id, sqlerrm;
      end;
    end loop;

    -- 2. Confirm what is due and still eligible. Each order is its own
    --    subtransaction: one failure rolls back only that order.
    for candidate in
      select a.order_id
        from public.delivery_auto_confirmations a
       where a.confirmed_at is null
         and a.confirm_at <= now()
         and public.delivery_auto_confirm_eligible(a.order_id)
       order by a.confirm_at, a.order_id
       limit p_limit
    loop
      begin
        if public.auto_confirm_delivery(candidate.order_id) then
          confirmed := confirmed + 1;
        end if;
      exception when others then
        failed := failed + 1;
        update public.delivery_auto_confirmations
           set last_error = left(sqlerrm, 500)
         where order_id = candidate.order_id;
      end;
    end loop;
  end if;

  summary := jsonb_build_object(
    'enabled', after_days is not null,
    'after_days', after_days,
    'reminded', reminded,
    'confirmed', confirmed,
    'failed', failed
  );
  insert into public.worker_runs (id, family, status, started_at, finished_at, summary)
  values (run_id, 'deliveryAutoConfirm', case when failed > 0 then 'failed' else 'succeeded' end,
          started, clock_timestamp(), summary);
  return summary;
end;
$$;


--
-- Name: become_shop(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.become_shop() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid:=auth.uid();
  profile_kind text;
  had_shop_row boolean;
  applied boolean:=false;
begin
  if actor is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if not private.beta_member_eligible(actor,'seller') then
    raise exception 'Selling is limited to invited beta members' using errcode='42501';
  end if;

  select profile_type into profile_kind from public.profiles where id=actor for update;
  if not found then raise exception 'Profile not found'; end if;
  if profile_kind not in ('user','shop') then raise exception 'Profile cannot become a shop'; end if;
  select exists(select 1 from public.shop_profiles where profile_id=actor) into had_shop_row;

  insert into public.shop_profiles(profile_id) values(actor) on conflict(profile_id) do nothing;
  if profile_kind='user' then
    update public.profiles set profile_type='shop' where id=actor;
    applied:=true;
  end if;

  if not exists(
    select 1 from public.profiles p join public.shop_profiles s on s.profile_id=p.id
    where p.id=actor and p.profile_type='shop'
  ) then raise exception 'Shop conversion did not persist'; end if;

  return jsonb_build_object(
    'ok',true,
    'applied',applied,
    'replayed',not applied and had_shop_row,
    'repaired',not applied and not had_shop_row
  );
end $$;


--
-- Name: begin_admin_external_operation(uuid, text, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_admin_external_operation(p_actor uuid, p_action text, p_subject_type text, p_subject text, p_order uuid, p_reason text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare op text;
begin
 perform public.assert_admin_actor(p_actor);
 if length(trim(p_reason))=0 then raise exception 'Reason required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_action||':'||p_subject,0));
 select a.metadata->>'operationId' into op from public.admin_audit_log a
 where a.action=p_action and a.subject_id=p_subject::uuid and a.metadata->>'phase'='requested'
 and not exists(select 1 from public.admin_audit_log done where done.metadata->>'operationId'=a.metadata->>'operationId' and done.metadata->>'phase' in ('completed','reconciled'))
 order by a.created_at limit 1;
 if found then return jsonb_build_object('operationId',op,'reused',true); end if;
 op:=gen_random_uuid()::text;
 insert into public.admin_audit_log(actor_id,action,subject_type,subject_id,order_id,reason,metadata)
 values(p_actor,p_action,p_subject_type,p_subject::uuid,p_order,p_reason,p_metadata||jsonb_build_object('operationId',op,'phase','requested'));
 return jsonb_build_object('operationId',op,'reused',false);
end $$;


--
-- Name: begin_admin_mfa_recovery(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_admin_mfa_recovery(p_actor uuid, p_target uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare op uuid:=gen_random_uuid();
begin
 perform public.assert_admin_actor(p_actor);
 if p_actor=p_target or length(trim(p_reason))<10 then raise exception 'A separate operator and identity-verification reason are required'; end if;
 update public.admin_users set sessions_valid_after=clock_timestamp() where user_id=p_target;
 if not found then raise exception 'Recovery target is not an administrator'; end if;
 insert into public.admin_audit_log(actor_id,action,subject_type,subject_id,reason,metadata)
 values(p_actor,'admin.mfa_recovery','user',p_target,p_reason,jsonb_build_object('operationId',op,'phase','requested'));
 return op;
end $$;


--
-- Name: begin_not_received_refund(uuid, timestamp with time zone, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_not_received_refund(p_order uuid, p_disputed_at timestamp with time zone, p_reason text, p_requested_by text, p_actor_role text, p_dispute_outcome text, p_payment_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  v_key text;
begin
  if p_order is null or p_disputed_at is null then raise exception 'Order and case are required' using errcode = '22023'; end if;
  select * into o from public.orders where id = p_order for update;
  if not found then return jsonb_build_object('ok', false, 'ineligible', true, 'error', 'Order not found.'); end if;
  v_key := 'not_received:' || o.id || ':' || extract(epoch from p_disputed_at)::text;
  if exists (select 1 from public.refund_operations where request_key = v_key and status <> 'failed') then
    return public.begin_request_refund_operation(v_key, o.id, null, p_reason, p_requested_by, p_actor_role,
      true, p_dispute_outcome, p_payment_reference);
  end if;
  if o.disputed_at is distinct from p_disputed_at or not private.not_received_refund_due(o.id) then
    return jsonb_build_object('ok', false, 'ineligible', true,
      'error', 'This case is no longer due a not-received refund.');
  end if;
  return public.begin_request_refund_operation(v_key, o.id, null, p_reason, p_requested_by, p_actor_role,
    true, p_dispute_outcome, p_payment_reference);
end $$;


--
-- Name: begin_payout_deadline_refund(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_payout_deadline_refund(p_order uuid, p_reason text, p_requested_by text, p_actor_role text, p_dispute_outcome text, p_payment_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  v_base text;
  v_key text;
  v_n integer := 0;
  v_remaining integer;
begin
  if p_order is null then raise exception 'Order is required' using errcode = '22023'; end if;
  v_base := 'payout_deadline:' || p_order;

  select * into o from public.orders where id = p_order for update;
  if not found then
    return jsonb_build_object('ok', false, 'ineligible', true, 'error', 'Order not found.');
  end if;
  if not private.payout_deadline_open_claim(p_order) then
    return jsonb_build_object('ok', false, 'ineligible', true,
      'error', 'This order is not being cancelled by the payout deadline.');
  end if;

  -- The deadline's own refund, still in flight: adopt it.
  select ro.request_key into v_key
  from public.refund_operations ro
  where ro.order_id = p_order
    and (ro.request_key = v_base or starts_with(ro.request_key, v_base || ':'))
    and ro.status in ('requested', 'provider_pending', 'provider_succeeded',
                      'effects_pending', 'reversal_pending', 'recovery_required')
    and ro.effects_completed_at is null
  order by ro.created_at desc
  limit 1;
  if found then
    return public.begin_request_refund_operation(v_key, p_order, null, p_reason, p_requested_by,
      p_actor_role, false, p_dispute_outcome, p_payment_reference);
  end if;

  -- Any other refund still in flight: wait for it.
  if exists (select 1 from public.refund_operations ro
             where ro.order_id = p_order
               and ro.status in ('requested', 'provider_pending', 'provider_succeeded',
                                 'effects_pending', 'reversal_pending', 'recovery_required')
               and ro.effects_completed_at is null) then
    return jsonb_build_object('ok', false, 'waiting', true,
      'error', 'Another refund on this order is still being made; the full refund waits for it.');
  end if;

  v_remaining := o.total_cents - o.refunded_cents;
  if v_remaining <= 0 then
    return jsonb_build_object('ok', false, 'error', 'Nothing left to refund on this order.');
  end if;
  if o.status is distinct from 'paid' then
    -- Moved since the claim was handed out (a buyer's case): the claim waits
    -- until the order is back.
    return jsonb_build_object('ok', false, 'waiting', true, 'status', o.status,
      'error', 'The order is not waiting for its refund right now.');
  end if;

  loop
    v_key := v_base || case when v_n = 0 then '' else ':' || v_n end;
    exit when not exists (select 1 from public.refund_operations
                          where request_key = v_key and status <> 'failed');
    v_n := v_n + 1;
  end loop;

  return public.begin_request_refund_operation(v_key, p_order, v_remaining, p_reason, p_requested_by,
    p_actor_role, false, p_dispute_outcome, p_payment_reference);
end;
$$;


--
-- Name: begin_refund_operation(uuid, integer, text, text, text, boolean, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_refund_operation(p_order_id uuid, p_amount_cents integer, p_reason text, p_requested_by text, p_actor_role text, p_resolve_dispute boolean, p_dispute_outcome text, p_payment_reference text, p_refund_reference text DEFAULT NULL::text, p_external boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order     record;
  v_inflight  int;
  v_remaining int;
  v_amount    int;
  v_existing  record;
  v_op        public.refund_operations;
  v_key       text;
  v_failed    int;
begin
  -- Adopt an operation we already hold for this Stripe refund object.
  if p_refund_reference is not null then
    select id, status into v_existing
    from public.refund_operations
    where refund_reference = p_refund_reference;
    if found then
      return jsonb_build_object('ok', true, 'adopted', true,
        'operation_id', v_existing.id, 'status', v_existing.status);
    end if;
  end if;

  select id, total_cents, refunded_cents, currency
    into v_order
    from public.orders where id = p_order_id
    for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Order not found.');
  end if;

  select coalesce(sum(amount_cents), 0) into v_inflight
  from public.refund_operations
  where order_id = p_order_id
    and status in ('requested', 'provider_pending', 'provider_succeeded',
                   'effects_pending', 'reversal_pending', 'recovery_required')
    -- 20261007100200: only what is not yet in refunded_cents.
    and effects_completed_at is null;

  v_remaining := v_order.total_cents - v_order.refunded_cents - v_inflight;
  v_amount := coalesce(p_amount_cents, v_remaining);

  -- External refunds already happened at Stripe: book what's still bookable
  -- rather than refusing (stale webhook views can over-ask harmlessly).
  if p_external then
    v_amount := least(v_amount, v_remaining);
  end if;

  if v_amount <= 0 or v_remaining <= 0 then
    return jsonb_build_object('ok', false,
      'error', 'Nothing left to refund on this order (settled or in flight).');
  end if;
  if v_amount > v_remaining then
    return jsonb_build_object('ok', false,
      'error', 'Refund exceeds what''s left to refund on this order.');
  end if;

  -- Cumulative-deterministic (settled + reserved + this), so a crash-retry of
  -- the same in-flight operation reuses the key. A NEW operation after a
  -- terminally FAILED one at the same amount would collide (failed ops release
  -- their reservation but keep their key row) — those get a deterministic
  -- retry suffix: Stripe refused the previous request, so the retry is a new
  -- logical attempt and must not replay the refused call's key.
  v_key := 'refund:order:' || p_order_id || ':' || (v_order.refunded_cents + v_inflight + v_amount);
  select count(*) into v_failed
  from public.refund_operations
  where order_id = p_order_id and status = 'failed';
  if v_failed > 0 then
    v_key := v_key || ':r' || v_failed;
  end if;

  insert into public.refund_operations (
    order_id, payment_reference, amount_cents, currency, remaining_before_cents,
    reason, requested_by, actor_role, idempotency_key, refund_reference,
    status, external, resolve_dispute, dispute_outcome, provider_completed_at
  ) values (
    p_order_id, p_payment_reference, v_amount, v_order.currency, v_remaining,
    left(coalesce(p_reason, ''), 500), p_requested_by, p_actor_role,
    v_key,
    p_refund_reference,
    -- External refunds already exist at the provider — they enter the machine
    -- at effects_pending; app-initiated ones start at requested.
    case when p_external then 'effects_pending' else 'requested' end,
    p_external,
    coalesce(p_resolve_dispute, false),
    p_dispute_outcome,
    case when p_external then now() end
  ) returning * into v_op;

  return jsonb_build_object('ok', true, 'adopted', false,
    'operation_id', v_op.id, 'idempotency_key', v_op.idempotency_key,
    'amount_cents', v_op.amount_cents, 'status', v_op.status);
end;
$$;


--
-- Name: begin_refund_replacement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_refund_replacement(p_recovery uuid, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.payment_recoveries; a public.refund_lifecycle_adjustments;
 f public.refund_operations; proof public.refund_recredit_proofs;
 o public.orders; previous public.refund_operations; result_id uuid:=gen_random_uuid(); due integer; source text;
begin
 if not exists(select 1 from public.admin_users where user_id=p_actor and role='admin') then raise exception 'Administrator required'; end if;
 select * into strict r from public.payment_recoveries where id=p_recovery;
 -- Serialize all new reservations on this order, including ordinary refunds.
 select * into strict o from public.orders where id=r.order_id for update;
 select * into strict r from public.payment_recoveries where id=p_recovery for update;
 if r.kind<>'refund_late_failure' or r.status<>'open' then raise exception 'Open late-refund case required'; end if;
 select * into strict a from public.refund_lifecycle_adjustments where refund_reference=substring(r.recovery_key from length('refund-late-failure:')+1);
 select * into strict f from public.refund_operations where id=a.refund_operation_id for update;
 select * into strict proof from public.refund_recredit_proofs where adjustment_id=a.id and recovery_id=r.id;
 if f.order_id<>o.id or f.provider_status not in ('failed','canceled') then raise exception 'Failed refund identity required'; end if;
 select * into previous from public.refund_operations where replaces_adjustment_id=a.id order by created_at desc,id desc limit 1;
 if found then
  -- Never issue another refund for an uncertain, settled or late-failed attempt.
  if previous.status<>'failed' or previous.effects_completed_at is not null then return previous.id; end if;
  if previous.provider_status is null or previous.provider_status not in ('failed','canceled') then raise exception 'Reconcile the previous replacement before retrying'; end if;
 end if;
 if exists(select 1 from public.refund_operations where order_id=o.id and id<>f.id and status in
 ('requested','provider_pending','provider_succeeded','effects_pending','reversal_pending','recovery_required')) then
  raise exception 'Finish other refund operations before replacing this refund';
 end if;
 if exists(select 1 from public.payment_recoveries where order_id=o.id and kind='refund_lifecycle_unresolved' and status='open') then raise exception 'Reconcile other provider refund evidence before replacement'; end if;
 if o.refunded_cents+a.refund_amount_cents>o.total_cents then raise exception 'Replacement exceeds the remaining buyer obligation'; end if;
 if proof.amount_cents=0 and (o.transfer_reference is not null or exists(
  select 1 from public.transfer_intents where order_id=o.id and (status<>'cancelled' or provider_call_may_have_occurred or transfer_reference is not null)
 )) then raise exception 'A later or uncertain seller payout requires reconciliation before zero-obligation replacement'; end if;
 source:=case when proof.amount_cents>0 then proof.recredit_transfer_reference else null end;
 due:=case when source is null then 0 else
 least(o.total_cents-o.platform_fee_cents,round((o.refunded_cents+a.refund_amount_cents)::numeric*(o.total_cents-o.platform_fee_cents)/greatest(o.total_cents,1)))
 -least(o.total_cents-o.platform_fee_cents,round(o.refunded_cents::numeric*(o.total_cents-o.platform_fee_cents)/greatest(o.total_cents,1))) end;
 if proof.amount_cents>0 and due<>proof.amount_cents then
  raise exception 'Seller allocation changed; reconcile the partial-refund rounding before replacement';
 end if;
 -- Release only this definitively failed reservation, in the same transaction
 -- that creates its replacement. Keep all original provider evidence intact.
 update public.refund_operations set status='failed',updated_at=now() where id=f.id;
 insert into public.refund_operations(id,order_id,payment_reference,amount_cents,currency,remaining_before_cents,
 reason,requested_by,actor_role,idempotency_key,status,resolve_dispute,dispute_outcome,replaces_adjustment_id,replacement_transfer_reference,created_at)
 values(result_id,o.id,f.payment_reference,a.refund_amount_cents,f.currency,o.total_cents-o.refunded_cents,
 'Admin refund: Replacement for failed refund '||a.refund_reference,'admin:'||p_actor,'admin',
 'refund:replacement:'||result_id,'requested',f.resolve_dispute,f.dispute_outcome,a.id,source,clock_timestamp());
 return result_id;
end $$;


--
-- Name: begin_request_refund_operation(text, uuid, integer, text, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_request_refund_operation(p_request_key text, p_order_id uuid, p_amount_cents integer, p_reason text, p_requested_by text, p_actor_role text, p_resolve_dispute boolean, p_dispute_outcome text, p_payment_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_existing record;
  v_result jsonb;
begin
  if p_request_key is null or length(p_request_key) not between 1 and 200 then
    raise exception 'A refund request key is required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('refund-request:' || p_request_key, 0));

  select id, status, order_id into v_existing
  from public.refund_operations
  where request_key = p_request_key and status <> 'failed'
  order by created_at desc
  limit 1;
  if found then
    if v_existing.order_id is distinct from p_order_id then
      raise exception 'Refund request key belongs to another order' using errcode = '22023';
    end if;
    return jsonb_build_object('ok', true, 'adopted', true,
      'operation_id', v_existing.id, 'status', v_existing.status);
  end if;

  v_result := public.begin_refund_operation(
    p_order_id, p_amount_cents, p_reason, p_requested_by, p_actor_role,
    p_resolve_dispute, p_dispute_outcome, p_payment_reference, null, false
  );
  if (v_result->>'ok')::boolean and not coalesce((v_result->>'adopted')::boolean, false) then
    update public.refund_operations
    set request_key = p_request_key
    where id = (v_result->>'operation_id')::uuid;
  end if;
  return v_result;
end;
$$;


--
-- Name: bind_cart_checkout_payment(uuid, text, uuid[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_cart_checkout_payment(p_buyer uuid, p_idempotency_key text, p_orders uuid[], p_provider text, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  requested uuid[];
  saved public.purchase_attempts%rowtype;
  payment_count integer;
begin
  requested := array(select distinct unnest(coalesce(p_orders, array[]::uuid[])) order by 1);
  if p_buyer is null or p_idempotency_key is null or cardinality(requested) = 0
     or nullif(trim(coalesce(p_provider, '')), '') is null
     or nullif(trim(coalesce(p_reference, '')), '') is null then
    raise exception 'Invalid checkout payment binding' using errcode='22023';
  end if;

  select * into saved from public.purchase_attempts
   where idempotency_key = p_idempotency_key
   for update;
  if not found or saved.buyer_id is distinct from p_buyer then
    raise exception 'Checkout payment attempt is unavailable to this buyer' using errcode='42501';
  end if;
  if exists (
    (select unnest(requested)::text
     except
     select value ->> 'order_id' from jsonb_array_elements(coalesce(saved.result -> 'orders', '[]'::jsonb)))
    union all
    (select value ->> 'order_id' from jsonb_array_elements(coalesce(saved.result -> 'orders', '[]'::jsonb))
     except
     select unnest(requested)::text)
  ) then
    raise exception 'Checkout payment orders do not match the durable attempt' using errcode='42501';
  end if;

  perform 1 from public.orders where id = any(requested) order by id for update;
  if (select count(*) from public.orders where id = any(requested) and buyer_id = p_buyer)
     <> cardinality(requested) then
    raise exception 'Checkout payment buyer mismatch' using errcode='42501';
  end if;

  perform 1 from public.payments where order_id = any(requested) order by order_id for update;
  select count(*) into payment_count from public.payments where order_id = any(requested);
  if payment_count <> cardinality(requested) then
    raise exception 'Checkout payment rows are incomplete';
  end if;
  if exists (
    select 1 from public.payments
    where order_id = any(requested)
      and provider_reference is not null
      and (
        provider_reference <> p_reference
        or provider is not null and provider <> p_provider
      )
  ) then
    raise exception 'Checkout payment reference conflict' using errcode='23505';
  end if;

  update public.payments
  set provider = p_provider,
      provider_reference = p_reference
  where order_id = any(requested)
    and (provider_reference is null or provider_reference = p_reference);

  return jsonb_build_object('ok', true, 'mapped', payment_count);
end;
$$;


--
-- Name: bind_checkout_analytics(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_checkout_analytics(p_orders uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if auth.uid() is null then return; end if;
 update public.orders set analytics_consent_version=c.version from public.analytics_consents c
 where orders.id=any(p_orders) and orders.buyer_id=auth.uid() and orders.status in ('pending','requires_action')
 and c.user_id=auth.uid() and c.allowed and c.expires_at>now();
end $$;


--
-- Name: block_deleted_account_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_deleted_account_writes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if auth.uid() is not null
    and exists(select 1 from public.remediation_jobs where dedup_key='delete:'||auth.uid())
    and not exists(select 1 from public.account_deletion_requests where user_id=auth.uid() and outcome='temporary_financial_hold') then
 raise exception 'Account deletion is pending' using errcode='42501'; end if;
 return null;
end $$;


--
-- Name: bump_listing_view(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_listing_view(p_listing uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return;
  end if;

  -- One counted view per viewer per listing per hour.
  if not public.consume_rate_limit(
       'view:' || p_listing::text || ':' || auth.uid()::text, 1, interval '1 hour'
     ) then
    return;
  end if;

  update public.listings
  set view_count = coalesce(view_count, 0) + 1
  where id = p_listing and status in ('active', 'sold') and seller_id <> auth.uid();
end;
$$;


--
-- Name: capture_reconciliation_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_reconciliation_candidates() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
 insert into public.capture_checks(reference)
 select distinct p.provider_reference from public.payments p join public.orders o on o.id=p.order_id
 where p.provider='stripe' and p.provider_reference is not null and (
 o.status in ('pending','requires_action') or
 (o.status in ('paid','shipped','delivered','completed','disputed') and o.refunded_cents<o.total_cents and o.transfer_reference is null and not exists(select 1 from public.transfer_intents t where t.order_id=o.id)) or
 (o.status in ('cancelled','payment_failed') and p.status='succeeded' and not exists(select 1 from public.refund_operations r where r.order_id=o.id and r.purpose='late_capture')))
 on conflict(reference) do nothing;
 with due as(select reference from public.capture_checks where next_attempt_at<=now() order by next_attempt_at,reference for update skip locked limit 50),
 claimed as(update public.capture_checks c set next_attempt_at=now()+interval '15 minutes' from due where c.reference=due.reference returning c.reference)
 select coalesce(jsonb_agg(reference),'[]') into result from claimed;
 return result;
end $$;


--
-- Name: car_generation_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.car_generation_before_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_fits boolean;
begin
  v_fits := new.generation_id is not null and new.catalog_model_id is not null and exists (
    select 1 from public.vehicle_generations g
    where g.id = new.generation_id and g.model_id = new.catalog_model_id
      and (new.year is null or new.year between g.year_start and coalesce(g.year_end, 2100)));
  if v_fits and (tg_op = 'INSERT'
                 or new.generation_id is distinct from old.generation_id
                 or old.generation_source = 'owner') then
    new.generation_source := 'owner';
    return new;
  end if;
  new.generation_id := public.resolve_vehicle_generation(new.catalog_model_id, new.year);
  new.generation_source := case when new.generation_id is not null then 'resolved' end;
  return new;
end;
$$;


--
-- Name: car_search_doc(text, text, text, integer, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.car_search_doc(p_name text, p_make text, p_model text, p_year integer, p_tags text[], p_about text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ select concat_ws(' ', p_name, p_make, p_model, p_year::text, array_to_string(p_tags, ' '), p_about) $$;


--
-- Name: car_update_page(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.car_update_page(p_car uuid, p_limit integer DEFAULT 50, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, intro text, body jsonb, published_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id, p.title, p.intro, p.body, p.published_at
  from public.activity_posts p
  where p.car_id = p_car
    and p.published_at is not null
    and (p_before_at is null or p_before_id is null
         or (p.published_at, p.id) < (p_before_at, p_before_id))
  order by p.published_at desc, p.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 101);
$$;


--
-- Name: FUNCTION car_update_page(p_car uuid, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.car_update_page(p_car uuid, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid) IS 'One page of a car''s published updates, newest first from a (published_at, id) position (N60). At most 101 rows.';


--
-- Name: carry_on_seller_adjustment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.carry_on_seller_adjustment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if new.order_id is null or new.seller_id is null then
    return null;
  end if;
  if tg_op = 'UPDATE' and not (old.voided_at is null and new.voided_at is not null) then
    return null;
  end if;
  if tg_op = 'INSERT' and new.voided_at is not null then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('seller-carry-order:' || new.order_id::text, 0));
  select status into v_status from public.transfer_intents where order_id = new.order_id;
  if v_status is null or v_status not in ('transferred', 'cancelled') then
    return null;
  end if;
  if tg_op = 'INSERT' then
    perform public.record_seller_carry(new.seller_id, 'late_adjustment', new.amount_cents, new.order_id, new.id,
      'late:' || new.id::text);
  else
    perform public.record_seller_carry(new.seller_id, 'adjustment_void', -old.amount_cents, new.order_id, new.id,
      'void:' || new.id::text);
  end if;
  return null;
end;
$$;


--
-- Name: carry_on_transfer_intent_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.carry_on_transfer_intent_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order record;
  v_adjustments int;
  v_net int;
  v_previous int;
  v_seller uuid;
begin
  if new.status is not distinct from old.status then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('seller-carry-order:' || new.order_id::text, 0));
  select seller_id, total_cents, refunded_cents into v_order from public.orders where id = new.order_id;
  v_seller := coalesce(new.seller_id, v_order.seller_id);

  if new.status = 'cancelled' and v_order.total_cents is not null then
    -- The same payable arithmetic as the transfer worker and
    -- complete_transfer_intent: share less the refund's share, plus labels.
    select coalesce(sum(amount_cents), 0)::int into v_adjustments
      from public.seller_adjustments
     where order_id = new.order_id and voided_at is null;
    v_net := new.amount_cents
      - case
          when v_order.total_cents <= 0 or new.amount_cents <= 0 then 0
          else least(new.amount_cents,
            round((v_order.refunded_cents::numeric * new.amount_cents) / v_order.total_cents)::int)
        end
      + v_adjustments;
    if v_net < 0 then
      perform public.record_seller_carry(v_seller, 'uncollected', v_net, new.order_id, null,
        'uncollected:' || new.order_id::text);
    end if;
  elsif old.status = 'cancelled' then
    -- 20261007100400: every 'uncollected' entry of the order — the one made
    -- at cancellation and any a later refund added — not only the first.
    select coalesce(sum(amount_cents), 0)::int into v_previous
      from public.seller_carry_entries
     where order_id = new.order_id and kind = 'uncollected';
    if v_previous <> 0 then
      perform public.record_seller_carry(v_seller, 'uncollected_reversed', -v_previous, new.order_id, null,
        'uncollected-reversed:' || new.order_id::text);
    end if;
  end if;

  if new.status = 'transferred' and coalesce(new.dispatch_carry_cents, 0) > 0 then
    perform public.record_seller_carry(v_seller, 'collected', new.dispatch_carry_cents, new.order_id, null,
      'collected:' || new.order_id::text);
  end if;
  return null;
end;
$$;


--
-- Name: charge_cents_in_bounds(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.charge_cents_in_bounds(p_cents bigint) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_cents between 50 and 99999999;
$$;


--
-- Name: check_photo_rewrite(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_photo_rewrite(p_bucket text, p_path text, p_token uuid, p_object uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_object uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || p_bucket || '/' || p_path, 0));
  select o.id into v_object from storage.objects o where o.bucket_id = p_bucket and o.name = p_path;
  if v_object is null
     or exists (select 1 from private.media_deletion_claims c where c.bucket = p_bucket and c.path = p_path) then
    return 'gone';
  end if;
  if v_object <> p_object or not exists (
    select 1 from private.media_rewrite_claims r
     where r.bucket = p_bucket and r.path = p_path and r.token = p_token
       and r.claimed_at > now() - interval '10 minutes') then
    return 'lost';
  end if;
  return 'current';
end;
$$;


--
-- Name: claim_listing_creation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_listing_creation(p_request uuid, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_request private.listing_creation_requests%rowtype;
  v_inserted integer;
begin
  if v_actor is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if not exists (
       select 1 from public.profiles p
       where p.id = v_actor and p.suspended_at is null
     )
     or not private.beta_member_eligible(v_actor, 'seller') then
    raise exception 'Selling is unavailable for this account' using errcode = '42501';
  end if;
  if p_request is null or coalesce(p_payload_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid listing creation request' using errcode = '22023';
  end if;

  insert into private.listing_creation_requests(seller_id, request_id, payload_hash)
  values(v_actor, p_request, p_payload_hash)
  on conflict(seller_id, request_id) do nothing;
  get diagnostics v_inserted = row_count;

  select * into strict v_request
  from private.listing_creation_requests
  where seller_id = v_actor and request_id = p_request
  for update;

  -- A claim that never produced a listing was refused or abandoned before
  -- anything committed (the listing and its completion commit together), so
  -- a changed request may take it over: same listing id, new details. Once
  -- the listing exists the request is spent on those details, and a
  -- different payload is still refused, so a completed request replays and
  -- never re-edits. The row lock above waits for any save of this request in
  -- flight, and re-reads it after.
  if v_request.payload_hash <> p_payload_hash then
    if v_request.completed_at is not null
       or exists (select 1 from public.listings l where l.id = v_request.listing_id) then
      raise exception 'Listing request was already used with different details'
        using errcode = '22023';
    end if;
    update private.listing_creation_requests r
    set payload_hash = p_payload_hash
    where r.seller_id = v_actor and r.request_id = p_request;
    v_request.payload_hash := p_payload_hash;
  end if;

  return jsonb_build_object(
    'listing_id', v_request.listing_id,
    'completed', v_request.completed_at is not null,
    'fresh', v_inserted = 1
  );
end;
$_$;


--
-- Name: claim_media_deletion(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_media_deletion(p_bucket text, p_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_claim private.media_deletion_claims%rowtype;
  v_token uuid := gen_random_uuid();
begin
  if p_bucket is null or p_bucket !~ '^[a-z0-9_-]{1,63}$' or not coalesce(private.media_path_ok(p_path), false) then
    return jsonb_build_object('status', 'invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || p_bucket || '/' || p_path, 0));
  select * into v_claim from private.media_deletion_claims where bucket = p_bucket and path = p_path;
  if found and v_claim.state = 'done' then
    return jsonb_build_object('status', 'gone');
  end if;
  if found and v_claim.claimed_at > now() - interval '10 minutes' then
    return jsonb_build_object('status', 'busy');
  end if;
  -- N627: the metadata job is re-encoding this object right now.
  if exists (select 1 from private.media_rewrite_claims r
              where r.bucket = p_bucket and r.path = p_path and r.claimed_at > now() - interval '10 minutes') then
    return jsonb_build_object('status', 'busy');
  end if;
  if found then
    -- Lease takeover. The previous holder neither completed nor released, so
    -- its delete may have happened: the claim stays and becomes uncertain
    -- (no reference could have been added while it was held).
    update private.media_deletion_claims
       set token = v_token, claimed_at = now(), maybe_deleted = true
     where bucket = p_bucket and path = p_path;
    return jsonb_build_object('status', 'claimed', 'token', v_token, 'maybe_deleted', true);
  end if;
  -- A fresh statement after the lock: it sees any reference committed by a
  -- writer that held the lock before us.
  if public.media_object_referenced(p_bucket, p_path) then
    return jsonb_build_object('status', 'referenced');
  end if;
  insert into private.media_deletion_claims (bucket, path, token, state, claimed_at)
    values (p_bucket, p_path, v_token, 'active', now());
  return jsonb_build_object('status', 'claimed', 'token', v_token, 'maybe_deleted', false);
end;
$_$;


--
-- Name: claim_order_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_order_emails(p_limit integer) RETURNS TABLE(id uuid, attempt integer, recipient_id uuid, order_id uuid, kind text, email text, guest boolean, buyer boolean, notification_prefs jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_row record;
  v_email text;
  v_confirmed boolean;
  v_buyer_id uuid;
  v_seller_id uuid;
  v_party boolean;
  v_buyer boolean;
  v_reason text;
  v_lease uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 10), 1), 50);
  v_claimed integer := 0;
begin
  for v_row in
    select q.id, q.recipient_id, q.order_id, q.kind, q.attempts, q.created_at, q.provider_held_at
      from public.order_email_outbox q
     where (q.status = 'pending' and q.next_attempt_at <= now())
        or (q.status = 'sending' and q.lease_expires_at < now())
     order by q.next_attempt_at, q.created_at, q.id
     limit 500
     for update of q skip locked
  loop
    exit when v_claimed >= v_limit;
    select nullif(btrim(u.email), ''), u.confirmed_at is not null into v_email, v_confirmed
      from auth.users u where u.id = v_row.recipient_id;
    -- "Is a party" and "is the buyer" are two questions, and neither may be
    -- answered by a null: an order whose buyer's account is gone has a null
    -- buyer_id, and its seller is still a party (review of #204).
    v_buyer_id := null;
    v_seller_id := null;
    select o.buyer_id, o.seller_id into v_buyer_id, v_seller_id from public.orders o where o.id = v_row.order_id;
    v_buyer := v_row.recipient_id is not distinct from v_buyer_id;
    v_party := v_buyer or v_row.recipient_id is not distinct from v_seller_id;

    v_reason := case
      when v_row.created_at < now() - case when v_row.provider_held_at is not null then interval '72 hours' else interval '24 hours' end then 'stale'
      when exists (select 1 from public.profiles p where p.id = v_row.recipient_id and p.suspended_at is not null)
        or exists (select 1 from public.account_deletion_requests r where r.user_id = v_row.recipient_id
                    and (r.outcome <> 'temporary_financial_hold' or r.scrubbed_at is not null)) then 'account_closed'
      when not v_party then 'not_a_party'
      when v_email is null then 'no_address'
      -- An unconfirmed address is a guest's: only the buyer's own emails.
      when not v_confirmed and not (v_buyer and v_row.kind in ('order_paid', 'order_shipped', 'receipt_auto_confirmed', 'order_refunded', 'order_partially_refunded', 'order_cancelled', 'dispute_resolved', 'admin_action')) then 'no_address'
    end;

    if v_reason is not null then
      update public.order_email_outbox
         set status = 'skipped', skip_reason = v_reason, lease_id = null, lease_expires_at = null, updated_at = now()
       where order_email_outbox.id = v_row.id;
      continue;
    end if;

    -- Twenty an hour to one person: the rest wait half an hour, in order.
    if (select count(*) from public.order_email_outbox s
         where s.recipient_id = v_row.recipient_id
           and ((s.status = 'sent' and s.sent_at > now() - interval '1 hour') or s.status = 'sending')) >= 20 then
      update public.order_email_outbox
         set status = 'pending', next_attempt_at = now() + interval '30 minutes', lease_id = null, lease_expires_at = null, updated_at = now()
       where order_email_outbox.id = v_row.id;
      continue;
    end if;

    v_lease := gen_random_uuid();
    update public.order_email_outbox
       set status = 'sending', attempts = order_email_outbox.attempts + 1, lease_id = v_lease,
           lease_expires_at = now() + interval '5 minutes', updated_at = now()
     where order_email_outbox.id = v_row.id;

    id := v_row.id;
    attempt := v_row.attempts + 1;
    recipient_id := v_row.recipient_id;
    order_id := v_row.order_id;
    kind := v_row.kind;
    email := v_email;
    guest := not v_confirmed;
    buyer := v_buyer;
    select coalesce(p.notification_prefs, '{}'::jsonb) into notification_prefs from public.profiles p where p.id = v_row.recipient_id;
    v_claimed := v_claimed + 1;
    return next;
  end loop;
end;
$$;


--
-- Name: claim_outbound_label_void(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_outbound_label_void(p_shipment uuid, p_worker uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  saved public.outbound_label_void_requests;
  observed_at timestamptz:=now();
begin
  if p_worker is null then raise exception 'Worker identity required'; end if;
  select * into strict saved from public.outbound_label_void_requests where shipment_id=p_shipment for update;
  if saved.status='completed' then
    return jsonb_build_object('action','completed','request',to_jsonb(saved),'observation_started_at',observed_at);
  elsif saved.status='rejected' then
    return jsonb_build_object('action','rejected','request',to_jsonb(saved),'observation_started_at',observed_at);
  elsif saved.status='provider_pending' and saved.claim_owner=p_worker and saved.claim_expires_at>now() then
    return jsonb_build_object('action','dispatch','request',to_jsonb(saved),'observation_started_at',observed_at);
  elsif saved.status='requested' or (
    saved.status='provider_pending' and saved.claim_expires_at<=now()
    and saved.provider_state='not_requested' and saved.provider_observed_at>=saved.claim_expires_at
  ) then
    update public.outbound_label_void_requests
    set status='provider_pending',claim_owner=p_worker,claim_expires_at=now()+interval '2 minutes',
        attempts=attempts+1,provider_state=null,provider_observed_at=null,last_error=null,updated_at=now()
    where shipment_id=p_shipment returning * into saved;
    return jsonb_build_object('action','dispatch','request',to_jsonb(saved),'observation_started_at',observed_at);
  end if;
  return jsonb_build_object('action','reconcile','request',to_jsonb(saved),'observation_started_at',observed_at);
end $$;


--
-- Name: claim_payout_deadline_cancellations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_payout_deadline_cancellations(p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_restricted integer := 0;
  v_paused integer := 0;
  v_claimed integer := 0;
  v_limit integer := greatest(coalesce(p_limit, 5), 1);
  v_order record;
  v_listing_ids uuid[];
  v_status text;
  v_shipped timestamptz;
  v_payable boolean;
  v_open jsonb;
begin
  if not private.payout_readiness_required() then
    return jsonb_build_object('restricted', 0, 'paused', 0, 'claimed', 0, 'orders', '[]'::jsonb);
  end if;

  -- Sellers with a sale at least 14 days old, still unpaid and payouts off.
  with overdue as (
    select distinct o.seller_id
    from public.transfer_intents ti
    join public.orders o on o.id = ti.order_id
    join public.profiles p on p.id = o.seller_id
    where ti.created_at <= now() - interval '14 days'
      and ti.status in ('holding', 'ready', 'blocked_unpayable', 'failed')
      and o.status not in ('refunded', 'cancelled')
      and not p.payouts_enabled
  ), restricted as (
    update public.profiles p
    set payout_restricted_at = now()
    where p.id in (select seller_id from overdue)
      and p.payout_restricted_at is null
      and not p.payouts_enabled
    returning p.id
  )
  select count(*) into v_restricted from restricted;

  -- 20261108110000: the restricted sellers' profiles first, then their
  -- listings. Payouts enabled (an update of the profile, whose trigger then
  -- restores the listings) either committed before this lock, and the
  -- profile is skipped here as payable, or waits for these pauses and then
  -- restores them.
  perform 1 from public.profiles p
  where p.payout_restricted_at is not null and not p.payouts_enabled
  order by p.id
  for share;

  -- Their live listings come down. Every pass, so a part released from an
  -- expired checkout back to active doesn't stay on sale.
  with live as (
    select l.id, l.seller_id
    from public.listings l
    join public.profiles p on p.id = l.seller_id
    where l.status = 'active'
      and p.payout_restricted_at is not null
      and not p.payouts_enabled
    order by l.id
    for update of l
  ), recorded as (
    insert into private.payout_deadline_paused_listings (listing_id, seller_id)
    select id, seller_id from live
    on conflict (listing_id) do nothing
    returning listing_id
  )
  select count(*) into v_paused from recorded;
  update public.listings l
  set status = 'paused'
  from private.payout_deadline_paused_listings pl
  where pl.listing_id = l.id and l.status = 'active'
    and exists (select 1 from public.profiles p
                where p.id = l.seller_id and p.payout_restricted_at is not null and not p.payouts_enabled);

  -- Claim each overdue order that hasn't been dispatched. Profile, then
  -- listing, then order (docs/decisions/agent-foundations.md §4), and
  -- re-read under the locks, so a dispatch or a payouts update that won the
  -- race keeps its order.
  for v_order in
    select o.id, o.seller_id
    from public.transfer_intents ti
    join public.orders o on o.id = ti.order_id
    join public.profiles p on p.id = o.seller_id
    where ti.created_at <= now() - interval '14 days'
      and ti.status in ('holding', 'ready', 'blocked_unpayable', 'failed')
      and o.status = 'paid'
      and o.shipped_at is null
      and not p.payouts_enabled
      and not exists (select 1 from private.payout_deadline_cancellations c where c.order_id = o.id)
    order by ti.created_at
    limit v_limit
  loop
    select p.payouts_enabled into v_payable from public.profiles p where p.id = v_order.seller_id for share;
    select coalesce(array_agg(oi.listing_id order by oi.listing_id), array[]::uuid[])
      into v_listing_ids
    from public.order_items oi where oi.order_id = v_order.id and oi.listing_id is not null;
    perform 1 from public.listings where id = any(v_listing_ids) order by id for update;
    select o.status, o.shipped_at into v_status, v_shipped
    from public.orders o where o.id = v_order.id for update;
    if v_status = 'paid' and v_shipped is null and not coalesce(v_payable, false) then
      insert into private.payout_deadline_cancellations (order_id, seller_id)
      values (v_order.id, v_order.seller_id)
      on conflict (order_id) do nothing;
      if found then v_claimed := v_claimed + 1; end if;
    end if;
  end loop;

  -- The open claims due now, oldest due first. A claim on an order that
  -- moved elsewhere (a buyer's dispute) waits until it is back, keeping its
  -- place. Each claim handed out is pushed back (5, 10, 20 ... minutes, at
  -- most 6 hours) before the worker tries it, so one that keeps failing
  -- can't hold the batch, and a worker that dies mid-pass loses nothing.
  -- skip locked: two passes never take the same claim.
  with due as (
    select c.order_id
    from private.payout_deadline_cancellations c
    join public.orders o on o.id = c.order_id
    where c.settled_at is null
      and o.status in ('paid', 'refunded')
      and c.next_attempt_at <= now()
    order by c.next_attempt_at, c.claimed_at, c.order_id
    limit v_limit
    for update of c skip locked
  ), handed as (
    update private.payout_deadline_cancellations c
    set attempts = c.attempts + 1,
        last_attempt_at = now(),
        next_attempt_at = now() + least(interval '5 minutes' * power(2, least(c.attempts, 7))::integer,
                                        interval '6 hours')
    from due
    where c.order_id = due.order_id
    returning c.order_id, c.claimed_at, c.attempts
  )
  select coalesce(jsonb_agg(jsonb_build_object('order_id', h.order_id, 'status', o.status, 'attempt', h.attempts)
                            order by h.claimed_at, h.order_id), '[]'::jsonb)
    into v_open
  from handed h
  join public.orders o on o.id = h.order_id;

  return jsonb_build_object('restricted', v_restricted, 'paused', v_paused, 'claimed', v_claimed, 'orders', v_open);
end;
$$;


--
-- Name: claim_photo_rewrite(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_photo_rewrite(p_bucket text, p_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_deletion private.media_deletion_claims%rowtype;
  v_lease private.media_rewrite_claims%rowtype;
  v_object uuid;
  v_token uuid := gen_random_uuid();
begin
  if not coalesce(private.photo_scrub_bucket(p_bucket), false) or not coalesce(private.media_path_ok(p_path), false) then
    return jsonb_build_object('status', 'invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || p_bucket || '/' || p_path, 0));
  select * into v_lease from private.media_rewrite_claims where bucket = p_bucket and path = p_path;
  if found and v_lease.claimed_at > now() - interval '10 minutes' then
    return jsonb_build_object('status', 'busy');
  end if;
  select o.id into v_object from storage.objects o where o.bucket_id = p_bucket and o.name = p_path;
  -- A lapsed lease whose object has another identity: an earlier run's write
  -- recreated a deleted photo and stopped before deleting it again.
  if v_lease.path is not null and v_object is not null and v_object <> v_lease.object_id then
    update private.media_rewrite_claims set token = v_token, claimed_at = now()
     where bucket = p_bucket and path = p_path;
    return jsonb_build_object('status', 'recreated', 'token', v_token, 'object_id', v_lease.object_id);
  end if;
  if v_object is null then
    delete from private.media_rewrite_claims where bucket = p_bucket and path = p_path;
    return jsonb_build_object('status', 'gone');
  end if;
  select * into v_deletion from private.media_deletion_claims where bucket = p_bucket and path = p_path;
  if found and v_deletion.state = 'done' then
    -- A tombstone never hides a live object: the cleanup deleted this path
    -- for good (and no reference may name it again), so an object here
    -- exists only because a late write recreated it. The job deletes it.
    insert into private.media_rewrite_claims (bucket, path, token, object_id, claimed_at)
    values (p_bucket, p_path, v_token, v_object, now())
    on conflict (bucket, path) do update set token = excluded.token, claimed_at = excluded.claimed_at;
    return jsonb_build_object('status', 'recreated', 'token', v_token,
                              'object_id', coalesce(v_lease.object_id, v_object));
  end if;
  if found then
    return jsonb_build_object('status', 'busy');
  end if;
  insert into private.media_rewrite_claims (bucket, path, token, object_id, claimed_at)
  values (p_bucket, p_path, v_token, v_object, now())
  on conflict (bucket, path) do update
    set token = excluded.token, object_id = excluded.object_id, claimed_at = excluded.claimed_at;
  return jsonb_build_object('status', 'claimed', 'token', v_token, 'object_id', v_object);
end;
$$;


--
-- Name: claim_refund_replacement_provider(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_refund_replacement_provider(p_operation uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare op public.refund_operations; previous_status text; o public.orders; proof public.refund_recredit_proofs; due integer;
begin
 select * into strict op from public.refund_operations where id=p_operation;
 select * into strict o from public.orders where id=op.order_id for update;
 select * into strict op from public.refund_operations where id=p_operation for update;
 if op.replaces_adjustment_id is null then raise exception 'Linked replacement required'; end if;
 if op.status not in ('requested','provider_pending') then return 'stopped'; end if;
 if exists(select 1 from public.payment_recoveries where order_id=op.order_id and kind='refund_lifecycle_unresolved' and status='open') then return 'recovery_required'; end if;
 if exists(select 1 from public.refund_operations where order_id=op.order_id and id<>op.id and status in ('requested','provider_pending','provider_succeeded','effects_pending','reversal_pending','recovery_required')) then return 'recovery_required'; end if;
 select * into strict proof from public.refund_recredit_proofs where adjustment_id=op.replaces_adjustment_id;
 if o.refunded_cents+op.amount_cents>o.total_cents then return 'recovery_required'; end if;
 due:=case when o.transfer_reference is null then 0 else
 least(o.total_cents-o.platform_fee_cents,round((o.refunded_cents+op.amount_cents)::numeric*(o.total_cents-o.platform_fee_cents)/greatest(o.total_cents,1)))
 -least(o.total_cents-o.platform_fee_cents,round(o.refunded_cents::numeric*(o.total_cents-o.platform_fee_cents)/greatest(o.total_cents,1))) end;
 if due<>proof.amount_cents then return 'recovery_required'; end if;
 if proof.amount_cents=0 and exists(select 1 from public.transfer_intents where order_id=o.id and (status<>'cancelled' or provider_call_may_have_occurred or transfer_reference is not null)) then return 'recovery_required'; end if;
 previous_status:=op.status;
 update public.refund_operations set status='provider_pending',updated_at=now() where id=op.id;
 return previous_status;
end $$;


--
-- Name: claim_refund_reversal(uuid, text, text, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_refund_reversal(p_operation uuid, p_worker text, p_transfer_reference text, p_amount_cents integer, p_currency text, p_operation_key text, p_lease_seconds integer DEFAULT 300) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op public.refund_operations;
  v_currency text := lower(p_currency);
begin
  if p_operation is null or nullif(p_worker, '') is null
     or nullif(p_transfer_reference, '') is null
     or p_amount_cents is null or p_amount_cents <= 0
     or nullif(v_currency, '') is null
     or nullif(p_operation_key, '') is null then
    raise exception 'Invalid reversal dispatch';
  end if;

  select * into v_op
  from public.refund_operations
  where id = p_operation
  for update;
  if not found then return 'missing'; end if;

  if v_op.status = 'completed' and v_op.reversal_reference is not null then
    if v_op.reversal_operation_key = p_operation_key
       and v_op.reversal_transfer_reference = p_transfer_reference
       and v_op.reversal_amount_cents = p_amount_cents
       and v_op.reversal_currency = v_currency then
      return 'completed';
    end if;
    return 'conflict';
  end if;
  if v_op.status <> 'reversal_pending' then return 'stopped'; end if;

  if v_op.reversal_operation_key is not null and (
    v_op.reversal_operation_key <> p_operation_key
    or v_op.reversal_transfer_reference <> p_transfer_reference
    or v_op.reversal_amount_cents <> p_amount_cents
    or v_op.reversal_currency <> v_currency
  ) then
    return 'conflict';
  end if;

  if v_op.reversal_locked_by is not null
     and v_op.reversal_locked_by <> p_worker
     and v_op.reversal_lease_expires_at >= now() then
    return 'busy';
  end if;

  update public.refund_operations
  set reversal_operation_key = p_operation_key,
      reversal_transfer_reference = p_transfer_reference,
      reversal_amount_cents = p_amount_cents,
      reversal_currency = v_currency,
      reversal_call_may_have_occurred = true,
      reversal_locked_by = p_worker,
      reversal_lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
      reversal_last_attempt_at = now(),
      updated_at = now()
  where id = p_operation;
  return 'claimed';
end;
$$;


--
-- Name: claim_remediation_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_remediation_jobs(p_kind text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 with exhausted as (update public.remediation_jobs set status='failed',last_error='Worker lease expired at retry limit',locked_until=null where kind=p_kind and status='processing' and locked_until<now() and attempts>=10 returning id),
 due as (select id from public.remediation_jobs where kind=p_kind and attempts<10 and next_attempt_at<=now()
 and (status='pending' or (status='processing' and locked_until<now())) order by next_attempt_at,id for update skip locked limit least(greatest(p_limit,1),50)),
 claimed as (update public.remediation_jobs j set status='processing',attempts=attempts+1,lease_id=gen_random_uuid(),locked_until=now()+interval '2 minutes'
 from due where j.id=due.id returning j.*) select coalesce(jsonb_agg(claimed),'[]'::jsonb) from claimed;
$$;


--
-- Name: claim_saved_search_digests(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_saved_search_digests(p_limit integer DEFAULT 50, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(digest_id uuid, attempt integer, recipient text, search_name text, href text, match_count integer, items jsonb, digest_day date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_row record;
  v_reason text;
  v_email text;
  v_attempt integer;
  v_lease interval := make_interval(secs => least(greatest(coalesce(p_lease_seconds, 300), 30), 3600));
begin
  update public.saved_search_email_digests d
     set status = 'failed', last_error = coalesce(d.last_error, 'send lease expired'), updated_at = now()
   where d.status = 'sending' and d.next_attempt_at <= now() and d.attempts >= 25;

  for v_row in
    select d.id, d.search_name, d.href, d.match_count, d.items, d.digest_day,
           s.alert, s.user_id, p.suspended_at
    from public.saved_search_email_digests d
    join public.saved_searches s on s.id = d.saved_search_id
    left join public.profiles p on p.id = s.user_id
    where d.status in ('pending', 'sending')
      and d.next_attempt_at <= now()
      and d.digest_day = private.saved_search_digest_day(now())
    order by d.next_attempt_at, d.id
    limit least(greatest(coalesce(p_limit, 50), 1), 200)
    for update of d skip locked
  loop
    v_email := null;
    select u.email into v_email from auth.users u
    where u.id = v_row.user_id and u.confirmed_at is not null and nullif(btrim(u.email), '') is not null;

    v_reason := case
      when not v_row.alert then 'alert_off'
      when v_row.suspended_at is not null
        or exists (select 1 from public.account_deletion_requests r where r.user_id = v_row.user_id) then 'account_closed'
      when not private.saved_search_emails_enabled(v_row.user_id) then 'opted_out'
      when v_email is null then 'no_address'
    end;

    if v_reason is not null then
      update public.saved_search_email_digests
         set status = 'skipped', skip_reason = v_reason, updated_at = now()
       where id = v_row.id;
      continue;
    end if;

    update public.saved_search_email_digests
       set status = 'sending', attempts = attempts + 1, next_attempt_at = now() + v_lease, updated_at = now()
     where id = v_row.id
    returning attempts into v_attempt;

    digest_id := v_row.id;
    attempt := v_attempt;
    recipient := v_email;
    search_name := v_row.search_name;
    href := v_row.href;
    match_count := v_row.match_count;
    items := v_row.items;
    digest_day := v_row.digest_day;
    return next;
  end loop;
end;
$$;


--
-- Name: claim_search_job_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_search_job_batch(p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
 -- Serialize claim selection only, never hold a transaction during HTTP work.
 perform pg_advisory_xact_lock(hashtextextended('search-job-claim', 0));
 update public.remediation_jobs set status = 'failed', last_error = 'Search lease retry limit reached', locked_until = null
  where kind = 'search' and status = 'processing' and locked_until < now() and attempts >= 10;
 with candidates as (
   select distinct on (j.payload->>'entity', j.payload->>'id') j.payload->>'entity' as entity, j.payload->>'id' as target, j.next_attempt_at, j.id
   from public.remediation_jobs j
   where j.kind = 'search' and j.attempts < 10 and j.next_attempt_at <= now()
     and (j.status = 'pending' or (j.status = 'processing' and j.locked_until < now()))
     and not exists (select 1 from public.remediation_jobs active
                      where active.kind = 'search' and active.status = 'processing' and active.locked_until > now()
                        and active.payload->>'entity' = j.payload->>'entity' and active.payload->>'id' = j.payload->>'id')
   order by j.payload->>'entity', j.payload->>'id', j.created_at, j.id
 ),
 due as (select entity, target from candidates order by next_attempt_at, id limit least(greatest(coalesce(p_limit, 10), 1), 1000)),
 claimed as (
   update public.remediation_jobs j
      set status = 'processing', attempts = attempts + 1, lease_id = gen_random_uuid(), locked_until = now() + interval '2 minutes'
     from due
    where j.kind = 'search' and j.payload->>'entity' = due.entity and j.payload->>'id' = due.target
      and j.attempts < 10 and j.next_attempt_at <= now()
      and (j.status = 'pending' or (j.status = 'processing' and j.locked_until < now()))
   returning j.*)
 select coalesce(jsonb_agg(claimed), '[]') into result from claimed;
 return result;
end
$$;


--
-- Name: claim_search_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_search_jobs() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
 -- Serialize claim selection only, never hold a transaction during HTTP work.
 perform pg_advisory_xact_lock(hashtextextended('search-job-claim',0));
 update public.remediation_jobs set status='failed',last_error='Search lease retry limit reached',locked_until=null where kind='search' and status='processing' and locked_until<now() and attempts>=10;
 with candidates as (
 select distinct on (j.payload->>'entity',j.payload->>'id') j.id,j.next_attempt_at
 from public.remediation_jobs j where j.kind='search' and j.attempts<10 and j.next_attempt_at<=now()
 and (j.status='pending' or (j.status='processing' and j.locked_until<now()))
 and not exists(select 1 from public.remediation_jobs active where active.kind='search' and active.status='processing' and active.locked_until>now() and active.payload->>'entity'=j.payload->>'entity' and active.payload->>'id'=j.payload->>'id')
 order by j.payload->>'entity',j.payload->>'id',j.created_at,j.id
 ), due as(select id from candidates order by next_attempt_at,id limit 10),
 claimed as(update public.remediation_jobs j set status='processing',attempts=attempts+1,lease_id=gen_random_uuid(),locked_until=now()+interval '2 minutes' from due where j.id=due.id returning j.*)
 select coalesce(jsonb_agg(claimed),'[]') into result from claimed;
 return result;
end $$;


--
-- Name: seller_carry_payouts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.seller_carry_payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seller_id uuid,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    last_error text,
    locked_by text,
    lease_expires_at timestamp with time zone,
    destination text,
    provider_call_may_have_occurred boolean DEFAULT false NOT NULL,
    transfer_reference text,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT seller_carry_payouts_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT seller_carry_payouts_currency_check CHECK ((currency = 'USD'::text)),
    CONSTRAINT seller_carry_payouts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'paid'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: claim_seller_carry_payouts(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_seller_carry_payouts(p_worker text, p_batch integer, p_lease_seconds integer, p_max_attempts integer) RETURNS SETOF public.seller_carry_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_worker is null or length(p_worker) = 0 or coalesce(p_lease_seconds, 0) <= 0 then
    raise exception 'Invalid carry payout claim';
  end if;
  return query
  with due as (
    select p.id
      from public.seller_carry_payouts p
     where (p.status in ('pending', 'failed')
            and p.attempts < p_max_attempts
            and (p.next_attempt_at is null or p.next_attempt_at <= now()))
        or (p.status = 'processing' and p.lease_expires_at <= now())
     order by p.created_at
     limit greatest(1, least(coalesce(p_batch, 1), 50))
     for update skip locked
  )
  update public.seller_carry_payouts p
     set status = 'processing',
         locked_by = p_worker,
         lease_expires_at = now() + make_interval(secs => p_lease_seconds),
         updated_at = now()
    from due
   where p.id = due.id
  returning p.*;
end;
$$;


--
-- Name: transfer_intents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transfer_intents (
    order_id uuid NOT NULL,
    seller_id uuid,
    amount_cents integer NOT NULL,
    currency text NOT NULL,
    status text DEFAULT 'holding'::text NOT NULL,
    available_at timestamp with time zone,
    transfer_reference text,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_transaction text,
    locked_at timestamp with time zone,
    locked_by text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    operation_key text,
    dispatch_amount_cents integer,
    dispatch_currency text,
    dispatch_destination text,
    dispatch_source_transaction text,
    dispatch_transfer_group text,
    provider_call_may_have_occurred boolean DEFAULT false NOT NULL,
    dispatch_carry_cents integer,
    CONSTRAINT transfer_intents_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT transfer_intents_dispatch_carry_check CHECK (((dispatch_carry_cents IS NULL) OR (dispatch_carry_cents >= 0))),
    CONSTRAINT transfer_intents_dispatch_payload_check CHECK ((((operation_key IS NULL) AND (dispatch_amount_cents IS NULL) AND (dispatch_currency IS NULL) AND (dispatch_destination IS NULL) AND (dispatch_source_transaction IS NULL) AND (dispatch_transfer_group IS NULL)) OR ((operation_key IS NOT NULL) AND (dispatch_amount_cents IS NOT NULL) AND (dispatch_amount_cents > 0) AND (dispatch_currency IS NOT NULL) AND (dispatch_currency ~ '^[a-z]{3}$'::text) AND (dispatch_destination IS NOT NULL) AND (length(dispatch_destination) > 0) AND (dispatch_source_transaction IS NOT NULL) AND (length(dispatch_source_transaction) > 0) AND (dispatch_transfer_group IS NOT NULL) AND (length(dispatch_transfer_group) > 0)))),
    CONSTRAINT transfer_intents_status_check CHECK ((status = ANY (ARRAY['holding'::text, 'ready'::text, 'processing'::text, 'transferred'::text, 'blocked_unpayable'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: claim_transfer_intents(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_transfer_intents(p_worker text, p_batch integer DEFAULT 20, p_lease_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.transfer_intents
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with candidates as (
    select ti.order_id, ti.status = 'processing' as was_processing
    from public.transfer_intents ti
    where (
        ti.status in ('ready', 'failed')
        and ti.attempts < p_max_attempts
        and (ti.next_attempt_at is null or ti.next_attempt_at <= now())
        and (
          ti.provider_call_may_have_occurred
          or not private.order_has_unresolved_chargeback(ti.order_id)
        )
      )
      -- 20261107210100 (N114): a seller-side wait takes a place in the batch
      -- only when it can move.
      or (
        ti.status = 'blocked_unpayable'
        and ti.attempts < p_max_attempts
        and (ti.next_attempt_at is null or ti.next_attempt_at <= now())
        and (
          ti.provider_call_may_have_occurred
          or (
            not private.order_has_unresolved_chargeback(ti.order_id)
            and exists (
              select 1 from public.profiles p
              where p.id = ti.seller_id
                and p.stripe_account_id is not null
                and p.payouts_enabled
            )
          )
        )
      )
      or (
        ti.status = 'holding'
        and ti.provider_call_may_have_occurred
        and ti.next_attempt_at is not null
        and ti.next_attempt_at <= now()
        and ti.attempts < p_max_attempts
      )
      or (
        ti.status = 'processing'
        and (ti.lease_expires_at is null or ti.lease_expires_at < now())
      )
    -- 20261107210100 (N114): longest-due first — the lapsed lease, the
    -- reconciliation or retry time, or when the payout became payable.
    order by
      case
        when ti.status = 'processing' then coalesce(ti.lease_expires_at, ti.updated_at)
        -- greatest() skips nulls: the later of the two times that are set.
        else coalesce(greatest(ti.available_at, ti.next_attempt_at), ti.created_at)
      end,
      ti.order_id
    limit greatest(p_batch, 1)
    for update of ti skip locked
  )
  update public.transfer_intents ti
  set status = 'processing',
      locked_at = now(),
      locked_by = p_worker,
      lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
      last_attempt_at = now(),
      provider_call_may_have_occurred =
        ti.provider_call_may_have_occurred or c.was_processing,
      updated_at = now()
  from candidates c
  where ti.order_id = c.order_id
  returning ti.*;
$$;


--
-- Name: claim_unmapped_payment_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_unmapped_payment_requests() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 with due as (select operation_key from public.payment_requests where provider_reference is null and provider_rejected_at is null and created_at<now()-interval '2 minutes' and next_reconcile_at<=now() order by next_reconcile_at,operation_key for update skip locked limit 10),
 claimed as(update public.payment_requests p set next_reconcile_at=now()+interval '15 minutes' from due where p.operation_key=due.operation_key returning p.*)
 select coalesce(jsonb_agg(claimed),'[]') from claimed;
$$;


--
-- Name: complete_listing_creation(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_listing_creation(p_request uuid, p_payload_hash text, p_listing uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if not exists (
       select 1 from public.profiles p
       where p.id = v_actor and p.suspended_at is null
     ) then
    raise exception 'Account unavailable' using errcode = '42501';
  end if;

  update private.listing_creation_requests r
  set completed_at = coalesce(r.completed_at, now())
  where r.seller_id = v_actor
    and r.request_id = p_request
    and r.payload_hash = p_payload_hash
    and r.listing_id = p_listing
    and exists (
      select 1 from public.listings l
      where l.id = p_listing and l.seller_id = v_actor
    );

  if not found then
    raise exception 'Listing creation request does not match the listing'
      using errcode = '22023';
  end if;
  return true;
end;
$$;


--
-- Name: complete_media_deletion(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_media_deletion(p_bucket text, p_path text, p_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update private.media_deletion_claims
     set state = 'done', completed_at = now()
   where bucket = p_bucket and path = p_path and token = p_token and state = 'active';
  return found;
end;
$$;


--
-- Name: complete_order_email(uuid, integer, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_order_email(p_id uuid, p_attempt integer, p_outcome text, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_retry_after integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.order_email_outbox%rowtype;
  v_until timestamptz;
begin
  select * into v_row from public.order_email_outbox where id = p_id for update;
  if not found then return 'gone'; end if;
  if p_outcome <> 'skipped' and (v_row.status <> 'sending' or v_row.attempts <> p_attempt) then return 'stale'; end if;
  if p_outcome = 'sent' then
    update public.order_email_outbox
       set status = 'sent', sent_at = now(), provider_message_id = left(p_provider_message_id, 200),
           -- Null, except a note on how it came to be counted as sent (a repeated key the provider refused).
           last_error = left(p_error, 200), lease_id = null, lease_expires_at = null, updated_at = now()
     where id = p_id;
    return 'sent';
  elsif p_outcome = 'retry' then
    if v_row.attempts >= 5 then
      update public.order_email_outbox
         set status = 'failed', last_error = left(p_error, 200), lease_id = null, lease_expires_at = null, updated_at = now()
       where id = p_id;
      return 'failed';
    end if;
    update public.order_email_outbox
       set status = 'pending', last_error = left(p_error, 200), lease_id = null, lease_expires_at = null,
           next_attempt_at = now() + (interval '10 minutes' * power(2, greatest(v_row.attempts - 1, 0))), updated_at = now()
     where id = p_id;
    return 'pending';
  elsif p_outcome = 'provider' then
    update public.order_email_outbox
       set status = 'pending', attempts = greatest(v_row.attempts - 1, 0), provider_held_at = coalesce(v_row.provider_held_at, now()),
           last_error = left(p_error, 200), lease_id = null, lease_expires_at = null,
           next_attempt_at = now() + interval '10 minutes', updated_at = now()
     where id = p_id;
    -- One window while the fault stands: the pass stops at the first row it
    -- tries, so every other waiting row is marked here, or it would go stale
    -- at 24 hours without ever having been tried (review of #204).
    update public.order_email_outbox
       set provider_held_at = now()
     where status = 'pending' and provider_held_at is null;
    return 'held';
  elsif p_outcome = 'rate_limited' then
    -- Not this message's fault and not ours: the attempt is not counted. The
    -- provider's own wait is honoured for the whole queue (nothing waiting is
    -- claimed before it), a minute when it names none, an hour at most.
    v_until := now() + make_interval(secs => least(greatest(coalesce(p_retry_after, 60), 1), 3600));
    update public.order_email_outbox
       set status = 'pending', attempts = greatest(v_row.attempts - 1, 0),
           last_error = left(p_error, 200), lease_id = null, lease_expires_at = null,
           next_attempt_at = v_until, updated_at = now()
     where id = p_id;
    update public.order_email_outbox
       set next_attempt_at = v_until
     where status = 'pending' and next_attempt_at < v_until;
    return 'limited';
  elsif p_outcome = 'rejected' then
    update public.order_email_outbox
       set status = 'skipped', skip_reason = 'rejected', last_error = left(p_error, 200), lease_id = null, lease_expires_at = null, updated_at = now()
     where id = p_id;
    return 'skipped';
  elsif p_outcome = 'skipped' then
    if p_reason not in ('muted', 'email_off') then raise exception 'Unknown skip reason' using errcode = '22023'; end if;
    update public.order_email_outbox
       set status = 'skipped', skip_reason = p_reason, lease_id = null, lease_expires_at = null, updated_at = now()
     where id = p_id and status in ('pending', 'sending');
    return 'skipped';
  end if;
  raise exception 'Unknown outcome %', p_outcome using errcode = '22023';
end;
$$;


--
-- Name: complete_outbound_label(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_outbound_label(p_shipment uuid, p_label jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  shipment_order uuid;
  saved public.outbound_label_requests;
  s public.shipments;
  o public.orders;
  adjustment public.seller_adjustments;
  amount integer;
begin
  select order_id into strict shipment_order from public.shipments where id=p_shipment;
  select * into strict o from public.orders where id=shipment_order for update;
  select * into strict s from public.shipments where id=p_shipment for update;
  select * into strict saved from public.outbound_label_requests where shipment_id=p_shipment for update;
  amount:=(p_label->>'amountCents')::integer;
  if p_label is null or jsonb_typeof(p_label)<>'object'
     or p_label->>'shipmentRef' is distinct from saved.rated->>'shipmentRef'
     or upper(p_label->>'currency') is distinct from upper(o.currency)
     or upper(p_label->>'currency') is distinct from upper(saved.rated->>'currency')
     or p_label->>'carrier' is distinct from saved.rated->>'carrier'
     or p_label->>'service' is distinct from saved.rated->>'service'
     or amount is null or amount<0 or amount is distinct from (saved.rated->>'amountCents')::integer
     or nullif(p_label->>'labelUrl','') is null or nullif(p_label->>'trackingCode','') is null then
    raise exception 'Purchased outbound label does not match its frozen request';
  end if;
  if saved.completed_at is not null then
    if saved.label<>p_label then raise exception 'Purchased outbound label replay changed'; end if;
    return jsonb_build_object('ok',true,'label',saved.label,'replayed',true);
  end if;
  if s.order_id<>o.id or s.direction<>'outbound' or s.fulfillment_type<>'drvn_shipping'
     or s.provider<>saved.provider or s.provider_shipment_id is distinct from saved.rated->>'shipmentRef'
     or s.status<>'pending' then raise exception 'Outbound shipment identity changed'; end if;

  update public.shipments set status='label_purchased',purchased_cents=amount,
    label_reference=p_label->>'labelUrl',tracking_code=p_label->>'trackingCode',
    provider_tracker_id=p_label->>'trackerRef',carrier=p_label->>'carrier',service=p_label->>'service'
  where id=s.id;
  insert into public.seller_adjustments(
    seller_id,order_id,shipment_id,kind,amount_cents,currency,external_reference,description
  ) values(
    o.seller_id,o.id,s.id,'outbound_label',-amount,o.currency,'label:'||s.id,
    (p_label->>'carrier')||' '||(p_label->>'service')||' outbound label'
  ) on conflict(kind,external_reference) where external_reference is not null do nothing;
  select * into strict adjustment from public.seller_adjustments
  where kind='outbound_label' and external_reference='label:'||s.id;
  if adjustment.seller_id is distinct from o.seller_id or adjustment.order_id<>o.id
     or adjustment.shipment_id is distinct from s.id or adjustment.amount_cents<>-amount
     or upper(adjustment.currency)<>upper(o.currency) then
    raise exception 'Outbound label seller adjustment conflicts';
  end if;
  update public.outbound_label_requests set completed_at=now(),label=p_label where shipment_id=s.id;
  delete from public.admin_alert_outbox where dedup_key='outbound-label:'||s.id and status='pending';
  return jsonb_build_object('ok',true,'label',p_label,'replayed',false);
end $$;


--
-- Name: complete_refund_reversal(uuid, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_refund_reversal(p_operation uuid, p_worker text, p_operation_key text, p_transfer_reference text, p_amount_cents integer, p_currency text, p_reversal_reference text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op public.refund_operations;
  v_recovery public.payment_recoveries;
  v_updated int;
begin
  if nullif(p_reversal_reference, '') is null then raise exception 'Invalid reversal reference'; end if;
  select * into v_op
  from public.refund_operations
  where id = p_operation
  for update;
  if not found then return 'missing'; end if;

  if v_op.status = 'completed' then
    if v_op.reversal_reference = p_reversal_reference
       and v_op.reversal_operation_key = p_operation_key
       and v_op.reversal_transfer_reference = p_transfer_reference
       and v_op.reversal_amount_cents = p_amount_cents
       and v_op.reversal_currency = lower(p_currency) then
      return 'completed';
    end if;
    return 'conflict';
  end if;

  if (
    v_op.status = 'reversal_pending'
    and v_op.reversal_locked_by = p_worker
    and v_op.reversal_lease_expires_at > now()
    and v_op.reversal_call_may_have_occurred
    and v_op.reversal_operation_key = p_operation_key
    and v_op.reversal_transfer_reference = p_transfer_reference
    and v_op.reversal_amount_cents = p_amount_cents
    and v_op.reversal_currency = lower(p_currency)
  ) is not true then
    return 'lost';
  end if;

  update public.refund_operations
  set status = 'completed',
      reversal_reference = p_reversal_reference,
      reversal_completed_at = now(),
      last_error = null,
      next_attempt_at = null,
      reversal_locked_by = null,
      reversal_lease_expires_at = null,
      updated_at = now()
  where id = p_operation;

  if v_op.recovery_id is not null then
    update public.payment_recoveries
    set status = 'recovered',
        resolved_at = now(),
        resolution_note = 'Reversal recovered from exact Stripe history match.'
    where id = v_op.recovery_id and status = 'open';
    get diagnostics v_updated = row_count;
    if v_updated = 0 then
      select * into v_recovery from public.payment_recoveries where id = v_op.recovery_id;
      if not found or v_recovery.status <> 'recovered' then
        raise exception 'Reversal recovery resolution was not persisted';
      end if;
    end if;
  end if;
  return 'completed';
end;
$$;


--
-- Name: complete_return_label(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_return_label(p_return uuid, p_label jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare saved public.return_label_requests; r public.returns; o public.orders; s public.shipments; adjustment public.seller_adjustments; amount integer;
begin
 select * into strict r from public.returns where id=p_return;
 select * into strict o from public.orders where id=r.order_id for update;
 select * into strict r from public.returns where id=p_return for update;
 select * into strict saved from public.return_label_requests where return_id=p_return for update;
 amount:=(p_label->>'amountCents')::integer;
 if p_label is null or jsonb_typeof(p_label)<>'object'
 or p_label->>'shipmentRef' is distinct from saved.rated->>'shipmentRef'
 or upper(p_label->>'currency') is distinct from upper(o.currency)
 or upper(p_label->>'currency') is distinct from upper(saved.rated->>'currency')
 or p_label->>'carrier' is distinct from saved.rated->>'carrier'
 or p_label->>'service' is distinct from saved.rated->>'service'
 or amount is null or amount<0 or amount is distinct from (saved.rated->>'amountCents')::integer
 or nullif(p_label->>'labelUrl','') is null or nullif(p_label->>'trackingCode','') is null
 then raise exception 'Purchased label does not match its frozen request'; end if;
 if saved.completed_at is not null then
   if saved.label<>p_label then raise exception 'Purchased label replay changed'; end if;
   return jsonb_build_object('ok',true,'label',saved.label);
 end if;
 select * into strict s from public.shipments where id=saved.shipment_id for update;
 if s.order_id<>o.id or s.return_id<>r.id or s.provider<>saved.provider or s.provider_shipment_id is distinct from saved.rated->>'shipmentRef'
 or (s.label_reference is not null and s.label_reference is distinct from p_label->>'labelUrl')
 then raise exception 'Return shipment identity changed'; end if;
 update public.shipments set provider_tracker_id=p_label->>'trackerRef',tracking_code=p_label->>'trackingCode',label_reference=p_label->>'labelUrl',purchased_cents=amount,
 status=case when status='pending' then 'label_purchased' else status end where id=s.id;
 insert into public.shipment_items(shipment_id,order_item_id) select s.id,order_item_id from public.return_items where return_id=r.id on conflict do nothing;
 if not exists(select 1 from public.shipment_items where shipment_id=s.id) then raise exception 'Return shipment has no item links'; end if;
 insert into public.seller_adjustments(seller_id,order_id,shipment_id,return_id,kind,amount_cents,currency,external_reference,description)
 values(o.seller_id,o.id,s.id,r.id,'return_label',-amount,o.currency,'retlabel:'||r.id,(p_label->>'carrier')||' '||(p_label->>'service')||' return label')
 on conflict(kind,external_reference) where external_reference is not null do nothing;
 select * into strict adjustment from public.seller_adjustments where kind='return_label' and external_reference='retlabel:'||r.id;
 if adjustment.seller_id is distinct from o.seller_id or adjustment.order_id<>o.id or adjustment.shipment_id is distinct from s.id or adjustment.return_id is distinct from r.id or adjustment.amount_cents<>-amount or upper(adjustment.currency)<>upper(o.currency) then raise exception 'Return label seller adjustment conflicts'; end if;
 update public.return_label_requests set completed_at=now(),label=p_label where return_id=p_return;
 delete from public.admin_alert_outbox where dedup_key='return-label:'||r.id and status='pending';
 return jsonb_build_object('ok',true,'label',p_label);
end $$;


--
-- Name: complete_saved_search_digest(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_saved_search_digest(p_id uuid, p_attempt integer, p_outcome text, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if p_outcome is null or p_outcome not in ('sent', 'retry', 'rejected') then
    raise exception 'Unknown digest outcome' using errcode = '22023';
  end if;
  update public.saved_search_email_digests d
     set status = case
                    when p_outcome = 'sent' then 'sent'
                    when p_outcome = 'retry' then 'pending'
                    else 'failed' end,
         sent_at = case when p_outcome = 'sent' then now() end,
         provider_message_id = case when p_outcome = 'sent' then left(nullif(btrim(p_provider_message_id), ''), 200) end,
         last_error = case when p_outcome = 'sent' then d.last_error else left(nullif(btrim(p_error), ''), 300) end,
         next_attempt_at = case
                             when p_outcome = 'retry'
                               then now() + least(interval '10 minutes' * power(2, least(d.attempts, 10) - 1), interval '60 minutes')
                             else now() end,
         updated_at = now()
   where d.id = p_id and d.status = 'sending' and d.attempts = p_attempt
  returning d.status into v_status;
  return coalesce(v_status, 'stale');
end;
$$;


--
-- Name: complete_seller_carry_payout(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_seller_carry_payout(p_id uuid, p_worker text, p_transfer_reference text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_payout public.seller_carry_payouts;
begin
  if p_transfer_reference is null or length(p_transfer_reference) = 0 then
    raise exception 'Invalid transfer reference';
  end if;
  select * into v_payout from public.seller_carry_payouts where id = p_id for update;
  if not found then return 'lost'; end if;
  if v_payout.status = 'paid' and v_payout.transfer_reference = p_transfer_reference then
    return 'completed';
  end if;
  if v_payout.status <> 'processing'
     or v_payout.locked_by is distinct from p_worker
     or v_payout.lease_expires_at is null
     or v_payout.lease_expires_at <= now()
     or not v_payout.provider_call_may_have_occurred then
    return 'lost';
  end if;
  update public.seller_carry_payouts
     set status = 'paid',
         transfer_reference = p_transfer_reference,
         paid_at = now(),
         last_error = null,
         next_attempt_at = null,
         locked_by = null,
         lease_expires_at = null,
         updated_at = now()
   where id = p_id;
  return 'completed';
end;
$$;


--
-- Name: complete_stripe_dispute_loss(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_stripe_dispute_loss(p_dispute text, p_event text, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare entry public.stripe_dispute_journal%rowtype;
begin
 select * into strict entry from public.stripe_dispute_journal where dispute_id=p_dispute for update;
 if entry.state<>'loss_pending' or entry.last_event_id<>p_event or entry.lease_id is distinct from p_lease or entry.lease_expires_at<=now() then raise exception 'Dispute lease lost'; end if;
 if exists(select 1 from public.orders where id=any(entry.order_ids) and refunded_cents<>total_cents) then raise exception 'Dispute refund ledger incomplete'; end if;
 update public.stripe_dispute_journal set state='lost',lease_id=null,lease_expires_at=null,updated_at=now() where dispute_id=p_dispute;
end $$;


--
-- Name: complete_transfer_intent(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_transfer_intent(p_order uuid, p_worker text, p_operation_key text, p_transfer_reference text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order record;
  v_intent public.transfer_intents;
  v_dispatch_amount int;
  v_operation_key text;
  v_adjustments int;
  v_current_payable int;
  -- 20261107130000
  v_chargeback boolean;
begin
  if p_order is null
     or p_worker is null
     or p_transfer_reference is null
     or length(p_transfer_reference) = 0 then
    raise exception 'Invalid transfer reference';
  end if;

  -- Match settle_refund_operation's order -> transfer_intent lock order. The
  -- order row lock also serializes FK-checked seller-adjustment inserts, so
  -- the payable amount below reflects every adjustment committed before this
  -- completion and cannot change until this transaction commits.
  select id, status, total_cents, platform_fee_cents, refunded_cents, transfer_reference
  into v_order
  from public.orders
  where id = p_order
  for update;
  if not found then return 'lost'; end if;

  select * into v_intent
  from public.transfer_intents
  where order_id = p_order
  for update;
  if not found then return 'lost'; end if;

  -- 20261107130000: read under the order lock, which a provider dispute
  -- admission also takes before it changes the order.
  v_chargeback := private.order_has_unresolved_chargeback(p_order);

  v_dispatch_amount := v_intent.dispatch_amount_cents;
  v_operation_key := v_intent.operation_key;

  if (
    v_intent.status = 'processing'
    and v_intent.locked_by = p_worker
    and v_intent.lease_expires_at > now()
    and v_intent.operation_key is not distinct from p_operation_key
  ) is not true then
    -- A full refund can cancel the intent while its owner is inside Stripe.
    -- The returned transfer is definitive evidence of the external effect, so
    -- preserve its reference and open the adjustment instead of dropping it.
    -- A processing row owned by anybody else remains untouched.
    -- 20261107130000: a full refund now shelves such a payout ('holding',
    -- settle_refund_operation) instead of cancelling it; the same evidence
    -- applies to it, and to an exhausted one the refund left 'failed' with
    -- its operator case. Any other shelved row stays 'lost' here and is found
    -- by the worker's next reconciliation.
    if (
         v_intent.status = 'cancelled'
         or (v_intent.status in ('holding', 'failed')
             and (v_order.status = 'refunded' or v_order.refunded_cents >= v_order.total_cents))
       )
       and v_intent.provider_call_may_have_occurred
       and v_intent.operation_key = p_operation_key
       and v_intent.transfer_reference is null then
      if v_order.transfer_reference is not null
         and v_order.transfer_reference <> p_transfer_reference then
        update public.transfer_intents
        set status = 'failed',
            attempts = greatest(attempts, 8),
            next_attempt_at = null,
            last_error = 'Order has a different transfer reference',
            locked_at = null,
            locked_by = null,
            lease_expires_at = null,
            updated_at = now()
        where order_id = p_order;

        insert into public.payment_recoveries (
          order_id, kind, recovery_key, amount_cents, detail
        ) values (
          p_order,
          'transfer_unresolved',
          'transfer-unresolved:' || p_order::text,
          coalesce(v_dispatch_amount, v_intent.amount_cents),
          'Stripe transfer ' || p_transfer_reference ||
            ' conflicts with order transfer ' || v_order.transfer_reference
        )
        on conflict (recovery_key) do update
        set last_seen_at = now(), detail = excluded.detail, status = 'open',
            resolved_by = null, resolved_at = null, resolution_note = null;
        return 'recovery';
      end if;

      update public.orders
      set transfer_reference = p_transfer_reference,
          transferred_at = coalesce(transferred_at, now())
      where id = p_order;
      update public.transfer_intents
      set status = 'transferred',
          transfer_reference = p_transfer_reference,
          last_error = null,
          next_attempt_at = null,
          locked_at = null,
          locked_by = null,
          lease_expires_at = null,
          updated_at = now()
      where order_id = p_order;
      insert into public.payment_recoveries (
        order_id, kind, recovery_key, amount_cents, detail
      ) values (
        p_order,
        'transfer_after_refund',
        'transfer-adjustment:' || v_operation_key || ':' || p_transfer_reference,
        v_dispatch_amount,
        'The order became non-payable while Stripe transfer ' ||
          p_transfer_reference || ' was in flight; reconcile the seller balance.'
      )
      on conflict (recovery_key) do update
      set last_seen_at = now(), detail = excluded.detail,
          amount_cents = excluded.amount_cents, status = 'open',
          resolved_by = null, resolved_at = null, resolution_note = null;
      return 'recovery';
    end if;
    return 'lost';
  end if;

  select coalesce(sum(amount_cents), 0)::int
  into v_adjustments
  from public.seller_adjustments
  where order_id = p_order and voided_at is null;

  v_current_payable := v_intent.amount_cents
    - case
        when v_order.total_cents <= 0 or v_intent.amount_cents <= 0 then 0
        else least(
          v_intent.amount_cents,
          round((v_order.refunded_cents::numeric * v_intent.amount_cents) /
            v_order.total_cents)::int
        )
      end
    + v_adjustments
    -- 20261005110100: the dispatch already took the frozen carry-forward
    -- collection off; compare like with like.
    - coalesce(v_intent.dispatch_carry_cents, 0);

  if v_order.transfer_reference is not null
     and v_order.transfer_reference <> p_transfer_reference then
    update public.transfer_intents
    set status = 'failed',
        attempts = greatest(attempts, 8),
        next_attempt_at = null,
        last_error = 'Order has a different transfer reference',
        locked_at = null,
        locked_by = null,
        lease_expires_at = null,
        updated_at = now()
    where order_id = p_order;

    insert into public.payment_recoveries (
      order_id, kind, recovery_key, amount_cents, detail
    ) values (
      p_order,
      'transfer_unresolved',
      'transfer-unresolved:' || p_order::text,
      coalesce(v_dispatch_amount, v_intent.amount_cents),
      'Stripe transfer ' || p_transfer_reference ||
        ' conflicts with order transfer ' || v_order.transfer_reference
    )
    on conflict (recovery_key) do update
    set last_seen_at = now(), detail = excluded.detail, status = 'open',
        resolved_by = null, resolved_at = null, resolution_note = null;
    return 'recovery';
  end if;

  update public.orders
  set transfer_reference = p_transfer_reference,
      transferred_at = coalesce(transferred_at, now())
  where id = p_order;

  update public.transfer_intents
  set status = 'transferred',
      transfer_reference = p_transfer_reference,
      last_error = null,
      next_attempt_at = null,
      locked_at = null,
      locked_by = null,
      lease_expires_at = null,
      updated_at = now()
  where order_id = p_order;

  -- 20261107130000: a transfer found (reconciled) after the order was fully
  -- refunded is recorded, and an operator decides on a reversal. Nothing is
  -- reversed automatically.
  if v_order.status = 'refunded' or v_order.refunded_cents >= v_order.total_cents then
    insert into public.payment_recoveries (
      order_id, kind, recovery_key, amount_cents, detail
    ) values (
      p_order,
      'transfer_after_refund',
      'transfer-adjustment:' || coalesce(v_operation_key, p_order::text) || ':' || p_transfer_reference,
      coalesce(v_dispatch_amount, v_intent.amount_cents),
      'Stripe transfer ' || p_transfer_reference ||
        ' was paid after the order was refunded; decide whether to reverse it from the seller.'
    )
    on conflict (recovery_key) do update
    set last_seen_at = now(), detail = excluded.detail,
        amount_cents = excluded.amount_cents, status = 'open',
        resolved_by = null, resolved_at = null, resolution_note = null;
    return 'recovery';
  end if;

  -- 20261107130000: a transfer found while a bank chargeback is unresolved is
  -- still recorded (it happened), and an operator is told, exactly as for a
  -- transfer that completed while the order was disputed.
  if (v_order.status in ('delivered', 'completed')) is not true
     or (v_intent.available_at is not null and v_intent.available_at > now())
     or v_chargeback then
    insert into public.payment_recoveries (
      order_id, kind, recovery_key, amount_cents, detail
    ) values (
      p_order,
      'transfer_unresolved',
      'transfer-unresolved:' || p_order::text,
      coalesce(v_dispatch_amount, v_intent.amount_cents),
      'Stripe transfer ' || p_transfer_reference ||
        ' completed while the order was ' || v_order.status ||
        case
          when v_intent.available_at is not null and v_intent.available_at > now()
            then ' and its clearing time was still in the future'
          else ''
        end ||
        case when v_chargeback then ' and a bank chargeback on it was unresolved' else '' end
    )
    on conflict (recovery_key) do update
    set last_seen_at = now(), detail = excluded.detail,
        amount_cents = excluded.amount_cents, status = 'open',
        resolved_by = null, resolved_at = null, resolution_note = null;
    return 'recovery';
  end if;

  if v_dispatch_amount is not null and v_current_payable <> v_dispatch_amount then
    insert into public.payment_recoveries (
      order_id, kind, recovery_key, amount_cents, detail
    ) values (
      p_order,
      'transfer_after_refund',
      'transfer-adjustment:' || v_operation_key || ':' || p_transfer_reference,
      abs(v_dispatch_amount - v_current_payable),
      'Recovered the frozen transfer amount ' || v_dispatch_amount::text ||
        ' cents while the current payable amount is ' || v_current_payable::text ||
        ' cents; reconcile the difference separately.'
    )
    on conflict (recovery_key) do update
    set last_seen_at = now(),
        detail = excluded.detail,
        amount_cents = excluded.amount_cents,
        status = 'open',
        resolved_by = null,
        resolved_at = null,
        resolution_note = null;
  end if;

  return 'completed';
end;
$$;


--
-- Name: confirm_admin_mfa(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_admin_mfa(p_user uuid, p_factor uuid, p_confirmed_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_confirmed_by is null or length(trim(p_confirmed_by)) < 3 then
    raise exception 'Say who confirmed the authenticator and how' using errcode = '22023';
  end if;
  if not exists (select 1 from public.admin_users where user_id = p_user) then
    raise exception 'This account is not a console member' using errcode = 'P0002';
  end if;
  if not private.admin_factor_confirmed(p_user, p_factor) then
    raise exception 'That factor is not a verified authenticator of this account' using errcode = '22023';
  end if;
  update public.admin_users
     set mfa_factor_id = p_factor,
         mfa_confirmed_at = now(),
         mfa_confirmed_by = left(trim(p_confirmed_by), 500)
   where user_id = p_user;
  return jsonb_build_object('user', p_user, 'factor', p_factor, 'confirmedAt', now());
end;
$$;


--
-- Name: consume_rate_limit(text, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_rate_limit(p_key text, p_limit integer, p_window interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count int;
begin
  insert into public.rate_limits (key, window_start, count)
  values (p_key, now(), 1)
  on conflict (key) do update
    set
      -- Reset the window if the old one has elapsed, otherwise increment.
      window_start = case
        when public.rate_limits.window_start < now() - p_window then now()
        else public.rate_limits.window_start
      end,
      count = case
        when public.rate_limits.window_start < now() - p_window then 1
        else public.rate_limits.count + 1
      end
  returning count into v_count;

  return v_count <= p_limit;
end;
$$;


--
-- Name: continue_account_deletion(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.continue_account_deletion(p_job uuid, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 update public.remediation_jobs set status='pending',next_attempt_at=now(),locked_until=null,lease_id=null,attempts=0
 where id=p_job and kind='delete_account' and status='processing' and lease_id=p_lease and locked_until>now();
 if not found then raise exception 'Deletion lease lost'; end if;
end $$;


--
-- Name: continue_account_export(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.continue_account_export(p_job uuid, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.remediation_jobs set status='pending',next_attempt_at=now(),locked_until=null,lease_id=null,attempts=greatest(attempts-1,0)
   where id=p_job and kind='account_export' and status='processing' and lease_id=p_lease and locked_until>now();
  if not found then raise exception 'Export lease lost'; end if;
end $$;


--
-- Name: copyright_takedown(uuid, uuid[], text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copyright_takedown(p_notice uuid, p_listing_ids uuid[], p_media_urls text[], p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := private.copyright_admin_step_up();
  v_notice public.copyright_notices;
  v_listings uuid[] := coalesce((select array_agg(distinct x) from unnest(coalesce(p_listing_ids, '{}')) x where x is not null), '{}');
  v_urls text[] := coalesce((select array_agg(distinct btrim(u)) from unnest(coalesce(p_media_urls, '{}')) u where btrim(coalesce(u, '')) <> ''), '{}');
  v_keys text[];
  v_removed uuid[];
  v_kept uuid[];
  v_owners uuid[];
  v_still text[];
  v_n int;
  v_counts jsonb := '{}'::jsonb;
  v_result jsonb;
begin
  if p_note is null or length(btrim(p_note)) < 1 or length(p_note) > 4000 then
    raise exception 'A note of 1–4000 characters is required' using errcode = '22023';
  end if;
  if cardinality(v_listings) + cardinality(v_urls) = 0 then
    raise exception 'Name at least one listing or photo to take down' using errcode = '22023';
  end if;
  if cardinality(v_listings) > 50 or cardinality(v_urls) > 200 then
    raise exception 'Take down at most 50 listings and 200 photos at a time' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_urls) u where private.media_object_key(u) is null) then
    raise exception 'Every photo must be a DRVN storage URL' using errcode = '22023';
  end if;

  select * into v_notice from public.copyright_notices where id = p_notice for update;
  if not found then
    raise exception 'Notice not found' using errcode = 'P0002';
  end if;
  if v_notice.status <> 'received' then
    raise exception 'This notice is already closed (%)', v_notice.status using errcode = '55000';
  end if;
  if (select count(*) from public.listings where id = any(v_listings)) <> cardinality(v_listings) then
    raise exception 'A listing named here does not exist' using errcode = 'P0002';
  end if;

  -- Listings: off the marketplace. One a checkout holds, or one already sold,
  -- keeps its status (the order owns it); its photos are purged regardless.
  perform 1 from public.listings where id = any(v_listings) order by id for update;
  with taken as (
    update public.listings
       set status = 'removed', removed_at = now(),
           removed_reason = left('Copyright notice: ' || btrim(p_note), 500)
     where id = any(v_listings) and status not in ('reserved', 'sold', 'removed')
    returning id
  )
  select coalesce(array_agg(id), '{}') into v_removed from taken;
  select coalesce(array_agg(id), '{}') into v_kept
    from public.listings where id = any(v_listings) and not (id = any(v_removed));

  -- Every object: the photos named, and every photo of those listings.
  select coalesce(array_agg(distinct k) filter (where k is not null), '{}') into v_keys
    from (
      select private.media_object_key(u) as k from unnest(v_urls) u
      union all
      select private.media_object_key(li.url) from public.listing_images li where li.listing_id = any(v_listings)
    ) s;

  -- Who held them: told afterwards (the app sends the notices).
  select coalesce(array_agg(distinct o), '{}') into v_owners
    from (
      select seller_id as o from public.listings where id = any(v_listings)
      union all
      select case when split_part(k, '/', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  then split_part(k, '/', 2)::uuid end
        from unnest(v_keys) k
    ) s
   where o is not null and exists (select 1 from public.profiles p where p.id = o);

  -- Purge every place the object is held. The order snapshot first: it is
  -- the copy a buyer's order would otherwise keep showing for ever.
  delete from public.order_item_snapshot_images where private.media_object_key(url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('order_snapshot_photos', v_n);
  delete from public.listing_images where private.media_object_key(url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('listing_photos', v_n);
  delete from public.car_images where private.media_object_key(url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('car_photos', v_n);
  delete from public.activity_images where private.media_object_key(url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('post_photos', v_n);
  delete from public.car_hotspots where private.media_object_key(image_url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('hotspots', v_n);
  update public.mod_items set image_url = null where private.media_object_key(image_url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('mod_photos', v_n);
  update public.cars set cover_image_url = null where private.media_object_key(cover_image_url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('car_covers', v_n);
  update public.profiles set avatar_url = null where private.media_object_key(avatar_url) = any(v_keys);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('avatars', v_n);

  insert into public.copyright_blocked_media (object_key, notice_id)
  select k, p_notice from unnest(v_keys) k
  on conflict (object_key) do nothing;

  -- Storage: the media worker deletes each object once nothing references
  -- it (its own check, under a lock). Only member folders are queued; the
  -- folder names the owner, as every member upload path does.
  insert into public.media_cleanup_queue (bucket, path, owner_id, reason)
  select split_part(k, '/', 1), substr(k, length(split_part(k, '/', 1)) + 2), split_part(k, '/', 2)::uuid, 'copyright_takedown'
    from unnest(v_keys) k
   where split_part(k, '/', 1) in ('avatars', 'car-images', 'activity-images', 'listing-images')
     and split_part(k, '/', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  on conflict (bucket, path) do update
    set enqueued_at = now(), attempts = 0, next_attempt_at = now(), last_error = null,
        reason = excluded.reason, generation = gen_random_uuid()
    where media_cleanup_queue.owner_id = excluded.owner_id;

  -- What this couldn't purge (a post body or a message still names it).
  select coalesce(array_agg(k order by k), '{}') into v_still
    from unnest(v_keys) k
   where public.media_object_referenced(split_part(k, '/', 1), substr(k, length(split_part(k, '/', 1)) + 2));

  v_result := jsonb_build_object(
    'removedListings', to_jsonb(v_removed),
    'keptListingStatus', to_jsonb(v_kept),
    'objects', to_jsonb(v_keys),
    'purged', v_counts,
    'stillReferenced', to_jsonb(v_still),
    'owners', to_jsonb(v_owners)
  );

  update public.copyright_notices
     set status = 'actioned', resolved_by = v_actor, resolved_at = now(), resolution_note = p_note, takedown = v_result
   where id = p_notice;

  insert into public.admin_audit_log (actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'copyright.takedown', 'copyright_notice', p_notice, p_note,
          jsonb_build_object('phase', 'completed') || v_result);

  return v_result;
end;
$_$;


--
-- Name: create_protection_return(uuid, uuid, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_protection_return(p_order uuid, p_seller uuid, p_item_ids uuid[] DEFAULT NULL::uuid[], p_ship_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  selected_ids uuid[];
  selected_count integer;
  entitlement integer;
  existing_return uuid;
  new_return uuid;
  stamped_at timestamptz:=now();
begin
  if p_order is null or p_seller is null or p_ship_days is null or p_ship_days<1 or p_ship_days>30 then
    raise exception 'Invalid protection return request';
  end if;
  select * into strict o from public.orders where id=p_order for update;
  if o.seller_id is distinct from p_seller then raise exception 'Seller authorization required' using errcode='42501'; end if;
  if o.buyer_id is null then raise exception 'Protection return requires a buyer'; end if;

  perform 1 from public.order_items where order_id=o.id order by id for update;
  if coalesce(cardinality(p_item_ids),0)=0 then
    select array_agg(id order by id) into selected_ids from public.order_items where order_id=o.id;
  else
    select array_agg(distinct id order by id) into selected_ids from unnest(p_item_ids) id;
  end if;
  select count(*),coalesce(sum(price_cents+coalesce(shipping_cents,0)),0)
  into selected_count,entitlement from public.order_items
  where order_id=o.id and id=any(selected_ids);
  if coalesce(cardinality(selected_ids),0)=0 or selected_count<>cardinality(selected_ids) then
    raise exception 'Return items do not belong to this order';
  end if;

  select r.id into existing_return
  from public.returns r
  join public.return_items ri on ri.return_id=r.id
  where r.order_id=o.id and r.return_type='protection'
    and r.status in ('requested','approved','awaiting_shipment','in_transit','delivered','received','escalated')
  group by r.id
  having array_agg(ri.order_item_id order by ri.order_item_id)=selected_ids
  order by r.id limit 1;
  if found then
    return jsonb_build_object('ok',true,'return_id',existing_return,'order_id',o.id,'replayed',true);
  end if;
  if o.status<>'disputed' then raise exception 'Protection return requires an open dispute'; end if;

  delete from public.returns r where r.order_id=o.id and r.return_type='protection'
    and r.status in ('requested','approved','awaiting_shipment')
    and not exists(select 1 from public.return_items ri where ri.return_id=r.id)
    and not exists(select 1 from public.shipments s where s.return_id=r.id)
    and r.refund_operation_id is null;

  insert into public.returns(
    order_id,requested_by,return_type,reason,responsibility,status,
    approved_at,ship_by,refund_amount_cents
  ) values(
    o.id,o.buyer_id,'protection',o.dispute_reason,'seller','awaiting_shipment',
    stamped_at,stamped_at+make_interval(days=>p_ship_days),entitlement
  ) returning id into new_return;
  insert into public.return_items(return_id,order_item_id,reason)
  select new_return,id,o.dispute_reason from public.order_items
  where order_id=o.id and id=any(selected_ids);
  return jsonb_build_object('ok',true,'return_id',new_return,'order_id',o.id,'replayed',false);
end $$;


--
-- Name: create_shop_policy_return(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_shop_policy_return(p_order uuid, p_buyer uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  item_ids uuid[];
  item_count integer;
  entitlement integer;
  policy_ok boolean;
  window_min integer;
  window_max integer;
  existing_return uuid;
  new_return uuid;
  saved_reason text:=coalesce(nullif(left(trim(coalesce(p_reason,'')),1000),''),'Preference return within the shop''s window');
begin
  if p_order is null or p_buyer is null then raise exception 'Order and buyer are required'; end if;
  select * into strict o from public.orders where id=p_order for update;
  if o.buyer_id is distinct from p_buyer then raise exception 'Buyer authorization required' using errcode='42501'; end if;
  if o.status not in ('delivered','completed') or o.delivered_at is null then
    raise exception 'Preference returns require delivery';
  end if;
  perform 1 from public.order_items where order_id=o.id order by id for update;
  select array_agg(id order by id),count(*),coalesce(sum(price_cents),0),
    bool_and(coalesce((commercial_snapshot#>>'{commercial,return_policy,returns_accepted}')::boolean,false)),
    min((commercial_snapshot#>>'{commercial,return_policy,window_days}')::integer),
    max((commercial_snapshot#>>'{commercial,return_policy,window_days}')::integer)
  into item_ids,item_count,entitlement,policy_ok,window_min,window_max
  from public.order_items where order_id=o.id;
  if item_count=0 then raise exception 'Order has no returnable items'; end if;
  if not coalesce(policy_ok,false) or window_min is null or window_min<>window_max or window_min not in (14,30,60) then
    raise exception 'Order does not have a consistent shop return policy';
  end if;

  select r.id into existing_return
  from public.returns r join public.return_items ri on ri.return_id=r.id
  where r.order_id=o.id and r.return_type='shop_policy' and r.requested_by=p_buyer
    and r.status in ('requested','approved','awaiting_shipment','in_transit','delivered','received','escalated')
  group by r.id
  having array_agg(ri.order_item_id order by ri.order_item_id)=item_ids
  order by r.id limit 1;
  if found then
    return jsonb_build_object('ok',true,'return_id',existing_return,'order_id',o.id,'replayed',true);
  end if;
  if o.delivered_at+make_interval(days=>window_min)<now() then raise exception 'Shop return window has closed'; end if;

  delete from public.returns r where r.order_id=o.id and r.return_type='shop_policy'
    and r.status in ('requested','approved','awaiting_shipment')
    and not exists(select 1 from public.return_items ri where ri.return_id=r.id)
    and not exists(select 1 from public.shipments s where s.return_id=r.id)
    and r.refund_operation_id is null;

  insert into public.returns(
    order_id,requested_by,return_type,reason,responsibility,status,refund_amount_cents
  ) values(o.id,p_buyer,'shop_policy',saved_reason,'buyer','requested',entitlement)
  returning id into new_return;
  insert into public.return_items(return_id,order_item_id,reason)
  select new_return,id,saved_reason from public.order_items where order_id=o.id;
  return jsonb_build_object('ok',true,'return_id',new_return,'order_id',o.id,'replayed',false);
end $$;


--
-- Name: delivery_auto_confirm_eligible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_auto_confirm_eligible(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
      from public.orders o
     where o.id = p_order
       and o.status = 'shipped'
       and not o.is_collection
       and o.shipped_at is not null
       and o.delivered_at is null
       and o.buyer_id is not null
       and o.disputed_at is null
       and o.stripe_dispute_id is null
       and o.refunded_cents = 0
       and not exists (select 1 from public.returns r where r.order_id = o.id)
       and not exists (select 1 from public.refund_operations ro where ro.order_id = o.id)
       and not exists (
         select 1 from public.shipments s
          where s.order_id = o.id
            and s.direction = 'outbound'
            and (s.provider_tracker_id is not null
                 or s.status in ('delivered', 'returned_to_sender', 'failed'))
       )
  );
$$;


--
-- Name: discard_listing_creation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.discard_listing_creation(p_request uuid, p_payload_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'Sign in first' using errcode='42501'; end if;
  delete from private.listing_creation_requests r
  where r.seller_id=v_actor and r.request_id=p_request
    and r.payload_hash=p_payload_hash and r.completed_at is null
    and not exists(select 1 from public.listings l where l.id=r.listing_id);
  return found;
end;
$$;


--
-- Name: edit_car_gallery(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_car_gallery(p_car uuid, p_operation text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  car public.cars;
  photo public.car_images;
  ids uuid[];
  v_url text;
  deleted_url text;
  changed integer;
  actor uuid;
begin
  actor:=case when current_user='service_role' then (p_payload->>'actor')::uuid else auth.uid() end;
  if p_operation='add' and current_user<>'service_role' then raise exception 'Uploads must be attached through the verified server action' using errcode='42501'; end if;
  if actor is null or p_car is null or p_payload is null or jsonb_typeof(p_payload)<>'object' then
    raise exception 'Invalid gallery change';
  end if;
  if current_user='service_role' then
    if not exists(select 1 from public.profiles where id=actor and suspended_at is null) then raise exception 'Account unavailable' using errcode='42501'; end if;
  end if;
  -- Named columns: the caller may not read every column of cars (vin, 20261004160000).
  select c.id, c.owner_id, c.cover_image_url into car.id, car.owner_id, car.cover_image_url
  from public.cars c where c.id=p_car and c.owner_id=actor for update;
  if not found then raise exception 'Car not found or unavailable' using errcode='42501'; end if;

  if p_operation='add' then
    v_url:=p_payload->>'url';
    if v_url is null or v_url !~ ('^https?://[^/]+/storage/v1/object/public/car-images/'||actor::text||'/') then
      raise exception 'Image must belong to your uploads';
    end if;
    select * into photo from public.car_images where car_id=p_car and car_images.url=v_url order by position,id limit 1;
    if not found then
      if (select count(*) from public.car_images where car_id=p_car)>=48 then raise exception 'A gallery can hold up to 48 photos'; end if;
      insert into public.car_images(car_id,url,position)
      select p_car,v_url,coalesce(max(position)+1,0) from public.car_images where car_id=p_car returning * into photo;
    end if;
    if car.cover_image_url is null then
      update public.cars set cover_image_url=photo.url where id=p_car;
      if not found then raise exception 'Gallery update was not permitted'; end if;
    end if;
  elsif p_operation='reorder' then
    if jsonb_typeof(p_payload->'ids') is distinct from 'array' then raise exception 'Image order is required'; end if;
    select coalesce(array_agg(value::uuid),'{}'::uuid[]) into ids from jsonb_array_elements_text(p_payload->'ids');
    if cardinality(ids)>48 or cardinality(ids)<>(select count(distinct value) from unnest(ids) value)
      or cardinality(ids)<>(select count(*) from public.car_images where car_id=p_car)
      or exists(select 1 from unnest(ids) item where not exists(select 1 from public.car_images where id=item and car_id=p_car)) then
      raise exception 'Gallery changed. Refresh before reordering';
    end if;
    update public.car_images i set position=ordered.ordinality-1
    from unnest(ids) with ordinality ordered(id,ordinality) where i.id=ordered.id and i.car_id=p_car;
    get diagnostics changed=row_count;
    if changed<>cardinality(ids) then raise exception 'Gallery update was not permitted'; end if;
  elsif p_operation='delete' then
    select * into photo from public.car_images where id=(p_payload->>'id')::uuid and car_id=p_car for update;
    if found then
      deleted_url:=photo.url;
      delete from public.car_images where id=photo.id and car_id=p_car;
      if not found then raise exception 'Photo deletion was not permitted'; end if;
      if car.cover_image_url=photo.url then
        update public.cars set cover_image_url=(select i.url from public.car_images i where car_id=p_car order by position,id limit 1) where id=p_car;
        if not found then raise exception 'Cover update was not permitted'; end if;
      end if;
    end if;
  elsif p_operation='cover' then
    select * into photo from public.car_images where car_id=p_car and car_images.url=p_payload->>'url' order by position,id limit 1;
    if not found then raise exception 'Choose a photo from this gallery'; end if;
    update public.cars set cover_image_url=photo.url where id=p_car;
    if not found then raise exception 'Cover update was not permitted'; end if;
  else raise exception 'Unsupported gallery change';
  end if;
  return jsonb_build_object('ok',true,'image',case when p_operation='add' then to_jsonb(photo) else null end,'deleted_url',deleted_url);
end $$;


--
-- Name: enqueue_order_receipt(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_order_receipt(p_buyer uuid, p_destination text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 insert into public.remediation_jobs(kind,dedup_key,payload) values('receipt','access:'||p_buyer::text||':'||p_destination,jsonb_build_object('buyer_id',p_buyer,'destination',p_destination)) on conflict(dedup_key) do nothing;
$$;


--
-- Name: enqueue_search_document(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_search_document(p_entity text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if p_entity not in ('listing','car','profile','update') then raise exception 'Unknown search family'; end if;
 insert into public.remediation_jobs(kind,dedup_key,payload) values('search','search:explicit:'||p_entity||':'||p_id||':'||txid_current(),jsonb_build_object('entity',p_entity,'id',p_id)) on conflict(dedup_key) do nothing;
end $$;


--
-- Name: enqueue_transfer_recovery_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_transfer_recovery_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind in ('transfer_after_refund', 'transfer_unresolved')
     and new.status = 'open' then
    insert into public.admin_alert_outbox (
      kind, title, detail, order_id, amount_cents, payload, dedup_key, status
    ) values (
      'transfer_stuck',
      'Seller transfer requires reconciliation',
      new.detail,
      new.order_id,
      new.amount_cents,
      jsonb_build_object(
        'recovery_id', new.id,
        'recovery_key', new.recovery_key,
        'recovery_kind', new.kind
      ),
      'transfer-recovery:' || coalesce(new.recovery_key, new.id::text),
      'pending'
    )
    on conflict (dedup_key) do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: escalate_order_dispute(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_order_dispute(p_order uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  v_opens timestamptz;
  v_until timestamptz;
begin
  if p_order is null or p_actor is null then raise exception 'Order and actor are required'; end if;
  select * into o from public.orders where id = p_order for update;
  if not found or (p_actor is distinct from o.buyer_id and p_actor is distinct from o.seller_id) then
    return jsonb_build_object('ok', false, 'reason', 'not_party');
  end if;
  if o.status <> 'disputed' then return jsonb_build_object('ok', false, 'reason', 'not_disputed'); end if;
  if o.dispute_escalated_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'already_escalated',
      'refund_due', private.not_received_refund_due(o.id));
  end if;

  v_opens := coalesce(o.dispute_respond_by, private.add_business_days(o.disputed_at, 3));
  v_until := coalesce(o.dispute_escalate_until, private.add_business_days(o.disputed_at, 21));
  if v_opens is null or now() < v_opens then
    return jsonb_build_object('ok', false, 'reason', 'too_early', 'opens_at', v_opens);
  end if;
  if now() > v_until then
    return jsonb_build_object('ok', false, 'reason', 'window_closed', 'closed_at', v_until);
  end if;
  -- A live offer is the seller's answer: the buyer accepts it or waits for
  -- its 48 hours to run out. An expired one never blocks, cleaned up or not.
  if p_actor = o.buyer_id and o.refund_offer_cents is not null
     and (o.refund_offered_at is null or o.refund_offer_expires_at > now()) then
    return jsonb_build_object('ok', false, 'reason', 'offer_pending', 'offer_expires_at', o.refund_offer_expires_at);
  end if;

  update public.orders
     set dispute_escalated_at = now(), dispute_escalated_by = p_actor
   where id = o.id;

  return jsonb_build_object('ok', true, 'refund_due', private.not_received_refund_due(o.id));
end $$;


--
-- Name: escalate_stale_disputes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_stale_disputes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count int := 0;
  r record;
begin
  for r in
    select id, buyer_id, seller_id
    from public.orders
    where status = 'disputed'
      and dispute_escalated_at is null
      and now() > coalesce(dispute_respond_by, disputed_at + interval '3 days') + interval '1 day'
  loop
    update public.orders set dispute_escalated_at = now() where id = r.id;

    if r.seller_id is not null then
      perform public.notify(
        r.seller_id, 'dispute_escalated', 'marketplace',
        'A dispute needs your reply',
        'This case is past the response window and is now flagged for DRVN support. '
          || 'Unanswered disputes are refunded to the buyer automatically.',
        '/orders/' || r.id, null
      );
    end if;
    if r.buyer_id is not null then
      perform public.notify(
        r.buyer_id, 'dispute_escalated', 'marketplace',
        'Your dispute was escalated',
        'The seller has not responded in time — DRVN support is now watching this case.',
        '/orders/' || r.id, null
      );
    end if;

    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


--
-- Name: execute_admin_command(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_admin_command(p_action text, p_subject uuid, p_reason text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare actor uuid:=auth.uid(); subject_type text; result jsonb:='{}'; l public.listings; ord public.orders; c public.ops_cases; ids uuid[]; n int; prior public.order_dispute_history;
begin
 if not public.is_admin() or public.admin_role()<>'admin' or not exists(
 select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->'amr','[]'::jsonb)) m
 where m->>'method' in ('totp','mfa/totp') and (m->>'timestamp')::numeric between extract(epoch from now())-900 and extract(epoch from now())+60
 ) then raise exception 'Admin step-up required' using errcode='42501'; end if;
 if length(trim(p_reason))<1 or length(p_reason)>4000 then raise exception 'A reason of 1–4000 characters is required'; end if;
 case p_action
 when 'listing.remove' then
  subject_type:='listing'; select * into strict l from public.listings where id=p_subject for update;
  if l.status in ('reserved','sold','removed') then raise exception 'Listing is not available for removal'; end if;
  update public.listings set status='removed',removed_at=now(),removed_reason=p_reason where id=p_subject;
  insert into public.notifications(user_id,kind,section,title,body,href) values(l.seller_id,'listing_removed','marketplace','A listing was removed',l.title||' — '||p_reason,'/selling');
  result:=jsonb_build_object('previousStatus',l.status);
 when 'listing.restore' then
  subject_type:='listing'; update public.listings set status='paused',removed_at=null,removed_reason=null where id=p_subject and status='removed';
  if not found then raise exception 'Listing is not removed'; end if;
 when 'user.suspend' then
  subject_type:='user';
  if actor=p_subject or exists(select 1 from public.admin_users where user_id=p_subject) then raise exception 'Admin membership is managed separately'; end if;
  update public.profiles set suspended_at=now(),suspended_reason=p_reason where id=p_subject and suspended_at is null;
  if not found then raise exception 'User is already suspended or missing'; end if;
  with paused as(update public.listings set status='paused' where seller_id=p_subject and status='active' returning id) select array_agg(id) into ids from paused;
  result:=jsonb_build_object('pausedListingIds',coalesce(ids,'{}'::uuid[]));
 when 'user.unsuspend' then
  subject_type:='user';
  perform 1 from public.profiles where id=p_subject for update;
  if exists(select 1 from public.remediation_jobs where dedup_key='delete:'||p_subject::text and status in ('pending','processing','failed')) then raise exception 'Account deletion is in progress; this account cannot be reactivated'; end if;
  if exists(select 1 from public.account_deletion_requests where user_id=p_subject) then raise exception 'This member asked for their account to be deleted; it cannot be reactivated'; end if;
  update public.profiles set suspended_at=null,suspended_reason=null where id=p_subject and suspended_at is not null;
  if not found then raise exception 'User is not suspended'; end if;
  select array(select jsonb_array_elements_text(a.metadata->'result'->'pausedListingIds')::uuid) into ids from public.admin_audit_log a where action='user.suspend' and subject_id=p_subject and metadata->'result' is not null order by created_at desc limit 1;
  with restored as(update public.listings set status='active' where id=any(coalesce(ids,'{}'::uuid[])) and seller_id=p_subject and status='paused' returning id) select array_agg(id) into ids from restored;
  result:=jsonb_build_object('reactivatedListingIds',coalesce(ids,'{}'::uuid[]));
 when 'report.actioned','report.dismissed' then
  subject_type:='report'; update public.reports set status=split_part(p_action,'.',2),resolved_by=actor,resolved_at=now(),resolution_note=p_reason where id=p_subject and status='open';
  if not found then raise exception 'Report is already resolved or missing'; end if;
 when 'recovery.recovered','recovery.written_off' then
  subject_type:='payment'; update public.payment_recoveries set status=split_part(p_action,'.',2),resolved_by=actor,resolved_at=now(),resolution_note=p_reason where id=p_subject and status='open';
  if not found then raise exception 'Recovery is already closed or missing'; end if;
 when 'note.internal' then
  subject_type:=p_data->>'subjectType';
  if subject_type not in ('user','listing','order','report','payment','dispute') then raise exception 'Invalid note subject'; end if;
 when 'dispute.resolve_for_seller' then
  subject_type:='dispute'; select * into strict ord from public.orders where id=p_subject for update;
  if ord.status<>'disputed' then raise exception 'Order is not disputed'; end if;
  update public.orders set status=coalesce(pre_dispute_status,'delivered'),dispute_resolved_at=now(),dispute_outcome='admin_resolved',refund_offer_cents=null,refund_offered_at=null where id=p_subject;
  insert into public.notifications(user_id,kind,section,title,body,href)
  select uid,'admin_action','marketplace','DRVN support resolved this dispute','The dispute was closed in the seller''s favour after review.','/orders/'||p_subject from unnest(array[ord.buyer_id,ord.seller_id]) uid where uid is not null;
  result:=jsonb_build_object('restored',ord.pre_dispute_status);
 when 'dispute.reopen' then
  -- 20261107210300 (N91): a resolved in-app case is final for the members;
  -- support may open a follow-up case. The previous case and its resolution
  -- stay in order_dispute_history; the follow-up starts with support, on a
  -- fresh clock, with the previous category and reason.
  subject_type:='dispute'; select * into strict ord from public.orders where id=p_subject for update;
  if ord.status='disputed' then raise exception 'The dispute is already open'; end if;
  if ord.status not in ('paid','shipped','delivered','completed') then raise exception 'Only a paid, unrefunded order can have a dispute reopened'; end if;
  if private.order_has_unresolved_chargeback(p_subject) then raise exception 'A bank chargeback is open on this order'; end if;
  select * into prior from public.order_dispute_history h
   where h.order_id=p_subject and h.event='resolved' and h.kind='in_app'
   order by h.created_at desc, h.id desc limit 1;
  if not found then raise exception 'This order has no resolved dispute to reopen'; end if;
  perform set_config('drvn.dispute_reopen','admin',true);
  update public.orders set status='disputed',pre_dispute_status=ord.status,
   dispute_category=prior.category,dispute_reason=prior.reason,disputed_at=now(),disputed_by=(select p.id from public.profiles p where p.id=prior.opened_by),
   dispute_respond_by=private.add_business_days(now(),3),dispute_escalate_until=private.add_business_days(now(),21),
   dispute_escalated_at=now(),dispute_escalated_by=(select p.id from public.profiles p where p.id=actor),dispute_sla_alerted_at=null,
   dispute_resolved_at=null,dispute_outcome=null,refund_offer_cents=null,refund_offered_at=null
  where id=p_subject;
  perform set_config('drvn.dispute_reopen','',true);
  insert into public.order_dispute_history(order_id,event,kind,category,reason,opened_at,opened_by,pre_dispute_status,actor_id,note,reopened_from)
  values(p_subject,'reopened','in_app',prior.category,prior.reason,now(),prior.opened_by,ord.status,actor,p_reason,prior.id);
  insert into public.notifications(user_id,kind,section,title,body,href)
  select uid,'admin_action','marketplace','DRVN support reopened this dispute','Support reopened the case to review it again. The earlier decision stays on record.','/orders/'||p_subject from unnest(array[ord.buyer_id,ord.seller_id]) uid where uid is not null;
  result:=jsonb_build_object('reopenedFrom',prior.id,'previousOutcome',prior.outcome,'restoredFrom',ord.status);
 when 'order.message_parties' then
  subject_type:='order'; select * into strict ord from public.orders where id=p_subject for update;
  insert into public.notifications(user_id,kind,section,title,body,href)
  select uid,'admin_action','marketplace','A message from DRVN support',p_reason,'/orders/'||p_subject from unnest(array[ord.buyer_id,ord.seller_id]) uid where uid is not null;
  get diagnostics n=row_count; result:=jsonb_build_object('recipients',n);
 when 'case.claim','case.release','case.update' then
  select * into strict c from public.ops_cases where order_id=p_subject or report_id=p_subject for update;
  subject_type:=case when c.kind='dispute' then 'order' else 'report' end;
  if c.status='resolved' then raise exception 'Case is closed'; end if;
  if p_action='case.claim' then
   if c.assigned_to is not null and c.assigned_to<>actor then raise exception 'Case is already assigned'; end if;
   update public.ops_cases set assigned_to=actor,status='claimed',updated_at=now() where id=c.id;
   result:=jsonb_build_object('released',false);
  elsif p_action='case.release' then
   if c.assigned_to is distinct from actor then raise exception 'Only the assignee may release a case'; end if;
   update public.ops_cases set assigned_to=null,status='open',updated_at=now() where id=c.id;
   result:=jsonb_build_object('released',true);
  else
   if p_data->>'priority' not in ('normal','high') or jsonb_typeof(p_data->'labels')<>'array' or jsonb_array_length(p_data->'labels')>6 then raise exception 'Invalid case update'; end if;
   if exists(select 1 from jsonb_array_elements_text(p_data->'labels') label where length(label)>30) then raise exception 'Case label too long'; end if;
   update public.ops_cases set priority=p_data->>'priority',labels=array(select jsonb_array_elements_text(p_data->'labels')),updated_at=now() where id=c.id;
   result:=jsonb_build_object('priority',p_data->>'priority','labels',p_data->'labels');
  end if;

 else raise exception 'Unsupported admin command';
 end case;
 insert into public.admin_audit_log(actor_id,action,subject_type,subject_id,order_id,reason,metadata)
 values(actor,p_action,subject_type,p_subject,(p_data->>'orderId')::uuid,p_reason,jsonb_build_object('phase','completed','result',result));
 return result;
end $$;


--
-- Name: expire_refund_offers(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_refund_offers(p_limit integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select id, buyer_id, seller_id
      from public.orders
     where status = 'disputed'
       and refund_offered_at is not null
       and refund_offer_expires_at <= now()
     order by refund_offer_expires_at, id
     limit least(greatest(coalesce(p_limit, 50), 1), 200)
     for update skip locked
  loop
    update public.orders set refund_offer_cents = null, refund_offered_at = null
     where id = r.id and status = 'disputed' and refund_offered_at is not null
       and refund_offer_expires_at <= now();
    if found then
      n := n + 1;
      if r.buyer_id is not null then
        perform public.notify(r.buyer_id, 'refund_offer_expired', 'marketplace',
          'A refund offer expired', 'The seller''s offer ran out after 48 hours. The case stays open.',
          '/orders/' || r.id, null);
      end if;
      if r.seller_id is not null then
        perform public.notify(r.seller_id, 'refund_offer_expired', 'marketplace',
          'Your refund offer expired', 'The buyer didn''t accept within 48 hours. The case stays open.',
          '/orders/' || r.id, null);
      end if;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: cars; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cars (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    make text,
    model text,
    year integer,
    color text,
    about text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    cover_image_url text,
    is_public boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    vin text,
    "trim" text,
    engine text,
    drivetrain text,
    body_class text,
    vin_decoded_at timestamp with time zone,
    catalog_make_id bigint,
    catalog_model_id bigint,
    identity_source text,
    cover_focal_x numeric(4,3),
    cover_focal_y numeric(4,3),
    make_key text GENERATED ALWAYS AS (lower(make)) STORED,
    model_key text GENERATED ALWAYS AS (lower(model)) STORED,
    generation_id bigint,
    generation_source text,
    CONSTRAINT cars_cover_focal_x_check CHECK (((cover_focal_x IS NULL) OR ((cover_focal_x >= (0)::numeric) AND (cover_focal_x <= (1)::numeric)))),
    CONSTRAINT cars_cover_focal_y_check CHECK (((cover_focal_y IS NULL) OR ((cover_focal_y >= (0)::numeric) AND (cover_focal_y <= (1)::numeric)))),
    CONSTRAINT cars_generation_source_check CHECK ((((generation_source = ANY (ARRAY['resolved'::text, 'owner'::text])) AND (generation_id IS NOT NULL)) OR ((generation_source IS NULL) AND (generation_id IS NULL)))),
    CONSTRAINT cars_identity_source_check CHECK (((identity_source IS NULL) OR (identity_source = ANY (ARRAY['picker'::text, 'vin'::text, 'manual'::text])))),
    CONSTRAINT cars_text_bounds CHECK (((char_length(name) BETWEEN 1 AND 120) AND (char_length(COALESCE(about, ''::text)) <= 4000) AND (char_length(COALESCE(color, ''::text)) <= 60) AND (COALESCE(array_length(tags, 1), 0) <= 20))),
    CONSTRAINT cars_vin_bounds CHECK (((vin IS NULL) OR ((char_length(vin) >= 11) AND (char_length(vin) <= 17))))
);


--
-- Name: COLUMN cars.identity_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cars.identity_source IS 'How the vehicle identity was established: picker (catalog selection), vin (decoded), manual (typed). Null on pre-0041 cars.';


--
-- Name: COLUMN cars.cover_focal_x; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cars.cover_focal_x IS 'Cover framing focal point, 0..1 from the left. Null = center. Render-only (0043).';


--
-- Name: COLUMN cars.generation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cars.generation_id IS 'The car''s generation. Resolved from catalog_model_id + year when exactly one generation covers the year; otherwise null until the owner chooses.';


--
-- Name: COLUMN cars.generation_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cars.generation_source IS 'resolved (the one generation covering model + year) or owner (the owner chose it). Null when generation_id is null.';


--
-- Name: explore_build_rows(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explore_build_rows(p_query text) RETURNS SETOF public.cars
    LANGUAGE sql STABLE
    AS $$
 select c.id, c.owner_id, c.slug, c.name, c.make, c.model, c.year, c.color, c.about, c.tags,
        c.cover_image_url, c.is_public, c.created_at, c.updated_at, null::text as vin, c.trim,
        c.engine, c.drivetrain, c.body_class, c.vin_decoded_at, c.catalog_make_id, c.catalog_model_id,
        c.identity_source, c.cover_focal_x, c.cover_focal_y, c.make_key, c.model_key,
        c.generation_id, c.generation_source
 from public.search_car_ids(p_query) with ordinality ranked(id,rank)
 join public.cars c on c.id=ranked.id where c.is_public order by ranked.rank,c.id;
$$;


--
-- Name: activity_posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.activity_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    car_id uuid,
    author_id uuid NOT NULL,
    title text,
    intro text,
    body jsonb DEFAULT '[]'::jsonb NOT NULL,
    video_url text,
    published_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    search_text text GENERATED ALWAYS AS (public.activity_post_search_text(body)) STORED,
    draft_key uuid,
    draft_archived_at timestamp with time zone,
    publish_operation_id uuid,
    CONSTRAINT activity_posts_text_bounds CHECK (((char_length(title) BETWEEN 1 AND 160) AND (char_length(COALESCE(intro, ''::text)) <= 2000)))
);


--
-- Name: COLUMN activity_posts.car_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.activity_posts.car_id IS 'Optional since W-5. A post must be about a car, a tagged part, or both — see the trigger below.';


--
-- Name: COLUMN activity_posts.title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.activity_posts.title IS 'Optional since the 2026-09 direction: a quick post is a photo and a caption. Readers use postHeadline() rather than assuming a value.';


--
-- Name: COLUMN activity_posts.draft_archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.activity_posts.draft_archived_at IS 'Older duplicate drafts retained in place during the durable-draft upgrade; excluded from the active composer.';


--
-- Name: COLUMN activity_posts.publish_operation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.activity_posts.publish_operation_id IS 'Client-stable UUID used to reconcile a publish whose response was lost.';


--
-- Name: explore_update_page(text, text, integer, integer, integer, integer, timestamp with time zone, uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explore_update_page(p_make text DEFAULT ''::text, p_model text DEFAULT ''::text, p_make_id integer DEFAULT 0, p_model_id integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25, p_by_car_up_to integer DEFAULT 5000) RETURNS SETOF public.activity_posts
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  lim integer := least(greatest(coalesce(p_limit, 25), 1), 101);
  skip integer := least(greatest(coalesce(p_offset, 0), 0), 10000);
  car_rule text := 'c.is_public';
  keyset text := '';
  cars integer;
begin
  -- explore_update_rows' vehicle and year rules, with the values written in.
  if coalesce(p_make, '') <> '' then
    car_rule := car_rule || ' and (' || case when coalesce(p_model_id, 0) <> 0
        then format('c.catalog_model_id = %s', p_model_id) else format('c.catalog_make_id = %s', coalesce(p_make_id, 0)) end
      || format(' or (c.make_key = %L%s))', lower(p_make),
           case when coalesce(p_model, '') <> '' then format(' and c.model_key = %L', lower(p_model)) else '' end);
  end if;
  if not (coalesce(p_ymin, 0) = 0 and coalesce(p_ymax, 9999) = 9999) then
    car_rule := car_rule || format(' and c.year between %s and %s', coalesce(p_ymin, 0), coalesce(p_ymax, 9999));
  end if;
  if p_before_at is not null and p_before_id is not null then
    keyset := format(' and (p.published_at, p.id) < (%L::timestamptz, %L::uuid)', p_before_at, p_before_id);
  end if;

  execute format('select count(*) from (select 1 from public.cars c where %s limit %s) s', car_rule, greatest(coalesce(p_by_car_up_to, 5000), 0) + 1) into cars;
  if cars <= greatest(coalesce(p_by_car_up_to, 5000), 0) then
    return query execute format(
      'select p.* from public.cars c cross join lateral ('
      '  select p.* from public.activity_posts p where p.car_id = c.id and p.published_at is not null%s'
      '  order by p.published_at desc, p.id desc limit %s) p'
      ' where %s order by p.published_at desc, p.id desc limit %s offset %s',
      keyset, lim + skip, car_rule, lim, skip);
  else
    return query execute format(
      'select p.* from public.activity_posts p where p.published_at is not null%s'
      ' and coalesce((select %s from public.cars c where c.id = p.car_id), false)'
      ' order by p.published_at desc, p.id desc limit %s offset %s',
      keyset, car_rule, lim, skip);
  end if;
end;
$$;


--
-- Name: explore_update_rows(text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explore_update_rows(p_query text DEFAULT ''::text, p_make text DEFAULT ''::text, p_model text DEFAULT ''::text, p_make_id integer DEFAULT 0, p_model_id integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999) RETURNS SETOF public.activity_posts
    LANGUAGE sql STABLE
    AS $$
 select p.* from public.activity_posts p join public.cars c on c.id=p.car_id
 left join public.search_update_ids(p_query) with ordinality r(id,rank) on r.id=p.id
 where c.is_public and p.published_at is not null and (trim(p_query)='' or r.id is not null)
 and (p_make='' or (p_model_id<>0 and c.catalog_model_id=p_model_id) or (p_model_id=0 and c.catalog_make_id=p_make_id) or (lower(c.make)=lower(p_make) and (p_model='' or lower(c.model)=lower(p_model))))
 and ((p_ymin=0 and p_ymax=9999) or c.year between p_ymin and p_ymax)
 order by r.rank,p.published_at desc,p.id;
$$;


--
-- Name: explore_update_search_rows(text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explore_update_search_rows(p_query text, p_make text DEFAULT ''::text, p_model text DEFAULT ''::text, p_make_id integer DEFAULT 0, p_model_id integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999) RETURNS SETOF public.activity_posts
    LANGUAGE sql STABLE
    AS $$
 -- The car is a lookup per matched update, not a third table in the join:
 -- with it in the join the planner, guessing at filters it cannot see the
 -- values of, sometimes starts from every car instead of from the matches.
 select p.* from public.search_update_ids(p_query) with ordinality r(id,rank)
 join public.activity_posts p on p.id=r.id
 where p.published_at is not null
 and (select c.is_public
   and (p_make='' or (p_model_id<>0 and c.catalog_model_id=p_model_id) or (p_model_id=0 and c.catalog_make_id=p_make_id) or (lower(c.make)=lower(p_make) and (p_model='' or lower(c.model)=lower(p_model))))
   and ((p_ymin=0 and p_ymax=9999) or c.year between p_ymin and p_ymax)
   from public.cars c where c.id=p.car_id)
 order by r.rank,p.published_at desc,p.id;
$$;


--
-- Name: feed_event_page(text[], integer, integer, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_event_page(p_kinds text[], p_limit integer, p_offset integer DEFAULT 0, p_exclude_owner uuid DEFAULT NULL::uuid, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(kind text, id uuid, happened_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Without a position the comparison is with "the end of time": every row.
  -- Written as one row comparison either way, so it is always a range read
  -- of the index rather than a filter.
  select e.kind, e.id, e.happened_at from (
    (select 'car'::text as kind, c.id, c.created_at as happened_at
       from public.cars c
      where 'car' = any(p_kinds) and c.is_public
        and (p_exclude_owner is null or c.owner_id <> p_exclude_owner)
        and (c.created_at, c.id) < (coalesce(p_before_at, 'infinity'::timestamptz), coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
      order by c.created_at desc, c.id desc
      limit greatest(0, least(p_limit, 200)) + greatest(0, p_offset))
    union all
    (select 'update'::text, p.id, p.published_at
       from public.activity_posts p
      where 'update' = any(p_kinds) and p.published_at is not null
        -- A scalar lookup per row read, not EXISTS: the planner answers EXISTS
        -- by loading every public car first, which costs more than the page.
        and (p.car_id is null or coalesce((select c.is_public from public.cars c where c.id = p.car_id), false))
        and (p_exclude_owner is null or p.author_id <> p_exclude_owner)
        and (p.published_at, p.id) < (coalesce(p_before_at, 'infinity'::timestamptz), coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
      order by p.published_at desc, p.id desc
      limit greatest(0, least(p_limit, 200)) + greatest(0, p_offset))
    union all
    (select 'part'::text, l.id, l.created_at
       from public.listings l
      where 'part' = any(p_kinds) and l.status = 'active'
        and (p_exclude_owner is null or l.seller_id <> p_exclude_owner)
        and (l.created_at, l.id) < (coalesce(p_before_at, 'infinity'::timestamptz), coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
      order by l.created_at desc, l.id desc
      limit greatest(0, least(p_limit, 200)) + greatest(0, p_offset))
  ) e
  order by e.happened_at desc, e.id desc
  limit greatest(0, least(p_limit, 200)) offset greatest(0, p_offset);
$$;


--
-- Name: feed_hydration(uuid[], uuid[], uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_hydration(p_post_ids uuid[], p_car_ids uuid[], p_listing_ids uuid[], p_viewer uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with
  viewer as (
    select case when p_viewer is not null and p_viewer = auth.uid() then p_viewer end as id
  ),
  page_posts as (
    select p.id, p.title, p.intro, p.car_id, p.author_id, p.published_at, p.body
    from public.activity_posts p
    where p.id in (select unnest(coalesce(p_post_ids, '{}'::uuid[])))
  ),
  page_cars as (
    select c.id, c.slug, c.name, c.make, c.model, c.year, c.cover_image_url, c.owner_id, c.created_at
    from public.cars c
    where c.id in (select unnest(coalesce(p_car_ids, '{}'::uuid[])))
  ),
  page_listings as (
    select l.id, l.title, l.price_cents, l.shipping_cents, l.condition, l.grade, l.location,
           l.part_number, l.seller_id, l.source_car_id, l.created_at
    from public.listings l
    where l.id in (select unnest(coalesce(p_listing_ids, '{}'::uuid[])))
  ),
  owner_ids as (
    select owner_id as id from page_cars
    union select author_id from page_posts
    union select seller_id from page_listings
  ),
  liked_ids as (
    select unnest(coalesce(p_listing_ids, '{}') || coalesce(p_car_ids, '{}')) as id
  )
  select jsonb_build_object(
    'posts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'title', p.title, 'intro', p.intro, 'car_id', p.car_id,
        'author_id', p.author_id, 'published_at', p.published_at, 'body', p.body,
        'cover_url', (select i.url from public.activity_images i where i.post_id = p.id order by i.position limit 1),
        'image_count', (select count(*) from public.activity_images i where i.post_id = p.id),
        'reactions', (select count(*) from public.activity_reactions r where r.post_id = p.id and r.emoji = '🔥'),
        'comments', (select count(*) from public.activity_comments c where c.post_id = p.id)
      )) from page_posts p), '[]'::jsonb),

    'cars', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'slug', c.slug, 'name', c.name, 'make', c.make, 'model', c.model, 'year', c.year,
        'cover_image_url', c.cover_image_url, 'owner_id', c.owner_id, 'created_at', c.created_at,
        'update_count', (select count(*) from public.activity_posts a
                          where a.car_id = c.id and a.published_at is not null),
        'last_activity_at', (select max(a.published_at) from public.activity_posts a
                              where a.car_id = c.id and a.published_at is not null),
        'for_sale_count', (select count(*) from public.listings l
                            where l.source_car_id = c.id and l.status = 'active')
      )) from page_cars c), '[]'::jsonb),

    'listings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', l.id, 'title', l.title, 'price_cents', l.price_cents, 'shipping_cents', l.shipping_cents,
        'condition', l.condition, 'grade', l.grade, 'location', l.location, 'part_number', l.part_number,
        'seller_id', l.seller_id, 'source_car_id', l.source_car_id, 'created_at', l.created_at,
        'cover_url', (select i.url from public.listing_images i where i.listing_id = l.id order by i.position limit 1),
        'watch_count', (select w.watchers from public.listing_watch_counts(array[l.id]) w),
        'question_count', (select count(*) from public.listing_questions q where q.listing_id = l.id)
      )) from page_listings l), '[]'::jsonb),

    -- The car of each post: names the build, lends its cover, and is the
    -- visibility gate (a post on a car the caller can't see is dropped).
    'post_cars', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'slug', c.slug, 'name', c.name, 'year', c.year, 'make', c.make, 'model', c.model,
        'is_public', c.is_public, 'cover_image_url', c.cover_image_url
      )) from public.cars c
      where c.id in (select car_id from page_posts where car_id is not null)), '[]'::jsonb),

    -- The source car of each part: the provenance line and fitment source.
    'source_cars', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'year', c.year, 'make', c.make, 'model', c.model, 'slug', c.slug, 'is_public', c.is_public
      )) from public.cars c
      where c.id in (select source_car_id from page_listings where source_car_id is not null)), '[]'::jsonb),

    'owners', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pr.id, 'display_name', pr.display_name, 'username', pr.username, 'avatar_url', pr.avatar_url
      )) from public.profiles pr where pr.id in (select id from owner_ids)), '[]'::jsonb),

    -- Public like counts over the page's listings and cars (0037).
    'likes', coalesce((
      select jsonb_agg(jsonb_build_object('target_type', k.target_type, 'target_id', k.target_id, 'count', k.n))
      from (select lk.target_type, lk.target_id, count(*) as n
              from public.likes lk
             where lk.target_type in ('listing', 'car') and lk.target_id in (select id from liked_ids)
             group by lk.target_type, lk.target_id) k), '[]'::jsonb),

    -- The viewer's garage, for "Fits your <car>" hints.
    'garage', coalesce((
      select jsonb_agg(jsonb_build_object('name', c.name, 'make', c.make, 'model', c.model))
      from public.cars c where c.owner_id = (select id from viewer)), '[]'::jsonb),

    -- The viewer's own marks, so every card renders its toggles pre-fired.
    'viewer_saves', coalesce((
      select jsonb_agg(jsonb_build_object('target_type', s.target_type, 'target_id', s.target_id))
      from public.saves s
      where s.user_id = (select id from viewer)
        and s.target_id = any(coalesce(p_listing_ids, '{}') || coalesce(p_car_ids, '{}') || coalesce(p_post_ids, '{}'))), '[]'::jsonb),
    'viewer_reactions', coalesce((
      select jsonb_agg(r.post_id)
      from public.activity_reactions r
      where r.user_id = (select id from viewer) and r.emoji = '🔥' and r.post_id = any(coalesce(p_post_ids, '{}'))), '[]'::jsonb),
    'viewer_likes', coalesce((
      select jsonb_agg(jsonb_build_object('target_type', lk.target_type, 'target_id', lk.target_id))
      from public.likes lk
      where lk.user_id = (select id from viewer) and lk.target_type in ('listing', 'car') and lk.target_id in (select id from liked_ids)), '[]'::jsonb)
  );
$$;


--
-- Name: finish_capture_check(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_capture_check(p_reference text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ delete from public.capture_checks where reference=p_reference; $$;


--
-- Name: finish_photo_rewrite(text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_photo_rewrite(p_bucket text, p_path text, p_token uuid, p_object uuid, p_outcome text, p_detail text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_object uuid;
  v_updated timestamptz;
begin
  if p_outcome is null or p_outcome not in ('clean', 'scrubbed', 'skipped', 'failed') then
    raise exception 'Unknown rewrite outcome %', p_outcome using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('drvn-media:' || p_bucket || '/' || p_path, 0));
  select o.id, o.updated_at into v_object, v_updated from storage.objects o where o.bucket_id = p_bucket and o.name = p_path;
  if v_object is null then
    delete from private.media_rewrite_claims where bucket = p_bucket and path = p_path and token = p_token;
    return 'gone';
  end if;
  if v_object <> p_object then
    -- Whoever holds the lease now, this object exists only because a write
    -- recreated it. Keep the lease (with the original identity) so the
    -- media cleanup leaves it alone and a later claim knows what it is.
    update private.media_rewrite_claims set claimed_at = now()
     where bucket = p_bucket and path = p_path and token = p_token;
    return 'recreated';
  end if;
  delete from private.media_rewrite_claims where bucket = p_bucket and path = p_path and token = p_token;
  if not found then
    return 'lease_lost';
  end if;
  insert into private.photo_metadata_scrubs (bucket, path, outcome, detail, object_updated_at, checked_at)
  values (p_bucket, p_path, p_outcome, left(p_detail, 500), v_updated, now())
  on conflict (bucket, path) do update
    set outcome = excluded.outcome, detail = excluded.detail,
        object_updated_at = excluded.object_updated_at, checked_at = excluded.checked_at;
  return 'recorded';
end;
$$;


--
-- Name: finish_remediation_job(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_remediation_job(p_id uuid, p_lease uuid, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 update public.remediation_jobs set status=case when p_error is null then 'completed' when attempts>=10 then 'failed' else 'pending' end,
 last_error=left(p_error,500), next_attempt_at=now()+interval '1 minute'*least(60,power(2,attempts)::int), locked_until=null,
 completed_at=case when p_error is null then now() else null end where id=p_id and lease_id=p_lease and status='processing';
 if not found then raise exception 'Job lease lost'; end if;
end $$;


--
-- Name: finish_reservation_expiry(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_reservation_expiry(p_job uuid, p_lease uuid, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare j public.remediation_jobs; o public.orders; ref text; result jsonb;
begin
 select * into j from public.remediation_jobs where id=p_job for update;
 if not found or j.kind<>'reservation_expiry' or j.status<>'processing' or j.lease_id is distinct from p_lease or j.locked_until<=now() then raise exception 'Expiry lease lost'; end if;
 -- One lock order for every path that sells a listing: listing → offer →
 -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
 perform 1 from public.listings where id in (
   select oi.listing_id from public.order_items oi where oi.order_id=(j.payload->>'order_id')::uuid and oi.listing_id is not null
 ) order by id for update;
 select * into o from public.orders where id=(j.payload->>'order_id')::uuid for update;
 if not found or o.status not in ('pending','requires_action') then return jsonb_build_object('outcome','already_resolved'); end if;
 select provider_reference into ref from public.payments where order_id=o.id;
 if p_reference is null then
   if ref is not null or exists(
     select 1 from public.payment_requests
     where (request->'orderIds') ? o.id::text
       and (provider_reference is not null or provider_rejected_at is null)
   ) then
     raise exception 'Payment outcome unresolved; retain reservation';
   end if;
 elsif ref is distinct from p_reference then raise exception 'Expiry payment reference mismatch';
 end if;
 if not exists(select 1 from public.order_items oi join public.listings l on l.id=oi.listing_id where oi.order_id=o.id and l.status='reserved' and l.reserved_until<now()) then
   raise exception 'Reservation is not expired';
 end if;
 result:=public.purchase_finalize(o.id,false,'stripe',p_reference,'checkout expired after payment cancellation or verified absence');
 if not coalesce((result->>'applied')::boolean,false) then raise exception 'Expiry transition refused'; end if;
 return jsonb_build_object('outcome','expired');
end $$;


--
-- Name: followed_feed_rows(integer, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.followed_feed_rows(p_limit integer DEFAULT 21, p_offset integer DEFAULT 0, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(kind text, id uuid, happened_at timestamp with time zone, seller_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with
  bounds as (
    select least(greatest(coalesce(p_limit, 21), 1), 101) as lim,
           least(greatest(coalesce(p_offset, 0), 0), 2000) as skip,
           (p_before_at is not null and p_before_id is not null) as positioned
  ),
  lane as (select lim + case when positioned then 0 else skip end as n from bounds),
  fc as (
    select f.target_id from public.follows f
    where f.follower_id = auth.uid() and f.target_type = 'car'
  ),
  fp as (
    select f.target_id from public.follows f
    where f.follower_id = auth.uid() and f.target_type = 'profile'
  ),
  merged as (
    select x.* from fc cross join lateral (
      select 'update'::text as kind, p.id, p.published_at as happened_at, null::uuid as seller_id
      from public.activity_posts p, bounds b
      where p.car_id = fc.target_id and p.published_at is not null
        and (not b.positioned or (p.published_at, p.id) < (p_before_at, p_before_id))
      order by p.published_at desc, p.id desc
      limit (select n from lane)
    ) x
    union
    select x.* from fp cross join lateral (
      select 'update'::text, p.id, p.published_at, null::uuid
      from public.activity_posts p, bounds b
      where p.author_id = fp.target_id and p.published_at is not null
        and (not b.positioned or (p.published_at, p.id) < (p_before_at, p_before_id))
      order by p.published_at desc, p.id desc
      limit (select n from lane)
    ) x
    union
    select x.* from fc cross join lateral (
      select 'car'::text, c.id, c.created_at, null::uuid
      from public.cars c, bounds b
      where c.id = fc.target_id and c.is_public
        and (not b.positioned or (c.created_at, c.id) < (p_before_at, p_before_id))
    ) x
    union
    select x.* from fp cross join lateral (
      select 'car'::text, c.id, c.created_at, null::uuid
      from public.cars c, bounds b
      where c.owner_id = fp.target_id and c.is_public
        and (not b.positioned or (c.created_at, c.id) < (p_before_at, p_before_id))
      order by c.created_at desc, c.id desc
      limit (select n from lane)
    ) x
    union
    select x.* from fp cross join lateral (
      select 'part'::text, l.id, l.created_at, l.seller_id
      from public.listings l, bounds b
      where l.seller_id = fp.target_id and l.status = 'active'
        and (not b.positioned or (l.created_at, l.id) < (p_before_at, p_before_id))
      order by l.created_at desc, l.id desc
      limit (select n from lane)
    ) x
    union
    select x.* from fc cross join lateral (
      select 'part'::text, l.id, l.created_at, l.seller_id
      from public.listings l, bounds b
      where l.source_car_id = fc.target_id and l.status = 'active'
        and (not b.positioned or (l.created_at, l.id) < (p_before_at, p_before_id))
      order by l.created_at desc, l.id desc
      limit (select n from lane)
    ) x
  )
  select m.kind, m.id, m.happened_at, m.seller_id
  from merged m
  order by m.happened_at desc, m.id desc, m.kind desc
  offset (select case when positioned then 0 else skip end from bounds)
  limit (select lim from bounds);
$$;


--
-- Name: FUNCTION followed_feed_rows(p_limit integer, p_offset integer, p_before_at timestamp with time zone, p_before_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.followed_feed_rows(p_limit integer, p_offset integer, p_before_at timestamp with time zone, p_before_id uuid) IS 'Home''s Following feed: updates, public cars and active parts from the caller''s followed cars and people, newest first, one page from a (happened_at, id) position or an offset of at most 2,000 (N31).';


--
-- Name: forget_deleted_social_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_deleted_social_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_type text := tg_argv[0];
begin
  delete from public.saves where target_type = v_type and target_id = old.id;
  if v_type in ('car', 'profile') then
    delete from public.follows where target_type = v_type and target_id = old.id;
  end if;
  if v_type in ('car', 'listing') then
    delete from public.likes where target_type = v_type and target_id = old.id;
  end if;
  delete from public.notifications where target_id = old.id;
  return old;
end;
$$;


--
-- Name: freeze_accepted_offer_checkout(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_accepted_offer_checkout(p_order uuid, p_actor uuid, p_shipping jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  o public.orders;
  collection boolean;
  offer_status text;
  listing_status text;
  listing_reserved_until timestamptz;
  -- 20261005110000
  collected_total int;
begin
  if p_order is null or p_actor is null or p_shipping is null or jsonb_typeof(p_shipping)<>'object' then
    raise exception 'Invalid accepted-offer checkout';
  end if;
  collection:=(p_shipping->>'isCollection')::boolean;
  if nullif(trim(p_shipping->>'name'),'') is null or collection is null then
    raise exception 'Invalid accepted-offer delivery details';
  end if;
  if not collection and (
    nullif(trim(p_shipping->>'line1'),'') is null
    or nullif(trim(p_shipping->>'city'),'') is null
    or nullif(trim(p_shipping->>'postcode'),'') is null
    or nullif(trim(p_shipping->>'country'),'') is null
  ) then raise exception 'Delivery address is incomplete'; end if;

  -- One lock order for every path that sells a listing: listing → offer →
  -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
  perform 1 from public.listings where id in (
    select oi.listing_id from public.order_items oi where oi.order_id=p_order and oi.listing_id is not null
  ) order by id for update;
  perform 1 from public.offers where id = (select x.origin_offer_id from public.orders x where x.id=p_order) for update;
  select * into strict o from public.orders where id=p_order for update;
  if o.buyer_id is distinct from p_actor then raise exception 'Buyer authorization required' using errcode='42501'; end if;
  if o.origin_offer_id is null then raise exception 'Order is not an accepted-offer reservation'; end if;
  select ofr.status,l.status,l.reserved_until
  into offer_status,listing_status,listing_reserved_until
  from public.offers ofr
  join public.order_items oi on oi.order_id=o.id and oi.listing_id=ofr.listing_id
  join public.listings l on l.id=ofr.listing_id
  where ofr.id=o.origin_offer_id and ofr.buyer_id=o.buyer_id and l.seller_id=o.seller_id
  for update of ofr,l;
  if not found then raise exception 'Accepted-offer reservation identity is inconsistent'; end if;
  if o.status<>'pending' then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,'reason','Accepted-offer reservation is no longer pending.');
  end if;
  if o.accepted_checkout_shipping is not null then
    if o.accepted_checkout_shipping<>p_shipping then
      raise exception 'Accepted-offer delivery details changed after checkout started';
    end if;
    -- 20261005110000: the total the payment must be for.
    return jsonb_build_object('ok',true,'applied',false,'replayed',true,'status',o.status,'total_cents',o.total_cents);
  end if;
  if offer_status<>'accepted' or listing_status<>'reserved'
     or listing_reserved_until is null or listing_reserved_until<=now() then
    raise exception 'Accepted-offer reservation is no longer available';
  end if;

  -- 20261005110000: the same eligibility cart checkout applies, read from
  -- what the order froze when the offer was accepted.
  if collection and exists (
    select 1 from public.order_items oi
    where oi.order_id=o.id
      and coalesce((oi.commercial_snapshot->'commercial'->>'allows_collection')::boolean,false)=false
  ) then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,
      'reason','Local pickup isn''t offered for this part — choose delivery instead.');
  end if;
  if not collection and exists (
    select 1 from public.order_items oi
    where oi.order_id=o.id
      and oi.commercial_snapshot->'commercial'->>'shipping_mode'='pickup_only'
  ) then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,
      'reason','This part is local pickup only — choose to collect it.');
  end if;
  if collection and o.shipping_cents<>0 then
    if exists (select 1 from public.payments where order_id=o.id and provider_reference is not null)
       or exists (select 1 from public.payment_requests where (request->'orderIds') ? o.id::text) then
      raise exception 'Accepted-offer payment already started; its amount cannot change'
        using errcode='55000';
    end if;
    collected_total:=o.subtotal_cents;
    if not public.charge_cents_in_bounds(collected_total::bigint) then
      raise exception 'An accepted offer must come to between $0.50 and $999,999.99'
        using errcode='22003';
    end if;
  end if;

  update public.orders set
    ship_name=p_shipping->>'name',
    ship_line1=coalesce(p_shipping->>'line1',''),
    ship_line2=nullif(p_shipping->>'line2',''),
    ship_city=coalesce(p_shipping->>'city',''),
    ship_postcode=coalesce(p_shipping->>'postcode',''),
    ship_country=coalesce(p_shipping->>'country',''),
    ship_state=nullif(p_shipping->>'state',''),
    ship_phone=nullif(p_shipping->>'phone',''),
    is_collection=collection,
    accepted_checkout_shipping=p_shipping
  where id=o.id;

  -- 20261005110000: a collected order is priced as purchase_begin prices a
  -- collected cart line — no shipping, and the fee on what the buyer pays.
  if collected_total is not null then
    update public.orders set
      shipping_cents=0,
      platform_fee_cents=round(collected_total*1000.0/10000.0),
      total_cents=collected_total
    where id=o.id;
    update public.order_items set
      shipping_cents=0,
      commercial_snapshot=jsonb_set(commercial_snapshot,'{commercial,shipping_cents}','0'::jsonb)
    where order_id=o.id;
    update public.payments set amount_cents=collected_total
    where order_id=o.id and status='pending';
    o.total_cents:=collected_total;
  end if;

  return jsonb_build_object('ok',true,'applied',true,'replayed',false,'status',o.status,'total_cents',o.total_cents);
end $_$;


--
-- Name: freeze_cart_checkout_shipping(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_cart_checkout_shipping(p_buyer uuid, p_idempotency_key text, p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  saved public.purchase_attempts%rowtype;
  target public.orders%rowtype;
  shipping jsonb;
  quote_ids jsonb;
  frozen_quotes jsonb := '[]'::jsonb;
  item record;
  quote public.shipping_rate_quotes%rowtype;
  existing_shipment public.shipments%rowtype;
  frozen_shipment_id uuid;
  result_order jsonb;
  drvn_count int;
  quote_count int;
  existing_count int;
  already_frozen boolean;
  settled_order boolean;
begin
  if p_buyer is null or p_idempotency_key is null or p_order is null then
    raise exception 'Cart shipping freeze requires buyer, attempt, and order'
      using errcode = '22023';
  end if;

  -- Lock order is journal -> order -> quotes. Every replay uses this order.
  select * into saved
    from public.purchase_attempts
   where idempotency_key = p_idempotency_key
   for update;

  if not found or saved.buyer_id is distinct from p_buyer then
    raise exception 'Checkout attempt is unavailable to this buyer'
      using errcode = '42501';
  end if;
  if saved.checkout_context is null
     or jsonb_typeof(saved.checkout_context) <> 'object'
     or saved.checkout_context ->> 'version' is distinct from '1'
     or jsonb_typeof(saved.checkout_context -> 'shipping') <> 'object'
     or jsonb_typeof(saved.checkout_context -> 'quoteIds') <> 'object' then
    raise exception 'Checkout attempt has no valid shipping context'
      using errcode = '22023';
  end if;

  select value into result_order
    from jsonb_array_elements(coalesce(saved.result -> 'orders', '[]'::jsonb))
   where value ->> 'order_id' = p_order::text;
  if not found then
    raise exception 'Order does not belong to this checkout attempt'
      using errcode = '42501';
  end if;

  select * into target
    from public.orders
   where id = p_order
   for update;
  if not found or target.buyer_id is distinct from p_buyer then
    raise exception 'Order is unavailable to this buyer'
      using errcode = '42501';
  end if;
  settled_order := target.status in (
    'paid', 'shipped', 'delivered', 'completed', 'refunded', 'disputed', 'payment_failed'
  );
  if target.status not in ('pending', 'requires_action') and not settled_order then
    raise exception 'Order is no longer awaiting checkout'
      using errcode = '55000';
  end if;

  -- The journal result and live order must still describe the same immutable
  -- listing set. This refuses a corrupted or substituted order id before any
  -- address or quote is written.
  if exists (
    (select oi.listing_id::text from public.order_items oi where oi.order_id = p_order
     except
     select jsonb_array_elements_text(coalesce(result_order -> 'listing_ids', '[]'::jsonb)))
    union all
    (select jsonb_array_elements_text(coalesce(result_order -> 'listing_ids', '[]'::jsonb))
     except
     select oi.listing_id::text from public.order_items oi where oi.order_id = p_order)
  ) then
    raise exception 'Order items do not match the checkout journal'
      using errcode = '55000';
  end if;

  shipping := saved.checkout_context -> 'shipping';
  quote_ids := saved.checkout_context -> 'quoteIds';

  if jsonb_typeof(shipping -> 'isCollection') <> 'boolean'
     or nullif(btrim(shipping ->> 'name'), '') is null then
    raise exception 'Checkout shipping context is malformed'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from jsonb_object_keys(quote_ids) key
     where not (coalesce(saved.request_fingerprint -> 'ids', '[]'::jsonb) ? key)
  ) then
    raise exception 'Checkout contains a quote outside its durable basket'
      using errcode = '42501';
  end if;
  select count(*) into quote_count
    from jsonb_object_keys(quote_ids) key
   where exists (
     select 1 from public.order_items oi
      where oi.order_id = p_order and oi.listing_id::text = key
   );
  select count(*) into drvn_count
    from public.order_items oi
   where oi.order_id = p_order
     and oi.commercial_snapshot -> 'commercial' ->> 'shipping_mode' = 'drvn_shipping';

  if (shipping ->> 'isCollection')::boolean then
    if quote_count <> 0 then
      raise exception 'Collection checkout cannot contain shipping quotes'
        using errcode = '22023';
    end if;
    if exists (
      select 1 from public.order_items oi
       where oi.order_id = p_order
         and coalesce(
           (oi.commercial_snapshot -> 'commercial' ->> 'allows_collection')::boolean,
           false
         ) = false
    ) then
      raise exception 'Collection was not offered by every order item'
        using errcode = '42501';
    end if;
    if target.shipping_cents <> 0
       or exists (select 1 from public.order_items oi where oi.order_id=p_order and oi.shipping_cents<>0) then
      raise exception 'Collection checkout retained a shipping charge'
        using errcode = '55000';
    end if;
  else
    if quote_count <> drvn_count then
      raise exception 'Checkout quote set does not match its DRVN Shipping items'
        using errcode = '22023';
    end if;
    if exists (
      select 1 from public.order_items oi
       where oi.order_id = p_order
         and quote_ids ? oi.listing_id::text
         and oi.commercial_snapshot -> 'commercial' ->> 'shipping_mode' <> 'drvn_shipping'
    ) then
      raise exception 'Checkout contains a quote for a non-DRVN order item'
        using errcode = '42501';
    end if;
  end if;

  -- A previous exact application is safe; any different address is evidence
  -- of state substitution and must never be overwritten during recovery.
  already_frozen := target.ship_name is not null;
  if already_frozen and (
    target.ship_name is distinct from shipping ->> 'name'
    or target.ship_line1 is distinct from coalesce(shipping ->> 'line1', '')
    or target.ship_line2 is distinct from nullif(shipping ->> 'line2', '')
    or target.ship_city is distinct from coalesce(shipping ->> 'city', '')
    or target.ship_postcode is distinct from coalesce(shipping ->> 'postcode', '')
    or target.ship_country is distinct from coalesce(shipping ->> 'country', '')
    or target.ship_state is distinct from nullif(shipping ->> 'state', '')
    or target.ship_phone is distinct from nullif(shipping ->> 'phone', '')
    or target.is_collection is distinct from (shipping ->> 'isCollection')::boolean
  ) then
    raise exception 'Order shipping destination differs from the checkout journal'
      using errcode = '42501';
  end if;

  for item in
    select oi.id, oi.listing_id, oi.shipping_cents
      from public.order_items oi
     where oi.order_id = p_order
       and oi.commercial_snapshot -> 'commercial' ->> 'shipping_mode' = 'drvn_shipping'
     order by oi.listing_id
  loop
    if nullif(quote_ids ->> item.listing_id::text, '') is null then
      raise exception 'DRVN Shipping item is missing its quoted rate'
        using errcode = '22023';
    end if;

    select * into quote
      from public.shipping_rate_quotes q
     where q.id = (quote_ids ->> item.listing_id::text)::uuid
     for update;

    if not found
       or quote.listing_id is distinct from item.listing_id
       or quote.buyer_id is distinct from p_buyer
       or quote.destination_hash is distinct from saved.checkout_context ->> 'destinationHash'
       or quote.consumed_order_id is not null and quote.consumed_order_id is distinct from p_order
       or quote.expires_at <= saved.created_at and quote.consumed_order_id is distinct from p_order
       or quote.amount_cents is distinct from item.shipping_cents
       or quote.amount_cents is distinct from
          (saved.request_fingerprint -> 'shipping' ->> item.listing_id::text)::int
       or quote.currency is distinct from target.currency then
      raise exception 'Quoted rate does not match the durable checkout'
        using errcode = '42501';
    end if;

    frozen_quotes := frozen_quotes || jsonb_build_array(jsonb_build_object(
      'listing_id', item.listing_id,
      'provider', quote.provider,
      'provider_shipment_id', quote.provider_shipment_id,
      'rate_ref', quote.rate_ref,
      'carrier', quote.carrier,
      'service', quote.service,
      'service_label', quote.service_label,
      'amount_cents', quote.amount_cents,
      'currency', quote.currency,
      'est_delivery_days', quote.est_delivery_days,
      'parcel', quote.parcel,
      'quoted_at', quote.created_at
    ));

  end loop;

  if target.shipping_quote is not null and target.shipping_quote is distinct from frozen_quotes then
    raise exception 'Frozen shipping service differs from the checkout journal'
      using errcode = '42501';
  end if;

  if settled_order then
    -- A partially settled multi-seller checkout re-enters this boundary for
    -- every order. Settled projections are immutable here: accept only the
    -- exact, already-complete freeze so the remaining pending order can heal.
    if not already_frozen
       or (drvn_count > 0 and target.shipping_quote is distinct from frozen_quotes)
       or (drvn_count = 0 and target.shipping_quote is not null) then
      raise exception 'Settled order has no exact frozen shipping projection'
        using errcode = '55000';
    end if;
  else
    update public.orders
       set ship_name = shipping ->> 'name',
           ship_line1 = coalesce(shipping ->> 'line1', ''),
           ship_line2 = nullif(shipping ->> 'line2', ''),
           ship_city = coalesce(shipping ->> 'city', ''),
           ship_postcode = coalesce(shipping ->> 'postcode', ''),
           ship_country = coalesce(shipping ->> 'country', ''),
           ship_state = nullif(shipping ->> 'state', ''),
           ship_phone = nullif(shipping ->> 'phone', ''),
           is_collection = (shipping ->> 'isCollection')::boolean,
           shipping_quote = case when drvn_count = 0 then null else frozen_quotes end
     where id = p_order;
  end if;

  -- The order projection is now written inside this transaction. Any failure
  -- while materializing a shipment or item link rolls it back with the quote
  -- consumption, so the payment boundary never observes a partial freeze.
  for item in
    select oi.id, oi.listing_id, oi.shipping_cents
      from public.order_items oi
     where oi.order_id = p_order
       and oi.commercial_snapshot -> 'commercial' ->> 'shipping_mode' = 'drvn_shipping'
     order by oi.listing_id
  loop
    select * into quote
      from public.shipping_rate_quotes q
     where q.id = (quote_ids ->> item.listing_id::text)::uuid;

    select count(*) into existing_count
      from public.shipments s
     where s.order_id = p_order
       and s.direction = 'outbound'
       and s.provider = quote.provider
       and s.provider_shipment_id = quote.provider_shipment_id;
    if existing_count > 1 then
      raise exception 'Checkout has duplicate provider shipments'
        using errcode = '55000';
    end if;

    select * into existing_shipment
      from public.shipments s
     where s.order_id = p_order
       and s.direction = 'outbound'
       and s.provider = quote.provider
       and s.provider_shipment_id = quote.provider_shipment_id
     limit 1;

    if found then
      if existing_shipment.fulfillment_type <> 'drvn_shipping'
         or existing_shipment.return_id is not null
         or existing_shipment.carrier is distinct from quote.carrier
         or existing_shipment.service is distinct from quote.service
         or existing_shipment.quoted_cents is distinct from quote.amount_cents
         or exists (
           select 1 from public.shipment_items si
            where si.shipment_id = existing_shipment.id
              and si.order_item_id <> item.id
         ) then
        raise exception 'Existing shipment differs from the checkout quote'
          using errcode = '42501';
      end if;
      frozen_shipment_id := existing_shipment.id;
    elsif settled_order then
      raise exception 'Settled order is missing its frozen shipment'
        using errcode = '55000';
    else
      insert into public.shipments (
        order_id, direction, provider, provider_shipment_id,
        fulfillment_type, carrier, service, status, quoted_cents
      ) values (
        p_order, 'outbound', quote.provider, quote.provider_shipment_id,
        'drvn_shipping', quote.carrier, quote.service, 'pending', quote.amount_cents
      ) returning id into frozen_shipment_id;
    end if;

    if settled_order then
      if quote.consumed_order_id is distinct from p_order
         or not exists (
           select 1 from public.shipment_items si
            where si.shipment_id = frozen_shipment_id
              and si.order_item_id = item.id
         ) then
        raise exception 'Settled order has an incomplete shipping projection'
          using errcode = '55000';
      end if;
    else
      insert into public.shipment_items (shipment_id, order_item_id)
      values (frozen_shipment_id, item.id)
      on conflict on constraint shipment_items_pkey do nothing;

      update public.shipping_rate_quotes
         set consumed_order_id = p_order
       where id = quote.id
         and (consumed_order_id is null or consumed_order_id = p_order);
      if not found then
        raise exception 'Quoted rate was consumed by another order'
          using errcode = '42501';
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'replayed', already_frozen,
    'shipmentCount', drvn_count
  );
end;
$$;


--
-- Name: freeze_order_deadlines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_order_deadlines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d record;
begin
  if tg_op = 'UPDATE' and (
       (old.dispatch_by is not null and new.dispatch_by is distinct from old.dispatch_by)
    or (old.deliver_by is not null and new.deliver_by is distinct from old.deliver_by)
    or (old.available_by is not null and new.available_by is distinct from old.available_by)
    or (old.delivery_estimate_source is not null and new.delivery_estimate_source is distinct from old.delivery_estimate_source)
  ) then
    raise exception 'Delivery deadlines are frozen at purchase' using errcode = '42501';
  end if;

  if new.status = 'paid'
     and (tg_op = 'INSERT' or old.status is distinct from 'paid')
     and new.dispatch_by is null and new.deliver_by is null and new.available_by is null then
    select * into d from private.order_deadlines(
      new.seller_id, new.is_collection, new.ship_country, new.shipping_quote,
      case when tg_op = 'INSERT' then least(coalesce(new.created_at, now()), now()) else now() end
    );
    new.dispatch_by := d.dispatch_by;
    new.deliver_by := d.deliver_by;
    new.available_by := d.available_by;
    new.delivery_estimate_source := d.estimate_source;
  end if;

  new.refund_offer_expires_at := case
    when new.refund_offered_at is null then null
    else new.refund_offered_at + interval '48 hours'
  end;
  return new;
end $$;


--
-- Name: freeze_transfer_carry(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_transfer_carry(p_order uuid, p_worker text, p_payable_cents integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_intent public.transfer_intents;
  v_collect int := 0;
begin
  if p_order is null or p_worker is null or p_payable_cents is null then
    raise exception 'Invalid carry-forward freeze';
  end if;
  select * into v_intent from public.transfer_intents where order_id = p_order for update;
  if not found
     or v_intent.status <> 'processing'
     or v_intent.locked_by is distinct from p_worker
     or v_intent.lease_expires_at is null
     or v_intent.lease_expires_at <= now() then
    return null;
  end if;
  if v_intent.provider_call_may_have_occurred or v_intent.operation_key is not null then
    return coalesce(v_intent.dispatch_carry_cents, 0);
  end if;
  if v_intent.seller_id is not null and p_payable_cents > 1 then
    perform pg_advisory_xact_lock(hashtextextended('seller-carry:' || v_intent.seller_id::text, 0));
    v_collect := least(public.seller_carry_available_cents(v_intent.seller_id, p_order), p_payable_cents - 1);
  end if;
  update public.transfer_intents
     set dispatch_carry_cents = v_collect, updated_at = now()
   where order_id = p_order;
  return v_collect;
end;
$$;


--
-- Name: garage_car_stats(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.garage_car_stats(p_cars uuid[]) RETURNS TABLE(car_id uuid, mods integer, updates integer, latest_update jsonb, parts_live integer, parts_held integer, parts_sold integer, open_offers integer, followers integer, likes integer, sales_count integer, sales_cents bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with mine as (
    select c.id from public.cars c
    where c.id = any(p_cars) and c.owner_id = auth.uid()
  ),
  mod_counts as (
    select m.car_id, count(*)::integer as n
    from public.mod_items m join mine on mine.id = m.car_id
    where m.status = 'installed'
    group by m.car_id
  ),
  post_counts as (
    select p.car_id, count(*)::integer as n
    from public.activity_posts p join mine on mine.id = p.car_id
    where p.published_at is not null
    group by p.car_id
  ),
  latest as (
    select distinct on (p.car_id)
      p.car_id,
      jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'intro', p.intro,
        'body', p.body,
        'published_at', p.published_at,
        'cover_url', (
          select ai.url from public.activity_images ai
          where ai.post_id = p.id order by ai.position limit 1
        )
      ) as post
    from public.activity_posts p join mine on mine.id = p.car_id
    where p.published_at is not null
    order by p.car_id, p.published_at desc, p.id desc
  ),
  parts as (
    select
      l.source_car_id as car_id,
      count(*) filter (where l.status = 'active')::integer as live,
      count(*) filter (where l.status = 'reserved')::integer as held,
      count(*) filter (where l.status = 'sold')::integer as sold,
      coalesce(sum((
        select count(*) from public.offers o
        where o.listing_id = l.id and o.status = 'open'
      )) filter (where l.status <> 'sold'), 0)::integer as offers
    from public.listings l join mine on mine.id = l.source_car_id
    where l.status in ('active', 'reserved', 'sold')
    group by l.source_car_id
  ),
  follow_counts as (
    select f.target_id as car_id, count(*)::integer as n
    from public.follows f join mine on mine.id = f.target_id
    where f.target_type = 'car'
    group by f.target_id
  ),
  like_counts as (
    select k.target_id as car_id, count(*)::integer as n
    from public.likes k join mine on mine.id = k.target_id
    where k.target_type = 'car'
    group by k.target_id
  ),
  -- Every unit the caller sold on DRVN, at the price the buyer paid.
  sold_items as (
    select
      oi.id as item_id,
      oi.order_id,
      coalesce(
        case when (oi.commercial_snapshot -> 'source_car' ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (oi.commercial_snapshot -> 'source_car' ->> 'id')::uuid end,
        l.source_car_id
      ) as car_id,
      oi.price_cents::bigint as unit_cents,
      greatest(coalesce(oi.quantity, 1), 1) as quantity,
      oi.price_cents::bigint * greatest(coalesce(oi.quantity, 1), 1) as goods_cents
    from public.orders o
    join public.order_items oi on oi.order_id = o.id
    left join public.listings l on l.id = oi.listing_id
    where o.seller_id = auth.uid()
      and o.status in ('paid', 'shipped', 'delivered', 'completed')
  ),
  -- A completed return's refund belongs to the returned units: up to their
  -- goods value (a return refund also carries a shipping share), split
  -- across the return's lines in whole cents. Read from the return itself —
  -- refund_operations isn't visible to the seller — and step 2 caps it by
  -- what the order actually shows as refunded.
  returned_lines as (
    select r.id as return_id, s.item_id, s.order_id,
           s.unit_cents * least(ri.quantity, s.quantity) as weight,
           greatest(coalesce(r.refund_amount_cents, 0) - coalesce(r.label_deduction_cents, 0), 0)::bigint as refund_cents
    from public.returns r
    join public.return_items ri on ri.return_id = r.id
    join sold_items s on s.item_id = ri.order_item_id
    where r.status = 'completed'
  ),
  return_shares as (
    select q.*, least(q.refund_cents, (sum(q.weight) over (partition by q.return_id))::bigint) as total,
           (sum(q.weight) over (partition by q.return_id))::bigint as weights
    from returned_lines q
  ),
  return_alloc as (
    select a.item_id, a.order_id,
           a.floor_cents + case when row_number() over (
             partition by a.return_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.return_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.weight) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.weight) % x.weights else 0 end as remainder
      from return_shares x
    ) a
  ),
  -- The order's confirmed refunds that can be goods refunds: never more
  -- than the goods themselves, and not the shipping share of a completed
  -- return's refund (the part beyond its returned goods).
  return_shipping as (
    select q.order_id, (sum(q.refund_cents - q.total))::bigint as cents
    from (select distinct on (return_id) order_id, refund_cents, total from return_shares order by return_id) q
    group by q.order_id
  ),
  order_refunds as (
    select s.order_id,
           least(greatest(coalesce(o.refunded_cents, 0)::bigint - coalesce(rs.cents, 0), 0),
                 (sum(s.goods_cents))::bigint) as goods_refund
    from sold_items s
    join public.orders o on o.id = s.order_id
    left join return_shipping rs on rs.order_id = s.order_id
    group by s.order_id, o.refunded_cents, rs.cents
  ),
  item_returns as (
    select s.item_id, s.order_id,
           least(coalesce((sum(ra.cents))::bigint, 0), s.goods_cents) as cents
    from sold_items s left join return_alloc ra on ra.item_id = s.item_id
    group by s.item_id, s.order_id, s.goods_cents
  ),
  -- Item-attributed refunds can't exceed what the order still shows as
  -- refunded (a late refund failure gives money back): cap them per order,
  -- again in whole cents.
  specific as (
    select a.item_id, a.order_id,
           a.floor_cents + case when row_number() over (
             partition by a.order_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.order_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.cents) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.cents) % x.weights else 0 end as remainder
      from (
        select ir.item_id, ir.order_id, ir.cents,
               (sum(ir.cents) over (partition by ir.order_id))::bigint as weights,
               least((sum(ir.cents) over (partition by ir.order_id))::bigint, r.goods_refund) as total
        from item_returns ir join order_refunds r on r.order_id = ir.order_id
      ) x
    ) a
  ),
  -- Whatever refund no return explains is shared across what's left of the
  -- order's goods by value — floor each share, then hand out the leftover
  -- cents by largest remainder (ties by item id). The shares add up to the
  -- refund exactly, to the cent.
  general as (
    select a.item_id,
           a.floor_cents + case when row_number() over (
             partition by a.order_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.order_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.weight) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.weight) % x.weights else 0 end as remainder
      from (
        select s.item_id, s.order_id,
               s.goods_cents - sp.cents as weight,
               (sum(s.goods_cents - sp.cents) over (partition by s.order_id))::bigint as weights,
               r.goods_refund - (sum(sp.cents) over (partition by s.order_id))::bigint as total
        from sold_items s
        join specific sp on sp.item_id = s.item_id
        join order_refunds r on r.order_id = s.order_id
      ) x
    ) a
  ),
  sales as (
    select s.car_id,
           count(*) filter (where s.goods_cents - sp.cents - g.cents > 0)::integer as n,
           sum(s.goods_cents - sp.cents - g.cents)::bigint as cents
    from sold_items s
    join specific sp on sp.item_id = s.item_id
    join general g on g.item_id = s.item_id
    join mine on mine.id = s.car_id
    group by s.car_id
  )
  select
    mine.id,
    coalesce(mod_counts.n, 0),
    coalesce(post_counts.n, 0),
    latest.post,
    coalesce(parts.live, 0),
    coalesce(parts.held, 0),
    coalesce(parts.sold, 0),
    coalesce(parts.offers, 0),
    coalesce(follow_counts.n, 0),
    coalesce(like_counts.n, 0),
    coalesce(sales.n, 0),
    coalesce(sales.cents, 0)
  from mine
  left join mod_counts on mod_counts.car_id = mine.id
  left join post_counts on post_counts.car_id = mine.id
  left join latest on latest.car_id = mine.id
  left join parts on parts.car_id = mine.id
  left join follow_counts on follow_counts.car_id = mine.id
  left join like_counts on like_counts.car_id = mine.id
  left join sales on sales.car_id = mine.id;
$_$;


--
-- Name: grow_products(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grow_products(p_full boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_started timestamptz := clock_timestamp();
  v_since timestamptz;
  v_created int := 0;
  v_linked int := 0;
  v_merged int := 0;
  v_opened int := 0;
  v_obsolete int := 0;
  v_n int;
  r record;
  v_a uuid;
  v_b uuid;
  v_result jsonb;
  v_queue bigint;
begin
  -- One run at a time; a run that finds another in progress does nothing.
  if not pg_try_advisory_xact_lock(hashtext('public.grow_products')) then
    return jsonb_build_object('skipped', 'another run in progress');
  end if;
  if not p_full then
    -- A minute of overlap: a write committed just as the last run started.
    select max((result ->> 'started_at')::timestamptz) - interval '1 minute' into v_since
    from public.product_grow_runs where result ? 'started_at';
  end if;
  -- (v_since null = everything: the first run, or a full one.)
  -- What changed since the last run, as the write triggers queued it. Rows
  -- queued while this run works stay for the next one.
  select coalesce(max(q.id), 0) into v_queue from public.product_grow_queue q;

  -- The brand + number members wrote, from listings and build lines.
  create temp table if not exists grow_seen (
    brand_key text, number_compact text, brand text, number text, name text, category text,
    src text, listing_id uuid, mod_item_id uuid, created_at timestamptz
  ) on commit drop;
  truncate grow_seen;
  -- Two statements, not one with "everything, or the queued ids": that
  -- condition hides the ids from the planner, which then reads every listing.
  if v_since is null then
    insert into grow_seen
    select s.* from (
      select nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), ''),
             l.part_number_compact, btrim(l.brand), btrim(l.part_number), l.title, l.category,
             'listing', l.id, null::uuid, l.created_at
      from public.listings l
      where l.part_number_compact is not null and l.status not in ('draft', 'removed')
      union all
      select m.brand_key, m.part_number_compact,
             -- Display only: the paste parser leaves leading punctuation ("-Bosch").
             regexp_replace(btrim(m.brand), '^[^[:alnum:]]+', ''), btrim(m.part_number), m.product, m.category,
             'mod', null::uuid, m.id, m.created_at
      from public.mod_items m
      where m.part_number_compact is not null
    ) s(brand_key, number_compact, brand, number, name, category, src, listing_id, mod_item_id, created_at)
    where s.number_compact ~ '[0-9]' and char_length(s.number_compact) between 3 and 64;
  else
    insert into grow_seen
    select s.* from (
      select nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), ''),
             l.part_number_compact, btrim(l.brand), btrim(l.part_number), l.title, l.category,
             'listing', l.id, null::uuid, l.created_at
      from (select distinct q.listing_id from public.product_grow_queue q
            where q.id <= v_queue and q.listing_id is not null) q
      join public.listings l on l.id = q.listing_id
      where l.part_number_compact is not null and l.status not in ('draft', 'removed')
      union all
      select m.brand_key, m.part_number_compact,
             regexp_replace(btrim(m.brand), '^[^[:alnum:]]+', ''), btrim(m.part_number), m.product, m.category,
             'mod', null::uuid, m.id, m.created_at
      from (select distinct q.mod_item_id from public.product_grow_queue q
            where q.id <= v_queue and q.mod_item_id is not null) q
      join public.mod_items m on m.id = q.mod_item_id
      where m.part_number_compact is not null
    ) s(brand_key, number_compact, brand, number, name, category, src, listing_id, mod_item_id, created_at)
    where s.number_compact ~ '[0-9]' and char_length(s.number_compact) between 3 and 64;
  end if;
  -- In a full run grow_seen holds every live record, so "does anything
  -- still point at this identifier" is answered here first.
  create index if not exists grow_seen_key on grow_seen (brand_key, number_compact);
  analyze grow_seen;

  -- 1. A product for every brand + number no product holds yet. A listing
  -- names it before a build line does; the earliest record names it.
  with fresh as materialized (
    select distinct on (s.brand_key, s.number_compact)
           gen_random_uuid() as id, s.brand_key, s.number_compact,
           left(coalesce(nullif(s.brand, ''), s.brand_key), 80) as brand, left(s.number, 80) as number,
           left(s.name, 200) as name, left(s.category, 80) as category, s.src
    from grow_seen s
    where s.brand_key is not null and char_length(s.brand_key) <= 64
      and not exists (select 1 from public.product_part_numbers pm
                      where pm.brand_key = s.brand_key and pm.number_compact = s.number_compact)
    order by s.brand_key, s.number_compact, (s.src = 'listing') desc, s.created_at, coalesce(s.listing_id, s.mod_item_id)
  ), made as (
    insert into public.products (id, brand_key, brand, name, category, created_from)
    select f.id, f.brand_key, f.brand, f.name, f.category, f.src from fresh f
    returning id
  )
  insert into public.product_part_numbers (brand_key, number_compact, product_id, number, basis)
  select f.brand_key, f.number_compact, f.id, f.number, 'brand_and_number'
  from fresh f join made on made.id = f.id;
  get diagnostics v_created = row_count;

  -- The numbers this run is about: what was written, and what links name —
  -- every link in a full run, links added or verified since in an hourly
  -- one. Every statement below joins this list: an "everything, or only
  -- these" condition (v_since is null or ...) hides the list from the
  -- planner, which then reads all products (20 s at 2M parts).
  create temp table if not exists grow_numbers (number_compact text primary key) on commit drop;
  truncate grow_numbers;
  insert into grow_numbers select distinct number_compact from grow_seen on conflict do nothing;
  if v_since is null then
    insert into grow_numbers
    select n from public.part_number_links l, lateral (values (l.from_compact), (l.to_compact)) v(n)
    on conflict do nothing;
  else
    insert into grow_numbers
    select n from public.part_number_links l, lateral (values (l.from_compact), (l.to_compact)) v(n)
    where l.created_at >= v_since
    union
    select n from public.part_number_links l, lateral (values (l.from_compact), (l.to_compact)) v(n)
    where l.verified_at >= v_since
    on conflict do nothing;
  end if;
  analyze grow_numbers;

  -- 2. Brand-scoped same_product links join their two pairs' products.
  for r in
    select l.id, l.from_brand_key, l.from_compact, l.to_brand_key, l.to_compact
    from public.part_number_links l
    where l.kind = 'same_product' and l.from_brand_key is not null
      and exists (select 1 from grow_numbers g where g.number_compact in (l.from_compact, l.to_compact))
    order by l.created_at, l.id
  loop
    select pm.product_id into v_a from public.product_part_numbers pm
     where pm.brand_key = r.from_brand_key and pm.number_compact = r.from_compact;
    select pm.product_id into v_b from public.product_part_numbers pm
     where pm.brand_key = r.to_brand_key and pm.number_compact = r.to_compact;
    if v_a is null and v_b is null then
      continue; -- nobody has written either number: no product to grow
    elsif v_a is null or v_b is null then
      if char_length(case when v_a is null then r.from_compact else r.to_compact end) between 3 and 64 then
        insert into public.product_part_numbers (brand_key, number_compact, product_id, basis, link_id)
        values (case when v_a is null then r.from_brand_key else r.to_brand_key end,
                case when v_a is null then r.from_compact else r.to_compact end,
                coalesce(v_a, v_b), 'same_product_link', r.id)
        on conflict (brand_key, number_compact) do nothing;
        get diagnostics v_n = row_count;
        v_linked := v_linked + v_n;
      end if;
    elsif v_a <> v_b then
      perform public.merge_products(array[v_a, v_b], 'same_product_link', null);
      v_merged := v_merged + 1;
    end if;
  end loop;

  -- 3. File what's ambiguous.
  -- One number, several brands' products.
  insert into public.product_identity_reviews (kind, dedup_key, number_compact, brand_keys, product_ids, detail)
  select 'number_across_brands',
         left('nab:' || x.number_compact || ':' || array_to_string(x.brand_keys, ','), 400),
         x.number_compact, x.brand_keys, x.product_ids,
         jsonb_build_object('brands', x.brands)
  from (
    select pm.number_compact,
           array_agg(pm.brand_key order by pm.brand_key) as brand_keys,
           array_agg(pm.product_id order by pm.brand_key) as product_ids,
           array_agg(p.brand order by pm.brand_key) as brands
    from (
      -- Numbers held by more than one identifier: nearly every number has
      -- one, so this narrows 2M numbers to the few worth checking.
      select pm.number_compact
      from grow_numbers g join public.product_part_numbers pm on pm.number_compact = g.number_compact
      group by pm.number_compact having count(*) > 1
    ) g
    join public.product_part_numbers pm on pm.number_compact = g.number_compact
    join public.products p on p.id = pm.product_id and p.status = 'active'
    -- Only identifiers something still points at. A seller who corrects a
    -- brand leaves the old brand + number with no record; that is not two
    -- brands sharing a number.
    where (pm.basis <> 'brand_and_number'
           or exists (select 1 from grow_seen s where s.brand_key = pm.brand_key and s.number_compact = pm.number_compact)
           or v_since is not null and exists (select 1 from public.listings l
                      where l.part_number_compact = pm.number_compact and l.status not in ('draft', 'removed')
                        and nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), '') = pm.brand_key)
           or v_since is not null and exists (select 1 from public.mod_items m
                      where m.part_number_compact = pm.number_compact and m.brand_key = pm.brand_key))
    group by pm.number_compact
    having count(distinct pm.product_id) > 1
  ) x
  on conflict (dedup_key) do nothing;
  get diagnostics v_n = row_count;
  v_opened := v_opened + v_n;

  -- A number we know, written without a brand.
  insert into public.product_identity_reviews (kind, dedup_key, number_compact, brand_keys, product_ids,
                                               listing_id, mod_item_id, detail)
  select 'brandless_number',
         'brandless:' || s.src || ':' || coalesce(s.listing_id, s.mod_item_id),
         s.number_compact, k.brand_keys, k.product_ids, s.listing_id, s.mod_item_id,
         jsonb_build_object('number', s.number, 'name', left(s.name, 200))
  from grow_seen s
  cross join lateral (
    select array_agg(pm.brand_key order by pm.brand_key) as brand_keys,
           array_agg(pm.product_id order by pm.brand_key) as product_ids
    from public.product_part_numbers pm where pm.number_compact = s.number_compact
  ) k
  where s.brand_key is null and k.product_ids is not null
  on conflict (dedup_key) do nothing;
  get diagnostics v_n = row_count;
  v_opened := v_opened + v_n;

  -- "Same product", without saying whose, between numbers two products hold.
  insert into public.product_identity_reviews (kind, dedup_key, number_compact, brand_keys, product_ids, link_id, detail)
  select 'unscoped_same_product', 'link:' || l.id, l.from_compact, k.brand_keys, k.product_ids, l.id,
         jsonb_build_object('from', l.from_compact, 'to', l.to_compact, 'source', l.source, 'source_ref', l.source_ref)
  from public.part_number_links l
  cross join lateral (
    select array_agg(distinct pm.brand_key) as brand_keys, array_agg(distinct pm.product_id) as product_ids
    from public.product_part_numbers pm where pm.number_compact in (l.from_compact, l.to_compact)
  ) k
  where l.kind = 'same_product' and l.from_brand_key is null
    and exists (select 1 from grow_numbers g where g.number_compact in (l.from_compact, l.to_compact))
    and exists (select 1 from public.product_part_numbers pm where pm.number_compact = l.from_compact)
    and exists (select 1 from public.product_part_numbers pm where pm.number_compact = l.to_compact)
    and cardinality(k.product_ids) > 1
  on conflict (dedup_key) do nothing;
  get diagnostics v_n = row_count;
  v_opened := v_opened + v_n;

  -- A listing's "also known as" number held by another product of its brand.
  insert into public.product_identity_reviews (kind, dedup_key, number_compact, brand_keys, product_ids, listing_id, detail)
  select 'listing_alternate', 'alt:' || s.listing_id || ':' || pn.number_compact, s.number_compact,
         array[s.brand_key], array[a.product_id, b.product_id], s.listing_id,
         jsonb_build_object('number', s.number, 'also_known_as', pn.number)
  from grow_seen s
  join public.listing_part_numbers pn on pn.listing_id = s.listing_id and pn.number_compact <> s.number_compact
  join public.product_part_numbers a on a.brand_key = s.brand_key and a.number_compact = s.number_compact
  join public.product_part_numbers b on b.brand_key = s.brand_key and b.number_compact = pn.number_compact
  where s.src = 'listing' and s.brand_key is not null and a.product_id <> b.product_id
  on conflict (dedup_key) do nothing;
  get diagnostics v_n = row_count;
  v_opened := v_opened + v_n;

  -- 4. Close what is no longer ambiguous: the products are now one, or the
  -- record has a brand, no longer carries the number, or is gone from sale
  -- for good. Read from the record itself, so an incremental run is right.
  update public.product_identity_reviews rv
     set status = 'obsolete', resolved_at = now(),
         resolution_note = 'No longer ambiguous: ' || case rv.kind
           when 'brandless_number' then 'the record now has a brand, or no longer has this number.'
           else 'these numbers now belong to one product.' end
   where rv.status = 'open'
     and case rv.kind
       when 'brandless_number' then not exists (
         select 1 from public.listings l
         where l.id = rv.listing_id and l.part_number_compact = rv.number_compact
           and nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), '') is null
           and l.status not in ('draft', 'removed')
         union all
         select 1 from public.mod_items m
         where m.id = rv.mod_item_id and m.part_number_compact = rv.number_compact and m.brand_key is null)
       when 'number_across_brands' then (
         select count(distinct coalesce(p.merged_into, p.id))
         from public.product_part_numbers pm join public.products p on p.id = pm.product_id
         where pm.number_compact = rv.number_compact and (pm.basis <> 'brand_and_number'
             or exists (select 1 from public.listings l
                        where l.part_number_compact = pm.number_compact and l.status not in ('draft', 'removed')
                          and nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), '') = pm.brand_key)
             or exists (select 1 from public.mod_items m
                        where m.part_number_compact = pm.number_compact and m.brand_key = pm.brand_key))) <= 1
       else (
         select count(distinct coalesce(p.merged_into, p.id)) from public.products p where p.id = any(rv.product_ids)) <= 1
     end;
  get diagnostics v_obsolete = row_count;

  -- What this run read leaves the queue.
  delete from public.product_grow_queue q where q.id <= v_queue;

  v_result := jsonb_build_object(
    'started_at', v_started, 'full', v_since is null, 'seen', (select count(*) from grow_seen),
    'numbers', (select count(*) from grow_numbers),
    'products_created', v_created, 'numbers_linked', v_linked, 'merges', v_merged,
    'reviews_opened', v_opened, 'reviews_obsolete', v_obsolete,
    'ms', round(extract(epoch from clock_timestamp() - v_started) * 1000));
  -- Coverage reads everything; measured on full runs only (and on demand
  -- through product_coverage()).
  if v_since is null then
    v_result := v_result || jsonb_build_object('coverage', public.product_coverage());
  end if;
  insert into public.product_grow_runs (result) values (v_result);
  delete from public.product_grow_runs
   where id < (select min(id) from (select id from public.product_grow_runs order by id desc limit 500) k);
  return v_result;
end;
$$;


--
-- Name: guard_accepted_checkout_shipping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_accepted_checkout_shipping() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer()
     and current_setting('drvn.account_scrub', true) = old.buyer_id::text then
    return new;
  end if;
  if old.accepted_checkout_shipping is not null and (
    new.accepted_checkout_shipping is distinct from old.accepted_checkout_shipping
    or new.ship_name is distinct from old.ship_name
    or new.ship_line1 is distinct from old.ship_line1
    or new.ship_line2 is distinct from old.ship_line2
    or new.ship_city is distinct from old.ship_city
    or new.ship_postcode is distinct from old.ship_postcode
    or new.ship_country is distinct from old.ship_country
    or new.ship_state is distinct from old.ship_state
    or new.ship_phone is distinct from old.ship_phone
    or new.is_collection is distinct from old.is_collection
  ) then raise exception 'Accepted-offer delivery details are immutable after checkout starts'; end if;
  return new;
end $$;


--
-- Name: guard_activity_comment_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_activity_comment_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.post_id is distinct from old.post_id or new.author_id is distinct from old.author_id then
    raise exception 'a comment stays on its post' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_activity_durable_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_activity_durable_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer()
    or current_setting('drvn.activity_write', true) = 'v1'
    or (tg_table_name = 'activity_images' and tg_op = 'DELETE' and pg_trigger_depth() > 1)
  then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  raise exception 'activity content must use the durable write operation'
    using errcode = '42501';
end;
$$;


--
-- Name: guard_activity_post_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_activity_post_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.car_id is distinct from old.car_id then
    raise exception 'an update belongs to the car it was filed against'
      using errcode = '42501';
  end if;
  if new.author_id is distinct from old.author_id then
    raise exception 'author is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_agent_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_agent_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' then
    -- A cascade from a deleted job or mandate only clears its link.
    if pg_trigger_depth() > 1
       and (to_jsonb(new) - 'job_id' - 'mandate_id') = (to_jsonb(old) - 'job_id' - 'mandate_id') then
      return new;
    end if;
    raise exception '% is append-only', tg_table_name using errcode = '42501';
  end if;
  if pg_trigger_depth() > 1 or current_setting('drvn.agent_purge', true) = 'on' then
    return old;
  end if;
  raise exception '% is append-only', tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: guard_agent_mandate_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_agent_mandate_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = old.status then return new; end if;
  if old.status in ('revoked', 'ended')
     or not (old.status, new.status) in (('active', 'paused'), ('paused', 'active'), ('active', 'revoked'),
       ('paused', 'revoked'), ('active', 'ended'), ('paused', 'ended')) then
    raise exception 'Mandate cannot move from % to %', old.status, new.status using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: guard_agent_task_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_agent_task_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.objective := public.agent_redact_cards(new.objective);
    return new;
  end if;
  if new.objective is distinct from old.objective then
    new.objective := public.agent_redact_cards(new.objective);
  end if;
  if new.status = old.status then return new; end if;
  if old.status in ('completed', 'failed', 'cancelled') then
    raise exception 'Task is finished' using errcode = '23514';
  end if;
  new.updated_at := now();
  new.finished_at := case when new.status in ('completed', 'failed', 'cancelled') then now() end;
  return new;
end;
$$;


--
-- Name: guard_audit_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_audit_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.subject_type = 'export' or new.action like 'export.%' then
    if new.subject_type <> 'export' or new.action not in ('export.started', 'export.completed', 'export.failed') then
      raise exception 'export records are export.started, export.completed or export.failed on an export subject'
        using errcode = '22023';
    end if;
    if new.actor_id is null or not exists (select 1 from public.admin_users au where au.user_id = new.actor_id) then
      raise exception 'export records can only name console members (got %)', new.actor_id
        using errcode = '42501';
    end if;
    return new;
  end if;
  if new.actor_id is null or not exists (
    select 1 from public.admin_users au
    where au.user_id = new.actor_id and au.role = 'admin'
  ) then
    raise exception 'audit rows can only name full admins as actors (got %)', new.actor_id
      using errcode = '42501';
  end if;
  return new;
end;
$$;


