--
-- Name: guard_late_refund_payout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_late_refund_payout() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if new.provider_call_may_have_occurred and not old.provider_call_may_have_occurred then
  perform 1 from public.orders where id=new.order_id for update;
  if exists(select 1 from public.payment_recoveries where order_id=new.order_id and kind='refund_late_failure' and status='open') then
   raise exception 'Reconcile the late refund before dispatching a new seller payout';
  end if;
 end if;
 return new;
end $$;


--
-- Name: guard_listing_child_member_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_child_member_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_listing uuid;
  v_status text;
  v_count integer;
  v_cap integer := tg_argv[0]::integer;
begin
  if public.is_trusted_writer() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'UPDATE' and new.listing_id is distinct from old.listing_id then
    raise exception 'A listing''s % can''t be moved to another listing', tg_table_name
      using errcode = '42501';
  end if;
  v_listing := case when tg_op = 'DELETE' then old.listing_id else new.listing_id end;

  select l.status into v_status from public.listings l where l.id = v_listing for update;
  if not found then
    -- The listing is being deleted with its rows, or isn't the caller's
    -- (the table's own policy refuses that write).
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if v_status in ('reserved', 'sold', 'removed') then
    raise exception 'A sold, reserved or removed listing can''t be edited' using errcode = '55000';
  end if;
  if tg_op = 'INSERT' then
    execute format('select count(*) from public.%I where listing_id = $1', tg_table_name)
      into v_count using v_listing;
    if v_count >= v_cap then
      raise exception 'A listing holds at most % rows in %', v_cap, tg_table_name
        using errcode = '54000';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$_$;


--
-- Name: guard_listing_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return old;
  end if;
  if old.status in ('reserved', 'sold') then
    raise exception 'cannot delete a listing that is reserved or sold'
      using errcode = '42501';
  end if;
  return old;
end;
$$;


--
-- Name: guard_listing_import_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_import_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (select count(*) from public.listing_imports
      where user_id = new.user_id
        and status not in ('consumed', 'expired', 'failed')) >= 20 then
    raise exception 'listing import limit reached (20 in progress)';
  end if;
  return new;
end;
$$;


--
-- Name: guard_listing_import_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_import_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status = old.status then
    return new;
  end if;
  if not (
    (old.status = 'pending'         and new.status in ('fetching', 'extracting', 'failed', 'expired')) or
    (old.status = 'fetching'        and new.status in ('extracting', 'failed', 'expired')) or
    (old.status = 'extracting'      and new.status in ('importing_media', 'ready', 'failed', 'expired')) or
    (old.status = 'importing_media' and new.status in ('ready', 'failed', 'expired')) or
    (old.status = 'ready'           and new.status in ('consumed', 'extracting', 'expired')) or
    (old.status = 'failed'          and new.status in ('fetching', 'extracting', 'expired'))
  ) then
    raise exception 'illegal listing import transition: % -> %', old.status, new.status;
  end if;
  -- consumed must point at the listing it became; nothing else may.
  if new.status = 'consumed' and new.listing_id is null then
    raise exception 'a consumed import must reference its listing';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: guard_listing_member_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_member_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status not in ('draft', 'active') then
      raise exception 'A new listing is a draft or goes live; % is set by DRVN', new.status
        using errcode = '42501';
    end if;
    new.created_at := now();
    new.view_count := 0;
    new.sold_at := null;
    new.reserved_until := null;
    new.removed_at := null;
    new.removed_reason := null;
    new.currency := 'USD';
    return new;
  end if;

  if new.id is distinct from old.id
     or new.seller_id is distinct from old.seller_id
     or new.created_at is distinct from old.created_at
     or new.view_count is distinct from old.view_count
     or new.published_at is distinct from old.published_at
     or new.sold_at is distinct from old.sold_at
     or new.reserved_until is distinct from old.reserved_until
     or new.removed_at is distinct from old.removed_at
     or new.removed_reason is distinct from old.removed_reason
     or new.currency is distinct from old.currency
     or new.updated_at is distinct from old.updated_at then
    raise exception 'That listing field is set by DRVN, not by the seller'
      using errcode = '42501';
  end if;
  -- A reserved, sold or removed listing is what a buyer agreed to, or what
  -- moderation took down: its content is frozen for the seller, as the
  -- editor (update_listing_atomic) already refuses. Status moves out of these
  -- states are guard_listing_status's to judge.
  if old.status in ('reserved', 'sold', 'removed')
     and (to_jsonb(new) - 'status') is distinct from (to_jsonb(old) - 'status') then
    raise exception 'A sold, reserved or removed listing can''t be edited'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_listing_price_above_floor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_price_above_floor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_floor integer;
begin
  if new.seller_id is distinct from old.seller_id then
    update public.listing_private_terms set seller_id = new.seller_id, updated_at = now()
    where listing_id = new.id;
  end if;
  if new.price_cents is distinct from old.price_cents then
    select t.offer_floor_cents into v_floor from public.listing_private_terms t where t.listing_id = new.id;
    if v_floor is not null and v_floor > new.price_cents then
      raise exception 'The asking price can''t go below your offer minimum; lower the minimum first'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_listing_price_bounds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_price_bounds() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
begin
  if new.status not in ('active', 'paused') or public.charge_cents_in_bounds(new.price_cents) then
    return new;
  end if;
  if tg_op = 'INSERT'
     or new.price_cents is distinct from old.price_cents
     or old.status = 'draft'
     or (new.status = 'active' and old.status not in ('active', 'reserved')) then
    raise exception 'A listed part needs a price between $0.50 and $999,999.99'
      using errcode = '22003';
  end if;
  return new;
end;
$_$;


--
-- Name: guard_listing_source_car(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_source_car() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.source_car_id is not null and not exists (
    select 1 from public.cars c
    where c.id = new.source_car_id and c.owner_id = new.seller_id
  ) then
    raise exception 'source_car_id must reference a car owned by the seller'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_listing_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_listing_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.status is distinct from old.status then
    -- `reserved` is an outcome of checkout, never a seller's choice. `sold`
    -- is too, with one exception: a seller may mark their own live or paused
    -- part sold when it sold somewhere else ("Mark sold"). The public "N sold"
    -- trust figure counts paid orders, so this can't inflate it.
    if new.status = 'sold' and old.status in ('active', 'paused') then
      null;
    elsif new.status in ('reserved', 'sold') then
      raise exception 'listing status % is set by checkout, not by the seller', new.status
        using errcode = '42501';
    end if;

    -- `removed` is a moderation outcome. Setting it, or un-setting it, is
    -- admin tooling (service role) only.
    if new.status = 'removed' or old.status = 'removed' then
      raise exception 'listing status ''removed'' is set and cleared by moderation'
        using errcode = '42501';
    end if;

    -- A listing held by an in-flight checkout must not be yanked out from
    -- under the buyer. Only the sweeper or a finalize may release it.
    if old.status = 'reserved' then
      raise exception 'listing is reserved by a checkout in progress'
        using errcode = '42501';
    end if;

    -- A sold part stays sold. Relisting means creating a new listing, so the
    -- order history keeps pointing at what was actually bought.
    if old.status = 'sold' then
      raise exception 'a sold listing cannot be relisted — create a new one'
        using errcode = '42501';
    end if;

    -- A suspended seller cannot put anything (back) on the market.
    if new.status = 'active' and public.is_suspended(new.seller_id) then
      raise exception 'account is suspended'
        using errcode = '42501';
    end if;
  end if;

  -- Price and shipping are part of what a buyer agreed to; freeze them while a
  -- checkout holds the row.
  if old.status = 'reserved'
     and (new.price_cents is distinct from old.price_cents
          or new.shipping_cents is distinct from old.shipping_cents) then
    raise exception 'cannot change price while a checkout is in progress'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_message_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_message_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.body is distinct from old.body
     or new.sender_id is distinct from old.sender_id
     or new.recipient_id is distinct from old.recipient_id
     or new.listing_id is distinct from old.listing_id
     or new.offer_id is distinct from old.offer_id
     or new.order_id is distinct from old.order_id
     or new.conversation_id is distinct from old.conversation_id
     or new.kind is distinct from old.kind
     or new.attachments is distinct from old.attachments then
    raise exception 'only read_at may be updated on a message'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_message_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_message_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_path text;
begin
  if not public.is_trusted_writer() then
    new.kind := 'message';
  end if;

  foreach v_path in array coalesce(new.attachments, '{}'::text[]) loop
    if v_path is null
       or position(new.sender_id::text || '/' || new.recipient_id::text || '/' in v_path) <> 1
       or v_path like '%..%'
       or v_path ~ '/[^/]*/[^/]*/' then
      raise exception 'attachments must be in the sender''s folder for this recipient'
        using errcode = '22023';
    end if;
  end loop;

  return new;
end;
$$;


--
-- Name: guard_mod_purchase_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_mod_purchase_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.source_order_item_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.source_order_item_id is not distinct from old.source_order_item_id then
    return new;
  end if;
  -- Workers and migrations act without a session.
  if auth.uid() is null then
    return new;
  end if;
  if not exists (
    select 1
      from public.order_items i
      join public.orders o on o.id = i.order_id
     where i.id = new.source_order_item_id
       and o.buyer_id = auth.uid()
       and o.status in ('delivered', 'completed')
  ) then
    raise exception 'That purchase isn''t yours to add.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_offer_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_offer_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.amount_cents is distinct from old.amount_cents
     or new.listing_id is distinct from old.listing_id
     or new.buyer_id is distinct from old.buyer_id
     or new.counter_amount_cents is distinct from old.counter_amount_cents then
    raise exception 'offer amount and parties are immutable'
      using errcode = '42501';
  end if;

  if old.status not in ('open', 'countered') and new.status <> old.status then
    raise exception 'offer status is final once it leaves open'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_offer_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_offer_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_listing record;
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  -- A buyer opens an offer. Countering is the seller's move and runs
  -- server-side, so neither the countered state nor its amount may be
  -- self-assigned.
  if new.status is distinct from 'open' then
    raise exception 'a new offer must start as open' using errcode = '42501';
  end if;
  if new.counter_amount_cents is not null or new.countered_at is not null then
    raise exception 'only the seller can counter, and not at offer time'
      using errcode = '42501';
  end if;
  if new.responded_at is not null then
    raise exception 'responded_at is set when the seller responds'
      using errcode = '42501';
  end if;

  select id, seller_id, status, price_cents
  into v_listing
  from public.listings
  where id = new.listing_id;

  if not found or v_listing.status <> 'active' then
    raise exception 'that part is not on sale' using errcode = '42501';
  end if;
  if v_listing.seller_id = new.buyer_id then
    raise exception 'you cannot offer on your own listing' using errcode = '42501';
  end if;
  if new.amount_cents > v_listing.price_cents then
    raise exception 'an offer cannot exceed the asking price' using errcode = '42501';
  end if;
  -- The seller's minimum is private (20261017120000): this invoker-rights
  -- guard can't read it, so offers_guard_private_floor checks it.

  -- One live offer per buyer per listing.
  if exists (
    select 1 from public.offers o
    where o.listing_id = new.listing_id
      and o.buyer_id = new.buyer_id
      and o.status in ('open', 'countered')
  ) then
    raise exception 'you already have a live offer on this part' using errcode = '42501';
  end if;

  -- The window is the platform's to set, not the buyer's.
  new.expires_at := now() + interval '72 hours';

  return new;
end;
$$;


--
-- Name: guard_order_collection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_collection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.is_collection and not old.is_collection then
    if exists (
      select 1
        from public.order_items oi
       where oi.order_id = new.id
         and coalesce(
               (oi.commercial_snapshot -> 'commercial' ->> 'allows_collection')::boolean,
               false
             ) = false
    ) then
      raise exception 'pickup not offered by every item on this order'
        using errcode = '42501';
    end if;
    if not exists (select 1 from public.order_items oi where oi.order_id = new.id) then
      raise exception 'pickup cannot be set before order items exist'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_order_dispute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_dispute() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Entering a case.
  if new.status = 'disputed' and old.status is distinct from 'disputed' then
    if not (new.stripe_dispute_id is not null and new.stripe_dispute_id is distinct from old.stripe_dispute_id)
       and coalesce(current_setting('drvn.dispute_reopen', true), '') <> 'admin'
       and exists (
         select 1 from public.order_dispute_history h
          where h.order_id = new.id and h.event = 'resolved' and h.kind = 'in_app'
       ) then
      raise exception 'This order''s dispute was resolved and is final; only DRVN support can reopen it'
        using errcode = '42501';
    end if;
  end if;

  if old.status = 'disputed' and new.status = 'disputed' then
    -- The case's reason, opener and clocks are fixed while it is open.
    if new.disputed_at is distinct from old.disputed_at
       -- (a deleted account's ON DELETE SET NULL may clear the opener)
       or (new.disputed_by is distinct from old.disputed_by and new.disputed_by is not null)
       or new.dispute_category is distinct from old.dispute_category
       or new.dispute_reason is distinct from old.dispute_reason
       or new.dispute_respond_by is distinct from old.dispute_respond_by
       or new.dispute_escalate_until is distinct from old.dispute_escalate_until then
      raise exception 'An open dispute''s reason and clocks cannot change' using errcode = '42501';
    end if;
    -- Accepting an offer claims it (refund_offered_at -> null, amount kept).
    -- An expired offer cannot be claimed, whether or not cleanup has run.
    if old.refund_offered_at is not null and new.refund_offered_at is null
       and new.refund_offer_cents is not null
       and old.refund_offer_expires_at <= now() then
      raise exception 'This refund offer has expired' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;


--
-- Name: guard_order_item_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_item_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  -- 20261005110000: the one permitted change — a collected accepted offer's
  -- delivery charge taken off its line (see freeze_accepted_offer_checkout).
  if old.shipping_cents <> 0
     and new.shipping_cents = 0
     and new.commercial_snapshot is not distinct from
         jsonb_set(old.commercial_snapshot, '{commercial,shipping_cents}', '0'::jsonb)
     and new.snapshot_version is not distinct from old.snapshot_version
     and new.condition_snapshot is not distinct from old.condition_snapshot
     and new.price_cents is not distinct from old.price_cents
     and new.quantity is not distinct from old.quantity
     and new.title is not distinct from old.title
     and new.order_id is not distinct from old.order_id
     and exists (
       select 1 from public.orders o
       where o.id = old.order_id
         and o.status = 'pending'
         and o.origin_offer_id is not null
         and o.accepted_checkout_shipping is not null
         and o.is_collection
         and o.shipping_cents = 0
     )
  then
    return new;
  end if;

  if new.commercial_snapshot is distinct from old.commercial_snapshot
     or new.snapshot_version is distinct from old.snapshot_version
     or (old.condition_snapshot is not null
         and new.condition_snapshot is distinct from old.condition_snapshot)
     or new.price_cents is distinct from old.price_cents
     or new.shipping_cents is distinct from old.shipping_cents
     or new.quantity is distinct from old.quantity
     or new.title is distinct from old.title
     or new.order_id is distinct from old.order_id
  then
    raise exception 'order_items purchase record is immutable'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_order_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  reason text := current_setting('drvn.order_status_override', true);
  problem text;
begin
  if reason is not null and reason <> '' then
    if btrim(reason) = '' then
      raise exception 'drvn.order_status_override needs a reason (guard_order_status)'
        using errcode = '23514';
    end if;
    if current_user::text not in ('postgres', 'supabase_admin')
       or session_user::text not in ('postgres', 'supabase_admin') then
      raise exception 'drvn.order_status_override is refused for % in a session of % (guard_order_status)', current_user, session_user
        using errcode = '42501';
    end if;
    insert into private.order_status_overrides (
      order_id, old_status, new_status, old_pre_dispute_status, new_pre_dispute_status,
      reason, current_role_name, session_role_name
    ) values (
      new.id, old.status, new.status, old.pre_dispute_status, new.pre_dispute_status,
      reason, current_user::text, session_user::text
    );
    return new;
  end if;

  problem := public.order_status_change_problem(old.status, new.status, old.pre_dispute_status, new.pre_dispute_status);
  if problem is not null then
    raise exception '% (order %, guard_order_status)', problem, new.id
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION guard_order_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_order_status() IS 'Plan 2 A2: refuses a change of orders.status or pre_dispute_status that private.order_status_transitions does not allow, for every role. Not security definer: it must see current_user and session_user for drvn.order_status_override.';


--
-- Name: guard_outbound_label_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_label_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.shipment_id<>old.shipment_id or new.provider<>old.provider or new.rated<>old.rated
     or (old.label is not null and new.label is distinct from old.label)
     or (old.completed_at is not null and new.completed_at is distinct from old.completed_at) then
    raise exception 'Outbound label identity is immutable';
  end if;
  return new;
end $$;


--
-- Name: guard_outbound_label_void_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_label_void_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.shipment_id<>old.shipment_id or new.order_id<>old.order_id
     or new.seller_id<>old.seller_id or new.provider<>old.provider
     or new.provider_shipment_reference<>old.provider_shipment_reference
     or new.amount_cents<>old.amount_cents or new.currency<>old.currency
     or new.created_at<>old.created_at
     or (old.completed_at is not null and new.completed_at is distinct from old.completed_at)
     or (old.rejected_at is not null and new.rejected_at is distinct from old.rejected_at) then
    raise exception 'Outbound label void identity is immutable';
  end if;
  return new;
end $$;


--
-- Name: guard_post_has_subject(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_post_has_subject() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Drafts are exempt: you start writing before you decide what it is about.
  if new.published_at is null then
    return new;
  end if;
  if new.car_id is not null then
    return new;
  end if;
  if exists (select 1 from public.activity_post_listings t where t.post_id = new.id) then
    return new;
  end if;
  raise exception 'A post needs a car, a tagged part, or both.' using errcode = '23514';
end;
$$;


--
-- Name: guard_private_floor_within_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_private_floor_within_price() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_price integer;
begin
  if new.offer_floor_cents is null then
    return new;
  end if;
  select l.price_cents into v_price from public.listings l where l.id = new.listing_id;
  if found and new.offer_floor_cents > v_price then
    raise exception 'The offer minimum must be no more than the asking price'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: guard_profile_age_confirmed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_age_confirmed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.username is not null
     and (tg_op = 'INSERT' or old.username is null)
     and not exists (select 1 from public.age_confirmations a where a.user_id = new.id) then
    raise exception 'Confirm you are 18 or over before choosing a handle'
      using errcode = '42501', hint = 'age_not_confirmed';
  end if;
  return new;
end;
$$;


--
-- Name: guard_profile_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.profile_type is distinct from old.profile_type then
    raise exception 'profile_type cannot be changed by the account holder'
      using errcode = '42501';
  end if;

  if old.username is not null and new.username is distinct from old.username then
    raise exception 'username cannot be changed once set'
      using errcode = '42501';
  end if;

  if new.payouts_enabled is distinct from old.payouts_enabled then
    raise exception 'payouts_enabled is set by Stripe onboarding, not by the account holder'
      using errcode = '42501';
  end if;

  -- 20261108100000: whether setup has started, and the day-14 restriction,
  -- come from Stripe and the money worker, never the account holder.
  if new.payout_details_submitted is distinct from old.payout_details_submitted
     or new.payout_restricted_at is distinct from old.payout_restricted_at then
    raise exception 'payout setup state is set by Stripe onboarding, not by the account holder'
      using errcode = '42501';
  end if;

  if new.stripe_account_id is distinct from old.stripe_account_id
     or new.stripe_customer_id is distinct from old.stripe_customer_id then
    raise exception 'Stripe account references are managed server-side'
      using errcode = '42501';
  end if;

  if new.suspended_at is distinct from old.suspended_at
     or new.suspended_reason is distinct from old.suspended_reason then
    raise exception 'suspension is managed by moderation'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_profile_main_car(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_main_car() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.main_car_id is not null
     and (old.main_car_id is distinct from new.main_car_id) then
    if not exists (
      select 1 from public.cars c
      where c.id = new.main_car_id and c.owner_id = new.id
    ) then
      raise exception 'A main car must be one of your own cars.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_refund_replacement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_refund_replacement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare proof public.refund_recredit_proofs;
begin
 if tg_op='INSERT' then
  perform 1 from public.orders where id=new.order_id for update;
  if new.replaces_adjustment_id is null and exists(select 1 from public.payment_recoveries where order_id=new.order_id and kind='refund_late_failure' and status='open') then
   raise exception 'Use the linked replacement action for this late-refund recovery';
  end if;
 else
  if new.replaces_adjustment_id is distinct from old.replaces_adjustment_id or new.replacement_transfer_reference is distinct from old.replacement_transfer_reference then raise exception 'Replacement identity is immutable'; end if;
 end if;
 if new.replaces_adjustment_id is not null then
  select * into strict proof from public.refund_recredit_proofs where adjustment_id=new.replaces_adjustment_id;
  if new.reversal_operation_key is not null and new.reversal_transfer_reference is distinct from new.replacement_transfer_reference then raise exception 'Replacement must reverse its dedicated seller transfer'; end if;
  if new.effects_completed_at is not null and new.reversal_due_cents is distinct from proof.amount_cents then raise exception 'Replacement seller allocation changed'; end if;
 end if;
 return new;
end $$;


--
-- Name: guard_return_item_unique_live(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_return_item_unique_live() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if exists (
    select 1
      from public.return_items ri
      join public.returns r on r.id = ri.return_id
     where ri.order_item_id = new.order_item_id
       and ri.return_id <> new.return_id
       and r.status not in ('rejected', 'expired', 'cancelled', 'completed')
  ) then
    raise exception 'order item already has an active return'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_return_label_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_return_label_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if new.return_id<>old.return_id or new.provider<>old.provider or new.rated<>old.rated or new.shipment_id<>old.shipment_id
 or (old.label is not null and new.label is distinct from old.label)
 or (old.completed_at is not null and new.completed_at is distinct from old.completed_at)
 then raise exception 'Return label identity is immutable'; end if;
 return new;
end $$;


--
-- Name: guard_return_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_return_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status then
    if not (
      (old.status = 'requested' and new.status in ('approved', 'rejected', 'cancelled', 'escalated'))
      or (old.status = 'approved' and new.status in ('awaiting_shipment', 'expired', 'cancelled', 'escalated'))
      or (old.status = 'awaiting_shipment' and new.status in ('in_transit', 'expired', 'cancelled', 'escalated'))
      or (old.status = 'in_transit' and new.status in ('delivered', 'escalated'))
      or (old.status = 'delivered' and new.status in ('received', 'escalated'))
      or (old.status = 'received' and new.status in ('completed', 'escalated'))
      or (old.status = 'escalated' and new.status in ('received', 'completed', 'rejected', 'cancelled'))
    ) then
      raise exception 'illegal return transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_review_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_review_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.reviewee_id is distinct from old.reviewee_id
     or new.reviewer_id is distinct from old.reviewer_id
     or new.order_id is distinct from old.order_id then
    raise exception 'a review stays attached to its order and its subject'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_saved_search_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_saved_search_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (select count(*) from public.saved_searches where user_id = new.user_id) >= 50 then
    raise exception 'saved search limit reached (50)';
  end if;
  return new;
end;
$$;


--
-- Name: guard_seller_adjustment_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_seller_adjustment_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.id is distinct from old.id
     or new.seller_id is distinct from old.seller_id
     or new.order_id is distinct from old.order_id
     or new.shipment_id is distinct from old.shipment_id
     or new.return_id is distinct from old.return_id
     or new.kind is distinct from old.kind
     or new.amount_cents is distinct from old.amount_cents
     or new.currency is distinct from old.currency
     or new.external_reference is distinct from old.external_reference
     or new.created_at is distinct from old.created_at
     or (old.voided_at is not null and new.voided_at is distinct from old.voided_at)
  then
    raise exception 'seller_adjustments rows are append-only (void via voided_at once, reverse via label_refund)'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_seller_carry_entry_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_seller_carry_entry_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Account deletion may clear the references (on delete set null); the
  -- money columns and the key never change, and rows are never removed.
  if tg_op = 'DELETE' then
    raise exception 'seller_carry_entries rows are append-only' using errcode = '42501';
  end if;
  if new.id is distinct from old.id
     or new.kind is distinct from old.kind
     or new.amount_cents is distinct from old.amount_cents
     or new.currency is distinct from old.currency
     or new.entry_key is distinct from old.entry_key
     or new.created_at is distinct from old.created_at
     or (new.seller_id is distinct from old.seller_id and new.seller_id is not null)
     or (new.order_id is distinct from old.order_id and new.order_id is not null)
     or (new.adjustment_id is distinct from old.adjustment_id and new.adjustment_id is not null) then
    raise exception 'seller_carry_entries rows are append-only' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_shipment_item_unique_live(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_shipment_item_unique_live() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_direction text;
begin
  select s.direction into v_direction from public.shipments s where s.id = new.shipment_id;

  if exists (
    select 1
      from public.shipment_items si
      join public.shipments s on s.id = si.shipment_id
     where si.order_item_id = new.order_item_id
       and si.shipment_id <> new.shipment_id
       and s.direction = v_direction
       and s.status not in ('cancelled', 'failed')
  ) then
    raise exception 'order item already has a live % shipment', v_direction
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_shipment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_shipment_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status then
    if not (
      (old.status = 'pending' and new.status in ('label_purchased', 'in_transit', 'cancelled', 'failed'))
      or (old.status = 'label_purchased' and new.status in ('in_transit', 'out_for_delivery', 'delivered', 'returned_to_sender', 'cancelled', 'failed'))
      or (old.status = 'in_transit' and new.status in ('out_for_delivery', 'delivered', 'returned_to_sender', 'failed'))
      or (old.status = 'out_for_delivery' and new.status in ('delivered', 'in_transit', 'returned_to_sender', 'failed'))
      or (old.status = 'returned_to_sender' and new.status in ('in_transit'))
    ) then
      raise exception 'illegal shipment transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


