-- Name: guard_snapshot_image_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_snapshot_image_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  raise exception 'order_item_snapshot_images rows are immutable'
    using errcode = '42501';
end;
$$;


--
-- Name: guest_hold_admit(text, text, uuid[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guest_hold_admit(p_device text, p_network text, p_listing_ids uuid[], p_buyer uuid, p_request text) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ids uuid[] := '{}';
  v_listing uuid;
  v_existing uuid;
  v_new integer;
  v_device integer;
  v_network integer;
begin
  if p_device is null or p_network is null or p_listing_ids is null or cardinality(p_listing_ids) = 0 then
    raise exception 'A guest hold needs a device, a network and listings' using errcode = '22023';
  end if;
  if p_request is null or char_length(p_request) not between 16 and 200 then
    raise exception 'A guest hold needs its checkout request' using errcode = '22023';
  end if;
  -- One order of locks for everyone: device, network, then listings sorted.
  perform pg_advisory_xact_lock(hashtextextended('guest-device:' || p_device, 0));
  perform pg_advisory_xact_lock(hashtextextended('guest-network:' || p_network, 0));
  for v_listing in select distinct x from unnest(p_listing_ids) x order by x loop
    perform pg_advisory_xact_lock(hashtextextended('guest-listing:' || v_listing::text, 0));
  end loop;

  -- A replay of the same request reuses its own admissions, and only those.
  select count(*) into v_new
    from (select distinct x from unnest(p_listing_ids) x) l
   where not exists (
     select 1 from public.guest_holds h
      where h.listing_id = l.x and h.request_key = p_request and private.guest_hold_live(h)
   );

  -- 1 live guest hold per listing: another guest's live hold refuses it.
  if exists (
    select 1 from public.guest_holds h
     where h.listing_id = any (p_listing_ids) and h.device_key <> p_device and private.guest_hold_live(h)
  ) then
    raise exception 'Another guest is checking out this part right now.' using errcode = 'GH409';
  end if;

  select count(*) into v_device from public.guest_holds h where h.device_key = p_device and private.guest_hold_live(h);
  select count(*) into v_network from public.guest_holds h where h.network_key = p_network and private.guest_hold_live(h);
  if v_device + v_new > 2 or v_network + v_new > 2 then
    raise exception 'Guest checkout holds up to 2 parts at a time. Sign in to buy more, or finish paying first.'
      using errcode = 'GH429';
  end if;

  for v_listing in select distinct x from unnest(p_listing_ids) x order by x loop
    select h.id into v_existing from public.guest_holds h
     where h.listing_id = v_listing and h.request_key = p_request and private.guest_hold_live(h)
     limit 1;
    if v_existing is null then
      insert into public.guest_holds (device_key, network_key, listing_id, buyer_id, request_key)
      values (p_device, p_network, v_listing, p_buyer, p_request)
      returning id into v_existing;
    end if;
    v_ids := v_ids || v_existing;
    v_existing := null;
  end loop;
  return v_ids;
end;
$$;


--
-- Name: guest_hold_release(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guest_hold_release(p_request text) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with released as (
    update public.guest_holds set released_at = now()
     where request_key = p_request and order_id is null and released_at is null
    returning 1
  )
  select count(*)::integer from released;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;


--
-- Name: has_embedded_media_reference(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_embedded_media_reference(p_url text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 select exists(select 1 from public.car_hotspots where image_url=p_url)
 or exists(select 1 from public.dispute_evidence where url=p_url)
 or exists(select 1 from public.order_items where position(trim(both '"' from to_jsonb(p_url)::text) in commercial_snapshot::text)>0)
 or exists(select 1 from public.activity_posts where position(trim(both '"' from to_jsonb(p_url)::text) in body::text)>0);
$$;


--
-- Name: hold_refund_reversal(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_refund_reversal(p_operation uuid, p_worker text, p_operation_key text, p_detail text, p_next_attempt_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op public.refund_operations;
  v_recovery uuid;
begin
  if nullif(p_detail, '') is null then raise exception 'Reversal recovery detail is required'; end if;
  select * into v_op
  from public.refund_operations
  where id = p_operation
  for update;
  if not found
     or v_op.status <> 'reversal_pending'
     or v_op.reversal_locked_by <> p_worker
     or v_op.reversal_operation_key <> p_operation_key
     or not v_op.reversal_call_may_have_occurred then
    return null;
  end if;

  insert into public.payment_recoveries (
    order_id, kind, recovery_key, amount_cents, detail
  ) values (
    v_op.order_id,
    'reversal_failed',
    'reversal-failed:' || p_operation::text,
    v_op.reversal_amount_cents,
    left(p_detail, 2000)
  )
  on conflict (recovery_key) do update
  set last_seen_at = now(),
      amount_cents = excluded.amount_cents,
      detail = excluded.detail,
      status = 'open',
      resolved_by = null,
      resolved_at = null,
      resolution_note = null
  returning id into v_recovery;

  insert into public.admin_alert_outbox (
    kind, title, detail, order_id, amount_cents, payload, dedup_key, status
  ) values (
    'recovery_case_opened',
    'Transfer reversal requires reconciliation',
    left(p_detail, 2000),
    v_op.order_id,
    v_op.reversal_amount_cents,
    jsonb_build_object('operation_id', p_operation, 'recovery_id', v_recovery),
    'reversal-failed:' || p_operation::text,
    'pending'
  ) on conflict (dedup_key) do nothing;

  update public.refund_operations
  set recovery_id = v_recovery,
      attempts = attempts + 1,
      next_attempt_at = p_next_attempt_at,
      last_error = left(p_detail, 500),
      reversal_locked_by = null,
      reversal_lease_expires_at = null,
      updated_at = now()
  where id = p_operation;
  return v_recovery;
end;
$$;


--
-- Name: hold_stripe_dispute(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_stripe_dispute(p_dispute text, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare entry public.stripe_dispute_journal%rowtype; recovery uuid;
begin
 select * into strict entry from public.stripe_dispute_journal where dispute_id=p_dispute for update;
 -- 20261107130000: lock every order of the basket, already-disputed ones
 -- included, before the journal changes, so a concurrent
 -- prepare_transfer_dispatch (FOR UPDATE on the order, then the journal)
 -- waits for this commit and then sees the unresolved entry.
 perform 1 from public.orders where id=any(entry.order_ids) order by id for update;
 update public.stripe_dispute_journal set state='recovery',lease_id=null,lease_expires_at=null,updated_at=now() where dispute_id=p_dispute;
 -- Freeze the basket while attribution is reviewed; never infer that a
 -- partial chargeback refunded every order on its PaymentIntent.
 update public.orders set pre_dispute_status=status,status='disputed',disputed_at=now(),
  dispute_resolved_at=null,dispute_outcome=null,dispute_category='other',
  dispute_reason='Card dispute requires reconciliation — '||p_dispute,stripe_dispute_id=p_dispute
 where id=any(entry.order_ids) and status in ('paid','shipped','delivered','completed');
 insert into public.payment_recoveries(order_id,kind,recovery_key,amount_cents,detail)
 values(case when cardinality(entry.order_ids)=1 then entry.order_ids[1] else null end,
 'partial_refund_unattributed','stripe:dispute:'||p_dispute,entry.amount_cents,left(p_detail,2000))
 on conflict(recovery_key) do update set last_seen_at=now()
 returning id into recovery;
 insert into public.admin_alert_outbox(kind,title,detail,order_id,amount_cents,payload,dedup_key)
 values('recovery_case_opened','Card dispute requires reconciliation',left(p_detail,2000),
 case when cardinality(entry.order_ids)=1 then entry.order_ids[1] else null end,entry.amount_cents,
 jsonb_build_object('recovery_id',recovery,'dispute_id',p_dispute),'stripe-dispute:'||p_dispute)
 on conflict(dedup_key) do nothing;
 return 'recovery_recorded';
end $$;


--
-- Name: hold_stripe_dispute(text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_stripe_dispute(p_dispute text, p_event text, p_created bigint, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_result text;
  v_case public.payment_recoveries%rowtype;
begin
  v_result := public.hold_stripe_dispute(p_dispute, p_detail);
  perform private.note_held_dispute_event(p_dispute, p_event, p_created);
  -- Held again after its case was closed (work review #148): the two-argument
  -- function only touches last_seen_at on a case that exists, so the
  -- chargeback would be held with no open case and nothing in the console.
  update public.payment_recoveries r
     set status = 'open', resolved_at = null, resolved_by = null, resolution_note = null, last_seen_at = now(),
         detail = left(p_detail || ' (This case was closed as ' || r.status || ' and opened again when a later Stripe event held the chargeback.)', 2000)
   where r.recovery_key = 'stripe:dispute:' || p_dispute and r.status <> 'open'
  returning * into v_case;
  if found then
    insert into public.admin_alert_outbox(kind, title, detail, order_id, amount_cents, payload, dedup_key)
    values ('recovery_case_opened', 'Card dispute held for review again', left(p_detail, 2000), v_case.order_id, v_case.amount_cents,
            jsonb_build_object('recovery_id', v_case.id, 'dispute_id', p_dispute, 'event_id', p_event),
            'stripe-dispute:' || p_dispute || ':held-again:' || coalesce(p_event, 'no-event'))
    on conflict (dedup_key) do nothing;
  end if;
  return v_result;
end;
$$;


--
-- Name: identifier_matches_listing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.identifier_matches_listing(p_id uuid, p_compact text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 with variants as(select p_compact compact union select case when l.from_compact=p_compact then l.to_compact else l.from_compact end from public.part_number_links l where l.from_compact=p_compact or l.to_compact=p_compact)
 select length(p_compact)>=4 and p_compact ~ '[0-9]' and exists(
 select 1 from public.listings l where l.id=p_id and l.status='active' and public.profile_is_visible(l.seller_id) and (
 exists(select 1 from variants v where l.part_number_compact like '%'||v.compact||'%') or exists(select 1 from public.listing_part_numbers n join variants v on n.number_compact=v.compact where n.listing_id=l.id)));
$$;


