--
-- Name: invoke_remediation_worker(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoke_remediation_worker(p_family text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare base text; secret text;
begin
 if p_family not in ('search','account-deletions','media-gc','saved-searches','listing-imports','agent','saved-search-digests','ledger-reconciliation') then raise exception 'Unknown worker family'; end if;
 select value into base from public.job_config where key='transfer_worker_url';
 select value into secret from public.job_config where key='transfer_worker_secret';
 if base is null or secret is null then return; end if;
 if base !~ '/api/jobs/transfers$' then raise exception 'Invalid transfer worker URL'; end if;
 perform net.http_post(url:=regexp_replace(base,'/transfers$','/'||p_family),headers:=jsonb_build_object('Authorization','Bearer '||secret,'Content-Type','application/json'),body:='{}'::jsonb,timeout_milliseconds:=60000);
end $_$;


--
-- Name: invoke_transfer_worker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoke_transfer_worker() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_url    text;
  v_secret text;
begin
  select value into v_url from public.job_config where key = 'transfer_worker_url';
  select value into v_secret from public.job_config where key = 'transfer_worker_secret';
  if v_url is null or v_secret is null then
    return; -- unconfigured (dev): the admin console's manual run is the path
  end if;
  begin
    perform net.http_post(
      url := v_url,
      headers := jsonb_build_object(
        'Authorization', 'Bearer ' || v_secret,
        'Content-Type', 'application/json'
      ),
      body := '{}'::jsonb
    );
  exception when others then
    raise notice 'transfer worker invocation failed: %', sqlerrm;
  end;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'aal', 'aal1') = 'aal2'
    and public.admin_role() is not null
    and exists (
      select 1 from public.admin_users a
      where a.user_id = auth.uid()
        and a.mfa_factor_id is not null
        and a.mfa_factor_id = private.admin_session_factor()
    );
$$;


