--
-- Name: list_conversations(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_conversations(p_filter text DEFAULT 'all'::text, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, counterparty_id uuid, last_message_id uuid, last_message_at timestamp with time zone, last_message_preview text, unread_count integer, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with mine as (
    select
      c.id, c.last_message_id, c.last_message_at, c.last_message_preview,
      case when c.participant_a = auth.uid() then c.participant_b else c.participant_a end as other
    from public.conversations c
    where auth.uid() in (c.participant_a, c.participant_b)
  ),
  scored as (
    select m.*, coalesce(u.unread_count, 0) as unread
    from mine m
    left join public.conversation_unreads u
      on u.conversation_id = m.id and u.user_id = auth.uid()
  ),
  filtered as (
    select s.*
    from scored s
    where (
      coalesce(p_filter, 'all') = 'all'
      or (p_filter = 'unread' and s.unread > 0)
      or (p_filter = 'buying' and (
        exists (select 1 from public.orders o where o.buyer_id = auth.uid() and o.seller_id = s.other)
        or exists (
          select 1 from public.offers f join public.listings l on l.id = f.listing_id
          where f.buyer_id = auth.uid() and l.seller_id = s.other
        )
        or exists (
          select 1 from public.messages mm join public.listings l on l.id = mm.listing_id
          where mm.conversation_id = s.id and mm.order_id is null and mm.offer_id is null
            and l.seller_id = s.other
        )
      ))
      or (p_filter = 'selling' and (
        exists (select 1 from public.orders o where o.seller_id = auth.uid() and o.buyer_id = s.other)
        or exists (
          select 1 from public.offers f join public.listings l on l.id = f.listing_id
          where l.seller_id = auth.uid() and f.buyer_id = s.other
        )
        or exists (
          select 1 from public.messages mm join public.listings l on l.id = mm.listing_id
          where mm.conversation_id = s.id and mm.order_id is null and mm.offer_id is null
            and l.seller_id = auth.uid()
        )
      ))
    )
    and (
      nullif(btrim(coalesce(p_query, '')), '') is null
      or s.last_message_preview ilike '%' || btrim(p_query) || '%'
      or exists (
        select 1 from public.profiles p
        where p.id = s.other
          and (p.display_name ilike '%' || btrim(p_query) || '%' or p.username ilike '%' || btrim(p_query) || '%')
      )
      or exists (
        select 1 from public.messages mm
        where mm.conversation_id = s.id and mm.body ilike '%' || btrim(p_query) || '%'
      )
      or exists (
        select 1 from public.messages mm
        join public.listings l on l.id = mm.listing_id
        where mm.conversation_id = s.id and l.title ilike '%' || btrim(p_query) || '%'
      )
    )
  )
  select f.id, f.other, f.last_message_id, f.last_message_at, f.last_message_preview,
         f.unread::int, count(*) over ()
  from filtered f
  order by f.last_message_at desc nulls last, f.id
  limit least(greatest(coalesce(p_limit, 20), 1), 100)
  offset greatest(coalesce(p_offset, 0), 0);
$$;


--
-- Name: listing_commercial_snapshot(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_commercial_snapshot(p_listing_id uuid, p_price_cents integer, p_shipping_cents integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_listing record;
  v_fitment jsonb;
  v_alt_numbers jsonb;
  v_car jsonb;
  v_seller jsonb;
  v_shop record;
  v_return_policy jsonb;
begin
  select l.id, l.seller_id, l.source_car_id, l.title, l.description,
         l.category, l.subcategory, l.condition, l.grade,
         l.condition_checklist, l.compatibility_notes, l.part_number,
         l.price_cents, l.currency, l.shipping_cents, l.allows_collection,
         l.shipping_mode, l.brand
    into v_listing
    from public.listings l
   where l.id = p_listing_id;

  if not found then
    return null;
  end if;

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'make', f.make, 'model', f.model,
             'year_start', f.year_start, 'year_end', f.year_end
           ) order by f.make, f.model, f.year_start
         ), '[]'::jsonb)
    into v_fitment
    from public.listing_fitments f
   where f.listing_id = p_listing_id;

  select coalesce(jsonb_agg(pn.number order by pn.created_at), '[]'::jsonb)
    into v_alt_numbers
    from public.listing_part_numbers pn
   where pn.listing_id = p_listing_id;

  select jsonb_strip_nulls(jsonb_build_object(
           'id', c.id, 'name', c.name,
           'year', c.year, 'make', c.make, 'model', c.model
         ))
    into v_car
    from public.cars c
   where c.id = v_listing.source_car_id;

  select jsonb_strip_nulls(jsonb_build_object(
           'id', p.id,
           'username', p.username,
           'display_name', p.display_name,
           'profile_type', p.profile_type
         ))
    into v_seller
    from public.profiles p
   where p.id = v_listing.seller_id;

  -- Shop context (0056): the seller's verification state and — when they
  -- accept preference returns — the policy the buyer purchased under.
  select sp.verification_status, sp.returns_accepted, sp.return_window_days
    into v_shop
    from public.shop_profiles sp
   where sp.profile_id = v_listing.seller_id;

  if found then
    v_seller := v_seller || jsonb_build_object(
      'verified_shop', v_shop.verification_status = 'verified'
    );
    if v_shop.returns_accepted then
      v_return_policy := jsonb_build_object(
        'returns_accepted', true,
        'window_days', v_shop.return_window_days
      );
    end if;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'version', 1,
    'captured_at', now(),
    'listing', jsonb_build_object(
      'id', v_listing.id,
      'title', v_listing.title,
      'description', v_listing.description,
      'category', v_listing.category,
      'subcategory', v_listing.subcategory
    ),
    'part', jsonb_build_object(
      'part_number', v_listing.part_number,
      'brand', v_listing.brand,
      'alt_part_numbers', v_alt_numbers
    ),
    'condition', jsonb_build_object(
      'condition', v_listing.condition,
      'grade', v_listing.grade,
      'checklist', v_listing.condition_checklist,
      'compatibility_notes', v_listing.compatibility_notes
    ),
    'fitment', v_fitment,
    'source_car', v_car,
    'commercial', jsonb_build_object(
      'price_cents', p_price_cents,
      'listing_price_cents', v_listing.price_cents,
      'currency', v_listing.currency,
      'shipping_cents', p_shipping_cents,
      'shipping_mode', case v_listing.shipping_mode
                         when 'drvn' then 'drvn_shipping'
                         when 'pickup_only' then 'pickup_only'
                         else 'seller_arranged'
                       end,
      'allows_collection', v_listing.allows_collection,
      'return_policy', v_return_policy
    ),
    'seller', v_seller
  ));
end;
$$;


--
-- Name: listing_edit_status(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_edit_status(p_request uuid, p_listing uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  select r.result into v_result
  from private.listing_edit_requests r
  join public.listings l on l.id = r.listing_id and l.seller_id = v_actor
  where r.seller_id = v_actor and r.request_id = p_request and r.listing_id = p_listing;
  if not found then return jsonb_build_object('committed', false); end if;
  return jsonb_build_object('committed', true, 'result', v_result);
end;
$$;


--
-- Name: listing_engagement_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_engagement_counts(p_listings uuid[]) RETURNS TABLE(listing_id uuid, likes integer, questions integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if cardinality(coalesce(p_listings, '{}')) > 200 then
    raise exception 'At most 200 listings per call' using errcode = '22023';
  end if;
  return query
  select ids.id,
         (select count(*)::integer from public.likes lk
           where lk.target_type = 'listing' and lk.target_id = ids.id),
         (select count(*)::integer from public.listing_questions q
           where q.listing_id = ids.id)
  from (select distinct unnest(coalesce(p_listings, '{}')) as id) ids;
end;
$$;


--
-- Name: FUNCTION listing_engagement_counts(p_listings uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listing_engagement_counts(p_listings uuid[]) IS 'Likes and questions per listing, counted in the database (N30). Caller''s rights. At most 200 ids.';


--
-- Name: listing_enquiry_reply_allowed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_enquiry_reply_allowed(p_listing uuid, p_buyer uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
      from public.listings l
      join public.messages m on m.listing_id = l.id
     where l.id = p_listing
       and l.seller_id = (select auth.uid())
       and m.sender_id = p_buyer
       and m.recipient_id = l.seller_id
       and m.order_id is null and m.offer_id is null
  );
$$;


--
-- Name: listing_public_offer_floor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_public_offer_floor(p_listing uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.offer_floor_cents
  from public.listings l
  join public.listing_private_terms t on t.listing_id = l.id
  where l.id = p_listing
    and l.show_offer_floor
    and l.status in ('active', 'reserved', 'sold')
    and (l.seller_id = (select auth.uid()) or not (l.seller_id in (select public.suspended_profile_ids())));
$$;


--
-- Name: FUNCTION listing_public_offer_floor(p_listing uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listing_public_offer_floor(p_listing uuid) IS 'A listing''s offer minimum, only when its seller chose to show it (O-3); null otherwise.';


--
-- Name: listing_question_parent_matches(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_question_parent_matches(p_parent_id uuid, p_listing_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.listing_questions q
    join public.listings l on l.id = q.listing_id
    where q.id = p_parent_id
      and q.listing_id = p_listing_id
      and (l.status in ('active', 'sold') or l.seller_id = auth.uid())
  );
$$;


--
-- Name: listing_search_doc(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_search_doc(p_title text, p_description text, p_compatibility_notes text, p_category text, p_brand text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ select concat_ws(' ', p_title, p_description, p_compatibility_notes, p_category, p_brand) $$;


--
-- Name: listing_vehicle_fit_from_car(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_vehicle_fit_from_car() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.refresh_listing_vehicle_fit(array(
    select l.id from public.listings l where l.source_car_id = new.id and l.status = 'active'));
  return null;
end;
$$;


--
-- Name: listing_vehicle_fit_from_fitment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_vehicle_fit_from_fitment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.refresh_listing_vehicle_fit(array(select distinct listing_id from changed_new));
  elsif tg_op = 'DELETE' then
    perform public.refresh_listing_vehicle_fit(array(select distinct listing_id from changed_old));
  else
    perform public.refresh_listing_vehicle_fit(array(
      select listing_id from changed_old union select listing_id from changed_new));
  end if;
  return null;
end;
$$;


--
-- Name: listing_vehicle_fit_from_listing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_vehicle_fit_from_listing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- A new price, date or seller on a part still for sale off the same car:
  -- the rows stay, only those columns change (cheaper than recomputing).
  if tg_op = 'UPDATE' and old.status = new.status and old.source_car_id is not distinct from new.source_car_id then
    update public.listing_vehicle_fit
       set price_cents = new.price_cents, published_at = new.published_at, seller_id = new.seller_id
     where listing_id = new.id;
    return null;
  end if;
  perform public.refresh_listing_vehicle_fit(array[new.id]);
  return null;
end;
$$;


--
-- Name: listing_watch_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_watch_counts(p_listings uuid[]) RETURNS TABLE(listing_id uuid, watchers integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if cardinality(coalesce(p_listings, '{}')) > 200 then
    raise exception 'At most 200 listings per call' using errcode = '22023';
  end if;
  return query
  select l.id,
         (select count(*)::integer from public.saves s
           where s.target_type = 'listing' and s.target_id = l.id)
  from public.listings l
  where l.id = any(coalesce(p_listings, '{}'))
    and (
      l.seller_id = auth.uid()
      or (
        public.profile_is_visible(l.seller_id)
        and (
          (l.status in ('active', 'reserved', 'sold') and not public.is_suspended(l.seller_id))
          or public.is_admin()
        )
      )
    );
end;
$$;


--
-- Name: local_feed_rows(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_feed_rows(p_country text, p_region text DEFAULT NULL::text) RETURNS TABLE(kind text, id uuid, happened_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'car'::text, c.id, c.created_at
    from public.cars c
    join public.profiles p on p.id = c.owner_id
   where c.is_public
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  union all
  select 'update'::text, a.id, a.published_at
    from public.activity_posts a
    left join public.cars c on c.id = a.car_id
    join public.profiles p on p.id = a.author_id
   where a.published_at is not null
     and (a.car_id is null or c.is_public)
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  union all
  select 'part'::text, l.id, l.created_at
    from public.listings l
    join public.profiles p on p.id = l.seller_id
   where l.status = 'active'
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  order by 3 desc, 2 desc;
$$;


--
-- Name: mark_due_transfer_intents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_due_transfer_intents() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with marked as (
    update public.transfer_intents ti
    set status = 'ready', updated_at = now()
    from public.orders o
    where ti.order_id = o.id
      and ti.status = 'holding'
      and ti.available_at is not null
      and ti.available_at <= now()
      and o.status in ('delivered', 'completed')
      and not private.order_has_unresolved_chargeback(o.id)
    returning ti.order_id
  )
  select count(*)::int from marked;
$$;


--
-- Name: mark_media_deletion_uncertain(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_media_deletion_uncertain(p_bucket text, p_path text, p_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update private.media_deletion_claims
     set maybe_deleted = true
   where bucket = p_bucket and path = p_path and token = p_token and state = 'active';
  return found;
end;
$$;


--
-- Name: mark_order_dispatched(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_dispatched(p_order uuid, p_actor uuid, p_carrier text, p_tracking text, p_tracker_provider text DEFAULT NULL::text, p_tracker_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  shipment public.shipments;
  normalized_carrier text:=nullif(left(trim(coalesce(p_carrier,'')),200),'');
  normalized_tracking text:=nullif(left(trim(coalesce(p_tracking,'')),200),'');
  tracker_provider text:=nullif(left(trim(coalesce(p_tracker_provider,'')),50),'');
  tracker_ref text:=nullif(left(trim(coalesce(p_tracker_ref,'')),200),'');
  stamped_at timestamptz:=now();
  live_count integer;
  effective text;
begin
  if p_order is null or p_actor is null then raise exception 'Order and actor are required'; end if;
  select * into strict o from public.orders where id=p_order for update;
  if o.seller_id is distinct from p_actor then raise exception 'Seller authorization required' using errcode='42501'; end if;
  if o.is_collection then raise exception 'Collection orders use the pickup handoff'; end if;
  -- 20261108110000: an order the payout deadline claimed is being refunded,
  -- whatever its dispute status (a not-received case keeps it 'disputed'
  -- and dispatch moves only pre_dispute_status, which the status trigger
  -- never saw). Refused before any shipment or tracker job is written.
  if private.payout_deadline_open_claim(o.id) then
    raise exception 'This order is being cancelled and refunded: payouts weren''t set up within 14 days of the sale'
      using errcode = 'LS002';
  end if;
  if normalized_carrier is null or normalized_tracking is null then raise exception 'Carrier and tracking are required'; end if;
  if (tracker_ref is null) <> (tracker_provider is null) then raise exception 'A tracker needs both its provider and its id'; end if;

  effective:=case when o.status='disputed' then coalesce(o.pre_dispute_status,'') else o.status end;

  if effective in ('shipped','delivered','completed') then
    if o.shipped_at is null or o.carrier is distinct from normalized_carrier or o.tracking_number is distinct from normalized_tracking then
      raise exception 'Dispatch replay does not match the recorded shipment';
    end if;
    select count(*) into live_count from public.shipments
    where order_id=o.id and direction='outbound' and status not in ('cancelled','failed');
    if live_count>1 then raise exception 'Order has multiple live outbound shipments'; end if;
    select * into shipment from public.shipments
    where order_id=o.id and direction='outbound' and status not in ('cancelled','failed')
    order by created_at,id limit 1 for update;
    if found then
      if shipment.tracking_code is distinct from normalized_tracking
         or shipment.carrier is distinct from normalized_carrier then
        raise exception 'Dispatch replay does not match the live shipment';
      end if;
      if shipment.status in ('pending','label_purchased') then
        update public.shipments set status='in_transit',shipped_at=coalesce(shipped_at,o.shipped_at)
        where id=shipment.id returning * into shipment;
      end if;
    else
      insert into public.shipments(
        order_id,direction,fulfillment_type,carrier,status,tracking_code,shipped_at
      ) values(
        o.id,'outbound','seller_arranged',normalized_carrier,'in_transit',normalized_tracking,o.shipped_at
      ) returning * into shipment;
    end if;
    insert into public.shipment_items(shipment_id,order_item_id)
    select shipment.id,id from public.order_items where order_id=o.id
    on conflict do nothing;
    if not exists(select 1 from public.shipment_items where shipment_id=shipment.id) then
      raise exception 'Dispatch shipment has no order items';
    end if;
    return jsonb_build_object('ok',true,'applied',false,'replayed',true,'status',o.status,'shipment_id',shipment.id);
  end if;
  if effective<>'paid' then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,'reason','Only a paid order can be dispatched.');
  end if;
  if o.status='disputed' and private.order_has_unresolved_chargeback(o.id) then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,'reason','A bank chargeback is open on this order.');
  end if;

  select count(*) into live_count from public.shipments
  where order_id=o.id and direction='outbound' and status not in ('cancelled','failed');
  if live_count>1 then raise exception 'Order has multiple live outbound shipments'; end if;
  select * into shipment from public.shipments
  where order_id=o.id and direction='outbound' and status not in ('cancelled','failed')
  order by created_at,id limit 1 for update;
  if found then
    if shipment.tracking_code is distinct from normalized_tracking or shipment.carrier is distinct from normalized_carrier then
      if shipment.fulfillment_type='drvn_shipping' and shipment.status='pending' then
        update public.shipments set status='cancelled' where id=shipment.id;
        shipment:=null;
      else
        raise exception 'A live outbound shipment already has different tracking';
      end if;
    elsif shipment.status in ('pending','label_purchased') then
      update public.shipments set status='in_transit',shipped_at=coalesce(shipped_at,stamped_at)
      where id=shipment.id returning * into shipment;
    end if;
    if shipment.id is not null then
      if tracker_ref is not null and shipment.provider_tracker_id is null then
        update public.shipments set provider=tracker_provider,provider_tracker_id=tracker_ref
        where id=shipment.id returning * into shipment;
      end if;
      insert into public.shipment_items(shipment_id,order_item_id)
      select shipment.id,id from public.order_items where order_id=o.id
      on conflict do nothing;
      if not exists(select 1 from public.shipment_items where shipment_id=shipment.id) then
        raise exception 'Dispatch shipment has no order items';
      end if;
    end if;
  end if;

  if shipment.id is null then
    insert into public.shipments(
      order_id,direction,fulfillment_type,carrier,status,tracking_code,shipped_at,provider,provider_tracker_id
    ) values(
      o.id,'outbound','seller_arranged',normalized_carrier,'in_transit',normalized_tracking,stamped_at,tracker_provider,tracker_ref
    ) returning * into shipment;
    insert into public.shipment_items(shipment_id,order_item_id)
    select shipment.id,id from public.order_items where order_id=o.id
    on conflict do nothing;
    if not exists(select 1 from public.shipment_items where shipment_id=shipment.id) then
      raise exception 'Dispatch shipment has no order items';
    end if;
  end if;

  -- Tracking DRVN can follow, registered off the request path (N110).
  if shipment.tracking_code is not null and shipment.provider_tracker_id is null then
    insert into public.remediation_jobs(kind,dedup_key,payload,next_attempt_at)
    values('tracker_registration','tracker:'||shipment.id,
           jsonb_build_object('shipment_id',shipment.id,'order_id',o.id),
           now()+interval '5 minutes')
    on conflict(dedup_key) do nothing;
  end if;

  if o.status='disputed' then
    -- The case stays open; resolving it lands on 'shipped'.
    update public.orders set
      pre_dispute_status='shipped',carrier=normalized_carrier,tracking_number=normalized_tracking,shipped_at=stamped_at
    where id=o.id;
    if o.buyer_id is not null then
      perform public.notify(o.buyer_id,'order_shipped','marketplace','Your part is on its way',
        normalized_carrier||' · '||normalized_tracking,'/orders/'||o.id,o.seller_id);
    end if;
    return jsonb_build_object('ok',true,'applied',true,'replayed',false,'status','disputed','shipment_id',shipment.id);
  end if;

  update public.orders set
    status='shipped',carrier=normalized_carrier,tracking_number=normalized_tracking,shipped_at=stamped_at
  where id=o.id;
  return jsonb_build_object('ok',true,'applied',true,'replayed',false,'status','shipped','shipment_id',shipment.id);
end $$;


--
-- Name: mark_order_received(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_received(p_order uuid, p_actor uuid, p_hold_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  intent public.transfer_intents;
  stamped_at timestamptz:=now();
  applied boolean:=false;
  stub_settlement boolean:=false;
  plausible boolean:=false;
begin
  if p_order is null or p_actor is null or p_hold_days<0 or p_hold_days>30 then
    raise exception 'Invalid receipt transition';
  end if;
  select * into strict o from public.orders where id=p_order for update;
  if o.buyer_id is distinct from p_actor then raise exception 'Buyer authorization required' using errcode='42501'; end if;
  if o.is_collection then raise exception 'Collection orders use the pickup handoff'; end if;
  if o.status not in ('shipped','delivered','completed') then
    return jsonb_build_object('ok',false,'applied',false,'status',o.status,'reason','Only a dispatched order can be received.');
  end if;

  select * into intent from public.transfer_intents where order_id=o.id for update;
  if not found then
    select exists(
      select 1 from public.payments p where p.order_id=o.id
      and p.provider='stub' and p.status='succeeded' and p.provider_reference is not null
      and p.amount_cents=o.total_cents and lower(p.currency)=lower(o.currency)
    ) into stub_settlement;
    if not stub_settlement then raise exception 'Seller transfer obligation is missing'; end if;
  end if;

  if o.status='shipped' then
    -- Plausibly arrived: a carrier says so, or it has been in transit long
    -- enough. Read before this receipt marks the shipments delivered itself.
    plausible:=exists(
      select 1 from public.shipments s
      where s.order_id=o.id and s.direction='outbound'
        and s.provider_tracker_id is not null and s.status='delivered'
    ) or (o.shipped_at is not null and o.shipped_at<=stamped_at-make_interval(days=>coalesce(
      (select s.receipt_release_after_days from public.settlement_settings s where s.id),3)));

    perform set_config('drvn.release_on_delivery',case when plausible then 'on' else '' end,true);
    update public.orders set status='delivered',delivered_at=stamped_at,completed_at=stamped_at where id=o.id;
    perform set_config('drvn.release_on_delivery','',true);
    o.status:='delivered';
    o.delivered_at:=stamped_at;
    applied:=true;
    update public.shipments set status='delivered',delivered_at=coalesce(delivered_at,stamped_at)
    where order_id=o.id and direction='outbound' and status in ('label_purchased','in_transit','out_for_delivery');
  elsif o.delivered_at is null then
    raise exception 'Delivered order is missing its receipt timestamp';
  end if;

  if not stub_settlement then
    update public.transfer_intents set
      available_at=coalesce(available_at,case
        when p_hold_days is null then public.payout_release_at(o.id,o.delivered_at,plausible)
        else o.delivered_at+make_interval(days=>p_hold_days)
      end),
      updated_at=now()
    where order_id=o.id and status='holding';
  end if;

  return jsonb_build_object(
    'ok',true,'applied',applied,'replayed',not applied,'status',o.status,
    'available_at',(select available_at from public.transfer_intents where order_id=o.id)
  );
end $$;


--
-- Name: mark_return_dispatched(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_return_dispatched(p_return uuid, p_actor uuid, p_carrier text, p_tracking text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.returns; o public.orders; s public.shipments; v_carrier text:=nullif(trim(p_carrier),''); v_tracking text:=nullif(trim(p_tracking),''); applied boolean:=false;
begin
 select * into strict r from public.returns where id=p_return;
 select * into strict o from public.orders where id=r.order_id for update;
 select * into strict r from public.returns where id=p_return for update;
 if p_actor is null or o.buyer_id is distinct from p_actor then raise exception 'Buyer authorization required' using errcode='42501'; end if;
 if r.status not in ('approved','awaiting_shipment','in_transit') then raise exception 'Return is not waiting for dispatch'; end if;
 if exists(select 1 from public.return_label_requests where return_id=r.id and completed_at is null) then raise exception 'Finish reconciling the prepaid label before adding tracking'; end if;
 if (select count(*) from public.shipments where return_id=r.id and status not in ('cancelled','failed'))>1 then raise exception 'Multiple return shipments require operator review'; end if;
 select * into s from public.shipments where return_id=r.id and status not in ('cancelled','failed') for update;
 if found then
   if s.status not in ('pending','label_purchased','in_transit') then raise exception 'Return shipment has already advanced'; end if;
   if s.label_reference is not null then
     if v_tracking is not null and v_tracking is distinct from s.tracking_code then raise exception 'Tracking differs from the prepaid label'; end if;
     v_tracking:=s.tracking_code; v_carrier:=s.carrier;
   elsif s.tracking_code is distinct from v_tracking or s.carrier is distinct from v_carrier then
     raise exception 'Return tracking changed after dispatch';
   end if;
 else
   if r.status='in_transit' then raise exception 'Return shipment record is missing'; end if;
   if v_carrier is null or v_tracking is null then raise exception 'Carrier and tracking are required'; end if;
   insert into public.shipments(order_id,direction,return_id,fulfillment_type,carrier,tracking_code,status,shipped_at)
   values(o.id,'return',r.id,'seller_arranged',v_carrier,v_tracking,'in_transit',now()) returning * into s;
 end if;
 if v_tracking is null or v_carrier is null then raise exception 'Return tracking is incomplete'; end if;
 insert into public.shipment_items(shipment_id,order_item_id) select s.id,order_item_id from public.return_items where return_id=r.id on conflict do nothing;
 if not exists(select 1 from public.shipment_items where shipment_id=s.id) then raise exception 'Return has no item links'; end if;
 if r.status<>'in_transit' then
   update public.shipments set status='in_transit',shipped_at=coalesce(shipped_at,now()) where id=s.id and status in ('pending','label_purchased');
   if r.status='approved' then update public.returns set status='awaiting_shipment' where id=r.id; end if;
   update public.returns set status='in_transit',shipped_at=coalesce(shipped_at,now()) where id=r.id;
   applied:=true;
 end if;
 return jsonb_build_object('ok',true,'applied',applied,'shipment_id',s.id,'manual',s.label_reference is null,'carrier',v_carrier,'tracking',v_tracking);
end $$;


--
-- Name: marketplace_brand_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_brand_counts() RETURNS TABLE(brand text, total bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.key, f.total
  from public.marketplace_facet_counts f where f.facet = 'brand'
  order by f.total desc, f.key;
$$;


--
-- Name: marketplace_browse_rows(text, text, integer, integer, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_browse_rows(p_query text DEFAULT ''::text, p_vehicle text DEFAULT ''::text, p_vyear integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_fit boolean DEFAULT false, p_viewer uuid DEFAULT auth.uid()) RETURNS SETOF public.listings
    LANGUAGE sql STABLE
    AS $_$
 select l.* from public.listings l where trim(p_query)='' and l.status='active'
 and (p_viewer is not distinct from auth.uid() or current_user='service_role')
 and (l.seller_id not in (select public.suspended_profile_ids()) or l.seller_id=p_viewer)
 and (p_vehicle='' or exists(
   select 1 from public.catalog_makes m
   left join public.catalog_models mo on mo.make_id=m.id and mo.id=case when p_vehicle ~ '^[1-9][0-9]{0,9}-[1-9][0-9]{0,9}$' then split_part(p_vehicle,'-',2)::bigint else 0 end
   join public.listing_vehicle_fit v on v.listing_id=l.id and v.make_key=lower(m.name) and v.model_key=coalesce(lower(mo.name),'')
   where m.id=case when p_vehicle ~ '^[1-9][0-9]{0,9}(-[1-9][0-9]{0,9})?$' then split_part(p_vehicle,'-',1)::bigint else 0 end
   and (position('-' in p_vehicle)=0 or mo.id is not null)
   and case when v.via='stated' then p_vyear=0 or v.years @> p_vyear
     else not v.stated_also and (v.car_public or v.car_owner_id=p_viewer)
       and (v.car_owner_id=v.seller_id or v.car_owner_id=p_viewer or v.car_owner_id not in (select public.suspended_profile_ids())) end))
 and ((p_ymin=0 and p_ymax=9999) or exists(select 1 from public.cars c where c.id=l.source_car_id and (c.is_public or c.owner_id=p_viewer) and (public.profile_is_visible(c.owner_id) or c.owner_id=p_viewer) and c.year between p_ymin and p_ymax))
 and (not p_fit or exists(select 1 from public.cars g
   join public.listing_vehicle_fit v on v.listing_id=l.id and v.make_key=lower(g.make) and v.model_key=lower(g.model)
   where g.owner_id=(select p_viewer) and g.make is not null and g.model is not null
   and case when v.via='stated' then case when coalesce(g.year,0)=0 then v.all_years else v.years @> g.year end
     else not v.stated_also and (v.car_public or v.car_owner_id=p_viewer)
       and (v.car_owner_id=v.seller_id or v.car_owner_id=p_viewer or v.car_owner_id not in (select public.suspended_profile_ids())) end))
 union all
 select s.* from public.marketplace_search_browse_rows(p_query, p_vehicle, p_vyear, p_ymin, p_ymax, p_fit, p_viewer) s;
$_$;


--
-- Name: marketplace_category_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_category_counts() RETURNS TABLE(category text, subcategory text, total bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.key, nullif(f.subkey, ''), f.total
  from public.marketplace_facet_counts f where f.facet = 'category';
$$;


--
-- Name: marketplace_count(text, text, text, text, text, text, integer, integer, text, integer, integer, integer, boolean, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_count(p_query text DEFAULT ''::text, p_category text DEFAULT ''::text, p_subcategory text DEFAULT ''::text, p_condition text DEFAULT ''::text, p_brand text DEFAULT ''::text, p_location text DEFAULT ''::text, p_min_cents integer DEFAULT NULL::integer, p_max_cents integer DEFAULT NULL::integer, p_vehicle text DEFAULT ''::text, p_vyear integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_fit boolean DEFAULT false, p_cap integer DEFAULT 10001, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sql text := public.marketplace_query_sql('count', p_query, p_category, p_subcategory, p_condition, p_brand, p_location,
    p_min_cents, p_max_cents, p_vehicle, p_vyear, p_ymin, p_ymax, p_fit,
    'newest', null, null, null, false, 0, 1, p_cap, p_ids);
  total integer;
begin
  if sql is null then return 0; end if;
  execute sql into total;
  return total;
end;
$$;


--
-- Name: marketplace_filtered_rows(text, text, text, integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_filtered_rows(p_query text DEFAULT ''::text, p_make text DEFAULT ''::text, p_model text DEFAULT ''::text, p_make_id integer DEFAULT 0, p_model_id integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_fit boolean DEFAULT false) RETURNS SETOF public.listings
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 select l.* from public.listings l where
 (trim(p_query)='' or l.id in(select id from public.marketplace_search_rows(p_query)))
 and (p_make='' or exists(select 1 from public.cars c where c.id=l.source_car_id and
   ((p_model_id<>0 and c.catalog_model_id=p_model_id) or (p_model_id=0 and c.catalog_make_id=p_make_id) or
   (lower(c.make)=lower(p_make) and (p_model='' or lower(c.model)=lower(p_model)))))
   or exists(select 1 from public.listing_fitments f where f.listing_id=l.id and lower(f.make)=lower(p_make) and (p_model='' or lower(f.model)=lower(p_model))))
 and ((p_ymin=0 and p_ymax=9999) or exists(select 1 from public.cars c where c.id=l.source_car_id and c.year between p_ymin and p_ymax))
 and (not p_fit or exists(select 1 from public.cars g where g.owner_id=auth.uid() and g.make is not null and g.model is not null and (
   exists(select 1 from public.cars c where c.id=l.source_car_id and lower(c.make)=lower(g.make) and lower(c.model)=lower(g.model))
   or exists(select 1 from public.listing_fitments f where f.listing_id=l.id and lower(f.make)=lower(g.make) and lower(f.model)=lower(g.model) and
   (g.year is null or ((f.year_start is null or g.year>=f.year_start) and (f.year_end is null or g.year<=f.year_end)))))));
$$;


--
-- Name: marketplace_match_evidence(uuid, text, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_match_evidence(p_listing uuid, p_make text, p_model text, p_year integer DEFAULT 0, p_viewer uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 with eligible as (
   select l.* from public.listings l where l.id=p_listing
     and (p_viewer is not distinct from auth.uid() or current_user='service_role')
     and (public.profile_is_visible(l.seller_id) or l.seller_id=p_viewer)
 ), claims as (
   select f.* from public.listing_fitments f join eligible l on l.id=f.listing_id
   where lower(f.make)=lower(p_make) and (coalesce(p_model,'')='' or lower(f.model)=lower(p_model))
 )
 select case
   when coalesce(p_make,'')='' or not exists(select 1 from eligible) then 'unknown'
   when exists(select 1 from claims f where (p_year<>0 or (f.year_start is null and f.year_end is null))
      and (p_year=0 or ((f.year_start is null or p_year>=f.year_start) and (f.year_end is null or p_year<=f.year_end)))) then 'seller_stated'
   when exists(select 1 from claims) then case when p_year=0 then 'year_needed' else 'outside_years' end
   when exists(select 1 from eligible l join public.cars c on c.id=l.source_car_id
     where (c.is_public or c.owner_id=p_viewer) and (public.profile_is_visible(c.owner_id) or c.owner_id=p_viewer)
     and lower(c.make)=lower(p_make) and (coalesce(p_model,'')='' or lower(c.model)=lower(p_model))) then 'source_model'
   else 'unknown' end;
$$;


--
-- Name: marketplace_page(text, text, text, text, text, text, integer, integer, text, integer, integer, integer, boolean, text, timestamp with time zone, integer, uuid, boolean, integer, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_page(p_query text DEFAULT ''::text, p_category text DEFAULT ''::text, p_subcategory text DEFAULT ''::text, p_condition text DEFAULT ''::text, p_brand text DEFAULT ''::text, p_location text DEFAULT ''::text, p_min_cents integer DEFAULT NULL::integer, p_max_cents integer DEFAULT NULL::integer, p_vehicle text DEFAULT ''::text, p_vyear integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_fit boolean DEFAULT false, p_sort text DEFAULT 'newest'::text, p_after_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_price integer DEFAULT NULL::integer, p_after_id uuid DEFAULT NULL::uuid, p_before boolean DEFAULT false, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS SETOF public.listings
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sql text := public.marketplace_query_sql('page', p_query, p_category, p_subcategory, p_condition, p_brand, p_location,
    p_min_cents, p_max_cents, p_vehicle, p_vyear, p_ymin, p_ymax, p_fit,
    p_sort, p_after_created, p_after_price, p_after_id, p_before, p_offset, p_limit, null, p_ids);
begin
  if sql is not null then
    return query execute sql;
  end if;
end;
$$;


--
-- Name: marketplace_query_sql(text, text, text, text, text, text, text, integer, integer, text, integer, integer, integer, boolean, text, timestamp with time zone, integer, uuid, boolean, integer, integer, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_query_sql(p_mode text, p_query text, p_category text, p_subcategory text, p_condition text, p_brand text, p_location text, p_min_cents integer, p_max_cents integer, p_vehicle text, p_vyear integer, p_ymin integer, p_ymax integer, p_fit boolean, p_sort text, p_after_created timestamp with time zone, p_after_price integer, p_after_id uuid, p_before boolean, p_offset integer, p_limit integer, p_cap integer, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  viewer uuid := auth.uid();
  sort text := case when p_sort in ('price_asc', 'price_desc') then p_sort else 'newest' end;
  lim integer := least(greatest(coalesce(p_limit, 25), 1), 101);
  skip integer := greatest(coalesce(p_offset, 0), 0);
  cap integer := least(greatest(coalesce(p_cap, 10001), 1), 100001);
  -- " or <column> = <viewer>", for the rules that let a member see their own.
  own text := case when viewer is null then '' else format(' or {col} = %L', viewer) end;
  make_name text;
  model_name text;
  filters text;
  fit_rule text;
  keyset text := '';
  order_by text;
  ascending boolean;
  garage record;
  arms text[] := '{}';
  slices text[] := '{}';
  arm text;
  body text;
  base_filters text;
  -- The ids a typed search matched, as a subquery (Postgres' capped search).
  searched text;
  -- The same seller rule, on listing_vehicle_fit's own copy of the seller.
  fit_seller text;
begin
  -- Skipping is for old ?page=N links; past 10,000 parts it would be a slow
  -- read of everything before, so there is no page there (the app offers
  -- page one). Positions have no such limit.
  if coalesce(p_offset, 0) > 10000 then return null; end if;

  -- The browse function's rules: for sale, seller not suspended (or the
  -- viewer), plus whatever the shopper chose. Every value is quoted in.
  filters := ' and l.status = ''active'' and (l.seller_id not in (select public.suspended_profile_ids())'
    || replace(own, '{col}', 'l.seller_id') || ')';
  base_filters := filters;
  if coalesce(p_category, '') <> '' then filters := filters || format(' and l.category = %L', p_category); end if;
  if coalesce(p_subcategory, '') <> '' then filters := filters || format(' and l.subcategory = %L', p_subcategory); end if;
  if coalesce(p_condition, '') <> '' then filters := filters || format(' and l.condition = %L', p_condition); end if;
  -- The whole brand, whatever its case. The app's rule was ILIKE with the
  -- wildcards escaped; on a UTF-8 database ILIKE lower-cases both sides and
  -- compares, so brand_key = lower(the brand) is the same test — one the
  -- planner can estimate and, under row security, answer from
  -- listings_active_brand_published_idx (ILIKE and lower() can't use an index there).
  if coalesce(p_brand, '') <> '' then
    filters := filters || format(' and l.brand_key = %L', lower(p_brand));
  end if;
  if coalesce(p_location, '') <> '' then
    filters := filters || format(' and l.location ilike %L', '%' || regexp_replace(p_location, '([\\%_])', '\\\1', 'g') || '%');
  end if;
  if p_min_cents is not null then filters := filters || format(' and l.price_cents >= %s', p_min_cents); end if;
  if p_max_cents is not null then filters := filters || format(' and l.price_cents <= %s', p_max_cents); end if;
  if not (coalesce(p_ymin, 0) = 0 and coalesce(p_ymax, 9999) = 9999) then
    filters := filters || format(
      ' and exists (select 1 from public.cars c where c.id = l.source_car_id and (c.is_public%s)'
      ' and (c.owner_id not in (select public.suspended_profile_ids())%s) and c.year between %s and %s)',
      replace(own, '{col}', 'c.owner_id'), replace(own, '{col}', 'c.owner_id'), coalesce(p_ymin, 0), coalesce(p_ymax, 9999));
  end if;
  -- A page the search engine found: those ids, still passing every rule.
  -- Otherwise a typed search is Postgres' own, capped at the newest 1,001
  -- matches among what the filters allow (marketplace_search_capped_ids).
  if p_ids is not null then
    filters := filters || format(' and l.id = any(%L::uuid[])', p_ids);
  elsif coalesce(trim(p_query), '') <> '' then
    searched := format('(select x.id from public.marketplace_search_capped_ids(%L, %L, %L, %L, %L, %L, %s, %s) x(id))',
      p_query, coalesce(p_category, ''), coalesce(p_subcategory, ''), coalesce(p_condition, ''), coalesce(p_brand, ''),
      coalesce(p_location, ''), coalesce(p_min_cents::text, 'null'), coalesce(p_max_cents::text, 'null'));
    -- A plain search reads from the matched ids (below); a search with a
    -- vehicle or a garage tests each candidate against them.
    if coalesce(p_vehicle, '') <> '' or p_fit then
      filters := filters || ' and l.id in ' || searched;
    end if;
  end if;

  -- How a stated or source-car row decides a match (20261011100000).
  -- {years} is the stated rows' year test.
  fit_seller := ' and (v.seller_id not in (select public.suspended_profile_ids())' || replace(own, '{col}', 'v.seller_id') || ')';
  fit_rule := 'case when v.via = ''stated'' then {years} else not v.stated_also and (v.car_public'
    || replace(own, '{col}', 'v.car_owner_id') || ') and (v.car_owner_id = v.seller_id'
    || replace(own, '{col}', 'v.car_owner_id') || ' or v.car_owner_id not in (select public.suspended_profile_ids())) end';

  if coalesce(p_vehicle, '') <> '' then
    select m.name, mo.name into make_name, model_name
    from public.catalog_makes m
    left join public.catalog_models mo on mo.make_id = m.id
      and mo.id = case when p_vehicle ~ '^[1-9][0-9]{0,9}-[1-9][0-9]{0,9}$' then split_part(p_vehicle, '-', 2)::bigint else 0 end
    where m.id = case when p_vehicle ~ '^[1-9][0-9]{0,9}(-[1-9][0-9]{0,9})?$' then split_part(p_vehicle, '-', 1)::bigint else 0 end
      and (position('-' in p_vehicle) = 0 or mo.id is not null);
    if make_name is null then return null; end if; -- names no vehicle: nothing matches
  end if;

  -- "Fits my garage": one test per distinct garage car.
  if p_fit then
    for garage in
      select distinct lower(g.make) as make_key, lower(g.model) as model_key, coalesce(g.year, 0) as yr
      from public.cars g
      where g.owner_id = viewer and g.make is not null and g.model is not null
      order by 1, 2, 3
    loop
      arms := arms || (format('v.make_key = %L and v.model_key = %L and ', garage.make_key, garage.model_key)
        || replace(fit_rule, '{years}', case when garage.yr = 0 then 'v.all_years' else format('v.years @> %s', garage.yr) end));
    end loop;
    if cardinality(arms) = 0 then return null; end if; -- no garage: nothing fits
  end if;

  -- Order and keyset position, written over {t}.{id}: whichever table
  -- drives the read. Paging backwards reads the other way. Newest is by
  -- when a part first went on sale (published_at, 20261107153200), so
  -- p_after_created is the position part's published_at.
  if sort = 'newest' then
    ascending := coalesce(p_before, false);
    order_by := case when ascending then '{t}.published_at asc, {t}.{id} asc' else '{t}.published_at desc, {t}.{id} desc' end;
    if p_after_created is not null and p_after_id is not null then
      keyset := format(' and ({t}.published_at, {t}.{id}) %s (%L::timestamptz, %L::uuid)',
        case when ascending then '>' else '<' end, p_after_created, p_after_id);
    end if;
  else
    ascending := (sort = 'price_asc') <> coalesce(p_before, false);
    order_by := case when ascending then '{t}.price_cents asc, {t}.{id} asc' else '{t}.price_cents desc, {t}.{id} desc' end;
    if p_after_price is not null and p_after_id is not null then
      keyset := format(' and ({t}.price_cents, {t}.{id}) %s (%s, %L::uuid)',
        case when ascending then '>' else '<' end, p_after_price, p_after_id);
    end if;
  end if;

  if p_ids is not null then
    -- The engine's page: at most a page of ids, so the rules are tests on
    -- those rows, and the engine's order stands.
    body := 'from public.listings l where true' || filters;
    if make_name is not null then
      body := body || format(' and exists (select 1 from public.listing_vehicle_fit v where v.listing_id = l.id'
        ' and v.make_key = %L and v.model_key = %L and ', lower(make_name), coalesce(lower(model_name), ''))
        || replace(fit_rule, '{years}', case when coalesce(p_vyear, 0) = 0 then 'true' else format('v.years @> %s', p_vyear) end) || ')';
    end if;
    if p_fit then
      body := body || ' and exists (select 1 from public.listing_vehicle_fit v where v.listing_id = l.id and (('
        || array_to_string(arms, ') or (') || ')))';
    end if;
    if p_mode = 'count' then
      return format('select count(*)::integer from (select 1 %s limit %s) counted', body, cap);
    end if;
    return format('select l.* %s order by array_position(%L::uuid[], l.id) limit %s', body, p_ids, lim);
  end if;

  if make_name is not null then
    -- Driven by the chosen vehicle's rows, in index order.
    body := format('from public.listing_vehicle_fit v join public.listings l on l.id = v.listing_id'
      ' where v.make_key = %L and v.model_key = %L and ', lower(make_name), coalesce(lower(model_name), ''))
      || replace(fit_rule, '{years}', case when coalesce(p_vyear, 0) = 0 then 'true' else format('v.years @> %s', p_vyear) end)
      || filters;
    if p_fit then
      body := body || ' and exists (select 1 from public.listing_vehicle_fit v where v.listing_id = l.id and (('
        || array_to_string(arms, ') or (') || ')))';
    end if;
    if p_mode = 'count' then
      -- Each row checks its own part by key, so the count stops at the cap;
      -- as a join the planner read every row for the vehicle, then every
      -- part for sale (3-21 s at 2M for the commonest car).
      -- With nothing but the vehicle chosen, the rows answer alone: a row
      -- exists only for a part for sale, and carries its seller.
      return format('select count(*)::integer from (select 1 from public.listing_vehicle_fit v'
        ' where v.make_key = %L and v.model_key = %L and %s%s limit %s) counted',
        lower(make_name), coalesce(lower(model_name), ''),
        replace(fit_rule, '{years}', case when coalesce(p_vyear, 0) = 0 then 'true' else format('v.years @> %s', p_vyear) end),
        case when filters = base_filters and not p_fit then fit_seller
             else ' and coalesce((select true from public.listings l where l.id = v.listing_id' || filters
                  || case when p_fit then ' and exists (select 1 from public.listing_vehicle_fit v where v.listing_id = l.id and (('
                                          || array_to_string(arms, ') or (') || ')))' else '' end
                  || '), false)' end,
        cap);
    end if;
    return format('select l.* %s%s order by %s limit %s offset %s', body,
      replace(replace(keyset, '{t}', 'v'), '{id}', 'listing_id'),
      replace(replace(order_by, '{t}', 'v'), '{id}', 'listing_id'), lim, skip);
  end if;

  if p_fit then
    -- One ordered slice per garage car, each as long as the page; the page
    -- is the best of them. A part fitting two cars is one part.
    foreach arm in array arms loop
      slices := slices || case when p_mode = 'count' then
        -- Counting: each row checks its own part by key (see the vehicle count).
        format('(select v.listing_id from public.listing_vehicle_fit v where %s%s limit %s)',
          arm, case when filters = base_filters then fit_seller
                    else ' and coalesce((select true from public.listings l where l.id = v.listing_id' || filters || '), false)' end, cap)
      else
        format('(select v.listing_id from public.listing_vehicle_fit v join public.listings l on l.id = v.listing_id where %s%s%s order by %s limit %s)',
          arm, filters, replace(replace(keyset, '{t}', 'v'), '{id}', 'listing_id'),
          replace(replace(order_by, '{t}', 'v'), '{id}', 'listing_id'), lim + skip)
      end;
    end loop;
    if p_mode = 'count' then
      return format('select count(*)::integer from (select distinct listing_id from (%s) s limit %s) counted',
        array_to_string(slices, ' union all '), cap);
    end if;
    return format('select l.* from public.listings l where l.id in (select listing_id from (%s) s)%s order by %s limit %s offset %s',
      array_to_string(slices, ' union all '), filters, replace(replace(order_by, '{t}', 'l'), '{id}', 'id'), lim, skip);
  end if;

  -- A plain browse or a filter: the listings indexes. A search: its matched
  -- ids (at most 1,001), each read by key — walking parts in order looking
  -- for them read deep into the catalogue for a word that matches few.
  if p_mode = 'count' then
    return format('select count(*)::integer from (select 1 from %s where true%s limit %s) counted',
      coalesce(searched || ' s join public.listings l on l.id = s.id', 'public.listings l'), filters, cap);
  end if;
  return format('select l.* from %s where true%s%s order by %s limit %s offset %s',
    coalesce(searched || ' s join public.listings l on l.id = s.id', 'public.listings l'),
    filters, replace(replace(keyset, '{t}', 'l'), '{id}', 'id'), replace(replace(order_by, '{t}', 'l'), '{id}', 'id'), lim, skip);
end;
$_$;


--
-- Name: marketplace_search_browse_rows(text, text, integer, integer, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_browse_rows(p_query text, p_vehicle text DEFAULT ''::text, p_vyear integer DEFAULT 0, p_ymin integer DEFAULT 0, p_ymax integer DEFAULT 9999, p_fit boolean DEFAULT false, p_viewer uuid DEFAULT auth.uid()) RETURNS SETOF public.listings
    LANGUAGE sql STABLE
    AS $_$
 select l.* from public.marketplace_search_ids(p_query) s(id) join public.listings l on l.id=s.id
 where trim(p_query)<>'' and l.status='active'
 and (p_viewer is not distinct from auth.uid() or current_user='service_role')
 and (l.seller_id not in (select public.suspended_profile_ids()) or l.seller_id=p_viewer)
 and (p_vehicle='' or exists(
   select 1 from public.catalog_makes m
   left join public.catalog_models mo on mo.make_id=m.id and mo.id=case when p_vehicle ~ '^[1-9][0-9]{0,9}-[1-9][0-9]{0,9}$' then split_part(p_vehicle,'-',2)::bigint else 0 end
   join public.listing_vehicle_fit v on v.listing_id=l.id and v.make_key=lower(m.name) and v.model_key=coalesce(lower(mo.name),'')
   where m.id=case when p_vehicle ~ '^[1-9][0-9]{0,9}(-[1-9][0-9]{0,9})?$' then split_part(p_vehicle,'-',1)::bigint else 0 end
   and (position('-' in p_vehicle)=0 or mo.id is not null)
   and case when v.via='stated' then p_vyear=0 or v.years @> p_vyear
     else not v.stated_also and (v.car_public or v.car_owner_id=p_viewer)
       and (v.car_owner_id=v.seller_id or v.car_owner_id=p_viewer or v.car_owner_id not in (select public.suspended_profile_ids())) end))
 and ((p_ymin=0 and p_ymax=9999) or exists(select 1 from public.cars c where c.id=l.source_car_id and (c.is_public or c.owner_id=p_viewer) and (public.profile_is_visible(c.owner_id) or c.owner_id=p_viewer) and c.year between p_ymin and p_ymax))
 and (not p_fit or exists(select 1 from public.cars g
   join public.listing_vehicle_fit v on v.listing_id=l.id and v.make_key=lower(g.make) and v.model_key=lower(g.model)
   where g.owner_id=(select p_viewer) and g.make is not null and g.model is not null
   and case when v.via='stated' then case when coalesce(g.year,0)=0 then v.all_years else v.years @> g.year end
     else not v.stated_also and (v.car_public or v.car_owner_id=p_viewer)
       and (v.car_owner_id=v.seller_id or v.car_owner_id=p_viewer or v.car_owner_id not in (select public.suspended_profile_ids())) end));
$_$;


--
-- Name: marketplace_search_capped_ids(text, text, text, text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_capped_ids(p_query text, p_category text DEFAULT ''::text, p_subcategory text DEFAULT ''::text, p_condition text DEFAULT ''::text, p_brand text DEFAULT ''::text, p_location text DEFAULT ''::text, p_min_cents integer DEFAULT NULL::integer, p_max_cents integer DEFAULT NULL::integer, p_cap integer DEFAULT 1001) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER ROWS 1001
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  cap integer := least(greatest(coalesce(p_cap, 1001), 1), 5001);
  term text := trim(regexp_replace(coalesce(p_query, ''), '[,()]', ' ', 'g'));
  compact text := lower(regexp_replace(term, '[^a-zA-Z0-9]', '', 'g'));
  identifier boolean;
  terms text[];
  numbered uuid[];
  filters text;
  matches text;
  window_size integer := 30000;
  found uuid[];
  scanned integer;
begin
  if term = '' then return; end if;
  -- marketplace_search_ids' rules: a single token of five or more letters
  -- and digits, two of them digits, is a part number and nothing else.
  identifier := term !~ '\s' and length(compact) >= 5 and length(regexp_replace(compact, '[^0-9]', '', 'g')) >= 2;
  terms := array(select distinct t from regexp_split_to_table(lower(term), '\s+') t where length(t) >= 1);
  -- A word not on search_words is searched alongside its closest word.
  terms := terms || array(select c.correction from public.search_word_corrections(term) c where c.correction <> all(terms));
  -- The part numbers (and their interchange numbers) the query could be.
  if length(compact) >= 4 and compact ~ '[0-9]' then
    numbered := array(
      with variants as (
        select compact as v
        union
        select case when k.from_compact = compact then k.to_compact else k.from_compact end
        from public.part_number_links k where k.from_compact = compact or k.to_compact = compact)
      select l.id from variants v join public.listings l on l.part_number_compact like '%' || v.v || '%'
      union
      select n.listing_id from variants v join public.listing_part_numbers n on n.number_compact = v.v);
  else
    numbered := '{}';
  end if;

  -- The visitor's read rule and the shopper's filters, values quoted in.
  filters := ' and l.status = ''active'' and l.seller_id not in (select public.suspended_profile_ids())';
  if coalesce(p_category, '') <> '' then filters := filters || format(' and l.category = %L', p_category); end if;
  if coalesce(p_subcategory, '') <> '' then filters := filters || format(' and l.subcategory = %L', p_subcategory); end if;
  if coalesce(p_condition, '') <> '' then filters := filters || format(' and l.condition = %L', p_condition); end if;
  -- The whole brand, whatever its case (see marketplace_query_sql).
  if coalesce(p_brand, '') <> '' then
    filters := filters || format(' and l.brand_key = %L', lower(p_brand));
  end if;
  if coalesce(p_location, '') <> '' then
    filters := filters || format(' and l.location ilike %L', '%' || regexp_replace(p_location, '([\\%_])', '\\\1', 'g') || '%');
  end if;
  if p_min_cents is not null then filters := filters || format(' and l.price_cents >= %s', p_min_cents); end if;
  if p_max_cents is not null then filters := filters || format(' and l.price_cents <= %s', p_max_cents); end if;

  -- What the words match: any word (or its correction, above), in the
  -- part's search document (search_listing_ids' first rule), or one of the
  -- numbers. A part number is matched by its numbers alone. Unlike
  -- search_listing_ids, a word is not also matched "close to" a word of the
  -- title: that test read thousands of near-miss titles from disk for one
  -- ordinary word (it timed out at 2M parts).
  matches := case when cardinality(numbered) > 0 then format('l.id = any(%L::uuid[])', numbered) else 'false' end;
  if not identifier then
    matches := matches || ' or ' || (
      select string_agg(format('public.listing_search_doc(l.title, l.description, l.compatibility_notes, l.category, l.brand) ilike %L', '%' || t || '%'), ' or ')
      from unnest(terms) t);
  end if;

  -- Newest (first published) first through the parts the filters allow,
  -- stopping at the cap:
  -- a common word fills it within a few thousand parts.
  execute format(
    'select array_agg(id) from (select l.id from (select l.* from public.listings l where true%s'
    ' order by l.published_at desc, l.id desc limit %s) l where %s limit %s) hits',
    filters, window_size, matches, cap)
    into found;
  found := coalesce(found, '{}');
  if cardinality(found) >= cap then
    return query select unnest(found);
    return;
  end if;
  -- Fewer than the cap in the window: if the window held every part the
  -- filters allow, that is the whole answer.
  execute format('select count(*) from (select 1 from public.listings l where true%s limit %s) w', filters, window_size)
    into scanned;
  if scanned < window_size then
    return query select unnest(found);
    return;
  end if;
  -- Sparse among the newest: every match through the word index, then
  -- newest first among those. The fence (offset 0) keeps the planner from
  -- walking every part newest-first instead — it guesses a word is common,
  -- and at 2M parts that read 150,000 parts from disk for one word.
  return query execute format(
    'select m.id from (select l.id, l.published_at from public.listings l where (%s)%s offset 0) m'
    ' order by m.published_at desc, m.id desc limit %s',
    matches, filters, cap);
end;
$$;


--
-- Name: marketplace_search_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_ids(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 100
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
 with cleaned as(select trim(regexp_replace(p_query,'[,()]',' ','g')) term),
 q as(select term,lower(regexp_replace(term,'[^a-zA-Z0-9]','','g')) compact from cleaned),
 classified as(select *,term !~ '\s' and length(compact)>=5 and length(regexp_replace(compact,'[^0-9]','','g'))>=2 identifier from q),
 -- The number as typed plus its known interchange numbers; none unless it
 -- could be a part number at all (identifier_matches_listing's own rule).
 variants as(
   select q.compact from classified q where length(q.compact)>=4 and q.compact ~ '[0-9]'
   union
   select case when k.from_compact=q.compact then k.to_compact else k.from_compact end
   from classified q join public.part_number_links k on k.from_compact=q.compact or k.to_compact=q.compact
   where length(q.compact)>=4 and q.compact ~ '[0-9]'),
 numbered as(
   select l.id from variants v join public.listings l on l.part_number_compact like '%'||v.compact||'%'
   union
   select n.listing_id from variants v join public.listing_part_numbers n on n.number_compact=v.compact)
 select l.id from public.listings l join public.profiles o on o.id=l.seller_id
 where l.status='active' and o.suspended_at is null and l.id in(select id from numbered)
 union
 select s.id from classified q cross join lateral public.search_listing_ids(q.term) s(id) where not q.identifier;
$$;


--
-- Name: marketplace_search_rows(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_rows(p_query text) RETURNS SETOF public.listings
    LANGUAGE sql STABLE
    AS $$
 select l.* from public.listings l where l.id in(select public.marketplace_search_ids(p_query));
$$;


--
-- Name: media_object_referenced(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.media_object_referenced(p_bucket text, p_path text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  k text;
begin
  if p_bucket is null or p_bucket !~ '^[a-z0-9_-]{1,63}$' or not coalesce(private.media_path_ok(p_path), false) then
    return true;
  end if;
  k := p_bucket || '/' || p_path;
  -- 20261110120000: a taken-down object is referenced only where a guard
  -- would have refused it (the photo columns the purge clears). A mention in
  -- a post's text or an order's commercial snapshot can't pin it: the media
  -- worker deletes it, and the proxy refuses it meanwhile.
  if exists (select 1 from public.copyright_blocked_media b where b.object_key = k) then
    return exists (select 1 from public.car_images where private.media_object_key(url) = k)
      or exists (select 1 from public.listing_images where private.media_object_key(url) = k)
      or exists (select 1 from public.activity_images where private.media_object_key(url) = k)
      or exists (select 1 from public.order_item_snapshot_images where private.media_object_key(url) = k)
      or exists (select 1 from public.profiles where private.media_object_key(avatar_url) = k)
      or exists (select 1 from public.cars where private.media_object_key(cover_image_url) = k)
      or exists (select 1 from public.mod_items where private.media_object_key(image_url) = k)
      or exists (select 1 from public.car_hotspots where private.media_object_key(image_url) = k)
      or exists (select 1 from public.activity_posts where strpos(body::text, '/storage/v1/') > 0 and k = any(private.activity_body_media_keys(body)));
  end if;
  return exists (select 1 from public.car_images where private.media_object_key(url) = k)
    or exists (select 1 from public.listing_images where private.media_object_key(url) = k)
    or exists (select 1 from public.activity_images where private.media_object_key(url) = k)
    -- Purchase evidence (0049): the gallery frozen onto an order.
    or exists (select 1 from public.order_item_snapshot_images where private.media_object_key(url) = k)
    or exists (select 1 from public.profiles where private.media_object_key(avatar_url) = k)
    or exists (select 1 from public.cars where private.media_object_key(cover_image_url) = k)
    or exists (select 1 from public.mod_items where private.media_object_key(image_url) = k)
    or exists (select 1 from public.car_hotspots where private.media_object_key(image_url) = k)
    -- Dispute evidence is stored by bare path (0027); legacy rows by URL.
    or (p_bucket = 'dispute-evidence' and exists (
      select 1 from public.dispute_evidence de
       where de.storage_path = p_path or de.url = p_path or private.media_object_key(de.url) = k))
    -- Message photos are stored on the message by path (20260928140000).
    or (p_bucket = 'message-photos' and exists (
      select 1 from public.messages where attachments @> array[p_path]))
    -- Embedded references: the commercial snapshot and post bodies. Every
    -- URL string in them is canonicalised (an escaped spelling still names
    -- its object); the substring test also keeps any bare path.
    or exists (select 1 from public.order_items
                where position(p_path in commercial_snapshot::text) > 0
                   or (strpos(commercial_snapshot::text, '/storage/v1/') > 0 and k = any(private.json_media_keys(commercial_snapshot))))
    or exists (select 1 from public.activity_posts
                where position(p_path in body::text) > 0
                   or (strpos(body::text, '/storage/v1/') > 0 and k = any(private.json_media_keys(body))));
end;
$_$;


--
-- Name: merge_products(uuid[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_products(p_products uuid[], p_basis text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_keep uuid;
  v_gone uuid[];
begin
  -- Follow anything already merged to where it went, then lock in id order.
  select array_agg(distinct coalesce(p.merged_into, p.id)) into p_products
  from public.products p where p.id = any(p_products);
  perform 1 from public.products p where p.id = any(p_products) order by p.id for update;
  select p.id into v_keep from public.products p
  where p.id = any(p_products) and p.status = 'active' order by p.created_at, p.id limit 1;
  if v_keep is null then
    return null;
  end if;
  select array_agg(p.id) into v_gone from public.products p
  where p.id = any(p_products) and p.status = 'active' and p.id <> v_keep;
  if v_gone is null then
    return v_keep;
  end if;
  update public.product_part_numbers m
     set product_id = v_keep,
         basis = coalesce(p_basis, m.basis),
         verified_by = case when p_basis = 'verified' then p_actor else m.verified_by end
   where m.product_id = any(v_gone);
  update public.products set merged_into = v_keep, updated_at = now() where merged_into = any(v_gone);
  update public.products set status = 'merged', merged_into = v_keep, updated_at = now() where id = any(v_gone);
  update public.products set updated_at = now() where id = v_keep;
  return v_keep;
end;
$$;


--
-- Name: message_after_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_after_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.conversation_id is null then
    return old;
  end if;

  if old.read_at is null and old.kind = 'message' then
    update public.conversation_unreads
    set unread_count = greatest(unread_count - 1, 0)
    where conversation_id = old.conversation_id
      and user_id = old.recipient_id;
  end if;

  update public.conversations c
  set last_message_id = latest.id,
      last_message_at = latest.created_at,
      last_message_preview = latest.preview
  from (
    select null::uuid as id, null::timestamptz as created_at, null::text as preview
    where not exists (select 1 from public.messages where conversation_id = old.conversation_id)
    union all
    (select m.id, m.created_at,
            left(case when char_length(btrim(m.body)) = 0 then 'Photo' else m.body end, 140)
     from public.messages m
     where m.conversation_id = old.conversation_id
     order by m.created_at desc, m.id desc
     limit 1)
  ) latest
  where c.id = old.conversation_id
    and c.last_message_id = old.id;

  return old;
end;
$$;


--
-- Name: message_after_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.conversation_id is null then
    return new;
  end if;

  update public.conversations
  set last_message_id = new.id,
      last_message_at = new.created_at,
      last_message_preview = left(case when char_length(btrim(new.body)) = 0 then 'Photo' else new.body end, 140)
  where id = new.conversation_id;

  if new.read_at is null and new.kind = 'message' then
    insert into public.conversation_unreads (conversation_id, user_id, unread_count)
    values (new.conversation_id, new.recipient_id, 1)
    on conflict (conversation_id, user_id)
    do update set unread_count = public.conversation_unreads.unread_count + 1;
  end if;

  return new;
end;
$$;


--
-- Name: message_attach_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_attach_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversation_id uuid;
  v_lo uuid := least(new.sender_id, new.recipient_id);
  v_hi uuid := greatest(new.sender_id, new.recipient_id);
begin
  if new.order_id is null and new.offer_id is null and new.listing_id is null then
    return new;
  end if;

  insert into public.conversations (participant_a, participant_b)
  values (v_lo, v_hi)
  on conflict (participant_a, participant_b) do nothing;

  select id into v_conversation_id
  from public.conversations
  where participant_a = v_lo and participant_b = v_hi;

  new.conversation_id := v_conversation_id;
  return new;
end;
$$;


--
-- Name: message_read_decrement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_read_decrement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.conversation_id is not null
     and new.kind = 'message'
     and old.read_at is null
     and new.read_at is not null then
    update public.conversation_unreads
    set unread_count = greatest(unread_count - 1, 0)
    where conversation_id = new.conversation_id
      and user_id = new.recipient_id;
  end if;
  return new;
end;
$$;


--
-- Name: mod_purchase_sources(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_purchase_sources(p_order_item_ids uuid[]) RETURNS TABLE(order_item_id uuid, source_car_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select i.id,
         nullif(i.commercial_snapshot -> 'source_car' ->> 'id', '')::uuid
    from public.order_items i
   where i.id = any (p_order_item_ids)
     and exists (select 1 from public.mod_items m where m.source_order_item_id = i.id);
$$;


--
-- Name: mod_search_doc(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_search_doc(p_brand text, p_product text, p_part_number text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ select concat_ws(' ', p_brand, p_product, p_part_number) $$;


--
-- Name: mod_sheet_matches(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_sheet_matches(p_car uuid, p_items jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    (select count(*)
       from jsonb_array_elements(p_items) with ordinality as item(value, ordinality)
       join public.mod_items m on m.id = (item.value->>'id')::uuid and m.car_id = p_car
      where m.position = item.ordinality::integer - 1
        and m.group_label = coalesce(nullif(btrim(item.value->>'group_label'), ''), 'Other')
        and m.category is not distinct from nullif(item.value->>'category', '')
        and m.brand is not distinct from nullif(btrim(item.value->>'brand'), '')
        and m.product is not distinct from nullif(btrim(item.value->>'product'), '')
        and m.part_number is not distinct from nullif(btrim(item.value->>'part_number'), '')
        and m.raw_text is not distinct from nullif(btrim(item.value->>'raw_text'), '')
        and m.confidence is not distinct from (
              case when nullif(item.value->>'confidence', '') is null
                then null else (item.value->>'confidence')::real end)
        and m.status = coalesce(nullif(item.value->>'status', ''), 'installed')
        and m.product_url is not distinct from nullif(btrim(item.value->>'product_url'), '')
        and m.image_url is not distinct from nullif(btrim(item.value->>'image_url'), '')
        and m.source_domain is not distinct from nullif(btrim(item.value->>'source_domain'), '')
        and m.ref_price_cents is not distinct from (
              case when nullif(item.value->>'ref_price_cents', '') is null
                then null else (item.value->>'ref_price_cents')::integer end)
        and m.ref_price_currency is not distinct from nullif(btrim(item.value->>'ref_price_currency'), '')
        and m.origin = coalesce(nullif(item.value->>'origin', ''), m.origin)
    ) = jsonb_array_length(p_items)
    and not exists (
      select 1 from public.mod_items m
       where m.car_id = p_car
         and m.linked_listing_id is null
         and m.source_order_item_id is null
         and not exists (select 1 from jsonb_array_elements(p_items) item where (item->>'id')::uuid = m.id)
    );
$$;


--
-- Name: mod_sheet_revision(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_sheet_revision(p_car uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select md5(coalesce(string_agg(md5(m::text), ',' order by m.id), ''))
    from public.mod_items m
   where m.car_id = p_car;
$$;


--
-- Name: mod_sheet_revision_if_matches(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_sheet_revision_if_matches(p_car uuid, p_items jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when public.mod_sheet_matches(p_car, coalesce(p_items, '[]'::jsonb))
              then public.mod_sheet_revision(p_car) end;
$$;


--
-- Name: my_account_deletion_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_account_deletion_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when r.user_id is null then null else jsonb_build_object(
           'outcome', r.outcome,
           'next_action', r.next_action,
           'responsible_owner', r.responsible_owner,
           'updated_at', r.updated_at
         ) end
    from (select (select auth.uid()) as uid) me
    left join public.account_deletion_requests r on r.user_id = me.uid;
$$;


--
-- Name: my_car_vin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_car_vin(p_car uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.vin from public.cars c where c.id = p_car and c.owner_id = auth.uid();
$$;


--
-- Name: my_deal_listing_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_deal_listing_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select o.listing_id from public.offers o
   where o.buyer_id = (select auth.uid())
  union
  select oi.listing_id from public.order_items oi
    join public.orders ord on ord.id = oi.order_id
   where ord.buyer_id = (select auth.uid()) and oi.listing_id is not null;
$$;


--
-- Name: FUNCTION my_deal_listing_ids(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_deal_listing_ids() IS 'OS-W33: ids of listings the caller made an offer on or ordered, for the archived-listing read policies; ids only, the caller''s own; none for a visitor.';


--
-- Name: my_default_offer_floor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_default_offer_floor() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.default_offer_floor_pct::integer
    from public.profiles p
   where p.id = auth.uid();
$$;


--
-- Name: FUNCTION my_default_offer_floor(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_default_offer_floor() IS 'The caller''s own default lowest offer (P-9). The column has no client select grant: a floor a buyer can read is not a floor.';


--
-- Name: my_dispute_evidence_upload_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_dispute_evidence_upload_count(p_order uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_count int;
begin
  if v_uid is null then
    return 0;
  end if;
  -- Held to the end of the upload's transaction: a second upload into the
  -- same folder waits here until the first has committed (or failed), and
  -- the count below, a new statement with a new snapshot, then includes it.
  perform pg_advisory_xact_lock(
    hashtextextended('dispute-evidence-upload:' || v_uid::text || ':' || coalesce(p_order::text, ''), 0)
  );
  select count(*)::int into v_count
    from storage.objects o
   where o.bucket_id = 'dispute-evidence'
     and o.name like v_uid::text || '/' || p_order::text || '/%';
  return v_count;
end;
$$;


--
-- Name: FUNCTION my_dispute_evidence_upload_count(p_order uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_dispute_evidence_upload_count(p_order uuid) IS 'N247: the caller''s own files in one order''s dispute-evidence folder. Locks that folder for the transaction first, so the upload policy''s cap of 16 holds under concurrent uploads.';


--
-- Name: my_listing_enquiries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_listing_enquiries(p_others uuid[]) RETURNS TABLE(other_id uuid, listing_id uuid, last_at timestamp with time zone, title text, seller_id uuid, status text, price_cents integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with pairs as (
    select case when m.sender_id = (select auth.uid()) then m.recipient_id else m.sender_id end as other_id,
           m.listing_id, max(m.created_at) as last_at
      from public.messages m
     where (select auth.uid()) is not null
       and cardinality(p_others) <= 100
       and m.order_id is null and m.offer_id is null and m.listing_id is not null
       and ((m.sender_id = (select auth.uid()) and m.recipient_id = any (p_others))
         or (m.recipient_id = (select auth.uid()) and m.sender_id = any (p_others)))
     group by 1, 2
  )
  select p.other_id, p.listing_id, p.last_at, l.title, l.seller_id, l.status::text, l.price_cents
    from pairs p
    join public.listings l on l.id = p.listing_id
   where l.seller_id in ((select auth.uid()), p.other_id)
   order by p.last_at desc, p.listing_id
   limit 1000;
$$;


