--

CREATE FUNCTION public.not_received_refund_due(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select private.not_received_refund_due(p_order); $$;


--
-- Name: not_received_refunds_due(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.not_received_refunds_due(p_limit integer DEFAULT 10) RETURNS TABLE(order_id uuid, disputed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select o.id, o.disputed_at
    from public.orders o
   where o.status = 'disputed'
     and o.dispute_category = 'item_not_received'
     and o.dispute_escalated_at is not null
     and coalesce(o.dispute_respond_by, o.disputed_at) <= now()
     and private.not_received_refund_due(o.id)
   order by o.dispute_respond_by nulls first, o.id
   limit least(greatest(coalesce(p_limit, 10), 1), 50);
$$;


--
-- Name: notification_href_target(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_href_target(p_href text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  uuid_re constant text := '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}';
  v_found text;
  v_id uuid;
begin
  if p_href is null then
    return null;
  end if;
  v_found := coalesce(
    substring(p_href from '^/posts/(' || uuid_re || ')(?:[/?#]|$)'),
    substring(p_href from '^/cars/[^/?#]+/activity/(' || uuid_re || ')(?:[/?#]|$)'),
    substring(p_href from '^/listings/(' || uuid_re || ')(?:[/?#]|$)')
  );
  if v_found is not null then
    return v_found::uuid;
  end if;
  v_found := substring(p_href from '^/cars/([^/?#]+)/?(?:[?#]|$)');
  if v_found is not null then
    select c.id into v_id from public.cars c where c.slug = v_found;
    return v_id;
  end if;
  v_found := substring(p_href from '^/u/([^/?#]+)/?(?:[?#]|$)');
  if v_found is not null then
    select p.id into v_id from public.profiles p where p.username = v_found;
    return v_id;
  end if;
  return null;
end;
$_$;


--
-- Name: notification_set_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_set_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if (tg_op = 'INSERT' and new.target_id is null)
     or (tg_op = 'UPDATE' and new.href is distinct from old.href) then
    new.target_id := public.notification_href_target(new.href);
  end if;
  return new;
end;
$$;


--
-- Name: notify(uuid, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify(p_user_id uuid, p_kind text, p_section text, p_title text, p_body text DEFAULT NULL::text, p_href text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Never notify someone about their own action.
  if p_user_id is null or p_user_id = p_actor_id then
    return;
  end if;

  insert into public.notifications (user_id, kind, section, title, body, href, actor_id)
  values (p_user_id, p_kind, p_section, p_title, p_body, p_href, p_actor_id);
end;
$$;


