--
-- Name: notify_on_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seller uuid;
  v_title text;
begin
  -- An attempt declined at once (below the minimum) isn't news (20261017160000).
  if new.status <> 'open' then return new; end if;
  select l.seller_id, l.title into v_seller, v_title
  from public.listings l where l.id = new.listing_id;

  perform public.notify(
    v_seller, 'offer_new', 'marketplace',
    'New offer on ' || v_title,
    to_char(new.amount_cents / 100.0, 'FM999,999,990.00'),
    '/offers/' || new.id, new.buyer_id
  );
  return new;
end;
$$;


--
-- Name: notify_on_offer_response(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_offer_response() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seller uuid;
  v_listing_title text;
  v_order uuid;
  v_agent_counter boolean;
begin
  if new.status = old.status then
    return new;
  end if;

  select l.seller_id, l.title into v_seller, v_listing_title
  from public.listings l where l.id = new.listing_id;

  -- Buyer-facing outcomes. A seller's acceptance is announced by the app,
  -- with the checkout link the buyer needs.
  if new.status in ('declined', 'countered') then
    perform public.notify(
      new.buyer_id, 'offer_' || new.status, 'marketplace',
      case new.status
        when 'declined' then 'Your offer was declined'
        else 'The seller countered your offer'
      end,
      v_listing_title, '/offers/' || new.id, v_seller
    );
  end if;

  -- Seller-facing: the buyer took the seller's counter. When the counter
  -- was the seller's agent's (A3a), it is a deal the agent reached: the
  -- notice opens the offer, where Cancel before checkout lives.
  if new.status = 'accepted' and new.counter_amount_cents is not null then
    select o.id into v_order from public.orders o where o.origin_offer_id = new.id;
    select r.actor_task_id is not null into v_agent_counter
    from public.offer_rounds r
    where r.offer_id = new.id and r.actor_role = 'seller' and r.kind = 'counter'
    order by r.round_no desc limit 1;
    if coalesce(v_agent_counter, false) then
      perform public.notify(
        v_seller, 'offer_agent_deal_reached', 'marketplace',
        'Deal reached: the buyer accepted your agent''s counter', v_listing_title,
        '/offers/' || new.id, new.buyer_id
      );
    else
      perform public.notify(
        v_seller, 'offer_counter_accepted', 'marketplace',
        'Your counter was accepted', v_listing_title,
        coalesce('/orders/' || v_order, '/offers/' || new.id), new.buyer_id
      );
    end if;
  end if;

  -- Seller-facing: the buyer countered back (negotiation v2).
  if new.status = 'open' and old.status = 'countered' then
    perform public.notify(
      v_seller, 'offer_countered_back', 'marketplace',
      'The buyer countered your offer', v_listing_title, '/offers/' || new.id, new.buyer_id
    );
  end if;

  -- Both sides: the turn ran out (20261017160000).
  if new.status = 'expired' then
    perform public.notify(
      new.buyer_id, 'offer_expired', 'marketplace',
      'Your offer expired', v_listing_title, '/offers/' || new.id, null
    );
    perform public.notify(
      v_seller, 'offer_expired', 'marketplace',
      'An offer expired', v_listing_title, '/offers/' || new.id, null
    );
  end if;

  -- Seller-facing: the buyer walked away.
  if new.status = 'withdrawn' then
    perform public.notify(
      v_seller, 'offer_withdrawn', 'marketplace',
      'An offer was withdrawn', v_listing_title, '/offers/' || new.id, new.buyer_id
    );
  end if;

  return new;
end;
$$;


--
-- Name: notify_on_order_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_order_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = old.status then
    return new;
  end if;

  if new.status = 'disputed' then
    perform public.notify(
      new.seller_id, 'order_disputed', 'marketplace',
      'A buyer opened a dispute',
      coalesce(new.dispute_reason, 'See the order for details'),
      '/orders/' || new.id, new.disputed_by
    );
  elsif old.status = 'disputed' and new.status <> 'refunded' then
    -- Resolved without a full refund: buyer closed it, or a partial refund
    -- was accepted and the order settled back to pre_dispute_status. The
    -- order/payment rows themselves carry whether money moved, so the
    -- notification just points both parties back at the order.
    perform public.notify(
      new.buyer_id, 'dispute_resolved', 'marketplace',
      'Dispute resolved', 'The order is settled', '/orders/' || new.id, null
    );
    perform public.notify(
      new.seller_id, 'dispute_resolved', 'marketplace',
      'Dispute resolved', 'The order is settled', '/orders/' || new.id, null
    );
  elsif new.status = 'paid' then
    perform public.notify(
      new.seller_id, 'order_sold', 'marketplace',
      'You made a sale',
      'Order ' || left(new.id::text, 8) || ' — dispatch when ready',
      '/orders/' || new.id, new.buyer_id
    );
    perform public.notify(
      new.buyer_id, 'order_paid', 'marketplace',
      'Payment confirmed', 'Your order is with the seller',
      '/orders/' || new.id, new.seller_id
    );
  elsif new.status = 'shipped' then
    perform public.notify(
      new.buyer_id, 'order_shipped', 'marketplace',
      'Your part is on its way',
      coalesce(new.carrier || ' · ' || new.tracking_number, 'Dispatched'),
      '/orders/' || new.id, new.seller_id
    );
  elsif new.status = 'delivered' then
    perform public.notify(
      new.seller_id, 'order_delivered', 'marketplace',
      'Delivery confirmed',
      case when current_setting('drvn.delivery_source', true) = 'auto_confirm'
        then 'No problem was reported in time, so the order was marked delivered'
        else 'The buyer marked the order received' end,
      '/orders/' || new.id, new.buyer_id
    );
  elsif new.status in ('cancelled', 'refunded', 'payment_failed') then
    perform public.notify(
      new.buyer_id, 'order_' || new.status, 'marketplace',
      'Order ' || replace(new.status, '_', ' '),
      coalesce(new.cancel_reason, null), '/orders/' || new.id, null
    );
    perform public.notify(
      new.seller_id, 'order_' || new.status, 'marketplace',
      'Order ' || replace(new.status, '_', ' '),
      coalesce(new.cancel_reason, null), '/orders/' || new.id, null
    );
  end if;

  return new;
end;
$$;


--
-- Name: notify_on_question(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_question() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seller uuid;
  v_title text;
begin
  select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;

  -- A reply notifies the person being replied to; a new question notifies the
  -- seller. Without this, sellers never learned a question had been asked.
  if new.parent_id is not null then
    select q.author_id into v_seller
    from public.listing_questions q where q.id = new.parent_id;
    v_title := public.actor_name(new.author_id) || ' answered your question';
  else
    v_title := public.actor_name(new.author_id) || ' asked about your part';
  end if;

  perform public.notify(
    v_seller, 'question', 'marketplace', v_title,
    left(new.body, 140), '/listings/' || new.listing_id, new.author_id
  );
  return new;
end;
$$;


--
-- Name: notify_on_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.notify(
    new.reviewee_id, 'review', 'engagement',
    public.actor_name(new.reviewer_id) || ' left you a ' || new.rating || '-star review',
    left(coalesce(new.body, ''), 140), '/orders/' || new.order_id, new.reviewer_id
  );
  return new;
end;
$$;


--
-- Name: notify_on_save(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_save() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_owner uuid;
  v_href text;
  v_title text;
  v_kind text := 'save';
  -- A saved *part* is market interest, not someone admiring your build. The PRD
  -- keeps the two columns separate, and the two have different preferences.
  v_section text := 'engagement';
begin
  if new.target_type = 'car' then
    select c.owner_id, '/cars/' || c.slug into v_owner, v_href
    from public.cars c where c.id = new.target_id;
    v_title := public.actor_name(new.user_id) || ' saved your build';
  elsif new.target_type = 'listing' then
    select l.seller_id, '/listings/' || l.id into v_owner, v_href
    from public.listings l where l.id = new.target_id;
    v_title := public.actor_name(new.user_id) || ' saved your part';
    v_kind := 'listing_save';
    v_section := 'marketplace';
  elsif new.target_type = 'post' then
    select p.author_id, public.post_href(p.id)
      into v_owner, v_href
    from public.activity_posts p
    where p.id = new.target_id;
    v_title := public.actor_name(new.user_id) || ' saved your update';
  elsif new.target_type = 'profile' then
    v_owner := new.target_id;
    v_title := public.actor_name(new.user_id) || ' saved your profile';
    select '/u/' || username into v_href from public.profiles where id = new.user_id;
  end if;

  -- Unknown target or vanished owner: the save still stands, silently.
  if v_owner is not null then
    perform public.notify(v_owner, v_kind, v_section, v_title, null, v_href, new.user_id);
  end if;
  return new;
end;
$$;


--
-- Name: offer_accept_begin(uuid, uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_accept_begin(p_offer_id uuid, p_seller_id uuid, p_reservation_window interval DEFAULT '24:00:00'::interval) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_offer record;
  v_listing record;
  v_price int;
  v_fee int;
  v_order_id uuid;
  v_shipping int;
begin
  select o.id, o.listing_id, o.buyer_id, o.amount_cents, o.counter_amount_cents,
         o.status, o.expires_at
  into v_offer
  from public.offers o
  where o.id = p_offer_id
  for update;

  if not found or v_offer.status not in ('open', 'countered') then
    return null;
  end if;

  if v_offer.expires_at is not null and v_offer.expires_at < now() then
    update public.offers
    set status = 'expired', responded_at = now()
    where id = p_offer_id;
    return null;
  end if;

  v_price := coalesce(v_offer.counter_amount_cents, v_offer.amount_cents);

  select l.shipping_cents into v_shipping
  from public.listings l
  where l.id = v_offer.listing_id and l.seller_id = p_seller_id and l.status = 'active';
  if found and not public.charge_cents_in_bounds(v_price::bigint + v_shipping::bigint) then
    raise exception 'An accepted offer must come to between $0.50 and $999,999.99 with shipping'
      using errcode = '22003';
  end if;

  update public.listings l
  set status = 'reserved', reserved_until = now() + p_reservation_window
  where l.id = v_offer.listing_id
    and l.seller_id = p_seller_id
    and l.status = 'active'
  returning l.id, l.title, l.shipping_cents, l.currency
  into v_listing;

  if not found then
    return null;
  end if;

  -- Fee basis is everything the buyer pays before tax: goods + shipping
  -- (0050). An accepted offer cannot dodge the fee through shipping either.
  v_fee := round((v_price + v_listing.shipping_cents) * 1000.0 / 10000.0);

  insert into public.orders (
    buyer_id, seller_id, status,
    subtotal_cents, shipping_cents, platform_fee_cents, total_cents, currency,
    origin_offer_id
  )
  values (
    v_offer.buyer_id, p_seller_id, 'pending',
    v_price, v_listing.shipping_cents, v_fee,
    v_price + v_listing.shipping_cents, v_listing.currency,
    p_offer_id
  )
  returning id into v_order_id;

  insert into public.order_items (order_id, listing_id, title, price_cents, shipping_cents)
  values (v_order_id, v_listing.id, v_listing.title, v_price, v_listing.shipping_cents);

  insert into public.payments (order_id, amount_cents, currency, status, idempotency_key)
  values (
    v_order_id,
    v_price + v_listing.shipping_cents,
    v_listing.currency,
    'pending',
    'offer:' || p_offer_id::text || ':' || v_order_id::text
  );

  update public.offers
  set status = 'accepted', responded_at = now()
  where id = p_offer_id;

  return v_order_id;
end;
$_$;


--
-- Name: offer_effective_floor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_effective_floor(p_listing uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(
    (select t.offer_floor_cents from public.listing_private_terms t where t.listing_id = p_listing),
    (select max(m.minimum_cents) from public.agent_mandates m
      where m.listing_id = p_listing and m.scope = 'seller' and m.status = 'active'
        and (m.expires_at is null or m.expires_at > now())
        and m.owner_id = (select l.seller_id from public.listings l where l.id = p_listing))
  );
$$;


--
-- Name: offer_move(uuid, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_move(p_offer uuid, p_kind text, p_amount integer, p_idempotency_key text, p_expected_round integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  return public.offer_move_core(auth.uid(), p_offer, p_kind, p_amount, p_idempotency_key, p_expected_round, null);
end;
$$;


--
-- Name: offer_move_core(uuid, uuid, text, integer, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_move_core(p_actor uuid, p_offer uuid, p_kind text, p_amount integer, p_idempotency_key text, p_expected_round integer, p_agent jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := p_actor; -- A2: the caller passes the actor
  v_prior public.offer_rounds;
  v_listing_id uuid;
  v_listing public.listings;
  v_offer public.offers;
  v_role text;
  v_turn text;
  v_floor integer;
  v_used integer;
  v_no integer;
  v_round uuid;
  v_kind text := p_kind;
  v_amount integer;
  v_expires timestamptz;
  v_order uuid;
  -- A2: the agent's authority, recorded on the round
  v_task uuid := (p_agent->>'task_id')::uuid;
  v_job uuid := (p_agent->>'job_id')::uuid;
  v_version integer := (p_agent->>'mandate_version')::integer;
  v_ceiling integer := (p_agent->>'ceiling_cents')::integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_offer is null or p_kind is null or p_kind not in ('counter', 'accept', 'decline', 'withdraw')
     or p_idempotency_key is null or length(p_idempotency_key) not between 8 and 200
     or (p_kind = 'counter' and (p_amount is null or p_amount <= 0 or p_amount > 100000000)) then
    raise exception 'Invalid offer move' using errcode = '22023';
  end if;

  -- An exact retry replays the move it already made.
  select * into v_prior from public.offer_rounds where actor_member_id = v_actor and idempotency_key = p_idempotency_key;
  if found then
    if v_prior.offer_id <> p_offer then raise exception 'Move retry identity changed' using errcode = '23505'; end if;
    return jsonb_build_object('offer_id', p_offer, 'round_no', v_prior.round_no, 'kind', v_prior.kind, 'replayed', true,
      'order_id', (select o.id from public.orders o where o.origin_offer_id = p_offer and v_prior.kind = 'accept'));
  end if;

  select o.listing_id into v_listing_id from public.offers o where o.id = p_offer;
  if not found then raise exception 'Offer not found' using errcode = 'P0002'; end if;
  perform set_config('drvn.offer_move', 'on', true);
  select * into v_listing from public.listings where id = v_listing_id for update;
  select * into v_offer from public.offers where id = p_offer for update;
  v_role := case when v_offer.buyer_id = v_actor then 'buyer' when v_listing.seller_id = v_actor then 'seller' end;
  if v_role is null then raise exception 'Offer not found' using errcode = 'P0002'; end if;
  if public.is_suspended(v_actor) then raise exception 'account is suspended' using errcode = '42501'; end if;
  if v_offer.status not in ('open', 'countered') then raise exception 'This offer is already settled' using errcode = 'OF005'; end if;
  if v_offer.round_count is distinct from p_expected_round then
    raise exception 'This offer changed; reload it' using errcode = 'OF003';
  end if;

  v_no := v_offer.round_count + 1;
  -- The turn ran out: record the expiry and say so (it commits).
  if v_offer.expires_at is not null and v_offer.expires_at < now() then
    update public.offers set status = 'expired', responded_at = now() where id = p_offer;
    insert into public.offer_rounds(offer_id, round_no, listing_id, buyer_id, actor_role, kind)
    values (p_offer, v_no, v_listing.id, v_offer.buyer_id, 'system', 'expire') returning id into v_round;
    update public.offers set round_count = v_no, last_round_id = v_round where id = p_offer;
    perform set_config('drvn.offer_move', '', true);
    return jsonb_build_object('offer_id', p_offer, 'round_no', v_no, 'kind', 'expire', 'outcome', 'expired', 'replayed', false);
  end if;

  v_turn := case v_offer.status when 'open' then 'seller' else 'buyer' end;

  if p_kind = 'withdraw' then
    if v_role <> 'buyer' then raise exception 'Only the buyer can withdraw' using errcode = '42501'; end if;
    update public.offers set status = 'withdrawn', responded_at = now() where id = p_offer;
  elsif p_kind = 'decline' then
    if v_role <> 'seller' then raise exception 'Only the seller can decline' using errcode = '42501'; end if;
    update public.offers set status = 'declined', responded_at = now() where id = p_offer;
  elsif p_kind = 'accept' then
    if v_role <> v_turn then raise exception 'It''s not your turn' using errcode = 'OF002'; end if;
    v_amount := case v_role when 'seller' then v_offer.amount_cents else v_offer.counter_amount_cents end;
    -- Under the listing and offer locks taken above; it locks nothing new
    -- before the order it creates.
    v_order := public.offer_accept_begin(p_offer, v_listing.seller_id);
    if v_order is null then raise exception 'This part is no longer available' using errcode = 'OF007'; end if;
  else
    if v_role <> v_turn then raise exception 'It''s not your turn' using errcode = 'OF002'; end if;
    if not public.consume_rate_limit('offer-move:' || v_actor, 30, interval '10 minutes') then
      raise exception 'Too many offer moves; try again shortly' using errcode = 'OF009';
    end if;
    v_floor := public.offer_effective_floor(v_listing.id);
    v_amount := p_amount;
    v_expires := now() + interval '72 hours';
    if v_role = 'seller' then
      if p_amount <= v_offer.amount_cents or p_amount > v_listing.price_cents or (v_floor is not null and p_amount < v_floor) then
        raise exception 'A counter must be above the offer, no more than the asking price and no less than your minimum' using errcode = 'OF004';
      end if;
      update public.offers set status = 'countered', counter_amount_cents = p_amount, countered_at = now(), expires_at = v_expires
      where id = p_offer;
    else
      if p_amount <= v_offer.amount_cents or p_amount >= v_offer.counter_amount_cents then
        raise exception 'A counter-offer must be above your last offer and below the seller''s counter' using errcode = 'OF004';
      end if;
      select count(*) into v_used from public.offer_rounds r
      where r.listing_id = v_listing.id and r.buyer_id = v_actor and r.actor_role = 'buyer' and r.kind in ('offer', 'counter', 'below_minimum');
      if v_used >= 3 then raise exception 'No offers left on this part' using errcode = 'OF001'; end if;
      if v_floor is not null and p_amount < v_floor then
        v_kind := 'below_minimum';
        v_expires := null;
        update public.offers set status = 'declined', amount_cents = p_amount, counter_amount_cents = null, responded_at = now()
        where id = p_offer;
      else
        update public.offers set status = 'open', amount_cents = p_amount, counter_amount_cents = null, countered_at = null, expires_at = v_expires
        where id = p_offer;
      end if;
    end if;
  end if;

  insert into public.offer_rounds(offer_id, round_no, listing_id, buyer_id, actor_role, kind, amount_cents, expires_at, actor_member_id, idempotency_key,
    actor_task_id, actor_job_id, mandate_version)
  values (p_offer, v_no, v_listing.id, v_offer.buyer_id, v_role, v_kind, v_amount,
          case when v_kind = 'counter' then v_expires end, v_actor, p_idempotency_key,
          v_task, v_job, v_version)
  returning id into v_round;
  if v_kind in ('counter', 'below_minimum') then
    insert into public.offer_round_terms(round_id, effective_floor_cents, buyer_ceiling_cents) values (v_round, v_floor, v_ceiling);
  end if;
  update public.offers set round_count = v_no, last_round_id = v_round where id = p_offer;
  perform set_config('drvn.offer_move', '', true);
  return jsonb_build_object('offer_id', p_offer, 'round_no', v_no, 'kind', v_kind, 'replayed', false,
    'outcome', case when v_kind = 'below_minimum' then 'below_minimum' else 'done' end, 'order_id', v_order);
end;
$$;


--
-- Name: offer_open(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_open(p_offer uuid, p_listing uuid, p_amount integer, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  return public.offer_open_core(auth.uid(), p_offer, p_listing, p_amount, p_message, null);
end;
$$;


--
-- Name: offer_open_core(uuid, uuid, uuid, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_open_core(p_actor uuid, p_offer uuid, p_listing uuid, p_amount integer, p_message text DEFAULT NULL::text, p_agent jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := p_actor; -- A2: the caller passes the actor
  v_listing public.listings;
  v_existing public.offers;
  v_first public.offer_rounds;
  v_opening public.messages;
  v_floor integer;
  v_used integer;
  v_round uuid;
  -- A2: the agent's authority, recorded on the round
  v_task uuid := (p_agent->>'task_id')::uuid;
  v_job uuid := (p_agent->>'job_id')::uuid;
  v_version integer := (p_agent->>'mandate_version')::integer;
  v_ceiling integer := (p_agent->>'ceiling_cents')::integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_offer is null or p_listing is null or p_amount is null or p_amount <= 0 or p_amount > 100000000 then
    raise exception 'Invalid offer request' using errcode = '22023';
  end if;
  if p_message is not null and (p_message = '' or p_message <> btrim(p_message) or length(p_message) > 2000) then
    raise exception 'Invalid offer message' using errcode = '22023';
  end if;

  -- An exact retry of a committed opening offer replays it.
  select * into v_existing from public.offers where id = p_offer;
  if found then
    select * into v_first from public.offer_rounds where offer_id = p_offer and round_no = 1;
    if v_existing.buyer_id <> v_actor or v_existing.listing_id <> p_listing
       or v_first.amount_cents is distinct from p_amount then
      raise exception 'Offer retry identity changed' using errcode = '23505';
    end if;
    if v_first.kind = 'offer' then
      select * into v_opening from public.messages where id = p_offer;
      if (p_message is null) is distinct from (not found)
         or (found and (v_opening.sender_id <> v_actor or v_opening.body <> p_message)) then
        raise exception 'Offer retry message changed' using errcode = '23505';
      end if;
    end if;
    return jsonb_build_object('offer_id', p_offer, 'replayed', true,
      'outcome', case when v_first.kind = 'below_minimum' then 'below_minimum' else 'sent' end);
  end if;

  perform set_config('drvn.offer_move', 'on', true);
  select * into v_listing from public.listings where id = p_listing for update;
  if not found or v_listing.status <> 'active' then raise exception 'Listing is not available' using errcode = 'OF007'; end if;
  if v_listing.seller_id = v_actor then raise exception 'You can''t offer on your own listing' using errcode = '42501'; end if;
  if public.is_suspended(v_actor) then raise exception 'account is suspended' using errcode = '42501'; end if;
  if v_listing.shipping_mode = 'drvn' then raise exception 'Offers are unavailable with rated shipping' using errcode = 'OF007'; end if;
  if p_amount > v_listing.price_cents then raise exception 'An offer can''t be above the asking price' using errcode = 'OF004'; end if;
  if exists (select 1 from public.offers o where o.listing_id = p_listing and o.buyer_id = v_actor and o.status in ('open', 'countered')) then
    raise exception 'You already have a live offer on this part' using errcode = '23505';
  end if;
  select count(*) into v_used from public.offer_rounds r
  where r.listing_id = p_listing and r.buyer_id = v_actor and r.actor_role = 'buyer' and r.kind in ('offer', 'counter', 'below_minimum');
  if v_used >= 3 then raise exception 'No offers left on this part' using errcode = 'OF001'; end if;
  if not public.consume_rate_limit('offer-move:' || v_actor, 30, interval '10 minutes') then
    raise exception 'Too many offer moves; try again shortly' using errcode = 'OF009';
  end if;

  v_floor := public.offer_effective_floor(p_listing);
  if v_floor is not null and p_amount < v_floor then
    -- Declined at once, and it uses one of the buyer's 3. Nothing says why.
    insert into public.offers(id, listing_id, buyer_id, amount_cents, status, responded_at)
    values (p_offer, p_listing, v_actor, p_amount, 'declined', now());
    insert into public.offer_rounds(offer_id, round_no, listing_id, buyer_id, actor_role, kind, amount_cents, actor_member_id, idempotency_key,
      actor_task_id, actor_job_id, mandate_version)
    values (p_offer, 1, p_listing, v_actor, 'buyer', 'below_minimum', p_amount, v_actor, 'open:' || p_offer,
      v_task, v_job, v_version)
    returning id into v_round;
    insert into public.offer_round_terms(round_id, effective_floor_cents, buyer_ceiling_cents) values (v_round, v_floor, v_ceiling);
    update public.offers set round_count = 1, last_round_id = v_round where id = p_offer;
    perform set_config('drvn.offer_move', '', true);
    return jsonb_build_object('offer_id', p_offer, 'replayed', false, 'outcome', 'below_minimum');
  end if;

  insert into public.offers(id, listing_id, buyer_id, amount_cents, status, expires_at)
  values (p_offer, p_listing, v_actor, p_amount, 'open', now() + interval '72 hours');
  if p_message is not null then
    insert into public.messages(id, listing_id, offer_id, order_id, sender_id, recipient_id, body)
    values (p_offer, p_listing, p_offer, null, v_actor, v_listing.seller_id, p_message);
  end if;
  insert into public.offer_rounds(offer_id, round_no, listing_id, buyer_id, actor_role, kind, amount_cents, expires_at, actor_member_id, idempotency_key,
    actor_task_id, actor_job_id, mandate_version)
  values (p_offer, 1, p_listing, v_actor, 'buyer', 'offer', p_amount, now() + interval '72 hours', v_actor, 'open:' || p_offer,
    v_task, v_job, v_version)
  returning id into v_round;
  insert into public.offer_round_terms(round_id, effective_floor_cents, buyer_ceiling_cents) values (v_round, v_floor, v_ceiling);
  update public.offers set round_count = 1, last_round_id = v_round where id = p_offer;
  perform set_config('drvn.offer_move', '', true);
  return jsonb_build_object('offer_id', p_offer, 'replayed', false, 'outcome', 'sent');
end;
$$;


--
-- Name: open_order_dispute(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_order_dispute(p_order uuid, p_buyer uuid, p_category text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  v_anchor timestamptz;
  v_closes timestamptz;
  v_now timestamptz := now();
  v_reason text := nullif(left(btrim(coalesce(p_reason, '')), 1000), '');
begin
  if p_order is null or p_buyer is null then raise exception 'Order and buyer are required'; end if;
  if p_category is null or p_category not in (
       'item_not_received', 'item_not_as_described', 'damaged_in_transit', 'wrong_item',
       'counterfeit', 'does_not_fit', 'other') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_category');
  end if;

  select * into o from public.orders where id = p_order for update;
  if not found or o.buyer_id is distinct from p_buyer then
    return jsonb_build_object('ok', false, 'reason', 'not_your_order');
  end if;
  if o.status = 'disputed' then return jsonb_build_object('ok', false, 'reason', 'already_open'); end if;
  if exists (select 1 from public.order_dispute_history h
              where h.order_id = o.id and h.event = 'resolved' and h.kind = 'in_app') then
    return jsonb_build_object('ok', false, 'reason', 'resolved_final');
  end if;
  if o.seller_id is null then return jsonb_build_object('ok', false, 'reason', 'seller_gone'); end if;
  if private.order_has_unresolved_chargeback(o.id) then
    return jsonb_build_object('ok', false, 'reason', 'chargeback_open');
  end if;

  if p_category = 'item_not_received' then
    if o.is_collection then
      if o.status <> 'paid' then return jsonb_build_object('ok', false, 'reason', 'wrong_stage'); end if;
      v_anchor := o.available_by;
    elsif o.status in ('paid', 'shipped') then
      v_anchor := coalesce(o.delivered_at, o.deliver_by);
    elsif o.status = 'delivered' and exists (
      -- "Tracking says delivered, but it never came": only a carrier
      -- delivery, not the buyer's own confirmation.
      select 1 from public.shipments s
       where s.order_id = o.id and s.direction = 'outbound' and s.status = 'delivered'
    ) then
      v_anchor := coalesce(o.delivered_at, o.deliver_by);
    else
      return jsonb_build_object('ok', false, 'reason', 'wrong_stage');
    end if;
    if v_anchor is null then return jsonb_build_object('ok', false, 'reason', 'no_deadline'); end if;
    v_closes := v_anchor + interval '30 days';
    if v_now < v_anchor then
      return jsonb_build_object('ok', false, 'reason', 'too_early', 'opens_at', v_anchor);
    end if;
    if v_now > v_closes then
      return jsonb_build_object('ok', false, 'reason', 'window_closed', 'closed_at', v_closes);
    end if;
  else
    if o.status not in ('shipped', 'delivered', 'completed') then
      return jsonb_build_object('ok', false, 'reason', 'wrong_stage');
    end if;
    if o.delivered_at is not null and v_now > o.delivered_at + interval '30 days' then
      return jsonb_build_object('ok', false, 'reason', 'window_closed', 'closed_at', o.delivered_at + interval '30 days');
    end if;
  end if;

  update public.orders set
    status = 'disputed',
    pre_dispute_status = o.status,
    dispute_category = p_category,
    dispute_reason = v_reason,
    disputed_at = v_now,
    disputed_by = p_buyer,
    dispute_respond_by = private.add_business_days(v_now, 3),
    dispute_escalate_until = private.add_business_days(v_now, 21),
    dispute_escalated_at = null,
    dispute_escalated_by = null,
    dispute_sla_alerted_at = null,
    dispute_resolved_at = null,
    dispute_outcome = null,
    refund_offer_cents = null,
    refund_offered_at = null
  where id = o.id;

  return jsonb_build_object(
    'ok', true,
    'respond_by', private.add_business_days(v_now, 3),
    'escalate_until', private.add_business_days(v_now, 21)
  );
end $$;


--
-- Name: open_seller_carry_payouts(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_seller_carry_payouts(p_quiet_hours integer DEFAULT 24, p_limit integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_candidate record;
  v_balance int;
  v_latest timestamptz;
  v_payout uuid;
  v_opened int := 0;
  v_quiet interval := make_interval(hours => greatest(coalesce(p_quiet_hours, 24), 0));
begin
  for v_candidate in
    select e.seller_id
      from public.seller_carry_entries e
     where e.seller_id is not null
     group by e.seller_id
    having sum(e.amount_cents) > 0 and max(e.created_at) <= now() - v_quiet
     order by max(e.created_at)
     limit greatest(1, least(coalesce(p_limit, 50), 500))
  loop
    -- The lock every writer and every transfer's freeze takes: the balance
    -- read below can't change until this transaction commits.
    perform pg_advisory_xact_lock(hashtextextended('seller-carry:' || v_candidate.seller_id::text, 0));
    select coalesce(sum(amount_cents), 0)::int, max(created_at) into v_balance, v_latest
      from public.seller_carry_entries where seller_id = v_candidate.seller_id;
    continue when v_balance <= 0 or v_latest > now() - v_quiet;
    continue when exists (
      select 1 from public.seller_carry_payouts
       where seller_id = v_candidate.seller_id and status in ('pending', 'processing', 'failed'));

    insert into public.seller_carry_payouts (seller_id, amount_cents)
    values (v_candidate.seller_id, v_balance)
    returning id into v_payout;
    perform public.record_seller_carry(
      v_candidate.seller_id, 'paid_out', -v_balance, null, null, 'paid-out:' || v_payout::text);
    v_opened := v_opened + 1;
  end loop;
  return v_opened;
end;
$$;


--
-- Name: ops_case_on_dispute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_case_on_dispute() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.disputed_at is not null and (old.disputed_at is distinct from new.disputed_at) then
    insert into public.ops_cases (kind, order_id, summary, priority)
    values (
      'dispute', new.id,
      coalesce(new.dispute_category::text, 'dispute'),
      case when new.total_cents >= 50000 then 'high' else 'normal' end
    )
    on conflict (order_id) where order_id is not null do update
      set status = case when public.ops_cases.status = 'resolved' then 'open' else public.ops_cases.status end,
          resolved_at = null,
          updated_at = now();
  end if;
  if new.dispute_resolved_at is not null and (old.dispute_resolved_at is distinct from new.dispute_resolved_at) then
    update public.ops_cases
    set status = 'resolved', resolved_at = new.dispute_resolved_at, updated_at = now()
    where order_id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: ops_case_on_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_case_on_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.ops_cases (kind, report_id, summary)
    values ('report', new.id, coalesce(new.reason::text, 'report'))
    on conflict (report_id) where report_id is not null do nothing;
  elsif tg_op = 'UPDATE' and new.status is distinct from old.status then
    if new.status in ('actioned', 'dismissed') then
      update public.ops_cases
      set status = 'resolved', resolved_at = now(), updated_at = now()
      where report_id = new.id;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: order_buyer_reviewable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_buyer_reviewable(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select not exists (select 1 from private.unproven_buyer_orders p where p.order_id = o.id)
  from public.orders o
  where o.id = p_order and auth.uid() in (o.buyer_id, o.seller_id);
$$;


--
-- Name: order_close_dispute(uuid, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_close_dispute(p_order uuid, p_outcome text, p_resolved_at timestamp with time zone, p_buyer uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  restored text;
begin
  if p_order is null or p_resolved_at is null then
    raise exception 'An order and the time the dispute closed are required';
  end if;
  if p_outcome is null or p_outcome not in ('closed_by_buyer', 'admin_resolved') then
    raise exception 'A dispute closes without a refund as closed_by_buyer or admin_resolved, not %', coalesce(p_outcome, 'null');
  end if;
  if (p_outcome = 'closed_by_buyer') <> (p_buyer is not null) then
    raise exception 'closed_by_buyer needs the buyer, and admin_resolved must not name one';
  end if;

  update public.orders
     set status = coalesce(pre_dispute_status, 'delivered'),
         dispute_resolved_at = p_resolved_at,
         dispute_outcome = p_outcome,
         refund_offer_cents = null,
         refund_offered_at = null
   where id = p_order
     and status = 'disputed'
     and (p_buyer is null or buyer_id = p_buyer)
  returning status into restored;
  return restored;
end $$;


--
-- Name: order_has_valid_tracking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_has_valid_tracking(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select private.order_has_valid_tracking(p_order); $$;


--
-- Name: order_mark_delivered_from_tracking(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_mark_delivered_from_tracking(p_order uuid, p_delivered_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  moved uuid;
  current_status text;
begin
  if p_order is null or p_delivered_at is null then
    raise exception 'An order and the time it was delivered are required';
  end if;

  update public.orders
     set status = 'delivered',
         delivered_at = p_delivered_at
   where id = p_order and status = 'shipped'
  returning id into moved;
  if moved is not null then return 'moved'; end if;

  update public.orders
     set pre_dispute_status = 'delivered',
         delivered_at = p_delivered_at
   where id = p_order and status = 'disputed' and pre_dispute_status = 'shipped'
  returning id into moved;
  if moved is not null then return 'moved_in_case'; end if;

  select status into current_status from public.orders where id = p_order;
  if not found then return null; end if;
  return 'unchanged:' || current_status;
end $$;


--
-- Name: order_mark_shipped_from_tracking(uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_mark_shipped_from_tracking(p_order uuid, p_shipped_at timestamp with time zone, p_carrier text DEFAULT NULL::text, p_tracking text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  moved uuid;
  current_status text;
begin
  if p_order is null or p_shipped_at is null then
    raise exception 'An order and the time it shipped are required';
  end if;

  update public.orders
     set status = 'shipped',
         shipped_at = p_shipped_at,
         carrier = p_carrier,
         tracking_number = p_tracking
   where id = p_order and status = 'paid'
  returning id into moved;
  if moved is not null then return 'moved'; end if;

  update public.orders
     set pre_dispute_status = 'shipped',
         shipped_at = p_shipped_at,
         carrier = p_carrier,
         tracking_number = p_tracking
   where id = p_order and status = 'disputed' and pre_dispute_status = 'paid'
  returning id into moved;
  if moved is not null then return 'moved_in_case'; end if;

  select status into current_status from public.orders where id = p_order;
  if not found then return null; end if;
  return 'unchanged:' || current_status;
end $$;


--
-- Name: order_status_change_problem(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_status_change_problem(p_old text, p_new text, p_old_pre text, p_new_pre text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  legal boolean;
begin
  if p_old is not distinct from p_new then
    -- Rule 4: an order in a case keeps its case; what it returns to may move
    -- only along the table.
    if p_old = 'disputed' and p_old_pre is distinct from p_new_pre then
      select exists (
        select 1 from private.order_status_transitions t
         where t.from_status = p_old_pre and t.to_status = p_new_pre
           and t.from_status <> 'disputed' and t.to_status not in ('disputed', 'refunded')
      ) into legal;
      if not coalesce(legal, false) then
        return format('an order in a case may not move from %s to %s underneath it', coalesce(p_old_pre, 'nothing'), coalesce(p_new_pre, 'nothing'));
      end if;
    end if;
    return null;
  end if;

  -- Rule 1.
  select exists (
    select 1 from private.order_status_transitions t
     where t.from_status = p_old and t.to_status = p_new
  ) into legal;
  if not legal then
    return format('an order''s status may not move from %s to %s', p_old, p_new);
  end if;

  -- Rule 3: leaving a case.
  if p_old = 'disputed' and p_new <> 'refunded' then
    if p_old_pre is null then
      if p_new not in ('paid', 'delivered') then
        return format('a case with no status recorded before it closes to paid or delivered, not %s', p_new);
      end if;
    elsif p_new <> p_old_pre then
      return format('a case closes back to %s, the status before it, not %s', p_old_pre, p_new);
    end if;
  end if;

  -- Rule 2: entering a case records where the order was.
  if p_new = 'disputed' and p_new_pre is distinct from p_old then
    return format('an order entering a case from %s must record %s as its status before the case, not %s', p_old, p_old, coalesce(p_new_pre, 'nothing'));
  end if;

  return null;
end;
$$;


--
-- Name: FUNCTION order_status_change_problem(p_old text, p_new text, p_old_pre text, p_new_pre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.order_status_change_problem(p_old text, p_new text, p_old_pre text, p_new_pre text) IS 'Plan 2 A2: why a change of an order''s status (and pre_dispute_status) is refused, or null when it is legal. Reads private.order_status_transitions. Called by public.guard_order_status.';


--
-- Name: pause_account_deletion_hold(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pause_account_deletion_hold(p_job uuid, p_lease uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order uuid;
begin
  update public.remediation_jobs
     set status = 'pending', next_attempt_at = now() + interval '1 hour', locked_until = null, lease_id = null,
         attempts = greatest(attempts - 1, 0), last_error = null
   where id = p_job and kind = 'delete_account' and status = 'processing' and lease_id = p_lease and locked_until > now();
  if not found then raise exception 'Deletion lease lost'; end if;
  v_order := private.account_deletion_hold_order(p_user);
  if exists (select 1 from public.account_deletion_requests where user_id = p_user and scrubbed_at is not null) then
    perform private.record_account_deletion_late_hold(p_user, v_order);
    return;
  end if;
  update public.account_deletion_requests
     set outcome = 'temporary_financial_hold', blocker_code = private.account_deletion_hold_code(v_order),
         affected_data_classes = array['orders', 'returns', 'refunds', 'payouts', 'chargebacks'],
         hold_order_id = v_order,
         next_action = private.account_deletion_hold_note(v_order),
         responsible_owner = 'account owner', updated_at = now()
   where user_id = p_user;
end $$;


--
-- Name: payout_available_at(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payout_available_at(p_order uuid, p_delivered_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select p_delivered_at + make_interval(days => case
    when policy.mode = 'claim_window' then greatest(policy.days, 30, coalesce(shop.window_days, 0))
    else policy.days
  end)
  from (
    select coalesce((select s.payout_hold_days from public.settlement_settings s where s.id), 2) as days,
           coalesce((select s.payout_hold_mode from public.settlement_settings s where s.id), 'fixed') as mode
  ) policy
  left join lateral (
    select max((oi.commercial_snapshot #>> '{commercial,return_policy,window_days}')::integer) as window_days
      from public.order_items oi
     where oi.order_id = p_order
       and oi.commercial_snapshot #>> '{commercial,return_policy,returns_accepted}' = 'true'
       and oi.commercial_snapshot #>> '{commercial,return_policy,window_days}' ~ '^[0-9]{1,3}$'
  ) shop on true
  where p_delivered_at is not null;
$_$;


--
-- Name: payout_release_at(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payout_release_at(p_order uuid, p_delivered_at timestamp with time zone, p_now boolean) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_now and coalesce((select s.payout_hold_mode from public.settlement_settings s where s.id), 'fixed') = 'fixed'
      then p_delivered_at
    else public.payout_available_at(p_order, p_delivered_at)
  end
  where p_delivered_at is not null;
$$;


--
-- Name: photo_metadata_candidates(text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_metadata_candidates(p_bucket text, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_uploaded_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(path text, updated_at timestamp with time zone, size_bytes bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not coalesce(private.photo_scrub_bucket(p_bucket), false) then
    raise exception 'Not a photo bucket this job rewrites: %', p_bucket using errcode = '22023';
  end if;
  return query
  select o.name::text, o.updated_at, coalesce((o.metadata->>'size')::bigint, 0)
    from storage.objects o
   where o.bucket_id = p_bucket
     and (p_after is null or o.name > p_after)
     and (p_uploaded_before is null or o.created_at < p_uploaded_before)
     and not exists (select 1 from private.photo_metadata_scrubs s
                      where s.bucket = p_bucket and s.path = o.name
                        and s.outcome in ('clean', 'scrubbed', 'skipped')
                        and s.object_updated_at is not distinct from o.updated_at)
     and not exists (select 1 from private.media_deletion_claims c
                      where c.bucket = p_bucket and c.path = o.name)
   order by o.name
   limit least(greatest(coalesce(p_limit, 100), 1), 500);
end;
$$;


--
-- Name: photo_metadata_scrub_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_metadata_scrub_summary() RETURNS TABLE(bucket text, outcome text, objects bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.bucket, s.outcome, count(*) from private.photo_metadata_scrubs s group by 1, 2 order by 1, 2;
$$;


--
-- Name: photo_rewrite_strays(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_rewrite_strays(p_bucket text, p_limit integer DEFAULT 500) RETURNS TABLE(path text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.path, min(s.reason)
    from (
      select r.path, 'unfinished_lease' as reason
        from private.media_rewrite_claims r
       where r.bucket = p_bucket and r.claimed_at <= now() - interval '10 minutes'
      union all
      select c.path, 'tombstoned_object'
        from private.media_deletion_claims c
        join storage.objects o on o.bucket_id = c.bucket and o.name = c.path
       where c.bucket = p_bucket and c.state = 'done'
    ) s
   where private.photo_scrub_bucket(p_bucket)
   group by s.path
   order by s.path
   limit least(greatest(coalesce(p_limit, 500), 1), 1000);
$$;


--
-- Name: photo_signatures_offer(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_signatures_offer(p_window bigint, p_signed jsonb) RETURNS TABLE(bucket text, path text, signed_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- In key order, so two instances offering overlapping photos in different
  -- orders take the keys in the same order and never deadlock. Paths the
  -- table would refuse are left out, so one bad path can't fail the batch.
  insert into private.photo_signatures (bucket, path, signing_window, signed_url)
  select distinct on (o.bucket, o.path) o.bucket, o.path, p_window, o.signed_url
    from jsonb_to_recordset(coalesce(p_signed, '[]'::jsonb)) as o(bucket text, path text, signed_url text)
   where o.bucket in ('car-images', 'listing-images', 'activity-images')
     and o.path is not null and length(o.path) between 3 and 512 and o.signed_url is not null
   order by o.bucket, o.path
  on conflict on constraint photo_signatures_pkey do nothing;

  -- Windows before the previous one can never be served again. Rows another
  -- offer is already removing are skipped, not waited for.
  delete from private.photo_signatures d
   where d.ctid in (
     select x.ctid from private.photo_signatures x
      where x.signing_window < p_window - 1
      limit 1000
      for update skip locked
   );

  return query
  select s.bucket, s.path, s.signed_url
    from jsonb_to_recordset(coalesce(p_signed, '[]'::jsonb)) as o(bucket text, path text)
    join private.photo_signatures s
      on s.bucket = o.bucket and s.path = o.path and s.signing_window = p_window;
end;
$$;


--
-- Name: photo_signatures_read(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_signatures_read(p_window bigint, p_objects jsonb) RETURNS TABLE(bucket text, path text, signed_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.bucket, s.path, s.signed_url
    from jsonb_to_recordset(coalesce(p_objects, '[]'::jsonb)) as o(bucket text, path text)
    join private.photo_signatures s
      on s.bucket = o.bucket and s.path = o.path and s.signing_window = p_window;
$$;


--
-- Name: photo_signing_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_signing_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select not exists (
    select 1 from private.photo_signable_positions() p
     where p.kind in ('column', 'body')
       and not exists (
         select 1 from pg_trigger t
          where t.tgrelid = to_regclass(format('public.%I', p.relation))
            and t.tgname = 'photo_owner_folder_guard' and t.tgenabled <> 'D'));
$$;


--
-- Name: pickup_mint_pass(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pickup_mint_pass(p_order_id uuid, p_buyer_id uuid, p_token_hash text, p_code_hash text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order record;
  v_pass record;
begin
  if p_order_id is null or p_buyer_id is null
     or nullif(p_token_hash, '') is null or nullif(p_code_hash, '') is null
     or p_expires_at is null then
    raise exception 'Pass mint needs an order, a buyer, both hashes and an expiry'
      using errcode = '22023';
  end if;

  -- The same lock order as pickup_redeem: the order row, then the pass row.
  select o.id, o.buyer_id, o.status, o.pre_dispute_status, o.is_collection, o.pickup_ready_at
    into v_order
    from public.orders o
   where o.id = p_order_id
   for update;

  if not found or v_order.buyer_id is distinct from p_buyer_id then
    return jsonb_build_object('ok', false, 'reason', 'not_your_order');
  end if;

  select pc.redeemed_at into v_pass
    from public.pickup_confirmations pc
   where pc.order_id = p_order_id
   for update;

  if found and v_pass.redeemed_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'already_redeemed');
  end if;
  -- 20261108110000: no pass for an order the payout deadline is refunding.
  if private.payout_deadline_open_claim(p_order_id) then
    return jsonb_build_object('ok', false, 'reason', 'payout_deadline');
  end if;
  if not v_order.is_collection or v_order.pickup_ready_at is null
     or not (v_order.status = 'paid'
             or (v_order.status = 'disputed' and v_order.pre_dispute_status = 'paid'
                 and not private.order_has_unresolved_chargeback(v_order.id))) then
    return jsonb_build_object('ok', false, 'reason', 'not_ready');
  end if;

  -- Rotate. redeemed_at and redeemed_by are never written here, and a
  -- redeemed row is never updated (the where clause), so no ordering of
  -- calls can erase a handoff.
  insert into public.pickup_confirmations as pc
    (order_id, token_hash, code_hash, attempts, expires_at)
  values (p_order_id, p_token_hash, p_code_hash, 0, p_expires_at)
  on conflict (order_id) do update
     set token_hash = excluded.token_hash,
         code_hash = excluded.code_hash,
         attempts = 0,
         expires_at = excluded.expires_at
   where pc.redeemed_at is null;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'already_redeemed');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: pickup_redeem(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pickup_redeem(p_order_id uuid, p_seller_id uuid, p_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_order record;
  v_pass record;
  v_in_case boolean;
begin
  select o.id, o.seller_id, o.status, o.pre_dispute_status, o.is_collection
    into v_order
    from public.orders o
   where o.id = p_order_id
   for update;

  if not found or v_order.seller_id is distinct from p_seller_id then
    return jsonb_build_object('ok', false, 'reason', 'not_your_order');
  end if;
  if not v_order.is_collection then
    return jsonb_build_object('ok', false, 'reason', 'not_pickup');
  end if;
  v_in_case := v_order.status = 'disputed' and v_order.pre_dispute_status = 'paid'
    and not private.order_has_unresolved_chargeback(v_order.id);
  if v_order.status <> 'paid' and not v_in_case then
    return jsonb_build_object('ok', false, 'reason', 'not_redeemable');
  end if;
  -- 20261108110000: an order the payout deadline claimed is being refunded,
  -- in a case or not; the pass is not burned.
  if private.payout_deadline_open_claim(p_order_id) then
    return jsonb_build_object('ok', false, 'reason', 'payout_deadline');
  end if;

  select * into v_pass
    from public.pickup_confirmations
   where order_id = p_order_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_pass');
  end if;
  if v_pass.redeemed_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'already_redeemed');
  end if;
  if v_pass.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  if v_pass.attempts >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'locked');
  end if;

  if v_pass.token_hash <> p_hash and v_pass.code_hash <> p_hash then
    update public.pickup_confirmations
       set attempts = attempts + 1
     where order_id = p_order_id;
    return jsonb_build_object('ok', false, 'reason', 'mismatch');
  end if;

  -- Handoff proven: single-use stamp + the same delivered/clearing entry a
  -- shipped order gets from the buyer''s confirm.
  update public.pickup_confirmations
     set redeemed_at = now(), redeemed_by = p_seller_id
   where order_id = p_order_id
     and redeemed_at is null;

  if v_in_case then
    -- The case stays open; resolving it lands on 'delivered'.
    update public.orders
       set pre_dispute_status = 'delivered',
           delivered_at = now(),
           completed_at = now()
     where id = p_order_id
       and status = 'disputed';
  else
    update public.orders
       set status = 'delivered',
           delivered_at = now(),
           completed_at = now()
     where id = p_order_id
       and status = 'paid';
  end if;

  -- The handoff starts the payout clock exactly as a buyer's receipt does
  -- for a shipped order (confirm_order_receipt): available when the owner's
  -- clearing hold (settlement_settings, 20261006100000) has passed since
  -- delivery. Without this the intent stayed 'holding' with no
  -- available_at, and mark_due_transfer_intents never released it. While a
  -- case is open, readiness still waits for the order to leave 'disputed'.
  update public.transfer_intents
     set available_at = coalesce(available_at, public.payout_available_at(p_order_id, now())),
         updated_at = now()
   where order_id = p_order_id
     and status = 'holding';

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: post_comment_page(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_comment_page(p_post uuid, p_limit integer DEFAULT 50, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, author_id uuid, body text, created_at timestamp with time zone, author_display_name text, author_username text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.id, c.author_id, c.body, c.created_at, p.display_name, p.username
  from public.activity_comments c
  left join public.profiles p on p.id = c.author_id
  where c.post_id = p_post
    and (p_before_at is null or p_before_id is null
         or (c.created_at, c.id) < (p_before_at, p_before_id))
  order by c.created_at desc, c.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 101);
$$;


--
-- Name: FUNCTION post_comment_page(p_post uuid, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_comment_page(p_post uuid, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid) IS 'One page of a post''s replies, newest first from a (created_at, id) position, with author names (N56). At most 101 rows.';


--
-- Name: post_href(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_href(p_post_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
           when c.slug is null then '/posts/' || p.id
           else '/cars/' || c.slug || '/activity/' || p.id
         end
  from public.activity_posts p
  left join public.cars c on c.id = p.car_id
  where p.id = p_post_id;
$$;


--
-- Name: FUNCTION post_href(p_post_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_href(p_post_id uuid) IS 'Where a post lives — /cars/{slug}/activity/{id}, or /posts/{id} with no car. Twin of postHref() in src/lib/activity/href.ts.';


--
-- Name: post_reaction_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_reaction_counts(p_post uuid) RETURNS TABLE(emoji text, total integer, reacted boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select r.emoji,
         count(*)::integer,
         coalesce(bool_or(r.user_id = auth.uid()), false)
  from public.activity_reactions r
  where r.post_id = p_post
  group by r.emoji;
$$;


--
-- Name: FUNCTION post_reaction_counts(p_post uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_reaction_counts(p_post uuid) IS 'Reactions on one post per emoji, and whether the caller is among them (N56). Never who else reacted.';


--
-- Name: post_search_doc(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_search_doc(p_title text, p_intro text, p_search_text text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ select concat_ws(' ', p_title, p_intro, p_search_text) $$;


--
-- Name: prepare_outbound_label(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_outbound_label(p_shipment uuid, p_actor uuid, p_provider text, p_rated jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  shipment_order uuid;
  s public.shipments;
  o public.orders;
  saved public.outbound_label_requests;
begin
  select order_id into strict shipment_order from public.shipments where id=p_shipment;
  select * into strict o from public.orders where id=shipment_order for update;
  select * into strict s from public.shipments where id=p_shipment for update;
  if s.order_id<>o.id then raise exception 'Shipment order changed'; end if;
  if p_actor is null or o.seller_id is distinct from p_actor then raise exception 'Seller authorization required' using errcode='42501'; end if;
  select * into saved from public.outbound_label_requests where shipment_id=s.id;
  if found then
    if saved.provider<>p_provider then raise exception 'Outbound label provider changed'; end if;
    return to_jsonb(saved);
  end if;
  if o.status<>'paid' or o.is_collection or s.direction<>'outbound'
     or s.fulfillment_type<>'drvn_shipping' or s.status<>'pending' then
    raise exception 'Shipment is not eligible for label purchase';
  end if;
  if p_provider not in ('stub','easypost') or p_rated is null or jsonb_typeof(p_rated)<>'object'
     or nullif(p_rated->>'shipmentRef','') is null or nullif(p_rated->>'rateRef','') is null
     or nullif(p_rated->>'carrier','') is null or nullif(p_rated->>'service','') is null
     or upper(p_rated->>'currency') is distinct from upper(o.currency)
     or coalesce((p_rated->>'amountCents')::integer,-1)<0 then
    raise exception 'Invalid outbound label rate';
  end if;
  if not exists(select 1 from public.shipment_items where shipment_id=s.id) then
    raise exception 'Outbound shipment has no item links';
  end if;
  update public.shipments set provider=p_provider,
    provider_shipment_id=p_rated->>'shipmentRef',carrier=p_rated->>'carrier',service=p_rated->>'service'
  where id=s.id;
  insert into public.outbound_label_requests(shipment_id,provider,rated)
  values(s.id,p_provider,p_rated) returning * into saved;
  insert into public.admin_alert_outbox(kind,title,detail,order_id,amount_cents,payload,dedup_key,next_attempt_at)
  values('recovery_case_opened','Outbound label needs reconciliation',
    'Check the saved outbound_label_requests provider shipment before buying any replacement label.',
    o.id,(p_rated->>'amountCents')::integer,jsonb_build_object('shipment_id',s.id),
    'outbound-label:'||s.id,now()+interval '15 minutes') on conflict(dedup_key) do nothing;
  return to_jsonb(saved);
end $$;


--
-- Name: prepare_outbound_label_void(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_outbound_label_void(p_shipment uuid, p_actor uuid, p_provider text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  shipment_order uuid;
  s public.shipments;
  o public.orders;
  original public.seller_adjustments;
  saved public.outbound_label_void_requests;
begin
  select order_id into strict shipment_order from public.shipments where id=p_shipment;
  select * into strict o from public.orders where id=shipment_order for update;
  select * into strict s from public.shipments where id=p_shipment for update;
  if s.order_id<>o.id then raise exception 'Shipment order changed'; end if;
  if p_actor is null or o.seller_id is distinct from p_actor then
    raise exception 'Seller authorization required' using errcode='42501';
  end if;
  if p_provider is null then raise exception 'Shipping provider required'; end if;
  select * into saved from public.outbound_label_void_requests where shipment_id=s.id for update;
  if found then
    if saved.order_id<>o.id or saved.seller_id is distinct from o.seller_id
       or saved.provider<>p_provider or saved.provider is distinct from s.provider
       or saved.provider_shipment_reference is distinct from s.provider_shipment_id
       or saved.amount_cents is distinct from s.purchased_cents
       or upper(saved.currency)<>upper(o.currency) then
      raise exception 'Saved outbound label void identity conflicts';
    end if;
    return to_jsonb(saved);
  end if;
  if s.direction<>'outbound' or s.fulfillment_type<>'drvn_shipping'
     or s.status<>'label_purchased' or p_provider not in ('stub','easypost')
     or s.provider is distinct from p_provider or nullif(s.provider_shipment_id,'') is null
     or s.purchased_cents is null or s.purchased_cents<0 or nullif(o.currency,'') is null then
    raise exception 'Shipment is not eligible for label void';
  end if;
  select * into strict original from public.seller_adjustments
  where kind='outbound_label' and external_reference='label:'||s.id;
  if original.seller_id is distinct from o.seller_id or original.order_id is distinct from o.id
     or original.shipment_id is distinct from s.id or original.return_id is not null
     or original.amount_cents<>-s.purchased_cents or upper(original.currency)<>upper(o.currency)
     or original.voided_at is not null then
    raise exception 'Outbound label purchase adjustment does not match shipment';
  end if;
  insert into public.outbound_label_void_requests(
    shipment_id,order_id,seller_id,provider,provider_shipment_reference,amount_cents,currency
  ) values(s.id,o.id,o.seller_id,p_provider,s.provider_shipment_id,s.purchased_cents,o.currency)
  returning * into saved;
  insert into public.admin_alert_outbox(
    kind,title,detail,order_id,amount_cents,payload,dedup_key,next_attempt_at
  ) values(
    'recovery_case_opened','Outbound label refund needs reconciliation',
    'Reconcile the frozen provider shipment before submitting another label refund.',
    o.id,s.purchased_cents,jsonb_build_object('shipment_id',s.id),
    'outbound-label-void:'||s.id,now()+interval '15 minutes'
  ) on conflict(dedup_key) do nothing;
  return to_jsonb(saved);
end $$;


--
-- Name: prepare_payment_request(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_payment_request(p_key text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.payment_requests;
begin
 perform 1 from public.orders where id::text in (select jsonb_array_elements_text(p_request->'orderIds')) order by id for update;
 if not exists(select 1 from public.payment_requests where operation_key=p_key) and exists(
   select 1 from public.orders o where o.id::text in (select jsonb_array_elements_text(p_request->'orderIds'))
   and (o.status not in ('pending','requires_action') or exists(select 1 from public.remediation_jobs where dedup_key='expiry:'||o.id))
 ) then raise exception 'Checkout is closing; payment creation refused'; end if;
 -- 20261107210050 (N244): a NEW payment needs every seller it
 -- pays to be able to receive payouts now, not only when the part was
 -- reserved (an accepted offer holds its part for up to a day). A request
 -- already persisted is the same payment, and its replay or reconciliation
 -- is never refused here.
 if not exists(select 1 from public.payment_requests where operation_key=p_key) and exists(
   select 1 from public.orders o where o.id::text in (select jsonb_array_elements_text(p_request->'orderIds'))
   and not private.seller_can_take_payment(o.seller_id)
 ) then
   raise exception 'This seller can''t take payment yet: their payouts aren''t set up' using errcode='LS001';
 end if;
 insert into public.payment_requests(operation_key,request) values(p_key,p_request) on conflict do nothing;
 select * into r from public.payment_requests where operation_key=p_key for update;
 if r.request<>p_request then raise exception 'Payment parameters changed'; end if;
 return jsonb_build_object('request',r.request,'correlation_id',r.correlation_id,'reference',r.provider_reference,'created_at',r.created_at,'rejected',r.provider_rejected_at is not null);
end $$;


--
-- Name: prepare_return_label(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_return_label(p_return uuid, p_actor uuid, p_provider text, p_rated jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.returns; o public.orders; saved public.return_label_requests; sid uuid:=gen_random_uuid();
begin
 select * into strict r from public.returns where id=p_return;
 select * into strict o from public.orders where id=r.order_id for update;
 select * into strict r from public.returns where id=p_return for update;
 if p_actor is null or o.buyer_id is distinct from p_actor then raise exception 'Buyer authorization required' using errcode='42501'; end if;
 select * into saved from public.return_label_requests where return_id=p_return;
 if found then
   if saved.provider<>p_provider then raise exception 'Return label provider changed'; end if;
   return to_jsonb(saved);
 end if;
 if r.status<>'awaiting_shipment' or r.responsibility<>'seller' or o.seller_id is null or (r.ship_by is not null and r.ship_by<now()) then raise exception 'Return is not eligible for a prepaid label'; end if;
 if p_provider not in ('stub','easypost') or p_rated is null or jsonb_typeof(p_rated)<>'object'
 or nullif(p_rated->>'shipmentRef','') is null or nullif(p_rated->>'rateRef','') is null
 or nullif(p_rated->>'carrier','') is null or nullif(p_rated->>'service','') is null
 or upper(p_rated->>'currency') is distinct from upper(o.currency)
 or coalesce((p_rated->>'amountCents')::integer,-1)<0 then raise exception 'Invalid return label rate'; end if;
 if exists(select 1 from public.shipments where return_id=p_return and status not in ('cancelled','failed')) then raise exception 'Return shipment already exists'; end if;
 insert into public.shipments(id,order_id,direction,return_id,provider,provider_shipment_id,fulfillment_type,carrier,service,status)
 values(sid,o.id,'return',r.id,p_provider,p_rated->>'shipmentRef','drvn_shipping',p_rated->>'carrier',p_rated->>'service','pending');
 insert into public.shipment_items(shipment_id,order_item_id)
 select sid,order_item_id from public.return_items where return_id=r.id;
 if not found then raise exception 'Return has no items'; end if;
 insert into public.return_label_requests(return_id,provider,rated,shipment_id) values(r.id,p_provider,p_rated,sid) returning * into saved;
 -- A process can die after buying postage. Its saved provider identity and
 -- delayed outbox alert must survive even if no caller catches the crash.
 insert into public.admin_alert_outbox(kind,title,detail,order_id,amount_cents,payload,dedup_key,next_attempt_at)
 values('recovery_case_opened','Return label needs reconciliation','Check the saved return_label_requests provider shipment before buying any replacement label.',o.id,(p_rated->>'amountCents')::int,
 jsonb_build_object('return_id',r.id,'shipment_id',sid),'return-label:'||r.id,now()+interval '15 minutes') on conflict(dedup_key) do nothing;
 return to_jsonb(saved);
end $$;


--
-- Name: prepare_seller_carry_payout(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_seller_carry_payout(p_id uuid, p_worker text, p_destination text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_payout public.seller_carry_payouts;
begin
  if p_destination is null or length(p_destination) = 0 then
    raise exception 'Invalid carry payout destination';
  end if;
  select * into v_payout from public.seller_carry_payouts where id = p_id for update;
  if not found
     or v_payout.status <> 'processing'
     or v_payout.locked_by is distinct from p_worker
     or v_payout.lease_expires_at is null
     or v_payout.lease_expires_at <= now() then
    return null;
  end if;
  update public.seller_carry_payouts
     set destination = coalesce(destination, p_destination),
         provider_call_may_have_occurred = true,
         updated_at = now()
   where id = p_id
  returning destination into v_payout.destination;
  return v_payout.destination;
end;
$$;


--
-- Name: prepare_transfer_dispatch(uuid, text, text, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_transfer_dispatch(p_order uuid, p_worker text, p_operation_key text, p_amount_cents integer, p_currency text, p_destination text, p_source_transaction text, p_transfer_group text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_updated int;
begin
  if p_order is null
     or p_worker is null
     or p_operation_key is null
     or p_amount_cents is null
     or p_currency is null
     or p_destination is null
     or p_source_transaction is null
     or p_transfer_group is null
     or length(p_operation_key) < 3
     or p_amount_cents <= 0
     or p_currency !~ '^[a-z]{3}$'
     or length(p_destination) = 0
     or length(p_source_transaction) = 0
     or length(p_transfer_group) = 0 then
    raise exception 'Invalid transfer dispatch payload';
  end if;

  -- 20261107130000: parent lock first (refund settlement, transfer completion
  -- and record_transfer_recovery take the same order -> intent order). FOR
  -- UPDATE, not KEY SHARE: it must wait for any chargeback admission in
  -- progress, and every admission locks the order before it writes the
  -- journal (hold_stripe_dispute, apply_stripe_dispute_event: section 6),
  -- so the check below reads the journal as committed. (KEY SHARE let the
  -- check run first and only waited later, in guard_late_refund_payout's
  -- FOR UPDATE, after the decision was made. Taking FOR UPDATE here also
  -- means that trigger never has to upgrade a weaker lock.)
  perform 1 from public.orders where id = p_order for update;

  if private.order_has_unresolved_chargeback(p_order) then
    update public.transfer_intents
    set status = 'holding',
        dispatch_carry_cents = case
          when operation_key is null and not provider_call_may_have_occurred then null
          else dispatch_carry_cents
        end,
        next_attempt_at = case
          when operation_key is null and not provider_call_may_have_occurred then null
          else now() + interval '5 minutes'
        end,
        last_error = 'Payout frozen: a bank chargeback on this order is unresolved',
        locked_at = null,
        locked_by = null,
        lease_expires_at = null,
        updated_at = now()
    where order_id = p_order
      and status = 'processing'
      and locked_by = p_worker
      and lease_expires_at > now();
    return false;
  end if;

  update public.transfer_intents
  set operation_key = p_operation_key,
      dispatch_amount_cents = p_amount_cents,
      dispatch_currency = p_currency,
      dispatch_destination = p_destination,
      dispatch_source_transaction = p_source_transaction,
      dispatch_transfer_group = p_transfer_group,
      source_transaction = coalesce(source_transaction, p_source_transaction),
      provider_call_may_have_occurred = true,
      updated_at = now()
  where order_id = p_order
    and status = 'processing'
    and locked_by = p_worker
    and lease_expires_at > now()
    and (
      (
        operation_key is null
        and dispatch_amount_cents is null
        and dispatch_currency is null
        and dispatch_destination is null
        and dispatch_source_transaction is null
        and dispatch_transfer_group is null
        and provider_call_may_have_occurred = false
      )
      or (
        operation_key = p_operation_key
        and dispatch_amount_cents = p_amount_cents
        and dispatch_currency = p_currency
        and dispatch_destination = p_destination
        and dispatch_source_transaction = p_source_transaction
        and dispatch_transfer_group = p_transfer_group
      )
    );
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$_$;


--
-- Name: price_comparables(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_comparables(p_brand text, p_part_number text, p_currency text DEFAULT 'USD'::text, p_exclude_listing uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c_min_sample constant int := 3;
  c_window_days constant int := 730;
  c_sample_cap constant int := 500;
  v_brand text := nullif(regexp_replace(lower(coalesce(p_brand, '')), '[^[:alnum:]]', '', 'g'), '');
  v_number text := nullif(regexp_replace(lower(coalesce(p_part_number, '')), '[^a-z0-9]', '', 'g'), '');
  v_product uuid;
  v_brands text[];
  v_pairs text[];
  v_numbers text[];
  v_sold jsonb;
  v_asking jsonb;
begin
  if v_brand is null or v_number is null then
    return jsonb_build_object('enough', false, 'reason', 'brand_and_number_required', 'min_sample', c_min_sample);
  end if;

  select pm.product_id into v_product
  from public.product_part_numbers pm where pm.brand_key = v_brand and pm.number_compact = v_number;

  -- Every (brand, number) the product holds; the pair alone before it has one.
  if v_product is not null then
    select array_agg(pm.brand_key order by pm.brand_key, pm.number_compact),
           array_agg(pm.number_compact order by pm.brand_key, pm.number_compact)
      into v_brands, v_pairs
    from public.product_part_numbers pm where pm.product_id = v_product;
  else
    v_brands := array[v_brand];
    v_pairs := array[v_number];
  end if;
  select array_agg(distinct n) into v_numbers from unnest(v_pairs) n;

  -- Per line, every lookup is an index probe on that line's own order: no
  -- join between the matching lines and an aggregate of them, which the
  -- planner estimates at one row and turns into a nested loop that redoes
  -- the aggregate per line (5,000 sales: 2.7 s; this way: tens of ms).
  with matching as materialized (
    select oi.id, oi.order_id, o.refunded_cents,
           greatest(coalesce(oi.quantity, 1), 1) as quantity,
           oi.price_cents::bigint * greatest(coalesce(oi.quantity, 1), 1) as goods_cents,
           -- The sold listing is read only for a snapshot from before
           -- part.brand (coalesce stops at the first value).
           nullif(regexp_replace(lower(coalesce(oi.commercial_snapshot -> 'part' ->> 'brand',
             (select l.brand from public.listings l where l.id = oi.listing_id), '')), '[^[:alnum:]]', '', 'g'), '') as brand_key,
           v.n as number_compact,
           coalesce(oi.commercial_snapshot -> 'condition' ->> 'condition',
             (select l.condition from public.listings l where l.id = oi.listing_id)) as condition,
           coalesce((oi.commercial_snapshot -> 'commercial' ->> 'shipping_cents')::bigint, oi.shipping_cents::bigint) as shipping_cents,
           coalesce(o.completed_at, o.delivered_at, o.created_at) as sold_at
    from unnest(v_numbers) v(n)
    -- The newest c_sample_cap purchases of each number, from the index in
    -- order; the completed, in-window, same-currency ones among them count.
    cross join lateral (
      select oi.* from public.order_items oi
      where nullif(regexp_replace(lower(coalesce(oi.commercial_snapshot -> 'part' ->> 'part_number', '')), '[^a-z0-9]', '', 'g'), '') = v.n
        and oi.commercial_snapshot -> 'part' ->> 'part_number' is not null
      order by oi.commercial_snapshot ->> 'captured_at' desc
      limit c_sample_cap
    ) oi
    join public.orders o on o.id = oi.order_id
    where o.status = 'completed'
      and coalesce(o.currency, 'USD') = p_currency
      and coalesce(o.completed_at, o.delivered_at, o.created_at) >= now() - make_interval(days => c_window_days)
  ),
  kept as materialized (
    select s.condition, s.shipping_cents, s.sold_at, s.unit_net_cents
    from (
      select m.condition, m.shipping_cents, m.sold_at,
             round((m.goods_cents - (r.unexplained_cents::numeric * m.goods_cents / nullif(g.goods_cents, 0))) / m.quantity) as unit_net_cents
      from matching m
      join unnest(v_brands, v_pairs) k(brand_key, number_compact)
        on k.brand_key = m.brand_key and k.number_compact = m.number_compact
      -- Every line of the order counts toward its goods, matching or not: a
      -- refund is shared across the whole order.
      cross join lateral (
        select sum(oi.price_cents::bigint * greatest(coalesce(oi.quantity, 1), 1)) as goods_cents
        from public.order_items oi where oi.order_id = m.order_id
      ) g
      -- What the order refunded beyond its completed returns, up to its goods.
      cross join lateral (
        select least(greatest(coalesce(m.refunded_cents, 0)::bigint - coalesce((
                 select sum(greatest(coalesce(r.refund_amount_cents, 0) - coalesce(r.label_deduction_cents, 0), 0))
                 from public.returns r where r.order_id = m.order_id and r.status = 'completed'), 0), 0),
               g.goods_cents) as unexplained_cents
      ) r
      -- A line with a completed return is not a sale.
      where not exists (
        select 1 from public.return_items ri join public.returns rt on rt.id = ri.return_id
        where ri.order_item_id = m.id and rt.status = 'completed')
    ) s
    where s.unit_net_cents > 0
  ),
  by_condition as (
    select condition, count(*) as n,
           percentile_disc(0.5) within group (order by unit_net_cents) as median_cents
    from kept where condition is not null group by condition
  ),
  totals as (
    select count(*) as n,
           percentile_disc(0.5) within group (order by unit_net_cents) as median_cents,
           percentile_disc(0.25) within group (order by unit_net_cents) as p25_cents,
           percentile_disc(0.75) within group (order by unit_net_cents) as p75_cents,
           percentile_disc(0.5) within group (order by shipping_cents) as median_shipping_cents,
           -- A sale completed "in the future" (clock skew) is a sale today.
           greatest(0, extract(day from now() - max(sold_at)))::int as newest_days,
           percentile_disc(0.5) within group (order by greatest(0, extract(day from now() - sold_at))::int) as median_age_days
    from kept
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'count', t.n,
    'enough', t.n >= c_min_sample,
    'median_cents', case when t.n >= c_min_sample then t.median_cents end,
    'p25_cents', case when t.n >= c_min_sample then t.p25_cents end,
    'p75_cents', case when t.n >= c_min_sample then t.p75_cents end,
    'median_shipping_cents', case when t.n >= c_min_sample then t.median_shipping_cents end,
    'newest_days', case when t.n >= c_min_sample then t.newest_days end,
    'median_age_days', case when t.n >= c_min_sample then t.median_age_days end,
    'by_condition', (select jsonb_agg(jsonb_build_object('condition', condition, 'count', n, 'median_cents', median_cents) order by n desc, condition)
                     from by_condition where n >= c_min_sample)
  )) into v_sold
  from totals t;

  with asking as (
    select l.price_cents::bigint as price_cents, l.condition, l.shipping_cents::bigint as shipping_cents, l.created_at
    from public.listings l
    join unnest(v_brands, v_pairs) k(brand_key, number_compact)
      on k.number_compact = l.part_number_compact
     and k.brand_key = nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), '')
    where l.part_number_compact = any(v_numbers)
      and l.status = 'active'
      and coalesce(l.currency, 'USD') = p_currency
      and l.id is distinct from p_exclude_listing
      and l.seller_id not in (select public.suspended_profile_ids())
  ),
  by_condition as (
    select condition, count(*) as n, percentile_disc(0.5) within group (order by price_cents) as median_cents
    from asking where condition is not null group by condition
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'count', (select count(*) from asking),
    'enough', (select count(*) from asking) >= c_min_sample,
    'median_cents', case when (select count(*) from asking) >= c_min_sample
      then (select percentile_disc(0.5) within group (order by price_cents) from asking) end,
    'p25_cents', case when (select count(*) from asking) >= c_min_sample
      then (select percentile_disc(0.25) within group (order by price_cents) from asking) end,
    'p75_cents', case when (select count(*) from asking) >= c_min_sample
      then (select percentile_disc(0.75) within group (order by price_cents) from asking) end,
    'median_shipping_cents', case when (select count(*) from asking) >= c_min_sample
      then (select percentile_disc(0.5) within group (order by shipping_cents) from asking) end,
    'by_condition', (select jsonb_agg(jsonb_build_object('condition', condition, 'count', n, 'median_cents', median_cents) order by n desc, condition)
                     from by_condition where n >= c_min_sample)
  )) into v_asking;

  return jsonb_build_object(
    'identity', jsonb_build_object('brand_key', v_brand, 'number_compact', v_number,
                                   'product', v_product is not null, 'numbers', cardinality(v_numbers)),
    'currency', p_currency,
    'min_sample', c_min_sample,
    'window_days', c_window_days,
    'sample_cap', c_sample_cap,
    'enough', coalesce((v_sold ->> 'enough')::boolean, false) or coalesce((v_asking ->> 'enough')::boolean, false),
    'sold', v_sold,
    'asking', v_asking
  );
end;
$$;


--
-- Name: product_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_coverage() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Set-based throughout: each record list is left-joined to the membership
  -- once (a hash join at 2M parts), never looked up row by row (185 s).
  with l as materialized (
    select l.part_number_compact as n,
           nullif(regexp_replace(lower(coalesce(l.brand, '')), '[^[:alnum:]]', '', 'g'), '') as b
    from public.listings l
    where l.part_number_compact is not null and l.status not in ('draft', 'removed')
  ), m as materialized (
    select m.part_number_compact as n, m.brand_key as b from public.mod_items m where m.part_number_compact is not null
  ), s as materialized (
    select nullif(regexp_replace(lower(coalesce(oi.commercial_snapshot -> 'part' ->> 'part_number', '')), '[^a-z0-9]', '', 'g'), '') as n,
           nullif(regexp_replace(lower(coalesce(oi.commercial_snapshot -> 'part' ->> 'brand', sl.brand, '')), '[^[:alnum:]]', '', 'g'), '') as b
    from public.order_items oi
    join public.orders o on o.id = oi.order_id and o.status = 'completed'
    left join public.listings sl on sl.id = oi.listing_id
    where oi.commercial_snapshot -> 'part' ->> 'part_number' is not null
  ), lp as (
    select l.n, l.b, pm.product_id from l left join public.product_part_numbers pm on pm.brand_key = l.b and pm.number_compact = l.n
  ), mp as (
    select m.n, m.b, pm.product_id from m left join public.product_part_numbers pm on pm.brand_key = m.b and pm.number_compact = m.n
  ), sp as (
    select s.n, s.b, pm.product_id from s left join public.product_part_numbers pm on pm.brand_key = s.b and pm.number_compact = s.n
  )
  select jsonb_build_object(
    'listings', (select jsonb_build_object(
        'with_number', count(*),
        'with_brand_and_number', count(*) filter (where b is not null),
        'eligible', count(*) filter (where b is not null and n ~ '[0-9]' and char_length(n) between 3 and 64),
        'with_product', count(*) filter (where product_id is not null))
      from lp),
    'mod_items', (select jsonb_build_object(
        'with_number', count(*),
        'with_brand_and_number', count(*) filter (where b is not null),
        'eligible', count(*) filter (where b is not null and n ~ '[0-9]' and char_length(n) between 3 and 64),
        'with_product', count(*) filter (where product_id is not null))
      from mp),
    'sold_lines', (select jsonb_build_object(
        'with_number', count(*) filter (where n is not null),
        'with_brand_and_number', count(*) filter (where n is not null and b is not null),
        'with_product', count(*) filter (where product_id is not null))
      from sp),
    'products', (select jsonb_build_object(
        'active', count(*) filter (where status = 'active'),
        'merged', count(*) filter (where status = 'merged'))
      from public.products p),
    'products_on_listings_and_builds', (select count(*) from (
        select product_id from lp where product_id is not null
        intersect
        select product_id from mp where product_id is not null) x),
    'open_reviews', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb)
      from (select kind, count(*) as n from public.product_identity_reviews where status = 'open' group by kind) r)
  );
$$;


--
-- Name: profile_follow_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_follow_counts(p_profile uuid) RETURNS TABLE(followers bigint, following bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    (select count(*) from public.follows f
      where f.target_type = 'profile' and f.target_id = p_profile) as followers,
    (select count(*) from public.follows f
      where f.follower_id = p_profile) as following
  where public.profile_is_visible(p_profile);
$$;


--
-- Name: profile_is_visible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_is_visible(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select exists(select 1 from public.profiles where id=p_id and suspended_at is null); $$;


--
-- Name: profile_sales_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_sales_count(p_profile uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*) from public.orders o
   where o.seller_id = p_profile
     and o.status in ('paid', 'shipped', 'delivered', 'completed')
     and public.profile_is_visible(p_profile);
$$;


--
-- Name: profile_shares_deal_with_me(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_shares_deal_with_me(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (select auth.uid()) is not null and (
    exists (
      select 1 from public.conversations c
       where (c.participant_a = (select auth.uid()) and c.participant_b = p_id)
          or (c.participant_b = (select auth.uid()) and c.participant_a = p_id)
    )
    or exists (
      select 1 from public.orders o
       where (o.buyer_id = (select auth.uid()) and o.seller_id = p_id)
          or (o.seller_id = (select auth.uid()) and o.buyer_id = p_id)
    )
  );
$$;


--
-- Name: prune_listing_edit_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_listing_edit_requests() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with gone as (delete from private.listing_edit_requests where created_at < now() - interval '7 days' returning 1)
  select count(*)::integer from gone;
$$;


--
-- Name: prune_rate_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_rate_limits() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from public.rate_limits where window_start < now() - interval '1 day';
$$;


--
-- Name: purchase_begin(uuid, uuid[], text, interval, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_begin(p_buyer_id uuid, p_listing_ids uuid[], p_idempotency_key text DEFAULT NULL::text, p_reservation_window interval DEFAULT '00:15:00'::interval, p_shipping_overrides jsonb DEFAULT NULL::jsonb, p_checkout_request_key text DEFAULT NULL::text, p_checkout_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_previous jsonb;
  v_owner uuid;
  v_bound_owner uuid;
  v_bound_idempotency_key text;
  v_bound_context jsonb;
  v_fingerprint jsonb;
  v_orders jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_group record;
  v_order_id uuid;
  v_fee int;
  v_requested uuid[];
  v_claimed uuid[];
  v_basket_total bigint;
begin
  if p_checkout_request_key is not null and (
    p_idempotency_key is null
    or p_checkout_context is null
    or jsonb_typeof(p_checkout_context) <> 'object'
  ) then
    raise exception 'Checkout request binding requires an idempotency key and context' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_buyer_id::text, 0));
  if exists(select 1 from public.profiles where id=p_buyer_id and suspended_at is not null) then raise exception 'Account unavailable'; end if;
  if p_checkout_request_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_checkout_request_key, 2));
    select buyer_id, idempotency_key, checkout_context
      into v_bound_owner, v_bound_idempotency_key, v_bound_context
    from public.purchase_attempts
    where checkout_request_key = p_checkout_request_key;
    if found and (
      v_bound_owner is distinct from p_buyer_id
      or v_bound_idempotency_key is distinct from p_idempotency_key
      or v_bound_context is distinct from p_checkout_context
    ) then
      raise exception 'Checkout request is already bound to a different purchase' using errcode='42501';
    end if;
  end if;
  v_fingerprint := jsonb_build_object('ids', (select jsonb_agg(x order by x) from (select distinct unnest(p_listing_ids) x) t), 'shipping', coalesce(p_shipping_overrides, '{}'::jsonb));
  if p_idempotency_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key, 1));
    select buyer_id, request_fingerprint into v_owner, v_previous from public.purchase_attempts where idempotency_key=p_idempotency_key;
    if found and (v_owner is distinct from p_buyer_id or v_previous is distinct from v_fingerprint) then
      raise exception 'Checkout attempt does not match this buyer or basket' using errcode='42501';
    end if;
    select result into v_previous
    from public.purchase_attempts
    where idempotency_key = p_idempotency_key;

    if v_previous is not null then
      -- 20261108130000: a replay settles this request's own admissions too.
      perform private.guest_holds_settle(p_idempotency_key, v_previous);
      return v_previous;
    end if;
  end if;

  if (select count(*) from public.orders where buyer_id=p_buyer_id and status in ('pending','requires_action')) >= 5 then
    raise exception 'Too many unresolved checkouts';
  end if;
  if (select count(distinct currency) from public.listings where id=any(p_listing_ids)) > 1 then raise exception 'A checkout must use one currency'; end if;
  if cardinality(p_listing_ids)>50 then raise exception 'Checkout supports at most 50 items'; end if;
  if (select count(distinct seller_id) from public.listings where id=any(p_listing_ids))>13 then raise exception 'Split this basket into checkouts with at most 13 sellers'; end if;
  v_requested := coalesce(p_listing_ids, array[]::uuid[]);
  if array_length(v_requested, 1) is null then
    return jsonb_build_object('orders', v_orders, 'skipped', v_skipped);
  end if;

  drop table if exists _claimed;
  create temp table _claimed on commit drop as
  with claimed as (
    update public.listings l
    set status = 'reserved',
        reserved_until = now() + p_reservation_window
    where l.id = any (v_requested)
      and l.status = 'active'
      and l.seller_id <> p_buyer_id
      and private.seller_can_take_payment(l.seller_id)
    returning
      l.id, l.seller_id, l.title, l.price_cents, l.shipping_cents, l.currency
  )
  select
    c.id, c.seller_id, c.title, c.price_cents, c.currency,
    greatest(
      coalesce((p_shipping_overrides ->> c.id::text)::int, c.shipping_cents),
      0
    ) as shipping_cents
  from claimed c;

  select coalesce(array_agg(id), array[]::uuid[]) into v_claimed from _claimed;

  -- One payment covers the whole basket, so the bound is on the basket. Summed
  -- as bigint: a basket of large prices must be refused, not overflow below.
  select coalesce(sum(price_cents::bigint + shipping_cents::bigint), 0)
    into v_basket_total from _claimed;
  if cardinality(v_claimed) > 0 and not public.charge_cents_in_bounds(v_basket_total) then
    raise exception 'A checkout total must be between $0.50 and $999,999.99'
      using errcode = '22003';
  end if;

  select coalesce(
    jsonb_agg(jsonb_build_object('listing_id', missing.id, 'reason', 'unavailable')),
    '[]'::jsonb
  )
  into v_skipped
  from (select unnest(v_requested) as id except select unnest(v_claimed)) as missing;

  for v_group in
    select
      c.seller_id,
      c.currency,
      sum(c.price_cents)::int as subtotal,
      sum(c.shipping_cents)::int as shipping
    from _claimed c
    group by c.seller_id, c.currency
  loop
    v_fee := round((v_group.subtotal + v_group.shipping) * 1000.0 / 10000.0);

    insert into public.orders (
      buyer_id, seller_id, status,
      subtotal_cents, shipping_cents, platform_fee_cents, total_cents, currency
    )
    values (
      p_buyer_id, v_group.seller_id, 'pending',
      v_group.subtotal, v_group.shipping, v_fee,
      v_group.subtotal + v_group.shipping, v_group.currency
    )
    returning id into v_order_id;

    insert into public.order_items (order_id, listing_id, title, price_cents, shipping_cents)
    select v_order_id, c.id, c.title, c.price_cents, c.shipping_cents
    from _claimed c
    where c.seller_id = v_group.seller_id and c.currency = v_group.currency;

    insert into public.payments (order_id, amount_cents, currency, idempotency_key, status)
    values (
      v_order_id,
      v_group.subtotal + v_group.shipping,
      v_group.currency,
      case
        when p_idempotency_key is null then null
        else p_idempotency_key || ':' || v_order_id::text
      end,
      'pending'
    );

    v_orders := v_orders || jsonb_build_object(
      'order_id', v_order_id,
      'seller_id', v_group.seller_id,
      'currency', v_group.currency,
      'subtotal_cents', v_group.subtotal,
      'shipping_cents', v_group.shipping,
      'platform_fee_cents', v_fee,
      'total_cents', v_group.subtotal + v_group.shipping,
      'listing_ids', (
        select jsonb_agg(c.id)
        from _claimed c
        where c.seller_id = v_group.seller_id and c.currency = v_group.currency
      )
    );
  end loop;

  v_previous := jsonb_build_object('orders', v_orders, 'skipped', v_skipped);

  if p_idempotency_key is not null then
    insert into public.purchase_attempts (
      idempotency_key, buyer_id, result, request_fingerprint,
      checkout_request_key, checkout_context
    )
    values (
      p_idempotency_key, p_buyer_id, v_previous, v_fingerprint,
      p_checkout_request_key, p_checkout_context
    )
    on conflict (idempotency_key) do nothing;
  end if;

  -- 20261108130000 (N89): a guest's hold admissions are bound to the orders
  -- that hold their parts in this same transaction, before any delivery or
  -- payment work, and the admissions for parts not reserved are given back.
  -- Only this request's admissions: another checkout's are never touched.
  perform private.guest_holds_settle(p_idempotency_key, v_previous);

  return v_previous;
end;
$_$;


--
-- Name: purchase_claim_key(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_claim_key(p_idempotency_key text, p_buyer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing jsonb;
begin
  if p_idempotency_key is null then
    return null;
  end if;

  insert into public.purchase_attempts (idempotency_key, buyer_id, result)
  values (p_idempotency_key, p_buyer_id, 'null'::jsonb)
  on conflict (idempotency_key) do nothing;

  -- Either we just claimed it (result = 'null') or someone else owns it.
  select result into v_existing
  from public.purchase_attempts
  where idempotency_key = p_idempotency_key
    and buyer_id is not distinct from p_buyer_id
  for update;

  return v_existing;
end;
$$;


--
-- Name: purchase_finalize(uuid, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_finalize(p_order_id uuid, p_success boolean, p_provider text DEFAULT 'stub'::text, p_reference text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order record;
  v_listing_ids uuid[];
  v_applied boolean := false;
begin
  -- One lock order for every path that sells a listing: listing → offer →
  -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
  perform 1 from public.listings where id in (
    select oi.listing_id from public.order_items oi where oi.order_id=p_order_id and oi.listing_id is not null
  ) order by id for update;

  -- Lock the order so two concurrent finalizes (a webhook retry racing the
  -- inline call) serialise rather than interleave.
  select id, status into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'order not found');
  end if;

  -- Terminal states are terminal. Without this, a late `failed` webhook could
  -- drag a paid, shipped, delivered order backwards to payment_failed.
  if v_order.status not in ('pending', 'requires_action') then
    return jsonb_build_object(
      'applied', false,
      'reason', 'order already settled',
      'status', v_order.status
    );
  end if;

  select coalesce(array_agg(listing_id), array[]::uuid[])
  into v_listing_ids
  from public.order_items
  where order_id = p_order_id and listing_id is not null;

  if p_success then
    update public.orders set status = 'paid' where id = p_order_id;

    update public.listings
    set status = 'sold', sold_at = now(), reserved_until = null
    where id = any (v_listing_ids) and status = 'reserved';

    update public.payments
    set status = 'succeeded',
        provider = p_provider,
        provider_reference = coalesce(p_reference, provider_reference)
    where order_id = p_order_id and status in ('pending', 'requires_action');

    update public.offers
    set status = 'expired', responded_at = now()
    where listing_id = any (v_listing_ids) and status in ('open', 'countered');
  else
    update public.orders
    set status = 'payment_failed',
        cancelled_at = now(),
        cancel_reason = p_failure_reason
    where id = p_order_id;

    update public.listings
    set status = 'active', reserved_until = null
    where id = any (v_listing_ids) and status = 'reserved';

    update public.payments
    set status = 'failed',
        provider = p_provider,
        failure_reason = p_failure_reason
    where order_id = p_order_id and status in ('pending', 'requires_action');
  end if;

  v_applied := true;
  return jsonb_build_object('applied', v_applied, 'status',
    case when p_success then 'paid' else 'payment_failed' end);
end;
$$;


