--
-- Name: queue_search_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_search_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r jsonb; entity text; target uuid;
begin
 r:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 entity:=tg_argv[0]; target:=(r->>tg_argv[1])::uuid;
 insert into public.remediation_jobs(kind,dedup_key,payload) values('search','search:'||entity||':'||target||':'||txid_current(),jsonb_build_object('entity',entity,'id',target)) on conflict(dedup_key) do nothing;
 if entity='car' then
   insert into public.remediation_jobs(kind,dedup_key,payload)
   select 'search','search:update:'||id||':'||txid_current(),jsonb_build_object('entity','update','id',id) from public.activity_posts where car_id=target on conflict(dedup_key) do nothing;
 elsif entity='profile' then
   insert into public.remediation_jobs(kind,dedup_key,payload)
   select 'search','search:listing:'||id||':'||txid_current(),jsonb_build_object('entity','listing','id',id) from public.listings where seller_id=target on conflict(dedup_key) do nothing;
   insert into public.remediation_jobs(kind,dedup_key,payload)
   select 'search','search:car:'||id||':'||txid_current(),jsonb_build_object('entity','car','id',id) from public.cars where owner_id=target on conflict(dedup_key) do nothing;
   insert into public.remediation_jobs(kind,dedup_key,payload)
   select 'search','search:update:'||p.id||':'||txid_current(),jsonb_build_object('entity','update','id',p.id) from public.activity_posts p join public.cars c on c.id=p.car_id where c.owner_id=target or p.author_id=target on conflict(dedup_key) do nothing;
 end if;
 return coalesce(new,old);
end $$;


--
-- Name: queue_search_profile_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_search_profile_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target uuid := coalesce(new.id, old.id);
begin
  insert into public.remediation_jobs(kind, dedup_key, payload)
  values ('search', 'search:profile:' || target || ':' || txid_current(), jsonb_build_object('entity', 'profile', 'id', target))
  on conflict (dedup_key) do nothing;
  if tg_op = 'UPDATE' and (old.suspended_at is null) <> (new.suspended_at is null) then
    insert into public.remediation_jobs(kind, dedup_key, payload)
    select 'search', 'search:listing:' || id || ':' || txid_current(), jsonb_build_object('entity', 'listing', 'id', id)
    from public.listings where seller_id = target
    on conflict (dedup_key) do nothing;
    insert into public.remediation_jobs(kind, dedup_key, payload)
    select 'search', 'search:car:' || id || ':' || txid_current(), jsonb_build_object('entity', 'car', 'id', id)
    from public.cars where owner_id = target
    on conflict (dedup_key) do nothing;
    insert into public.remediation_jobs(kind, dedup_key, payload)
    select 'search', 'search:update:' || p.id || ':' || txid_current(), jsonb_build_object('entity', 'update', 'id', p.id)
    from public.activity_posts p join public.cars c on c.id = p.car_id
    where c.owner_id = target or p.author_id = target
    on conflict (dedup_key) do nothing;
  end if;
  return null;
end;
$$;


--
-- Name: raise_dispatch_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_dispatch_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row record;
  v_n integer := 0;
begin
  for v_row in
    select o.id, o.seller_id, o.dispatch_by
      from public.orders o
     where o.status = 'paid' and o.shipped_at is null
       -- A seller whose account is gone has nobody to remind, and their null
       -- id would fail the insert below and roll back every reminder with it
       -- (review of #204).
       and o.seller_id is not null
       and o.dispatch_by is not null and o.dispatch_by <= now() + interval '24 hours'
       -- Not for an order long past its date: that is the dispatch deadline's own handling.
       and o.dispatch_by > now() - interval '24 hours'
       and not exists (select 1 from public.dispatch_reminders r where r.order_id = o.id)
     order by o.dispatch_by
     limit 200
  loop
    insert into public.dispatch_reminders (order_id, seller_id, dispatch_by)
    values (v_row.id, v_row.seller_id, v_row.dispatch_by)
    on conflict (order_id) do nothing;
    if not found then
      continue;
    end if;
    perform public.notify(v_row.seller_id, 'dispatch_reminder', 'marketplace',
      'An order is due to be dispatched', 'Mark it dispatched with its tracking number once it is on its way.', '/orders/' || v_row.id, null);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: raise_payout_setup_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_payout_setup_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row record;
  v_n integer := 0;
begin
  for v_row in
    with unpaid as (
      select o.id as order_id, o.seller_id, (current_date - min(ti.created_at)::date) as day
        from public.transfer_intents ti
        join public.orders o on o.id = ti.order_id
        join public.profiles p on p.id = o.seller_id
       where ti.status in ('holding', 'ready', 'blocked_unpayable', 'failed')
         and o.status not in ('refunded', 'cancelled')
         and not p.payouts_enabled
       group by o.id, o.seller_id
    )
    select u.seller_id,
           count(*)::integer as sale_count,
           max(u.day) as oldest_day,
           (array_agg(u.order_id order by u.day desc, u.order_id))[1] as order_id
      from unpaid u
     where u.day between 0 and 13
       -- Before the limit: with it after, sellers past the first 200 by id were never reached.
       and not exists (select 1 from public.payout_setup_reminders r where r.seller_id = u.seller_id and r.reminded_on = current_date)
     group by u.seller_id
    having bool_or(u.day in (3, 7, 12))
     order by u.seller_id
     limit 200
  loop
    insert into public.payout_setup_reminders (seller_id, reminded_on, order_id, sale_count, oldest_day)
    values (v_row.seller_id, current_date, v_row.order_id, v_row.sale_count, v_row.oldest_day)
    on conflict (seller_id, reminded_on) do nothing;
    if not found then
      continue;
    end if;
    insert into public.notifications (user_id, kind, section, title, body, href)
    values (v_row.seller_id, 'payout_setup_reminder', 'marketplace',
            case when v_row.sale_count > 1 then format('Set up payouts to be paid for your %s sales', v_row.sale_count)
                 else 'Set up payouts to be paid for your sale' end,
            case when v_row.oldest_day >= 12
                 then format('%s left: finish your payout setup, or the oldest sale is refunded on day 14.',
                             case when 14 - v_row.oldest_day = 1 then 'One day' else (14 - v_row.oldest_day)::text || ' days' end)
                 else 'Finish your payout setup within 14 days of each sale, or it is refunded.' end,
            '/orders/' || v_row.order_id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: recommend_listings(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommend_listings(p_user uuid, p_limit integer DEFAULT 8) RETURNS TABLE(id uuid, title text, price_cents integer, shipping_cents integer, condition text, location text, part_number text, seller_id uuid, source_car_id uuid, status text, score integer, reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with
  garage as (
    select distinct lower(c.make) as mk, lower(c.model) as md
    from public.cars c
    where c.owner_id = p_user
      and coalesce(c.make, '') <> '' and coalesce(c.model, '') <> ''
  ),
  matched_cars as (
    select c.id,
           nullif(concat_ws(' ', nullif(trim(c.make), ''), nullif(trim(c.model), '')), '') as label
    from public.cars c
    join garage g on lower(c.make) = g.mk and lower(c.model) = g.md
  ),
  rule1 as (
    select l.id as listing_id, 10 as pts, 'Fits your ' || m.label as reason, 1 as rule
    from public.listings l
    join matched_cars m on m.id = l.source_car_id
    where l.status = 'active' and l.seller_id <> p_user
    order by l.created_at desc
    limit 50
  ),
  my_saved as (
    select s.target_id, s.created_at
    from public.saves s
    where s.user_id = p_user and s.target_type = 'listing'
  ),
  my_recent_saved as (
    select target_id from my_saved order by created_at desc limit 50
  ),
  neighbours as (
    select distinct n.user_id
    from (
      select s.user_id
      from public.saves s
      where s.target_type = 'listing'
        and s.target_id in (select target_id from my_recent_saved)
        and s.user_id <> p_user
      limit 50
    ) n
  ),
  rule2 as (
    select s.target_id as listing_id, 3 as pts, 'Because you saved similar parts' as reason, 2 as rule
    from (
      select s.target_id
      from public.saves s
      where s.target_type = 'listing'
        and s.user_id in (select user_id from neighbours)
        and s.target_id not in (select target_id from my_saved)
      limit 50
    ) s
  ),
  first_rules as (
    select * from rule1
    union all
    select * from rule2
  ),
  rule3 as (
    select s.target_id as listing_id, 1 as pts, 'Popular with the DRVN community' as reason, 3 as rule
    from (
      select s.target_id from public.saves s where s.target_type = 'listing' limit 50
    ) s
    where (select count(distinct listing_id) from first_rules) < coalesce(p_limit, 8)
  ),
  scored as (
    select p.listing_id,
           sum(p.pts)::integer as score,
           (array_agg(p.reason order by p.rule) filter (where p.reason is not null))[1] as reason,
           min(p.rule) as first_rule
    from (select * from first_rules union all select * from rule3) p
    group by p.listing_id
  )
  select l.id, l.title, l.price_cents, l.shipping_cents, l.condition, l.location, l.part_number,
         l.seller_id, l.source_car_id, l.status, s.score, s.reason
  from scored s
  join public.listings l on l.id = s.listing_id
  where l.status = 'active' and l.seller_id <> p_user
  order by s.score desc, s.first_rule, l.created_at desc
  limit greatest(coalesce(p_limit, 8), 0);
$$;


--
-- Name: reconcile_admin_external_operation(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_admin_external_operation(p_operation uuid, p_seen_through bigint, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_req public.admin_audit_log;
  v_terminal public.admin_audit_log;
  v_latest bigint;
  v_order uuid;
  v_ops jsonb;
  v_running boolean := false;
  v_applied boolean := false;
  v_any boolean := false;
  v_evidence jsonb;
  v_lease constant interval := interval '15 minutes';
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists(
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->'amr', '[]'::jsonb)) m
    where m->>'method' in ('totp', 'mfa/totp')
      and (m->>'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then
    raise exception 'Admin step-up required' using errcode = '42501';
  end if;
  if p_outcome is null or p_outcome not in ('applied', 'not_applied', 'unknown') then
    raise exception 'Outcome must be applied, not_applied or unknown' using errcode = '22023';
  end if;
  if p_reason is null or length(trim(p_reason)) < 1 or length(p_reason) > 4000 then
    raise exception 'A reason of 1–4000 characters is required' using errcode = '22023';
  end if;

  select * into v_req from public.admin_audit_log a
  where a.metadata->>'operationId' = p_operation::text and a.metadata->>'phase' = 'requested'
  order by a.id limit 1;
  if not found then raise exception 'No such operation' using errcode = 'P0002'; end if;

  -- The fence's own lock: admission of a new operation on this subject waits
  -- for us, and so does any other reconciler.
  perform pg_advisory_xact_lock(hashtextextended(v_req.action || ':' || v_req.subject_id::text, 0));

  select * into v_terminal from public.admin_audit_log a
  where a.metadata->>'operationId' = p_operation::text
    and a.metadata->>'phase' in ('completed', 'reconciled')
  order by a.id limit 1;
  if found then
    if v_terminal.metadata->>'phase' = 'reconciled' and v_terminal.metadata->>'outcome' = p_outcome then
      -- The same answer already committed (a lost response, a double click).
      return jsonb_build_object('status', 'resolved', 'outcome', p_outcome, 'replayed', true);
    end if;
    return jsonb_build_object(
      'status', 'already_resolved',
      'phase', v_terminal.metadata->>'phase',
      'outcome', v_terminal.metadata->>'outcome'
    );
  end if;

  select max(a.id) into v_latest from public.admin_audit_log a
  where a.metadata->>'operationId' = p_operation::text;
  if p_seen_through is null or v_latest > p_seen_through then
    raise exception 'This operation changed since you opened it; reload before recording'
      using errcode = '40001';
  end if;

  if p_outcome = 'unknown' then
    insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, order_id, reason, metadata)
    values (v_actor, 'operation.reconcile', v_req.subject_type, v_req.subject_id, v_req.order_id, p_reason,
      jsonb_build_object('operationId', p_operation::text, 'phase', 'escalated', 'outcome', 'unknown',
        'reconciles', v_req.action));
    return jsonb_build_object('status', 'escalated', 'outcome', 'unknown', 'replayed', false);
  end if;

  -- Which durable money records can answer for this operation?
  if v_req.action = 'order.force_refund' then
    v_order := v_req.subject_id;
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', r.id, 'status', r.status, 'providerStatus', r.provider_status,
             'refundReference', r.refund_reference, 'amountCents', r.amount_cents)
             order by r.created_at), '[]'::jsonb),
           coalesce(bool_or(r.status in ('requested', 'provider_pending', 'provider_succeeded', 'effects_pending', 'recovery_required')), false),
           coalesce(bool_or(r.status in ('reversal_pending', 'completed')), false),
           count(*) > 0
      into v_ops, v_running, v_applied, v_any
    from public.refund_operations r
    where r.order_id = v_order
      and r.created_at >= v_req.created_at
      and r.requested_by = 'admin:' || v_req.actor_id::text;
  elsif v_req.action = 'recovery.replace_refund' then
    select pr.order_id into v_order from public.payment_recoveries pr where pr.id = v_req.subject_id;
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', r.id, 'status', r.status, 'providerStatus', r.provider_status,
             'refundReference', r.refund_reference, 'amountCents', r.amount_cents)
             order by r.created_at), '[]'::jsonb),
           coalesce(bool_or(r.status in ('requested', 'provider_pending', 'provider_succeeded', 'effects_pending', 'recovery_required')), false),
           coalesce(bool_or(r.status in ('reversal_pending', 'completed')), false),
           count(*) > 0
      into v_ops, v_running, v_applied, v_any
    from public.refund_operations r
    where r.order_id = v_order
      and r.created_at >= v_req.created_at
      and r.replaces_adjustment_id is not null;
  end if;

  if v_order is not null then
    if v_running then
      raise exception 'A refund from this operation is still being processed. Let the payment worker finish it (or work its recovery case), then record the outcome.'
        using errcode = '55000';
    end if;
    if p_outcome = 'applied' and not v_applied then
      raise exception 'No completed refund from this operation is recorded. Check again, or record it as unknown so it stays blocked.'
        using errcode = '55000';
    end if;
    if p_outcome = 'not_applied' and v_applied then
      raise exception 'A completed refund from this operation is recorded. Record it as applied.'
        using errcode = '55000';
    end if;
    if p_outcome = 'not_applied' and not v_any and v_req.created_at > now() - v_lease then
      raise exception 'This operation was requested under 15 minutes ago and may still be running. Check again later.'
        using errcode = '55000';
    end if;
    v_evidence := jsonb_build_object('source', 'refund_operations', 'orderId', v_order,
      'operations', v_ops, 'observedAt', now());
  else
    if v_req.created_at > now() - v_lease then
      raise exception 'This operation was requested under 15 minutes ago and may still be running. Check again later.'
        using errcode = '55000';
    end if;
    v_evidence := jsonb_build_object('source', 'operator', 'observedAt', now(),
      'note', 'No durable money record is linked to this action; the outcome is the operator''s account.');
  end if;

  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, order_id, reason, metadata)
  values (v_actor, 'operation.reconcile', v_req.subject_type, v_req.subject_id, v_req.order_id, p_reason,
    jsonb_build_object('operationId', p_operation::text, 'phase', 'reconciled', 'outcome', p_outcome,
      'reconciles', v_req.action, 'evidence', v_evidence, 'seenThrough', p_seen_through));
  return jsonb_build_object('status', 'resolved', 'outcome', p_outcome, 'evidence', v_evidence, 'replayed', false);
end;
$$;


--
-- Name: record_admin_export(text, text, jsonb, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_admin_export(p_phase text, p_view text DEFAULT NULL::text, p_filters jsonb DEFAULT '{}'::jsonb, p_export uuid DEFAULT NULL::uuid, p_rows integer DEFAULT NULL::integer, p_detail text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_started public.admin_audit_log%rowtype;
  v_export uuid;
begin
  if v_actor is null or not public.is_admin() then
    raise exception 'An admin session is required to export' using errcode = '42501';
  end if;

  if p_phase = 'started' then
    if p_export is not null then
      raise exception 'A new export takes no id' using errcode = '22023';
    end if;
    if p_view is null or p_view not in ('orders', 'disputes_open', 'disputes_resolved', 'audit') then
      raise exception 'Unknown export view %', p_view using errcode = '22023';
    end if;
    if p_filters is null or jsonb_typeof(p_filters) <> 'object' or length(p_filters::text) > 4000 then
      raise exception 'Export filters must be an object of at most 4,000 characters' using errcode = '22023';
    end if;
    v_export := gen_random_uuid();
    insert into public.admin_audit_log (actor_id, action, subject_type, subject_id, reason, metadata)
    values (v_actor, 'export.started', 'export', v_export,
            'CSV export: ' || replace(p_view, '_', ' '),
            jsonb_build_object('phase', 'started', 'view', p_view, 'filters', p_filters, 'role', public.admin_role()));
    return v_export;
  end if;

  if p_phase is null or p_phase not in ('completed', 'failed') then
    raise exception 'Unknown export phase %', p_phase using errcode = '22023';
  end if;
  if p_export is null then
    raise exception 'Which export finished?' using errcode = '22023';
  end if;
  if p_phase = 'completed' and (p_rows is null or p_rows < 0) then
    raise exception 'A completed export records its row count' using errcode = '22023';
  end if;

  -- One finishing row per export, however many callers race.
  perform pg_advisory_xact_lock(hashtextextended('drvn-export:' || p_export::text, 0));
  select * into v_started from public.admin_audit_log a
   where a.subject_type = 'export' and a.subject_id = p_export and a.action = 'export.started'
     and a.actor_id = v_actor
   limit 1;
  if not found then
    raise exception 'No export of yours with that id was started' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.admin_audit_log a
              where a.subject_type = 'export' and a.subject_id = p_export
                and a.action in ('export.completed', 'export.failed')) then
    raise exception 'That export is already recorded as finished' using errcode = '55000';
  end if;

  insert into public.admin_audit_log (actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'export.' || p_phase, 'export', p_export, v_started.reason,
          (v_started.metadata - 'phase') || jsonb_strip_nulls(jsonb_build_object(
            'phase', p_phase,
            'rows', p_rows,
            'detail', left(nullif(trim(coalesce(p_detail, '')), ''), 500),
            'startedAt', v_started.created_at)));
  return p_export;
end;
$$;


--
-- Name: record_capture_recovery(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_capture_recovery(p_key text, p_detail text, p_amount integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result uuid;
begin
 if length(p_key)>250 or length(p_key)<3 then raise exception 'Invalid recovery identity'; end if;
 insert into public.payment_recoveries(kind,recovery_key,detail,amount_cents)
 values('capture_unresolved',p_key,left(p_detail,1000),p_amount)
 on conflict(recovery_key) do update set last_seen_at=now()
 returning id into result;
 return result;
end $$;


--
-- Name: record_delivery_proof(uuid, text, text, text[], timestamp with time zone, text, text, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_delivery_proof(p_shipment uuid, p_destination_match text, p_verdict text, p_reasons text[], p_carrier_delivered_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_destination_postcode text DEFAULT NULL::text, p_destination_city text DEFAULT NULL::text, p_first_scan_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_signed_by text DEFAULT NULL::text, p_evidence_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  s public.shipments;
  o public.orders;
  v_verdict text := p_verdict;
  v_reasons text[] := coalesce(p_reasons, '{}'::text[]);
  v_existing public.delivery_proofs;
begin
  if p_shipment is null or p_verdict not in ('verified', 'review')
     or p_destination_match not in ('postcode', 'city', 'mismatch', 'missing') then
    raise exception 'Invalid delivery proof' using errcode = '22023';
  end if;
  select * into s from public.shipments where id = p_shipment for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_shipment'); end if;
  if s.direction <> 'outbound' or s.status <> 'delivered' then
    return jsonb_build_object('ok', false, 'reason', 'not_delivered');
  end if;
  select * into strict o from public.orders where id = s.order_id;

  -- Freshness: evidence older than what is on record never replaces it (a
  -- delayed webhook after a verified delivery). Undated evidence only
  -- replaces undated evidence, such as a backfilled review record.
  select * into v_existing from public.delivery_proofs where shipment_id = s.id;
  if found and v_existing.evidence_at is not null
     and (p_evidence_at is null or p_evidence_at < v_existing.evidence_at) then
    return jsonb_build_object('ok', true, 'stale', true, 'verdict', v_existing.verdict,
      'reasons', to_jsonb(v_existing.reasons));
  end if;

  <<attempt>>
  loop
    begin
      insert into public.delivery_proofs as p (
        shipment_id, order_id, carrier, tracking_code, carrier_delivered_at, destination_postcode,
        destination_city, first_scan_at, signed_by, evidence_at, order_postcode, order_city, order_country,
        order_created_at, deliver_by, signature_required, destination_match, verdict, reasons
      ) values (
        s.id, o.id, s.carrier, s.tracking_code, p_carrier_delivered_at,
        nullif(left(btrim(p_destination_postcode), 40), ''), nullif(left(btrim(p_destination_city), 120), ''),
        p_first_scan_at, nullif(left(btrim(p_signed_by), 200), ''), p_evidence_at,
        o.ship_postcode, o.ship_city, o.ship_country, o.created_at, o.deliver_by,
        o.total_cents >= 75000, p_destination_match, v_verdict, v_reasons
      )
      on conflict (shipment_id) do update set
        carrier = excluded.carrier,
        tracking_code = excluded.tracking_code,
        carrier_delivered_at = excluded.carrier_delivered_at,
        destination_postcode = excluded.destination_postcode,
        destination_city = excluded.destination_city,
        first_scan_at = excluded.first_scan_at,
        signed_by = excluded.signed_by,
        evidence_at = excluded.evidence_at,
        order_postcode = excluded.order_postcode,
        order_city = excluded.order_city,
        order_country = excluded.order_country,
        order_created_at = excluded.order_created_at,
        deliver_by = excluded.deliver_by,
        signature_required = excluded.signature_required,
        destination_match = excluded.destination_match,
        verdict = excluded.verdict,
        reasons = excluded.reasons,
        evaluated_at = now();
      exit attempt;
    exception when check_violation then
      if v_verdict = 'review' then raise; end if;
      -- The app said verified; the order's own facts don't support it.
      v_verdict := 'review';
      v_reasons := array['evidence_check_failed'];
    end;
  end loop;

  return jsonb_build_object('ok', true, 'verdict', v_verdict, 'reasons', to_jsonb(v_reasons));
end $$;


--
-- Name: record_dispute_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_dispute_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.order_dispute_history (
    order_id, event, kind, category, reason, opened_at, opened_by, respond_by, escalate_until,
    escalated_at, escalated_by, pre_dispute_status, stripe_dispute_id, resolved_at, outcome,
    resolved_to_status
  ) values (
    new.id, 'resolved',
    case when old.stripe_dispute_id is not null
          and old.dispute_reason like 'Card dispute % — ' || old.stripe_dispute_id then 'chargeback' else 'in_app' end,
    old.dispute_category, old.dispute_reason, old.disputed_at, old.disputed_by,
    old.dispute_respond_by, old.dispute_escalate_until, old.dispute_escalated_at,
    old.dispute_escalated_by, old.pre_dispute_status, old.stripe_dispute_id,
    coalesce(new.dispute_resolved_at, now()), new.dispute_outcome, new.status
  );
  return new;
end $$;


--
-- Name: record_listing_edit(uuid, text, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_listing_edit(p_request uuid, p_payload_hash text, p_listing uuid, p_expected_updated_at timestamp with time zone, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_inserted integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_request is null or coalesce(p_payload_hash, '') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_result) is distinct from 'object' then
    raise exception 'Invalid listing edit request' using errcode = '22023';
  end if;
  -- 20261007100300: only from inside save_listing_edit, in its transaction.
  if coalesce(current_setting('drvn.listing_edit_request', true), '') is distinct from p_request::text then
    raise exception 'An edit outcome is recorded only by the edit itself' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.listings l
    where l.id = p_listing and l.seller_id = v_actor
      and l.updated_at = (p_result->>'updated_at')::timestamptz
  ) then
    raise exception 'Edit outcome does not match the listing' using errcode = '22023';
  end if;

  delete from private.listing_edit_requests r
  where r.seller_id = v_actor and r.created_at < now() - interval '7 days';

  insert into private.listing_edit_requests(
    seller_id, request_id, listing_id, expected_updated_at, payload_hash, result
  ) values (v_actor, p_request, p_listing, p_expected_updated_at, p_payload_hash, p_result)
  on conflict (seller_id, request_id) do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 0 then
    raise exception 'This edit request was already used' using errcode = '22023';
  end if;
end;
$_$;


--
-- Name: record_listing_view(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_listing_view(p_listing uuid, p_arrival text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_counted int;
  v_arrival text := case
    when p_arrival in ('car', 'post', 'profile', 'store', 'marketplace', 'explore', 'home', 'front',
                       'saved', 'listing', 'agent', 'other', 'external', 'direct') then p_arrival
    else 'other'
  end;
begin
  if (select auth.uid()) is null or p_listing is null then
    return false;
  end if;

  -- Same rule as bump_listing_view: one counted view per member per
  -- listing per hour, and the same key, so the two never double count.
  if not public.consume_rate_limit(
       'view:' || p_listing::text || ':' || (select auth.uid())::text, 1, interval '1 hour'
     ) then
    return false;
  end if;

  update public.listings
     set view_count = coalesce(view_count, 0) + 1
   where id = p_listing and status in ('active', 'sold') and seller_id <> (select auth.uid());
  get diagnostics v_counted = row_count;
  if v_counted = 0 then
    return false;
  end if;

  insert into public.listing_view_arrivals as a (listing_id, day, arrival, views)
  values (p_listing, (now() at time zone 'utc')::date, v_arrival, 1)
  on conflict (listing_id, day, arrival) do update set views = a.views + 1;
  return true;
end;
$$;


--
-- Name: FUNCTION record_listing_view(p_listing uuid, p_arrival text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_listing_view(p_listing uuid, p_arrival text) IS 'OS-R-arrival: counts a member''s view of a listing (bump_listing_view''s rules) and the surface it arrived from.';


--
-- Name: record_offer_round(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_offer_round() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_seller uuid;
  v_kind text;
  v_role text;
  v_actor uuid;
  v_amount integer;
  v_expires timestamptz;
  v_round uuid;
  v_no integer;
begin
  -- offer_open / offer_move write their own rounds (20261017160000).
  if current_setting('drvn.offer_move', true) = 'on' then return null; end if;
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return null;
  end if;
  select l.seller_id into v_seller from public.listings l where l.id = new.listing_id;

  if tg_op = 'INSERT' then
    v_kind := 'offer'; v_role := 'buyer'; v_actor := new.buyer_id;
    v_amount := new.amount_cents; v_expires := new.expires_at;
  elsif new.status = 'countered' then
    v_kind := 'counter'; v_role := 'seller'; v_actor := v_seller;
    v_amount := new.counter_amount_cents; v_expires := new.expires_at;
  elsif new.status = 'accepted' then
    -- The seller accepts the buyer's amount; the buyer accepts a counter.
    v_kind := 'accept';
    if old.status = 'countered' then v_role := 'buyer'; v_actor := new.buyer_id;
    else v_role := 'seller'; v_actor := v_seller; end if;
    v_amount := coalesce(new.counter_amount_cents, new.amount_cents);
  elsif new.status = 'declined' then
    v_kind := 'decline'; v_role := 'seller'; v_actor := v_seller;
  elsif new.status = 'withdrawn' then
    v_kind := 'withdraw'; v_role := 'buyer'; v_actor := new.buyer_id;
  elsif new.status = 'expired' then
    v_kind := 'expire'; v_role := 'system'; v_actor := null;
  else
    return null;
  end if;

  -- One writer per offer at a time: the offer row is already locked by the
  -- statement that fired this trigger.
  select coalesce(max(r.round_no), 0) + 1 into v_no from public.offer_rounds r where r.offer_id = new.id;
  insert into public.offer_rounds(offer_id, round_no, listing_id, buyer_id, actor_role, kind, amount_cents, expires_at, actor_member_id)
  values (new.id, v_no, new.listing_id, new.buyer_id, v_role, v_kind, v_amount, v_expires, v_actor)
  returning id into v_round;
  update public.offers set round_count = v_no, last_round_id = v_round where id = new.id;

  -- A proposal (opening offer or counter) keeps the seller's minimum in force
  -- at the time, so a later change can't rewrite what was agreed.
  if v_kind in ('offer', 'counter') then
    insert into public.offer_round_terms(round_id, effective_floor_cents)
    select v_round, t.offer_floor_cents from public.listing_private_terms t where t.listing_id = new.listing_id;
  end if;
  return null;
end;
$$;


--
-- Name: record_outbound_label_void_observation(uuid, uuid, text, text, integer, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_outbound_label_void_observation(p_shipment uuid, p_worker uuid, p_source text, p_state text, p_attempt integer, p_observed_at timestamp with time zone, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  request_order uuid;
  saved public.outbound_label_void_requests;
  result jsonb;
begin
  if p_attempt is null or p_observed_at is null or p_observed_at>now()+interval '1 minute' then
    raise exception 'Invalid outbound label void observation epoch';
  end if;
  select order_id into strict request_order from public.outbound_label_void_requests
  where shipment_id=p_shipment;
  perform 1 from public.orders where id=request_order for update;
  if not found then raise exception 'Outbound label void order is missing'; end if;
  perform 1 from public.shipments where id=p_shipment for update;
  if not found then raise exception 'Outbound label void shipment is missing'; end if;
  select * into strict saved from public.outbound_label_void_requests
  where shipment_id=p_shipment for update;
  if saved.attempts<>p_attempt then
    raise exception 'Outbound label void observation belongs to a stale attempt' using errcode='42501';
  end if;
  result:=public.record_outbound_label_void_observation_unfenced(
    p_shipment,p_worker,p_source,p_state,p_detail
  );
  update public.outbound_label_void_requests set provider_observed_at=p_observed_at
  where shipment_id=p_shipment;
  return result;
end $$;


--
-- Name: record_outbound_label_void_observation_unfenced(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_outbound_label_void_observation_unfenced(p_shipment uuid, p_worker uuid, p_source text, p_state text, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  saved public.outbound_label_void_requests;
  s public.shipments;
  o public.orders;
  original public.seller_adjustments;
  reversal public.seller_adjustments;
begin
  if p_worker is null or p_source is null or p_source not in ('dispatch','reconcile')
     or p_state is null or p_state not in ('not_requested','submitted','refunded','rejected','unknown') then
    raise exception 'Invalid outbound label void observation';
  end if;
  select * into strict saved from public.outbound_label_void_requests where shipment_id=p_shipment;
  select * into strict o from public.orders where id=saved.order_id for update;
  select * into strict s from public.shipments where id=p_shipment for update;
  select * into strict saved from public.outbound_label_void_requests where shipment_id=p_shipment for update;
  if p_source='dispatch' and saved.claim_owner is distinct from p_worker then
    raise exception 'Outbound label void worker does not own provider dispatch' using errcode='42501';
  end if;
  if p_source='dispatch' and p_state='not_requested' then
    raise exception 'A dispatch response cannot prove no request exists';
  end if;
  if saved.status='completed' then
    if p_state<>'refunded' then raise exception 'Completed label void cannot regress'; end if;
    return jsonb_build_object('state','refunded','replayed',true);
  elsif saved.status='rejected' then
    if p_state<>'rejected' then raise exception 'Rejected label void cannot change outcome'; end if;
    return jsonb_build_object('state','rejected','replayed',true);
  elsif saved.status<>'provider_pending' then
    raise exception 'Outbound label void has not been claimed';
  end if;
  if saved.order_id<>o.id or saved.seller_id is distinct from o.seller_id or s.order_id<>o.id
     or saved.provider is distinct from s.provider
     or saved.provider_shipment_reference is distinct from s.provider_shipment_id
     or saved.amount_cents is distinct from s.purchased_cents or upper(saved.currency)<>upper(o.currency) then
    raise exception 'Outbound label void identity changed';
  end if;
  if p_state in ('not_requested','submitted','unknown') then
    update public.outbound_label_void_requests
    set provider_state=p_state,provider_observed_at=now(),last_error=left(p_detail,500),updated_at=now()
    where shipment_id=p_shipment returning * into saved;
    return jsonb_build_object('state','pending','request',to_jsonb(saved));
  elsif p_state='rejected' then
    update public.outbound_label_void_requests
    set status='rejected',provider_state='rejected',provider_observed_at=now(),rejected_at=now(),
        claim_owner=null,claim_expires_at=null,last_error=left(p_detail,500),updated_at=now()
    where shipment_id=p_shipment;
    delete from public.admin_alert_outbox where dedup_key='outbound-label-void:'||p_shipment and status='pending';
    return jsonb_build_object('state','rejected','replayed',false);
  end if;
  if s.status<>'label_purchased' then raise exception 'Outbound shipment is no longer voidable'; end if;
  select * into strict original from public.seller_adjustments
  where kind='outbound_label' and external_reference='label:'||s.id;
  if original.seller_id is distinct from saved.seller_id or original.order_id is distinct from saved.order_id
     or original.shipment_id is distinct from saved.shipment_id or original.return_id is not null
     or original.amount_cents<>-saved.amount_cents or upper(original.currency)<>upper(saved.currency)
     or original.voided_at is not null then raise exception 'Outbound label purchase adjustment changed'; end if;
  if saved.amount_cents>0 then
    insert into public.seller_adjustments(
      seller_id,order_id,shipment_id,kind,amount_cents,currency,external_reference,description
    ) values(
      saved.seller_id,saved.order_id,saved.shipment_id,'label_refund',saved.amount_cents,
      saved.currency,'label:'||saved.shipment_id||':refund','Label voided/refunded'
    ) on conflict(kind,external_reference) where external_reference is not null do nothing;
    select * into strict reversal from public.seller_adjustments
    where kind='label_refund' and external_reference='label:'||saved.shipment_id||':refund';
    if reversal.seller_id is distinct from saved.seller_id or reversal.order_id is distinct from saved.order_id
       or reversal.shipment_id is distinct from saved.shipment_id or reversal.return_id is not null
       or reversal.amount_cents<>saved.amount_cents or upper(reversal.currency)<>upper(saved.currency)
       or reversal.voided_at is not null then raise exception 'Outbound label refund adjustment conflicts'; end if;
  elsif exists(
    select 1 from public.seller_adjustments
    where kind='label_refund' and external_reference='label:'||saved.shipment_id||':refund'
  ) then raise exception 'Zero-cost outbound label has a conflicting refund adjustment'; end if;
  update public.shipments set status='cancelled' where id=s.id;
  update public.outbound_label_void_requests
  set status='completed',provider_state='refunded',provider_observed_at=now(),completed_at=now(),
      claim_owner=null,claim_expires_at=null,last_error=null,updated_at=now()
  where shipment_id=s.id;
  delete from public.admin_alert_outbox where dedup_key='outbound-label-void:'||s.id and status='pending';
  return jsonb_build_object('state','refunded','replayed',false);
end $$;


--
-- Name: record_payment_reference(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_reference(p_key text, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare saved_request jsonb;
begin
 update public.payment_requests set provider_reference=p_reference where operation_key=p_key and (provider_reference is null or provider_reference=p_reference) returning request into saved_request;
 if not found then raise exception 'Payment reference conflict'; end if;
 -- Persist the order mapping before returning a client secret or processing
 -- result. A crash in the caller cannot strand an already-created intent.
 if exists(select 1 from public.payments where order_id::text in (select jsonb_array_elements_text(saved_request->'orderIds')) and provider_reference is not null and provider_reference<>p_reference) then raise exception 'Order payment reference conflict'; end if;
 update public.payments set provider='stripe',provider_reference=p_reference
 where order_id::text in (select jsonb_array_elements_text(saved_request->'orderIds'));
end $$;


--
-- Name: record_payment_request_rejection(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_request_rejection(p_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.payment_requests;
  v_order uuid;
  v_result jsonb;
  v_released int := 0;
  v_reason text := left(coalesce(nullif(trim(p_reason), ''), 'Payment provider refused the request'), 500);
begin
  -- One lock order for every path that sells a listing: listing → offer →
  -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
  perform 1 from public.listings where id in (
    select oi.listing_id from public.order_items oi
    where oi.listing_id is not null and oi.order_id::text in (
      select jsonb_array_elements_text(request->'orderIds') from public.payment_requests where operation_key = p_key)
  ) order by id for update;
  -- Same lock order as prepare_payment_request: orders, then the request.
  perform 1 from public.orders
  where id::text in (
    select jsonb_array_elements_text(request->'orderIds')
    from public.payment_requests where operation_key = p_key
  )
  order by id for update;
  select * into r from public.payment_requests where operation_key = p_key for update;
  if not found then
    raise exception 'Payment request not found' using errcode = 'P0002';
  end if;
  -- Any recorded reference means a PaymentIntent may exist. Never release.
  if r.provider_reference is not null or exists(
    select 1 from public.payments
    where order_id::text in (select jsonb_array_elements_text(r.request->'orderIds'))
      and provider_reference is not null
  ) then
    raise exception 'Payment request has a provider reference; reconcile it instead'
      using errcode = '55000';
  end if;

  update public.payment_requests
  set provider_rejected_at = coalesce(provider_rejected_at, now()),
      provider_rejection = coalesce(provider_rejection, v_reason)
  where operation_key = p_key;

  for v_order in
    select o.id from public.orders o
    where o.id::text in (select jsonb_array_elements_text(r.request->'orderIds'))
      and o.status in ('pending', 'requires_action')
    order by o.id
  loop
    v_result := public.purchase_finalize(v_order, false, 'stripe', null, v_reason);
    if coalesce((v_result->>'applied')::boolean, false) then
      v_released := v_released + 1;
    end if;
  end loop;

  return jsonb_build_object('rejected', true, 'released', v_released);
end;
$$;


--
-- Name: record_refund_provider_event(text, text, uuid, uuid, text, integer, text, text, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_refund_provider_event(p_event_id text, p_refund_reference text, p_operation_id uuid, p_order_id uuid, p_payment_reference text, p_amount_cents integer, p_currency text, p_provider_status text, p_provider_created_at timestamp with time zone, p_balance_transaction text DEFAULT NULL::text, p_failure_balance_transaction text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_pending_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op public.refund_operations;
  v_order public.orders;
  v_payment public.payments;
  v_existing_event public.refund_provider_events;
  v_inflight int;
  v_remaining int;
  v_after int;
  v_fee_after int;
  v_fee_restore int;
  v_seller_recredit int;
  v_recovery_id uuid;
  v_adjustment_id uuid;
  v_known_order uuid;
begin
  if p_event_id is null or length(p_event_id) < 3
     or p_refund_reference is null or length(p_refund_reference) < 3
     or p_amount_cents is null or p_amount_cents <= 0
     or p_currency is null or p_provider_created_at is null
     or p_provider_status is null
     or p_provider_status not in ('pending','requires_action','succeeded','failed','canceled','unknown') then
    raise exception 'Invalid refund provider event';
  end if;

  -- 20261010100000: the order a refund names is provider metadata and may not
  -- exist here. Only an order that does is stored in an order_id column; the
  -- reported value is kept as reported_order_id either way.
  select id into v_known_order from public.orders where id = p_order_id;

  select * into v_existing_event
  from public.refund_provider_events where event_id = p_event_id;
  if found then
    if v_existing_event.refund_reference <> p_refund_reference
       or v_existing_event.payment_reference is distinct from p_payment_reference
       or v_existing_event.amount_cents <> p_amount_cents
       or lower(v_existing_event.currency) <> lower(p_currency)
       or v_existing_event.provider_status <> p_provider_status
       or v_existing_event.provider_created_at <> p_provider_created_at
       or v_existing_event.balance_transaction is distinct from p_balance_transaction
       or v_existing_event.failure_balance_transaction is distinct from p_failure_balance_transaction
       or v_existing_event.failure_reason is distinct from p_failure_reason
       or v_existing_event.reported_operation_id is distinct from p_operation_id
       or v_existing_event.reported_order_id is distinct from p_order_id then
      raise exception 'Refund event replay payload changed';
    end if;
    if v_existing_event.refund_operation_id is null then
      return jsonb_build_object('action','recovery_recorded','replayed',true);
    end if;
    select * into v_op from public.refund_operations
      where id = v_existing_event.refund_operation_id;
    if not found then raise exception 'Recorded refund event lost its operation'; end if;
    return jsonb_build_object(
      'action', case
        when v_op.provider_status in ('failed','canceled') or v_op.status = 'recovery_required'
          then 'recovery_recorded'
        when v_op.provider_status in ('pending','requires_action','unknown')
          then 'pending'
        when v_op.provider_status = 'succeeded'
             and v_op.status in ('provider_succeeded','effects_pending','reversal_pending')
          then 'settle'
        else 'committed'
      end,
      'operation_id', v_op.id,
      'replayed', true
    );
  end if;

  if p_operation_id is not null then
    select * into v_op from public.refund_operations where id = p_operation_id for update;
  else
    select * into v_op from public.refund_operations
      where refund_reference = p_refund_reference for update;
  end if;

  if not found and p_operation_id is not null then
    insert into public.refund_provider_events(
      event_id,refund_reference,reported_operation_id,payment_reference,order_id,
      reported_order_id,amount_cents,currency,
      provider_status,provider_created_at,balance_transaction,
      failure_balance_transaction,failure_reason
    ) values (
      p_event_id,p_refund_reference,p_operation_id,p_payment_reference,v_known_order,
      p_order_id,p_amount_cents,p_currency,
      p_provider_status,p_provider_created_at,p_balance_transaction,
      p_failure_balance_transaction,p_failure_reason
    );
    insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
    values(
      'refund_lifecycle_unresolved','refund-lifecycle:'||p_refund_reference,
      v_known_order,p_amount_cents,
      'Refund '||p_refund_reference||' references an unknown local operation.'
    )
    on conflict(recovery_key) do update set
      last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
      status='open', resolved_by=null, resolved_at=null, resolution_note=null;
    return jsonb_build_object('action','recovery_recorded','reason','unknown_operation');
  end if;

  if found then
    if v_op.payment_reference is distinct from p_payment_reference
       or v_op.amount_cents <> p_amount_cents
       or lower(v_op.currency) <> lower(p_currency)
       or (p_order_id is not null and v_op.order_id <> p_order_id)
       or not exists (
         select 1 from public.payments
         where order_id=v_op.order_id and provider_reference=p_payment_reference
       )
       or (v_op.refund_reference is not null and v_op.refund_reference <> p_refund_reference) then
      insert into public.refund_provider_events(
        event_id,refund_reference,reported_operation_id,payment_reference,order_id,
        reported_order_id,amount_cents,currency,
        provider_status,provider_created_at,balance_transaction,
        failure_balance_transaction,failure_reason
      ) values (
        p_event_id,p_refund_reference,p_operation_id,p_payment_reference,v_known_order,
        p_order_id,p_amount_cents,p_currency,
        p_provider_status,p_provider_created_at,p_balance_transaction,
        p_failure_balance_transaction,p_failure_reason
      );
      insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
      values(
        'refund_lifecycle_unresolved','refund-lifecycle:'||p_refund_reference,
        v_known_order,p_amount_cents,
        'Refund '||p_refund_reference||' does not match the referenced local operation.'
      )
      on conflict(recovery_key) do update set
        last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
        status='open', resolved_by=null, resolved_at=null, resolution_note=null;
      return jsonb_build_object('action','recovery_recorded','reason','operation_mismatch');
    end if;
  else
    if v_known_order is null then
      insert into public.refund_provider_events(
        event_id,refund_reference,reported_operation_id,payment_reference,
        reported_order_id,amount_cents,currency,
        provider_status,provider_created_at,balance_transaction,
        failure_balance_transaction,failure_reason
      ) values (
        p_event_id,p_refund_reference,p_operation_id,p_payment_reference,
        p_order_id,p_amount_cents,p_currency,
        p_provider_status,p_provider_created_at,p_balance_transaction,
        p_failure_balance_transaction,p_failure_reason
      );
      insert into public.payment_recoveries(kind,recovery_key,amount_cents,detail)
      values(
        'refund_lifecycle_unresolved','refund-lifecycle:'||p_refund_reference,
        p_amount_cents,'Refund '||p_refund_reference||' has no safe local order attribution.'
      )
      on conflict(recovery_key) do update set
        last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
        status='open', resolved_by=null, resolved_at=null, resolution_note=null;
      return jsonb_build_object('action','recovery_recorded','reason','missing_mapping');
    end if;

    select * into v_order from public.orders where id = p_order_id for update;
    if not found then raise exception 'Refund order mapping disappeared'; end if;
    select * into v_payment from public.payments
      where order_id = p_order_id and provider_reference = p_payment_reference
      limit 1;
    if not found or lower(v_order.currency) <> lower(p_currency) then
      insert into public.refund_provider_events(
        event_id,refund_reference,reported_operation_id,payment_reference,order_id,
        reported_order_id,amount_cents,currency,
        provider_status,provider_created_at,balance_transaction,
        failure_balance_transaction,failure_reason
      ) values (
        p_event_id,p_refund_reference,p_operation_id,p_payment_reference,p_order_id,
        p_order_id,p_amount_cents,p_currency,
        p_provider_status,p_provider_created_at,p_balance_transaction,
        p_failure_balance_transaction,p_failure_reason
      );
      insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
      values(
        'refund_lifecycle_unresolved','refund-lifecycle:'||p_refund_reference,
        p_order_id,p_amount_cents,
        'Refund '||p_refund_reference||' payment or currency does not match the local order.'
      )
      on conflict(recovery_key) do update set
        last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
        status='open', resolved_by=null, resolved_at=null, resolution_note=null;
      return jsonb_build_object('action','recovery_recorded','reason','payment_mismatch');
    end if;

    select coalesce(sum(amount_cents),0) into v_inflight
    from public.refund_operations
    where order_id=p_order_id and status in (
      'requested','provider_pending','provider_succeeded','effects_pending',
      'reversal_pending','recovery_required'
    )
    -- 20261007100200: only what is not yet in refunded_cents.
    and effects_completed_at is null;
    v_remaining := v_order.total_cents - v_order.refunded_cents - v_inflight;
    if p_amount_cents > v_remaining or exists(select 1 from public.payment_recoveries where order_id=p_order_id and kind='refund_late_failure' and status='open') then
      insert into public.refund_provider_events(
        event_id,refund_reference,reported_operation_id,payment_reference,order_id,
        reported_order_id,amount_cents,currency,
        provider_status,provider_created_at,balance_transaction,
        failure_balance_transaction,failure_reason
      ) values (
        p_event_id,p_refund_reference,p_operation_id,p_payment_reference,p_order_id,
        p_order_id,p_amount_cents,p_currency,
        p_provider_status,p_provider_created_at,p_balance_transaction,
        p_failure_balance_transaction,p_failure_reason
      );
      insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
      values(
        'refund_lifecycle_unresolved','refund-lifecycle:'||p_refund_reference,
        p_order_id,p_amount_cents,
        'Refund '||p_refund_reference||' cannot be safely allocated: the unreserved balance is insufficient or a late-refund replacement recovery is open.'
      )
      on conflict(recovery_key) do update set
        last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
        status='open', resolved_by=null, resolved_at=null, resolution_note=null;
      return jsonb_build_object('action','recovery_recorded','reason','amount_mismatch');
    end if;

    insert into public.refund_operations(
      order_id,payment_reference,amount_cents,currency,remaining_before_cents,
      reason,requested_by,actor_role,idempotency_key,refund_reference,status,
      external,resolve_dispute,dispute_outcome,provider_status,
      provider_failure_reason,provider_balance_transaction,
      provider_failure_balance_transaction,provider_pending_reason,
      provider_event_created_at,provider_event_id
    ) values (
      p_order_id,p_payment_reference,p_amount_cents,v_order.currency,v_remaining,
      'Stripe refund '||p_refund_reference,'stripe:webhook','system',
      'stripe:external:'||p_refund_reference,p_refund_reference,
      case when p_provider_status='succeeded' then 'provider_succeeded'
           else 'provider_pending' end,
      true,true,'chargeback_lost',null,null,
      null,null,null,
      null,null
    ) returning * into v_op;
  end if;

  insert into public.refund_provider_events(
    event_id,refund_reference,refund_operation_id,reported_operation_id,payment_reference,order_id,
    reported_order_id,amount_cents,currency,provider_status,provider_created_at,balance_transaction,
    failure_balance_transaction,failure_reason
  ) values (
    p_event_id,p_refund_reference,v_op.id,p_operation_id,p_payment_reference,v_op.order_id,
    p_order_id,p_amount_cents,p_currency,p_provider_status,p_provider_created_at,
    p_balance_transaction,p_failure_balance_transaction,p_failure_reason
  );

  -- A terminal provider failure never regresses. Older callbacks are retained
  -- above, but do not change the current operation state.
  if v_op.provider_status in ('failed','canceled') then
    return jsonb_build_object('action','recovery_recorded','operation_id',v_op.id,'stale',true);
  end if;
  if v_op.provider_event_created_at is not null
     and p_provider_created_at < v_op.provider_event_created_at then
    return jsonb_build_object('action','committed','operation_id',v_op.id,'stale',true);
  end if;
  if v_op.provider_status='succeeded'
     and p_provider_status in ('pending','requires_action','unknown') then
    return jsonb_build_object('action','committed','operation_id',v_op.id,'stale',true);
  end if;

  if p_provider_status in ('pending','requires_action','unknown') then
    update public.refund_operations set
      refund_reference=p_refund_reference,
      provider_status=p_provider_status,
      provider_pending_reason=p_pending_reason,
      provider_balance_transaction=p_balance_transaction,
      provider_event_created_at=p_provider_created_at,
      provider_event_id=p_event_id,
      updated_at=now(),
      status=case when status in ('requested','provider_pending') then 'provider_pending' else status end
    where id=v_op.id;
    return jsonb_build_object('action','pending','operation_id',v_op.id);
  end if;

  if p_provider_status='succeeded' then
    update public.refund_operations set
      refund_reference=p_refund_reference,
      provider_status='succeeded',
      provider_pending_reason=null,
      provider_failure_reason=null,
      provider_balance_transaction=p_balance_transaction,
      provider_failure_balance_transaction=null,
      provider_completed_at=coalesce(provider_completed_at,now()),
      provider_event_created_at=p_provider_created_at,
      provider_event_id=p_event_id,
      updated_at=now(),
      status=case when status in ('requested','provider_pending') then 'provider_succeeded' else status end
    where id=v_op.id;
    return jsonb_build_object('action','settle','operation_id',v_op.id);
  end if;

  -- failed/canceled before local settlement: preserve the provider identity and
  -- release the reservation, but retain one visible obligation for the
  -- customer's unresolved refund.
  if v_op.effects_completed_at is null then
    insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
    values(
      'refund_failed','refund-failed:'||p_refund_reference,v_op.order_id,v_op.amount_cents,
      'Refund '||p_refund_reference||' '||p_provider_status||': '||coalesce(p_failure_reason,'no reason supplied')
    )
    on conflict(recovery_key) do update set
      last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
      status='open', resolved_by=null, resolved_at=null, resolution_note=null
    returning id into v_recovery_id;
    update public.refund_operations set
      status='failed', refund_reference=p_refund_reference,
      provider_status=p_provider_status,
      provider_failure_reason=left(p_failure_reason,500),
      provider_balance_transaction=p_balance_transaction,
      provider_failure_balance_transaction=p_failure_balance_transaction,
      provider_event_created_at=p_provider_created_at,provider_event_id=p_event_id,
      recovery_id=v_recovery_id,last_error=left(coalesce(p_failure_reason,p_provider_status),500),
      updated_at=now()
    where id=v_op.id;
    return jsonb_build_object('action','recovery_recorded','operation_id',v_op.id);
  end if;

  -- succeeded -> failed: compensate the exact operation once. We intentionally
  -- preserve order workflow status because the pre-refund fulfillment state is
  -- not derivable from money counters; the recovery row is the operator's
  -- explicit instruction to repair that state after review.
  select * into v_order from public.orders where id=v_op.order_id for update;
  if v_order.refunded_cents < v_op.amount_cents then
    raise exception 'Late refund failure exceeds settled refund ledger';
  end if;
  v_after := v_order.refunded_cents - v_op.amount_cents;
  v_fee_after := least(v_order.platform_fee_cents,
    round((v_after::numeric * v_order.platform_fee_cents) / greatest(v_order.total_cents,1)));
  v_fee_restore := v_order.platform_fee_refunded_cents - v_fee_after;
  v_seller_recredit := case
    when v_op.reversal_reference is not null then coalesce(v_op.reversal_due_cents,0)
    when coalesce(v_op.reversal_due_cents,0)=0 then 0
    else null
  end;

  insert into public.refund_lifecycle_adjustments(
    refund_operation_id,refund_reference,event_id,kind,refund_amount_cents,
    fee_restore_cents,seller_recredit_cents,failure_balance_transaction
  ) values (
    v_op.id,p_refund_reference,p_event_id,'provider_failure_compensation',
    v_op.amount_cents,v_fee_restore,v_seller_recredit,p_failure_balance_transaction
  )
  on conflict(refund_operation_id,kind) do nothing
  returning id into v_adjustment_id;

  if v_adjustment_id is not null then
    update public.orders set
      refunded_cents=v_after,
      platform_fee_refunded_cents=v_fee_after
    where id=v_op.order_id;
    update public.payments set
      refunded_cents=refunded_cents-v_op.amount_cents,
      status=case when refunded_cents-v_op.amount_cents<=0 then 'succeeded'
                  else 'partially_refunded' end
    where order_id=v_op.order_id and refunded_cents>=v_op.amount_cents
    returning * into v_payment;
    if not found then raise exception 'Late refund failure payment ledger mismatch'; end if;
  end if;

  insert into public.payment_recoveries(kind,recovery_key,order_id,amount_cents,detail)
  values(
    'refund_late_failure','refund-late-failure:'||p_refund_reference,v_op.order_id,
    case when coalesce(v_seller_recredit,0)>0 then v_seller_recredit else v_op.amount_cents end,
    'Refund '||p_refund_reference||' failed after local settlement. Customer remains owed '
      ||v_op.amount_cents||' '||v_op.currency||'. Seller re-credit obligation: '
      ||case when v_seller_recredit is null
             then 'unknown until the in-flight reversal is reconciled.'
             else v_seller_recredit||' cents.' end
  )
  on conflict(recovery_key) do update set
    last_seen_at=now(), detail=excluded.detail, amount_cents=excluded.amount_cents,
    status='open', resolved_by=null, resolved_at=null, resolution_note=null
  returning id into v_recovery_id;

  update public.refund_operations set
    status='recovery_required',provider_status=p_provider_status,
    provider_failure_reason=left(p_failure_reason,500),
    provider_balance_transaction=p_balance_transaction,
    provider_failure_balance_transaction=p_failure_balance_transaction,
    provider_event_created_at=p_provider_created_at,provider_event_id=p_event_id,
    recovery_id=v_recovery_id,last_error='Provider refund failed after local settlement',
    updated_at=now()
  where id=v_op.id;
  return jsonb_build_object(
    'action','recovery_recorded','operation_id',v_op.id,
    'compensated',v_adjustment_id is not null,
    'seller_recredit_cents',v_seller_recredit
  );
end;
$$;


--
-- Name: record_refund_recredit_proof(uuid, uuid, uuid, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_refund_recredit_proof(p_recovery uuid, p_adjustment uuid, p_actor uuid, p_amount integer, p_currency text, p_transfer text DEFAULT NULL::text, p_reversal text DEFAULT NULL::text, p_balance_transaction text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare recovery public.payment_recoveries%rowtype; adjustment public.refund_lifecycle_adjustments%rowtype;
 operation public.refund_operations%rowtype; existing public.refund_recredit_proofs%rowtype;
begin
 if not exists(select 1 from public.admin_users where user_id=p_actor and role='admin') then raise exception 'Administrator verification required'; end if;
 select * into strict recovery from public.payment_recoveries where id=p_recovery for update;
 select * into strict adjustment from public.refund_lifecycle_adjustments where id=p_adjustment;
 select * into strict operation from public.refund_operations where id=adjustment.refund_operation_id;
 if recovery.kind<>'refund_late_failure' or recovery.status<>'open'
 or recovery.recovery_key<>'refund-late-failure:'||adjustment.refund_reference
 or recovery.order_id is distinct from operation.order_id
 or p_amount is distinct from coalesce(adjustment.seller_recredit_cents,operation.reversal_due_cents)
 or lower(operation.currency) is distinct from p_currency
 or (operation.reversal_reference is not null and p_amount>0 and operation.reversal_reference is distinct from p_reversal)
 then raise exception 'Recredit proof does not match the immutable obligation'; end if;
 insert into public.refund_recredit_proofs(adjustment_id,recovery_id,recredit_transfer_reference,original_reversal_reference,amount_cents,currency,balance_transaction,verified_by)
 values(p_adjustment,p_recovery,p_transfer,p_reversal,p_amount,p_currency,p_balance_transaction,p_actor)
 on conflict(adjustment_id) do nothing;
 select * into strict existing from public.refund_recredit_proofs where adjustment_id=p_adjustment;
 if existing.recovery_id<>p_recovery or existing.recredit_transfer_reference is distinct from p_transfer or existing.amount_cents<>p_amount or existing.currency<>p_currency or existing.original_reversal_reference is distinct from p_reversal then raise exception 'Conflicting recredit proof'; end if;
end $$;


--
-- Name: record_seller_carry(uuid, text, integer, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_seller_carry(p_seller uuid, p_kind text, p_amount integer, p_order uuid, p_adjustment uuid, p_key text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_seller is null or p_amount is null or p_amount = 0 then
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('seller-carry:' || p_seller::text, 0));
  insert into public.seller_carry_entries (seller_id, kind, amount_cents, order_id, adjustment_id, entry_key)
  values (p_seller, p_kind, p_amount, p_order, p_adjustment, p_key)
  on conflict (entry_key) do nothing;
end;
$$;


--
-- Name: record_transfer_recovery(uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_transfer_recovery(p_order uuid, p_worker text, p_key text, p_detail text, p_amount integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_result uuid;
begin
  if p_order is null
     or p_worker is null
     or p_key is null
     or p_detail is null
     or length(p_key) < 3
     or length(p_key) > 250 then
    raise exception 'Invalid transfer recovery identity';
  end if;

  -- Take the parent lock first, matching refund settlement and transfer
  -- completion. A stale owner returns null without changing state or audit.
  perform 1 from public.orders where id = p_order for key share;
  if not found then return null; end if;

  update public.transfer_intents
  set status = 'failed',
      attempts = greatest(attempts, 8),
      next_attempt_at = null,
      last_error = left(p_detail, 500),
      locked_at = null,
      locked_by = null,
      lease_expires_at = null,
      updated_at = now()
  where order_id = p_order
    and status = 'processing'
    and locked_by = p_worker
    and lease_expires_at > now()
    and transfer_reference is null;
  if not found then return null; end if;

  insert into public.payment_recoveries (
    order_id, kind, recovery_key, amount_cents, detail
  ) values (
    p_order,
    'transfer_unresolved',
    p_key,
    p_amount,
    left(p_detail, 1000)
  )
  on conflict (recovery_key) do update
  set last_seen_at = now(),
      detail = excluded.detail,
      amount_cents = excluded.amount_cents,
      status = 'open',
      resolved_by = null,
      resolved_at = null,
      resolution_note = null
  returning id into v_result;

  return v_result;
end;
$$;


--
-- Name: record_webhook_failure(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_webhook_failure(p_id text, p_kind text, p_detail text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_attempts integer;
begin
  if p_kind is null or p_kind not in ('retry', 'error') then
    raise exception 'Unknown webhook failure kind' using errcode = '22023';
  end if;
  update public.webhook_events
     set failed_attempts = failed_attempts + 1,
         last_failed_at = now(),
         last_failure_kind = p_kind,
         last_failure_detail = left(nullif(btrim(p_detail), ''), 300)
   where id = p_id and processed_at is null
  returning failed_attempts into v_attempts;
  return v_attempts;
end;
$$;


--
-- Name: record_worker_run(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_worker_run(p_id uuid, p_family text, p_status text, p_summary jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if p_status='running' then insert into public.worker_runs(id,family) values(p_id,p_family);
 else update public.worker_runs set finished_at=now(),status=p_status,summary=p_summary where id=p_id and family=p_family and status='running';
 if not found then raise exception 'Unknown worker run'; end if; end if;
end $$;


--
-- Name: refresh_explore_builders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_explore_builders() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Every eligible builder's public cars (with a cover) and the published
  -- updates on them; each update is on one car, so counting the updates
  -- per owner equals the old count(distinct). Updates are counted per car
  -- in one pass, not looked up car by car (at 2M parts that was 3.6M reads
  -- from disk). The top 2,000, so a member who follows many builders still
  -- gets a full list.
  delete from public.explore_builder_rankings;
  insert into public.explore_builder_rankings (rank, profile_id, car_count, update_count)
  select row_number() over (order by s.car_count desc, s.update_count desc, s.owner_id), s.owner_id, s.car_count, s.update_count
  from (
    select c.owner_id, count(*) as car_count, coalesce(sum(u.n), 0)::bigint as update_count
    from public.cars c
    join public.profiles p on p.id = c.owner_id
    left join (select a.car_id, count(*) as n from public.activity_posts a
                where a.published_at is not null group by a.car_id) u on u.car_id = c.id
    -- Suspension is checked when the list is read, so a member who is
    -- suspended and restored keeps their place.
    where c.is_public and c.cover_image_url is not null and p.username is not null
    group by c.owner_id
  ) s
  order by s.car_count desc, s.update_count desc, s.owner_id
  limit 2000;
end;
$$;


--
-- Name: refresh_explore_rankings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_explore_rankings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.refresh_explore_trending();
  perform public.refresh_explore_builders();
end;
$$;


--
-- Name: refresh_explore_trending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_explore_trending() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  delete from public.explore_trending_models;
  insert into public.explore_trending_models (rank, make, model, builds, updates, catalog_make_id, catalog_model_id)
  select row_number() over (), t.* from public.trending_models_live(45, 24) t;
end;
$$;


--
-- Name: refresh_listing_vehicle_fit(uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_listing_vehicle_fit(p_listings uuid[], p_lock boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_lock then
    perform 1 from public.listings l where l.id = any(p_listings) order by l.id for update;
  end if;
  delete from public.listing_vehicle_fit where listing_id = any(p_listings);
  insert into public.listing_vehicle_fit
    (listing_id, make_key, model_key, via, years, all_years, stated_also, car_public, car_owner_id,
     seller_id, published_at, price_cents)
  with parts as (
    select l.id, l.seller_id, l.source_car_id, l.published_at, l.price_cents
    from public.listings l
    where l.id = any(p_listings) and l.status = 'active'
  ),
  stated as (
    select p.id, lower(f.make) as make_key, k.model_key,
           range_agg(int4range(f.year_start, f.year_end, '[]')) as years,
           bool_or(f.year_start is null and f.year_end is null) as all_years
    from parts p
    join public.listing_fitments f on f.listing_id = p.id
    cross join lateral (values (lower(f.model)), ('')) k(model_key)
    group by p.id, lower(f.make), k.model_key
  ),
  from_car as (
    select distinct p.id, lower(c.make) as make_key, k.model_key, c.is_public, c.owner_id
    from parts p
    join public.cars c on c.id = p.source_car_id
    cross join lateral (values (coalesce(lower(c.model), '')), ('')) k(model_key)
    where c.make is not null
  )
  select s.id, s.make_key, s.model_key, 'stated', s.years, s.all_years, false, true, null,
         p.seller_id, p.published_at, p.price_cents
  from stated s join parts p on p.id = s.id
  union all
  select c.id, c.make_key, c.model_key, 'car', null, false,
         s.id is not null,
         c.is_public, c.owner_id, p.seller_id, p.published_at, p.price_cents
  from from_car c
  join parts p on p.id = c.id
  -- A join, not a lookup per row: refreshing every part at once (the
  -- backfill) must stay linear.
  left join stated s on s.id = c.id and s.make_key = c.make_key and s.model_key = c.model_key;
end;
$$;


--
-- Name: refresh_marketplace_facet_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_marketplace_facet_counts() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with fresh as (
    select case when grouping(l.category) = 0 then 'category' when grouping(l.brand) = 0 then 'brand' else 'condition' end as facet,
           coalesce(l.category, l.brand, l.condition) as key,
           coalesce(l.subcategory, '') as subkey,
           count(*) as total
    from public.listings l
    where l.status = 'active' and l.seller_id not in (select public.suspended_profile_ids())
    group by grouping sets ((l.category, l.subcategory), (l.brand), (l.condition))
    having (grouping(l.category) = 0) or (grouping(l.brand) = 0 and l.brand is not null)
        or (grouping(l.condition) = 0 and l.condition is not null)
  ),
  gone as (
    delete from public.marketplace_facet_counts t
    where not exists (select 1 from fresh f where f.facet = t.facet and f.key = t.key and f.subkey = t.subkey)
  )
  insert into public.marketplace_facet_counts (facet, key, subkey, total)
  select facet, key, subkey, total from fresh
  on conflict (facet, key, subkey) do update set total = excluded.total
  where public.marketplace_facet_counts.total is distinct from excluded.total;
$$;


--
-- Name: refresh_search_words(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_search_words() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with fresh as (
    select w.word, count(*)::integer as uses
    from public.listings l
    cross join lateral regexp_split_to_table(lower(coalesce(l.title, '') || ' ' || coalesce(l.brand, '')), '[^[:alpha:]]+') w(word)
    where l.status = 'active' and l.seller_id not in (select public.suspended_profile_ids())
      and length(w.word) between 4 and 30
    group by w.word
  ),
  gone as (
    delete from public.search_words t where t.word not in (select f.word from fresh f)
  )
  insert into public.search_words (word, uses)
  select word, uses from fresh
  on conflict (word) do update set uses = excluded.uses
  where public.search_words.uses is distinct from excluded.uses;
$$;


--
-- Name: refund_gap_snapshot(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_gap_snapshot(p_payment_reference text, p_refund_references text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'payments', (select count(*) from public.payments where provider_reference = p_payment_reference),
    'booked_cents', (select coalesce(sum(refunded_cents), 0) from public.payments
                     where provider_reference = p_payment_reference),
    -- Same rule as before: an operation for one of these refunds whose money
    -- isn't in refunded_cents yet and that the refund state machine still
    -- drives.
    'in_flight_cents', (select coalesce(sum(amount_cents), 0) from public.refund_operations
                        where refund_reference = any(coalesce(p_refund_references, '{}'))
                          and effects_completed_at is null
                          and status in ('requested', 'provider_pending', 'provider_succeeded', 'effects_pending'))
  );
$$;


--
-- Name: reject_copyright_notice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_copyright_notice(p_notice uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := private.copyright_admin_step_up();
begin
  if p_note is null or length(btrim(p_note)) < 1 or length(p_note) > 4000 then
    raise exception 'A note of 1–4000 characters is required' using errcode = '22023';
  end if;
  update public.copyright_notices
     set status = 'rejected', resolved_by = v_actor, resolved_at = now(), resolution_note = p_note
   where id = p_notice and status = 'received';
  if not found then
    raise exception 'This notice is not open' using errcode = '55000';
  end if;
  insert into public.admin_audit_log (actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'copyright.reject', 'copyright_notice', p_notice, p_note, jsonb_build_object('phase', 'completed'));
end;
$$;


--
-- Name: reject_dispute_history_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_dispute_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' and not exists (select 1 from public.orders where id = old.order_id) then
    return old; -- the order itself was deleted (cascade)
  end if;
  raise exception 'Dispute history is append-only' using errcode = '42501';
end $$;


