CREATE FUNCTION public.reject_refund_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'Refund lifecycle history is append-only';
end $$;


--
-- Name: release_cart_checkout(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_cart_checkout(p_buyer uuid, p_idempotency_key text, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  a public.purchase_attempts;
  v_order_ids uuid[];
  o public.orders;
  pay public.payments;
  v_result jsonb;
  v_released int := 0;
begin
  if p_buyer is null or p_idempotency_key is null then
    raise exception 'Invalid checkout release' using errcode = '22023';
  end if;

  -- Serialise with purchase_begin for this buyer, so a restart cannot race
  -- the attempt it is replacing.
  perform pg_advisory_xact_lock(hashtextextended(p_buyer::text, 0));

  select * into a
  from public.purchase_attempts
  where idempotency_key = p_idempotency_key
  for update;
  -- 20261108110300: a guest's attempt (no checkout_request_key) is released
  -- too. Every attempt is a cart basket (only purchase_begin writes them),
  -- and the per-order checks below refuse an accepted offer regardless.
  if not found or a.buyer_id is distinct from p_buyer then
    raise exception 'Checkout attempt not found for this buyer' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct (x ->> 'order_id')::uuid), array[]::uuid[])
    into v_order_ids
  from jsonb_array_elements(coalesce(a.result -> 'orders', '[]'::jsonb)) x;

  -- listing → order → payment.
  perform 1 from public.listings
  where id in (
    select oi.listing_id from public.order_items oi
    where oi.order_id = any (v_order_ids) and oi.listing_id is not null
  )
  order by id
  for update;

  perform 1 from public.orders where id = any (v_order_ids) order by id for update;

  -- Check every order before releasing any, so a refusal leaves the whole
  -- basket exactly as it was.
  for o in select * from public.orders where id = any (v_order_ids) order by id loop
    if o.buyer_id is distinct from p_buyer then
      raise exception 'Checkout order belongs to another buyer' using errcode = '42501';
    end if;
    if o.origin_offer_id is not null then
      raise exception 'An accepted offer is not a cart checkout' using errcode = '42501';
    end if;
    if o.status in ('payment_failed', 'cancelled') then
      continue;
    end if;
    if o.status not in ('pending', 'requires_action') then
      raise exception 'Checkout already settled; nothing released' using errcode = '55000';
    end if;

    select * into pay from public.payments where order_id = o.id for update;
    if p_reference is null then
      if pay.provider_reference is not null or exists (
        select 1 from public.payment_requests pr
        where (pr.request -> 'orderIds') ? o.id::text
          and (pr.provider_reference is not null or pr.provider_rejected_at is null)
      ) then
        raise exception 'Payment outcome unresolved; retain reservation' using errcode = '55000';
      end if;
    elsif pay.provider_reference is distinct from p_reference then
      raise exception 'Checkout payment reference mismatch' using errcode = '55000';
    end if;
  end loop;

  for o in
    select * from public.orders
    where id = any (v_order_ids) and status in ('pending', 'requires_action')
    order by id
  loop
    select * into pay from public.payments where order_id = o.id;
    v_result := public.purchase_finalize(
      o.id,
      false,
      coalesce(pay.provider, 'stripe'),
      p_reference,
      'buyer restarted checkout before paying'
    );
    if not coalesce((v_result ->> 'applied')::boolean, false) then
      raise exception 'Checkout release refused' using errcode = '55000';
    end if;
    v_released := v_released + 1;
  end loop;

  return jsonb_build_object('ok', true, 'released', v_released);
end;
$$;


--
-- Name: release_expired_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_expired_reservations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare queued int;
begin
 insert into public.remediation_jobs(kind,dedup_key,payload)
 select 'reservation_expiry','expiry:'||o.id,jsonb_build_object('order_id',o.id)
 from public.orders o
 where o.status in ('pending','requires_action')
 and exists(select 1 from public.order_items oi join public.listings l on l.id=oi.listing_id
   where oi.order_id=o.id and l.status='reserved' and l.reserved_until<now())
 and not exists(select 1 from public.remediation_jobs j where j.dedup_key='expiry:'||o.id)
 order by o.created_at,o.id limit 500
 on conflict(dedup_key) do nothing;
 get diagnostics queued=row_count;
 update public.offers set status='expired',responded_at=now()
 where status in ('open','countered') and expires_at<now();
 return jsonb_build_object('queued',queued,'listings_released',0,'orders_cancelled',0);
end $$;


--
-- Name: release_media_claim(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_media_claim(p_bucket text, p_path text, p_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  delete from private.media_deletion_claims
   where bucket = p_bucket and path = p_path and token = p_token and state = 'active' and not maybe_deleted;
  return found;
end;
$$;


--
-- Name: release_refused_admin_refund(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_refused_admin_refund(p_actor uuid, p_operation uuid, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.admin_audit_log;
  v_ops jsonb;
  v_blocking int;
begin
  perform public.assert_admin_actor(p_actor);

  select * into v_req from public.admin_audit_log a
  where a.metadata->>'operationId' = p_operation::text
    and a.metadata->>'phase' = 'requested'
    and a.action = 'order.force_refund'
    and a.actor_id = p_actor
  order by a.id limit 1;
  if not found then
    raise exception 'No such refund request from this admin' using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_req.action || ':' || v_req.subject_id::text, 0));

  if exists (
    select 1 from public.admin_audit_log a
    where a.metadata->>'operationId' = p_operation::text
      and a.metadata->>'phase' in ('completed', 'reconciled')
  ) then
    return jsonb_build_object('released', false, 'status', 'already_resolved');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id, 'status', r.status, 'providerStatus', r.provider_status,
           'refundReference', r.refund_reference, 'amountCents', r.amount_cents)
           order by r.created_at), '[]'::jsonb),
         count(*) filter (where r.status <> 'failed' or r.refund_reference is not null)
    into v_ops, v_blocking
  from public.refund_operations r
  where r.order_id = v_req.subject_id
    and r.created_at >= v_req.created_at
    and r.requested_by = 'admin:' || v_req.actor_id::text;

  if v_blocking > 0 then
    return jsonb_build_object('released', false, 'status', 'refund_on_file', 'operations', v_ops);
  end if;

  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, order_id, reason, metadata)
  values (p_actor, 'operation.reconcile', v_req.subject_type, v_req.subject_id, v_req.order_id,
    left(coalesce(nullif(trim(p_detail), ''), 'Refund refused'), 4000),
    jsonb_build_object('operationId', p_operation::text, 'phase', 'reconciled', 'outcome', 'not_applied',
      'reconciles', v_req.action,
      'evidence', jsonb_build_object('source', 'refusal', 'detail', left(coalesce(p_detail, ''), 1000),
        'operations', v_ops, 'observedAt', now())));

  return jsonb_build_object('released', true, 'status', 'resolved', 'operations', v_ops);
end;
$$;


--
-- Name: release_refused_deletion_resume(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_refused_deletion_resume(p_actor uuid, p_operation uuid, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.admin_audit_log;
  v_job text;
begin
  perform public.assert_admin_actor(p_actor);
  select * into v_req from public.admin_audit_log a
   where a.metadata->>'operationId' = p_operation::text
     and a.metadata->>'phase' = 'requested'
     and a.action = 'deletion.resume'
     and a.actor_id = p_actor
   order by a.id limit 1;
  if not found then
    raise exception 'No such deletion resume from this admin' using errcode = 'P0002';
  end if;
  perform pg_advisory_xact_lock(private.account_deletion_lock_key(v_req.subject_id));
  if exists (select 1 from public.admin_audit_log a
              where a.metadata->>'operationId' = p_operation::text
                and a.metadata->>'phase' in ('completed', 'reconciled')) then
    return jsonb_build_object('released', false, 'status', 'already_resolved');
  end if;
  select j.status into v_job from public.remediation_jobs j
   where j.dedup_key = 'delete:' || v_req.subject_id::text and j.kind = 'delete_account';
  -- Queued or running: the resume may have applied. Keep it for an operator.
  if v_job in ('pending', 'processing') then
    return jsonb_build_object('released', false, 'status', 'job_queued', 'job_status', v_job);
  end if;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, order_id, reason, metadata)
  values (p_actor, 'operation.reconcile', v_req.subject_type, v_req.subject_id, null,
    left(coalesce(nullif(trim(p_detail), ''), 'Resume refused'), 4000),
    jsonb_build_object('operationId', p_operation::text, 'phase', 'reconciled', 'outcome', 'not_applied',
      'reconciles', v_req.action,
      'evidence', jsonb_build_object('source', 'refusal', 'detail', left(coalesce(p_detail, ''), 1000),
        'jobStatus', v_job, 'observedAt', now())));
  return jsonb_build_object('released', true, 'status', 'resolved', 'job_status', v_job);
end $$;


--
-- Name: release_refused_dispute_retry(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_refused_dispute_retry(p_actor uuid, p_operation uuid, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.admin_audit_log;
  v_state text;
begin
  perform public.assert_admin_actor(p_actor);
  select * into v_req from public.admin_audit_log a
   where a.metadata->>'operationId' = p_operation::text
     and a.metadata->>'phase' = 'requested'
     and a.action = 'recovery.retry_dispute'
     and a.actor_id = p_actor
   order by a.id limit 1;
  if not found then raise exception 'No such retry from this admin' using errcode = 'P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_req.action || ':' || v_req.subject_id::text, 0));
  if exists (select 1 from public.admin_audit_log a
              where a.metadata->>'operationId' = p_operation::text
                and a.metadata->>'phase' in ('completed', 'reconciled')) then
    return jsonb_build_object('released', false, 'status', 'already_resolved');
  end if;
  select j.state into v_state from public.stripe_dispute_journal j where j.dispute_id = v_req.metadata->>'disputeId';
  if v_state is distinct from 'recovery' then
    return jsonb_build_object('released', false, 'status', 'not_held', 'state', v_state);
  end if;
  insert into public.admin_audit_log(actor_id, action, subject_type, subject_id, order_id, reason, metadata)
  values (p_actor, 'operation.reconcile', v_req.subject_type, v_req.subject_id, v_req.order_id,
    left(coalesce(nullif(trim(p_detail), ''), 'Retry refused'), 4000),
    jsonb_build_object('operationId', p_operation::text, 'phase', 'reconciled', 'outcome', 'not_applied',
      'reconciles', v_req.action,
      'evidence', jsonb_build_object('source', 'refusal', 'detail', left(coalesce(p_detail, ''), 1000), 'journalState', v_state, 'observedAt', now())));
  return jsonb_build_object('released', true, 'status', 'resolved');
end;
$$;


--
-- Name: release_seller_carry_payout(uuid, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_seller_carry_payout(p_id uuid, p_worker text, p_status text, p_last_error text, p_attempts integer, p_next_attempt_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_payout public.seller_carry_payouts;
begin
  if p_status is null or p_status not in ('pending', 'failed', 'cancelled') then
    raise exception 'Invalid carry payout release status';
  end if;
  select * into v_payout from public.seller_carry_payouts where id = p_id for update;
  if not found
     or v_payout.status <> 'processing'
     or v_payout.locked_by is distinct from p_worker
     or v_payout.lease_expires_at is null
     or v_payout.lease_expires_at <= now() then
    return false;
  end if;
  if p_status = 'cancelled' then
    if v_payout.provider_call_may_have_occurred then
      raise exception 'A carry payout that may have reached Stripe cannot be cancelled';
    end if;
    perform public.record_seller_carry(
      v_payout.seller_id, 'paid_out_reversed', v_payout.amount_cents, null, null,
      'paid-out-reversed:' || v_payout.id::text);
  end if;
  update public.seller_carry_payouts
     set status = p_status,
         last_error = left(p_last_error, 500),
         attempts = coalesce(p_attempts, attempts),
         next_attempt_at = case when p_status = 'cancelled' then null else p_next_attempt_at end,
         locked_by = null,
         lease_expires_at = null,
         updated_at = now()
   where id = p_id;
  return true;
end;
$$;


--
-- Name: release_transfer_intent(uuid, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_transfer_intent(p_order uuid, p_worker text, p_status text, p_last_error text DEFAULT NULL::text, p_attempts integer DEFAULT NULL::integer, p_next_attempt_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_updated int;
begin
  if p_status not in ('holding', 'blocked_unpayable', 'failed', 'cancelled') then
    raise exception 'Invalid transfer release status';
  end if;

  update public.transfer_intents
  set status = p_status,
      attempts = coalesce(p_attempts, attempts),
      next_attempt_at = p_next_attempt_at,
      last_error = left(p_last_error, 500),
      locked_at = null,
      locked_by = null,
      lease_expires_at = null,
      updated_at = now()
  where order_id = p_order
    and status = 'processing'
    and locked_by = p_worker
    and lease_expires_at > now();
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


--
-- Name: remap_public_media(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remap_public_media(p_old text, p_new text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare changed int:=0; n int;
begin
 if p_old=p_new or length(p_old)>2000 or length(p_new)>2000 or position('/storage/v1/object/public/' in p_old)=0 or split_part(p_old,'/storage/v1/object/public/',1)<>split_part(p_new,'/storage/v1/object/public/',1) then raise exception 'Invalid media remap'; end if;
 -- Immutable financial evidence and embedded content require explicit review.
 if exists(select 1 from public.order_item_snapshot_images where url=p_old)
 or exists(select 1 from public.dispute_evidence where url=p_old)
 or exists(select 1 from public.order_items where position(p_old in commercial_snapshot::text)>0)
 or exists(select 1 from public.activity_posts where position(p_old in body::text)>0) then return jsonb_build_object('outcome','retained_for_review'); end if;
 update public.car_images set url=p_new where url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.listing_images set url=p_new where url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.activity_images set url=p_new where url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.profiles set avatar_url=p_new where avatar_url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.cars set cover_image_url=p_new where cover_image_url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.car_hotspots set image_url=p_new where image_url=p_old; get diagnostics n=row_count; changed:=changed+n;
 update public.staged_uploads set consumed_at=coalesce(consumed_at,now()) where url=p_old;
 return jsonb_build_object('outcome','remapped','references',changed);
end $$;


--
-- Name: renew_refund_reversal_lease(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_refund_reversal_lease(p_operation uuid, p_worker text, p_operation_key text, p_lease_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_updated int;
begin
  update public.refund_operations
  set reversal_lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
      updated_at = now()
  where id = p_operation
    and status = 'reversal_pending'
    and reversal_locked_by = p_worker
    and reversal_lease_expires_at > now()
    and reversal_operation_key = p_operation_key
    and reversal_call_may_have_occurred;
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


--
-- Name: renew_remediation_lease(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_remediation_lease(p_id uuid, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 update public.remediation_jobs set locked_until=now()+interval '2 minutes' where id=p_id and lease_id=p_lease and status='processing' and locked_until>now();
 if not found then raise exception 'Job lease lost'; end if;
end $$;


--
-- Name: repair_completed_outbound_label(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_completed_outbound_label(p_shipment uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  shipment_order uuid;
  s public.shipments;
  o public.orders;
  adjustment public.seller_adjustments;
begin
  select order_id into strict shipment_order from public.shipments where id=p_shipment;
  select * into strict o from public.orders where id=shipment_order for update;
  select * into strict s from public.shipments where id=p_shipment for update;
  if p_actor is null or o.seller_id is distinct from p_actor then raise exception 'Seller authorization required' using errcode='42501'; end if;
  if s.order_id<>o.id or s.direction<>'outbound' or s.fulfillment_type<>'drvn_shipping'
     or s.status<>'label_purchased' or s.purchased_cents is null or s.purchased_cents<0
     or nullif(s.provider_shipment_id,'') is null or nullif(s.label_reference,'') is null
     or nullif(s.tracking_code,'') is null or nullif(s.carrier,'') is null or nullif(s.service,'') is null
     or not exists(select 1 from public.shipment_items where shipment_id=s.id) then
    raise exception 'Completed outbound shipment is incomplete';
  end if;
  insert into public.seller_adjustments(
    seller_id,order_id,shipment_id,kind,amount_cents,currency,external_reference,description
  ) values(
    o.seller_id,o.id,s.id,'outbound_label',-s.purchased_cents,o.currency,'label:'||s.id,
    s.carrier||' '||s.service||' outbound label'
  ) on conflict(kind,external_reference) where external_reference is not null do nothing;
  select * into strict adjustment from public.seller_adjustments
  where kind='outbound_label' and external_reference='label:'||s.id;
  if adjustment.seller_id is distinct from o.seller_id or adjustment.order_id<>o.id
     or adjustment.shipment_id is distinct from s.id or adjustment.amount_cents<>-s.purchased_cents
     or upper(adjustment.currency)<>upper(o.currency) then
    raise exception 'Completed outbound label seller adjustment conflicts';
  end if;
  return jsonb_build_object('ok',true,'label_url',s.label_reference);
end $$;


--
-- Name: replace_car_showcase(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_car_showcase(p_car uuid, p_image_url text, p_pins jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_pins jsonb := coalesce(p_pins, '[]'::jsonb);
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'Sign in to edit this build.' using errcode = '42501';
  end if;
  if jsonb_typeof(v_pins) <> 'array' then
    raise exception 'Pins must be a list.' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(v_pins);
  if v_count > 8 then
    raise exception 'A showcase has at most 8 pins.' using errcode = '22023';
  end if;
  -- The owner's car, locked so a second save queues behind this one.
  perform 1 from public.cars c where c.id = p_car and c.owner_id = auth.uid() for update;
  if not found then
    raise exception 'Car not found.' using errcode = '42501';
  end if;

  -- Validate everything before anything changes.
  if v_count > 0 then
    if not exists (select 1 from public.car_images i where i.car_id = p_car and i.url = p_image_url) then
      raise exception 'Pick one of this car''s photos for the showcase.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_pins) pin
       where jsonb_typeof(pin->'x') <> 'number' or jsonb_typeof(pin->'y') <> 'number'
          or (pin->>'x')::numeric not between 0 and 1 or (pin->>'y')::numeric not between 0 and 1
          or char_length(btrim(coalesce(pin->>'label', ''))) not between 1 and 80
    ) then
      raise exception 'Every pin needs a place on the photo and a label.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_pins) pin
       where nullif(pin->>'mod_item_id', '') is not null
         and not exists (
           select 1 from public.mod_items m
            where m.id = (pin->>'mod_item_id')::uuid and m.car_id = p_car
         )
    ) then
      raise exception 'A pin names a part that isn''t on this build.' using errcode = '22023';
    end if;
  end if;

  delete from public.car_hotspots where car_id = p_car;
  insert into public.car_hotspots (car_id, image_url, x, y, mod_item_id, label)
  select p_car, p_image_url,
         round((pin->>'x')::numeric, 3), round((pin->>'y')::numeric, 3),
         nullif(pin->>'mod_item_id', '')::uuid, btrim(pin->>'label')
    from jsonb_array_elements(v_pins) pin;
  return v_count;
end;
$$;


--
-- Name: replay_listing_edit(uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_listing_edit(p_request uuid, p_payload_hash text, p_listing uuid, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_request private.listing_edit_requests%rowtype;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_request is null or coalesce(p_payload_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid listing edit request' using errcode = '22023';
  end if;
  select * into v_request
  from private.listing_edit_requests r
  where r.seller_id = v_actor and r.request_id = p_request;
  if not found then return null; end if;
  if v_request.listing_id is distinct from p_listing
     or v_request.expected_updated_at is distinct from p_expected_updated_at
     or v_request.payload_hash is distinct from p_payload_hash then
    raise exception 'This edit request was already used with different details'
      using errcode = '22023';
  end if;
  -- A replay is not a free pass: the caller must still own the listing and
  -- be allowed to act.
  if not exists (select 1 from public.listings l where l.id = p_listing and l.seller_id = v_actor) then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if public.is_suspended(v_actor) then
    raise exception 'account is suspended' using errcode = '42501';
  end if;
  return v_request.result;
end;
$_$;


--
-- Name: request_account_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare uid uuid:=auth.uid(); job uuid; blockers jsonb; existing_case public.account_deletion_requests%rowtype;
begin
  if uid is null then raise exception 'Sign in first' using errcode='42501'; end if;
  -- N41: fresh proof it's the owner, checked here and not only in the app,
  -- so a stolen or old access token calling this function directly can't
  -- queue the cleanup and suspend the account.
  if not private.signed_in_within(600) then
    raise exception 'Recent sign-in required' using errcode='42501',
      hint='Sign in again (password, Google, or an emailed link) and retry within ten minutes.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
  -- N39: a member suspended by moderation can still ask for deletion. Only a
  -- deletion already underway answers with its own state.
  if private.account_deletion_started(uid) then
    select * into existing_case from public.account_deletion_requests where user_id=uid;
    if existing_case.outcome='cleanup_pending' then
      return jsonb_build_object('outcome','cleanup_pending','job_id',existing_case.job_id,'message','Account cleanup is already in progress.');
    elsif existing_case.outcome='operator_attention' then
      return jsonb_build_object('outcome','operator_attention','message',existing_case.next_action);
    end if;
    raise exception 'Account access is suspended' using errcode='42501';
  end if;
  if exists(select 1 from public.admin_users where user_id=uid) then
    insert into public.account_deletion_requests(user_id,outcome,blocker_code,affected_data_classes,next_action,responsible_owner,policy_decisions_pending)
    values(uid,'operator_attention','admin_membership',array['administrator identity','audit trail'],'An operator must remove administrator access and review the retained audit identity.','operations',array['audit identity retention duration','retained identity anonymization'])
    on conflict(user_id) do update set outcome=excluded.outcome,blocker_code=excluded.blocker_code,affected_data_classes=excluded.affected_data_classes,next_action=excluded.next_action,responsible_owner=excluded.responsible_owner,policy_decisions_pending=excluded.policy_decisions_pending,updated_at=now();
    return jsonb_build_object('outcome','operator_attention','message','Administrator accounts require operator review before deletion.');
  end if;
  blockers:=public.account_deletion_blockers(uid);
  if (blockers->>'financial_hold')::boolean then
    insert into public.account_deletion_requests(user_id,outcome,blocker_code,affected_data_classes,next_action,responsible_owner,policy_decisions_pending)
    values(uid,'temporary_financial_hold','active_financial_obligations',array['orders','returns','refunds','payouts'],'Finish outstanding orders, returns, refunds, and payouts, then request deletion again.','account owner',array['financial record retention duration','eventual identity anonymization'])
    on conflict(user_id) do update set outcome=excluded.outcome,blocker_code=excluded.blocker_code,affected_data_classes=excluded.affected_data_classes,next_action=excluded.next_action,responsible_owner=excluded.responsible_owner,policy_decisions_pending=excluded.policy_decisions_pending,updated_at=now();
    return jsonb_build_object('outcome','temporary_financial_hold','message','Deletion is on hold while financial obligations remain. You can keep using your account to finish them.');
  end if;
  select id into job from public.remediation_jobs where dedup_key='delete:'||uid;
  -- Expire every package before suspending access. A download that begins
  -- after this transaction commits cannot observe a completed package.
  update public.account_export_requests set status='expired',expires_at=least(expires_at,now()),last_error='Expired because account deletion began'
    where user_id=uid and status<>'expired';
  update public.profiles set suspended_at=coalesce(suspended_at,now()),suspended_reason='Account deletion requested' where id=uid;
  update public.listings set status='paused' where seller_id=uid and status='active';
  if job is null then
    insert into public.remediation_jobs(kind,dedup_key,payload) values('delete_account','delete:'||uid,jsonb_build_object('user_id',uid)) returning id into job;
  end if;
  insert into public.account_deletion_requests(user_id,job_id,outcome,blocker_code,affected_data_classes,next_action,responsible_owner,policy_decisions_pending)
  values(uid,job,'cleanup_pending',null,array['profile','owned content','uploads','provider customer'],'Automated cleanup is in progress.','privacy worker',array['financial record retention duration','audit/log retention','backup expiry','eventual identity anonymization'])
  on conflict(user_id) do update set job_id=excluded.job_id,outcome=excluded.outcome,blocker_code=null,affected_data_classes=excluded.affected_data_classes,next_action=excluded.next_action,responsible_owner=excluded.responsible_owner,policy_decisions_pending=excluded.policy_decisions_pending,updated_at=now();
  return jsonb_build_object('outcome','cleanup_pending','job_id',job,'message','Account cleanup has been queued.');
end $$;


--
-- Name: request_account_export(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_export() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare uid uuid := auth.uid(); request_id uuid;
begin
  if uid is null then raise exception 'Sign in first' using errcode='42501'; end if;
  -- Shared with deletion and export publication so eligibility changes are
  -- serialized in one order for this account.
  perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
  -- N39: a suspension doesn't take away the right to a copy of your data;
  -- only a deletion that has begun does (its packages are being destroyed).
  perform 1 from public.profiles where id=uid for share;
  if not found then raise exception 'Sign in first' using errcode='42501'; end if;
  if private.account_deletion_started(uid) then raise exception 'Account access is suspended' using errcode='42501'; end if;
  select id into request_id from public.account_export_requests
   where user_id=uid and status in ('pending','processing') and expires_at>now()
   order by requested_at desc limit 1;
  if found then return request_id; end if;
  insert into public.account_export_requests(user_id,contract_version)
    values(uid,'2026-10-25.v12') returning id into request_id;
  insert into public.remediation_jobs(kind,dedup_key,payload)
    values('account_export','export:'||request_id,jsonb_build_object('request_id',request_id,'user_id',uid))
    on conflict(dedup_key) do nothing;
  return request_id;
end $$;


--
-- Name: require_refund_recredit_proof(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_refund_recredit_proof() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if old.kind='refund_late_failure' and new.status<>'open' then
  if not exists(select 1 from public.refund_recredit_proofs where recovery_id=old.id) then raise exception 'Verify the seller recredit obligation before closing this recovery case'; end if;
  if not exists(
   select 1 from public.refund_recredit_proofs proof
   join public.refund_lifecycle_adjustments a on a.id=proof.adjustment_id
   join public.refund_operations f on f.id=a.refund_operation_id
   join public.refund_operations replacement on replacement.replaces_adjustment_id=a.id
   where proof.recovery_id=old.id and replacement.order_id=f.order_id
    and replacement.payment_reference=f.payment_reference and replacement.amount_cents=a.refund_amount_cents
    and replacement.refund_reference is not null and replacement.refund_reference<>a.refund_reference
    and ((replacement.status='completed' and replacement.provider_status='succeeded')
     or exists(select 1 from public.payment_recoveries child where child.recovery_key='refund-late-failure:'||replacement.refund_reference and child.status='recovered'))
  ) then raise exception 'The linked replacement buyer refund must also be settled before closure'; end if;
  if new.status<>'recovered' then raise exception 'A fulfilled late-refund obligation must be recorded as recovered'; end if;
  -- Failed pre-settlement attempts share this obligation. Once its linked
  -- successor has paid the buyer, their alerts must no longer claim money owed.
  update public.payment_recoveries early_case set status='recovered',resolved_by=new.resolved_by,
   resolved_at=coalesce(new.resolved_at,now()),resolution_note='Superseded replacement fulfilled; parent recovery '||old.id
  where early_case.status='open' and early_case.kind='refund_failed' and exists(
   select 1 from public.refund_operations attempt
   join public.refund_recredit_proofs proof on proof.adjustment_id=attempt.replaces_adjustment_id
   where proof.recovery_id=old.id and attempt.recovery_id=early_case.id
    and attempt.status='failed' and attempt.provider_status in ('failed','canceled') and attempt.effects_completed_at is null
  );
 end if;
 return new;
end $$;


--
-- Name: resolve_product_identity_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_product_identity_review(p_review uuid, p_decision text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_review public.product_identity_reviews;
  v_keep uuid;
  v_status text;
begin
  if not public.is_admin() or public.admin_role() <> 'admin' or not exists (
    select 1 from jsonb_array_elements(coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb -> 'amr', '[]'::jsonb)) m
    where m ->> 'method' in ('totp', 'mfa/totp')
      and (m ->> 'timestamp')::numeric between extract(epoch from now()) - 900 and extract(epoch from now()) + 60
  ) then
    raise exception 'Admin step-up required' using errcode = '42501';
  end if;
  if p_reason is null or length(trim(p_reason)) < 1 or length(p_reason) > 4000 then
    raise exception 'A reason of 1–4000 characters is required';
  end if;

  select * into v_review from public.product_identity_reviews where id = p_review for update;
  if not found then
    raise exception 'Review not found';
  end if;
  if v_review.status <> 'open' then
    raise exception 'This review is already closed (%)', v_review.status;
  end if;

  if p_decision = 'merge' then
    if v_review.kind = 'brandless_number' then
      raise exception 'A record without a brand can''t be merged: dismiss it, or ask the member to add the brand';
    end if;
    v_keep := public.merge_products(v_review.product_ids, 'verified', v_actor);
    if v_review.link_id is not null then
      update public.part_number_links set verified_at = now(), verified_by = v_actor where id = v_review.link_id;
    end if;
    v_status := 'merged';
  elsif p_decision = 'keep_separate' then
    if v_review.kind = 'brandless_number' then
      raise exception 'Dismiss a record without a brand instead';
    end if;
    v_status := 'kept_separate';
  elsif p_decision = 'dismiss' then
    v_status := 'dismissed';
  else
    raise exception 'Decision must be merge, keep_separate or dismiss';
  end if;

  update public.product_identity_reviews
     set status = v_status, resolved_by = v_actor, resolved_at = now(), resolution_note = p_reason
   where id = p_review;
  insert into public.admin_audit_log (actor_id, action, subject_type, subject_id, reason, metadata)
  values (v_actor, 'product.' || p_decision, 'product_review', p_review, p_reason,
          jsonb_build_object('phase', 'completed', 'kind', v_review.kind, 'productIds', v_review.product_ids,
                             'keptProductId', v_keep, 'numberCompact', v_review.number_compact));
  return jsonb_build_object('status', v_status, 'keptProductId', v_keep);
end;
$$;


--
-- Name: resolve_vehicle_generation(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_vehicle_generation(p_model_id bigint, p_year integer) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when count(*) = 1 then min(g.id) end
  from public.vehicle_generations g
  where g.model_id = p_model_id
    and (p_year is null or p_year between g.year_start and coalesce(g.year_end, 2100));
$$;


--
-- Name: respond_shop_policy_return(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_shop_policy_return(p_return uuid, p_seller uuid, p_decision text, p_ship_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.returns;
  o public.orders;
  return_order uuid;
  stamped_at timestamptz:=now();
begin
  if p_return is null or p_seller is null or p_decision not in ('approve','reject')
     or p_ship_days is null or p_ship_days<1 or p_ship_days>30 then
    raise exception 'Invalid shop return response';
  end if;
  select order_id into strict return_order from public.returns where id=p_return;
  select * into strict o from public.orders where id=return_order for update;
  select * into strict r from public.returns where id=p_return for update;
  if r.order_id<>o.id then raise exception 'Return order changed'; end if;
  if o.seller_id is distinct from p_seller then raise exception 'Seller authorization required' using errcode='42501'; end if;
  if r.return_type<>'shop_policy' then raise exception 'Return is not a shop-policy request'; end if;

  if p_decision='approve' and r.status='awaiting_shipment' and r.approved_at is not null and r.ship_by is not null then
    return jsonb_build_object('ok',true,'order_id',o.id,'return_id',r.id,'replayed',true,'status',r.status);
  elsif p_decision='approve' and r.status='approved' and r.approved_at is not null and r.ship_by is not null then
    update public.returns set status='awaiting_shipment' where id=r.id;
    return jsonb_build_object('ok',true,'order_id',o.id,'return_id',r.id,'replayed',false,'repaired',true,'status','awaiting_shipment');
  elsif p_decision='reject' and r.status='rejected' then
    return jsonb_build_object('ok',true,'order_id',o.id,'return_id',r.id,'replayed',true,'status',r.status);
  elsif r.status<>'requested' then
    return jsonb_build_object('ok',false,'order_id',o.id,'return_id',r.id,'reason','This return has already been handled.');
  end if;

  if p_decision='reject' then
    update public.returns set status='rejected' where id=r.id;
  else
    update public.returns set status='approved',approved_at=stamped_at,
      ship_by=stamped_at+make_interval(days=>p_ship_days) where id=r.id;
    update public.returns set status='awaiting_shipment' where id=r.id;
  end if;
  return jsonb_build_object('ok',true,'order_id',o.id,'return_id',r.id,'replayed',false,
    'status',case when p_decision='approve' then 'awaiting_shipment' else 'rejected' end);
end $$;


--
-- Name: save_listing_creation(uuid, text, jsonb, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_listing_creation(p_request uuid, p_payload_hash text, p_listing jsonb, p_images jsonb, p_fitments jsonb, p_alt_numbers jsonb, p_mod_item uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_claim jsonb;
  v_id uuid;
  v_existing public.listings%rowtype;
  v_status text;
  v_inserted integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode='42501'; end if;
  if jsonb_typeof(p_listing) is distinct from 'object'
     or jsonb_typeof(p_images) is distinct from 'array'
     or jsonb_typeof(p_fitments) is distinct from 'array'
     or jsonb_typeof(p_alt_numbers) is distinct from 'array'
     or jsonb_array_length(p_images) > 12
     or jsonb_array_length(p_fitments) > 10
     or jsonb_array_length(p_alt_numbers) > 5 then
    raise exception 'Invalid listing projection' using errcode='22023';
  end if;
  v_status := p_listing->>'status';
  if v_status not in ('draft','active') then
    raise exception 'Invalid initial listing status' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || ':' || p_request::text, 0));
  v_claim := public.claim_listing_creation(p_request,p_payload_hash);
  v_id := (v_claim->>'listing_id')::uuid;
  if (v_claim->>'completed')::boolean then
    return jsonb_build_object('listing_id',v_id,'completed',true,'replayed',true);
  end if;

  insert into public.listings(
    id,seller_id,source_car_id,title,description,category,subcategory,condition,
    grade,condition_checklist,price_cents,shipping_cents,shipping_mode,
    weight_oz,length_in,width_in,height_in,show_offer_floor,allows_collection,
    location,compatibility_notes,part_number,status,
    brand,part_miles,part_miles_unit
  ) values (
    v_id,v_actor,nullif(p_listing->>'source_car_id','')::uuid,
    p_listing->>'title',nullif(p_listing->>'description',''),p_listing->>'category',
    nullif(p_listing->>'subcategory',''),nullif(p_listing->>'condition',''),
    nullif(p_listing->>'grade',''),nullif(p_listing->'condition_checklist','null'::jsonb),
    (p_listing->>'price_cents')::integer,(p_listing->>'shipping_cents')::integer,
    p_listing->>'shipping_mode',nullif(p_listing->>'weight_oz','')::numeric,
    nullif(p_listing->>'length_in','')::numeric,nullif(p_listing->>'width_in','')::numeric,
    nullif(p_listing->>'height_in','')::numeric,
    coalesce((p_listing->>'show_offer_floor')::boolean,false),
    (p_listing->>'allows_collection')::boolean,nullif(p_listing->>'location',''),
    nullif(p_listing->>'compatibility_notes',''),nullif(p_listing->>'part_number',''),v_status,
    nullif(btrim(p_listing->>'brand'),''),
    nullif(p_listing->>'part_miles','')::integer,
    nullif(p_listing->>'part_miles_unit','')
  ) on conflict(id) do nothing;
  -- The minimum goes to listing_private_terms through its setter, and only when
  -- this call created the listing; a retry is compared by the check below.
  get diagnostics v_inserted = row_count;
  if v_inserted = 1 then
    perform public.set_listing_offer_floor(v_id, nullif(p_listing->>'offer_floor_cents','')::integer);
  end if;

  select * into strict v_existing from public.listings where id=v_id for update;
  if v_existing.seller_id is distinct from v_actor
     or v_existing.source_car_id is distinct from nullif(p_listing->>'source_car_id','')::uuid
     or v_existing.title is distinct from p_listing->>'title'
     or v_existing.description is distinct from nullif(p_listing->>'description','')
     or v_existing.category is distinct from p_listing->>'category'
     or v_existing.subcategory is distinct from nullif(p_listing->>'subcategory','')
     or v_existing.condition is distinct from nullif(p_listing->>'condition','')
     or v_existing.grade is distinct from nullif(p_listing->>'grade','')
     or v_existing.condition_checklist is distinct from nullif(p_listing->'condition_checklist','null'::jsonb)
     or v_existing.price_cents is distinct from (p_listing->>'price_cents')::integer
     or v_existing.shipping_cents is distinct from (p_listing->>'shipping_cents')::integer
     or v_existing.shipping_mode is distinct from p_listing->>'shipping_mode'
     or v_existing.weight_oz is distinct from nullif(p_listing->>'weight_oz','')::numeric
     or v_existing.length_in is distinct from nullif(p_listing->>'length_in','')::numeric
     or v_existing.width_in is distinct from nullif(p_listing->>'width_in','')::numeric
     or v_existing.height_in is distinct from nullif(p_listing->>'height_in','')::numeric
     or public.my_listing_offer_floor(v_id) is distinct from nullif(p_listing->>'offer_floor_cents','')::integer
     or v_existing.show_offer_floor is distinct from coalesce((p_listing->>'show_offer_floor')::boolean,false)
     or v_existing.allows_collection is distinct from (p_listing->>'allows_collection')::boolean
     or v_existing.location is distinct from nullif(p_listing->>'location','')
     or v_existing.compatibility_notes is distinct from nullif(p_listing->>'compatibility_notes','')
     or v_existing.part_number is distinct from nullif(p_listing->>'part_number','')
     or v_existing.brand is distinct from nullif(btrim(p_listing->>'brand'),'')
     or v_existing.part_miles is distinct from nullif(p_listing->>'part_miles','')::integer
     or v_existing.part_miles_unit is distinct from nullif(p_listing->>'part_miles_unit','')
     or v_existing.status is distinct from v_status then
    raise exception 'Listing changed after this request began; refresh before continuing'
      using errcode='40001';
  end if;

  delete from public.listing_images where listing_id=v_id;
  insert into public.listing_images(listing_id,url,alt,position)
  select v_id,item->>'url',nullif(item->>'alt',''),ordinality-1
  from jsonb_array_elements(p_images) with ordinality as image(item,ordinality);

  delete from public.listing_fitments where listing_id=v_id;
  insert into public.listing_fitments(listing_id,make,model,year_start,year_end)
  select v_id,item->>'make',item->>'model',nullif(item->>'year_start','')::integer,
         nullif(item->>'year_end','')::integer
  from jsonb_array_elements(p_fitments) as fitment(item);

  delete from public.listing_part_numbers where listing_id=v_id;
  insert into public.listing_part_numbers(listing_id,number)
  select v_id,value from jsonb_array_elements_text(p_alt_numbers) as number(value);

  if p_mod_item is not null and v_existing.source_car_id is not null then
    update public.mod_items m set linked_listing_id=v_id
    where m.id=p_mod_item and m.car_id=v_existing.source_car_id
      and exists(select 1 from public.cars c where c.id=m.car_id and c.owner_id=v_actor);
    if not found then
      raise exception 'Build line does not belong to this listing source car' using errcode='42501';
    end if;
  end if;

  perform public.complete_listing_creation(p_request,p_payload_hash,v_id);
  return jsonb_build_object('listing_id',v_id,'completed',true,'replayed',false);
end;
$$;


--
-- Name: save_listing_edit(uuid, text, uuid, timestamp with time zone, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_listing_edit(p_request uuid, p_payload_hash text, p_listing uuid, p_expected_updated_at timestamp with time zone, p_fields jsonb, p_images jsonb, p_fitments jsonb, p_alt_numbers jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_prior jsonb;
  v_saved jsonb;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('listing-edit:' || v_actor::text || ':' || p_request::text, 0));

  v_prior := public.replay_listing_edit(p_request, p_payload_hash, p_listing, p_expected_updated_at);
  if v_prior is not null then
    return v_prior || jsonb_build_object('replayed', true);
  end if;

  v_saved := public.update_listing_atomic(
    p_listing, p_expected_updated_at, p_fields, p_images, p_fitments, p_alt_numbers
  );
  -- 20261007100300: the pass record_listing_edit asks for, held only for
  -- that one call.
  perform set_config('drvn.listing_edit_request', p_request::text, true);
  perform public.record_listing_edit(
    p_request, p_payload_hash, p_listing, p_expected_updated_at, v_saved
  );
  perform set_config('drvn.listing_edit_request', '', true);
  return v_saved || jsonb_build_object('replayed', false);
end;
$$;


--
-- Name: save_marketplace_search(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_marketplace_search(p_name text, p_params jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare found_id uuid;
begin
 if auth.uid() is null then raise exception 'Sign in to save searches'; end if;
 if jsonb_typeof(p_params)<>'object' or p_params->>'_version' is distinct from '2' or octet_length(p_params::text)>5000 then raise exception 'Invalid saved search'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
 select id into found_id from public.saved_searches where user_id=auth.uid() and params=p_params order by created_at limit 1;
 if found_id is not null then return found_id; end if;
 insert into public.saved_searches(user_id,name,params,alert) values(auth.uid(),left(p_name,120),p_params,false) returning id into found_id;
 return found_id;
end;
$$;


--
-- Name: save_mod_items(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_mod_items(p_car_id uuid, p_items jsonb, p_expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_items jsonb := coalesce(p_items, '[]'::jsonb);
  v_expected integer;
  v_written integer;
  v_current text;
begin
  if auth.uid() is null then
    raise exception 'Sign in to save this build.' using errcode = '42501';
  end if;
  if p_car_id is null then
    raise exception 'Missing car.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_items) <> 'array' then
    raise exception 'Modification lines must be an array.' using errcode = '22023';
  end if;

  v_expected := jsonb_array_length(v_items);
  if v_expected > 200 then
    raise exception 'A build can contain at most 200 modification lines.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.cars c where c.id = p_car_id and c.owner_id = auth.uid()
  ) then
    raise exception 'Car not found.' using errcode = '42501';
  end if;
  if p_expected_revision is null then
    raise exception 'Reload the build before saving.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where coalesce(item->>'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) then
    raise exception 'Every modification line needs a stable id.' using errcode = '22023';
  end if;
  if exists (
    select item->>'id'
    from jsonb_array_elements(v_items) item
    group by item->>'id'
    having count(*) > 1
  ) then
    raise exception 'Modification line ids must be unique.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    join public.mod_items existing on existing.id = (item->>'id')::uuid
    where existing.car_id <> p_car_id
  ) then
    raise exception 'A modification line belongs to another car.' using errcode = '42501';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where nullif(item->>'category', '') is not null
      and item->>'category' not in (
        'suspension', 'exhaust', 'intake', 'turbo', 'wheels', 'brakes',
        'ecu-tune', 'aero-exterior', 'interior', 'drivetrain'
      )
  ) then
    raise exception 'Unsupported modification category.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where nullif(item->>'confidence', '') is not null
      and ((item->>'confidence')::real < 0 or (item->>'confidence')::real > 1)
  ) then
    raise exception 'Modification confidence must be between zero and one.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where coalesce(nullif(item->>'status', ''), 'installed') not in ('installed', 'removed')
  ) then
    raise exception 'A modification line is neither installed nor removed.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where nullif(item->>'origin', '') is not null
      and item->>'origin' not in ('aftermarket', 'stock')
  ) then
    raise exception 'A modification line is neither aftermarket nor stock.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_items) item
    where nullif(item->>'ref_price_cents', '') is not null
      and (
        nullif(btrim(item->>'ref_price_currency'), '') is null
        or (item->>'ref_price_cents')::integer < 0
      )
  ) then
    raise exception 'A reference price needs a currency.' using errcode = '22023';
  end if;

  -- N65 (OS-W21 follow-on, OS-W23): the sheet is saved only over the version
  -- the editor loaded. Saves of one car queue on its row; then the current
  -- revision must be the one the caller read, or nothing is written — an
  -- older tab, or a draft the agent read before a newer edit, can no longer
  -- delete or overwrite lines it never saw.
  perform 1 from public.cars c where c.id = p_car_id for update;
  v_current := public.mod_sheet_revision(p_car_id);
  if v_current is distinct from p_expected_revision then
    -- A retry of a save that already committed (its response was lost)
    -- finds the sheet exactly as it asked: report it saved, write nothing.
    if public.mod_sheet_matches(p_car_id, v_items) then
      return jsonb_build_object(
        'outcome', 'saved',
        'revision', v_current,
        'items', coalesce((
          select jsonb_agg(
                   jsonb_build_object('id', item.id, 'position', item.position, 'status', item.status)
                   order by item.position
                 )
          from public.mod_items item
          where item.car_id = p_car_id
        ), '[]'::jsonb)
      );
    end if;
    raise exception 'This build changed since you opened it — in another tab or from your agent. Reload to see the latest.'
      using errcode = '40001', hint = 'stale_mod_sheet';
  end if;

  -- A row the payload omits is a row the editor deleted — unless the editor
  -- never knew it. A line released for sale (A-1: delete only where it can't
  -- orphan a listing) and a line that came from a purchase (C-1) are both
  -- written from OTHER screens, so a sheet left open in a second tab would
  -- omit them and this statement would erase them. Neither is deletable from
  -- the sheet: they come off the car by being marked removed.
  delete from public.mod_items existing
  where existing.car_id = p_car_id
    and existing.linked_listing_id is null
    and existing.source_order_item_id is null
    and not exists (
      select 1
      from jsonb_array_elements(v_items) item
      where (item->>'id')::uuid = existing.id
    );

  insert into public.mod_items (
    id, car_id, group_label, category, brand, product, part_number,
    raw_text, confidence, position, status, removed_at,
    product_url, image_url, source_domain, ref_price_cents, ref_price_currency,
    origin, updated_at
  )
  select
    (item.value->>'id')::uuid,
    p_car_id,
    coalesce(nullif(btrim(item.value->>'group_label'), ''), 'Other'),
    nullif(item.value->>'category', ''),
    nullif(btrim(item.value->>'brand'), ''),
    nullif(btrim(item.value->>'product'), ''),
    nullif(btrim(item.value->>'part_number'), ''),
    nullif(btrim(item.value->>'raw_text'), ''),
    case when nullif(item.value->>'confidence', '') is null
      then null else (item.value->>'confidence')::real end,
    item.ordinality::integer - 1,
    coalesce(nullif(item.value->>'status', ''), 'installed'),
    case when coalesce(nullif(item.value->>'status', ''), 'installed') = 'removed'
      then now() else null end,
    nullif(btrim(item.value->>'product_url'), ''),
    nullif(btrim(item.value->>'image_url'), ''),
    nullif(btrim(item.value->>'source_domain'), ''),
    case when nullif(item.value->>'ref_price_cents', '') is null
      then null else (item.value->>'ref_price_cents')::integer end,
    nullif(btrim(item.value->>'ref_price_currency'), ''),
    coalesce(nullif(item.value->>'origin', ''), 'aftermarket'),
    now()
  from jsonb_array_elements(v_items) with ordinality as item(value, ordinality)
  on conflict (id) do update set
    group_label = excluded.group_label,
    category = excluded.category,
    brand = excluded.brand,
    product = excluded.product,
    part_number = excluded.part_number,
    raw_text = excluded.raw_text,
    confidence = excluded.confidence,
    position = excluded.position,
    status = excluded.status,
    -- Derived, never client-supplied: a line that was already off the car
    -- keeps the date it came off; re-fitting one clears it.
    removed_at = case
      when excluded.status = 'removed'
        then coalesce(public.mod_items.removed_at, now())
      else null
    end,
    product_url = excluded.product_url,
    image_url = excluded.image_url,
    source_domain = excluded.source_domain,
    ref_price_cents = excluded.ref_price_cents,
    ref_price_currency = excluded.ref_price_currency,
    -- An editor that predates origin omits it; the line keeps what it was.
    origin = coalesce(
      (select nullif(sent->>'origin', '')
         from jsonb_array_elements(v_items) sent
        where (sent->>'id')::uuid = excluded.id),
      public.mod_items.origin
    ),
    updated_at = excluded.updated_at
  where public.mod_items.car_id = excluded.car_id;

  get diagnostics v_written = row_count;
  if v_written <> v_expected then
    raise exception 'The modification sheet changed while it was being saved.' using errcode = '40001';
  end if;

  return jsonb_build_object(
    'outcome', 'saved',
    'revision', public.mod_sheet_revision(p_car_id),
    'items', coalesce((
      select jsonb_agg(
               jsonb_build_object('id', item.id, 'position', item.position, 'status', item.status)
               order by item.position
             )
      from public.mod_items item
      where item.car_id = p_car_id
    ), '[]'::jsonb)
  );
end;
$_$;


--
-- Name: saved_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_counts() RETURNS TABLE(parts integer, unavailable_parts integer, builds integer, posts integer, followed_builds integer, followed_sellers integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    (select count(*)::integer from public.saves s
      where s.user_id = auth.uid() and s.target_type = 'listing'
        and exists (select 1 from public.listings l where l.id = s.target_id)),
    (select count(*)::integer from public.saves s
      where s.user_id = auth.uid() and s.target_type = 'listing'
        and not exists (select 1 from public.listings l where l.id = s.target_id)),
    (select count(*)::integer from public.saves s
      where s.user_id = auth.uid() and s.target_type = 'car'
        and exists (select 1 from public.cars c where c.id = s.target_id)),
    (select count(*)::integer from public.saves s
      where s.user_id = auth.uid() and s.target_type = 'post'
        and exists (select 1 from public.activity_posts p
                     where p.id = s.target_id and p.published_at is not null)),
    (select count(*)::integer from public.follows f
      where f.follower_id = auth.uid() and f.target_type = 'car'
        and exists (select 1 from public.cars c where c.id = f.target_id)),
    (select count(*)::integer from public.follows f
      where f.follower_id = auth.uid() and f.target_type = 'profile'
        and exists (select 1 from public.profiles pr where pr.id = f.target_id));
$$;


--
-- Name: FUNCTION saved_counts(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.saved_counts() IS 'The caller''s Saved totals, of targets that exist and they can see; unavailable_parts are saves of parts they no longer can (N31, N61).';


--
-- Name: saved_listing_page(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_listing_page(p_query text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0) RETURNS TABLE(listing_id uuid, total integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with mine as (
    select l.id, l.created_at, l.price_cents
    from public.saves s
    join public.listings l on l.id = s.target_id
    where s.user_id = auth.uid() and s.target_type = 'listing'
      and (nullif(btrim(coalesce(p_query, '')), '') is null
           or l.title ilike '%' || replace(replace(replace(btrim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%')
  )
  select m.id, (count(*) over ())::integer
  from mine m
  order by
    case when p_sort = 'price' then m.price_cents end asc,
    case when p_sort = 'price' then m.id end asc,
    m.created_at desc,
    m.id desc
  offset greatest(coalesce(p_offset, 0), 0)
  limit least(greatest(coalesce(p_limit, 24), 1), 100);
$$;


--
-- Name: FUNCTION saved_listing_page(p_query text, p_sort text, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.saved_listing_page(p_query text, p_sort text, p_limit integer, p_offset integer) IS 'One page of the caller''s saved parts they can still see, by title search, newest or price, with the total (N31).';


--
-- Name: saved_page(text, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_page(p_collection text, p_limit integer DEFAULT 24, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(target_id uuid, saved_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 24), 1), 101);
  v_positioned boolean := p_before_at is not null and p_before_id is not null;
begin
  if p_collection = 'build' then
    return query
    select s.target_id, s.created_at from public.saves s
    where s.user_id = auth.uid() and s.target_type = 'car'
      and exists (select 1 from public.cars c where c.id = s.target_id)
      and (not v_positioned or (s.created_at, s.target_id) < (p_before_at, p_before_id))
    order by s.created_at desc, s.target_id desc limit v_limit;
  elsif p_collection = 'post' then
    return query
    select s.target_id, s.created_at from public.saves s
    where s.user_id = auth.uid() and s.target_type = 'post'
      and exists (select 1 from public.activity_posts p
                   where p.id = s.target_id and p.published_at is not null)
      and (not v_positioned or (s.created_at, s.target_id) < (p_before_at, p_before_id))
    order by s.created_at desc, s.target_id desc limit v_limit;
  elsif p_collection = 'unavailable_part' then
    return query
    select s.target_id, s.created_at from public.saves s
    where s.user_id = auth.uid() and s.target_type = 'listing'
      and not exists (select 1 from public.listings l where l.id = s.target_id)
      and (not v_positioned or (s.created_at, s.target_id) < (p_before_at, p_before_id))
    order by s.created_at desc, s.target_id desc limit v_limit;
  elsif p_collection = 'followed_build' then
    return query
    select f.target_id, f.created_at from public.follows f
    where f.follower_id = auth.uid() and f.target_type = 'car'
      and exists (select 1 from public.cars c where c.id = f.target_id)
      and (not v_positioned or (f.created_at, f.target_id) < (p_before_at, p_before_id))
    order by f.created_at desc, f.target_id desc limit v_limit;
  elsif p_collection = 'followed_seller' then
    return query
    select f.target_id, f.created_at from public.follows f
    where f.follower_id = auth.uid() and f.target_type = 'profile'
      and exists (select 1 from public.profiles pr where pr.id = f.target_id)
      and (not v_positioned or (f.created_at, f.target_id) < (p_before_at, p_before_id))
    order by f.created_at desc, f.target_id desc limit v_limit;
  else
    raise exception 'Unknown saved collection' using errcode = '22023';
  end if;
end;
$$;


--
-- Name: FUNCTION saved_page(p_collection text, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.saved_page(p_collection text, p_limit integer, p_before_at timestamp with time zone, p_before_id uuid) IS 'One page of a Saved section (build, post, unavailable_part, followed_build, followed_seller) the caller can see, newest first from a (saved_at, id) position (N68).';


--
-- Name: saved_search_digest_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_search_digest_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_candidate record;
  v_digest record;
  v_carried integer := 0;
  v_expired integer := 0;
  v_pruned integer;
begin
  for v_candidate in
    select d.id, d.saved_search_id from public.saved_search_email_digests d
    where d.status in ('pending', 'sending') and d.next_attempt_at <= now()
      and d.digest_day < private.saved_search_digest_day(now())
    order by d.digest_day, d.id
  loop
    perform 1 from public.saved_searches s where s.id = v_candidate.saved_search_id for update;
    select d.* into v_digest from public.saved_search_email_digests d
    where d.id = v_candidate.id and d.status in ('pending', 'sending') and d.next_attempt_at <= now()
    for update;
    if not found then continue; end if;

    update public.saved_search_email_cursors c
       set checked_through = greatest(v_digest.window_start, private.saved_search_digest_floor()),
           checked_xact = v_digest.window_start_xact, updated_at = now()
     where c.saved_search_id = v_digest.saved_search_id
       and c.checked_through = v_digest.window_end
       and v_digest.window_start_xact is not null;
    if found then
      update public.saved_search_email_digests
         set status = 'skipped', skip_reason = 'carried', updated_at = now() where id = v_digest.id;
      v_carried := v_carried + 1;
    else
      update public.saved_search_email_digests
         set status = 'skipped', skip_reason = 'expired', updated_at = now() where id = v_digest.id;
      v_expired := v_expired + 1;
    end if;
  end loop;
  delete from public.saved_search_email_digests d where d.created_at < now() - interval '90 days';
  get diagnostics v_pruned = row_count;
  return jsonb_build_object('carried', v_carried, 'expired', v_expired, 'pruned', v_pruned);
end;
$$;


--
-- Name: saved_search_digests_due(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_search_digests_due(p_limit integer DEFAULT 200) RETURNS TABLE(saved_search_id uuid, user_id uuid, params jsonb, checked_through timestamp with time zone, checked_xact bigint, window_end timestamp with time zone, window_xact bigint, window_floor timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.id, s.user_id, s.params, c.checked_through, c.checked_xact, now(), private.snapshot_xmin(),
         greatest(private.saved_search_digest_floor(), c.activated_at)
  from public.saved_searches s
  left join public.saved_search_email_cursors c on c.saved_search_id = s.id
  where s.alert
    and (c.saved_search_id is null
         or (private.saved_search_digest_day(c.checked_through) < private.saved_search_digest_day(now())
             and extract(hour from now() at time zone 'Europe/London') >= 8))
    and not exists (
      select 1 from public.saved_search_email_digests d
      where d.saved_search_id = s.id and d.status in ('pending', 'sending')
        and d.digest_day < private.saved_search_digest_day(now()))
  order by c.checked_through nulls first, s.id
  limit least(greatest(coalesce(p_limit, 200), 1), 500)
$$;


--
-- Name: saved_search_email_window_start(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_search_email_window_start() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.alert and (tg_op = 'INSERT' or not old.alert) then
    insert into public.saved_search_email_cursors (saved_search_id, checked_through, checked_xact, activated_at)
    values (new.id, now(), private.snapshot_xmin(), now())
    on conflict (saved_search_id) do update
      set checked_through = excluded.checked_through, checked_xact = excluded.checked_xact,
          activated_at = excluded.activated_at, updated_at = now();
  elsif tg_op = 'UPDATE' and old.alert and not new.alert then
    update public.saved_search_email_digests
       set status = 'skipped', skip_reason = 'alert_off', updated_at = now()
     where saved_search_id = new.id and status in ('pending', 'sending');
  end if;
  return null;
end;
$$;


--
-- Name: scrub_deleted_account(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrub_deleted_account(p_user uuid, p_email_digest text, p_digest_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_request public.account_deletion_requests%rowtype;
  v_blockers jsonb;
  v_last_activity timestamptz;
  v_username text;
  v_counts jsonb := '{}'::jsonb;
  n integer;
  removed constant text := 'Removed: this member deleted their account.';
  left_drvn constant text := 'A member who has since left DRVN';
begin
  if p_user is null then
    raise exception 'A deletion scrub needs an account' using errcode = '22023';
  end if;
  -- The deletion lock the hold gate, finalise and the hold requeue take
  -- (20261108130400), so a hold can't commit halfway through a scrub.
  perform pg_advisory_xact_lock(private.account_deletion_lock_key(p_user));

  select * into v_request from public.account_deletion_requests where user_id = p_user for update;
  -- A case resumed after a hold still reads temporary_financial_hold until
  -- its outcome is recorded, so the live blocker check below decides.
  if not found
     or not exists (select 1 from public.remediation_jobs j where j.dedup_key = 'delete:' || p_user::text) then
    raise exception 'This account has no deletion under way' using errcode = '55000';
  end if;
  -- Never while money is still moving: the other party may need the address.
  v_blockers := public.account_deletion_blockers(p_user);
  if coalesce((v_blockers->>'financial_hold')::boolean, true) then
    raise exception 'This account still has orders or payments in progress' using errcode = '55000';
  end if;
  if v_request.email_digest is null and p_email_digest is not null then
    if p_email_digest !~ '^[0-9a-f]{64}$' or nullif(btrim(p_digest_key), '') is null then
      raise exception 'The email digest is malformed' using errcode = '22023';
    end if;
  end if;

  perform set_config('drvn.account_scrub', p_user::text, true);

  -- Auth: the email, the phone, the sign-in metadata, and linked identities
  -- (a Google identity carries the email and name). Sessions were revoked
  -- by the ban before this runs.
  update auth.users
     set email = null,
         email_change = '',
         raw_user_meta_data = '{}'::jsonb
   where id = p_user;
  if exists (select 1 from information_schema.columns
              where table_schema = 'auth' and table_name = 'users' and column_name = 'phone') then
    update auth.users set phone = null, phone_change = '' where id = p_user;
  end if;
  if to_regclass('auth.identities') is not null then
    update auth.identities
       set identity_data = jsonb_strip_nulls(jsonb_build_object(
             'sub', identity_data->'sub', 'provider_id', identity_data->'provider_id'))
     where user_id = p_user;
  end if;
  delete from public.account_emails where user_id = p_user;
  update public.beta_memberships
     set email_normalized = 'deleted-' || p_user::text || '@deleted.invalid'
   where user_id = p_user;
  update public.beta_invitations
     set email_normalized = 'deleted-' || p_user::text || '@deleted.invalid'
   where consumed_by = p_user;

  -- The profile: the handle is retired (N38), never handed out again.
  select username into v_username from public.profiles where id = p_user;
  if v_username is not null and v_username ~ '^[a-z0-9_]{3,30}$' then
    -- N418: the claim's lock (guard_username_choice), so a claim of this
    -- handle can't slip in between the tombstone and the commit.
    perform pg_advisory_xact_lock(private.username_lock_key(v_username));
    insert into private.username_tombstones (username) values (v_username) on conflict (username) do nothing;
  end if;
  update public.profiles
     set avatar_url = null, display_name = 'Deleted member', username = null, bio = null,
         headline = null, location = null, country = null, region = null, store_note = null,
         main_car_id = null, default_offer_floor_pct = null, links = '[]'::jsonb
   where id = p_user;

  -- Addresses: their ship-from and return addresses, the delivery details
  -- on orders they bought (country and the collection flag stay, as keys),
  -- and the shipping snapshot a checkout journalled.
  delete from public.seller_fulfillment_profiles where seller_id = p_user;
  update public.orders
     set ship_name = null, ship_line1 = null, ship_line2 = null, ship_city = null,
         ship_postcode = null, ship_state = null, ship_phone = null,
         accepted_checkout_shipping = case when accepted_checkout_shipping is null then null
           else jsonb_strip_nulls(jsonb_build_object(
             'country', accepted_checkout_shipping->'country',
             'isCollection', accepted_checkout_shipping->'isCollection')) end,
         buyer_label = 'Deleted member'
   where buyer_id = p_user;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('orders_bought', n);
  update public.purchase_attempts
     set checkout_context = checkout_context - 'shipping' - 'destinationHash'
   where buyer_id = p_user and checkout_context is not null;

  -- Order party labels on the other side.
  update public.orders set seller_label = 'Deleted member' where seller_id = p_user;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('orders_sold', n);

  -- What they wrote. Message threads and question threads keep their shape
  -- (the other party's replies still make sense); comments go.
  update public.messages
     set body = removed, attachments = '{}'
   where sender_id = p_user and kind = 'message'
     and (body is distinct from removed or cardinality(attachments) > 0);
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('messages', n);
  update public.conversations c
     set last_message_preview = removed
    from public.messages m
   where m.id = c.last_message_id and m.sender_id = p_user and m.kind = 'message'
     and c.last_message_preview is distinct from removed;
  update public.listing_questions
     set body = removed
   where author_id = p_user and body is distinct from removed;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('questions', n);
  delete from public.activity_comments where author_id = p_user;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('comments', n);

  -- N418 and 20261110220000: what they wrote, as other members'
  -- notifications copied it, found by actor and by the offer or order the
  -- notice is about (private.scrub_member_notices, below).
  v_counts := v_counts || private.scrub_member_notices(p_user, v_username);
  -- Their listing titles in other members' saved-search emails (N1069, work review #153).
  v_counts := v_counts || private.scrub_member_digest_items(p_user);

  -- Their own social record, none of it a transaction key.
  delete from public.notifications where user_id = p_user;
  delete from public.saved_searches where user_id = p_user;
  delete from public.follows where follower_id = p_user or (target_type = 'profile' and target_id = p_user);
  delete from public.listing_imports where user_id = p_user;

  -- The retention clock, fixed on the first scrub.
  select max(greatest(coalesce(o.completed_at, '-infinity'), coalesce(o.refunded_at, '-infinity'),
                      coalesce(o.cancelled_at, '-infinity'), o.updated_at))
    into v_last_activity
    from public.orders o
   where o.buyer_id = p_user or o.seller_id = p_user;

  update public.account_deletion_requests
     set email_digest = coalesce(email_digest, p_email_digest),
         email_digest_key = case when email_digest is null and p_email_digest is not null
                                 then btrim(p_digest_key) else email_digest_key end,
         scrubbed_at = coalesce(scrubbed_at, now()),
         retention_starts_at = coalesce(retention_starts_at, greatest(now(), coalesce(v_last_activity, now()))),
         retain_until = coalesce(retain_until, greatest(now(), coalesce(v_last_activity, now())) + interval '6 years'),
         -- Decided now: the retention period (6 years) and what the
         -- anonymization removes (this scrub).
         policy_decisions_pending = array_remove(array_remove(policy_decisions_pending,
           'financial record retention duration'), 'eventual identity anonymization'),
         updated_at = now()
   where id = v_request.id
  returning retain_until into v_request.retain_until;

  -- The address exception ends with the scrub, not with the transaction.
  perform set_config('drvn.account_scrub', '', true);
  return v_counts || jsonb_build_object('retain_until', v_request.retain_until);
end;
$_$;


--
-- Name: search_car_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_car_ids(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 100
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET "pg_trgm.word_similarity_threshold" TO '0.45'
    AS $$
  with terms as (
    select distinct t
    from regexp_split_to_table(lower(coalesce(p_query, '')), '\s+') as t
    where length(t) >= 1
  ),
  -- One row per (car, word it matched). Each arm is answered by a trigram
  -- index, so only matching rows are ever read.
  hits as (
    select c.id, t.t from terms t join public.cars c
      on public.car_search_doc(c.name, c.make, c.model, c.year, c.tags, c.about) ilike '%' || t.t || '%'
     where c.is_public
    union
    select m.car_id, t.t from terms t join public.mod_items m
      on public.mod_search_doc(m.brand, m.product, m.part_number) ilike '%' || t.t || '%'
     where m.status = 'installed'
    union
    select c.id, t.t from terms t join public.cars c on t.t <% c.name
     where c.is_public
  ),
  scored as (
    select
      c.id,
      count(*) as hits,
      bool_or(c.name ilike '%' || h.t || '%') as name_hit,
      similarity(c.name, lower(coalesce(p_query, ''))) as sim
    from hits h
    join public.cars c on c.id = h.id
    join public.profiles o on o.id = c.owner_id
    where c.is_public and o.suspended_at is null
    group by c.id, c.name
  )
  select id from scored
  order by hits desc, name_hit desc, sim desc, id
$$;


--
-- Name: search_listing_documents(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_listing_documents(p_ids uuid[]) RETURNS TABLE(id uuid, doc jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.id, jsonb_build_object(
    'id', l.id::text,
    'sort_id', l.id::text,
    'title', l.title,
    'description', coalesce(l.description, ''),
    'compatibility_notes', coalesce(l.compatibility_notes, ''),
    'part_numbers', array_remove(array[l.part_number, l.part_number_compact], null)
                    || coalesce((select array_agg(n.number order by n.number) from public.listing_part_numbers n where n.listing_id = l.id), '{}'),
    'category', l.category,
    'subcategory', coalesce(l.subcategory, ''),
    'brand', coalesce(l.brand, ''),
    'brand_key', lower(coalesce(l.brand, '')),
    'condition', coalesce(l.condition, ''),
    'status', l.status,
    'price_cents', l.price_cents,
    'created_at_unix', extract(epoch from l.created_at)::bigint,
    'created_at_us', (extract(epoch from l.created_at) * 1000000)::bigint,
    'published_at_us', (extract(epoch from l.published_at) * 1000000)::bigint,
    'seller_id', l.seller_id::text,
    'source_car', case when c.is_public then concat_ws(' ', c.year, c.make, c.model) else '' end,
    'source_car_public', coalesce(c.is_public, false),
    'source_car_year', case when c.is_public then c.year end,
    'fitment', coalesce((select array_agg(concat_ws(' ', f.make, f.model, f.year_start, f.year_end) order by f.id) from public.listing_fitments f where f.listing_id = l.id), '{}'),
    'fit_keys', array(select distinct v.make_key || '|' || v.model_key from public.listing_vehicle_fit v
                       where v.listing_id = l.id and (v.via = 'stated' or (v.car_public and not v.stated_also)) order by 1),
    'fit_any_year', array(select distinct v.make_key || '|' || v.model_key from public.listing_vehicle_fit v
                           where v.listing_id = l.id and v.via = 'car' and v.car_public and not v.stated_also order by 1),
    'fit_year_keys', array(select distinct v.make_key || '|' || v.model_key || '|' || y
                            from public.listing_vehicle_fit v cross join generate_series(1950, 2030) y
                            where v.listing_id = l.id and v.via = 'stated' and v.years @> y order by 1))
  from public.listings l
  left join public.cars c on c.id = l.source_car_id
  where l.id = any(p_ids) and l.status = 'active'
    and l.seller_id not in (select public.suspended_profile_ids());
$$;


--
-- Name: search_listing_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_listing_ids(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET "pg_trgm.word_similarity_threshold" TO '0.45'
    AS $$
  with terms as (
    select distinct t
    from regexp_split_to_table(lower(coalesce(p_query, '')), '\s+') as t
    where length(t) >= 1
  ),
  -- One row per (part, word it matched), each arm answered by a trigram index.
  hits as (
    select l.id, t.t from terms t join public.listings l
      on public.listing_search_doc(l.title, l.description, l.compatibility_notes, l.category, l.brand) ilike '%' || t.t || '%'
    union
    select l.id, t.t from terms t join public.listings l on t.t <% l.title
  ),
  -- What a signed-out visitor may see: this runs with the definer's rights
  -- so the indexes can be used, and so applies the read rule itself.
  visible as (
    select l.id, l.title from public.listings l
    join public.profiles o on o.id = l.seller_id
    where l.status in ('active', 'reserved', 'sold') and o.suspended_at is null
  ),
  scored as (
    select
      v.id,
      count(*) as hits,
      bool_or(v.title ilike '%' || h.t || '%') as title_hit,
      similarity(v.title, lower(coalesce(p_query, ''))) as sim
    from hits h join visible v on v.id = h.id
    group by v.id, v.title
  )
  select id from (
    select id, hits, title_hit, sim, 0 as ord from scored
    union all
    -- No usable words (empty / whitespace query): the unfiltered set.
    select v.id, 0, false, 0::real, 1 as ord
    from visible v
    where not exists (select 1 from terms)
  ) ranked
  order by ord, hits desc, title_hit desc, sim desc, id
$$;


--
-- Name: search_profile_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_profile_ids(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with terms as (
    select distinct t
    from regexp_split_to_table(
      lower(regexp_replace(coalesce(p_query, ''), '@', ' ', 'g')), '\s+'
    ) as t
    where length(t) >= 1
  ),
  profile_text as (
    select
      p.id,
      coalesce(p.display_name, p.username, '') as name,
      p.username,
      concat_ws(' ', p.username, p.display_name, p.headline) as blob
    from public.profiles p
    where p.suspended_at is null
      and (p.username is not null or p.display_name is not null)
  ),
  scored as (
    select
      pt.id,
      bool_or(lower(coalesce(pt.username, '')) = t.t) as exact_username,
      count(*) filter (
        where pt.blob ilike '%' || t.t || '%'
           or word_similarity(t.t, pt.name) >= 0.45
      ) as hits,
      bool_or(pt.name ilike '%' || t.t || '%') as name_hit,
      max(similarity(pt.name, lower(coalesce(p_query, '')))) as sim
    from profile_text pt
    cross join terms t
    group by pt.id
  )
  select id from scored
  where hits > 0
  order by exact_username desc, hits desc, name_hit desc, sim desc
$$;


--
-- Name: search_update_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_update_ids(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 100
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET "pg_trgm.word_similarity_threshold" TO '0.45'
    AS $$
  with terms as (
    select distinct t
    from regexp_split_to_table(lower(coalesce(p_query, '')), '\s+') as t
    where length(t) >= 1
  ),
  -- Cars whose name, make, model or year carry the word. The index covers
  -- the whole car document, so the narrower test is applied to what it finds.
  car_hits as (
    select c.id, t.t from terms t join public.cars c
      on public.car_search_doc(c.name, c.make, c.model, c.year, c.tags, c.about) ilike '%' || t.t || '%'
     where c.is_public
       and concat_ws(' ', c.name, c.make, c.model, c.year::text) ilike '%' || t.t || '%'
  ),
  -- One row per (update, word it matched), each arm answered by an index.
  hits as (
    select p.id, t.t from terms t join public.activity_posts p
      on public.post_search_doc(p.title, p.intro, p.search_text) ilike '%' || t.t || '%'
     where p.published_at is not null
    union
    select p.id, ch.t from car_hits ch join public.activity_posts p on p.car_id = ch.id
     where p.published_at is not null
    union
    select p.id, t.t from terms t join public.activity_posts p on t.t <% p.title
     where p.published_at is not null
  ),
  scored as (
    select
      p.id,
      p.published_at,
      count(*) as hits,
      bool_or(p.title ilike '%' || h.t || '%') as title_hit,
      similarity(coalesce(p.title, ''), lower(coalesce(p_query, ''))) as sim
    from hits h
    join public.activity_posts p on p.id = h.id
    left join public.cars c on c.id = p.car_id
    left join public.profiles o on o.id = c.owner_id
    where p.published_at is not null
      and (p.car_id is null or (c.is_public and o.suspended_at is null))
    group by p.id, p.title, p.published_at
  )
  select id from scored
  order by hits desc, title_hit desc, sim desc, published_at desc, id
$$;


--
-- Name: search_user_messages(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_user_messages(p_query text) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.id
  from public.conversations c
  left join public.profiles p
    on p.id = case when c.participant_a = auth.uid() then c.participant_b else c.participant_a end
  where (c.participant_a = auth.uid() or c.participant_b = auth.uid())
    and (
      c.last_message_preview ilike '%' || p_query || '%'
      or p.display_name ilike '%' || p_query || '%'
      or p.username ilike '%' || p_query || '%'
      or exists (
        select 1 from public.messages m
        where m.conversation_id = c.id
          and m.body ilike '%' || p_query || '%'
      )
    )
  order by c.last_message_at desc nulls last
  limit 50;
$$;


--
-- Name: search_word_corrections(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_word_corrections(p_query text) RETURNS TABLE(word text, correction text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
  select q.word, c.word
  from (select distinct t as word
        from regexp_split_to_table(lower(left(coalesce(p_query, ''), 200)), '\s+') t
        where t ~ '^[[:alpha:]]{4,30}$'
        limit 8) q
  cross join lateral (
    select s.word from public.search_words s
    order by s.word <-> q.word, s.uses desc
    limit 1) c
  where not exists (select 1 from public.search_words s where s.word = q.word)
    and similarity(c.word, q.word) >= 0.35;
$_$;


--
-- Name: seller_active_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_active_counts(p_sellers uuid[]) RETURNS TABLE(seller_id uuid, total bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.seller_id, count(*)::bigint
    from public.listings l
   where l.seller_id = any(p_sellers)
     and l.status = 'active'
   group by l.seller_id;
$$;


--
-- Name: seller_carry_available_cents(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_carry_available_cents(p_seller uuid, p_except_order uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(0,
    -coalesce((select sum(e.amount_cents) from public.seller_carry_entries e where e.seller_id = p_seller), 0)
    - coalesce((
        select sum(ti.dispatch_carry_cents) from public.transfer_intents ti
         where ti.seller_id = p_seller
           and ti.order_id is distinct from p_except_order
           and ti.dispatch_carry_cents > 0
           -- 20261007100400: only a reservation that binds. Until a dispatch
           -- is prepared (operation_key) nothing has been promised to
           -- Stripe and freeze_transfer_carry re-decides the amount on the
           -- next attempt, so an amount left on an intent that fell back to
           -- holding or failed before then reserves nothing; the one worker
           -- between its freeze and its dispatch is 'processing'.
           and (ti.status = 'processing'
                or ti.operation_key is not null
                or ti.provider_call_may_have_occurred)
           and (ti.status not in ('transferred', 'cancelled')
                or (ti.status = 'cancelled' and ti.provider_call_may_have_occurred))
      ), 0)
  )::int;
$$;


--
-- Name: seller_listing_stats(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_listing_stats(p_seller uuid, p_register text DEFAULT 'all'::text, p_sort text DEFAULT 'top_offer'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, title text, part_number text, price_cents integer, status text, view_count integer, created_at timestamp with time zone, source_car_id uuid, cover_url text, watch_count integer, top_offer_cents integer, soonest_offer_expiry timestamp with time zone, unanswered_questions integer, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select
      l.id, l.title, l.part_number, l.price_cents, l.status, l.view_count,
      l.created_at, l.source_car_id,
      (select li.url from listing_images li
        where li.listing_id = l.id
        order by li.position, li.created_at
        limit 1) as cover_url,
      (select count(*) from saves s
        where s.target_type = 'listing' and s.target_id = l.id)::int as watch_count,
      (select max(coalesce(o.counter_amount_cents, o.amount_cents)) from offers o
        where o.listing_id = l.id and o.status in ('open', 'countered'))::int as top_offer_cents,
      (select min(o.expires_at) from offers o
        where o.listing_id = l.id and o.status in ('open', 'countered')) as soonest_offer_expiry,
      -- A root question counts as unanswered while no reply points at it —
      -- same definition the page used to compute in JS (unansweredFor).
      (select count(*) from listing_questions q
        where q.listing_id = l.id
          and q.parent_id is null
          and not exists (select 1 from listing_questions a where a.parent_id = q.id)
      )::int as unanswered_questions
    from listings l
    where l.seller_id = p_seller
      and p_seller = auth.uid()
  ),
  filtered as (
    select * from base b
    where case p_register
      when 'live'  then b.status = 'active' and b.top_offer_cents is null
      when 'offer' then b.top_offer_cents is not null
      when 'all'   then true
      else b.status = p_register
    end
  )
  select f.*, count(*) over () as total_count
  from filtered f
  -- Every measure sorts descending (the seller wants the loudest row first);
  -- created_at desc is both the 'newest' sort and the tiebreak, matching the
  -- old in-memory stable sort over a newest-first fetch. Unknown sort keys
  -- fall through to newest.
  order by
    case when p_sort = 'top_offer' then f.top_offer_cents end desc nulls last,
    case when p_sort = 'views'     then f.view_count end desc,
    case when p_sort = 'watch'     then f.watch_count end desc,
    case when p_sort = 'asking'    then f.price_cents end desc,
    f.created_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


--
-- Name: seller_open_question_list(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_open_question_list(p_limit integer DEFAULT 5) RETURNS TABLE(id uuid, listing_id uuid, listing_title text, body text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select q.id, q.listing_id, l.title, q.body, q.created_at
  from public.listing_questions q
  join public.listings l on l.id = q.listing_id
  where l.seller_id = auth.uid()
    and q.parent_id is null
    and not exists (select 1 from public.listing_questions a where a.parent_id = q.id)
  order by q.created_at desc
  limit least(greatest(coalesce(p_limit, 5), 1), 20);
$$;


--
-- Name: seller_open_questions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_open_questions(p_seller uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select count(*)
  from public.listing_questions q
  join public.listings l on l.id = q.listing_id
  where l.seller_id = p_seller
    and p_seller = auth.uid()
    and q.parent_id is null
    and not exists (
      select 1 from public.listing_questions a where a.parent_id = q.id
    );
$$;


--
-- Name: seller_payout_dates(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_payout_dates(p_orders uuid[]) RETURNS TABLE(order_id uuid, available_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.order_id, t.available_at
    from public.transfer_intents t
    join public.orders o on o.id = t.order_id
   where t.order_id = any (p_orders)
     and o.seller_id = (select auth.uid())
     and t.available_at is not null;
$$;


--
-- Name: seller_register_tally(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_register_tally(p_seller uuid) RETURNS TABLE(all_count bigint, live_count bigint, offer_count bigint, draft_count bigint, paused_count bigint, reserved_count bigint, archived_count bigint, sold_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select
      l.status,
      exists (select 1 from offers o
        where o.listing_id = l.id and o.status in ('open', 'countered')) as under_offer
    from listings l
    where l.seller_id = p_seller
      and p_seller = auth.uid()
  )
  select
    count(*) as all_count,
    count(*) filter (where status = 'active' and not under_offer) as live_count,
    count(*) filter (where under_offer) as offer_count,
    count(*) filter (where status = 'draft') as draft_count,
    count(*) filter (where status = 'paused') as paused_count,
    count(*) filter (where status = 'reserved') as reserved_count,
    count(*) filter (where status = 'archived') as archived_count,
    count(*) filter (where status = 'sold') as sold_count
  from base;
$$;


--
-- Name: seller_review_summaries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seller_review_summaries(p_sellers uuid[]) RETURNS TABLE(seller_id uuid, review_count integer, rating_avg numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if cardinality(coalesce(p_sellers, '{}')) > 200 then
    raise exception 'At most 200 sellers per call' using errcode = '22023';
  end if;
  return query
  select r.reviewee_id, count(*)::integer, avg(r.rating)::numeric
  from public.reviews r
  where r.reviewee_id = any(coalesce(p_sellers, '{}'))
  group by r.reviewee_id;
end;
$$;


--
-- Name: FUNCTION seller_review_summaries(p_sellers uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.seller_review_summaries(p_sellers uuid[]) IS 'Review count and average rating per seller, over every review (N30). A seller with none is absent. Caller''s rights. At most 200 ids.';


--
-- Name: set_analytics_consent(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analytics_consent(p_allowed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if auth.uid() is null or not public.profile_is_visible(auth.uid()) then raise exception 'Active account required' using errcode='42501'; end if;
 insert into public.analytics_consents(user_id,allowed) values(auth.uid(),p_allowed)
 on conflict(user_id) do update set allowed=p_allowed,version=gen_random_uuid(),expires_at=now()+interval '180 days';
end $$;


--
-- Name: set_listing_offer_floor(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_listing_offer_floor(p_listing uuid, p_floor integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_listing public.listings;
begin
  select * into v_listing from public.listings where id = p_listing for update;
  if not found or v_listing.seller_id is distinct from (select auth.uid()) then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if public.is_suspended(v_listing.seller_id) then
    raise exception 'account is suspended' using errcode = '42501';
  end if;
  if v_listing.status in ('sold', 'reserved', 'removed') then
    raise exception 'A sold, reserved or removed listing can''t be edited' using errcode = '55000';
  end if;
  if p_floor is not null and (p_floor <= 0 or p_floor > v_listing.price_cents) then
    raise exception 'The offer minimum must be above zero and no more than the asking price'
      using errcode = '23514';
  end if;
  insert into public.listing_private_terms(listing_id, seller_id, offer_floor_cents)
  values (v_listing.id, v_listing.seller_id, p_floor)
  on conflict (listing_id) do update
    set offer_floor_cents = excluded.offer_floor_cents,
        seller_id = excluded.seller_id,
        updated_at = now();
end;
$$;


--
-- Name: FUNCTION set_listing_offer_floor(p_listing uuid, p_floor integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_listing_offer_floor(p_listing uuid, p_floor integer) IS 'Sets or clears the seller''s private offer minimum on their own listing (20261019120000).';


--
-- Name: set_social_relationship(text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_social_relationship(p_kind text, p_target_type text, p_target_id uuid, p_active boolean) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_target_id is null or p_active is null then
    raise exception 'Target and desired state are required' using errcode = '22023';
  end if;

  if p_kind = 'save' and p_target_type in ('listing', 'car', 'profile', 'post') then
    if p_active then
      insert into public.saves(user_id, target_type, target_id)
      values(uid, p_target_type, p_target_id)
      on conflict(user_id, target_type, target_id) do nothing;
    else
      delete from public.saves
      where user_id = uid and target_type = p_target_type and target_id = p_target_id;
    end if;
  elsif p_kind = 'like' and p_target_type in ('listing', 'car') then
    if p_active then
      insert into public.likes(user_id, target_type, target_id)
      values(uid, p_target_type, p_target_id)
      on conflict(user_id, target_type, target_id) do nothing;
    else
      delete from public.likes
      where user_id = uid and target_type = p_target_type and target_id = p_target_id;
    end if;
  elsif p_kind = 'follow' and p_target_type in ('car', 'profile') then
    if p_active then
      insert into public.follows(follower_id, target_type, target_id)
      values(uid, p_target_type, p_target_id)
      on conflict(follower_id, target_type, target_id) do nothing;
    else
      delete from public.follows
      where follower_id = uid and target_type = p_target_type and target_id = p_target_id;
    end if;
  else
    raise exception 'Unsupported social relationship' using errcode = '22023';
  end if;

  return p_active;
end;
$$;


--
-- Name: settle_payment_capture(text, uuid[], integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_payment_capture(p_reference text, p_order_ids uuid[], p_amount integer, p_currency text, p_source text, p_buyer uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o public.orders; v_sum bigint; v_count int; v_result jsonb; v_op jsonb; v_late boolean:=false; v_ids uuid[];
begin
 select array_agg(distinct x order by x) into v_ids from unnest(p_order_ids) x;
 if coalesce(cardinality(v_ids),0)=0 then raise exception 'No orders for captured payment'; end if;
 -- One lock order for every path that sells a listing: listing → offer →
 -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
 perform 1 from public.listings where id in (
   select oi.listing_id from public.order_items oi where oi.order_id=any(v_ids) and oi.listing_id is not null
 ) order by id for update;
 perform 1 from public.orders where id=any(v_ids) order by id for update;
 select sum(total_cents),count(*) into v_sum,v_count from public.orders where id=any(v_ids) and lower(currency)=lower(p_currency) and buyer_id=p_buyer;
 if v_count<>cardinality(v_ids) or v_sum<>p_amount then raise exception 'Captured payment does not match orders'; end if;
 for o in select * from public.orders where id=any(v_ids) order by id loop
   if exists(select 1 from public.payments where order_id=o.id and provider_reference is not null and provider_reference<>p_reference) then raise exception 'Payment reference mismatch'; end if;
   if not exists(select 1 from public.payments where order_id=o.id) then raise exception 'Missing payment ledger'; end if;
   if o.status in ('pending','requires_action') then
     v_result:=public.purchase_finalize(o.id,true,'stripe',p_reference,null);
     if not coalesce((v_result->>'applied')::boolean,false) then raise exception 'Settlement refused'; end if;
     select * into o from public.orders where id=o.id;
   end if;
   if o.status in ('cancelled','payment_failed') then
     v_late:=true;
     update public.payments set provider='stripe',provider_reference=p_reference,status=case when coalesce(refunded_cents,0)>=amount_cents then 'refunded' else 'succeeded' end where order_id=o.id;
     if not exists(select 1 from public.refund_operations where order_id=o.id and purpose='late_capture') then
       v_op:=public.begin_refund_operation(o.id,null,'Payment captured after order cancellation','system:late_capture','system',false,null,p_reference,null,false);
       if not coalesce((v_op->>'ok')::boolean,false) then raise exception 'Cannot reserve compensation: %',v_op; end if;
       update public.refund_operations set purpose='late_capture' where id=(v_op->>'operation_id')::uuid;
     end if;
   elsif o.status in ('paid','shipped','delivered','completed','disputed') then
    if o.refunded_cents<o.total_cents and o.transfer_reference is null then
     insert into public.transfer_intents(order_id,seller_id,amount_cents,currency,status,source_transaction)
       values(o.id,o.seller_id,o.total_cents-o.platform_fee_cents,o.currency,'holding',p_source) on conflict(order_id) do nothing;
     if not exists(select 1 from public.transfer_intents where order_id=o.id and seller_id=o.seller_id and currency=o.currency and amount_cents=o.total_cents-o.platform_fee_cents and (p_source is null or source_transaction=p_source)) then raise exception 'Payout obligation conflict'; end if;
    end if;
   elsif o.status <> 'refunded' then
     raise exception 'Unhandled captured order state: %',o.status;
   end if;
 end loop;
 insert into public.remediation_jobs(kind,dedup_key,payload) values('receipt','receipt:'||p_reference,jsonb_build_object('buyer_id',p_buyer,'order_ids',v_ids,'compensation',v_late)) on conflict(dedup_key) do nothing;
 return jsonb_build_object('outcome',case when v_late then 'compensation_queued' else 'settled' end);
end $$;


--
-- Name: settle_payout_deadline_cancellation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_payout_deadline_cancellation(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_claim private.payout_deadline_cancellations;
  v_order public.orders;
  v_listing_ids uuid[];
  v_seller uuid;
  v_payable boolean;
begin
  if p_order is null then raise exception 'Order is required'; end if;
  select c.seller_id into v_seller from private.payout_deadline_cancellations c where c.order_id = p_order;
  if v_seller is null then
    raise exception 'This order was not cancelled by the payout deadline';
  end if;
  -- Profile, then listing, then order: the order a payouts update and its
  -- restore trigger take.
  select coalesce(p.payouts_enabled, false) into v_payable
  from public.profiles p where p.id = v_seller for share;
  select coalesce(array_agg(oi.listing_id order by oi.listing_id), array[]::uuid[])
    into v_listing_ids
  from public.order_items oi where oi.order_id = p_order and oi.listing_id is not null;
  perform 1 from public.listings where id = any(v_listing_ids) order by id for update;
  select * into v_order from public.orders where id = p_order for update;
  select * into v_claim from private.payout_deadline_cancellations where order_id = p_order for update;
  if v_claim.order_id is null then
    raise exception 'This order was not cancelled by the payout deadline';
  end if;
  if v_claim.settled_at is not null then
    return jsonb_build_object('ok', true, 'complete', true, 'replayed', true);
  end if;
  if v_order.status is distinct from 'refunded' or v_order.refunded_cents < v_order.total_cents then
    return jsonb_build_object('ok', false, 'complete', false, 'status', v_order.status,
                              'reason', 'The refund is not complete yet.');
  end if;

  if coalesce(v_payable, false) and not public.is_suspended(v_claim.seller_id) then
    -- Back on sale only if it could be published; otherwise the seller's,
    -- paused, to finish and publish.
    update public.listings set status = 'active', sold_at = null, reserved_until = null
    where id = any(v_listing_ids) and status = 'sold' and private.listing_can_go_live(id);
    update public.listings set status = 'paused', sold_at = null, reserved_until = null
    where id = any(v_listing_ids) and status = 'sold';
  else
    insert into private.payout_deadline_paused_listings (listing_id, seller_id)
    select l.id, l.seller_id from public.listings l where l.id = any(v_listing_ids) and l.status = 'sold'
    on conflict (listing_id) do nothing;
    update public.listings set status = 'paused', sold_at = null, reserved_until = null
    where id = any(v_listing_ids) and status = 'sold';
  end if;
  update private.payout_deadline_cancellations set settled_at = now() where order_id = p_order;
  return jsonb_build_object('ok', true, 'complete', true, 'replayed', false);
end;
$$;


--
-- Name: settle_refund_operation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_refund_operation(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_op        public.refund_operations;
  v_order     record;
  v_payment   record;
  v_before    int;
  v_after     int;
  v_fully     boolean;
  v_transfer  int;   -- seller share of the order (total − fee)
  v_rev_due   int;
  v_fee_after int;
  v_next      text;
  -- 20261005110100
  v_sent      int;
  v_seller    uuid;
  v_cap       int;
  v_shortfall int := 0;
  -- 20261007100000
  v_share_delta int;
  v_reversed  int;
  -- 20261007100400
  v_closed      record;
  -- 20261107130000
  v_exhausted   int;
  v_adjustments int;
  v_net_before  int;
  v_net_after   int;
begin
  select * into v_op from public.refund_operations
    where id = p_operation_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Operation not found.');
  end if;
  if v_op.status not in ('provider_succeeded', 'effects_pending') then
    return jsonb_build_object('ok', true, 'already', true, 'status', v_op.status,
      'reversal_due_cents', coalesce(v_op.reversal_due_cents, 0),
      'fee_refunded_delta', 0);
  end if;

  select id, status, total_cents, platform_fee_cents, refunded_cents,
         platform_fee_refunded_cents, transfer_reference, pre_dispute_status,
         currency
    into v_order
    from public.orders where id = v_op.order_id
    for update;

  v_before := v_order.refunded_cents;
  v_after  := least(v_before + v_op.amount_cents, v_order.total_cents);
  v_fully  := v_after >= v_order.total_cents;

  -- Seller reversal owed, cumulative-deterministic (matches
  -- reversalShareCents in lib/payments/refunds.ts).
  v_transfer := v_order.total_cents - v_order.platform_fee_cents;
  -- 20261005110100: a transfer can't be reversed by more than was sent. Label
  -- costs and carried-forward charges came off the transfer, so the share can
  -- exceed it; Stripe refused that reversal and it sat in recovery. The
  -- reversal is now capped at the amount sent, and what the cap leaves
  -- unreversed is exactly the charges that transfer had collected — they go
  -- back on the seller's carry-forward balance (seller_carry_entries).
  -- Transfers sent before dispatch amounts were recorded keep the old rule.
  --
  -- 20261007100000: the cap is on what is still reversible — the amount sent
  -- less what earlier refunds of this order already took back — not on the
  -- cumulative refund share. A refund made before the transfer was never
  -- reversed (the transfer was simply sent smaller), so counting its share
  -- against the cap cancelled the reversal of every later refund by that
  -- much: $50 of a $100 order refunded before payout, $50 after, reversed
  -- nothing and left the seller holding $45 of a fully refunded order.
  select ti.dispatch_amount_cents, ti.seller_id into v_sent, v_seller
    from public.transfer_intents ti
   where ti.order_id = v_op.order_id
     and ti.status = 'transferred'
     and ti.transfer_reference is not distinct from v_order.transfer_reference;
  v_cap := least(v_transfer, coalesce(v_sent, v_transfer));
  if v_order.transfer_reference is not null and v_transfer > 0 and v_order.total_cents > 0 then
    v_share_delta := least(v_transfer, round((v_after::numeric * v_transfer) / v_order.total_cents))
                   - least(v_transfer, round((v_before::numeric * v_transfer) / v_order.total_cents));
    if v_sent is null then
      v_rev_due := v_share_delta;
    else
      select coalesce(sum(ro.reversal_due_cents), 0) into v_reversed
        from public.refund_operations ro
       where ro.order_id = v_op.order_id and ro.id <> p_operation_id;
      v_rev_due := least(v_share_delta, greatest(v_cap - v_reversed, 0));
    end if;
    v_shortfall := v_share_delta - v_rev_due;
  else
    v_rev_due := 0;
  end if;

  v_fee_after := least(v_order.platform_fee_cents,
    round((v_after::numeric * v_order.platform_fee_cents) / greatest(v_order.total_cents, 1)));

  update public.orders o
  set refunded_cents = v_after,
      platform_fee_refunded_cents = v_fee_after,
      refunded_at = now(),
      status = case when v_op.purpose = 'late_capture' then o.status when v_fully then 'refunded'
                    when v_op.resolve_dispute and o.status = 'disputed'
                      then coalesce(v_order.pre_dispute_status, 'delivered')
                    else o.status end,
      cancelled_at = case when v_fully then now() else o.cancelled_at end,
      cancel_reason = case when v_fully then left(v_op.reason, 500) else o.cancel_reason end,
      dispute_resolved_at = case when v_op.resolve_dispute and o.status = 'disputed'
                                 then now() else o.dispute_resolved_at end,
      refund_offer_cents = case when v_op.resolve_dispute and o.status = 'disputed'
                                then null else o.refund_offer_cents end,
      refund_offered_at = case when v_op.resolve_dispute and o.status = 'disputed'
                               then null else o.refund_offered_at end,
      dispute_outcome = case when v_op.resolve_dispute and o.status = 'disputed'
                             then v_op.dispute_outcome else o.dispute_outcome end
  where o.id = v_op.order_id;

  select id, amount_cents, refunded_cents into v_payment
    from public.payments where order_id = v_op.order_id
    limit 1;
  if found then
    update public.payments
    set refunded_cents = coalesce(v_payment.refunded_cents, 0) + v_op.amount_cents,
        status = case when coalesce(v_payment.refunded_cents, 0) + v_op.amount_cents
                           >= v_payment.amount_cents
                      then 'refunded' else 'partially_refunded' end
    where id = v_payment.id;
  end if;

  -- 20261007100400: a payout that was ALREADY cancelled — its label costs had
  -- used up what the earlier refunds left of the seller's share — recorded
  -- what the seller owed at that moment (carry_on_transfer_intent_status,
  -- 'uncollected'). A later refund takes away more of that share, so more of
  -- the same label costs is uncovered; nothing recorded it, because the
  -- intent's status no longer changes and there is no transfer to reverse.
  -- Record the difference, with the same arithmetic as that trigger: the
  -- seller's position on the order (share left after refunds, plus live
  -- adjustments), counted only where it is below zero. Read before the
  -- cancellation below, so a payout this very refund cancels is left to the
  -- trigger, which already sees the new refunded amount.
  select ti.amount_cents, ti.seller_id into v_closed
    from public.transfer_intents ti
   where ti.order_id = v_op.order_id
     and ti.status = 'cancelled'
     and ti.transfer_reference is null;
  if found and v_order.transfer_reference is null
     and v_order.total_cents > 0 and v_closed.amount_cents > 0 then
    perform pg_advisory_xact_lock(hashtextextended('seller-carry-order:' || v_op.order_id::text, 0));
    select coalesce(sum(amount_cents), 0)::int into v_adjustments
      from public.seller_adjustments
     where order_id = v_op.order_id and voided_at is null;
    v_net_before := v_closed.amount_cents
      - least(v_closed.amount_cents, round((v_before::numeric * v_closed.amount_cents) / v_order.total_cents)::int)
      + v_adjustments;
    v_net_after := v_closed.amount_cents
      - least(v_closed.amount_cents, round((v_after::numeric * v_closed.amount_cents) / v_order.total_cents)::int)
      + v_adjustments;
    if least(v_net_after, 0) < least(v_net_before, 0) then
      perform public.record_seller_carry(
        coalesce(v_closed.seller_id, (select o.seller_id from public.orders o where o.id = v_op.order_id)),
        'uncollected', least(v_net_after, 0) - least(v_net_before, 0), v_op.order_id, null,
        'uncollected:' || v_op.order_id::text || ':refund:' || p_operation_id::text);
    end if;
  end if;

  if v_fully then
    -- 20261107130000: only a payout Stripe was never called for is cancelled
    -- outright. One whose call may have happened (a crashed or in-flight
    -- request) could still produce a transfer, and a cancelled row is never
    -- claimed again, so it goes to the worker's reconciliation shelf instead,
    -- due now, with any lease ended (an in-flight owner can then neither
    -- prepare nor overwrite it). The worker records a transfer it finds,
    -- with a 'transfer_after_refund' case for an operator to decide on a
    -- reversal, and cancels the payout itself once its attempt budget has
    -- found none. One whose attempt budget is already spent (the worker's
    -- 8; claim_transfer_intents would never admit it again) stays with the
    -- operator instead: 'failed', its case open, with a note of the refund.
    update public.transfer_intents
    set status = 'cancelled', last_error = 'order fully refunded', updated_at = now()
    where order_id = v_op.order_id
      and status in ('holding', 'ready', 'blocked_unpayable', 'failed', 'processing')
      and not provider_call_may_have_occurred;
    update public.transfer_intents
    set status = 'holding',
        next_attempt_at = now(),
        last_error = 'order fully refunded; reconciling a possible Stripe transfer',
        locked_at = null,
        locked_by = null,
        lease_expires_at = null,
        updated_at = now()
    where order_id = v_op.order_id
      and status in ('holding', 'ready', 'blocked_unpayable', 'failed', 'processing')
      and provider_call_may_have_occurred
      and attempts < 8;
    update public.transfer_intents
    set status = 'failed',
        next_attempt_at = null,
        last_error = left('order fully refunded; ' || coalesce(last_error, ''), 500),
        locked_at = null,
        locked_by = null,
        lease_expires_at = null,
        updated_at = now()
    where order_id = v_op.order_id
      and status in ('holding', 'ready', 'blocked_unpayable', 'failed', 'processing')
      and provider_call_may_have_occurred
      and attempts >= 8
    returning coalesce(dispatch_amount_cents, amount_cents) into v_exhausted;
    if found then
      insert into public.payment_recoveries (order_id, kind, recovery_key, amount_cents, detail)
      values (
        v_op.order_id, 'transfer_unresolved', 'transfer-unresolved:' || v_op.order_id::text, v_exhausted,
        'The order was fully refunded while this seller transfer was unresolved (Stripe may have been called); check Stripe before closing.'
      )
      on conflict (recovery_key) do update
      set detail = left('The order was fully refunded while this seller transfer was unresolved; check Stripe before closing. '
                        || coalesce(public.payment_recoveries.detail, ''), 1000),
          last_seen_at = now(), status = 'open',
          resolved_by = null, resolved_at = null, resolution_note = null;
    end if;
  end if;

  -- 20261005110100
  if v_shortfall > 0 then
    perform public.record_seller_carry(
      v_seller, 'reversal_shortfall', -v_shortfall, v_op.order_id, null,
      'reversal-shortfall:' || p_operation_id::text);
  end if;

  v_next := case when v_rev_due > 0 then 'reversal_pending' else 'completed' end;

  update public.refund_operations
  set status = v_next,
      reversal_due_cents = v_rev_due,
      effects_completed_at = now(),
      reversal_completed_at = case when v_rev_due > 0 then null else now() end,
      updated_at = now()
  where id = p_operation_id;

  return jsonb_build_object('ok', true, 'already', false, 'status', v_next,
    'reversal_due_cents', v_rev_due,
    'transfer_reference', v_order.transfer_reference,
    'fully_refunded', v_fully,
    'refunded_after_cents', v_after,
    'fee_refunded_delta', v_fee_after - v_order.platform_fee_refunded_cents);
end;
$_$;


--
-- Name: settle_seller_cancellation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_seller_cancellation(p_order uuid, p_actor uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.orders;
  payment public.payments;
  listing_ids uuid[];
  bad_listings integer;
  reason text:=coalesce(nullif(left(trim(coalesce(p_reason,'')),500),''),'cancelled by seller');
begin
  if p_order is null or p_actor is null then raise exception 'Order and actor are required'; end if;
  -- One lock order for every path that sells a listing: listing → offer →
  -- order → payment (docs/decisions/agent-foundations.md §4, 20261018100200).
  perform 1 from public.listings where id in (
    select oi.listing_id from public.order_items oi where oi.order_id=p_order and oi.listing_id is not null
  ) order by id for update;
  select * into strict o from public.orders where id=p_order for update;
  if o.seller_id is distinct from p_actor then raise exception 'Seller authorization required' using errcode='42501'; end if;

  select coalesce(array_agg(listing_id order by listing_id),array[]::uuid[])
  into listing_ids from public.order_items where order_id=o.id and listing_id is not null;
  if cardinality(listing_ids)=0 then raise exception 'Order has no inventory items'; end if;
  perform 1 from public.listings where id=any(listing_ids) order by id for update;

  if o.seller_cancellation_relisted_at is not null then
    return jsonb_build_object('ok',true,'complete',true,'replayed',true,'status',o.status);
  end if;
  select * into payment from public.payments where order_id=o.id for update;

  -- Cancel only before checkout begins (negotiation v2, O-5): once the buyer
  -- has frozen the accepted offer's delivery, the order runs its course.
  if o.status='pending' and o.accepted_checkout_shipping is not null then
    return jsonb_build_object('ok',false,'complete',false,'reason','The buyer has started checkout, so this order can no longer be cancelled.');
  end if;

  if o.status='pending' then
    if not found or payment.status not in ('pending','failed') or payment.provider_reference is not null
       or exists(
         select 1 from public.payment_requests request
         where request.request->'orderIds' ? o.id::text
       ) then
      return jsonb_build_object('ok',false,'complete',false,'reason','Payment state requires reconciliation before cancellation.');
    end if;
    update public.orders set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),
      cancel_reason=reason,seller_cancellation_relisted_at=now() where id=o.id;
    update public.listings set status='active',sold_at=null,reserved_until=null
      where id=any(listing_ids) and status='reserved';
  elsif o.status='paid' then
    return jsonb_build_object('ok',true,'complete',false,'needs_refund',true,'status',o.status);
  elsif o.status='refunded' then
    if not found or payment.status<>'refunded' or payment.refunded_cents<payment.amount_cents
       or not exists(
         select 1 from public.refund_operations r where r.order_id=o.id
         and r.requested_by='seller:'||p_actor::text
         and r.status in ('completed','recovery_required')
       ) then
      raise exception 'Seller cancellation refund is not durably complete';
    end if;
    update public.listings set status='active',sold_at=null,reserved_until=null
      where id=any(listing_ids) and status='sold';
    update public.orders set cancel_reason=coalesce(cancel_reason,reason),
      cancelled_at=coalesce(cancelled_at,now()),seller_cancellation_relisted_at=now()
      where id=o.id;
  elsif o.status='cancelled' and found and payment.provider_reference is null then
    update public.listings set status='active',sold_at=null,reserved_until=null
      where id=any(listing_ids) and status='reserved';
    update public.orders set cancel_reason=coalesce(cancel_reason,reason),
      cancelled_at=coalesce(cancelled_at,now()),seller_cancellation_relisted_at=now()
      where id=o.id;
  else
    return jsonb_build_object('ok',false,'complete',false,'status',o.status,'reason','This order cannot be cancelled by the seller.');
  end if;

  select count(*) into bad_listings from public.listings where id=any(listing_ids) and status<>'active';
  if bad_listings<>0 then raise exception 'Cancellation inventory could not be released safely'; end if;
  return jsonb_build_object('ok',true,'complete',true,'replayed',false,'status',(select status from public.orders where id=o.id));
end $$;


--
-- Name: settlement_hold_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_hold_policy() RETURNS TABLE(payout_hold_days integer, payout_hold_mode text, receipt_release_after_days integer, auto_confirm_after_days integer, auto_confirm_notice_days integer, card_verification_on boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.payout_hold_days,
         s.payout_hold_mode,
         s.receipt_release_after_days,
         s.auto_confirm_after_days,
         s.auto_confirm_notice_days,
         s.card_verification_from_cents is not null
  from public.settlement_settings s
  where s.id;
$$;


--
-- Name: FUNCTION settlement_hold_policy(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settlement_hold_policy() IS 'The public part of settlement_settings: hold, release and auto-confirm periods, and whether card verification is on, never its amount (20261107210000).';


--
-- Name: sitemap_post_page(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sitemap_post_page(p_start integer, p_count integer) RETURNS TABLE(id uuid, car_slug text, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id, c.slug, p.updated_at
  from public.activity_posts p
  left join public.cars c on c.id = p.car_id
  where p.published_at is not null
    and (p.car_id is null or (c.is_public and c.slug is not null))
    and p.author_id not in (select public.suspended_profile_ids())
  order by p.id
  offset greatest(coalesce(p_start, 0), 0)
  limit least(greatest(coalesce(p_count, 0), 0), 1000);
$$;


--
-- Name: skip_order_emails_email_off(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.skip_order_emails_email_off() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  update public.order_email_outbox
     set status = 'skipped', skip_reason = 'email_off', lease_id = null, lease_expires_at = null, updated_at = now()
   where status = 'pending';
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: snapshot_order_item_images(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_order_item_images() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.listing_id is not null then
    insert into public.order_item_snapshot_images (order_item_id, url, alt, position)
    select new.id, li.url, li.alt, coalesce(li.position, 0)
      from public.listing_images li
     where li.listing_id = new.listing_id;
  end if;
  return null;
end;
$$;


--
-- Name: snapshot_order_item_purchase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_order_item_purchase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- 0024 behaviour, preserved verbatim: the condition contract that dispute
  -- adjudication already reads.
  if new.listing_id is not null and new.condition_snapshot is null then
    select jsonb_strip_nulls(
             jsonb_build_object(
               'condition', l.condition,
               'grade', l.grade,
               'checklist', l.condition_checklist,
               'compatibility_notes', l.compatibility_notes
             )
           )
      into new.condition_snapshot
      from public.listings l
     where l.id = new.listing_id;
  end if;

  if new.commercial_snapshot is null and new.listing_id is not null then
    new.commercial_snapshot := public.listing_commercial_snapshot(
      new.listing_id, new.price_cents, new.shipping_cents
    );
  end if;

  -- Live order paths always insert with an existing listing, so this branch
  -- is a safety net, not a code path: freeze what the row itself carries
  -- rather than let a NOT NULL violation abort a checkout.
  if new.commercial_snapshot is null then
    new.commercial_snapshot := jsonb_build_object(
      'version', 1,
      'captured_at', now(),
      'degraded', true,
      'listing', jsonb_strip_nulls(jsonb_build_object('id', new.listing_id, 'title', new.title)),
      'commercial', jsonb_build_object(
        'price_cents', new.price_cents,
        'shipping_cents', new.shipping_cents,
        'quantity', new.quantity
      )
    );
  end if;

  new.snapshot_version := coalesce(new.snapshot_version, 1);
  return new;
end;
$$;


--
-- Name: snapshot_order_parties(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_order_parties() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.buyer_label is null then
    select coalesce(display_name, username, 'DRVN member') into new.buyer_label
    from public.profiles where id = new.buyer_id;
  end if;
  if new.seller_label is null then
    select coalesce(display_name, username, 'DRVN member') into new.seller_label
    from public.profiles where id = new.seller_id;
  end if;
  return new;
end;
$$;


--
-- Name: social_target_must_exist(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_target_must_exist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.target_type = 'listing' then
    perform 1 from public.listings l where l.id = new.target_id for key share;
  elsif new.target_type = 'car' then
    perform 1 from public.cars c where c.id = new.target_id for key share;
  elsif new.target_type = 'post' then
    perform 1 from public.activity_posts p where p.id = new.target_id for key share;
  elsif new.target_type = 'profile' then
    perform 1 from public.profiles pr where pr.id = new.target_id for key share;
  else
    -- Each table's own check says which kinds it takes.
    return new;
  end if;
  if not found then
    raise exception 'That is no longer there' using errcode = '23503';
  end if;
  return new;
end;
$$;


--
-- Name: stamp_listing_published_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_listing_published_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.published_at := case when new.status = 'draft' then null else least(new.created_at, now()) end;
    new.published_xact := case when new.status = 'draft' then null else pg_current_xact_id()::text::bigint end;
  elsif old.published_at is not null then
    new.published_at := old.published_at;
    new.published_xact := old.published_xact;
  elsif new.status = 'active' then
    new.published_at := now();
    new.published_xact := pg_current_xact_id()::text::bigint;
  else
    new.published_at := null;
    new.published_xact := null;
  end if;
  return new;
end;
$$;


--
-- Name: start_payout_clock_on_delivery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_payout_clock_on_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'delivered' and old.status is distinct from 'delivered' and new.delivered_at is not null then
    update public.transfer_intents
       set available_at = coalesce(available_at, public.payout_release_at(
             new.id,
             new.delivered_at,
             coalesce(current_setting('drvn.delivery_source', true), '') = 'auto_confirm'
               or coalesce(current_setting('drvn.release_on_delivery', true), '') = 'on'
           )),
           updated_at = now()
     where order_id = new.id
       and status = 'holding'
       and available_at is null;
  end if;
  return new;
end;
$$;


--
-- Name: storage_object_rows(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_object_rows(p_bucket text, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(path text, created_at timestamp with time zone, expected_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- expected_reason: why missing bytes would be on purpose. 'deleted' — the
  -- media cleanup deleted this path for good (a restored row whose bytes it
  -- removed); 'retention' — a chat photo the sweep has deleted by now (the
  -- sweep judges the object's own age). Null: missing bytes are a loss.
  select o.name::text, o.created_at,
         case
           when exists (select 1 from private.media_deletion_claims c
                         where c.bucket = o.bucket_id and c.path = o.name and c.state = 'done') then 'deleted'
           when o.bucket_id = 'agent-chat-photos' and private.agent_chat_photo_swept(o.created_at) then 'retention'
         end
    from storage.objects o
   where o.bucket_id = p_bucket
     and p_bucket in ('avatars', 'car-images', 'activity-images', 'listing-images',
                      'dispute-evidence', 'message-photos', 'agent-chat-photos')
     and (p_after is null or o.name > p_after)
   order by o.name
   limit least(greatest(coalesce(p_limit, 500), 1), 1000);
$$;


--
-- Name: storage_reference_report(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_reference_report(p_sample integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with refs as materialized (
    select * from private.storage_reference_rows()
  ),
  keys as (
    select bucket, path, array_agg(distinct source order by source) as sources,
           bool_and(retention_expired) as retention_expired
      from refs group by bucket, path
  ),
  absent as (
    select k.*,
           -- The media cleanup deleted it (a tombstone) or is deleting it.
           exists (select 1 from private.media_deletion_claims c where c.bucket = k.bucket and c.path = k.path) as deleted
      from keys k
     where not exists (select 1 from storage.objects o where o.bucket_id = k.bucket and o.name = k.path)
  ),
  -- Gone on purpose: retention or a recorded deletion. Not restored.
  expected as (
    select a.*, case when a.deleted then 'deleted' else 'retention' end as reason
      from absent a where a.deleted or a.retention_expired
  ),
  -- Gone and nothing says it should be: what a restore must fix.
  missing as (
    select a.* from absent a where not a.deleted and not a.retention_expired
  ),
  unreferenced as (
    select o.bucket_id as bucket, o.name::text as path
      from storage.objects o
     where o.bucket_id in ('avatars', 'car-images', 'activity-images', 'listing-images',
                           'dispute-evidence', 'message-photos', 'agent-chat-photos')
       and not exists (select 1 from refs r where r.bucket = o.bucket_id and r.path = o.name)
       -- An upload not yet attached to anything is expected; the media
       -- cleanup reclaims it after 48 hours.
       and not exists (select 1 from public.staged_uploads s
                        where s.bucket = o.bucket_id and s.path = o.name and s.consumed_at is null)
  )
  select jsonb_build_object(
    'references', (select count(*) from keys),
    'missingObjects', (select count(*) from missing),
    'missingByBucket', coalesce((select jsonb_object_agg(bucket, n) from (select bucket, count(*) n from missing group by bucket) x), '{}'::jsonb),
    'missingSample', coalesce((select jsonb_agg(jsonb_build_object('bucket', bucket, 'path', path, 'sources', sources) order by bucket, path)
                                 from (select * from missing order by bucket, path limit least(greatest(coalesce(p_sample, 20), 0), 500)) s), '[]'::jsonb),
    'expectedMissing', (select count(*) from expected),
    'expectedMissingByReason', coalesce((select jsonb_object_agg(reason, n) from (select reason, count(*) n from expected group by reason) x), '{}'::jsonb),
    'expectedMissingSample', coalesce((select jsonb_agg(jsonb_build_object('bucket', bucket, 'path', path, 'reason', reason) order by bucket, path)
                                         from (select * from expected order by bucket, path limit least(greatest(coalesce(p_sample, 20), 0), 500)) s), '[]'::jsonb),
    'unreferencedObjects', (select count(*) from unreferenced),
    'unreferencedByBucket', coalesce((select jsonb_object_agg(bucket, n) from (select bucket, count(*) n from unreferenced group by bucket) x), '{}'::jsonb),
    'unreferencedSample', coalesce((select jsonb_agg(jsonb_build_object('bucket', bucket, 'path', path) order by bucket, path)
                                      from (select * from unreferenced order by bucket, path limit least(greatest(coalesce(p_sample, 20), 0), 500)) s), '[]'::jsonb)
  );
$$;


--
-- Name: suggested_builders(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggested_builders(p_viewer uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 6) RETURNS TABLE(id uuid, username text, display_name text, avatar_url text, headline text, car_count bigint, update_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.explore_builder_rankings) then
    -- Not refreshed yet: the old live answer.
    return query
      select p.id, p.username, p.display_name, p.avatar_url, p.headline,
             count(distinct c.id), count(distinct a.id)
      from public.profiles p
      join public.cars c on c.owner_id = p.id and c.is_public and c.cover_image_url is not null
      left join public.activity_posts a on a.car_id = c.id and a.published_at is not null
      where p.username is not null
        and public.profile_is_visible(p.id)
        and (p_viewer is null or p.id <> p_viewer)
        and not exists (select 1 from public.follows f
                         where p_viewer is not null and f.follower_id = p_viewer
                           and f.target_type = 'profile' and f.target_id = p.id)
      group by p.id, p.username, p.display_name, p.avatar_url, p.headline
      order by count(distinct c.id) desc, count(distinct a.id) desc, p.id
      limit greatest(1, least(p_limit, 24));
    return;
  end if;
  -- Names, pictures and suspension are read now; only the counts are stored.
  return query
    select p.id, p.username, p.display_name, p.avatar_url, p.headline, r.car_count, r.update_count
    from public.explore_builder_rankings r
    join public.profiles p on p.id = r.profile_id
    where p.username is not null
      and p.id not in (select public.suspended_profile_ids())
      and (p_viewer is null or p.id <> p_viewer)
      and not exists (select 1 from public.follows f
                       where p_viewer is not null and f.follower_id = p_viewer
                         and f.target_type = 'profile' and f.target_id = p.id)
    order by r.rank
    limit greatest(1, least(p_limit, 24));
end;
$$;


--
-- Name: suspended_profile_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suspended_profile_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id from public.profiles p where p.suspended_at is not null;
$$;


--
-- Name: sync_account_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_account_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.email is null then
    delete from public.account_emails where user_id = new.id;
    return new;
  end if;

  insert into public.account_emails (user_id, email)
  values (new.id, lower(trim(new.email)))
  on conflict (user_id) do update
    set email = excluded.email, updated_at = now();

  return new;
end;
$$;


--
-- Name: sync_activity_post_listings(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_activity_post_listings(p_post_id uuid, p_listing_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_author uuid;
  v_car uuid;
  v_published timestamptz;
  v_before uuid[];
  v_count int;
begin
  select author_id, car_id, published_at
    into v_author, v_car, v_published
    from public.activity_posts where id = p_post_id;
  if v_author is null or v_author is distinct from auth.uid() then
    return;
  end if;

  select coalesce(array_agg(listing_id), '{}') into v_before
    from public.activity_post_listings where post_id = p_post_id;

  delete from public.activity_post_listings where post_id = p_post_id;

  insert into public.activity_post_listings (post_id, listing_id, position)
  select p_post_id, picked.id, picked.ordinality - 1
    from (
      select l.id, tagged.ordinality
        from unnest(coalesce(p_listing_ids, '{}')) with ordinality as tagged(listing_id, ordinality)
        join public.listings l
          on l.id = tagged.listing_id
         and l.seller_id = v_author
         and (l.status = 'active' or l.id = any (v_before))
       order by tagged.ordinality
       limit 3
    ) picked
  on conflict do nothing;

  get diagnostics v_count = row_count;
  if v_count = 0 and v_car is null and v_published is not null then
    raise exception 'A post needs a car, a tagged part, or both.' using errcode = '23514';
  end if;
end;
$$;


--
-- Name: take_down_reported_content(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_down_reported_content(p_actor uuid, p_report uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_report public.reports;
  v_note text;
  v_removed jsonb;
  v_replies int := 0;
  v_closed jsonb;
begin
  perform public.assert_admin_actor(p_actor);
  if p_reason is null or length(btrim(p_reason)) < 1 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  v_note := left('Removed: ' || btrim(p_reason), 4000);

  select * into v_report from public.reports where id = p_report for update;
  if not found then
    raise exception 'Report not found' using errcode = 'P0002';
  end if;
  if v_report.subject_type not in ('post', 'comment') then
    raise exception 'Only a reported post or reply is removed from here' using errcode = '22023';
  end if;

  -- Lock the thing being removed. For a post this also holds off new
  -- replies (their foreign-key check waits on this lock, then fails).
  if v_report.subject_type = 'post' then
    select jsonb_build_object('id', p.id, 'author_id', p.author_id, 'car_id', p.car_id, 'title', p.title,
                              'intro', p.intro, 'body', p.body, 'published_at', p.published_at)
      into v_removed
      from public.activity_posts p where p.id = v_report.subject_id for update;
    if v_removed is null then
      raise exception 'That post is already gone.' using errcode = 'P0002';
    end if;
    select count(*)::int into v_replies from public.activity_comments c where c.post_id = v_report.subject_id;
  else
    select jsonb_build_object('id', c.id, 'author_id', c.author_id, 'post_id', c.post_id, 'body', c.body,
                              'created_at', c.created_at)
      into v_removed
      from public.activity_comments c where c.id = v_report.subject_id for update;
    if v_removed is null then
      raise exception 'That reply is already gone.' using errcode = 'P0002';
    end if;
  end if;

  -- Every open report on the thing and, for a post, on its replies — found
  -- by a join, so no reply count is too large — closed before the delete
  -- takes the replies with it (N140).
  with closed as (
    update public.reports r
       set status = 'actioned', resolved_by = p_actor, resolved_at = now(), resolution_note = v_note
     where r.status = 'open'
       and (
         (r.subject_type = v_report.subject_type and r.subject_id = v_report.subject_id)
         or (v_report.subject_type = 'post' and r.subject_type = 'comment' and r.subject_id in (
               select c.id from public.activity_comments c where c.post_id = v_report.subject_id))
       )
    returning r.id, r.subject_type, r.reporter_id
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'subject_type', subject_type, 'reporter_id', reporter_id)
                            order by id), '[]'::jsonb)
    into v_closed
    from closed;

  if v_report.subject_type = 'post' then
    delete from public.activity_posts where id = v_report.subject_id;
  else
    delete from public.activity_comments where id = v_report.subject_id;
  end if;

  return jsonb_build_object('removed', v_removed, 'replyCount', v_replies, 'closed', v_closed);
end;
$$;


--
-- Name: FUNCTION take_down_reported_content(p_actor uuid, p_report uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_down_reported_content(p_actor uuid, p_report uuid, p_reason text) IS 'N140/OS-W21: removes a reported post or reply and, in the same transaction, closes every open report on it and on a post''s replies. Service role only; the actor must be a full admin.';


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: trending_models(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trending_models(p_days integer DEFAULT 45, p_limit integer DEFAULT 12) RETURNS TABLE(make text, model text, builds bigint, updates bigint, catalog_make_id bigint, catalog_model_id bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if greatest(1, least(p_days, 365)) = 45 and exists (select 1 from public.explore_trending_models) then
    return query
      select t.make, t.model, t.builds, t.updates, t.catalog_make_id, t.catalog_model_id
      from public.explore_trending_models t
      order by t.rank
      limit greatest(1, least(p_limit, 24));
  else
    return query select * from public.trending_models_live(p_days, p_limit);
  end if;
end;
$$;


--
-- Name: trending_models_live(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trending_models_live(p_days integer, p_limit integer) RETURNS TABLE(make text, model text, builds bigint, updates bigint, catalog_make_id bigint, catalog_model_id bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- count(*) is count(a.id) (every joined update has an id) and can be
  -- answered from activity_posts_published_car_idx without reading updates.
  select c.make, c.model, count(distinct c.id), count(*), min(c.catalog_make_id), min(c.catalog_model_id)
  from public.cars c
  join public.activity_posts a
    on a.car_id = c.id
   and a.published_at is not null
   and a.published_at > now() - make_interval(days => greatest(1, least(p_days, 365)))
  where c.is_public
    and c.owner_id not in (select public.suspended_profile_ids())
    and c.make is not null
    and c.model is not null
  group by c.make, c.model
  order by count(*) desc, count(distinct c.id) desc, c.make, c.model
  limit greatest(1, least(p_limit, 24));
$$;


--
-- Name: unlink_mod_listing(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlink_mod_listing(p_car uuid, p_mod_item uuid, p_expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_listing uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in to edit this build.' using errcode = '42501';
  end if;
  if p_car is null or p_mod_item is null then
    raise exception 'Missing build line.' using errcode = '22023';
  end if;
  if p_expected_revision is null then
    raise exception 'Reload the build before saving.' using errcode = '22023';
  end if;

  perform 1 from public.cars c where c.id = p_car and c.owner_id = auth.uid() for update;
  if not found then
    raise exception 'Car not found.' using errcode = '42501';
  end if;
  if public.mod_sheet_revision(p_car) is distinct from p_expected_revision then
    raise exception 'This build changed since you opened it — in another tab or from your agent. Reload to see the latest.'
      using errcode = '40001', hint = 'stale_mod_sheet';
  end if;

  select m.linked_listing_id into v_listing
    from public.mod_items m
   where m.id = p_mod_item and m.car_id = p_car;
  if not found then
    raise exception 'That line isn''t on this build.' using errcode = 'P0002';
  end if;
  if v_listing is not null then
    update public.mod_items m set linked_listing_id = null
     where m.id = p_mod_item and m.car_id = p_car;
  end if;

  return jsonb_build_object(
    'revision', public.mod_sheet_revision(p_car),
    'listing_id', v_listing
  );
end;
$$;


--
-- Name: update_listing_atomic(uuid, timestamp with time zone, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_listing_atomic(p_listing uuid, p_expected_updated_at timestamp with time zone, p_fields jsonb, p_images jsonb, p_fitments jsonb, p_alt_numbers jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.listings%rowtype;
  v_removed text[];
  v_updated_at timestamptz;
  v_floor integer;
begin
  if v_actor is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if jsonb_typeof(p_fields) is distinct from 'object'
     or (p_images is not null and jsonb_typeof(p_images) is distinct from 'array')
     or jsonb_typeof(p_fitments) is distinct from 'array'
     or jsonb_typeof(p_alt_numbers) is distinct from 'array'
     or (p_images is not null and jsonb_array_length(p_images) > 12)
     or jsonb_array_length(p_fitments) > 10
     or jsonb_array_length(p_alt_numbers) > 5
     or p_expected_updated_at is null then
    raise exception 'Invalid listing edit' using errcode = '22023';
  end if;

  select * into v_row from public.listings where id = p_listing for update;
  if not found or v_row.seller_id is distinct from v_actor then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if public.is_suspended(v_actor) then
    raise exception 'account is suspended' using errcode = '42501';
  end if;
  if v_row.status in ('sold', 'reserved', 'removed') then
    raise exception 'A sold, reserved or removed listing can''t be edited' using errcode = '55000';
  end if;
  if v_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'Listing changed after this edit began; reload before saving'
      using errcode = '40001';
  end if;
  if v_row.status = 'active' and p_images is not null and jsonb_array_length(p_images) = 0 then
    raise exception 'A live listing needs at least one photo' using errcode = '23514';
  end if;

  -- The minimum lives in listing_private_terms. It is written on whichever side
  -- of a price change keeps it at or below the price at every step.
  v_floor := nullif(p_fields->>'offer_floor_cents', '')::integer;
  if v_floor is not null and (v_floor <= 0 or v_floor > (p_fields->>'price_cents')::integer) then
    raise exception 'The offer minimum must be above zero and no more than the asking price'
      using errcode = '23514';
  end if;
  if v_floor is null or v_floor <= v_row.price_cents then
    perform public.set_listing_offer_floor(p_listing, v_floor);
  end if;

  update public.listings set
    source_car_id = nullif(p_fields->>'source_car_id', '')::uuid,
    title = p_fields->>'title',
    description = nullif(p_fields->>'description', ''),
    category = p_fields->>'category',
    subcategory = nullif(p_fields->>'subcategory', ''),
    condition = nullif(p_fields->>'condition', ''),
    grade = nullif(p_fields->>'grade', ''),
    condition_checklist = nullif(p_fields->'condition_checklist', 'null'::jsonb),
    price_cents = (p_fields->>'price_cents')::integer,
    shipping_cents = (p_fields->>'shipping_cents')::integer,
    shipping_mode = p_fields->>'shipping_mode',
    weight_oz = nullif(p_fields->>'weight_oz', '')::numeric,
    length_in = nullif(p_fields->>'length_in', '')::numeric,
    width_in = nullif(p_fields->>'width_in', '')::numeric,
    height_in = nullif(p_fields->>'height_in', '')::numeric,
    show_offer_floor = coalesce((p_fields->>'show_offer_floor')::boolean, false),
    allows_collection = (p_fields->>'allows_collection')::boolean,
    location = nullif(p_fields->>'location', ''),
    compatibility_notes = nullif(p_fields->>'compatibility_notes', ''),
    part_number = nullif(p_fields->>'part_number', ''),
    brand = nullif(btrim(p_fields->>'brand'), ''),
    part_miles = nullif(p_fields->>'part_miles', '')::integer,
    part_miles_unit = nullif(p_fields->>'part_miles_unit', '')
  where id = p_listing
  returning updated_at into v_updated_at;
  -- RLS can turn an update into zero rows without an error; zero rows is
  -- not a save.
  if not found then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if v_floor > v_row.price_cents then
    perform public.set_listing_offer_floor(p_listing, v_floor);
  end if;

  if p_images is not null then
    select coalesce(array_agg(li.url), '{}') into v_removed
    from public.listing_images li
    where li.listing_id = p_listing
      and li.url not in (select item->>'url' from jsonb_array_elements(p_images) as image(item));

    delete from public.listing_images where listing_id = p_listing;
    insert into public.listing_images(listing_id, url, alt, position)
    select p_listing, item->>'url', nullif(item->>'alt', ''), ordinality - 1
    from jsonb_array_elements(p_images) with ordinality as image(item, ordinality);
  end if;

  delete from public.listing_fitments where listing_id = p_listing;
  insert into public.listing_fitments(listing_id, make, model, year_start, year_end)
  select p_listing, item->>'make', item->>'model', nullif(item->>'year_start', '')::integer,
         nullif(item->>'year_end', '')::integer
  from jsonb_array_elements(p_fitments) as fitment(item);

  delete from public.listing_part_numbers where listing_id = p_listing;
  insert into public.listing_part_numbers(listing_id, number)
  select p_listing, value from jsonb_array_elements_text(p_alt_numbers) as number(value);

  return jsonb_build_object(
    'listing_id', p_listing,
    'updated_at', v_updated_at,
    'removed_image_urls', to_jsonb(coalesce(v_removed, '{}'))
  );
end;
$$;


--
-- Name: username_available(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.username_available(p_username text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select case
    when p_username is null or p_username !~ '^[a-z0-9_]{3,30}$' then 'invalid'
    when exists (select 1 from public.profiles p where p.username = p_username)
      or exists (select 1 from private.reserved_usernames r where r.username = p_username)
      or exists (select 1 from private.username_tombstones t where t.username = p_username)
      then 'taken'
    else 'available'
  end;
$_$;


--
-- Name: vehicle_generations_rescan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vehicle_generations_rescan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_models bigint[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct model_id) into v_models from changed_new;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct model_id) into v_models from changed_old;
  else
    select array_agg(distinct model_id) into v_models
    from (select model_id from changed_old union select model_id from changed_new) m;
  end if;
  update public.cars c
     set generation_id = c.generation_id
   where c.catalog_model_id = any(v_models)
     and (c.generation_source is distinct from 'owner'
          and c.generation_id is distinct from public.resolve_vehicle_generation(c.catalog_model_id, c.year)
          or c.generation_source = 'owner');
  return null;
end;
$$;


--
-- Name: withdraw_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_listing(p_listing uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_listing public.listings;
  v_offer record;
  v_ended integer := 0;
  v_round uuid;
begin
  if v_uid is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  if p_listing is null then raise exception 'Missing listing' using errcode = '22023'; end if;

  -- Listing first: the lock every offer move and checkout takes first too.
  select * into v_listing from public.listings where id = p_listing for update;
  if not found or v_listing.seller_id is distinct from v_uid then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if v_listing.status in ('reserved', 'sold') then
    raise exception 'This listing is mid-checkout or sold' using errcode = 'LW423';
  end if;
  -- This function is a definer, so guard_listing_status never sees its
  -- write: the moderation rule is restated here. Only a state the seller
  -- owns can be withdrawn; 'removed' (or any state moderation holds) is
  -- moderation's to set and to clear.
  if v_listing.status not in ('draft', 'active', 'paused', 'archived') or v_listing.removed_at is not null then
    raise exception 'This listing was removed by moderation' using errcode = 'LW403';
  end if;

  -- Live offers end whatever the listing's state: one archived before
  -- withdrawal existed, or by a status change, may still have some.
  -- The offer rounds below are this function's; the round trigger stays out.
  perform set_config('drvn.offer_move', 'on', true);
  for v_offer in
    select o.id, o.buyer_id, o.round_count from public.offers o
     where o.listing_id = p_listing and o.status in ('open', 'countered')
     order by o.id
     for update
  loop
    insert into public.offer_rounds (offer_id, round_no, listing_id, buyer_id, actor_role, kind, actor_member_id)
    values (v_offer.id, v_offer.round_count + 1, p_listing, v_offer.buyer_id, 'system', 'withdraw', null)
    returning id into v_round;
    update public.offers
       set status = 'withdrawn', ended_reason = 'listing_withdrawn', responded_at = now(),
           round_count = v_offer.round_count + 1, last_round_id = v_round
     where id = v_offer.id;
    perform public.notify(
      v_offer.buyer_id, 'offer_listing_withdrawn', 'marketplace',
      'The seller withdrew this listing', 'Your offer on "' || v_listing.title || '" has ended. Nothing was charged.',
      '/offers/' || v_offer.id, null
    );
    v_ended := v_ended + 1;
  end loop;
  perform set_config('drvn.offer_move', 'off', true);

  if v_listing.status <> 'archived' then
    update public.listings set status = 'archived' where id = p_listing;
  end if;
  -- A replay only when the work was already done: archived, nothing live.
  return jsonb_build_object(
    'outcome', 'withdrawn',
    'offers_ended', v_ended,
    'replayed', v_listing.status = 'archived' and v_ended = 0
  );
end;
$$;


--
-- Name: FUNCTION withdraw_listing(p_listing uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.withdraw_listing(p_listing uuid) IS 'N77: the seller withdraws a listing atomically (listing-first lock): live offers end with a listing-withdrawal reason, buyers are told, the listing is archived, nothing is deleted. Refuses a removed listing (LW403); ends live offers on an already-archived one.';


--
-- Name: worker_health_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_health_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_jobs jsonb;
  v_families jsonb;
  v_queues jsonb;
  v_scheduler boolean := to_regclass('cron.job') is not null and to_regclass('cron.job_run_details') is not null;
  v_history boolean := coalesce(current_setting('cron.log_run', true), 'on') <> 'off';
begin
  if v_scheduler then
    with inventory as (select * from private.scheduled_job_inventory()),
    history as (select d.start_time from cron.job_run_details d order by d.runid limit 1),
    observed as (
      select i.*, j.jobid, j.active, j.schedule as actual_schedule, j.command as actual_command,
             s.runid as success_run, s.end_time as last_success, f.end_time as last_failure, r.start_time as running_since
      from inventory i
      left join cron.job j on j.jobname = i.job
      left join lateral (
        select d.runid, d.end_time from cron.job_run_details d
        where d.jobid = j.jobid and d.status = 'succeeded' order by d.runid desc limit 1) s on true
      left join lateral (
        select d.end_time from cron.job_run_details d
        where d.jobid = j.jobid and d.status = 'failed' and d.runid > coalesce(s.runid, -1)
        order by d.runid desc limit 1) f on true
      left join lateral (
        select d.start_time from cron.job_run_details d
        where d.jobid = j.jobid and d.status in ('starting', 'running', 'sending', 'connecting')
          and d.runid > coalesce(s.runid, -1)
        order by d.runid limit 1) r on true
    ),
    judged as (
      select o.*,
        case
          when o.jobid is null then 'not_scheduled'
          when not o.active then 'inactive'
          when o.actual_schedule is distinct from o.schedule then 'schedule_changed'
          when private.normalized_sql(o.actual_command) is distinct from private.normalized_sql(o.command) then 'command_changed'
          when not v_history then 'history_disabled'
          when o.last_failure is not null then 'failing'
          when o.running_since < now() - o.budget then 'stuck_running'
          -- Never run: only once the scheduler's own history is older than
          -- the budget, so a fresh project is not red until 03:15.
          when o.success_run is null then
            case when (select h.start_time from history h) < now() - o.budget then 'never_succeeded' end
          when o.last_success < now() - o.budget then 'overdue'
        end as reason
      from observed o
    )
    select jsonb_agg(jsonb_build_object(
      'job', job, 'schedule', schedule, 'families', to_jsonb(families),
      'budget_seconds', extract(epoch from budget),
      'scheduled', jobid is not null, 'active', coalesce(active, false),
      'schedule_matches', jobid is not null and actual_schedule is not distinct from schedule,
      'command_matches', jobid is not null and private.normalized_sql(actual_command) is not distinct from private.normalized_sql(command),
      'last_success', last_success, 'last_failure', last_failure, 'running_since', running_since,
      'stale', reason is not null, 'reason', reason) order by job)
    into v_jobs from judged;
  else
    select jsonb_agg(jsonb_build_object(
      'job', job, 'schedule', schedule, 'families', to_jsonb(families),
      'budget_seconds', extract(epoch from budget),
      'scheduled', false, 'active', false, 'schedule_matches', false, 'command_matches', false,
      'last_success', null, 'last_failure', null, 'running_since', null,
      'stale', true, 'reason', 'scheduler_missing') order by job)
    into v_jobs from private.scheduled_job_inventory();
  end if;

  with family_jobs as (
    select distinct on (f.family) f.family, i.job, i.budget
    from private.scheduled_job_inventory() i cross join lateral unnest(i.families) as f(family)
    order by f.family, i.budget
  ),
  runs as (
    select fj.*, s.started_at as success_started, s.finished_at as last_success,
           fl.finished_at as last_failure, rn.started_at as running_since
    from family_jobs fj
    left join lateral (
      select r.started_at, r.finished_at from public.worker_runs r
      where r.family = fj.family and r.status = 'succeeded' order by r.started_at desc limit 1) s on true
    left join lateral (
      select r.finished_at from public.worker_runs r
      where r.family = fj.family and r.status = 'failed' and r.started_at >= coalesce(s.started_at, '-infinity')
      order by r.started_at desc limit 1) fl on true
    -- A run orphaned before a later success is history, not a stuck worker.
    left join lateral (
      select r.started_at from public.worker_runs r
      where r.family = fj.family and r.status = 'running' and r.started_at > coalesce(s.started_at, '-infinity')
      order by r.started_at limit 1) rn on true
  ),
  judged as (
    select runs.*,
      case
        when last_success is null then 'never_succeeded'
        when last_failure is not null then 'failing'
        when running_since < now() - interval '6 minutes' then 'stuck_running'
        when last_success < now() - budget then 'overdue'
      end as reason
    from runs
  )
  select jsonb_agg(jsonb_build_object(
    'family', family, 'job', job, 'last_success', last_success, 'last_failure', last_failure,
    'running_since', running_since, 'budget_seconds', extract(epoch from budget),
    'stale', reason is not null, 'reason', reason) order by family)
  into v_families from judged;

  with runnable(kind, status, due_at, grace, page_now, attempts) as (
    -- Durable job queues: 'failed' is terminal (attempts exhausted).
    select kind, status, next_attempt_at, interval '30 minutes', status = 'failed', attempts
    from public.remediation_jobs
    where status = 'failed' or (status = 'pending' and next_attempt_at <= now())
    union all
    select kind, 'processing', locked_until, interval '30 minutes', false, attempts
    from public.remediation_jobs where status = 'processing' and locked_until <= now()
    union all
    select 'alerts', status, next_attempt_at, interval '30 minutes', status = 'failed', attempts
    from public.admin_alert_outbox
    where status = 'failed' or (status = 'pending' and next_attempt_at <= now())
    -- Payouts. Overdue only when the payout could go: delivered, released,
    -- and not frozen by a chargeback that hasn't reached a final outcome
    -- (the journal's terminal states, as 20261107130000 defines them).
    union all
    select 'transfers', ti.status,
      case when ti.status = 'holding' then ti.available_at
           else greatest(coalesce(ti.available_at, ti.created_at), coalesce(ti.next_attempt_at, ti.created_at)) end,
      interval '30 minutes', false, ti.attempts
    from public.transfer_intents ti join public.orders o on o.id = ti.order_id
    where ((ti.status = 'holding' and ti.available_at is not null and ti.available_at <= now()
            and o.status in ('delivered', 'completed'))
        -- Admission's own rule (claim_transfer_intents, 8 attempts): an
        -- exhausted row has opened a recovery case, which pages instead.
        or (ti.status in ('ready', 'failed') and ti.attempts < 8
            and greatest(coalesce(ti.available_at, ti.created_at), coalesce(ti.next_attempt_at, ti.created_at)) <= now()))
      and not exists (select 1 from public.stripe_dispute_journal j
                      where j.order_ids @> array[ti.order_id] and j.state not in ('won', 'warning_closed', 'lost'))
    union all
    select 'transfers', 'processing', lease_expires_at, interval '30 minutes', false, attempts
    from public.transfer_intents where status = 'processing' and lease_expires_at <= now()
    -- A seller who can't be paid yet is waiting on the seller, not on us.
    union all
    select 'transfers', 'blocked_unpayable', coalesce(available_at, created_at), null::interval, false, attempts
    from public.transfer_intents where status = 'blocked_unpayable' and coalesce(available_at, created_at) <= now()
    -- Refunds we owe a step on. 'failed' (refused, terminal) and
    -- 'recovery_required' with a recovery case belong to that case.
    union all
    select 'refunds', status, coalesce(next_attempt_at, created_at), interval '30 minutes', false, attempts
    from public.refund_operations
    where status in ('requested', 'provider_succeeded', 'effects_pending', 'reversal_pending')
      and coalesce(next_attempt_at, created_at) <= now()
    -- An outcome nobody has confirmed (a timeout, a failed lookup) is aged
    -- from creation: each reconcile attempt moves next_attempt_at, so the
    -- backoff would otherwise reset the grace for as long as it lasts.
    union all
    select 'refunds', 'provider_unknown', created_at, interval '2 hours', false, attempts
    from public.refund_operations
    where status = 'provider_pending' and coalesce(provider_status, 'unknown') not in ('pending', 'requires_action')
    union all
    select 'refunds', 'recovery_required', updated_at, interval '0 seconds', true, attempts
    from public.refund_operations where status = 'recovery_required' and recovery_id is null
    -- Refunds Stripe is still settling: visible, and late after three days.
    union all
    select 'refunds', 'awaiting_provider', created_at, interval '72 hours', false, attempts
    from public.refund_operations
    where status = 'provider_pending' and provider_status in ('pending', 'requires_action')
    union all
    select 'labelVoids', status,
      case when provider_state = 'submitted' then updated_at + interval '6 hours'
           when status = 'requested' then updated_at + interval '1 minute'
           else updated_at + interval '15 minutes' end,
      interval '30 minutes', false, null::integer
    from public.outbound_label_void_requests
    where status in ('requested', 'provider_pending') and
      case when provider_state = 'submitted' then updated_at + interval '6 hours'
           when status = 'requested' then updated_at + interval '1 minute'
           else updated_at + interval '15 minutes' end <= now()
    -- Chargeback recovery: a loss being booked whose lease ran out.
    union all
    select 'provider_disputes', 'loss_pending', coalesce(lease_expires_at, updated_at), interval '30 minutes', false, null::integer
    from public.stripe_dispute_journal
    where state = 'loss_pending' and coalesce(lease_expires_at, updated_at) <= now()
    -- Provider events not yet applied (a retry, or a first pass that died).
    union all
    select case when id like 'easypost:%' then 'easypost_webhooks' else 'webhooks' end,
      case when failed_attempts > 0 then 'retrying' else 'unprocessed' end,
      received_at, interval '1 hour', false, failed_attempts
    from public.webhook_events where processed_at is null
    union all
    select 'financial_recovery', 'open', created_at, interval '0 seconds', true, null::integer
    from public.payment_recoveries where status = 'open'
  ),
  queues as (
    select kind, status, count(*) as count, min(due_at) as oldest, max(attempts) as attempts_max,
      coalesce(bool_or(page_now) or min(due_at) < now() - min(grace), false) as overdue
    from runnable group by kind, status
  )
  select coalesce(jsonb_agg(to_jsonb(queues) order by kind, status), '[]'::jsonb) into v_queues from queues;

  return jsonb_build_object(
    'families', coalesce(v_families, '[]'::jsonb),
    'jobs', coalesce(v_jobs, '[]'::jsonb),
    'queues', v_queues,
    'config', jsonb_build_object(
      'scheduler', v_scheduler,
      'run_history', v_scheduler and v_history,
      'pg_net', exists (select 1 from pg_extension where extname = 'pg_net'),
      'worker_url', (select c.value from public.job_config c where c.key = 'transfer_worker_url'),
      'worker_secret_sha256', (select encode(sha256(convert_to(c.value, 'UTF8')), 'hex')
                               from public.job_config c where c.key = 'transfer_worker_secret')));
end;
$$;


--
-- Name: write_account_export(uuid, uuid, uuid, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_account_export(p_job uuid, p_lease uuid, p_request uuid, p_part jsonb DEFAULT NULL::jsonb, p_checkpoint jsonb DEFAULT NULL::jsonb, p_manifest jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare job public.remediation_jobs%rowtype; request public.account_export_requests%rowtype;
begin
 select * into job from public.remediation_jobs where id=p_job for update;
 if job.id is null or job.kind<>'account_export' or job.status<>'processing' or job.lease_id is distinct from p_lease or job.locked_until<=now() or job.payload->>'request_id'<>p_request::text then raise exception 'Export lease lost'; end if;
 perform pg_advisory_xact_lock(hashtextextended((job.payload->>'user_id'),0));
 -- N39: a moderation suspension still gets its export; a deletion that has
 -- begun does not.
 perform 1 from public.profiles where id=(job.payload->>'user_id')::uuid for share;
 if not found or private.account_deletion_started((job.payload->>'user_id')::uuid) then raise exception 'Export unavailable'; end if;
 select * into request from public.account_export_requests where id=p_request for update;
 if request.id is null or request.user_id::text<>job.payload->>'user_id' or request.expires_at<=now() or request.status in ('expired','completed')
    or private.account_deletion_started(request.user_id)
 then raise exception 'Export unavailable'; end if;
 if p_part is not null then
  if p_part->>'object_path' not like request.user_id::text||'/'||request.id::text||'/%' then raise exception 'Invalid export object ownership'; end if;
  insert into public.account_export_parts(request_id,section_key,page_number,object_path,row_count,byte_count,sha256,content_type)
  values(request.id,p_part->>'section_key',(p_part->>'page_number')::int,p_part->>'object_path',(p_part->>'row_count')::int,(p_part->>'byte_count')::int,p_part->>'sha256',p_part->>'content_type')
  on conflict(request_id,section_key,page_number) do update set object_path=excluded.object_path,row_count=excluded.row_count,byte_count=excluded.byte_count,sha256=excluded.sha256,content_type=excluded.content_type;
 end if;
 if p_checkpoint is not null then
  update public.account_export_requests set status='processing',last_error=null,current_section=(p_checkpoint->>'section')::int,current_offset=(p_checkpoint->>'offset')::int,current_cursor=p_checkpoint->>'cursor' where id=request.id;
 end if;
 if p_manifest is not null then
  update public.account_export_requests set status='completed',manifest=p_manifest,
   manifest_path=(select object_path from public.account_export_parts where request_id=request.id and section_key='manifest' and page_number=0),completed_at=now(),last_error=null where id=request.id;
 end if;
 if p_error is not null then update public.account_export_requests set status='failed',last_error=left(p_error,500) where id=request.id; end if;
end $$;


--
-- Name: write_activity_post(text, uuid, uuid, text, jsonb, text[], text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_activity_post(p_mode text, p_post_id uuid, p_car_id uuid, p_title text, p_body jsonb DEFAULT NULL::jsonb, p_image_urls text[] DEFAULT NULL::text[], p_intro text DEFAULT NULL::text, p_video_url text DEFAULT NULL::text, p_listing_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(post_id uuid, outcome text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_post_id uuid;
  v_post public.activity_posts%rowtype;
  v_existing_images text[];
  v_has_draft boolean;
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_mode not in ('draft', 'publish', 'update', 'quick') then
    raise exception 'invalid activity write mode' using errcode = '22023';
  end if;
  if p_post_id is null then
    raise exception 'post identity is required' using errcode = '22023';
  end if;
  -- W-5: a quick post may have no car. Everywhere else the car is still
  -- required, because the full editor is reached from a car sheet and a
  -- carless long-form post has nowhere to live.
  -- Editing is the other exception: a carless post that can be published
  -- but never corrected would be a trap.
  if p_car_id is null and p_mode not in ('quick', 'update') then
    raise exception 'post and car identity are required' using errcode = '22023';
  end if;
  -- W-1: a quick post has no title. Everywhere else a title is still
  -- required, because the full editor asks for one and a blank heading on a
  -- long update reads as a bug rather than a choice.
  -- ...and an edit of a post that never had one must not be made to invent it.
  if p_mode = 'quick' or (p_mode = 'update' and exists (
       select 1 from public.activity_posts e
        where e.id = p_post_id and e.author_id = v_user_id
          and nullif(trim(coalesce(e.title, '')), '') is null)) then
    if char_length(trim(coalesce(p_title, ''))) > 160 then
      raise exception 'activity title must contain 1 to 160 characters' using errcode = '22023';
    end if;
  elsif char_length(trim(coalesce(p_title, ''))) not between 1 and 160 then
    raise exception 'activity title must contain 1 to 160 characters' using errcode = '22023';
  end if;
  if p_mode in ('draft', 'publish', 'quick') and jsonb_typeof(p_body) is distinct from 'array' then
    raise exception 'activity body must be an array' using errcode = '22023';
  end if;
  -- W-2: every NEW publish needs a photo. Drafts are exempt (you write
  -- first and photograph later), and `update` is exempt so a post published
  -- before this rule can still be edited without one.
  if p_mode in ('publish', 'quick')
     and coalesce(array_length(p_image_urls, 1), 0) = 0 then
    raise exception 'a published update needs at least one photo' using errcode = '22023';
  end if;
  if coalesce(array_length(p_listing_ids, 1), 0) > 3 then
    raise exception 'an update can tag at most three parts' using errcode = '22023';
  end if;
  -- W-5: with no car there is nothing to own, so the post must be about a
  -- part instead. The deferred constraint trigger enforces this too; saying
  -- it here gives the composer a sentence a person can act on.
  if p_car_id is null and p_mode = 'update' then
    -- The tags already on the post are its subject; the sync refuses to
    -- leave a carless post with none.
    null;
  elsif p_car_id is null then
    if coalesce(array_length(p_listing_ids, 1), 0) = 0 then
      raise exception 'a post with no car has to tag a part' using errcode = '22023';
    end if;
  elsif not exists (
    select 1 from public.cars c
    where c.id = p_car_id and c.owner_id = v_user_id
  ) then
    raise exception 'car not found' using errcode = '42501';
  end if;

  -- One lock per member per car; carless posts share a single queue of
  -- their own, which is what 'none' stands in for.
  perform pg_advisory_xact_lock(
    hashtextextended('activity:' || v_user_id::text || ':' || coalesce(p_car_id::text, 'none'), 0)
  );

  if p_mode = 'update' then
    select p.* into v_post
    from public.activity_posts p
    where p.id = p_post_id
      and p.car_id is not distinct from p_car_id
      and p.author_id = v_user_id
      and p.published_at is not null
    for update;
    if not found then
      raise exception 'published update not found' using errcode = 'P0002';
    end if;

    perform set_config('drvn.activity_write', 'v1', true);
    update public.activity_posts p
    set title = nullif(trim(coalesce(p_title, '')), ''),
        intro = nullif(trim(coalesce(p_intro, '')), ''),
        video_url = nullif(trim(coalesce(p_video_url, '')), ''),
        body = case when p_body is null then p.body else p_body end
    where p.id = v_post.id;

    if p_body is not null then
      delete from public.activity_images ai where ai.post_id = v_post.id;
      insert into public.activity_images (post_id, url, position)
      select v_post.id, image.url, image.position - 1
      from unnest(coalesce(p_image_urls, array[]::text[])) with ordinality as image(url, position);
    end if;
    if p_listing_ids is not null then
      perform public.sync_activity_post_listings(v_post.id, p_listing_ids);
    end if;
    perform set_config('drvn.activity_write', '', true);

    return query select v_post.id, 'updated'::text;
    return;
  end if;

  -- ========================================================
  -- W-1, release-blocking: a quick post NEVER touches a draft.
  --
  -- `publish` finds the car's unpublished draft and converts that row into
  -- the published post — which is right for the full editor, and catastrophic
  -- for a quick post: somebody halfway through writing a long update, who
  -- fires off a photo and a caption, would find the long one gone and its
  -- text replaced. So `quick` returns before the draft lookup below ever
  -- runs. It is still retry-safe, through the same publish_operation_id the
  -- publish path uses.
  -- ========================================================
  if p_mode = 'quick' then
    select p.* into v_post
    from public.activity_posts p
    where p.author_id = v_user_id
      and p.car_id is not distinct from p_car_id
      and p.published_at is not null
      and (p.publish_operation_id = p_post_id or p.id = p_post_id)
    order by (p.publish_operation_id = p_post_id) desc
    limit 1
    for update;
    if found then
      return query select v_post.id, 'replayed'::text;
      return;
    end if;

    perform set_config('drvn.activity_write', 'v1', true);
    insert into public.activity_posts (
      id, car_id, author_id, title, intro, body, published_at, publish_operation_id
    ) values (
      p_post_id, p_car_id, v_user_id,
      nullif(trim(coalesce(p_title, '')), ''),
      null, p_body, clock_timestamp(), p_post_id
    )
    returning id into v_post_id;

    insert into public.activity_images (post_id, url, position)
    select v_post_id, image.url, image.position - 1
    from unnest(coalesce(p_image_urls, array[]::text[])) with ordinality as image(url, position);

    perform public.sync_activity_post_listings(v_post_id, p_listing_ids);
    perform set_config('drvn.activity_write', '', true);

    return query select v_post_id, 'published'::text;
    return;
  end if;

  if p_mode = 'publish' then
    -- A response can disappear after commit. The next attempt uses the same
    -- operation UUID and adopts only the exact row and image projection.
    select p.* into v_post
    from public.activity_posts p
    where p.author_id = v_user_id
      and p.car_id = p_car_id
      and p.published_at is not null
      and (p.publish_operation_id = p_post_id or p.id = p_post_id)
    order by (p.publish_operation_id = p_post_id) desc
    limit 1
    for update;
    if found then
      select coalesce(array_agg(ai.url order by ai.position), array[]::text[])
      into v_existing_images
      from public.activity_images ai
      where ai.post_id = v_post.id;
      if v_post.title is distinct from trim(p_title)
        or v_post.body is distinct from p_body
        or v_existing_images is distinct from coalesce(p_image_urls, array[]::text[])
      then
        raise exception 'publish operation content changed' using errcode = '22023';
      end if;
      return query select v_post.id, 'replayed'::text;
      return;
    end if;
  end if;

  if p_mode = 'draft' then
    -- An autosave request can already be in flight when publish begins. If
    -- publish commits first, that older save must not resurrect a new draft.
    select p.* into v_post
    from public.activity_posts p
    where p.author_id = v_user_id
      and p.car_id = p_car_id
      and p.published_at is not null
      and (p.publish_operation_id = p_post_id or p.id = p_post_id)
    order by (p.publish_operation_id = p_post_id) desc
    limit 1
    for update;
    if found then
      return query select v_post.id, 'publish_won'::text;
      return;
    end if;
  end if;

  select p.* into v_post
  from public.activity_posts p
  where p.car_id = p_car_id
    and p.author_id = v_user_id
    and p.published_at is null
    and p.draft_archived_at is null
  limit 1
  for update;
  v_has_draft := found;

  if p_mode = 'draft' then
    perform set_config('drvn.activity_write', 'v1', true);
    if v_has_draft then
      update public.activity_posts p
      set title = trim(p_title), body = p_body, draft_key = p_car_id
      where p.id = v_post.id
      returning p.id into v_post_id;
    else
      insert into public.activity_posts (
        id, car_id, author_id, title, intro, body, published_at, draft_key
      ) values (
        p_post_id, p_car_id, v_user_id, trim(p_title), null, p_body, null, p_car_id
      )
      returning id into v_post_id;
    end if;
    perform set_config('drvn.activity_write', '', true);
    return query select v_post_id, 'draft_saved'::text;
    return;
  end if;

  perform set_config('drvn.activity_write', 'v1', true);
  if v_has_draft then
    update public.activity_posts p
    set title = trim(p_title),
        intro = null,
        body = p_body,
        published_at = clock_timestamp(),
        draft_key = null,
        publish_operation_id = p_post_id
    where p.id = v_post.id
    returning p.id into v_post_id;
  else
    insert into public.activity_posts (
      id, car_id, author_id, title, intro, body, published_at, publish_operation_id
    ) values (
      p_post_id, p_car_id, v_user_id, trim(p_title), null, p_body, clock_timestamp(), p_post_id
    )
    returning id into v_post_id;
  end if;

  delete from public.activity_images ai where ai.post_id = v_post_id;
  insert into public.activity_images (post_id, url, position)
  select v_post_id, image.url, image.position - 1
  from unnest(coalesce(p_image_urls, array[]::text[])) with ordinality as image(url, position);
  perform public.sync_activity_post_listings(v_post_id, p_listing_ids);
  perform set_config('drvn.activity_write', '', true);

  return query select v_post_id, 'published'::text;
end;
$$;


--
-- Name: listing_creation_requests; Type: TABLE; Schema: private; Owner: -
--

