    payload_hash text NOT NULL,
    result jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT listing_edit_requests_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: media_deletion_claims; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.media_deletion_claims (
    bucket text NOT NULL,
    path text NOT NULL,
    token uuid NOT NULL,
    state text NOT NULL,
    maybe_deleted boolean DEFAULT false NOT NULL,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT media_deletion_claims_state_check CHECK ((state = ANY (ARRAY['active'::text, 'done'::text])))
);


--
-- Name: media_rewrite_claims; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.media_rewrite_claims (
    bucket text NOT NULL,
    path text NOT NULL,
    token uuid NOT NULL,
    object_id uuid NOT NULL,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: order_status_overrides; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.order_status_overrides (
    id bigint NOT NULL,
    order_id uuid NOT NULL,
    old_status text NOT NULL,
    new_status text NOT NULL,
    old_pre_dispute_status text,
    new_pre_dispute_status text,
    reason text NOT NULL,
    current_role_name text NOT NULL,
    session_role_name text NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE order_status_overrides; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.order_status_overrides IS 'Every change of orders.status or pre_dispute_status made under drvn.order_status_override (plan 2 A2). Written by public.guard_order_status in the same transaction.';


--
-- Name: order_status_overrides_id_seq; Type: SEQUENCE; Schema: private; Owner: -
--

ALTER TABLE private.order_status_overrides ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME private.order_status_overrides_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: order_status_transitions; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.order_status_transitions (
    from_status text NOT NULL,
    to_status text NOT NULL,
    owners text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    CONSTRAINT order_status_transitions_from CHECK ((from_status = ANY (ARRAY['pending'::text, 'requires_action'::text, 'payment_failed'::text, 'paid'::text, 'shipped'::text, 'delivered'::text, 'completed'::text, 'cancelled'::text, 'refunded'::text, 'disputed'::text]))),
    CONSTRAINT order_status_transitions_moves CHECK ((from_status <> to_status)),
    CONSTRAINT order_status_transitions_owned CHECK ((btrim(owners) <> ''::text)),
    CONSTRAINT order_status_transitions_to CHECK ((to_status = ANY (ARRAY['pending'::text, 'requires_action'::text, 'payment_failed'::text, 'paid'::text, 'shipped'::text, 'delivered'::text, 'completed'::text, 'cancelled'::text, 'refunded'::text, 'disputed'::text])))
);


--
-- Name: TABLE order_status_transitions; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.order_status_transitions IS 'The legal changes of orders.status (plan 2 A2). Enforced by public.guard_order_status on every update; src/lib/domain/states.ts ORDER_TRANSITIONS must equal it. owners: the functions that make the change.';


--
-- Name: payout_deadline_cancellations; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.payout_deadline_cancellations (
    order_id uuid NOT NULL,
    seller_id uuid NOT NULL,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_attempt_at timestamp with time zone
);


--
-- Name: COLUMN payout_deadline_cancellations.next_attempt_at; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private.payout_deadline_cancellations.next_attempt_at IS 'When the worker may next be handed this claim; each hand-out pushes it back by a doubling backoff (20261108110000).';


--
-- Name: payout_deadline_paused_listings; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.payout_deadline_paused_listings (
    listing_id uuid NOT NULL,
    seller_id uuid NOT NULL,
    paused_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: photo_metadata_scrubs; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.photo_metadata_scrubs (
    bucket text NOT NULL,
    path text NOT NULL,
    outcome text NOT NULL,
    detail text,
    object_updated_at timestamp with time zone,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT photo_metadata_scrubs_detail_check CHECK (((detail IS NULL) OR (length(detail) <= 500))),
    CONSTRAINT photo_metadata_scrubs_outcome_check CHECK ((outcome = ANY (ARRAY['clean'::text, 'scrubbed'::text, 'skipped'::text, 'failed'::text])))
);


--
-- Name: photo_refs_quarantined; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.photo_refs_quarantined (
    id bigint NOT NULL,
    relation text NOT NULL,
    field text NOT NULL,
    value text NOT NULL,
    row_data jsonb NOT NULL,
    action text NOT NULL,
    owner_id uuid NOT NULL,
    folder_owner text,
    quarantined_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '90 days'::interval) NOT NULL,
    CONSTRAINT photo_refs_quarantined_action_check CHECK ((action = ANY (ARRAY['deleted'::text, 'cleared'::text, 'stripped'::text])))
);


--
-- Name: TABLE photo_refs_quarantined; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.photo_refs_quarantined IS 'Photo references that named another member''s object, moved aside by 20261110190000 (N940). The whole row is kept for 90 days, and no longer than either member''s account.';


--
-- Name: photo_refs_quarantined_id_seq; Type: SEQUENCE; Schema: private; Owner: -
--

ALTER TABLE private.photo_refs_quarantined ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME private.photo_refs_quarantined_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: photo_signatures; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.photo_signatures (
    bucket text NOT NULL,
    path text NOT NULL,
    signing_window bigint NOT NULL,
    signed_url text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT photo_signatures_bucket_check CHECK ((bucket = ANY (ARRAY['car-images'::text, 'listing-images'::text, 'activity-images'::text]))),
    CONSTRAINT photo_signatures_path_check CHECK (((length(path) >= 3) AND (length(path) <= 512)))
);


--
-- Name: TABLE photo_signatures; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.photo_signatures IS 'The signed URL each member photo is shown through in one signing window, shared by every app instance (20261110100000). Bearer links: service role only, through photo_signatures_read/offer.';


--
-- Name: reserved_usernames; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.reserved_usernames (
    username text NOT NULL,
    reason text NOT NULL,
    CONSTRAINT reserved_usernames_username_check CHECK ((username ~ '^[a-z0-9_]{3,30}$'::text))
);


--
-- Name: unproven_buyer_orders; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.unproven_buyer_orders (
    order_id uuid NOT NULL,
    buyer_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE unproven_buyer_orders; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.unproven_buyer_orders IS 'Orders whose buyer had not proven their email when the order was placed (guest checkout). The seller cannot review the buyer on these.';


--
-- Name: username_audit; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.username_audit (
    id bigint NOT NULL,
    user_id uuid NOT NULL,
    old_username text NOT NULL,
    problem text NOT NULL,
    action text NOT NULL,
    new_username text,
    audited_at timestamp with time zone DEFAULT now() NOT NULL,
    run_id uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT username_audit_action_check CHECK ((action = ANY (ARRAY['lowercased'::text, 'cleared'::text, 'kept'::text]))),
    CONSTRAINT username_audit_problem_check CHECK ((problem = ANY (ARRAY['format'::text, 'case_collision'::text, 'reserved'::text])))
);


--
-- Name: username_audit_id_seq; Type: SEQUENCE; Schema: private; Owner: -
--

ALTER TABLE private.username_audit ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME private.username_audit_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: username_tombstones; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.username_tombstones (
    username text NOT NULL,
    retired_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text DEFAULT 'account deleted'::text NOT NULL,
    CONSTRAINT username_tombstones_username_check CHECK ((username ~ '^[a-z0-9_]{3,30}$'::text))
);


--
-- Name: account_deletion_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_deletion_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    job_id uuid,
    outcome text NOT NULL,
    blocker_code text,
    affected_data_classes text[] DEFAULT '{}'::text[] NOT NULL,
    next_action text NOT NULL,
    responsible_owner text,
    review_at timestamp with time zone,
    policy_decisions_pending text[] DEFAULT '{}'::text[] NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    email_digest text,
    email_digest_key text,
    scrubbed_at timestamp with time zone,
    retention_starts_at timestamp with time zone,
    retain_until timestamp with time zone,
    hold_order_id uuid,
    CONSTRAINT account_deletion_requests_digest_key_pair CHECK (((email_digest IS NULL) = (email_digest_key IS NULL))),
    CONSTRAINT account_deletion_requests_email_digest_shape CHECK (((email_digest IS NULL) OR (email_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT account_deletion_requests_outcome_check CHECK ((outcome = ANY (ARRAY['temporary_financial_hold'::text, 'cleanup_pending'::text, 'operator_attention'::text, 'completed'::text]))),
    CONSTRAINT account_deletion_requests_retention_clock CHECK (((retain_until IS NULL) OR ((retention_starts_at IS NOT NULL) AND (retain_until = (retention_starts_at + '6 years'::interval)))))
);


--
-- Name: COLUMN account_deletion_requests.email_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_deletion_requests.email_digest IS 'N16: HMAC-SHA256 of the deleted account''s normalised email, keyed by a server secret (email_digest_key names which). The email itself is gone.';


--
-- Name: COLUMN account_deletion_requests.retain_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_deletion_requests.retain_until IS 'N16: transaction keys are kept until this moment: retention_starts_at (the later of the scrub and the member''s last order activity) + 6 years.';


--
-- Name: account_emails; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_emails (
    user_id uuid NOT NULL,
    email text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE account_emails; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.account_emails IS 'Service-role-only email → account index for guest checkout. RLS enabled with no policies: unreadable by anon/authenticated. Never expose through PostgREST.';


--
-- Name: account_export_parts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_export_parts (
    request_id uuid NOT NULL,
    section_key text NOT NULL,
    page_number integer NOT NULL,
    object_path text NOT NULL,
    row_count integer NOT NULL,
    byte_count integer NOT NULL,
    sha256 text NOT NULL,
    content_type text DEFAULT 'application/json'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_export_parts_byte_count_check CHECK ((byte_count >= 0)),
    CONSTRAINT account_export_parts_page_number_check CHECK ((page_number >= 0)),
    CONSTRAINT account_export_parts_row_count_check CHECK ((row_count >= 0)),
    CONSTRAINT account_export_parts_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: account_export_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_export_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    contract_version text NOT NULL,
    cutoff_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    current_section integer DEFAULT 0 NOT NULL,
    current_offset integer DEFAULT 0 NOT NULL,
    current_cursor text,
    manifest jsonb,
    manifest_path text,
    last_error text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    last_purge_attempt_at timestamp with time zone,
