--
-- Name: copyright_notices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.copyright_notices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    claimant_name text NOT NULL,
    claimant_email text NOT NULL,
    claimant_address text NOT NULL,
    claimant_phone text,
    rights_holder text,
    work_description text NOT NULL,
    content_urls text[] NOT NULL,
    good_faith boolean NOT NULL,
    accurate_and_authorised boolean NOT NULL,
    signature text NOT NULL,
    submitted_by uuid,
    status text DEFAULT 'received'::text NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolution_note text,
    takedown jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT copyright_notices_accurate_and_authorised_check CHECK (accurate_and_authorised),
    CONSTRAINT copyright_notices_claimant_address_check CHECK (((length(btrim(claimant_address)) >= 5) AND (length(btrim(claimant_address)) <= 1000))),
    CONSTRAINT copyright_notices_claimant_email_check CHECK (((length(claimant_email) <= 320) AND (claimant_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text))),
    CONSTRAINT copyright_notices_claimant_name_check CHECK (((length(btrim(claimant_name)) >= 2) AND (length(btrim(claimant_name)) <= 200))),
    CONSTRAINT copyright_notices_claimant_phone_check CHECK (((claimant_phone IS NULL) OR (length(claimant_phone) <= 50))),
    CONSTRAINT copyright_notices_content_urls_check CHECK (((cardinality(content_urls) >= 1) AND (cardinality(content_urls) <= 20))),
    CONSTRAINT copyright_notices_good_faith_check CHECK (good_faith),
    CONSTRAINT copyright_notices_rights_holder_check CHECK (((rights_holder IS NULL) OR (length(rights_holder) <= 200))),
    CONSTRAINT copyright_notices_signature_check CHECK (((length(btrim(signature)) >= 2) AND (length(btrim(signature)) <= 200))),
    CONSTRAINT copyright_notices_status_check CHECK ((status = ANY (ARRAY['received'::text, 'actioned'::text, 'rejected'::text]))),
    CONSTRAINT copyright_notices_work_description_check CHECK (((length(btrim(work_description)) >= 10) AND (length(btrim(work_description)) <= 4000)))
);


