--
-- Name: delivery_proofs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.delivery_proofs (
    shipment_id uuid NOT NULL,
    order_id uuid NOT NULL,
    carrier text,
    tracking_code text,
    carrier_delivered_at timestamp with time zone,
    destination_postcode text,
    destination_city text,
    first_scan_at timestamp with time zone,
    signed_by text,
    evidence_at timestamp with time zone,
    order_postcode text,
    order_city text,
    order_country text,
    order_created_at timestamp with time zone NOT NULL,
    deliver_by timestamp with time zone,
    signature_required boolean NOT NULL,
    destination_match text NOT NULL,
    verdict text NOT NULL,
    reasons text[] DEFAULT '{}'::text[] NOT NULL,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT delivery_proofs_destination_match_check CHECK ((destination_match = ANY (ARRAY['postcode'::text, 'city'::text, 'mismatch'::text, 'missing'::text]))),
    CONSTRAINT delivery_proofs_verdict_check CHECK ((verdict = ANY (ARRAY['verified'::text, 'review'::text]))),
    CONSTRAINT delivery_proofs_verified_evidence CHECK (((verdict <> 'verified'::text) OR ((cardinality(reasons) = 0) AND (carrier_delivered_at IS NOT NULL) AND (carrier_delivered_at >= order_created_at) AND (first_scan_at IS NOT NULL) AND (first_scan_at >= order_created_at) AND (deliver_by IS NOT NULL) AND (first_scan_at <= deliver_by) AND ((NOT signature_required) OR (NULLIF(btrim(signed_by), ''::text) IS NOT NULL)) AND (((destination_match = 'postcode'::text) AND (private.postcode_key(destination_postcode, order_country) IS NOT NULL) AND (private.postcode_key(destination_postcode, order_country) = private.postcode_key(order_postcode, order_country))) OR ((destination_match = 'city'::text) AND (private.postcode_key(destination_postcode, order_country) IS NULL) AND (private.city_key(destination_city) IS NOT NULL) AND (private.city_key(destination_city) = private.city_key(order_city)))))))
);


--
-- Name: TABLE delivery_proofs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.delivery_proofs IS 'One verified-proof record per delivered outbound shipment (N95, 20261107210300). verified needs carrier date, matching destination, an in-time scan and a $750+ signature; anything else is review. Decides not-received cases; never gates dispatch or payouts.';


