-- Name: messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid,
    offer_id uuid,
    sender_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    body text NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    order_id uuid,
    conversation_id uuid,
    kind text DEFAULT 'message'::text NOT NULL,
    attachments text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT messages_attachments_check CHECK ((cardinality(attachments) <= 4)),
    CONSTRAINT messages_body_bounds CHECK (((char_length(body) >= 1) AND (char_length(body) <= 4000))),
    CONSTRAINT messages_has_context CHECK (((offer_id IS NOT NULL) OR (order_id IS NOT NULL) OR (listing_id IS NOT NULL))),
    CONSTRAINT messages_has_words CHECK (((char_length(btrim(body)) > 0) OR (cardinality(attachments) > 0))),
    CONSTRAINT messages_kind_check CHECK ((kind = ANY (ARRAY['message'::text, 'event'::text])))
);


--
-- Name: mod_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mod_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    car_id uuid NOT NULL,
    group_label text DEFAULT 'Other'::text NOT NULL,
    category text,
    brand text,
    product text,
    part_number text,
    raw_text text,
    linked_listing_id uuid,
    confidence real,
    "position" integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'installed'::text NOT NULL,
    removed_at timestamp with time zone,
    source_order_item_id uuid,
    product_url text,
    image_url text,
    source_domain text,
    ref_price_cents integer,
    ref_price_currency text,
    origin text DEFAULT 'aftermarket'::text NOT NULL,
    part_number_compact text GENERATED ALWAYS AS (NULLIF(regexp_replace(lower(COALESCE(part_number, ''::text)), '[^a-z0-9]'::text, ''::text, 'g'::text), ''::text)) STORED,
    brand_key text GENERATED ALWAYS AS (NULLIF(regexp_replace(lower(COALESCE(brand, ''::text)), '[^[:alnum:]]'::text, ''::text, 'g'::text), ''::text)) STORED,
    CONSTRAINT mod_items_image_url_https CHECK (((image_url IS NULL) OR (image_url ~ '^https://[^[:space:]]+$'::text))),
    CONSTRAINT mod_items_origin_check CHECK ((origin = ANY (ARRAY['aftermarket'::text, 'stock'::text]))),
    CONSTRAINT mod_items_product_url_http CHECK (((product_url IS NULL) OR (product_url ~* '^https?://[^[:space:]]+$'::text))),
    CONSTRAINT mod_items_ref_price_currency_check CHECK (((ref_price_cents IS NULL) OR ((ref_price_currency IS NOT NULL) AND (ref_price_cents >= 0)))),
    CONSTRAINT mod_items_removed_at_agrees_check CHECK (((status = 'removed'::text) = (removed_at IS NOT NULL))),
    CONSTRAINT mod_items_source_domain_shape CHECK (((source_domain IS NULL) OR (source_domain ~* '^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$'::text))),
    CONSTRAINT mod_items_status_check CHECK ((status = ANY (ARRAY['installed'::text, 'removed'::text])))
);


--
-- Name: COLUMN mod_items.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.status IS 'installed | removed. Removal is a state, not a delete: the row keeps its id so listings, updates and the public build sheet can still name the part.';


--
-- Name: COLUMN mod_items.removed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.removed_at IS 'When the part came off. Set exactly when status = removed.';


--
-- Name: COLUMN mod_items.source_order_item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.source_order_item_id IS 'The order item this mod was built from (C-1). Unique, so adding a purchase to a car twice is a no-op.';


--
-- Name: COLUMN mod_items.product_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.product_url IS 'Where the owner pasted this part from. Displayed as a plain link out; never used as a listing photo source.';


--
-- Name: COLUMN mod_items.image_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.image_url IS 'Thumbnail imported from the product link, in DRVN storage. A shop product photo must never become a listing photo (L-4).';


--
-- Name: COLUMN mod_items.source_domain; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.source_domain IS 'Host the link came from, for the "via <shop>" line.';


--
-- Name: COLUMN mod_items.ref_price_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.ref_price_cents IS 'What the shop listed it at when the link was read. Reference only — not a DRVN price.';


--
-- Name: COLUMN mod_items.ref_price_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.ref_price_currency IS 'ISO-4217 code for ref_price_cents. No currency means no price: the check below refuses the ambiguous half-state.';


--
-- Name: COLUMN mod_items.origin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.origin IS 'aftermarket (fitted by the owner) or stock (a factory part that came off when a mod went on).';


--
-- Name: COLUMN mod_items.part_number_compact; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.part_number_compact IS 'part_number lower-cased with every non a-z0-9 character removed (the listings.part_number_compact expression). Generated.';


--
-- Name: COLUMN mod_items.brand_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_items.brand_key IS 'brand lower-cased with everything but letters and digits removed ("-Bosch", "BOSCH" -> bosch). Generated; the products identity half.';


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    section text NOT NULL,
    title text NOT NULL,
    body text,
    href text,
    actor_id uuid,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
