    CONSTRAINT notifications_section_check CHECK ((section = ANY (ARRAY['engagement'::text, 'marketplace'::text])))
);


--
-- Name: COLUMN notifications.target_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.target_id IS 'What the notification is about (a post, part, car or member), read from href on insert. Not a foreign key; cleared with its subject (20261107180100).';


--
-- Name: offer_round_terms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offer_round_terms (
    round_id uuid NOT NULL,
    effective_floor_cents integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    buyer_ceiling_cents integer,
    CONSTRAINT offer_round_terms_buyer_ceiling_cents_check CHECK (((buyer_ceiling_cents IS NULL) OR (buyer_ceiling_cents > 0))),
    CONSTRAINT offer_round_terms_effective_floor_cents_check CHECK (((effective_floor_cents IS NULL) OR (effective_floor_cents > 0)))
);


--
-- Name: TABLE offer_round_terms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.offer_round_terms IS 'The limits in force when a round was issued (binding snapshot). Private: no client grants.';


--
-- Name: offer_rounds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offer_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    offer_id uuid NOT NULL,
    round_no integer NOT NULL,
    listing_id uuid NOT NULL,
    buyer_id uuid NOT NULL,
    actor_role text NOT NULL,
    kind text NOT NULL,
    amount_cents integer,
    expires_at timestamp with time zone,
    actor_member_id uuid,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_task_id uuid,
    actor_job_id uuid,
    mandate_version integer,
    CONSTRAINT offer_rounds_actor_role_check CHECK ((actor_role = ANY (ARRAY['buyer'::text, 'seller'::text, 'system'::text]))),
    CONSTRAINT offer_rounds_agent_shape CHECK (((actor_task_id IS NULL) OR ((actor_role = ANY (ARRAY['buyer'::text, 'seller'::text])) AND (mandate_version IS NOT NULL)))),
    CONSTRAINT offer_rounds_amount_cents_check CHECK (((amount_cents IS NULL) OR (amount_cents > 0))),
    CONSTRAINT offer_rounds_kind_check CHECK ((kind = ANY (ARRAY['offer'::text, 'counter'::text, 'accept'::text, 'decline'::text, 'withdraw'::text, 'expire'::text, 'below_minimum'::text]))),
    CONSTRAINT offer_rounds_round_no_check CHECK ((round_no > 0))
);


--
-- Name: TABLE offer_rounds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.offer_rounds IS 'One row per negotiation move (20261017150000). Append-only; written by triggers now and by offer_move from A1 step two.';


--
-- Name: COLUMN offer_rounds.actor_task_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.offer_rounds.actor_task_id IS 'Set when the agent made this move (the "via agent" label, A3a). The job and mandate version say under what authority.';


--
-- Name: ops_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ops_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    assigned_to uuid,
    order_id uuid,
    report_id uuid,
    summary text DEFAULT ''::text NOT NULL,
    labels text[] DEFAULT '{}'::text[] NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ops_cases_check CHECK ((((kind = 'dispute'::text) AND (order_id IS NOT NULL) AND (report_id IS NULL)) OR ((kind = 'report'::text) AND (report_id IS NOT NULL) AND (order_id IS NULL)))),
    CONSTRAINT ops_cases_kind_check CHECK ((kind = ANY (ARRAY['dispute'::text, 'report'::text]))),
    CONSTRAINT ops_cases_priority_check CHECK ((priority = ANY (ARRAY['normal'::text, 'high'::text]))),
    CONSTRAINT ops_cases_status_check CHECK ((status = ANY (ARRAY['open'::text, 'claimed'::text, 'resolved'::text])))
);


--
-- Name: order_dispute_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_dispute_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
