    outcome text,
    resolved_to_status text,
    actor_id uuid,
    note text,
    reopened_from uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT order_dispute_history_event_check CHECK ((event = ANY (ARRAY['resolved'::text, 'reopened'::text]))),
    CONSTRAINT order_dispute_history_kind_check CHECK ((kind = ANY (ARRAY['in_app'::text, 'chargeback'::text]))),
    CONSTRAINT order_dispute_history_note_bounds CHECK (((note IS NULL) OR (char_length(note) <= 4000)))
);


--
-- Name: TABLE order_dispute_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.order_dispute_history IS 'Every closed dispute case and every admin reopen (20261107210300). Append-only: a resolved in-app case is final (N91).';


--
-- Name: order_email_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_email_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    notification_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    order_id uuid NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    skip_reason text,
    provider_held_at timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_id uuid,
    lease_expires_at timestamp with time zone,
    last_error text,
    provider_message_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT order_email_outbox_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT order_email_outbox_kind_check CHECK ((kind = ANY (ARRAY['order_sold'::text, 'order_paid'::text, 'order_shipped'::text, 'order_delivered'::text, 'receipt_auto_confirmed'::text, 'order_disputed'::text, 'dispute_resolved'::text, 'admin_action'::text, 'order_refunded'::text, 'payout_setup_reminder'::text, 'order_cancelled'::text, 'order_partially_refunded'::text, 'dispatch_reminder'::text]))),
    CONSTRAINT order_email_outbox_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 200))),
    CONSTRAINT order_email_outbox_skip_reason_check CHECK (((skip_reason IS NULL) OR (skip_reason = ANY (ARRAY['email_off'::text, 'stale'::text, 'account_closed'::text, 'no_address'::text, 'not_a_party'::text, 'muted'::text, 'rejected'::text])))),
    CONSTRAINT order_email_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'skipped'::text, 'failed'::text])))
);


--
-- Name: TABLE order_email_outbox; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.order_email_outbox IS 'Order emails waiting to be sent (20261111090000, #116): user id and order id only; the address is read at send. Service role only.';


