COMMENT ON COLUMN public.order_items.snapshot_version IS 'Shape version of commercial_snapshot. v1 = 0049.';


--
-- Name: orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    buyer_id uuid,
    seller_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    subtotal_cents integer DEFAULT 0 NOT NULL,
    platform_fee_cents integer DEFAULT 0 NOT NULL,
    total_cents integer DEFAULT 0 NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    shipping_cents integer DEFAULT 0 NOT NULL,
    ship_name text,
    ship_line1 text,
    ship_line2 text,
    ship_city text,
    ship_postcode text,
    ship_country text,
    ship_phone text,
    is_collection boolean DEFAULT false NOT NULL,
    carrier text,
    tracking_number text,
    shipped_at timestamp with time zone,
    delivered_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancel_reason text,
    buyer_label text,
    seller_label text,
    dispute_category text,
    dispute_reason text,
    disputed_at timestamp with time zone,
    disputed_by uuid,
    dispute_resolved_at timestamp with time zone,
    pre_dispute_status text,
    refund_offer_cents integer,
    refund_offered_at timestamp with time zone,
    transfer_reference text,
    transferred_at timestamp with time zone,
    refunded_cents integer DEFAULT 0 NOT NULL,
    platform_fee_refunded_cents integer DEFAULT 0 NOT NULL,
    refunded_at timestamp with time zone,
    dispute_escalated_at timestamp with time zone,
    dispute_sla_alerted_at timestamp with time zone,
    dispute_escalated_by uuid,
    dispute_outcome text,
    ship_state text,
    origin_offer_id uuid,
    correlation_id uuid,
    shipping_quote jsonb,
    pickup_ready_at timestamp with time zone,
    analytics_consent_version uuid,
    stripe_dispute_id text,
    accepted_checkout_shipping jsonb,
    seller_cancellation_relisted_at timestamp with time zone,
    dispatch_by timestamp with time zone,
    deliver_by timestamp with time zone,
    available_by timestamp with time zone,
    delivery_estimate_source text,
    dispute_respond_by timestamp with time zone,
    dispute_escalate_until timestamp with time zone,
    refund_offer_expires_at timestamp with time zone,
    CONSTRAINT orders_currency_usd CHECK ((currency = 'USD'::text)),
    CONSTRAINT orders_delivery_estimate_source_check CHECK (((delivery_estimate_source IS NULL) OR (delivery_estimate_source = ANY (ARRAY['quote'::text, 'fallback'::text, 'collection'::text])))),
    CONSTRAINT orders_dispute_category_check CHECK (((dispute_category IS NULL) OR (dispute_category = ANY (ARRAY['item_not_received'::text, 'item_not_as_described'::text, 'damaged_in_transit'::text, 'wrong_item'::text, 'counterfeit'::text, 'does_not_fit'::text, 'other'::text])))),
    CONSTRAINT orders_dispute_outcome_check CHECK (((dispute_outcome IS NULL) OR (dispute_outcome = ANY (ARRAY['refund_accepted'::text, 'closed_by_buyer'::text, 'auto_refunded'::text, 'admin_refunded'::text, 'admin_resolved'::text, 'chargeback_lost'::text])))),
    CONSTRAINT orders_refund_offer_cents_check CHECK (((refund_offer_cents IS NULL) OR ((refund_offer_cents > 0) AND (refund_offer_cents <= total_cents)))),
    CONSTRAINT orders_refunded_cents_check CHECK (((refunded_cents >= 0) AND (refunded_cents <= total_cents) AND (platform_fee_refunded_cents >= 0) AND (platform_fee_refunded_cents <= platform_fee_cents))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'requires_action'::text, 'payment_failed'::text, 'paid'::text, 'shipped'::text, 'delivered'::text, 'completed'::text, 'cancelled'::text, 'refunded'::text, 'disputed'::text])))
);


--
-- Name: COLUMN orders.ship_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.ship_state IS 'State / province / region — optional at the DB level; required client-side in checkout when ship_country is US/CA/AU.';


--
-- Name: COLUMN orders.origin_offer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.origin_offer_id IS 'The accepted offer this order came from. NULL for buy-now and cart orders.';


--
-- Name: COLUMN orders.correlation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.correlation_id IS 'Groups the orders of one checkout and matches the Stripe PaymentIntent metadata correlation_id. Observability only — never a money-path key.';


--
-- Name: COLUMN orders.shipping_quote; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.shipping_quote IS 'DRVN Shipping service frozen at checkout (§15.7): provider, service, quoted amount, parcel. Null for flat/pickup orders.';


--
-- Name: COLUMN orders.pickup_ready_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.pickup_ready_at IS 'Seller marked this collection order ready for handoff (0054). Null for shipped orders.';


--
-- Name: COLUMN orders.dispatch_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.dispatch_by IS 'Frozen when the order became paid (20261107210300): paid + the seller''s handling business days. Shipping orders only.';


--
-- Name: COLUMN orders.deliver_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.deliver_by IS 'Latest delivery date, frozen when paid: dispatch_by + transit business days (quote, else 5 domestic / 15 international). "Item never arrived" opens here.';


--
-- Name: COLUMN orders.available_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.available_by IS 'Collection orders: when the item must be made available, frozen when paid (paid + handling business days).';


--
-- Name: COLUMN orders.dispute_respond_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.dispute_respond_by IS 'Seller response deadline: 3 business days after the report. Escalation opens here.';


--
-- Name: COLUMN orders.dispute_escalate_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.dispute_escalate_until IS 'Last moment either party can escalate: 21 business days after the report.';


--
-- Name: COLUMN orders.refund_offer_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.refund_offer_expires_at IS 'refund_offered_at + 48 hours, always (orders_freeze_deadlines). An expired offer cannot be accepted and does not block escalation.';


