--
-- Name: part_number_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.part_number_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    from_compact text NOT NULL,
    to_compact text NOT NULL,
    kind text NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    from_brand_key text,
    to_brand_key text,
    confidence real,
    source_ref text,
    created_by uuid,
    verified_at timestamp with time zone,
    verified_by uuid,
    CONSTRAINT part_number_links_brand_scope_check CHECK ((((from_brand_key IS NULL) = (to_brand_key IS NULL)) AND ((from_brand_key IS NULL) OR ((char_length(from_brand_key) >= 1) AND (char_length(from_brand_key) <= 64))) AND ((to_brand_key IS NULL) OR ((char_length(to_brand_key) >= 1) AND (char_length(to_brand_key) <= 64))))),
    CONSTRAINT part_number_links_check CHECK ((from_compact <> to_compact)),
    CONSTRAINT part_number_links_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT part_number_links_from_compact_check CHECK (((char_length(from_compact) >= 2) AND (char_length(from_compact) <= 64))),
