    state text,
    postal_code text NOT NULL,
    country text DEFAULT 'US'::text NOT NULL,
    phone text,
    return_name text,
    return_street1 text,
    return_street2 text,
    return_city text,
    return_state text,
    return_postal_code text,
    return_country text,
    default_handling_days integer DEFAULT 2 NOT NULL,
