    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sfp_field_lengths_check CHECK (((char_length(ship_from_name) BETWEEN 1 AND 80) AND ((company IS NULL) OR (char_length(company) <= 80)) AND ((char_length(street1) >= 1) AND (char_length(street1) <= 120)) AND ((street2 IS NULL) OR (char_length(street2) <= 120)) AND ((char_length(city) >= 1) AND (char_length(city) <= 80)) AND ((state IS NULL) OR (char_length(state) <= 40)) AND ((char_length(postal_code) >= 1) AND (char_length(postal_code) <= 20)) AND (char_length(country) = 2) AND ((phone IS NULL) OR (char_length(phone) <= 30)) AND ((return_country IS NULL) OR (char_length(return_country) = 2)))),
    CONSTRAINT sfp_handling_days_check CHECK (((default_handling_days >= 1) AND (default_handling_days <= 10))),
    CONSTRAINT sfp_return_address_complete_check CHECK ((((return_street1 IS NULL) AND (return_city IS NULL) AND (return_postal_code IS NULL) AND (return_country IS NULL)) OR ((return_street1 IS NOT NULL) AND (return_city IS NOT NULL) AND (return_postal_code IS NOT NULL) AND (return_country IS NOT NULL))))
);


