    CONSTRAINT settlement_settings_auto_confirm_notice CHECK (((auto_confirm_notice_days BETWEEN 1 AND 7) AND ((auto_confirm_after_days IS NULL) OR (auto_confirm_after_days > auto_confirm_notice_days)))),
    CONSTRAINT settlement_settings_card_verification_from CHECK (((card_verification_from_cents IS NULL) OR (card_verification_from_cents > 0))),
    CONSTRAINT settlement_settings_hold_days CHECK (((payout_hold_days >= 0) AND (payout_hold_days <= 30))),
    CONSTRAINT settlement_settings_hold_mode CHECK ((payout_hold_mode = ANY (ARRAY['fixed'::text, 'claim_window'::text]))),
    CONSTRAINT settlement_settings_receipt_release_days CHECK (((receipt_release_after_days >= 0) AND (receipt_release_after_days <= 30))),
    CONSTRAINT settlement_settings_single_row CHECK (id),
    CONSTRAINT settlement_settings_tracking_required_from CHECK (((tracking_required_from_cents IS NULL) OR (tracking_required_from_cents > 0)))
);


--
-- Name: COLUMN settlement_settings.payout_hold_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.settlement_settings.payout_hold_days IS 'Days from delivery until a payout is available (0–30). Owner setting; 2 since 20261009100000, and the default and missing-row fallback since 20261107220900.';


--
-- Name: COLUMN settlement_settings.tracking_required_from_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.settlement_settings.tracking_required_from_cents IS 'Unused since 20261107200100 (N110: no amount-based dispatch refusal). Kept so older apps still read it; nothing enforces it.';


