--
-- Name: listings active listings readable; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "active listings readable" ON public.listings FOR SELECT USING ((((status = ANY (ARRAY['active'::text, 'reserved'::text, 'sold'::text])) AND (NOT (seller_id IN ( SELECT public.suspended_profile_ids() AS suspended_profile_ids)))) OR (( SELECT auth.uid() AS uid) = seller_id) OR ( SELECT public.is_admin() AS is_admin)));


--
-- Name: activity_images activity images follow post; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "activity images follow post" ON public.activity_images FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (public.activity_posts p
     LEFT JOIN public.cars c ON ((c.id = p.car_id)))
  WHERE ((p.id = activity_images.post_id) AND (((p.published_at IS NOT NULL) AND ((p.car_id IS NULL) OR c.is_public)) OR (p.author_id = ( SELECT auth.uid() AS uid)))))));


