CREATE POLICY "users file reports" ON public.reports FOR INSERT WITH CHECK ((( SELECT auth.uid() AS uid) = reporter_id));


--
-- Name: follows users manage own follows; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users manage own follows" ON public.follows USING ((( SELECT auth.uid() AS uid) = follower_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = follower_id));


--
-- Name: likes users manage own likes; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users manage own likes" ON public.likes USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: activity_reactions users manage own reactions; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users manage own reactions" ON public.activity_reactions USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK (((( SELECT auth.uid() AS uid) = user_id) AND (char_length(emoji) <= 16) AND public.activity_post_visible(post_id)));


--
-- Name: saves users manage own saves; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users manage own saves" ON public.saves USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: notifications users read own notifications; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users read own notifications" ON public.notifications FOR SELECT USING ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: conversation_unreads users read own unreads; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users read own unreads" ON public.conversation_unreads FOR SELECT USING ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: notifications users update own notifications; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users update own notifications" ON public.notifications FOR UPDATE USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: profiles users update own profile; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users update own profile" ON public.profiles FOR UPDATE USING ((( SELECT auth.uid() AS uid) = id)) WITH CHECK ((( SELECT auth.uid() AS uid) = id));


--
-- Name: listing_vehicle_fit vehicle fit follows the part; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "vehicle fit follows the part" ON public.listing_vehicle_fit FOR SELECT TO authenticated, anon USING ((((via = 'stated'::text) OR car_public OR (car_owner_id = ( SELECT auth.uid() AS uid))) AND ((seller_id = ( SELECT auth.uid() AS uid)) OR (NOT (seller_id IN ( SELECT public.suspended_profile_ids() AS suspended_profile_ids))))));


--
-- Name: vehicle_generations vehicle generations are public; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "vehicle generations are public" ON public.vehicle_generations FOR SELECT TO authenticated, anon USING (true);


