-- ---------------------------------------------------------------------------
-- Storage rules, sign-in triggers, live-update tables
-- ---------------------------------------------------------------------------
create policy "dispute evidence is immutable" on storage.objects
  as restrictive for update to anon, authenticated
  using (bucket_id <> 'dispute-evidence'::text);
create policy "members never delete media or evidence" on storage.objects
  as restrictive for delete to anon, authenticated
  using (bucket_id <> ALL (ARRAY['avatars'::text, 'car-images'::text, 'activity-images'::text, 'listing-images'::text, 'dispute-evidence'::text, 'message-photos'::text]));
create policy "message photos require server normalization insert" on storage.objects
  as restrictive for insert to authenticated
  with check (bucket_id <> 'message-photos'::text);
create policy "message photos require server normalization update" on storage.objects
  as restrictive for update to authenticated
  using (bucket_id <> 'message-photos'::text);
create policy "public photos require server normalization insert" on storage.objects
  as restrictive for insert to authenticated
  with check (bucket_id <> ALL (ARRAY['avatars'::text, 'car-images'::text, 'activity-images'::text, 'listing-images'::text]));
create policy "public photos require server normalization update" on storage.objects
  as restrictive for update to authenticated
  using (bucket_id <> ALL (ARRAY['avatars'::text, 'car-images'::text, 'activity-images'::text, 'listing-images'::text]));
create policy "public read media" on storage.objects
  as permissive for select to public
  using (bucket_id = 'avatars'::text);
create policy "read dispute evidence" on storage.objects
  as permissive for select to public
  using (bucket_id = 'dispute-evidence'::text AND ((storage.foldername(name))[1] = auth.uid()::text OR public.is_admin() OR (EXISTS ( SELECT 1
   FROM public.dispute_evidence de
     JOIN public.orders o ON o.id = de.order_id
  WHERE de.storage_path = objects.name AND (auth.uid() = o.buyer_id OR auth.uid() = o.seller_id)))));
create policy "read message photos" on storage.objects
  as permissive for select to public
  using (bucket_id = 'message-photos'::text AND ((storage.foldername(name))[1] = auth.uid()::text OR (storage.foldername(name))[2] = auth.uid()::text OR public.is_admin()));
create policy "upload evidence into an open dispute" on storage.objects
  as permissive for insert to authenticated
  with check (bucket_id = 'dispute-evidence'::text AND name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[A-Za-z0-9_-]{1,80}\.[A-Za-z0-9]{1,10}$'::text AND split_part(name, '/'::text, 1) = ((( SELECT auth.uid() AS uid))::text) AND (EXISTS ( SELECT 1
   FROM public.orders o
  WHERE o.id =
        CASE
            WHEN split_part(objects.name, '/'::text, 2) ~ '^[0-9a-f-]{36}$'::text THEN split_part(objects.name, '/'::text, 2)::uuid
            ELSE NULL::uuid
        END AND o.status = 'disputed'::text AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id) AND (( SELECT count(*) AS count
           FROM public.dispute_evidence de
          WHERE de.order_id = o.id AND de.uploader_id = (( SELECT auth.uid() AS uid)))) < 8 AND public.my_dispute_evidence_upload_count(o.id) < 16)));
create policy "upload own message photos" on storage.objects
  as permissive for insert to authenticated
  with check (bucket_id = 'message-photos'::text AND (storage.foldername(name))[1] = auth.uid()::text);
create policy "users update own media" on storage.objects
  as permissive for update to public
  using ((bucket_id = ANY (ARRAY['avatars'::text, 'car-images'::text, 'activity-images'::text, 'listing-images'::text])) AND (storage.foldername(name))[1] = auth.uid()::text);
create policy "users upload to own folder" on storage.objects
  as permissive for insert to public
  with check ((bucket_id = ANY (ARRAY['avatars'::text, 'car-images'::text, 'activity-images'::text, 'listing-images'::text])) AND auth.role() = 'authenticated'::text AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TRIGGER users_sync_account_email AFTER INSERT OR UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_account_email();
do $drvn_baseline$
begin
  if exists (select 1 from pg_catalog.pg_publication where pubname = 'supabase_realtime') then
    if not exists (select 1 from pg_catalog.pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'conversation_unreads') then
      alter publication supabase_realtime add table public.conversation_unreads;
    end if;
    if not exists (select 1 from pg_catalog.pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages') then
      alter publication supabase_realtime add table public.messages;
    end if;
  end if;
end $drvn_baseline$;

-- ---------------------------------------------------------------------------
-- Storage buckets and reference rows
-- ---------------------------------------------------------------------------
