ard dispute opened","owners":"open_order_dispute, hold_stripe_dispute, apply_stripe_dispute_event, execute_admin_command","to_status":"disputed","from_status":"shipped"},{"note":"a full refund settled","owners":"settle_refund_operation","to_status":"refunded","from_status":"shipped"},{"note":"a case or a card dispute opened","owners":"open_order_dispute, hold_stripe_dispute, apply_stripe_dispute_event, execute_admin_command","to_status":"disputed","from_status":"delivered"},{"note":"a full refund settled","owners":"settle_refund_operation","to_status":"refunded","from_status":"delivered"},{"note":"a case or a card dispute opened","owners":"open_order_dispute, hold_stripe_dispute, apply_stripe_dispute_event, execute_admin_command","to_status":"disputed","from_status":"completed"},{"note":"a full refund settled","owners":"settle_refund_operation","to_status":"refunded","from_status":"completed"},{"note":"only back to pre_dispute_status","owners":"apply_stripe_dispute_event, order_close_dispute, execute_admin_command, settle_refund_operation","to_status":"paid","from_status":"disputed"},{"note":"only back to pre_dispute_status","owners":"apply_stripe_dispute_event, order_close_dispute, execute_admin_command, settle_refund_operation","to_status":"shipped","from_status":"disputed"},{"note":"only back to pre_dispute_status","owners":"apply_stripe_dispute_event, order_close_dispute, execute_admin_command, settle_refund_operation","to_status":"delivered","from_status":"disputed"},{"note":"only back to pre_dispute_status","owners":"apply_stripe_dispute_event, order_close_dispute, execute_admin_command, settle_refund_operation","to_status":"completed","from_status":"disputed"},{"note":"a full refund settled","owners":"settle_refund_operation","to_status":"refunded","from_status":"disputed"}]$drvn_baseline$::jsonb);
