-- ---------------------------------------------------------------------------
-- Scheduled jobs
-- ---------------------------------------------------------------------------
do $drvn_baseline$
begin
  if exists (select 1 from pg_catalog.pg_extension where extname = 'pg_cron') then
    perform cron.schedule('drvn-agent-worker', '*/5 * * * *', 'select public.invoke_remediation_worker(''agent'');');
    perform cron.schedule('drvn-cron-history-prune', '27 4 * * *', 'select private.prune_cron_history();');
    perform cron.schedule('drvn-deletion-worker', '*/5 * * * *', 'select public.invoke_remediation_worker(''account-deletions'');');
    perform cron.schedule('drvn-delivery-auto-confirm', '23 * * * *', 'select public.auto_confirm_untracked_deliveries();');
    perform cron.schedule('drvn-dispute-sla', '5 8 * * *', ' select public.escalate_stale_disputes(); ');
    perform cron.schedule('drvn-explore-builders', '*/10 * * * *', 'select public.refresh_explore_builders();');
    perform cron.schedule('drvn-explore-trending', '*/2 * * * *', 'select public.refresh_explore_trending();');
    perform cron.schedule('drvn-grow-products', '17 * * * *', 'select public.grow_products()');
    perform cron.schedule('drvn-grow-products-full', '47 4 * * *', 'select public.grow_products(true)');
    perform cron.schedule('drvn-ledger-reconciliation', '50 5 * * *', 'select public.invoke_remediation_worker(''ledger-reconciliation'');');
    perform cron.schedule('drvn-listing-edit-sweep', '45 3 * * *', 'select public.prune_listing_edit_requests();');
    perform cron.schedule('drvn-listing-import-sweep', '37 3 * * *', 'select public.invoke_remediation_worker(''listing-imports'');');
    perform cron.schedule('drvn-marketplace-counts', '30 seconds', 'select public.refresh_marketplace_facet_counts();');
    perform cron.schedule('drvn-media-gc', '17 3 * * *', 'select public.invoke_remediation_worker(''media-gc'');');
    perform cron.schedule('drvn-prune-rate-limits', '15 3 * * *', ' select public.prune_rate_limits(); ');
    perform cron.schedule('drvn-release-reservations', '*/5 * * * *', ' select public.release_expired_reservations(); ');
    perform cron.schedule('drvn-saved-search-digests', '41 * * * *', 'select public.invoke_remediation_worker(''saved-search-digests'');');
    perform cron.schedule('drvn-saved-search-worker', '*/30 * * * *', 'select public.invoke_remediation_worker(''saved-searches'');');
    perform cron.schedule('drvn-search-words', '23 * * * *', 'select public.refresh_search_words();');
    perform cron.schedule('drvn-search-worker', '*/2 * * * *', 'select public.invoke_remediation_worker(''search'');');
    perform cron.schedule('drvn-transfer-worker', '*/10 * * * *', ' select public.mark_due_transfer_intents(); select public.invoke_transfer_worker(); ');
  end if;
end $drvn_baseline$;

-- ---------------------------------------------------------------------------
-- New functions closed by default (A3, 20261111100000), last so they bind only what comes after
-- ---------------------------------------------------------------------------
alter default privileges revoke execute on functions from public;
alter default privileges in schema public revoke execute on functions from anon, authenticated;

commit;
